/*
 * Soil Moisture Monitor — Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - DFRobot Soil Moisture Sensor v2.0 (analog resistive sensor)
 *   - MCP3008 10-bit ADC
 *   - MCP3008 SPI0: CE0=GPIO8, MOSI=GPIO10, MISO=GPIO9, SCLK=GPIO11
 *   - Sensor analog output -> MCP3008 CH0
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o soil_monitor soil_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./soil_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* MCP3008 on SPI0 CE0 */
#define SPI_SPEED      1000000    /* 1 MHz — well within MCP3008 spec */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define SAMPLE_PERIOD  1          /* seconds between readings */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 read (single-ended, 10-bit)                                 */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 SPI protocol (3-byte transfer, Mode 0, MSB-first):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out low bits)
 *
 * Result (10-bit) is assembled from:
 *   ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Timestamped logging                                                  */
/* ------------------------------------------------------------------ */
static void log_reading(int adc_value)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] ADC Value: %d\n", timestamp, adc_value);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Monitoring Started (MCP3008 CH0, SPI0 CE0).\n");
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error — continuing after delay\n");
        } else {
            log_reading(adc_value);
        }
        sleep(SAMPLE_PERIOD);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

