/*
 * Raspberry Pi 4 Model B — MLX91219 Hall-effect current sensor via ADS1115 ADC
 *
 * Wiring:
 *   ADS1115 SDA  -> Pi GPIO2 (I2C bus 1 SDA)
 *   ADS1115 SCL  -> Pi GPIO3 (I2C bus 1 SCL)
 *   ADS1115 ADDR -> GND  (I2C address 0x48)
 *   ADS1115 AIN0 <- MLX91219 analog output
 *
 * The MLX91219 is an analog sensor with a sensitivity of 40 mV/A.
 * The ADS1115 is configured for single-ended AIN0, PGA ±4.096 V,
 * 128 SPS, single-shot mode.  Every 500 ms we read the 16-bit raw
 * value, convert it to volts, then to amperes, and print the result.
 *
 * Build:  gcc -O2 -Wall -o mlx91219_current mlx91219_current.c -lpigpio -lrt
 * Run:    sudo ./mlx91219_current
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADS1115 constants -------------------------------------------------- */
#define I2C_BUS        1
#define ADS1115_ADDR   0x48          /* ADDR tied to GND */

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config-register bit fields */
#define ADS1115_CFG_OS_SINGLE  0x8000  /* Begin a single conversion */
#define ADS1115_CFG_MUX_AIN0   0x4000  /* AIN0 single-ended */
#define ADS1115_CFG_PGA_4_096  0x0200  /* ±4.096 V range */
#define ADS1115_CFG_MODE_SS    0x0100  /* Single-shot mode */
#define ADS1115_CFG_DR_128     0x0080  /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE  0x0003  /* Disable comparator */

/* ---- MLX91219 parameters ------------------------------------------------ */
#define MLX91219_SENSITIVITY  0.040    /* V/A  (40 mV/A) */
#define MLX91219_ZERO_OFFSET  2.5      /* V    (mid-supply, centered) */

/* ADS1115 PGA ±4.096 V range => 1 bit = 125 µV */
#define ADS1115_V_PER_BIT     0.000125

/* ---- Globals for signal-safe cleanup ------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a 16-bit value to an ADS1115 register.
 * pigpio's i2cWriteI2CBlockData sends [reg, msb, lsb] in that order.
 */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)((value >> 8) & 0xFF);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteI2CBlockData(handle, reg, buf + 1, 2) < 0)
        return -1;
    return 0;
}

/*
 * Read a 16-bit value from an ADS1115 register.
 * pigpio's i2cReadI2CBlockData returns [msb, lsb] in that order.
 */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];
    int n = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (n != 2)
        return -1;
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Trigger a single-shot conversion on AIN0 and wait for completion.
 * Returns 0 on success, -1 on error.
 */
static int ads1115_read_ain0(int handle, int16_t *raw_out)
{
    uint16_t config = ADS1115_CFG_OS_SINGLE | ADS1115_CFG_MUX_AIN0 |
                      ADS1115_CFG_PGA_4_096 | ADS1115_CFG_MODE_SS |
                      ADS1115_CFG_DR_128 | ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Error: failed to write ADS1115 config register\n");
        return -1;
    }

    /* 128 SPS => ~7.8 ms per conversion; wait 10 ms to be safe */
    gpioDelay(10000);

    uint16_t cfg_readback;
    if (ads1115_read_reg(handle, ADS1115_REG_CONFIG, &cfg_readback) < 0) {
        fprintf(stderr, "Error: failed to read ADS1115 config register\n");
        return -1;
    }

    /* OS bit (0x8000) is set when conversion is complete */
    if ((cfg_readback & ADS1115_CFG_OS_SINGLE) == 0) {
        fprintf(stderr, "Error: ADS1115 conversion not complete\n");
        return -1;
    }

    uint16_t raw;
    if (ads1115_read_reg(handle, ADS1115_REG_CONVERSION, &raw) < 0) {
        fprintf(stderr, "Error: failed to read ADS1115 conversion register\n");
        return -1;
    }

    *raw_out = (int16_t)raw;
    return 0;
}

int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus to ADS1115 ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d) — sensor absent or bus error\n",
                g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers for graceful shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX91219 current sensor via ADS1115 (I2C 0x48). Press Ctrl+C to exit.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int16_t raw;
        if (ads1115_read_ain0(g_i2c_handle, &raw) < 0) {
            fprintf(stderr, "Warning: ADC read failed, retrying next cycle\n");
            gpioDelay(500000);
            continue;
        }

        /* Convert raw ADC value to voltage */
        double voltage = (double)raw * ADS1115_V_PER_BIT;

        /* Convert voltage to current using MLX91219 sensitivity */
        double current = (voltage - MLX91219_ZERO_OFFSET) / MLX91219_SENSITIVITY;

        printf("Current: %.3f A\n", current);
        fflush(stdout);

        /* 500 ms sampling interval */
        gpioDelay(500000);
    }

    /* ---- Graceful cleanup ---- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

