#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

/* ---------------- Configuration ---------------- */
#define FLAME_SENSOR_GPIO 4
#define BUZZER_GPIO       27
#define I2C_BUS           1
#define ADS1115_ADDR      0x48
#define ADS1115_CONV_REG  0x00
#define ADS1115_CONFIG_REG 0x01

/* Config: single-shot, AIN0 single-ended, gain +/-4.096V, 128 SPS, no comparator */
#define ADS1115_CONFIG_BASE 0x8000  /* OS bit */
#define ADS1115_MUX_AIN0    0x4000  /* AIN0 vs GND */
#define ADS1115_PGA_4_096   0x0200  /* PGA = 4.096V */
#define ADS1115_MODE_SS    0x0100  /* Single-shot mode */
#define ADS1115_DR_128     0x0080  /* 128 SPS */
#define ADS1115_CQUE_NONE  0x0003  /* Disable comparator */
#define ADS1115_CONFIG     (ADS1115_CONFIG_BASE | ADS1115_MUX_AIN0 | \
                            ADS1115_PGA_4_096 | ADS1115_MODE_SS | \
                            ADS1115_DR_128 | ADS1115_CQUE_NONE)

#define TEMP_THRESHOLD_C  60.0f
#define FLAME_DEBOUNCE_US 50000  /* 50 ms */
#define POLL_DELAY_US     100000 /* 100 ms */
#define BUZZER_ON_US      2000000 /* 2 s */
#define ADC_CONV_TIMEOUT_US 10000 /* 10 ms */

/* ---------------- Globals ---------------- */
static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_flame_pending = 0;
static volatile uint32_t     g_flame_tick = 0;
static FILE                 *g_log = NULL;
static int                   g_i2c_handle = -1;

/* ---------------- Prototypes ---------------- */
static int  init_gpio(void);
static int  init_i2c(void);
static int  read_temperature(float *temp_out);
static void flame_isr(int gpio, int level, uint32_t tick, void *userdata);
static void log_event(const char *msg);
static void cleanup(void);
static void signal_handler(int sig);

/* ---------------- Implementation ---------------- */

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", FLAME_SENSOR_GPIO);
        return -1;
    }
    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", FLAME_SENSOR_GPIO);
        return -1;
    }

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", BUZZER_GPIO);
        return -1;
    }
    if (gpioWrite(BUZZER_GPIO, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise buzzer state.\n");
        return -1;
    }

    if (gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0,
                         flame_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR on GPIO%d.\n", FLAME_SENSOR_GPIO);
        return -1;
    }

    return 0;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed on bus %d addr 0x%02X (pigpio code %d).\n",
                I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        return -1;
    }

    /* Write config register (16-bit big-endian) */
    char cfg[3];
    cfg[0] = ADS1115_CONFIG_REG;
    cfg[1] = (ADS1115_CONFIG >> 8) & 0xFF;
    cfg[2] = ADS1115_CONFIG & 0xFF;
    if (i2cWriteDevice(g_i2c_handle, cfg, 3) < 0) {
        fprintf(stderr, "Error: failed to write ADS1115 config register.\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /* Wait for first conversion to complete (OS bit = 1) */
    char reg = ADS1115_CONFIG_REG;
    if (i2cWriteDevice(g_i2c_handle, &reg, 1) < 0) {
        fprintf(stderr, "Error: failed to select config register for status check.\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }
    char status;
    int attempts = 0;
    do {
        if (i2cReadDevice(g_i2c_handle, &status, 1) < 0) {
            fprintf(stderr, "Error: failed to read ADS1115 config status.\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            return -1;
        }
        if (++attempts > 20) {
            fprintf(stderr, "Error: ADS1115 conversion timeout (sensor absent or bus error).\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            return -1;
        }
        gpioDelay(5000); /* 5 ms */
    } while ((status & 0x80) == 0);

    return 0;
}

static int read_temperature(float *temp_out)
{
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: I2C handle invalid in read_temperature.\n");
        return -1;
    }

    /* Trigger a single-shot conversion by writing the config register */
    char cfg[3];
    cfg[0] = ADS1115_CONFIG_REG;
    cfg[1] = (ADS1115_CONFIG >> 8) & 0xFF;
    cfg[2] = ADS1115_CONFIG & 0xFF;
    if (i2cWriteDevice(g_i2c_handle, cfg, 3) < 0) {
        fprintf(stderr, "Error: failed to trigger ADS1115 conversion.\n");
        return -1;
    }

    /* Poll config register until OS bit = 1 (conversion complete) */
    char reg = ADS1115_CONFIG_REG;
    if (i2cWriteDevice(g_i2c_handle, &reg, 1) < 0) {
        fprintf(stderr, "Error: failed to select config register for conversion check.\n");
        return -1;
    }
    char status;
    int attempts = 0;
    do {
        if (i2cReadDevice(g_i2c_handle, &status, 1) < 0) {
            fprintf(stderr, "Error: failed to read ADS1115 conversion status.\n");
            return -1;
        }
        if (++attempts > 20) {
            fprintf(stderr, "Error: ADS1115 conversion timeout.\n");
            return -1;
        }
        gpioDelay(5000); /* 5 ms */
    } while ((status & 0x80) == 0);

    /* Read 2 bytes from conversion register */
    char data[2];
    if (i2cReadDevice(g_i2c_handle, data, 2) < 0) {
        fprintf(stderr, "Error: failed to read ADS1115 conversion result.\n");
        return -1;
    }

    int16_t raw = (data[0] << 8) | data[1];
    /* Gain +/-4.096V => 1 bit = 125 uV */
    float voltage = (raw * 0.000125f);
    if (voltage < 0.0f) voltage = 0.0f;
    if (voltage > 3.3f) voltage = 3.3f;

    /* Map 0V-3.3V to 20C-80C */
    *temp_out = 20.0f + (voltage / 3.3f) * 60.0f;
    return 0;
}

static void flame_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)userdata;
    uint32_t now = tick;
    uint32_t elapsed = now - g_flame_tick;
    if (elapsed < FLAME_DEBOUNCE_US) {
        return; /* within debounce window */
    }
    g_flame_tick = now;
    g_flame_pending = 1;
}

static void log_event(const char *msg)
{
    if (!g_log) {
        fprintf(stderr, "Error: log file not open.\n");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }
    fprintf(g_log, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(g_log);
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, NULL, NULL);
    gpioTerminate();
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }

    g_log = fopen("fire_log.txt", "a");
    if (!g_log) {
        perror("fopen fire_log.txt");
        cleanup();
        return 1;
    }

    log_event("System started.");

    while (g_running) {
        if (g_flame_pending) {
            g_flame_pending = 0;
            log_event("Flame detected!");
        }

        float temp;
        if (read_temperature(&temp) == 0) {
            if (temp > TEMP_THRESHOLD_C) {
                log_event("Temperature above threshold!");
                gpioWrite(BUZZER_GPIO, 1);
                gpioDelay(BUZZER_ON_US);
                gpioWrite(BUZZER_GPIO, 0);
            } else {
                char buf[64];
                snprintf(buf, sizeof(buf), "Temperature: %.2f C", temp);
                log_event(buf);
            }
        } else {
            log_event("Error reading temperature from ADC.");
        }

        gpioDelay(POLL_DELAY_US);
    }

    log_event("System shutting down.");
    cleanup();
    return 0;
}

