        }
        if (++attempts > 20) {
            fprintf(stderr, "Error: ADS1115 conversion timeout.\n");
            return -1;
        }
        gpioDelay(5000); /* 5 ms */
    } while ((status & 0x80) == 0);

    /* Read 2 bytes from conversion register */
    char data[2];
    if (i2cReadDevice(g_i2c_handle, data, 2) < 0) {
        fprintf(stderr, "Error: failed to read ADS1115 conversion result.\n");
        return -1;
    }

    int16_t raw = (data[0] << 8) | data[1];
    /* Gain +/-4.096V => 1 bit = 125 uV */
    float voltage = (raw * 0.000125f);
    if (voltage < 0.0f) voltage = 0.0f;
    if (voltage > 3.3f) voltage = 3.3f;

    /* Map 0V-3.3V to 20C-80C */
    *temp_out = 20.0f + (voltage / 3.3f) * 60.0f;
    return 0;
}

static void flame_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)userdata;
    uint32_t now = tick;
    uint32_t elapsed = now - g_flame_tick;
    if (elapsed < FLAME_DEBOUNCE_US) {
        return; /* within debounce window */
    }
    g_flame_tick = now;
    g_flame_pending = 1;
}

static void log_event(const char *msg)
{
    if (!g_log) {
        fprintf(stderr, "Error: log file not open.\n");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }
    fprintf(g_log, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(g_log);
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, NULL, NULL);
    gpioTerminate();
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }

    g_log = fopen("fire_log.txt", "a");
    if (!g_log) {
        perror("fopen fire_log.txt");
        cleanup();
        return 1;
    }

    log_event("System started.");

    while (g_running) {
        if (g_flame_pending) {
            g_flame_pending = 0;
            log_event("Flame detected!");
        }

        float temp;
        if (read_temperature(&temp) == 0) {
            if (temp > TEMP_THRESHOLD_C) {
                log_event("Temperature above threshold!");
                gpioWrite(BUZZER_GPIO, 1);
                gpioDelay(BUZZER_ON_US);
                gpioWrite(BUZZER_GPIO, 0);
            } else {
                char buf[64];
                snprintf(buf, sizeof(buf), "Temperature: %.2f C", temp);
                log_event(buf);
            }
        } else {
            log_event("Error reading temperature from ADC.");
        }

        gpioDelay(POLL_DELAY_US);
    }

    log_event("System shutting down.");
    cleanup();
    return 0;
}

