#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define DEFAULT_SENSITIVITY 0.1f   /* 100 mV/A -> 0.1 V/A */
#define DEFAULT_THRESHOLD   5.0f
#define DEFAULT_LOG_FILE    "current_log.txt"
#define DEFAULT_SPI_DEVICE  "/dev/spidev0.0"
#define DEFAULT_GPIO_CHIP   "gpiochip4"
#define FAN_GPIO_LINE       18
#define SPI_SPEED_HZ        1000000
#define SPI_BITS_PER_WORD   8
#define SPI_MODE            0
#define ADC_CHANNEL         0
#define ADC_MAX_VALUE       1023
#define ADC_VREF            3.3f
#define SAMPLE_INTERVAL_S   1

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd   = -1;
static struct gpiod_chip  *g_chip  = NULL;
static struct gpiod_line  *g_fan_line = NULL;
static char *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_adc(int fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, dummy byte */
    uint8_t tx[3] = { 0x01, (uint8_t)(0x80 | (channel << 4)), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    if (value < 0 || value > ADC_MAX_VALUE) {
        fprintf(stderr, "ADC value out of range: %d\n", value);
        return -1;
    }
    return value;
}

static float adc_to_current(int adc_value, float sensitivity)
{
    float voltage = (float)adc_value * ADC_VREF / (float)(ADC_MAX_VALUE + 1);
    return voltage / sensitivity;
}

static int gpio_init(void)
{
    g_chip = gpiod_chip_open_by_name(DEFAULT_GPIO_CHIP);
    if (!g_chip) {
        g_chip = gpiod_chip_open_by_number(0);
    }
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        return -1;
    }

    g_fan_line = gpiod_chip_get_line(g_chip, FAN_GPIO_LINE);
    if (!g_fan_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", FAN_GPIO_LINE, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(g_fan_line, "mlx91219-fan", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        g_fan_line = NULL;
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }
    return 0;
}

static void set_fan(int on)
{
    if (g_fan_line) {
        if (gpiod_line_set_value(g_fan_line, on ? 1 : 0) < 0) {
            fprintf(stderr, "gpiod_line_set_value: %s\n", strerror(errno));
        }
    }
}

static void log_data(float current, int fan_state)
{
    if (!g_log_file) return;

    FILE *fp = fopen(g_log_file, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", g_log_file, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s, Current: %.2f A, Fan: %s\n", ts, current, fan_state ? "ON" : "OFF");
    }
    fclose(fp);
}

static void cleanup(void)
{
    set_fan(0);
    if (g_fan_line) {
        gpiod_line_release(g_fan_line);
        g_fan_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_log_file) {
        free(g_log_file);
        g_log_file = NULL;
    }
}

int main(int argc, char *argv[])
{
    int opt;
    float sensitivity = DEFAULT_SENSITIVITY;
    float threshold   = DEFAULT_THRESHOLD;

    while ((opt = getopt(argc, argv, "s:t:l:h")) != -1) {
        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                if (sensitivity <= 0.0f) {
                    fprintf(stderr, "Invalid sensitivity (must be > 0)\n");
                    return 1;
                }
                break;
            case 't':
                threshold = atof(optarg);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Invalid threshold (must be > 0)\n");
                    return 1;
                }
                break;
            case 'l':
                g_log_file = strdup(optarg);
                if (!g_log_file) {
                    fprintf(stderr, "strdup: %s\n", strerror(errno));
                    return 1;
                }
                break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity_V_per_A] [-t threshold_A] [-l log_file]\n", argv[0]);
                return 1;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    g_spi_fd = spi_init(DEFAULT_SPI_DEVICE);
    if (g_spi_fd < 0) {
        return 1;
    }

    if (gpio_init() < 0) {
        close(g_spi_fd);
        return 1;
    }

    printf("MLX91219 Current Monitor (libgpiod)\n");
    printf("  SPI: %s | ADC channel: %d | Fan GPIO: %d | Log: %s\n",
           DEFAULT_SPI_DEVICE, ADC_CHANNEL, FAN_GPIO_LINE, g_log_file ? g_log_file : "stdout");
    printf("  Sensitivity: %.3f V/A | Threshold: %.2f A\n", sensitivity, threshold);

    while (g_running) {
        int adc = read_adc(g_spi_fd, ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read error; retrying in %d s\n", SAMPLE_INTERVAL_S);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        if (adc == 0 || adc == ADC_MAX_VALUE) {
            fprintf(stderr, "Warning: ADC saturated (%d) - sensor absent or wiring fault\n", adc);
        }

        float current = adc_to_current(adc, sensitivity);
        int fan_on = (current > threshold) ? 1 : 0;
        set_fan(fan_on);

        log_data(current, fan_on);

        printf("Current: %.2f A | Fan: %s\n", current, fan_on ? "ON" : "OFF");
        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

