#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x28
#define LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL_SEC 5
#define ADC_MAX_VALUE 65535.0f
#define ADC_MIN_VALUE 0.0f

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c(void);
int read_adc_raw(uint16_t *raw_value);
float convert_to_ppm(uint16_t raw_value);
int log_data(float ppm_value);
void signal_handler(int signal);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

// Initialize I2C communication
int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X on bus %d: %d\n", I2C_ADDR, I2C_BUS, i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw 16-bit ADC value from the sensor
int read_adc_raw(uint16_t *raw_value) {
    char buffer[2];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C device: expected 2 bytes, got %d\n", bytes_read);
        return -1;
    }
    *raw_value = ((uint16_t)buffer[0] << 8) | (uint8_t)buffer[1];
    return 0;
}

