#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * Raspberry Pi 3 Model B+ - KY-026 Flame Sensor + MCP3008 ADC
 *
 * Wiring:
 *   KY-026 D0  -> GPIO4  (digital flame presence)
 *   KY-026 A0  -> MCP3008 CH0 (analog temperature proxy)
 *   MCP3008 VDD -> 3.3V
 *   MCP3008 VREF-> 3.3V
 *   MCP3008 AGND-> GND
 *   MCP3008 DGND-> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *
 * Build: gcc -Wall -Wextra -O2 -o flame_monitor flame_monitor.c -lpigpio -lrt
 * Run:   sudo ./flame_monitor
 */

#define FLAME_GPIO          4
#define SPI_CHANNEL         0          /* SPI0 CE0 */
#define SPI_SPEED           1000000    /* 1 MHz */
#define SPI_FLAGS           0          /* Mode 0, active-low CE */
#define MCP3008_CHANNEL     0          /* CH0 */
#define ADC_MAX_VALUE       1023       /* 10-bit ADC */
#define TEMP_MIN            10.0f
#define TEMP_MAX            40.0f
#define LOG_FILE            "flame_data.csv"
#define SAMPLE_INTERVAL_S   1

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl+C)                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read 10-bit value from MCP3008 single-ended channel               */
/* Returns 0-1023 on success, -1 on SPI transfer failure              */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read sequence (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (SGL/DIFF=1, D2 D1 D0 = channel)
     *   Byte 2: 0x00  (clock out remaining bits)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9 b8] in the lower nibble
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC value to temperature (linear approximation)           */
/* ------------------------------------------------------------------ */
static float adc_to_temperature(int adc_value)
{
    if (adc_value < 0) adc_value = 0;
    if (adc_value > ADC_MAX_VALUE) adc_value = ADC_MAX_VALUE;

    return TEMP_MIN + ((float)adc_value / (float)ADC_MAX_VALUE) *
           (TEMP_MAX - TEMP_MIN);
}

/* ------------------------------------------------------------------ */
/* Append a timestamped CSV row to the log file                        */
/* ------------------------------------------------------------------ */
static int log_data(int flame_detected, float temperature)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error: could not open log file");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("Error: time() failed");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &tm_info) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d,%.2f\n", timestamp, flame_detected,
                temperature) < 0) {
        perror("Error: fprintf() failed");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error: fclose() failed");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                  */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure flame GPIO as input */
    if (gpioSetMode(FLAME_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(FLAME_GPIO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /*
     * Open SPI0 CE0 at 1 MHz, mode 0.
     * pigpio drives CE0 automatically during spiXfer, so manual
     * gpioWrite() is not required.
     */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Warning: sigaction(SIGINT) failed");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Warning: sigaction(SIGTERM) failed");
    }

    printf("Flame sensor monitoring started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        int flame_detected = gpioRead(FLAME_GPIO);
        if (flame_detected < 0) {
            fprintf(stderr, "Error: gpioRead(FLAME_GPIO) failed\n");
        } else {
            int adc_value = read_mcp3008(MCP3008_CHANNEL);
            if (adc_value < 0) {
                fprintf(stderr, "Error: MCP3008 read failed - skipping log\n");
            } else {
                float temperature = adc_to_temperature(adc_value);
                if (log_data(flame_detected, temperature) != 0) {
                    fprintf(stderr, "Error: log_data failed\n");
                }
            }
        }

        /* Sleep in 100 ms increments so SIGINT is responsive */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

