#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x48 // Default I2C address for MICS-4514
#define CO_THRESHOLD 25.0 // PPM
#define LOG_FILE "co_log.txt"
#define ALERT_LOG_FILE "alert_log.txt"
#define READ_INTERVAL_SEC 5

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int handle, int *ox_adc, int *red_adc);
float calculate_co_ppm(int ox_adc, int red_adc);
int log_co_level(float co_ppm);
int log_alert(float co_ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data from MICS-4514
int read_sensor_data(int handle, int *ox_adc, int *red_adc) {
    char buf[4];
    int bytes_read = i2cReadDevice(handle, buf, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }
    *ox_adc = (buf[0] << 8) | buf[1];
    *red_adc = (buf[2] << 8) | buf[3];
    return 0;
}

// Calculate CO level in PPM
float calculate_co_ppm(int ox_adc, int red_adc) {
    // Placeholder calculation (replace with actual calibration curve)
    float co_ppm = (float)(ox_adc - red_adc) * 0.1;
    if (co_ppm < 0) co_ppm = 0;
    return co_ppm;
}

// Log CO level to file
int log_co_level(float co_ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, CO: %.2f PPM\n", s, co_ppm);
    fclose(fp);
    return 0;
}

// Log alert to file
int log_alert(float co_ppm) {
    FILE *fp = fopen(ALERT_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening alert log file: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, ALERT: CO level exceeded threshold (%.2f PPM > %.2f PPM)\n", s, co_ppm, CO_THRESHOLD);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
