#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

#define I2C_BUS 1
#define MIC1_ADDR 0x48
#define MIC2_ADDR 0x49
#define LOG_FILE "audio_log.txt"
#define SAMPLE_INTERVAL_US 100000
#define ERROR_VALUE -999.0f

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_microphone(int handle, float *out_db) {
    char buf[2];
    int bytes = i2cReadDevice(handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "Error reading I2C device (handle %d): %d\n", handle, bytes);
        *out_db = ERROR_VALUE;
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    float voltage = (float)raw * 3.3f / 32768.0f;
    float pressure = voltage / 0.000707945784f;
    *out_db = 20.0f * log10f(pressure / 20e-6f);
    return 0;
}

static void log_data(float db1, float db2, float avg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (db1 == ERROR_VALUE || db2 == ERROR_VALUE) {
        fprintf(fp, "%s, Sensor1: ERROR, Sensor2: ERROR, Average: ERROR\n", ts);
    } else {
        fprintf(fp, "%s, Sensor1: %.2f dB, Sensor2: %.2f dB, Average: %.2f dB\n", ts, db1, db2, avg);
    }
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, MIC1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1 (addr 0x%02X): %d\n", MIC1_ADDR, i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, MIC2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2 (addr 0x%02X): %d\n", MIC2_ADDR, i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        float db1 = ERROR_VALUE, db2 = ERROR_VALUE;
        int rc1 = read_microphone(i2c_handle1, &db1);
        int rc2 = read_microphone(i2c_handle2, &db2);

        if (rc1 != 0 && rc2 != 0) {
            fprintf(stderr, "Both sensor reads failed; skipping sample.\n");
        } else {
            float avg = (db1 + db2) / 2.0f;
            log_data(db1, db2, avg);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    gpioTerminate();
    return 0;
}

