#include <string.h>
#include <math.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_FLAGS 0
#define LED_GPIO 27
#define THRESHOLD 0.7
#define NUM_SAMPLES 100
#define SAMPLE_INTERVAL_US 1000 // 1 ms
#define LED_ON_TIME_MS 500
#define CSV_FILE "audio_events.csv"

// Global variables
int spi_handle = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_adc(int channel);
double calculate_rms(int *samples, int num_samples);
void control_led(int state);
void log_data(double mic1_rms, double mic2_rms);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // MCP3008 SPI command: start bit (1), single-ended mode (1), channel select (3 bits), then don't care
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode + channel
    tx_buf[2] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to calculate RMS value
double calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    return sqrt(sum_of_squares / num_samples);
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

// Function to log data to a CSV file
void log_data(double mic1_rms, double mic2_rms) {
    FILE *fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", CSV_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.4f,%.4f\n", timestamp, mic1_rms, mic2_rms);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    control_led(0); // Ensure LED is off initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int mic1_samples[NUM_SAMPLES];
    int mic2_samples[NUM_SAMPLES];

    // Main loop
    while (program_running) {
        for (int i = 0; i < NUM_SAMPLES; i++) {
            mic1_samples[i] = read_adc(0); // ADC channel 0
            mic2_samples[i] = read_adc(1); // ADC channel 1
            gpioDelay(SAMPLE_INTERVAL_US);
        }

        double mic1_rms = calculate_rms(mic1_samples, NUM_SAMPLES);
        double mic2_rms = calculate_rms(mic2_samples, NUM_SAMPLES);

        log_data(mic1_rms, mic2_rms);

        if (mic1_rms > THRESHOLD || mic2_rms > THRESHOLD) {
            control_led(1); // Turn LED on
            gpioDelay(LED_ON_TIME_MS * 1000); // Wait for 500ms
            control_led(0); // Turn LED off
        }
    }

    // Cleanup
    control_led(0); // Ensure LED is off
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return 0;
}

