#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TCS34725_I2C_ADDR 0x29
#define TCS34725_ENABLE  0x00
#define TCS34725_ATIME   0x01
#define TCS34725_ID      0x12
#define TCS34725_CDATAL  0x14
#define TCS34725_RDATAL  0x16
#define TCS34725_GDATAL  0x18
#define TCS34725_BDATAL  0x1A
#define TCS34725_CONTROL 0x0F

#define TCS34725_ENABLE_PON  0x01
#define TCS34725_ENABLE_AEN  0x02
#define TCS34725_ID_VALUE    0x44

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int tcs34725_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int tcs34725_read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %d\n", reg, rc);
    }
    return rc;
}

static int tcs34725_read_word(int handle, uint8_t reg) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C word read failed (reg=0x%02X): %d\n", reg, rc);
    }
    return rc;
}

static int tcs34725_init(int handle) {
    int id = tcs34725_read_reg(handle, TCS34725_ID);
    if (id < 0) return -1;
    if ((id & 0x0F) != TCS34725_ID_VALUE) {
        fprintf(stderr, "TCS34725 ID mismatch: got 0x%02X, expected 0x%02X\n", id & 0x0F, TCS34725_ID_VALUE);
        return -1;
    }

    if (tcs34725_write_reg(handle, TCS34725_ATIME, 0xFF) < 0) return -1;
    if (tcs34725_write_reg(handle, TCS34725_CONTROL, 0x01) < 0) return -1;
    if (tcs34725_write_reg(handle, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) return -1;
    gpioDelay(3000);
    if (tcs34725_write_reg(handle, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) return -1;
    gpioDelay(3000);
    return 0;
}

static int tcs34725_read_color(int handle, unsigned int *clear, unsigned int *red, unsigned int *green, unsigned int *blue) {
    int c = tcs34725_read_word(handle, TCS34725_CDATAL);
    int r = tcs34725_read_word(handle, TCS34725_RDATAL);
    int g = tcs34725_read_word(handle, TCS34725_GDATAL);
    int b = tcs34725_read_word(handle, TCS34725_BDATAL);
    if (c < 0 || r < 0 || g < 0 || b < 0) return -1;
    *clear = (unsigned int)c;
    *red   = (unsigned int)r;
    *green = (unsigned int)g;
    *blue  = (unsigned int)b;
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, TCS34725_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at addr 0x%02X: %d\n", TCS34725_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (tcs34725_init(i2c_handle) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("color_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open color_log.csv\n");
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Clear,Red,Green,Blue\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int consecutive_failures = 0;

    while (!terminate) {
        unsigned int clear, red, green, blue;
        if (tcs34725_read_color(i2c_handle, &clear, &red, &green, &blue) == 0) {
            consecutive_failures = 0;
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
            fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
            fflush(log_file);
        } else {
            consecutive_failures++;
            if (consecutive_failures >= 3) {
                fprintf(stderr, "Too many consecutive I2C failures (%d), exiting\n", consecutive_failures);
                break;
            }
        }
        gpioDelay(1000000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

