#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS_CHIP_SELECT_LINE "gpiochip0"
#define CS_CHIP_SELECT_OFFSET 8  // GPIO8 (CE0)
#define LOG_FILE "moisture_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008_channel(int spi_fd, struct gpiod_line *cs_line, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    // MCP3008 command: start bit (1), single-ended mode (1), channel bits (3), then don't care
    uint8_t tx[3] = { 0x01, (uint8_t)(0x80 | (channel << 4)), 0x00 };
