#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define MLX90817_ADDR  0x40
#define PRESSURE_REG   0x00
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_US      1000000  /* 1 second */
#define MAX_CONSEC_ERR 10

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_fp    = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, MLX90817_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: pigpio code %d\n",
                I2C_BUS, MLX90817_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_pressure_raw(uint16_t *raw_out)
{
    char buf[2];
    int  rc;

    rc = i2cReadI2CBlockData(g_i2c_handle, PRESSURE_REG, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read failed (reg 0x%02X, rc=%d): %s\n",
                PRESSURE_REG, rc, pigpio_error(rc));
        return -1;
    }

    uint16_t val = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *raw_out = val;
    return 0;
}

static double convert_to_kpa(uint16_t raw)
{
    return ((double)raw / 65535.0) * 500.0;
}

static int log_pressure(double pressure_kPa)
{
    time_t     now;
    struct tm  tm_utc;
    char       ts[32];

    time(&now);
    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    if (fprintf(g_log_fp, "%s,%.2f\n", ts, pressure_kPa) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(g_log_fp);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    if (fprintf(g_log_fp, "timestamp,pressure_kPa\n") < 0) {
        perror("Error writing header");
        cleanup();
        return EXIT_FAILURE;
    }
    fflush(g_log_fp);

    int consec_err = 0;

    while (g_running) {
        uint16_t raw;

        if (read_pressure_raw(&raw) == 0) {
            consec_err = 0;
            double kpa = convert_to_kpa(raw);
            if (log_pressure(kpa) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            consec_err++;
            if (consec_err >= MAX_CONSEC_ERR) {
                fprintf(stderr, "Too many consecutive I2C errors; aborting.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

