#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_GPIO 17

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_MUX_AIN1_GND 0x5000
#define ADS1115_CONFIG_PGA_2_048V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003

#define PRESSURE_THRESHOLD 105.0
#define VREF 5.0
#define VSUPPLY 5.0
#define PRESSURE_MAX 400.0
#define TEMP_MIN 0.0
#define TEMP_MAX 100.0
#define TEMP_V_MIN 1.0
#define TEMP_V_MAX 2.0
#define ADC_MAX 32767.0
#define ADC_MIN 0.0
#define RETRY_COUNT 3
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ads1115_write_config(uint16_t config) {
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    return i2cWriteDevice(i2c_handle, buf, 3);
}

static int ads1115_read_conversion(int16_t *raw) {
    char reg = ADS1115_REG_CONVERSION;
    char buf[2];
    if (i2cWriteDevice(i2c_handle, &reg, 1) < 0) return -1;
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) return -1;
    *raw = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_adc_channel(int channel, int16_t *raw) {
    uint16_t mux;
    switch (channel) {
        case 0: mux = ADS1115_CONFIG_MUX_AIN0_GND; break;
        case 1: mux = ADS1115_CONFIG_MUX_AIN1_GND; break;
        default: return -1;
    }
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | mux | ADS1115_CONFIG_PGA_2_048V |
                      ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS |
                      ADS1115_CONFIG_CQUE_NONE;
    for (int i = 0; i < RETRY_COUNT; i++) {
        if (ads1115_write_config(config) == 0) {
            gpioDelay(10000);
            if (ads1115_read_conversion(raw) == 0) return 0;
        }
        gpioDelay(10000);
    }
    return -1;
}

static float adc_to_voltage(int16_t raw) {
    return ((float)raw / ADC_MAX) * VREF;
}

static float voltage_to_pressure(float v) {
    return (v / VSUPPLY) * PRESSURE_MAX;
}

static float voltage_to_temperature(float v) {
    float frac = (v - TEMP_V_MIN) / (TEMP_V_MAX - TEMP_V_MIN);
    return TEMP_MIN + frac * (TEMP_MAX - TEMP_MIN);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at addr 0x%02X.\n", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90834 Pressure Sensor Interface (via ADS1115)\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int16_t raw_pressure = 0, raw_temp = 0;
        int ok = 0;

        if (read_adc_channel(0, &raw_pressure) == 0) ok = 1;
        if (!ok && read_adc_channel(0, &raw_pressure) == 0) ok = 1;
        if (!ok && read_adc_channel(0, &raw_pressure) == 0) ok = 1;

        if (ok) {
            float v_pressure = adc_to_voltage(raw_pressure);
            float pressure = voltage_to_pressure(v_pressure);

            if (read_adc_channel(1, &raw_temp) != 0) {
                fprintf(stderr, "Warning: Failed to read temperature channel.\n");
                float v_temp = 0.0;
            } else {
                float v_temp = adc_to_voltage(raw_temp);
                float temp = voltage_to_temperature(v_temp);
                printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temp);
            }

            if (pressure > PRESSURE_THRESHOLD) {
                gpioWrite(LED_GPIO, 1);
                printf("WARNING: Pressure exceeds threshold!\n");
            } else {
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Error: Failed to read pressure after %d retries.\n", RETRY_COUNT);
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

