#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_OS_BEGIN 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003

#define VREF 4.096
#define ADC_MAX 32767.0
#define OFFSET_V 0.5
#define SENSITIVITY_V_PER_KPA 0.1
#define MIN_PRESSURE 0.0
#define MAX_PRESSURE 100.0

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_config(uint16_t config) {
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    return i2cWriteDevice(i2c_handle, buf, 3);
}

static int read_conversion(int16_t *raw) {
    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(i2c_handle, &reg, 1) < 0) return -1;
    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) return -1;
    *raw = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_pressure(double *pressure) {
    int16_t raw;
    if (read_conversion(&raw) < 0) return -1;
    double voltage = (raw / ADC_MAX) * VREF;
    double pressure_kpa = (voltage - OFFSET_V) / SENSITIVITY_V_PER_KPA;
    if (pressure_kpa < MIN_PRESSURE || pressure_kpa > MAX_PRESSURE) return -2;
    *pressure = pressure_kpa;
    return 0;
}

static void log_pressure(double pressure) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X\n", ADS1115_ADDR);
        gpioTerminate();
        return 1;
    }

    uint16_t config = ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0_GND |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;
    if (write_config(config) < 0) {
        fprintf(stderr, "Failed to write ADS1115 config\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("pressure_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int ret = read_pressure(&pressure);
        if (ret == 0) {
            log_pressure(pressure);
            printf("Pressure: %.2f kPa\n", pressure);
        } else if (ret == -1) {
            fprintf(stderr, "I2C/ADC read error\n");
        } else {
            fprintf(stderr, "Pressure out of range: %.2f kPa\n", pressure);
        }
        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

