#define THERMISTOR_ADC_CHANNEL 1

#define HUMIDITY_THRESHOLD 80.0
#define SUPPLY_VOLTAGE 5.0
#define VREF 3.3
#define R0 10000.0
#define BETA 3950.0
#define R_SERIES 10000.0

#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com"
#define EMAIL_SUBJECT "Humidity Alert"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_adc(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) return -1;
    return ((rx[1] & 0x03) << 8) | rx[2];
}

float calculate_humidity(int adc_value) {
    float voltage = (adc_value * VREF) / 4095.0;
    return (voltage - 0.824) / 0.0315;
}

float calculate_temperature(int adc_value) {
    float voltage = (adc_value * VREF) / 4095.0;
    float r_thermistor = R_SERIES * (VREF / voltage - 1.0);
    float temp = (1.0 / (1.0 / 298.15 + (1.0 / BETA) * log(r_thermistor / R0))) - 273.15;
    return temp;
}

