#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_BITS_PER_WORD 8
#define SPI_MODE 0

#define GPIO_CHIP "/dev/gpiochip4"
#define CS_LINE_OFFSET 8  // GPIO8 (SPI0 CE0)

#define VREF 3.3
#define ADC_MAX_VALUE 4095.0
#define TMP36_OFFSET 0.5
#define TMP36_SCALE 0.01
#define MIN_VALID_VOLTAGE (TMP36_OFFSET - (40.0 * TMP36_SCALE))
#define MAX_VALID_VOLTAGE (TMP36_OFFSET + (125.0 * TMP36_SCALE))

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

