/*
 * Si1172-A30-GMR Optical Heart Rate Sensor reader for Raspberry Pi Zero W
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   Si1172 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   Si1172 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   Si1172 VDD -> 3.3 V
 *   Si1172 GND -> GND
 *
 * The Si1172 requires a proprietary algorithm to convert raw PPG samples
 * to HR/SpO2.  This program reads the raw 16-bit IR and RED ADC values
 * from the FIFO and logs them as proxy values for HR and SpO2.
 *
 * Build:  gcc -O2 -Wall -o si1172_hr si1172_hr.c -lpigpio -lrt
 * Run:    sudo ./si1172_hr
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Si1172 I2C address (7-bit) ---- */
#define SI1172_I2C_ADDR 0x49

/* ---- Si1172 register addresses ---- */
#define SI1172_REG_COMMAND      0xC0
#define SI1172_REG_IRQ_STATUS   0xC1
#define SI1172_REG_IRQ_ENABLE   0xC2
#define SI1172_REG_FIFO_DATA    0xC3
#define SI1172_REG_FIFO_CONFIG  0xC4

/* ---- Si1172 command codes ---- */
#define SI1172_CMD_RESET        0x01
#define SI1172_CMD_START        0x02
#define SI1172_CMD_STOP         0x03
#define SI1172_CMD_READ_FIFO    0x80

/* ---- Error codes ---- */
#define ERR_OK           0
#define ERR_READ_FAILED  1
#define ERR_SENSOR_ABSENT 2

/* ---- Globals for cleanup ---- */
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;
static volatile sig_atomic_t g_terminate = 0;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a Si1172 register.                           */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int si1172_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a Si1172 register.                           */
/* Returns the byte value (0-255) on success, -1 on failure.            */
/* ------------------------------------------------------------------ */
static int si1172_read_reg(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian value from a Si1172 register.            */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int si1172_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    /* pigpio returns the word as (high_byte << 8) | low_byte */
    *out = (uint16_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the Si1172 sensor.                                        */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int si1172_init(int handle)
{
    /* Issue a software reset via the COMMAND register. */
    if (si1172_write_reg(handle, SI1172_REG_COMMAND, SI1172_CMD_RESET) != 0)
        return -1;

    /* Allow the reset to complete (Si1172 needs ~10 ms after reset). */
    gpioDelay(20000); /* 20 ms */

    /* Verify the sensor is present by reading the IRQ_STATUS register. */
    int status = si1172_read_reg(handle, SI1172_REG_IRQ_STATUS);
    if (status < 0) {
        fprintf(stderr, "[ERROR] Sensor absent or unresponsive after reset.\n");
        return -1;
    }

    /* Clear any latched interrupts. */
    if (si1172_write_reg(handle, SI1172_REG_IRQ_STATUS, 0x00) != 0)
        return -1;

    /* Enable all interrupts (IRQ_ENABLE = 0xFF). */
    if (si1172_write_reg(handle, SI1172_REG_IRQ_ENABLE, 0xFF) != 0)
        return -1;

    /* Configure FIFO: enable data capture, set sample rate. */
    if (si1172_write_reg(handle, SI1172_REG_FIFO_CONFIG, 0x01) != 0)
        return -1;

    /* Start continuous measurements. */
    if (si1172_write_reg(handle, SI1172_REG_COMMAND, SI1172_CMD_START) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample row from the Si1172 FIFO.                            */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int si1172_read_sample(int handle, uint16_t *hr_proxy, uint16_t *spo2_proxy)
{
    /*
     * Issue a read-FIFO command to fetch the latest 16-bit IR and RED
     * ADC values from the FIFO.  The Si1172 returns the IR value in
     * the low byte and the RED value in the high byte of the word.
     */
    int rc = si1172_write_reg(handle, SI1172_REG_COMMAND, SI1172_CMD_READ_FIFO);
    if (rc != 0)
        return -1;

    /* Small delay for the FIFO read to complete. */
    gpioDelay(5000); /* 5 ms */

    /* Read the 16-bit word from FIFO_DATA (0xC3). */
    if (si1172_read_reg16(handle, SI1172_REG_FIFO_DATA, hr_proxy) != 0)
        return -1;

    /*
     * The Si1172 returns the IR value in the low byte and the RED
     * value in the high byte.  We log the raw IR as a proxy for HR
     * and the raw RED as a proxy for SpO2.
     */
    *spo2_proxy = (uint16_t)((*hr_proxy >> 8) & 0xFF);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one data row to the CSV file.                                    */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, time_t timestamp,
                     uint16_t hr_proxy, uint16_t spo2_proxy, int error_flag)
{
    fprintf(fp, "%ld,%u,%u,%d\n",
            (long)timestamp, hr_proxy, spo2_proxy, error_flag);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup resources.                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at the Si1172 address ---- */
    g_i2c_handle = i2cOpen(1, SI1172_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                SI1172_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialize the sensor ---- */
    if (si1172_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Si1172 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open the log file ---- */
    g_log_file = fopen("biometric_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open biometric_log.csv for appending.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if the file is empty. */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,hr_proxy,spo2_proxy,error_flag\n");
        fflush(g_log_file);
    }

    /* ---- Install signal handler for graceful shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed; continuing without handler.\n");
    }

    /* ---- Main sampling loop ---- */
    while (!g_terminate) {
        time_t now = time(NULL);
        uint16_t hr_proxy = 0, spo2_proxy = 0;
        int error_flag = ERR_OK;

        if (si1172_read_sample(g_i2c_handle, &hr_proxy, &spo2_proxy) != 0) {
            error_flag = ERR_READ_FAILED;
        }

        log_data(g_log_file, now, hr_proxy, spo2_proxy, error_flag);

        /* Sleep 1 second between samples. */
        gpioDelay(1000000); /* 1 second */
    }

    /* ---- Graceful shutdown ---- */
    fprintf(stderr, "\n[INFO] Shutting down gracefully...\n");

    /* Stop measurements before closing. */
    if (g_i2c_handle >= 0) {
        si1172_write_reg(g_i2c_handle, SI1172_REG_COMMAND, SI1172_CMD_STOP);
    }

    cleanup();
    return EXIT_SUCCESS;
}

