#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define ICP10125_ADDR 0x67
#define MEASURE_CMD_HIGH_PRECISION 0x6845
#define CSV_FILE "environmental_data.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *csv_fp = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_icp10125(int fd, float *temperature, float *pressure) {
    uint8_t data[6];
    int16_t raw_pressure, raw_temperature;

    if (i2c_write_cmd(fd, MEASURE_CMD_HIGH_PRECISION) < 0)
        return -1;

    /* Wait for conversion to complete (datasheet: typ 10ms, max 20ms) */
    usleep(20000);

    if (i2c_read_data(fd, data, 6) < 0)
        return -1;

    /* Verify CRC for pressure (bytes 0-1, CRC at byte 2) */
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC error on pressure data\n");
        return -1;
    }
    /* Verify CRC for temperature (bytes 3-4, CRC at byte 5) */
    if (crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC error on temperature data\n");
        return -1;
    }

    raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    raw_temperature = (int16_t)((data[3] << 8) | data[4]);

    /* Apply official ICP-10125 calibration formulas */
    *pressure = 45000.0f + (100.0f * (float)raw_pressure);
    *temperature = 25.0f + (0.01f * (float)raw_temperature);

    return 0;
}

static void log_data(FILE *fp, float temperature, float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, pressure);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                ICP10125_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    csv_fp = fopen(CSV_FILE, "a");
    if (!csv_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", CSV_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float temperature, pressure;
        if (read_icp10125(i2c_fd, &temperature, &pressure) == 0) {
            printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
            log_data(csv_fp, temperature, pressure);
        } else {
            fprintf(stderr, "Sensor read failed, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
            log_data(csv_fp, -999.0f, -999.0f);
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    if (csv_fp) fclose(csv_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

