#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0

#define ADC_CHANNEL_1 0
#define ADC_CHANNEL_2 1

#define SAMPLE_RATE 1000
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE)

#define DEFAULT_GAIN 1.0

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

int read_adc(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx_buf[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx_buf, (char *)rx_buf, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    return ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
}

int main(int argc, char *argv[]) {
    double gain = DEFAULT_GAIN;

    if (argc > 1) {
        gain = atof(argv[1]);
        if (gain <= 0.0) {
            fprintf(stderr, "Error: Gain must be a positive number.\n");
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    printf("Audio Sampling and Noise Cancellation (Gain: %.2f)\n", gain);
    printf("Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc1 = read_adc(spi_handle, ADC_CHANNEL_1);
        int adc2 = read_adc(spi_handle, ADC_CHANNEL_2);

        if (adc1 < 0 || adc2 < 0) {
            fprintf(stderr, "Error: ADC read failed, exiting.\n");
            break;
        }

        int cancelled_audio = (int)((double)adc1 - (double)adc2) * gain;

        if (cancelled_audio < 0) cancelled_audio = 0;
        if (cancelled_audio > 1023) cancelled_audio = 1023;

        printf("%d,%d,%d\n", adc1, adc2, cancelled_audio);
        fflush(stdout);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    spiClose(spi_handle);
    gpioTerminate();

    printf("\nAudio sampling stopped.\n");
    return 0;
}

