#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define LOG_FILE "moisture_log.txt"
#define SAMPLE_INTERVAL 60

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int log_moisture_data(int moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        fprintf(stderr, "Error: gmtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d\n", timestamp, moisture_level) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: Failed to close log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGTERM handler: %s\n", strerror(errno));
    }

    printf("VH400 soil moisture logger started. Logging to '%s' every %d seconds.\n", LOG_FILE, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int moisture_level = read_mcp3008(MCP3008_CHANNEL);

        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
        } else if (moisture_level < 0 || moisture_level > 1023) {
            fprintf(stderr, "Error: Invalid moisture level %d (expected 0-1023)\n", moisture_level);
        } else {
            if (log_moisture_data(moisture_level) != 0) {
                fprintf(stderr, "Error: Failed to log moisture data\n");
            }
        }

        if (running) {
            sleep(SAMPLE_INTERVAL);
        }
    }

    printf("\nShutting down...\n");

    if (spi_handle >= 0) {
        if (spiClose(spi_handle) != 0) {
            fprintf(stderr, "Warning: spiClose() failed\n");
        }
    }

    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

