#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8

#define BUZZER_GPIO 18
#define FLAME_THRESHOLD 1.0
#define TEMPERATURE_OFFSET 25.0
#define TEMPERATURE_SCALE 0.001
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3
#define ADC_MAX 1023

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *buzzer_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float read_temperature(void) {
    FILE *fp = fopen("ambient_temp.txt", "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open ambient_temp.txt: %s. Using default %.2f°C\n", strerror(errno), TEMPERATURE_OFFSET);
        return TEMPERATURE_OFFSET;
    }

    float temp;
    if (fscanf(fp, "%f", &temp) != 1) {
        fprintf(stderr, "Warning: Invalid temperature in ambient_temp.txt. Using default %.2f°C\n", TEMPERATURE_OFFSET);
        temp = TEMPERATURE_OFFSET;
    }
    fclose(fp);
    return temp;
}

static int log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    if (fprintf(log_file, "%s,%d,%.3f,%.3f,%.2f,%d\n", timestamp, raw_adc, voltage, compensated_voltage, temperature, flame_detected) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return 1;
    }

    log_file = fopen("flame_log.txt", "a");
    if (!log_file) {
        perror("Failed to open flame_log.txt");
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        fclose(log_file);
        return 1;
    }

    unsigned char mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        cleanup();
        return 1;
    }

    unsigned char bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        cleanup();
        return 1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("Failed to open gpiochip4");
        cleanup();
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        perror("Failed to get GPIO line for buzzer");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(buzzer_line, "flame_buzzer", 0) < 0) {
        perror("Failed to request GPIO line as output");
        cleanup();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_adc = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && running) {
            raw_adc = read_mcp3008(0);
            if (raw_adc >= 0 && raw_adc <= ADC_MAX) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "ADC read failed (attempt %d/%d). Retrying...\n", retries, MAX_RETRIES);
                usleep(100000);
            }
        }

        if (raw_adc < 0 || raw_adc > ADC_MAX) {
            fprintf(stderr, "ADC read failed after %d retries. Skipping iteration.\n", MAX_RETRIES);
            gpiod_line_set_value(buzzer_line, 0);
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        float voltage = (float)raw_adc * 3.3f / 1024.0f;
        float temperature = read_temperature();
        float compensated_voltage = voltage + (temperature - TEMPERATURE_OFFSET) * TEMPERATURE_SCALE;
        int flame_detected = (compensated_voltage > FLAME_THRESHOLD) ? 1 : 0;

        if (log_data(raw_adc, voltage, compensated_voltage, temperature, flame_detected) < 0) {
            fprintf(stderr, "Logging failed. Continuing...\n");
        }

        if (flame_detected) {
            gpiod_line_set_value(buzzer_line, 1);
            printf("Flame detected! Buzzer ON.\n");
        } else {
            gpiod_line_set_value(buzzer_line, 0);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

