#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define LED_GPIO 17
#define WATER_LEVEL_HIGH 75.0
#define WATER_LEVEL_LOW 70.0
#define MCP3008_CHANNEL 0
#define SAMPLE_INTERVAL_MS 5000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *json_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d): %s\n", ret, pigpio_error(ret));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double calculate_water_level(int adc_value) {
    return (double)adc_value / 1023.0 * 100.0;
}

static void log_water_level(double water_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    int milliseconds = ts.tv_nsec / 1000000;

    fprintf(json_file, "{\"timestamp\":\"%s.%03d\", \"water_level\":%.2f}\n",
            timestamp, milliseconds, water_level);
    fflush(json_file);
}

static void control_led(double water_level) {
    static int led_state = 0;

    if (water_level > WATER_LEVEL_HIGH && led_state == 0) {
        gpioWrite(LED_GPIO, 1);
        led_state = 1;
        printf("Water level high (%.2f%%), LED ON\n", water_level);
    } else if (water_level < WATER_LEVEL_LOW && led_state == 1) {
        gpioWrite(LED_GPIO, 0);
        led_state = 0;
        printf("Water level low (%.2f%%), LED OFF\n", water_level);
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    if (json_file != NULL) {
        fprintf(json_file, "]\n");
        fclose(json_file);
        json_file = NULL;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", pigpio_error(spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    json_file = fopen("water_levels.json", "w");
    if (json_file == NULL) {
        perror("Failed to open water_levels.json");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(json_file, "[\n");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
        } else {
            double water_level = calculate_water_level(adc_value);
            log_water_level(water_level);
            control_led(water_level);
            printf("Water level: %.2f%% (ADC: %d)\n", water_level, adc_value);
        }

        for (int i = 0; i < 50 && running; i++) {
            gpioDelay(100000);
        }
    }

    cleanup();
    printf("Water level monitoring stopped.\n");
    return EXIT_SUCCESS;
}

