#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_RAW 300
#define DEFAULT_MAX_RAW 700
#define DEFAULT_MOISTURE_THRESHOLD 30.0
#define DEFAULT_LOGGING_FREQUENCY 60
#define DEFAULT_RECIPIENT_EMAIL "recipient@example.com"
#define DEFAULT_MSMTP_CONFIG "/etc/msmtprc"
#define DEFAULT_LOG_FILE "plant_data.txt"
#define EMAIL_BODY_MAX 512

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static int pigpio_initialized = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double calculate_moisture_percentage(int raw_value, int min_raw, int max_raw) {
    if (max_raw == min_raw) return 0.0;
    return ((double)(raw_value - min_raw) / (double)(max_raw - min_raw)) * 100.0;
}

static int log_data(const char *filename, double moisture_percentage) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file %s\n", filename);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage);
    fclose(fp);
    return 0;
}

static int send_email_alert(const char *recipient_email, const char *msmtp_config, double moisture_percentage) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    char email_body[EMAIL_BODY_MAX];
    snprintf(email_body, sizeof(email_body),
             "Subject: Plant Moisture Alert\n\n"
             "Plant moisture level is below threshold.\n"
             "Timestamp: %s\n"
             "Moisture Percentage: %.2f%%\n",
             timestamp, moisture_percentage);

    char command[512];
    snprintf(command, sizeof(command),
             "msmtp -t %s < /dev/tty", recipient_email);

    FILE *fp = popen(command, "w");
    if (!fp) {
        fprintf(stderr, "Error: Could not execute msmtp\n");
        return -1;
    }

    if (fputs(email_body, fp) == EOF) {
        fprintf(stderr, "Error: Could not write email body\n");
        pclose(fp);
        return -1;
    }

    if (pclose(fp) == -1) {
        fprintf(stderr, "Error: msmtp execution failed\n");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (pigpio_initialized) {
        gpioTerminate();
        pigpio_initialized = 0;
    }
}

int main(int argc, char *argv[]) {
    int spi_channel = DEFAULT_SPI_CHANNEL;
    int adc_channel = DEFAULT_ADC_CHANNEL;
    int min_raw = DEFAULT_MIN_RAW;
    int max_raw = DEFAULT_MAX_RAW;
    double moisture_threshold = DEFAULT_MOISTURE_THRESHOLD;
    int logging_frequency = DEFAULT_LOGGING_FREQUENCY;
    char *recipient_email = strdup(DEFAULT_RECIPIENT_EMAIL);
    char *msmtp_config_path = strdup(DEFAULT_MSMTP_CONFIG);
    char *log_file_path = strdup(DEFAULT_LOG_FILE);

    if (!recipient_email || !msmtp_config_path || !log_file_path) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        free(recipient_email);
        free(msmtp_config_path);
        free(log_file_path);
        return 1;
    }

    int opt;
    while ((opt = getopt(argc, argv, "s:a:m:M:t:f:r:c:l:")) != -1) {
        switch (opt) {
            case 's': spi_channel = atoi(optarg); break;
            case 'a': adc_channel = atoi(optarg); break;
            case 'm': min_raw = atoi(optarg); break;
            case 'M': max_raw = atoi(optarg); break;
            case 't': moisture_threshold = atof(optarg); break;
            case 'f': logging_frequency = atoi(optarg); break;
            case 'r': recipient_email = strdup(optarg); break;
            case 'c': msmtp_config_path = strdup(optarg); break;
            case 'l': log_file_path = strdup(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-s spi_channel] [-a adc_channel] [-m min_raw] [-M max_raw] [-t moisture_threshold] [-f logging_frequency] [-r recipient_email] [-c msmtp_config] [-l log_file]\n", argv[0]);
                free(recipient_email);
                free(msmtp_config_path);
                free(log_file_path);
                return 1;
        }
    }

    if (spi_channel < 0 || spi_channel > 1) {
        fprintf(stderr, "Error: Invalid SPI channel %d\n", spi_channel);
        free(recipient_email);
        free(msmtp_config_path);
        free(log_file_path);
        return 1;
    }
    if (adc_channel < 0 || adc_channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", adc_channel);
        free(recipient_email);
        free(msmtp_config_path);
        free(log_file_path);
        return 1;
    }
    if (min_raw >= max_raw) {
        fprintf(stderr, "Error: Minimum raw value must be less than maximum raw value\n");
        free(recipient_email);
        free(msmtp_config_path);
        free(log_file_path);
        return 1;
    }
    if (moisture_threshold < 0.0 || moisture_threshold > 100.0) {
        fprintf(stderr, "Error: Moisture threshold must be between 0.0 and 100.0\n");
        free(recipient_email);
        free(msmtp_config_path);
        free(log_file_path);
        return 1;
    }
    if (logging_frequency <= 0) {
        fprintf(stderr, "Error: Logging frequency must be greater than 0\n");
        free(recipient_email);
        free(msmtp_config_path);
        free(log_file_path);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        free(recipient_email);
        free(msmtp_config_path);
        free(log_file_path);
        return 1;
    }
    pigpio_initialized = 1;

    spi_handle = spiOpen(spi_channel, 500000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed on channel %d\n", spi_channel);
        cleanup();
        free(recipient_email);
        free(msmtp_config_path);
        free(log_file_path);
        return 1;
    }

    printf("Plant monitoring started. Logging to %s every %d seconds.\n", log_file_path, logging_frequency);
    printf("SPI channel: %d, ADC channel: %d, Min raw: %d, Max raw: %d, Threshold: %.2f%%\n",
           spi_channel, adc_channel, min_raw, max_raw, moisture_threshold);

    while (running) {
        int raw_value = read_mcp3008(adc_channel);
        if (raw_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        } else {
            double moisture_percentage = calculate_moisture_percentage(raw_value, min_raw, max_raw);

            if (log_data(log_file_path, moisture_percentage) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }

            if (moisture_percentage < moisture_threshold) {
                if (send_email_alert(recipient_email, msmtp_config_path, moisture_percentage) != 0) {
                    fprintf(stderr, "Error: Failed to send email alert\n");
                }
            }
        }

        for (int i = 0; i < logging_frequency && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    free(recipient_email);
    free(msmtp_config_path);
    free(log_file_path);
    return 0;
}

