#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define MCP3008_CH     0          /* KY-036 analog out -> MCP3008 CH0 */
#define LOG_FILE       "soil_moisture.log"
#define DEFAULT_DELAY  1          /* seconds between samples */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — async-signal-safe subset only                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;                 /* let main loop exit cleanly          */
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 single-ended channel (0-7).                            */
/* Returns 0-1023 on success, -1 on SPI transfer error.                 */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: SGL/DIFF=1 (single) | D2 D1 D0 = channel, upper nibble
     *          => 0x80 | (channel << 4)
     *   Byte 2: 0x00  (don't care, clocks out low 2 bits)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9 b8] in the lower nibble
     *   rx[2] = b7..b0
     */
    unsigned char tx[3] = { 0x01, (unsigned char)(0x80 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert 10-bit ADC value to moisture percentage (0-100).            */
/* 0 = bone dry, 1023 = fully submerged.                               */
/* ------------------------------------------------------------------ */
static int adc_to_moisture(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;
    return (int)(((float)adc_value / 1023.0f) * 100.0f);
}

/* ------------------------------------------------------------------ */
/* Append a timestamped sample line to the log file.                    */
/* ------------------------------------------------------------------ */
static void log_sample(FILE *fp, int adc_value, int moisture)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, ADC: %d, Moisture: %d%%\n", ts, adc_value, moisture);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources.                                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int sample_delay = DEFAULT_DELAY;

    if (argc > 1) {
        sample_delay = atoi(argv[1]);
        if (sample_delay <= 0) {
            fprintf(stderr, "Invalid delay '%s', using default %d s\n",
                    argv[1], DEFAULT_DELAY);
            sample_delay = DEFAULT_DELAY;
        }
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- SPI open ---- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");
    printf("Sampling every %d s. Log: %s\n", sample_delay, LOG_FILE);

    /* ---- main loop ---- */
    while (g_running) {
        int adc = read_mcp3008(g_spi_handle, MCP3008_CH);
        if (adc < 0) {
            fprintf(stderr, "Warning: SPI read error — skipping sample\n");
        } else {
            int moisture = adc_to_moisture(adc);
            log_sample(g_log_file, adc, moisture);
            printf("ADC: %4d  Moisture: %3d%%\n", adc, moisture);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < sample_delay * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

