    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs_line) {
        perror("Failed to get CS GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008-cs", 1) < 0) {
        perror("Failed to request CS line as output");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Monitoring Started. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpiod_line_set_value(cs_line, 0) < 0) {
            perror("Failed to assert CS");
            break;
        }

        int adc_value = read_mcp3008(spi_fd, 0);

        if (gpiod_line_set_value(cs_line, 1) < 0) {
            perror("Failed to deassert CS");
            break;
        }

        if (adc_value < 0) {
            fprintf(stderr, "SPI communication error\n");
        } else if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Warning: ADC value at rail (%d). Sensor absent or wiring fault.\n", adc_value);
        } else {
            float moisture_percentage = calculate_moisture_percentage(adc_value);
            log_data(moisture_percentage);
        }

        sleep(5);
    }

    printf("\nCleaning up...\n");
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

