#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 300
#define MOISTURE_THRESHOLD_HIGH 600
#define LOG_BUFFER_SIZE 20
#define SAMPLE_INTERVAL_US 5000000

#define ADC_CHANNEL 0

typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

typedef struct {
    LogEntry entries[LOG_BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static int spi_handle = -1;
static CircularBuffer log_buffer;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %s\n", SPI_CHANNEL, pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed: %s\n", pigpio_error(ret));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

static void control_pump(int moisture_level) {
    static int pump_state = 0;
    int new_state = (moisture_level < MOISTURE_THRESHOLD_LOW) ? 1 : 0;

    if (new_state != pump_state) {
        if (gpioWrite(PUMP_GPIO, new_state) != 0) {
            fprintf(stderr, "Error writing to GPIO %d\n", PUMP_GPIO);
            return;
        }
        pump_state = new_state;
        printf("Pump %s\n", pump_state ? "ON" : "OFF");
    }
}

static void add_to_log(int moisture_level, int pump_state) {
    log_buffer.entries[log_buffer.head].timestamp = time(NULL);
    log_buffer.entries[log_buffer.head].moisture_level = moisture_level;
    log_buffer.entries[log_buffer.head].pump_state = pump_state;

    log_buffer.head = (log_buffer.head + 1) % LOG_BUFFER_SIZE;
    if (log_buffer.count < LOG_BUFFER_SIZE) {
        log_buffer.count++;
    }
}

static void print_log_buffer(void) {
    printf("\n--- Log Buffer (%d entries) ---\n", log_buffer.count);
    int start = (log_buffer.count < LOG_BUFFER_SIZE) ? 0 : log_buffer.head;
    for (int i = 0; i < log_buffer.count; i++) {
        int idx = (start + i) % LOG_BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&log_buffer.entries[idx].timestamp);
        if (tm_info) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(time_str, "UNKNOWN", sizeof(time_str));
        }
        printf("[%s] Moisture: %d, Pump: %s\n",
               time_str,
               log_buffer.entries[idx].moisture_level,
               log_buffer.entries[idx].pump_state ? "ON" : "OFF");
    }
    printf("--- End of Log Buffer ---\n\n");
}

static void timer_callback(void *user_data) {
    (void)user_data;
    int moisture_level = read_mcp3008(ADC_CHANNEL);
    if (moisture_level < 0) {
        fprintf(stderr, "Error reading moisture level\n");
        return;
    }

    control_pump(moisture_level);
    add_to_log(moisture_level, (moisture_level < MOISTURE_THRESHOLD_LOW) ? 1 : 0);
    print_log_buffer();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", PUMP_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(PUMP_GPIO, 0) != 0) {
        fprintf(stderr, "Error initializing pump state on GPIO %d\n", PUMP_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    memset(&log_buffer, 0, sizeof(log_buffer));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up timer\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Soil Moisture Monitoring System started. Press Ctrl+C to exit.\n");

    while (running) {
        sleep(1);
    }

    printf("\nShutting down...\n");
    gpioSetTimerFuncEx(0, 0, NULL, NULL);
    gpioWrite(PUMP_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

