#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define MAX30102_ADDR 0x57

#define REG_INTR_STATUS_1 0x00
#define REG_INTR_STATUS_2 0x01
#define REG_INTR_ENABLE_1 0x02
#define REG_INTR_ENABLE_2 0x03
#define REG_FIFO_WR_PTR 0x04
#define REG_OVF_COUNTER 0x05
#define REG_FIFO_RD_PTR 0x07
#define REG_MODE_CONFIG 0x06
#define REG_SPO2_CONFIG 0x08
#define REG_LED1_PA 0x09
#define REG_LED2_PA 0x0A
#define REG_PART_ID 0xFF

#define EXPECTED_PART_ID 0x15
#define SAMPLE_INTERVAL_US 1000000
#define LOG_FILE "health_log.txt"

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    return i2cWriteDevice(i2c_handle, buf, 2);
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) return -1;
    char data_buf[1];
    if (i2cReadDevice(i2c_handle, data_buf, 1) != 1) return -1;
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int init_max30102(void) {
    uint8_t part_id = 0;
    if (i2c_read_reg(REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error: Failed to read Part ID register.\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Error: Unexpected Part ID 0x%02X (expected 0x%02X). Sensor not present?\n", part_id, EXPECTED_PART_ID);
        return -1;
    }

    if (i2c_write_reg(REG_MODE_CONFIG, 0x40) != 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg(REG_INTR_ENABLE_1, 0x00) != 0) return -1;
    if (i2c_write_reg(REG_INTR_ENABLE_2, 0x00) != 0) return -1;

    if (i2c_write_reg(REG_MODE_CONFIG, 0x03) != 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg(REG_SPO2_CONFIG, 0x27) != 0) return -1;
    if (i2c_write_reg(REG_LED1_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED2_PA, 0x24) != 0) return -1;

    return 0;
}

static int read_fifo_data(uint8_t *data, int len) {
    char reg_buf[1] = {(char)REG_FIFO_RD_PTR};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) return -1;
    char read_buf[len];
    if (i2cReadDevice(i2c_handle, read_buf, len) != len) return -1;
    memcpy(data, read_buf, len);
    return 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file %s.\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s - %s\n", timestamp, message);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at address 0x%02X on bus %d.\n", MAX30102_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (init_max30102() != 0) {
        fprintf(stderr, "Error: MAX30102 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MAX30102 monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint8_t data[6];
        if (read_fifo_data(data, 6) != 0) {
            fprintf(stderr, "Error: Failed to read FIFO data.\n");
            log_event("I2C read error");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        uint32_t ir_sum = 0, red_sum = 0;
        for (int i = 0; i < 3; i++) {
            ir_sum += data[i];
            red_sum += data[i + 3];
        }

        if (ir_sum == 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float ratio = (float)red_sum / (float)ir_sum;
        float spo2 = 110.0f - 25.0f * ratio;
        if (spo2 < 0.0f) spo2 = 0.0f;
        if (spo2 > 100.0f) spo2 = 100.0f;

        if (spo2 < 95.0f) {
            char log_msg[128];
            snprintf(log_msg, sizeof(log_msg), "SpO2: %.1f%%", spo2);
            log_event(log_msg);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

