#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0
#define BUZZER_PIN  24
#define GAS_THRESHOLD 500
#define SAMPLE_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read a 10-bit value from the MCP3008 on the given single-ended channel.
 * Returns 0-1023 on success, or -1 on SPI error.
 */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (Mode 0, 0):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     *   Byte 2: 0x00  (don't care, clocks out low 2 bits)
     * Response:
     *   rx[1] bits 1-0 are the high 2 bits of the result.
     *   rx[2] is the low 8 bits.
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

static int set_buzzer(int state) {
    int ret = gpioWrite(BUZZER_PIN, state);
    if (ret < 0) {
        fprintf(stderr, "Failed to write buzzer pin %d: %s\n",
                BUZZER_PIN, pigpio_error(ret));
        return -1;
    }
    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, Mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", pigpio_error(spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure buzzer pin as output and ensure it starts OFF */
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (set_buzzer(0) < 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        set_buzzer(0);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Gas sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int gas_value = read_mcp3008(0);
        if (gas_value < 0) {
            fprintf(stderr, "Error reading gas sensor value. Retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        printf("Gas ADC value: %d\n", gas_value);

        if (gas_value >= GAS_THRESHOLD) {
            if (set_buzzer(1) < 0) {
                fprintf(stderr, "Failed to turn buzzer ON\n");
            }
        } else {
            if (set_buzzer(0) < 0) {
                fprintf(stderr, "Failed to turn buzzer OFF\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Graceful cleanup */
    printf("\nShutting down...\n");
    set_buzzer(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

