    if (i2c_write_reg(ADS1115_REG_CONFIG, 0xC183) < 0) {
        perror("ads1115 config"); close(i2c_fd); i2c_fd = -1; return -1;
    }
    return 0;
}

static int ads1115_read(uint16_t *raw) {
    uint16_t cfg = 0xC183;
    if (i2c_write_reg(ADS1115_REG_CONFIG, cfg) < 0) return -1;
    usleep(10000);
    uint16_t val;
    if (i2c_read_reg16(ADS1115_REG_CONV, &val) < 0) return -1;
    *raw = val;
    return 0;
}

static int gpio_init(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) { perror("gpiod_chip_open"); return -1; }
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) { perror("relay line"); return -1; }
    reed_line = gpiod_chip_get_line(chip, REED_PIN);
    if (!reed_line) { perror("reed line"); return -1; }
    if (gpiod_line_request_output(relay_line, "door_relay", 0) < 0) {
        perror("relay out"); return -1;
    }
    if (gpiod_line_request_input(reed_line, "door_reed") < 0) {
        perror("reed in"); return -1;
    }
    return 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen("/var/log/door_events.log", "a");
    if (!fp) { perror("log open"); return; }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[64];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, msg);
    fclose(fp);
}

static void cleanup(void) {
    if (relay_line) gpiod_line_set_value(relay_line, 0);
    if (relay_line) gpiod_line_release(relay_line);
    if (reed_line) gpiod_line_release(reed_line);
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
}

int main(void) {
    struct sigaction sa = { .sa_handler = sighandler };
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (ads1115_init() < 0) { log_event("ADS1115 init failed"); return 1; }
    if (gpio_init() < 0) { log_event("GPIO init failed"); cleanup(); return 1; }

    double sum = 0.0;
    int valid = 0;
    for (int i = 0; i < CALIB_SAMPLES; i++) {
        uint16_t r;
        if (ads1115_read(&r) < 0) {
            fprintf(stderr, "Calibration read %d failed\n", i);
            continue;
        }
        sum += (double)r;
        valid++;
        usleep(CALIB_MS * 1000);
    }
    if (valid == 0) { log_event("No valid calibration samples"); cleanup(); return 1; }
    double avg = sum / valid;
    double thresh = avg * THRESHOLD_PCT / 100.0;
    printf("Calibrated: avg=%.2f, threshold=%.2f\n", avg, thresh);

    while (running) {
        uint16_t raw;
        if (ads1115_read(&raw) < 0) {
            log_event("ADC read failed");
            usleep(POLL_MS * 1000);
            continue;
        }
        double val = (double)raw;
        if (val < thresh) {
            log_event("Proximity below threshold - releasing lock");
            if (gpiod_line_set_value(relay_line, 1) < 0)
                log_event("Relay set HIGH failed");
            usleep(RELAY_PULSE_MS * 1000);
            if (gpiod_line_set_value(relay_line, 0) < 0)
                log_event("Relay set LOW failed");
            int reed = gpiod_line_get_value(reed_line);
            if (reed < 0) {
                log_event("Reed read failed");
            } else if (reed == 0) {
                log_event("Door opened");
            } else {
                log_event("Door not opened");
            }
        }
        usleep(POLL_MS * 1000);
    }

    log_event("Shutting down");
    cleanup();
    return 0;
}

