#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8

#define NUM_SENSORS     3
#define LOG_INTERVAL_S  5
#define LOG_FILE        "soil_moisture_log.csv"

static const int cs_pins[NUM_SENSORS] = {8, 7, 25};

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int spi_fd, struct gpiod_line *cs_line, int channel) {
    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "CS low failed: %s\n", strerror(errno));
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "CS high failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int log_data(FILE *fp, int s1, int s2, int s3) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, s1, s2, s3) < 0) {
        fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open failed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    struct gpiod_line *cs_lines[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        cs_lines[i] = gpiod_chip_get_line(chip, cs_pins[i]);
        if (!cs_lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n", cs_pins[i], strerror(errno));
            for (int j = 0; j < i; j++) gpiod_line_release(cs_lines[j]);
            gpiod_chip_close(chip);
            close(spi_fd);
            return 1;
        }
        if (gpiod_line_request_output(cs_lines[i], "mcp3008-cs", 1) < 0) {
            fprintf(stderr, "gpiod_line_request_output(%d) failed: %s\n", cs_pins[i], strerror(errno));
            for (int j = 0; j < i; j++) gpiod_line_release(cs_lines[j]);
            gpiod_chip_close(chip);
            close(spi_fd);
            return 1;
        }
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        for (int i = 0; i < NUM_SENSORS; i++) gpiod_line_release(cs_lines[i]);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n") < 0 || fflush(fp) != 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
        }
    }

    printf("Logging soil moisture data every %d seconds. Press Ctrl+C to stop.\n", LOG_INTERVAL_S);

    while (g_running) {
        int s1 = read_mcp3008(spi_fd, cs_lines[0], 0);
        int s2 = read_mcp3008(spi_fd, cs_lines[1], 0);
        int s3 = read_mcp3008(spi_fd, cs_lines[2], 0);

        if (log_data(fp, s1, s2, s3) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        for (int i = 0; i < LOG_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    fclose(fp);
    for (int i = 0; i < NUM_SENSORS; i++) gpiod_line_release(cs_lines[i]);
    gpiod_chip_close(chip);
    close(spi_fd);

    return 0;
}

