#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define MCP3008_CHANNEL 0
#define MAX_RETRIES 3
#define DRY_RAW 200
#define WET_RAW 800
#define DEFAULT_THRESHOLD 30.0
#define DEFAULT_DURATION 10
#define DEFAULT_INTERVAL 60

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static double threshold = DEFAULT_THRESHOLD;
static int duration = DEFAULT_DURATION;
static int interval = DEFAULT_INTERVAL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %d\n", attempt + 1, MAX_RETRIES, ret);
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(100000);
        }
    }
    return -1;
}

static double calculate_moisture(int raw) {
    if (raw < DRY_RAW) raw = DRY_RAW;
    if (raw > WET_RAW) raw = WET_RAW;
    double pct = ((double)(raw - DRY_RAW) / (double)(WET_RAW - DRY_RAW)) * 100.0;
    if (pct < 0.0) pct = 0.0;
    if (pct > 100.0) pct = 100.0;
    return pct;
}

static void log_event(const char *msg) {
    FILE *fp = fopen("irrigation.log", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %m\n");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fclose(fp);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't': threshold = atof(optarg); break;
            case 'd': duration = atoi(optarg); break;
            case 's': interval = atoi(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration_s] [-s sleep_s]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioWrite(PUMP_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Irrigation system started");

    while (running) {
        int raw = read_mcp3008(MCP3008_CHANNEL);
        if (raw < 0) {
            log_event("Error: MCP3008 read failed after retries");
            gpioDelay(interval * 1000000);
            continue;
        }

        double moisture = calculate_moisture(raw);
        char msg[128];
        snprintf(msg, sizeof(msg), "Moisture: %.2f%% (raw=%d)", moisture, raw);
        log_event(msg);

        if (moisture < threshold) {
            log_event("Moisture below threshold, activating pump");
            if (gpioWrite(PUMP_GPIO, 1) != 0) {
                log_event("Error: failed to activate pump");
            } else {
                gpioDelay(duration * 1000000);
                if (gpioWrite(PUMP_GPIO, 0) != 0) {
                    log_event("Error: failed to deactivate pump");
                } else {
                    log_event("Pump deactivated");
                }
            }
        }

        gpioDelay(interval * 1000000);
    }

    log_event("Shutting down, turning off pump");
    cleanup();
    return EXIT_SUCCESS;
}

