#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define PCF8591_ADDR   0x48
#define PCF8591_CTRL   0x40  /* single-ended, channel 0, analog output disabled */
#define SAMPLE_MS      100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }

    /* Acquire the PCF8591 slave address */
    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        goto cleanup;
    }

    /*
     * The PCF8591 returns the result of the previous conversion on the
     * first read after a control-byte write.  Issue a dummy read and
     * discard it so the next read returns the current sample.
     */
    uint8_t dummy;
    ssize_t n = read(fd, &dummy, 1);
    if (n != 1) {
        if (n < 0)
            perror("dummy read");
        else
            fprintf(stderr, "dummy read returned %zd bytes\n", n);
        goto cleanup;
    }

    printf("PCF8591 AIN0 monitor started (Ctrl-C to stop)\n");

    while (g_running) {
        /* Write the control byte to select channel 0, single-ended */
        uint8_t ctrl = PCF8591_CTRL;
        ssize_t w = write(fd, &ctrl, 1);
        if (w != 1) {
            if (w < 0)
                perror("write control byte");
            else
                fprintf(stderr, "write control byte returned %zd\n", w);
            goto cleanup;
        }

        /* Read the current conversion result */
        uint8_t value;
        ssize_t r = read(fd, &value, 1);
        if (r != 1) {
            if (r < 0)
                perror("read conversion");
            else
                fprintf(stderr, "read conversion returned %zd\n", r);
            goto cleanup;
        }

        printf("AIN0: %u\n", (unsigned)value);
        fflush(stdout);

        usleep(SAMPLE_MS * 1000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

