#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <syslog.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* Configuration */
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_BASE 0x8000  /* OS bit: begin single conversion */
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define MOTOR_SHUTDOWN_PIN 27
#define BUFFER_SIZE 10
#define THRESHOLD_GAUSS 500.0f
#define SAMPLE_INTERVAL_US 1000000  /* 1 Hz */
#define VREF 3.3f
#define ZERO_FIELD_VOLTAGE 2.5f
#define SENSITIVITY_MV_PER_GAUSS 1.4f

/* Globals */
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

/* Circular buffer */
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static CircularBuffer gauss_buffer = {0};

/* Prototypes */
static int ads1115_read_raw(int handle, int16_t *raw_out);
static float raw_to_gauss(int16_t raw);
static void buffer_add(CircularBuffer *cb, float value);
static float buffer_average(const CircularBuffer *cb);
static void motor_shutdown(void);
static void cleanup(void);
static void signal_handler(int sig);

/* Read raw 16-bit signed value from ADS1115 conversion register */
static int ads1115_read_raw(int handle, int16_t *raw_out) {
    char reg = ADS1115_REG_CONVERSION;
    char buf[2];

    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        syslog(LOG_ERR, "I2C write (reg select) failed: %s", strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        syslog(LOG_ERR, "I2C read conversion failed: %s", strerror(errno));
        return -1;
    }
    *raw_out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* Convert raw ADC value to Gauss */
static float raw_to_gauss(int16_t raw) {
    float voltage = ((float)raw / 32767.0f) * VREF;
    if (voltage < 0.0f || voltage > VREF) {
        syslog(LOG_ERR, "Voltage out of range: %.3f V", voltage);
        return 0.0f;
    }
    float gauss = (voltage - ZERO_FIELD_VOLTAGE) /
                  (SENSITIVITY_MV_PER_GAUSS / 1000.0f);
    return gauss;
}

/* Add value to circular buffer */
static void buffer_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

/* Compute rolling average */
static float buffer_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / cb->count;
}

/* Drive shutdown pin HIGH */
static void motor_shutdown(void) {
    syslog(LOG_INFO, "Motor shutdown triggered!");
    if (gpioWrite(MOTOR_SHUTDOWN_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to set shutdown pin HIGH: %s", strerror(errno));
    }
}

/* Release all resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(MOTOR_SHUTDOWN_PIN, 0);
    gpioTerminate();
    closelog();
}

/* Signal handler */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    openlog("hall_monitor", LOG_PID | LOG_CONS, LOG_USER);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* Configure shutdown pin */
    if (gpioSetMode(MOTOR_SHUTDOWN_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", MOTOR_SHUTDOWN_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioWrite(MOTOR_SHUTDOWN_PIN, 0);

    /* Open I2C to ADS1115 */
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %d at addr 0x%02X", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Configure ADS1115: AIN0 single-ended, PGA +/-4.096 V, single-shot, 128 SPS */
    uint16_t config = ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS;
    char cfg_buf[3];
    cfg_buf[0] = ADS1115_REG_CONFIG;
    cfg_buf[1] = (config >> 8) & 0xFF;
    cfg_buf[2] = config & 0xFF;
    if (i2cWriteDevice(i2c_handle, cfg_buf, 3) != 0) {
        syslog(LOG_ERR, "Failed to configure ADS1115: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Allow first conversion to complete */
    gpioDelay(120000);  /* 120 ms > 1/128 s */

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Hall-effect monitor started (ADS1115 @ 0x%02X, threshold %.1f G)",
           ADS1115_ADDR, THRESHOLD_GAUSS);

    /* Main loop */
    while (running) {
        int16_t raw;
        if (ads1115_read_raw(i2c_handle, &raw) != 0) {
            syslog(LOG_ERR, "ADC read failed; skipping sample");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float gauss = raw_to_gauss(raw);
        buffer_add(&gauss_buffer, gauss);
        float avg = buffer_average(&gauss_buffer);

        syslog(LOG_INFO, "Raw=%d  V=%.3f  Gauss=%.2f  Avg=%.2f",
               raw, ((float)raw / 32767.0f) * VREF, gauss, avg);

        if (avg > THRESHOLD_GAUSS) {
            motor_shutdown();
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    cleanup();
    return EXIT_SUCCESS;
}

