#include <string.h>
#include <unistd.h>

#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MOISTURE_THRESHOLD 300
#define WATERING_DURATION 10
#define SLEEP_DURATION 60
#define LOG_FILE "watering_events.txt"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx[3] = {0};

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

static void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
}

static void log_event(int moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - Moisture Level: %d\n", timestamp, moisture_level);
    fclose(fp);
}

static void cleanup(void) {
    control_pump(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed on channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handlers\n");
        cleanup();
        return EXIT_FAILURE;
    }

    control_pump(0);

    while (running) {
        int moisture_level = read_mcp3008(0);

        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
            control_pump(0);
            break;
        }

        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level %d below threshold %d. Activating pump.\n",
                   moisture_level, MOISTURE_THRESHOLD);
            control_pump(1);
            log_event(moisture_level);

            for (int i = 0; i < WATERING_DURATION && running; i++) {
                sleep(1);
            }

            control_pump(0);
            printf("Pump deactivated.\n");
        } else {
            printf("Moisture level %d above threshold %d. No watering needed.\n",
                   moisture_level, MOISTURE_THRESHOLD);
        }

        for (int i = 0; i < SLEEP_DURATION && running; i++) {
            sleep(1);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

