#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define ADC_CHANNEL 0        /* MCP3008 CH0 */
#define ADC_MAX      1023     /* 10-bit ADC full-scale at 3.3 V */
#define RAIN_MAX     10
#define SAMPLE_US    1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0-1023 on success, -1 on SPI transfer failure.
 */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (mode 0, MSB first):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel select)
     *   Byte 2: 0x00  (clock out remaining bits)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9 b8] in the lower two bits
     *   rx[2] = b7..b0
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int calculate_rainfall_intensity(int adc_value)
{
    if (adc_value < 0) adc_value = 0;
    if (adc_value > ADC_MAX) adc_value = ADC_MAX;

    float intensity = (float)adc_value / (float)ADC_MAX * (float)RAIN_MAX;
    return (int)(intensity + 0.5f);
}

static void log_data(int adc_value, int intensity)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] ADC: %4d  Rain Intensity: %2d\n", timestamp, adc_value, intensity);
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); /* mode 0 */
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error; retrying next cycle\n");
        } else {
            int intensity = calculate_rainfall_intensity(adc_value);
            log_data(adc_value, intensity);
        }
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

