#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define PWM_GPIO    18
#define PWM_RANGE   1023
#define PWM_FREQ    1000
#define SAMPLE_US   100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0 */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int adc = read_mcp3008(spi_handle, 0);
        if (adc < 0) {
            fprintf(stderr, "ADC read error, retrying...\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (gpioPWM(PWM_GPIO, adc) != 0) {
            fprintf(stderr, "PWM write failed on GPIO %d\n", PWM_GPIO);
        }

        printf("ADC: %4d  PWM: %4d\n", adc, adc);
        fflush(stdout);
        gpioDelay(SAMPLE_US);
    }

    /* Clean shutdown */
    gpioPWM(PWM_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

