#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <getopt.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_BEGIN 0x8000
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define LED_GPIO 17
#define SAMPLE_INTERVAL_US 100000
#define BLINK_DURATION_US 1000000
#define BLINK_HALF_PERIOD_US 50000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static double threshold_gauss = 100.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_config(int handle, uint16_t config) {
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    if (i2cWriteDevice(handle, buf, 3) < 0) {
        fprintf(stderr, "Error writing ADS1115 config: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_conversion(int handle, int16_t *raw) {
    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(handle, &reg, 1) < 0) {
        fprintf(stderr, "Error setting ADS1115 conversion register: %s\n", strerror(errno));
        return -1;
    }
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading ADS1115 conversion: %s\n", strerror(errno));
        return -1;
    }
    *raw = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static double raw_to_gauss(int16_t raw) {
    const double vref = 4.096;
    const double sensitivity = 0.001;
    const double zero_gauss_v = 1.65;
    double voltage = (raw / 32767.0) * vref;
    return (voltage - zero_gauss_v) / sensitivity;
}

static void blink_led(int gpio, int duration_us) {
    for (int i = 0; i < duration_us / BLINK_HALF_PERIOD_US && running; i++) {
        gpioWrite(gpio, 1);
        gpioDelay(BLINK_HALF_PERIOD_US);
        gpioWrite(gpio, 0);
        gpioDelay(BLINK_HALF_PERIOD_US);
    }
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold_gauss = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_gauss]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n", I2C_BUS, ADS1115_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t config = ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0 |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;

    while (running) {
        if (write_config(i2c_handle, config) < 0) {
            break;
        }
        gpioDelay(10000);

        int16_t raw;
        if (read_conversion(i2c_handle, &raw) < 0) {
            break;
        }

        double gauss = raw_to_gauss(raw);
        printf("Magnetic Field: %.2f Gauss\n", gauss);

        if (gauss > threshold_gauss) {
            printf("Threshold exceeded! Blinking LED.\n");
            blink_led(LED_GPIO, BLINK_DURATION_US);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

