#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define RELAY_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_soil_monitor"
#define MQTT_TOPIC_SOIL_MOISTURE "soil_moisture"
#define MQTT_TOPIC_PUMP_CONTROL "pump_control"
#define MOISTURE_THRESHOLD_LOW 30.0
#define MOISTURE_THRESHOLD_HIGH 35.0
#define SAMPLE_INTERVAL 60
#define ADC_MAX_VALUE 1023
#define ADC_MIN_VALUE 0

static int spi_handle = -1;
static MQTTClient client;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel %d", channel);
        return -1;
    }

    char tx[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx[3] = {0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        syslog(LOG_ERR, "SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static float calculate_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
        syslog(LOG_ERR, "ADC value out of range: %d", adc_value);
        return -1.0;
    }
    return 100.0 - ((float)adc_value / (float)ADC_MAX_VALUE) * 100.0;
}

static void pump_control_callback(char *topic, char *payload, int payloadlen, void *userdata) {
    (void)userdata;
    if (payloadlen < 1) {
        syslog(LOG_ERR, "Empty payload received");
        return;
    }
    char cmd[2] = {0};
    if (payloadlen > 1) payloadlen = 1;
    memcpy(cmd, payload, payloadlen);
    syslog(LOG_INFO, "Pump command: %s", cmd);
    if (strcmp(cmd, "on") == 0) {
        if (gpioWrite(RELAY_GPIO, 1) != 0) {
            syslog(LOG_ERR, "Failed to activate relay");
        } else {
            syslog(LOG_INFO, "Pump activated");
        }
    } else if (strcmp(cmd, "off") == 0) {
        if (gpioWrite(RELAY_GPIO, 0) != 0) {
            syslog(LOG_ERR, "Failed to deactivate relay");
        } else {
            syslog(LOG_INFO, "Pump deactivated");
        }
    } else {
        syslog(LOG_ERR, "Invalid pump command: %s", cmd);
    }
}

static void soil_moisture_callback(char *topic, char *payload, int payloadlen, void *userdata) {
    (void)topic;
    (void)userdata;
    if (payloadlen < 1) {
        syslog(LOG_ERR, "Empty payload received");
        return;
    }
    float moisture = (float)payload[0] - '0';
    syslog(LOG_INFO, "Soil moisture: %.1f%%", moisture);
}

static int initialize_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "Failed to open SPI channel %d", SPI_CHANNEL);
        return -1;
    }
    syslog(LOG_INFO, "SPI initialized on channel %d, speed %d Hz", SPI_CHANNEL, SPI_SPEED);
    return 0;
}

static int initialize_gpio(void) {
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", RELAY_GPIO);
        return -1;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        syslog(LOG_ERR, "Failed to initialize relay GPIO %d to LOW", RELAY_GPIO);
        return -1;
    }
    syslog(LOG_INFO, "GPIO %d initialized as relay output (off)", RELAY_GPIO);
    return 0;
}

static int initialize_mqtt(void) {
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 60;
    conn_opts.cleansession = 1;

    int rc = MQTTClient_create(&client, MQTT_BROKER, MQTT_PORT, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTTClient_create failed: %s", MQTTClient_strerror(rc));
        return -1;
    }

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTTClient_connect failed: %s", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        return -1;
    }

    rc = MQTTClient_subscribe(client, MQTT_TOPIC_PUMP_CONTROL, 1);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTTClient_subscribe failed: %s", MQTTClient_strerror(rc));
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        return -1;
    }

    rc = MQTTClient_subscribe(client, MQTT_TOPIC_SOIL_MOISTURE, 1);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTTClient_subscribe failed: %s", MQTTClient_strerror(rc));
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        return -1;
    }

    syslog(LOG_INFO, "MQTT client connected to %s:%d", MQTT_BROKER, MQTT_PORT);
    return 0;
}

static void cleanup(void) {
    syslog(LOG_INFO, "Cleaning up resources...");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (client) {
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        client = NULL;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("soil_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handlers");
        closelog();
        return 1;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    if (initialize_spi() != 0) {
        gpioTerminate();
        closelog();
        return 1;
    }

    if (initialize_gpio() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    if (initialize_mqtt() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    int pump_active = 0;

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value");
        } else {
            float moisture = calculate_moisture(adc_value);
            if (moisture < 0) {
                syslog(LOG_ERR, "Failed to calculate moisture");
            } else {
                syslog(LOG_INFO, "Soil moisture: %.1f%% (ADC: %d)", moisture, adc_value);

