        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        float voltages[NUM_CHANNELS];
        int error = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int raw = read_mcp3008(i);
            if (raw < 0) {
                error = 1;
                break;
            }
            voltages[i] = (raw / 1023.0f) * VREF;
        }

        if (error) {
            fprintf(stderr, "Error reading ADC values, skipping log\n");
        } else {
            if (log_data(LOG_FILE, voltages) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        if (running) {
            sleep(SAMPLE_INTERVAL_SEC);
        }
    }

    if (spi_handle >= 0) {
