#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define NOISE_THRESHOLD 500
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define LOG_FILE "vibration_log.txt"
#define SAMPLE_INTERVAL_US 10000

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void log_event(int noise_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d - Noise Level: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, noise_level);
    fclose(fp);
}

static void control_motors(int noise_level) {
    if (noise_level > NOISE_THRESHOLD) {
        int duty = (noise_level - NOISE_THRESHOLD) * PWM_RANGE / (1023 - NOISE_THRESHOLD);
        if (duty > PWM_RANGE) duty = PWM_RANGE;
        if (duty < 0) duty = 0;

        if (gpioPWM(MOTOR1_GPIO, duty) < 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", MOTOR1_GPIO);
        }
        if (gpioPWM(MOTOR2_GPIO, duty) < 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", MOTOR2_GPIO);
        }
    } else {
        gpioPWM(MOTOR1_GPIO, 0);
        gpioPWM(MOTOR2_GPIO, 0);
    }
}

