        while (retries < MAX_RETRIES && running) {
            adc_value = read_mcp3008(0);
            if (adc_value >= 0) break;
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Read failed, retry %d/%d\n", retries, MAX_RETRIES);
                sleep(1);
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after %d retries\n", MAX_RETRIES);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float moisture_percentage = calculate_moisture_percentage(adc_value);
        if (moisture_percentage < 0) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        control_pump(moisture_percentage < MOISTURE_THRESHOLD ? 1 : 0);
        log_data(moisture_percentage);

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    control_pump(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

