#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define VALVE_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define NUM_SENSORS 3
#define LOG_FILE "irrigation.log"
#define SAMPLE_INTERVAL_SEC 5

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calculate_valve_position(int avg_adc) {
    if (avg_adc < 0) avg_adc = 0;
    if (avg_adc > 1023) avg_adc = 1023;
    int pos = 100 - (int)(((float)avg_adc / 1023.0f) * 100.0f);
    if (pos < 0) pos = 0;
    if (pos > 100) pos = 100;
    return pos;
}

static void log_data(int s1, int s2, int s3, int avg, int valve_pos) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s, S1=%d, S2=%d, S3=%d, Avg=%d, Valve=%d%%\n",
            ts, s1, s2, s3, avg, valve_pos);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, PWM_RANGE);
    gpioPWM(VALVE_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Irrigation control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int s1 = read_mcp3008(0);
        int s2 = read_mcp3008(1);
        int s3 = read_mcp3008(2);

        int valid = 0;
        int sum = 0;
        if (s1 >= 0) { sum += s1; valid++; }
        if (s2 >= 0) { sum += s2; valid++; }
        if (s3 >= 0) { sum += s3; valid++; }

        int avg = 0;
        if (valid > 0) {
            avg = sum / valid;
        }

        int valve_pos = calculate_valve_position(avg);
        gpioPWM(VALVE_GPIO, valve_pos);

        log_data(s1, s2, s3, avg, valve_pos);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    gpioPWM(VALVE_GPIO, 0);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    printf("Irrigation control stopped.\n");
    return 0;
}

