#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define LOG_FILE "soil_data.txt"
#define MAX_RETRIES 5
#define RETRY_DELAY_MS 100
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            if (adc_value < 0 || adc_value > 1023) {
                fprintf(stderr, "ADC value out of range: %d\n", adc_value);
                return -1;
            }
            return adc_value;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n",
                attempt + 1, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(RETRY_DELAY_MS * 1000);
        }
    }
    return -1;
}

static float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        return -1.0f;
    }
    return ((float)adc_value / 1023.0f) * 100.0f;
}

static void log_data(float moisture_percentage) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return;
    }

    if (moisture_percentage >= 0.0f) {
        fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage);
    } else {
        fprintf(fp, "%s, ERROR\n", timestamp);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed on channel %d: %s\n", SPI_CHANNEL, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value after %d retries.\n", MAX_RETRIES);
            log_data(-1.0f);
        } else {
            float moisture_percentage = calculate_moisture_percentage(adc_value);
            log_data(moisture_percentage);
            printf("Moisture: %.2f%% (ADC: %d)\n", moisture_percentage, adc_value);
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

