#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define CONFIG_FILE "theremin_config.txt"

#define MIN_FREQUENCY 220
#define MAX_FREQUENCY 880
#define MIN_DISTANCE 20
#define MAX_DISTANCE 400

#define MIN_VOLUME 0
#define MAX_VOLUME 100

#define PWM_PERIOD_NS 10000000
#define PWM_DUTY_CYCLE_NS 5000000

#define TIMEOUT_US 30000

volatile sig_atomic_t program_running = 1;

struct calibration_data {
    int trig_pin;
    int echo_pin;
    int pwm_pin;
    int spi_device;
    int ldr_channel;
    int min_frequency;
    int max_frequency;
    int min_distance;
    int max_distance;
    int min_volume;
    int max_volume;
};

struct calibration_data config;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int read_distance(int trig_pin, int echo_pin) {
    struct gpiod_line *trig_line = gpiod_line_get(config.trig_line, TRIG_PIN);
    struct gpiod_line *echo_line = gpiod_line_get(config.echo_line, ECHO_PIN);

    if (!trig_line || !echo_line) {
        fprintf(stderr, "Error: Failed to get GPIO lines.\n");
        return -1;
    }

    if (gpiod_line_request_output(trig_line, "theremin", 0) < 0) {
        fprintf(stderr, "Error: Failed to request trig line as output.\n");
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "theremin") < 0) {
        fprintf(stderr, "Error: Failed to request echo line as input.\n");
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        return -1;
    }

    struct timespec start_time, end_time;
    long long start_ns, end_ns, pulse_width_ns;

    gpiod_line_set_value(trig_line, 0);
    usleep(2);

    gpiod_line_set_value(trig_line, 1);
    usleep(10);
    gpiod_line_set_value(trig_line, 0);

    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end_time);
        if ((end_time.tv_sec - start_time.tv_sec) * 1000000000LL + (end_time.tv_nsec - start_time.tv_nsec) > TIMEOUT_US * 1000) {
            fprintf(stderr, "Error: Timeout waiting for echo start.\n");
            gpiod_line_release(trig_line);
            gpiod_line_release(echo_line);
            return -1;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end_time);
        if ((end_time.tv_sec - start_time.tv_sec) * 1000000000LL + (end_time.tv_nsec - start_time.tv_nsec) > TIMEOUT_US * 1000) {
            fprintf(stderr, "Error: Timeout waiting for echo end.\n");
            gpiod_line_release(trig_line);
            gpiod_line_release(echo_line);
            return -1;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &end_time);

    start_ns = start_time.tv_sec * 1000000000LL + start_time.tv_nsec;
    end_ns = end_time.tv_sec * 1000000000LL + end_time.tv_nsec;
    pulse_width_ns = end_ns - start_ns;

    int distance = (int)((pulse_width_ns / 2) / 29.1);

    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);

    return distance;
}

int read_ldr_value(int spi_device, int ldr_channel) {
    unsigned char tx_buf[3] = {0x01, (0x08 | (ldr_channel << 4)), 0x00};
    unsigned char rx_buf[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(spi_device, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error: SPI transfer failed");
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

int map_distance_to_frequency(int distance) {
    if (distance < config.min_distance) distance = config.min_distance;
    if (distance > config.max_distance) distance = config.max_distance;

    int frequency = config.min_frequency + (int)(((float)(distance - config.min_distance) / (config.max_distance - config.min_distance)) * (config.max_frequency - config.min_frequency));
    return frequency;
}

int map_ldr_value_to_volume(int ldr_value) {
    if (ldr_value < config.min_volume) ldr_value = config.min_volume;
    if (ldr_value > config.max_volume) ldr_value = config.max_volume;

    int volume = config.min_volume + (int)(((float)(ldr_value - config.min_volume) / (config.max_volume - config.min_volume)) * (config.max_volume - config.min_volume));
    return volume;
}

void set_pwm_frequency(int pwm_pin, int frequency) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/period", pwm_pin);
    FILE *fp = fopen(path, "w");
    if (fp) {
        fprintf(fp, "%d", 1000000000 / frequency);
        fclose(fp);
    }

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/duty_cycle", pwm_pin);
    fp = fopen(path, "w");
    if (fp) {
        fprintf(fp, "%d", (1000000000 / frequency) / 2);
        fclose(fp);
    }
}

void set_pwm_duty_cycle(int pwm_pin, int duty_cycle) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/duty_cycle", pwm_pin);
    FILE *fp = fopen(path, "w");
    if (fp) {
        fprintf(fp, "%d", duty_cycle);
        fclose(fp);
    }
}

void save_config(const char *filename) {
    FILE *fp = fopen(filename, "w");
    if (fp) {
        fprintf(fp, "%d,%d,%d,%d,%d,%d,%d,%d,%d,%d\n",
                config.trig_pin, config.echo_pin, config.pwm_pin, config.spi_device, config.ldr_channel,
                config.min_frequency, config.max_frequency, config.min_distance, config.max_distance,
                config.min_volume, config.max_volume);
        fclose(fp);
    }
}

int load_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error: Could not open config file.\n");
        return -1;
    }

    if (fscanf(fp, "%d,%d,%d,%d,%d,%d,%d,%d,%d,%d",
               &config.trig_pin, &config.echo_pin, &config.pwm_pin, &config.spi_device, &config.ldr_channel,
               &config.min_frequency, &config.max_frequency, &config.min_distance, &config.max_distance,
               &config.min_volume, &config.max_volume) != 10) {
        fprintf(stderr, "Error: Invalid config file format.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);

    if (load_config(CONFIG_FILE) != 0) {
        fprintf(stderr, "Error: Could not load config. Using defaults.\n");
        config.trig_pin = TRIG_PIN;
        config.echo_pin = ECHO_PIN;
        config.pwm_pin = PWM_PIN;
        config.spi_device = open(SPI_DEVICE, O_RDWR);
        if (config.spi_device < 0) {
            perror("Error: Could not open SPI device");
            return 1;
        }
        config.ldr_channel = 0;
        config.min_frequency = MIN_FREQUENCY;
        config.max_frequency = MAX_FREQUENCY;
        config.min_distance = MIN_DISTANCE;
        config.max_distance = MAX_DISTANCE;
        config.min_volume = MIN_VOLUME;
        config.max_volume = MAX_VOLUME;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error: Could not open gpiochip0");
        return 1;
    }

    config.trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    config.echo_line = gpiod_chip_get_line(chip, ECHO_PIN);

    if (!config.trig_line || !config.echo_line) {
        fprintf(stderr, "Error: Could not get GPIO lines.\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(config.trig_line, "theremin", 0) < 0) {
        fprintf(stderr, "Error: Could not request trig line as output.\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(config.echo_line, "theremin") < 0) {
        fprintf(stderr, "Error: Could not request echo line as input.\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(config.spi_device, SPI_IOC_WR_MODE, &(unsigned int){0}) < 0) {
        perror("Error: Could not set SPI mode");
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(config.spi_device, SPI_IOC_WR_BITS_PER_WORD, &(unsigned int){8}) < 0) {
        perror("Error: Could not set SPI bits per word");
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(config.spi_device, SPI_IOC_WR_MAX_SPEED_HZ, &(unsigned int){SPI_SPEED}) < 0) {
        perror("Error: Could not set SPI speed");
        gpiod_chip_close(chip);
        return 1;
    }

    while (program_running) {
        int distance = read_distance(config.trig_pin, config.echo_pin);
        if (distance < 0) {
            fprintf(stderr, "Error: Failed to read distance.\n");
            distance = -1;
        }

        int ldr_value = read_ldr_value(config.spi_device, config.ldr_channel);
        if (ldr_value < 0) {
            fprintf(stderr, "Error: Failed to read LDR value.\n");
            ldr_value = -1;
        }

        if (distance >= 0 && ldr_value >= 0) {
            int frequency = map_distance_to_frequency(distance);
            int volume = map_ldr_value_to_volume(ldr_value);
            int duty_cycle = (PWM_DUTY_CYCLE_NS * volume) / 100;

            set_pwm_frequency(config.pwm_pin, frequency);
            set_pwm_duty_cycle(config.pwm_pin, duty_cycle);
        }

        usleep(50000);
    }

    set_pwm_duty_cycle(config.pwm_pin, 0);
    gpiod_line_release(config.trig_line);
    gpiod_line_release(config.echo_line);
    gpiod_chip_close(chip);
    close(config.spi_device);
    save_config(CONFIG_FILE);

    return 0;
}

