FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_aqi(int adc_value);
void control_fan(int state);
void log_data(float aqi);
void signal_handler(int signal);
int initialize_spi();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // MCP3008 SPI protocol: start bit (1), single-ended mode (1), channel select (3 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode + channel
    tx_buf[2] = 0x00; // Don't care

    int retries = 0;
    while (retries < MAX_RETRIES) {
        int result = spiXfer(spi_handle, (char *)tx_buf, (char *)rx_buf, 3);
        if (result == 3) {
            // Extract 10-bit ADC value from response
            int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d/%d), result=%d\n", retries + 1, MAX_RETRIES, result);
            retries++;
            if (retries < MAX_RETRIES) {
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay before retry
            }
        }
    }

    fprintf(stderr, "Error: SPI transfer failed after %d retries\n", MAX_RETRIES);
    return -1;
}

// Function to convert ADC value to AQI
float adc_to_aqi(int adc_value) {
    // Linear mapping: 0-1023 -> 0-500
    return (float)adc_value * 500.0 / 1023.0;
}

// Function to control the ventilation fan
void control_fan(int state) {
    gpioWrite(FAN_GPIO, state);
}

// Function to log data to a file
void log_data(float aqi) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

