    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off initially

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value from MQ-135 sensor
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, re-initializing SPI...\n");
            spiClose(spi_handle);
            if (initialize_spi() != 0) {
                fprintf(stderr, "Error: SPI re-initialization failed, exiting\n");
                break;
            }
            continue; // Skip to the next iteration
        }

        // Convert ADC value to AQI
        float aqi = adc_to_aqi(adc_value);

        // Control the ventilation fan based on AQI
        if (aqi > AQI_THRESHOLD) {
            control_fan(1); // Turn fan on
        } else {
            control_fan(0); // Turn fan off
        }

        // Log the data
        log_data(aqi);

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup
    control_fan(0); // Ensure fan is off
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Air quality monitoring stopped.\n");
    return 0;
}

