    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (ppm_value < 0.0) {
        fprintf(log_fp, "%s, Error: ADC read failed\n", timestamp);
    } else {
        fprintf(log_fp, "%s, PPM: %.2f\n", timestamp, ppm_value);
    }
    fflush(log_fp);
}

static void cleanup(void) {
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (gpio_init() < 0) {
        close(spi_fd);
        spi_fd = -1;
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Alcohol sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = -1;
        int retries = 0;

        while (retries < MAX_SPI_RETRIES && program_running) {
            adc_value = read_mcp3008(ADC_CHANNEL);
            if (adc_value >= 0) {
                break;
            }
            retries++;
            if (retries < MAX_SPI_RETRIES) {
                fprintf(stderr, "SPI read failed, retrying (%d/%d)...\n", retries, MAX_SPI_RETRIES);
                usleep(SPI_RETRY_DELAY_MS * 1000);
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Error: SPI read failed after %d retries.\n", MAX_SPI_RETRIES);
            log_data(-1.0);
        } else {
            double ppm_value = adc_to_ppm(adc_value);

            if (adc_value == 0 || adc_value == 1023) {
                fprintf(stderr, "Warning: ADC reading at extreme (%d). Sensor absent or disconnected?\n", adc_value);
            }

            if (ppm_value > PPM_THRESHOLD_HIGH) {
                printf("Alcohol detected! Limit exceeded (PPM: %.2f)\n", ppm_value);
                fprintf(log_fp, "Alcohol detected! Limit exceeded (PPM: %.2f)\n", ppm_value);
            } else if (ppm_value < PPM_THRESHOLD_LOW) {
                printf("Sobriety confirmed (PPM: %.2f)\n", ppm_value);
                fprintf(log_fp, "Sobriety confirmed (PPM: %.2f)\n", ppm_value);
            } else {
                printf("Alcohol level within acceptable range (PPM: %.2f)\n", ppm_value);
                fprintf(log_fp, "Alcohol level within acceptable range (PPM: %.2f)\n", ppm_value);
            }
            fflush(log_fp);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

