#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>

// Motor 1
#define MOTOR1_ENABLE 18
#define MOTOR1_DIR    23

// Motor 2
#define MOTOR2_ENABLE 24
#define MOTOR2_DIR    25

// SPI
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0

// MCP3008 Channels
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

// Speed limits
#define MIN_SPEED 50
#define MAX_SPEED 255

// Motion profile parameters
#define ACCEL_TIME_MS 1000
#define HOLD_TIME_MS  2000
#define DECEL_TIME_MS 1000
#define PAUSE_TIME_MS 5000

// Global variables
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int map_pot_to_speed(int pot_value);
void motor1_forward(int speed);
void motor1_backward(int speed);
void motor2_forward(int speed);
void motor2_backward(int speed);
void motion_profile(int speed_factor);
void cleanup(int signal);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;

    // Stop motors
    gpioPWM(MOTOR1_ENABLE, 0);
    gpioPWM(MOTOR2_ENABLE, 0);
    gpioWrite(MOTOR1_DIR, 0);
    gpioWrite(MOTOR2_DIR, 0);

    // Close SPI
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }

    // Terminate pigpio
    gpioTerminate();
    exit(0);
}

// Read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // MCP3008 SPI command: start bit, single-ended mode, channel select
    tx_buf[0] = 0x01;  // Start bit
    tx_buf[1] = (0x08 | channel) << 4;  // Single-ended + channel
    tx_buf[2] = 0x00;

    int ret = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (returned %d)\n", channel, ret);
        return -1;
    }

    // Extract 10-bit value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Map potentiometer value (0-1023) to speed factor (0-1) using logarithmic curve
int map_pot_to_speed(int pot_value) {
    if (pot_value < 0) pot_value = 0;
    if (pot_value > 1023) pot_value = 1023;

    // Logarithmic mapping: finer control at lower speeds
    float speed_factor = (float)log10f((float)pot_value + 1.0f) / log10f(1024.0f);
    if (speed_factor < 0.0f) speed_factor = 0.0f;
    if (speed_factor > 1.0f) speed_factor = 1.0f;

    return (int)(speed_factor * 100.0f);
}

// Motor 1 forward
void motor1_forward(int speed) {
    gpioWrite(MOTOR1_DIR, 1);
    gpioPWM(MOTOR1_ENABLE, speed);
}

// Motor 1 backward
void motor1_backward(int speed) {
    gpioWrite(MOTOR1_DIR, 0);
    gpioPWM(MOTOR1_ENABLE, speed);
}

// Motor 2 forward
void motor2_forward(int speed) {
    gpioWrite(MOTOR2_DIR, 1);
    gpioPWM(MOTOR2_ENABLE, speed);
}

// Motor 2 backward
void motor2_backward(int speed) {
    gpioWrite(MOTOR2_DIR, 0);
    gpioPWM(MOTOR2_ENABLE, speed);
}

// Motion profile: accelerate, hold, decelerate
void motion_profile(int speed_factor) {
    int max_speed = (MAX_SPEED * speed_factor) / 100;
    int min_speed = (MIN_SPEED * speed_factor) / 100;

    // Accelerate
    for (int speed = min_speed; speed <= max_speed; speed++) {
        motor1_forward(speed);
        motor2_backward(speed);
        gpioDelay(ACCEL_TIME_MS);
        if (terminate) break;
    }

    // Hold
    for (int i = 0; i < HOLD_TIME_MS / 100; i++) {
        motor1_forward(max_speed);
        motor2_backward(max_speed);
        gpioDelay(100);
        if (terminate) break;
    }

    // Decelerate
    for (int speed = max_speed; speed >= min_speed; speed--) {
        motor1_forward(speed);
        motor2_backward(speed);
        gpioDelay(DECEL_TIME_MS);
        if (terminate) break;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIR, PI_OUTPUT);

    // Open SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Main loop
    while (!terminate) {
        // Read potentiometers
        int pot1_value = read_mcp3008(POT1_CHANNEL);
        int pot2_value = read_mcp3008(POT2_CHANNEL);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error reading potentiometers, skipping cycle\n");
            gpioDelay(PAUSE_TIME_MS * 1000);
            continue;
        }

        // Map to speed factors
        int speed_factor1 = map_pot_to_speed(pot1_value);
        int speed_factor2 = map_pot_to_speed(pot2_value);

        // Run motion profile
        motion_profile(speed_factor1);
        motion_profile(speed_factor2);

        // Pause
        gpioDelay(PAUSE_TIME_MS * 1000);
    }

    // Cleanup (should not reach here if signal handler works)
    cleanup(0);
    return 0;
}

