#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0     // MCP3008 channel 0
#define VREF 3.3          // Reference voltage for MCP3008
#define ADC_MAX 1023      // 10-bit ADC
#define SENSOR_MIN_VOLTAGE 0.5
#define SENSOR_MAX_VOLTAGE 4.5
#define SENSOR_MAX_AIRFLOW 200.0
#define LOG_FILE "airflow_log.txt"
#define SAMPLE_INTERVAL_MS 100

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_adc(int channel);
float voltage_to_airflow(float voltage);
void log_airflow(float airflow);
void log_error(const char *message);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        log_error("Invalid ADC channel");
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // MCP3008 SPI command: start bit (1), single-ended mode (1), channel select (3 bits), then don't care
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode + channel
    tx_buf[2] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        log_error("SPI transfer failed");
        return -1;
    }

    // Extract 10-bit ADC value from response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert voltage to airflow (SLPM)
float voltage_to_airflow(float voltage) {
    if (voltage < SENSOR_MIN_VOLTAGE) voltage = SENSOR_MIN_VOLTAGE;
    if (voltage > SENSOR_MAX_VOLTAGE) voltage = SENSOR_MAX_VOLTAGE;
    return (voltage - SENSOR_MIN_VOLTAGE) / (SENSOR_MAX_VOLTAGE - SENSOR_MIN_VOLTAGE) * SENSOR_MAX_AIRFLOW;
}

// Function to log airflow data to file
void log_airflow(float airflow) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Airflow: %.2f SLPM\n", timestamp, airflow);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to log errors to file
void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            log_error("ADC read failed");
        } else {
            // Convert ADC value to voltage
            float voltage = (float)adc_value / ADC_MAX * VREF;

            // Convert voltage to airflow
            float airflow = voltage_to_airflow(voltage);

            // Log airflow data
            log_airflow(airflow);
        }

        // Wait for 100 milliseconds
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpio delay is in microseconds
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Airflow monitoring stopped.\n");
    return 0;
}

