#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "gpiochip0"
#define CS_GPIO_LINE    8          /* GPIO8 = CE0 on Raspberry Pi Zero W */
#define ADC_CHANNEL     0          /* MCP3008 CH0 */
#define SAMPLE_RATE_HZ  1000
#define SAMPLE_PERIOD_NS (1000000000LL / SAMPLE_RATE_HZ)
#define LOG_FILE        "audio_log.txt"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0 on success and stores the 10-bit value in *out, -1 on error.
 */
static int mcp3008_read(int spi_fd, struct gpiod_line *cs_line, int channel,
                        uint16_t *out)
{
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };
    struct spi_ioc_transfer tr;
    int ret;

    /* Assert CS (active low) */
    ret = gpiod_line_set_value(cs_line, 0);
    if (ret < 0) {
        fprintf(stderr, "gpiod_line_set_value(0) failed: %s\n", strerror(errno));
        return -1;
    }

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = 1000000;
    tr.bits_per_word = 8;
    tr.delay_usecs = 0;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1); /* best-effort deassert */
        return -1;
    }

    /* Deassert CS */
    ret = gpiod_line_set_value(cs_line, 1);
    if (ret < 0) {
        fprintf(stderr, "gpiod_line_set_value(1) failed: %s\n", strerror(errno));
        return -1;
    }

    /* MCP3008 returns 10 bits: rx[1] low 2 bits + rx[2] 8 bits */
    *out = (uint16_t)(((rx[1] & 0x03) << 8) | rx[2]);
    return 0;
}

int main(void)
{
    int spi_fd = -1;
    FILE *log_file = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    int ret = EXIT_FAILURE;

    /* Signal handling for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Open SPI device */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup;
    }

    /* SPI mode 0, 8 bits/word, 1 MHz max */
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Open GPIO chip and request CS line as output, default high */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n",
                GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    cs_line = gpiod_chip_get_line(chip, CS_GPIO_LINE);
    if (!cs_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                CS_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008-cs", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Sampling ADMP401 via MCP3008 CH0 at %d Hz. Press Ctrl+C to stop.\n",
           SAMPLE_RATE_HZ);

    struct timespec next_sample;
    clock_gettime(CLOCK_MONOTONIC_RAW, &next_sample);

    while (g_running) {
        uint16_t adc_value;
        struct timespec now;
        long long elapsed_ns;
        long long sleep_ns;

        if (mcp3008_read(spi_fd, cs_line, ADC_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "ADC read failed; continuing.\n");
            goto sleep_and_retry;
        }

        clock_gettime(CLOCK_MONOTONIC_RAW, &now);
        elapsed_ns = (now.tv_sec - next_sample.tv_sec) * 1000000000LL
                    + (now.tv_nsec - next_sample.tv_nsec);

        /* Log with nanosecond timestamp */
        if (fprintf(log_file, "%lld|%u\n", elapsed_ns, adc_value) < 0) {
            fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
            goto cleanup;
        }
        if (fflush(log_file) != 0) {
            fprintf(stderr, "fflush failed: %s\n", strerror(errno));
            goto cleanup;
        }

        next_sample.tv_sec = now.tv_sec;
        next_sample.tv_nsec = now.tv_nsec;
        next_sample.tv_nsec += SAMPLE_PERIOD_NS;
        if (next_sample.tv_nsec >= 1000000000LL) {
            next_sample.tv_sec++;
            next_sample.tv_nsec -= 1000000000LL;
        }

        sleep_ns = (next_sample.tv_sec - now.tv_sec) * 1000000000LL
                  + (next_sample.tv_nsec - now.tv_nsec);
        if (sleep_ns > 0) {
            struct timespec req = {
                .tv_sec = sleep_ns / 1000000000LL,
                .tv_nsec = sleep_ns % 1000000000LL
            };
            while (nanosleep(&req, &req) < 0 && errno == EINTR && g_running) {
                /* interrupted by signal; loop back to check g_running */
            }
        }

        continue;

    sleep_and_retry:
        /* Sleep until the next scheduled sample (approximate) */
        struct timespec req = {
            .tv_sec = SAMPLE_PERIOD_NS / 1000000000LL,
            .tv_nsec = SAMPLE_PERIOD_NS % 1000000000LL
        };
        while (nanosleep(&req, &req) < 0 && errno == EINTR && g_running) {
            /* interrupted by signal; loop back to check g_running */
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return ret;
}

