#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// MCP3008 SPI configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_FLAGS 0       // Mode 0, active low CS

// MCP3008 CS pin (GPIO8)
#define CS_PIN 8

// ADXL335 configuration
#define ADXL335_X_CHANNEL 0
#define ADXL335_Y_CHANNEL 1
#define ADXL335_Z_CHANNEL 2
#define ADXL335_SENSITIVITY 0.3 // 300 mV/g
#define ADXL335_ZERO_G_BIAS 1.5 // 1.5V at 0g
#define ADC_VREF 3.3
#define ADC_RESOLUTION 1024.0

// Kalman filter parameters
#define Q_NOISE 0.001
#define R_MEASUREMENT 0.1

// Global variables
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Kalman filter state
typedef struct {
    double x;
    double P;
} KalmanState;

KalmanState kalman_x, kalman_y, kalman_z;

// Function prototypes
int read_mcp3008(int channel);
double adxl335_to_g(int adc_value);
double kalman_filter(KalmanState *state, double measurement);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buf[3];
    char rx_buf[3];

    // MCP3008 SPI command: Start bit (1), SGL/DIFF=1 (single-ended), D2 D1 D0 = channel
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00;

    gpioWrite(CS_PIN, 0); // Select MCP3008
    int ret = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    gpioWrite(CS_PIN, 1); // Deselect MCP3008

    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d (returned %d)\n", channel, ret);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Convert ADC value to acceleration in g
double adxl335_to_g(int adc_value) {
    double voltage = (double)adc_value * ADC_VREF / ADC_RESOLUTION;
    return (voltage - ADXL335_ZERO_G_BIAS) / ADXL335_SENSITIVITY;
}

// Kalman filter update
double kalman_filter(KalmanState *state, double measurement) {
    // Predict
    state->x = state->x; // No process model, just hold
    state->P = state->P + Q_NOISE;

    // Update
    double y = measurement - state->x;
    double S = state->P + R_MEASUREMENT;
    double K = state->P / S;

    state->x = state->x + K * y;
    state->P = (1.0 - K) * state->P;

    return state->x;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure CS pin as output and set high (deselected)
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Kalman filters
    kalman_x.x = 0.0;
    kalman_x.P = 1.0;
    kalman_y.x = 0.0;
    kalman_y.P = 1.0;
    kalman_z.x = 0.0;
    kalman_z.P = 1.0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("ADXL335 accelerometer reading (via MCP3008 ADC). Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int x_adc = read_mcp3008(ADXL335_X_CHANNEL);
        int y_adc = read_mcp3008(ADXL335_Y_CHANNEL);
        int z_adc = read_mcp3008(ADXL335_Z_CHANNEL);

        if (x_adc < 0 || y_adc < 0 || z_adc < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            break;
        }

        double x_g = adxl335_to_g(x_adc);
        double y_g = adxl335_to_g(y_adc);
        double z_g = adxl335_to_g(z_adc);

        double x_filtered = kalman_filter(&kalman_x, x_g);
        double y_filtered = kalman_filter(&kalman_y, y_g);
        double z_filtered = kalman_filter(&kalman_z, z_g);

        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", x_filtered, y_filtered, z_filtered);

        gpioDelay(100000); // 100 ms = 10 Hz
    }

    // Cleanup
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

