#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

#define VCC 3.3
#define V_QUIESCENT (VCC / 2.0)
#define SENSITIVITY 0.025
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static float read_sensor(struct gpiod_line *line) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
        return -1.0f;
    }
    return (float)val * VCC;
}

static float calculate_magnetic_field(float voltage) {
