#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define PUMP_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define MOISTURE_THRESHOLD 30.0
#define LOG_FILE "watering.log"

static int spi_handle = -1;
static volatile int keep_running = 1;

int read_mcp3008(int channel);
double calculate_moisture_level(int adc_value);
void control_pump(double moisture_level);
void log_event(const char *message);
void signal_handler(int signal);

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Error: Invalid MCP3008 channel");
        return -1;
    }

    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = 0x01;
    tx_buf[1] = (0x08 | channel) << 4;
    tx_buf[2] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        log_event("Error: SPI transfer failed");
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

double calculate_moisture_level(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        log_event("Error: ADC value out of range");
        return -1.0;
    }
    return (double)adc_value / 1023.0 * 100.0;
}

void control_pump(double moisture_level) {
    if (moisture_level < 0) {
        log_event("Error: Invalid moisture level");
        return;
    }

    if (moisture_level < MOISTURE_THRESHOLD) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            log_event("Pump turned ON");
        } else {
            log_event("Error: Failed to turn pump ON");
        }
    } else {
        if (gpioWrite(PUMP_GPIO, 0) == 0) {
            log_event("Pump turned OFF");
        } else {
            log_event("Error: Failed to turn pump OFF");
        }
    }
}

void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "[%s] %s\n", timestamp, message);
    fclose(fp);
}

void signal_handler(int signal) {
    keep_running = 0;
    log_event("Program terminated by signal");
    gpioWrite(PUMP_GPIO, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set pump GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(PUMP_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize pump GPIO state\n");
        gpioTerminate();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started");

    while (keep_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            double moisture_level = calculate_moisture_level(adc_value);
            if (moisture_level >= 0) {
                control_pump(moisture_level);
            }
        } else {
            log_event("Error: Failed to read ADC value");
        }
        sleep(60);
    }

    gpioWrite(PUMP_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

