#define LED_GPIO 17
#define MAX_RECONNECT_DELAY 60

static struct mosquitto *mosq = NULL;
static volatile sig_atomic_t running = 1;

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int set_led_state(int state) {
    if (gpioWrite(LED_GPIO, state) != 0) {
        log_error("Failed to write to GPIO17");
        return -1;
    }
    return 0;
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker\n");
        if (mosquitto_subscribe(m, NULL, MQTT_TOPIC, 0) != MOSQ_ERR_SUCCESS) {
            log_error("Failed to subscribe to topic");
        }
    } else {
        log_error("MQTT connection error");
    }
}

static void on_disconnect(struct mosquitto *m, void *userdata, int rc) {
    (void)m; (void)userdata;
    if (rc != 0) {
        log_error("MQTT disconnected unexpectedly");
    }
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m; (void)userdata;
    if (message->payloadlen <= 0) {
        log_error("Empty payload received");
        return;
    }

    cJSON *root = cJSON_Parse(message->payload);
    if (!root) {
        log_error("Failed to parse JSON payload");
        return;
    }

    cJSON *led_state = cJSON_GetObjectItemCaseSensitive(root, "led_state");
    if (!led_state || !cJSON_IsBool(led_state)) {
        log_error("Invalid payload: missing or non-boolean led_state");
        cJSON_Delete(root);
        return;
    }

    int state = cJSON_GetBool(led_state) ? 1 : 0;
    if (set_led_state(state) != 0) {
        log_error("Failed to set LED state");
    } else {
        printf("LED set to %s\n", state ? "ON" : "OFF");
    }

    cJSON_Delete(root);
}

static void reconnect_attempt(int delay_seconds) {
    printf("Reconnecting in %d seconds...\n", delay_seconds);
    sleep(delay_seconds);
    if (mosquitto_reconnect(mosq) != MOSQ_ERR_SUCCESS) {
        log_error("Reconnect attempt failed");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        log_error("pigpio initialization failed");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        log_error("Failed to set GPIO17 as output");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_led_state(0) != 0) {
        log_error("Failed to initialize LED state");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create mosquitto instance");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to start MQTT loop");
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int reconnect_delay = 1;
    while (running) {
        rc = mosquitto_loop(mosq, 1000, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("MQTT loop error");
            if (reconnect_delay < MAX_RECONNECT_DELAY) {
                reconnect_attempt(reconnect_delay);
                reconnect_delay *= 2;
            } else {
                reconnect_delay = MAX_RECONNECT_DELAY;
            }
        }
    }

    printf("Shutting down...\n");
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();

    set_led_state(0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

