#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "/dev/gpiochip0"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE "/var/log/vibration_shutdown.log"
#define CONSUMER "vibration-monitor"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s: %s\n", timestamp, message) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open(" GPIO_CHIP_NAME ")");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line()");
        goto cleanup_chip;
    }

    if (gpiod_line_request_falling_edge_events(line, CONSUMER) < 0) {
        perror("gpiod_line_request_falling_edge_events()");
        goto cleanup_chip;
    }

    printf("Vibration monitoring started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);

    while (program_running) {
        struct timespec ts = { 1, 0 }; /* 1-second timeout so we can check program_running */
        int rv = gpiod_line_event_wait(line, &ts);

        if (rv < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("gpiod_line_event_wait()");
            break;
        }

        if (rv == 0) {
            /* Timeout, no event — loop back and check program_running */
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            perror("gpiod_line_event_read()");
            continue;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            printf("Vibration detected! Shutting down...\n");
            fflush(stdout);

            if (log_event("Vibration detected! Shutting down...") < 0) {
                fprintf(stderr, "Warning: failed to log event.\n");
            }

            int rc = system("sudo shutdown -h now");
            if (rc == -1) {
                perror("system()");
            }
            break;
        }
    }

    ret = EXIT_SUCCESS;

    gpiod_line_release(line);

cleanup_chip:
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("Vibration monitoring stopped.\n");
    }

    return ret;
}

