#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define ADC_CHANNEL 0
#define VREF 3.3f
#define ADC_RESOLUTION 1024.0f
#define TEMP_SCALE 100.0f
#define BUFFER_SIZE 120
#define LOG_INTERVAL 5
#define LOG_FILE "temp_log.dat"

static int spi_handle = -1;
static float temp_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char rx[3] = {0};
    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_temperature(int adc_value) {
    float voltage = (float)adc_value * VREF / ADC_RESOLUTION;
    return voltage * TEMP_SCALE;
}

static void log_temperature(float temperature) {
    printf("Temperature: %.2f °C\n", temperature);
}

static void update_circular_buffer(float temperature) {
    temp_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static int write_buffer_to_file(void) {
    FILE *fp = fopen(LOG_FILE, "wb+");
    if (!fp) {
        fprintf(stderr, "Error opening file %s for writing\n", LOG_FILE);
        return -1;
    }
    size_t written = fwrite(temp_buffer, sizeof(float), BUFFER_SIZE, fp);
    if (written != BUFFER_SIZE) {
        fprintf(stderr, "Error writing to file %s (wrote %zu of %d)\n", LOG_FILE, written, BUFFER_SIZE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");
    while (running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed, skipping this cycle\n");
        } else {
            float temperature = adc_to_temperature(adc_value);
            log_temperature(temperature);
            update_circular_buffer(temperature);
            if (write_buffer_to_file() != 0) {
                fprintf(stderr, "Warning: file write failed, continuing\n");
            }
        }
        for (int i = 0; i < LOG_INTERVAL && running; i++) {
            sleep(1);
        }
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Temperature monitoring stopped.\n");
    return 0;
}

