        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_temperature(int adc_value) {
    float voltage = (float)adc_value * VREF / ADC_RESOLUTION;
    return voltage * TEMP_SCALE;
}

static void log_temperature(float temperature) {
    printf("Temperature: %.2f °C\n", temperature);
}

static void update_circular_buffer(float temperature) {
    temp_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static int write_buffer_to_file(void) {
    FILE *fp = fopen(LOG_FILE, "wb+");
    if (!fp) {
        fprintf(stderr, "Error opening file %s for writing\n", LOG_FILE);
        return -1;
    }
    size_t written = fwrite(temp_buffer, sizeof(float), BUFFER_SIZE, fp);
    if (written != BUFFER_SIZE) {
        fprintf(stderr, "Error writing to file %s (wrote %zu of %d)\n", LOG_FILE, written, BUFFER_SIZE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");
    while (running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed, skipping this cycle\n");
        } else {
            float temperature = adc_to_temperature(adc_value);
            log_temperature(temperature);
            update_circular_buffer(temperature);
            if (write_buffer_to_file() != 0) {
                fprintf(stderr, "Warning: file write failed, continuing\n");
            }
        }
        for (int i = 0; i < LOG_INTERVAL && running; i++) {
            sleep(1);
        }
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Temperature monitoring stopped.\n");
    return 0;
}

