#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define MCP3008_CHANNEL 0
#define MCP4725_ADDR 0x62
#define DAC_VREF 3.3
#define TEMP_MIN 0.0
#define TEMP_MAX 50.0
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 500000
#define MAX_SPI_RETRIES 3
#define MAX_I2C_RETRIES 3

static int spi_handle = -1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    for (int attempt = 0; attempt < MAX_SPI_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %d\n", attempt + 1, MAX_SPI_RETRIES, ret);
        gpioDelay(10000);
    }
    return -1;
}

static int write_mcp4725(int value) {
    if (value < 0 || value > 4095) {
        fprintf(stderr, "Invalid DAC value: %d\n", value);
        return -1;
    }

    unsigned char tx[3] = { 0x40, (unsigned char)(value >> 4), (unsigned char)(value & 0x0F) };
    unsigned char rx[3] = { 0 };

    for (int attempt = 0; attempt < MAX_I2C_RETRIES; attempt++) {
        int ret = i2cWriteDevice(i2c_handle, (char *)tx, 3);
        if (ret == 0) {
            return 0;
        }
        fprintf(stderr, "I2C write failed (attempt %d/%d): %d\n", attempt + 1, MAX_I2C_RETRIES, ret);
        gpioDelay(10000);
    }
    return -1;
}

static float adc_to_voltage(int adc_value) {
    return (float)adc_value * DAC_VREF / 4095.0;
}

static float voltage_to_temperature(float voltage) {
    return (voltage - 0.5) * 100.0;
}

static int temperature_to_dac_value(float temperature) {
    if (temperature < TEMP_MIN) temperature = TEMP_MIN;
    if (temperature > TEMP_MAX) temperature = TEMP_MAX;
    float ratio = (temperature - TEMP_MIN) / (TEMP_MAX - TEMP_MIN);
    return (int)(ratio * 4095.0);
}

