                fprintf(stderr, "Error converting ADC value for sensor %d\n", i);
                continue;
            }

            log_data(log_file, i + 1, moisture);
        }

        if (!terminate) {
            gpioDelay(SLEEP_INTERVAL_SEC * 1000000);
        }
    }

    printf("\nCleaning up and exiting...\n");
    cleanup();
    return 0;
}

