#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define DELAY_MS 1000

static const unsigned int relay_pins[NUM_RELAYS] = {17, 22, 23, 24};
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[NUM_RELAYS];
static volatile sig_atomic_t keep_running = 1;

static void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", relay_pins[i]);
            return -1;
        }

        if (gpiod_line_request_output(relay_lines[i], "relay_sequencer", 0) < 0) {
            perror("gpiod_line_request_output");
            return -1;
        }
    }
    return 0;
}

static void deactivate_all_relays(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 0);
        }
    }
}

static void release_gpio(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_release(relay_lines[i]);
            relay_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() < 0) {
        release_gpio();
        return EXIT_FAILURE;
    }

    printf("Relay sequencer started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        for (int i = 0; i < NUM_RELAYS && keep_running; i++) {
            if (gpiod_line_set_value(relay_lines[i], 1) < 0) {
                perror("gpiod_line_set_value (activate)");
                break;
            }
            usleep(DELAY_MS * 1000);
            if (gpiod_line_set_value(relay_lines[i], 0) < 0) {
                perror("gpiod_line_set_value (deactivate)");
                break;
            }
            if (i < NUM_RELAYS - 1 && keep_running) {
                usleep(DELAY_MS * 1000);
            }
        }
    }

    deactivate_all_relays();
    release_gpio();
    printf("Relay sequencer stopped.\n");
    return EXIT_SUCCESS;
}

