            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(10000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

