#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* GPIO pin assignments */
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* Mode 0, active-low CE */

/* Rain sensor channel on MCP3008 */
#define RAIN_SENSOR_CHANNEL 0

/* Motor PWM parameters */
#define PWM_RANGE 255
#define PWM_DUTY  150

/* Rain threshold (0-10 scale) */
#define RAIN_THRESHOLD 5

/* Log file path */
#define LOG_FILE "rain_log.txt"

/* Global state */
static volatile sig_atomic_t program_running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown                                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Stop the motor immediately (safe state)                            */
/* ------------------------------------------------------------------ */
static void motor_stop(void)
{
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, 0);
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 single-ended channel (0-7)                             */
/* Returns 0-1023 on success, -1 on SPI transfer error.                */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (single-ended + channel)
     *   tx[2] = 0x00                       (don't care)
     * Result: 10-bit value in rx[1] low 2 bits + rx[2]
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC value (0-1023) to rain level (0-10).                     */
/* Grove rain sensor: higher voltage = drier, so ADC 1023 -> level 0,  */
/* ADC 0 -> level 10.                                                */
/* ------------------------------------------------------------------ */
static int adc_to_rain_level(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;

    return (int)(((float)adc_value / 1023.0f) * 10.0f);
}

/* ------------------------------------------------------------------ */
/* Drive motor forward (close window)                                 */
/* ------------------------------------------------------------------ */
static void motor_forward(void)
{
    gpioWrite(MOTOR_IN1, 1);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, PWM_DUTY);
}

/* ------------------------------------------------------------------ */
/* Drive motor reverse (open window)                                   */
/* ------------------------------------------------------------------ */
static void motor_reverse(void)
{
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 1);
    gpioPWM(MOTOR_ENA, PWM_DUTY);
}

/* ------------------------------------------------------------------ */
/* Log a timestamped rain reading to the log file.                     */
/* Returns 0 on success, -1 on write/flush failure.                    */
/* ------------------------------------------------------------------ */
static int log_rain_reading(int rain_level)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources                                               */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    motor_stop();

    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio, SPI, GPIO, PWM, and log file.                    */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int initialize(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    /* Configure motor control pins as outputs */
    if (gpioSetMode(MOTOR_IN1, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_IN2, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_ENA, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for motor pins\n");
        gpioTerminate();
        return -1;
    }

    /* Set PWM range and start with motor stopped */
    if (gpioSetPWMrange(MOTOR_ENA, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return -1;
    }
    gpioPWM(MOTOR_ENA, 0);

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        spiClose(spi_handle);
        spi_handle = -1;
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main loop                                                            */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
    }

    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    int window_closed = 0;   /* 0 = open, 1 = closed */

    while (program_running) {
        int adc_value = read_mcp3008(RAIN_SENSOR_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: failed to read rain sensor\n");
        } else {
            int rain_level = adc_to_rain_level(adc_value);

            if (log_rain_reading(rain_level) != 0) {
                fprintf(stderr, "Warning: logging failed, continuing\n");
            }

            printf("Rain Level: %d (ADC: %d)\n", rain_level, adc_value);

            if (rain_level >= RAIN_THRESHOLD) {
                if (!window_closed) {
                    printf("Rain detected! Closing window...\n");
                    motor_forward();
                    window_closed = 1;
                }
            } else {
                if (window_closed) {
                    printf("Rain stopped. Opening window...\n");
                    motor_reverse();
                    window_closed = 0;
                }
            }
        }

        /* Sleep 1 second, but wake early if a signal arrives */
        for (int i = 0; i < 10 && program_running; i++) {
            gpioDelay(100000);  /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

