#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define MIC_ADC_PIN 26
#define LED_PIN 16
#define THRESHOLD 700
#define DEBOUNCE_MS 50
#define LED_ON_MS 500
#define SAMPLE_DELAY_US 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int pin) {
    int adc_value = 0;
    int i;

    for (i = 0; i < 10; i++) {
        gpioSetMode(pin, PI_OUTPUT);
        gpioWrite(pin, 0);
        gpioDelay(1);
        gpioSetMode(pin, PI_INPUT);
        gpioDelay(10);
        adc_value += gpioRead(pin);
    }
    return (adc_value * 1023) / 10;
}

static void trigger_led(int pin, int duration_ms) {
    gpioWrite(pin, 1);
    gpioDelay(duration_ms * 1000);
    gpioWrite(pin, 0);
}

static void log_detection(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Clap detected!\n", timestamp);
    } else {
        printf("[unknown time] Clap detected!\n");
    }
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MIC_ADC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set MIC_ADC_PIN %d as input.\n", MIC_ADC_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set LED_PIN %d as output.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler.\n");
    }

    printf("Clap detector running. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc(MIC_ADC_PIN);

        if (adc_value > THRESHOLD) {
            trigger_led(LED_PIN, LED_ON_MS);
            log_detection();
            gpioDelay(DEBOUNCE_MS * 1000);
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

