    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Clap detected!\n", timestamp);
    } else {
        printf("[unknown time] Clap detected!\n");
    }
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MIC_ADC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set MIC_ADC_PIN %d as input.\n", MIC_ADC_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set LED_PIN %d as output.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler.\n");
    }

    printf("Clap detector running. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc(MIC_ADC_PIN);

        if (adc_value > THRESHOLD) {
            trigger_led(LED_PIN, LED_ON_MS);
            log_detection();
            gpioDelay(DEBOUNCE_MS * 1000);
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

