#include <errno.h>

#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 200.0
#define LOG_FILE "distance_log.txt"
#define VOLTAGE_HIGH 3.3
#define VOLTAGE_LOW 0.0
#define A 26.0
#define B -6.0
#define RETRY_DELAY 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int gpio_export(int pin) {
    char buf[4];
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening export: %s\n", strerror(errno));
        return -1;
    }
    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Error writing to export: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_unexport(int pin) {
    char buf[4];
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening unexport: %s\n", strerror(errno));
        return -1;
    }
    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Error writing to unexport: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(int pin, const char *dir) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening direction: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, dir, strlen(dir)) < 0) {
        fprintf(stderr, "Error writing direction: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_read(int pin) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening value: %s\n", strerror(errno));
        return -1;
    }
    char val = 0;
    if (read(fd, &val, 1) < 0) {
        fprintf(stderr, "Error reading value: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return (val == '1') ? 1 : 0;
}

static double read_distance(void) {
    if (gpio_read(GPIO_PIN) < 0) {
        return -1.0;
    }
    int digital = gpio_read(GPIO_PIN);
    double voltage = (digital == 1) ? VOLTAGE_HIGH : VOLTAGE_LOW;
    return (A / voltage) + B;
}

static void log_distance(double distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Distance: %.2f mm\n", timestamp, distance);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpio_export(GPIO_PIN) < 0) {
        return EXIT_FAILURE;
    }
    usleep(100000);
    if (gpio_set_direction(GPIO_PIN, "in") < 0) {
        gpio_unexport(GPIO_PIN);
        return EXIT_FAILURE;
    }

    while (running) {
        double distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, retrying in %d seconds...\n", RETRY_DELAY);
            sleep(RETRY_DELAY);
            continue;
