#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

/*
 * Raspberry Pi Zero W – DRV5055VA Hall-effect sensor via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO 11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO 9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO 10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO 8  (SPI0 CE0)
 *   MCP3008 CH0  -> DRV5055VA OUT
 *   DRV5055VA VCC -> 3.3 V
 *   DRV5055VA GND -> GND
 *   LED anode    -> GPIO 21 (with ~330 Ω series resistor to GND)
 *
 * DRV5055VA ratiometric characteristics (3.3 V supply):
 *   Quiescent output = VCC / 2 = 1.65 V
 *   Sensitivity = 2.5 * VCC / 5 = 1.65 mV/mT
 *   Field (mT) = (V_out - 1.65) * 1000 / 1.65
 */

#define SPI_CHANNEL    0          /* CE0 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC */
#define VREF           3.3        /* Reference voltage */

#define LED_GPIO       21
#define THRESHOLD_MT   10.0

#define LOG_FILE       "magnetic_log.txt"
#define SAMPLE_US     100000      /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single-ended channel from the MCP3008.
 * Returns 0-1023 on success, -1 on SPI error. */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  -> SGL/DIFF=1, D2 D1 D0 = channel
     *   Byte 2: 0x00  (don't care, clocks out low 2 bits)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9 b8] in the low nibble
     *   rx[2] = b7..b0
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
static float adc_to_voltage(int adc_value)
{
    return (float)adc_value * VREF / (float)ADC_MAX_VALUE;
}

/* ------------------------------------------------------------------ */
/* DRV5055VA field strength (mT) from output voltage.
 *   quiescent = VCC / 2 = 1.65 V
 *   sensitivity = 1.65 mV/mT
 *   field_mT = (V_out - 1.65) * 1000 / 1.65 */
static float voltage_to_field_mt(float voltage)
{
    float quiescent = VREF / 2.0f;
    float sensitivity_mv_per_mt = 1.65f;
    return (voltage - quiescent) * 1000.0f / sensitivity_mv_per_mt;
}

/* ------------------------------------------------------------------ */
static void log_reading(float field_mt)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, %.2f mT\n", ts, field_mt);
    } else {
        fprintf(fp, "(unknown time), %.2f mT\n", field_mt);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
static void control_led(float field_mt)
{
    int level = (field_mt > THRESHOLD_MT) ? 1 : 0;
    if (gpioWrite(LED_GPIO, level) < 0) {
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed\n", LED_GPIO, level);
    }
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- LED GPIO setup --------------------------------------------- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* --- SPI open --------------------------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen(CE%d, %d, 0) failed (handle %d)\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handling -------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("DRV5055VA via MCP3008 logging started.  Ctrl+C to exit.\n");

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        int adc = read_mcp3008(ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read error – skipping sample\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        float voltage = adc_to_voltage(adc);
        float field_mt = voltage_to_field_mt(voltage);

        log_reading(field_mt);
        control_led(field_mt);

        printf("ADC=%4d  V=%.3f  field=%.2f mT  LED=%s\n",
               adc, voltage, field_mt,
               (field_mt > THRESHOLD_MT) ? "ON" : "OFF");

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

