#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * Raspberry Pi Zero W – MLX91211 current sensor via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> Pi 5V  (pin 2)
 *   MCP3008 VREF -> Pi 5V  (pin 2)
 *   MCP3008 AGND -> Pi GND (pin 6)
 *   MCP3008 DGND -> Pi GND (pin 6)
 *   MCP3008 CLK  -> Pi GPIO11 (SCLK, pin 23)
 *   MCP3008 DOUT -> Pi GPIO9  (MISO, pin 21)
 *   MCP3008 DIN  -> Pi GPIO10 (MOSI, pin 19)
 *   MCP3008 CS   -> Pi GPIO8  (CE0,  pin 24)
 *   MCP3008 CH0  -> MLX91211 analog output
 *   MLX91211 VDD -> Pi 5V  (pin 2)
 *   MLX91211 GND -> Pi GND (pin 6)
 *
 * MLX91211 output is ratiometric: 2.5 V at 0 A, 5.0 V at +50 A.
 *
 * Build:  gcc -O2 -Wall -o current_monitor current_monitor.c -lpigpio -lrt
 * Run:    sudo ./current_monitor
 */

#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_CODE   1023       /* 10-bit ADC */
#define ADC_VREF       5.0        /* VREF tied to 5V rail */
#define ADC_VZERO      0.0
#define ADC_VFULL      ADC_VREF
#define CURRENT_FULL   50.0       /* A */
#define CURRENT_ZERO   0.0
#define LOG_FILE       "current_log.txt"
#define SAMPLE_US      100000     /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single-ended channel from the MCP3008.
 * Returns 0-1023 on success, -1 on SPI transfer error. */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   tx[0] = 0x01                        start bit
     *   tx[1] = (0x08 | (channel << 4))     single-ended + channel
     *   tx[2] = 0x00                        padding
     * Result: ((rx[1] & 0x03) << 8) | rx[2]
     */
    char tx[3] = { 0x01, (char)(0x08 | (channel << 4)), 0x00 };
    char rx[3] = { 0, 0, 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    int code = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return code;
}

/* ------------------------------------------------------------------ */
static float adc_to_voltage(int code)
{
    return ADC_VZERO + ((float)code / (float)ADC_MAX_CODE) * (ADC_VFULL - ADC_VZERO);
}

/* ------------------------------------------------------------------ */
static float voltage_to_current(float v)
{
    if (v < ADC_VZERO) v = ADC_VZERO;
    if (v > ADC_VFULL) v = ADC_VFULL;
    return (v - ADC_VZERO) * (CURRENT_FULL - CURRENT_ZERO) /
           (ADC_VFULL - ADC_VZERO);
}

/* ------------------------------------------------------------------ */
static void log_current(float current)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(g_log, "%s %.2f A\n", ts, current) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return;
    }
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- SPI init ---- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- log file ---- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen(" LOG_FILE ")");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX91211 current monitor started. Press Ctrl+C to stop.\n");

    /* ---- main loop ---- */
    while (g_running) {
        int code = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (code < 0) {
            gpioDelay(SAMPLE_US);
            continue;
        }

        float v = adc_to_voltage(code);
        float i = voltage_to_current(v);

        if (v < ADC_VZERO || v > ADC_VFULL) {
            fprintf(stderr, "Warning: voltage %.3f V out of range [%.1f, %.1f]\n",
                    v, ADC_VZERO, ADC_VFULL);
            gpioDelay(SAMPLE_US);
            continue;
        }

        log_current(i);
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

