#define DEBOUNCE_DELAY_US 200000 /* 200 ms */
#define IMAGE_WIDTH  1280
#define IMAGE_HEIGHT 720
#define IMAGE_QUALITY 85
#define IMAGE_DIR "/home/pi/security_cam"
#define MAX_PATH 512

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int ensure_directory(const char *path)
{
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode))
            return 0;
        syslog(LOG_ERR, "Path '%s' exists but is not a directory", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        syslog(LOG_ERR, "Failed to create directory '%s': %m", path);
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename)
{
    char command[MAX_PATH];
    int needed = snprintf(command, sizeof(command),
                          "libcamera-still -o '%s' --width %d --height %d --quality %d --nopreview 2>/dev/null",
                          filename, IMAGE_WIDTH, IMAGE_HEIGHT, IMAGE_QUALITY);
    if (needed < 0 || (size_t)needed >= sizeof(command)) {
        syslog(LOG_ERR, "Command buffer too small");
        return -1;
    }

    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork() failed: %m");
        return -1;
    }

    if (pid == 0) {
        /* Child: redirect stdout/stderr to /dev/null and exec */
        freopen("/dev/null", "w", stdout);
        freopen("/dev/null", "w", stderr);
        execvp("libcamera-still", NULL);
        _exit(127);
    }

    /* Parent: wait for child */
    int status = 0;
    while (waitpid(pid, &status, 0) < 0) {
        if (errno == EINTR) {
            if (!g_running)
                return -1;
            continue;
        }
        syslog(LOG_ERR, "waitpid() failed: %m");
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0)
        return 0;

    syslog(LOG_ERR, "libcamera-still failed (exit status %d)",
           WIFEXITED(status) ? WEXITSTATUS(status) : -1);
    return -1;
}

static void log_event(int priority, const char *message)
{
    syslog(priority, "%s", message);
    fprintf(stderr, "%s\n", message);
}

int main(void)
{
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
