        fprintf(stderr, "Error opening device %s: %s\n", device, strerror(errno));
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", device);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", device);
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_GREY) {
        fprintf(stderr, "Device does not support grayscale format\n");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer *buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        fprintf(stderr, "Error allocating buffer array\n");
        close(fd);
        return EXIT_FAILURE;
    }

    for (unsigned int i = 0; i < req.count; ++i) {
        memset(buffers + i, 0, sizeof(*buffers));
        buffers[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buffers[i].memory = V4L2_MEMORY_MMAP;
        buffers[i].index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, buffers + i) == -1) {
            fprintf(stderr, "Error querying buffer %u: %s\n", i, strerror(errno));
            free(buffers);
            close(fd);
            return EXIT_FAILURE;
        }

        buffers[i].length = buffers[i].m.buf.length;

        if (xioctl(fd, VIDIOC_QBUF, buffers + i) == -1) {
            fprintf(stderr, "Error queueing buffer %u: %s\n", i, strerror(errno));
            free(buffers);
            close(fd);
            return EXIT_FAILURE;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        free(buffers);
        close(fd);
        return EXIT_FAILURE;
    }

    int frame_number = 0;
    fd_set fds;
    struct timeval tv;

    while (!stop_flag) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2;
        tv.tv_usec = 0;

        int r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r == -1) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error in select(): %s\n", strerror(errno));
            break;
        }

        if (r == 0) {
            fprintf(stderr, "select() timeout\n");
            continue;
        }

        if (capture_frame(fd, buffers[0].m.buf.start, buffers[0].length, &frame_number) == -1) {
            break;
        }
    }

    if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
    }

    for (unsigned int i = 0; i < req.count; ++i) {
        if (buffers[i].m.buf.start && buffers[i].m.buf.start != MAP_FAILED) {
            munmap(buffers[i].m.buf.start, buffers[i].length);
        }
    }

    free(buffers);
    close(fd);

    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

