#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH  1920
#define IMAGE_HEIGHT 1080
#define NUM_BUFFERS  4
#define OUTPUT_FILE  "image.jpg"

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;
    void *buffers[NUM_BUFFERS];
    size_t lengths[NUM_BUFFERS];
    unsigned int n_buffers = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("open(" DEVICE_NAME ")");
        return EXIT_FAILURE;
    }

    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        goto cleanup;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }

    if (fmt.fmt.pix.width != IMAGE_WIDTH || fmt.fmt.pix.height != IMAGE_HEIGHT) {
        fprintf(stderr, "Warning: device set %ux%u, requested %ux%u\n",
                fmt.fmt.pix.width, fmt.fmt.pix.height,
                IMAGE_WIDTH, IMAGE_HEIGHT);
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory (got %u)\n", req.count);
        goto cleanup;
    }

    for (n_buffers = 0; n_buffers < req.count; n_buffers++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            goto cleanup;
        }

        buffers[n_buffers] = mmap(NULL, buf.length,
                                  PROT_READ | PROT_WRITE,
                                  MAP_SHARED, fd, buf.m.offset);
        if (buffers[n_buffers] == MAP_FAILED) {
            perror("mmap");
            buffers[n_buffers] = NULL;
            goto cleanup;
        }
        lengths[n_buffers] = buf.length;
    }

    for (unsigned int i = 0; i < n_buffers; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            goto cleanup;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (g_stop) {
        fprintf(stderr, "Interrupted before frame capture\n");
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        goto cleanup;
    }

    if (buf.bytesused == 0) {
        fprintf(stderr, "No data captured (bytesused=0)\n");
        goto cleanup;
    }

    FILE *out = fopen(OUTPUT_FILE, "wb");
    if (!out) {
        perror("fopen(" OUTPUT_FILE ")");
        goto cleanup;
    }

    size_t written = fwrite(buffers[buf.index], 1, buf.bytesused, out);
    if (written != buf.bytesused) {
        perror("fwrite");
        fclose(out);
        unlink(OUTPUT_FILE);
        goto cleanup;
    }

    if (fclose(out) != 0) {
        perror("fclose");
        unlink(OUTPUT_FILE);
        goto cleanup;
    }

    printf("Image saved as %s (%u bytes)\n", OUTPUT_FILE, buf.bytesused);
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
            perror("VIDIOC_STREAMOFF");
        }
    }

    for (unsigned int i = 0; i < n_buffers; i++) {
        if (buffers[i] && buffers[i] != MAP_FAILED) {
            if (munmap(buffers[i], lengths[i]) < 0) {
                perror("munmap");
            }
        }
    }

    if (fd >= 0) {
        close(fd);
    }

    return ret;
}

