#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define BUTTON_UP_PIN 6
#define BUTTON_DOWN_PIN 7
#define BUTTON_LEFT_PIN 8
#define BUTTON_RIGHT_PIN 9

#define SERVO_MIN_DUTY 50
#define SERVO_MAX_DUTY 1000
#define SERVO_MID_DUTY 750
#define SERVO_STEP 5
#define SERVO_MIN_POS 25
#define SERVO_MAX_POS 125
#define PWM_PERIOD_NS 20000000  /* 20 ms = 50 Hz */
#define POLL_INTERVAL_US 50000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_servo_duty(struct gpiod_line *line, int duty) {
    if (duty < SERVO_MIN_DUTY) duty = SERVO_MIN_DUTY;
    if (duty > SERVO_MAX_DUTY) duty = SERVO_MAX_DUTY;

    int on_ns = (duty * PWM_PERIOD_NS) / SERVO_MAX_DUTY;
    int off_ns = PWM_PERIOD_NS - on_ns;

    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value(1)");
        return;
    }
    if (on_ns > 0) {
        struct timespec ts = { on_ns / 1000000000L, (on_ns % 1000000000L) * 1000L };
        nanosleep(&ts, NULL);
    }
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value(0)");
        return;
    }
    if (off_ns > 0) {
        struct timespec ts = { off_ns / 1000000000L, (off_ns % 1000000000L) * 1000L };
        nanosleep(&ts, NULL);
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pan_line = NULL, *tilt_line = NULL;
    struct gpiod_line *up_line = NULL, *down_line = NULL;
    struct gpiod_line *left_line = NULL, *right_line = NULL;
    int pan_pos = SERVO_MID_DUTY;
    int tilt_pos = SERVO_MID_DUTY;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    pan_line = gpiod_chip_get_line(chip, PAN_SERVO_PIN);
    tilt_line = gpiod_chip_get_line(chip, TILT_SERVO_PIN);
    up_line = gpiod_chip_get_line(chip, BUTTON_UP_PIN);
    down_line = gpiod_chip_get_line(chip, BUTTON_DOWN_PIN);
    left_line = gpiod_chip_get_line(chip, BUTTON_LEFT_PIN);
    right_line = gpiod_chip_get_line(chip, BUTTON_RIGHT_PIN);

    if (!pan_line || !tilt_line || !up_line || !down_line || !left_line || !right_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(pan_line, "pan-servo", 0) < 0) {
        perror("gpiod_line_request_output(pan)");
        goto cleanup;
    }
    if (gpiod_line_request_output(tilt_line, "tilt-servo", 0) < 0) {
        perror("gpiod_line_request_output(tilt)");
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(up_line, "button-up", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input_flags(up)");
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(down_line, "button-down", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input_flags(down)");
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(left_line, "button-left", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input_flags(left)");
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(right_line, "button-right", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input_flags(right)");
        goto cleanup;
    }

    while (running) {
        int up_val = gpiod_line_get_value(up_line);
        int down_val = gpiod_line_get_value(down_line);
        int left_val = gpiod_line_get_value(left_line);
        int right_val = gpiod_line_get_value(right_line);

        if (up_val < 0 || down_val < 0 || left_val < 0 || right_val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        if (up_val == 0) {
            tilt_pos += SERVO_STEP;
            if (tilt_pos > SERVO_MAX_POS) tilt_pos = SERVO_MAX_POS;
            set_servo_duty(tilt_line, tilt_pos);
        }
        if (down_val == 0) {
            tilt_pos -= SERVO_STEP;
            if (tilt_pos < SERVO_MIN_POS) tilt_pos = SERVO_MIN_POS;
            set_servo_duty(tilt_line, tilt_pos);
        }
        if (left_val == 0) {
            pan_pos -= SERVO_STEP;
            if (pan_pos < SERVO_MIN_POS) pan_pos = SERVO_MIN_POS;
            set_servo_duty(pan_line, pan_pos);
        }
        if (right_val == 0) {
            pan_pos += SERVO_STEP;
            if (pan_pos > SERVO_MAX_POS) pan_pos = SERVO_MAX_POS;
            set_servo_duty(pan_line, pan_pos);
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (pan_line) gpiod_line_release(pan_line);
    if (tilt_line) gpiod_line_release(tilt_line);
    if (up_line) gpiod_line_release(up_line);
    if (down_line) gpiod_line_release(down_line);
    if (left_line) gpiod_line_release(left_line);
    if (right_line) gpiod_line_release(right_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

