static void cleanup_camera(int fd, buffer_t *buffers, unsigned int n_buffers) {
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
    }
    if (buffers && n_buffers > 0) {
