        fprintf(stderr, "Frame size mismatch: %d < %d\n", yuyv_size,
                *frame_width * *frame_height * 2);
        return -1;
    }

    for (int y = 0; y < *frame_height; ++y) {
        for (int x = 0; x < *frame_width; x += 2) {
            int idx = (y * *frame_width + x) * 2;
            int rgb_idx = (y * *frame_width + x) * 3;
            unsigned char y1 = yuyv[idx];
            unsigned char u = yuyv[idx + 1];
            unsigned char y2 = yuyv[idx + 2];
            unsigned char v = yuyv[idx + 3];

