            float u_f = (float)u - 128.0f;
            float v_f = (float)v - 128.0f;

            float r1 = y1_f + 1.13983f * v_f;
            float g1 = y1_f - 0.39465f * u_f - 0.58060f * v_f;
            float b1 = y1_f + 2.03211f * u_f;

            float y2_f = (float)y2 - 16.0f;
            float r2 = y2_f + 1.13983f * v_f;
            float g2 = y2_f - 0.39465f * u_f - 0.58060f * v_f;
            float b2 = y2_f + 2.03211f * u_f;

            frame_rgb[rgb_idx] = (unsigned char)r1;
            frame_rgb[rgb_idx + 1] = (unsigned char)g1;
            frame_rgb[rgb_idx + 2] = (unsigned char)b1;
            frame_rgb[rgb_idx + 3] = (unsigned char)r2;
            frame_rgb[rgb_idx + 4] = (unsigned char)g2;
            frame_rgb[rgb_idx + 5] = (unsigned char)b2;
        }
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        return -1;
    }

