#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"

static int has_capability(unsigned int caps, unsigned int flag)
{
    return (caps & flag) == flag;
}

static void print_resolution(const struct v4l2_frmsizeenum *fs)
{
    printf("  %ux%u\n", fs->discrete_size.width, fs->discrete_size.height);
}

static void print_frame_rate(const struct v4l2_frmivalenum *fi)
{
    printf("    %u/%u\n", fi->discrete_frame_interval.numerator,
           fi->discrete_frame_interval.denominator);
}

int main(void)
{
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_frmsizeenum fs;
    struct v4l2_frmivalenum fi;
    struct v4l2_queryctrl qc;
    int ret;

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    memset(&cap, 0, sizeof(cap));
    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (!has_capability(cap.capabilities, V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s does not support video capture\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!has_capability(cap.capabilities, V4L2_CAP_READWRITE)) {
        fprintf(stderr, "%s does not support read/write I/O\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Capabilities: 0x%08x\n", cap.capabilities);

    memset(&fs, 0, sizeof(fs));
    fs.pixel_format = V4L2_PIX_FMT_UYVY;
    fs.index = 0;
    printf("Supported resolutions (UYVY):\n");
    while ((ret = ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fs)) == 0) {
        if (fs.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
            print_resolution(&fs);
        }
        fs.index++;
    }
