#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN  6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

#define SERVO_MIN_PULSE_US 1000
#define SERVO_MAX_PULSE_US 2000
#define SERVO_CENTER_US  1500
#define STEP_US          10
#define LOOP_DELAY_US    50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);

    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    if (gpioServo(PAN_SERVO_PIN, SERVO_CENTER_US) < 0) {
        fprintf(stderr, "Error: failed to start pan servo PWM.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioServo(TILT_SERVO_PIN, SERVO_CENTER_US) < 0) {
        fprintf(stderr, "Error: failed to start tilt servo PWM.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Pan-Tilt Camera Control (pigpio)\n");
    printf("  Pan servo: GPIO%d | Tilt servo: GPIO%d\n", PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("  UP: GPIO%d | DOWN: GPIO%d | LEFT: GPIO%d | RIGHT: GPIO%d\n",
           UP_BUTTON_PIN, DOWN_BUTTON_PIN, LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN);
    printf("  Center position: %d us\n", SERVO_CENTER_US);
    printf("  Press Ctrl+C to exit.\n");

    int pan_pos = SERVO_CENTER_US;
    int tilt_pos = SERVO_CENTER_US;

    while (running) {
        int up_pressed = (gpioRead(UP_BUTTON_PIN) == 0);
        int down_pressed = (gpioRead(DOWN_BUTTON_PIN) == 0);
        int left_pressed = (gpioRead(LEFT_BUTTON_PIN) == 0);
        int right_pressed = (gpioRead(RIGHT_BUTTON_PIN) == 0);

        if (up_pressed) {
            tilt_pos += STEP_US;
            if (tilt_pos > SERVO_MAX_PULSE_US) tilt_pos = SERVO_MAX_PULSE_US;
            if (gpioServo(TILT_SERVO_PIN, tilt_pos) < 0) {
                fprintf(stderr, "Warning: gpioServo failed on tilt.\n");
            }
        }
        if (down_pressed) {
            tilt_pos -= STEP_US;
            if (tilt_pos < SERVO_MIN_PULSE_US) tilt_pos = SERVO_MIN_PULSE_US;
            if (gpioServo(TILT_SERVO_PIN, tilt_pos) < 0) {
                fprintf(stderr, "Warning: gpioServo failed on tilt.\n");
            }
        }
        if (left_pressed) {
            pan_pos -= STEP_US;
            if (pan_pos < SERVO_MIN_PULSE_US) pan_pos = SERVO_MIN_PULSE_US;
            if (gpioServo(PAN_SERVO_PIN, pan_pos) < 0) {
                fprintf(stderr, "Warning: gpioServo failed on pan.\n");
            }
        }
        if (right_pressed) {
            pan_pos += STEP_US;
            if (pan_pos > SERVO_MAX_PULSE_US) pan_pos = SERVO_MAX_PULSE_US;
            if (gpioServo(PAN_SERVO_PIN, pan_pos) < 0) {
                fprintf(stderr, "Warning: gpioServo failed on pan.\n");
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

