#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <curl/curl.h>

#define PIR_GPIO 17
#define DEBOUNCE_SEC 2
#define POLL_INTERVAL_US 100000
#define CAPTURE_WIDTH 640
#define CAPTURE_HEIGHT 480
#define CAPTURE_QUALITY 85
#define CAPTURE_DIR "motion_captures"
#define MAX_FILENAME_LEN 256
#define MAX_CMD_LEN 512
#define MAX_PAYLOAD_LEN 512

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int capture_image(const char *filename) {
    char command[MAX_CMD_LEN];
    int ret = snprintf(command, sizeof(command),
        "libcamera-still -o %s -w %d -h %d -q %d --nopreview 2>/dev/null",
        filename, CAPTURE_WIDTH, CAPTURE_HEIGHT, CAPTURE_QUALITY);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error: command buffer too small\n");
        return -1;
    }

    pid_t pid = fork();
    if (pid < 0) {
        fprintf(stderr, "Error: fork() failed: %s\n", strerror(errno));
        return -1;
    }

    if (pid == 0) {
        execl("/bin/sh", "sh", "-c", command, (char *)NULL);
        perror("execl() failed");
        _exit(127);
    }

    int status = 0;
    if (waitpid(pid, &status, 0) < 0) {
        fprintf(stderr, "Error: waitpid() failed: %s\n", strerror(errno));
        return -1;
    }

    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: libcamera-still failed (status=0x%04x)\n", status);
        return -1;
    }

    return 0;
}

static int create_timestamped_filename(char *filename, size_t size) {
    time_t rawtime;
    struct tm timeinfo;
    struct timespec ts;

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error: clock_gettime() failed: %s\n", strerror(errno));
        return -1;
    }

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);

    int ret = snprintf(filename, size, "%s/motion_%04d%02d%02d_%02d%02d%02d_%06ld.jpg",
        CAPTURE_DIR,
        timeinfo.tm_year + 1900, timeinfo.tm_mon + 1, timeinfo.tm_mday,
        timeinfo.tm_hour, timeinfo.tm_min, timeinfo.tm_sec, ts.tv_nsec / 1000);

    if (ret < 0 || (size_t)ret >= size) {
        fprintf(stderr, "Error: filename buffer too small\n");
        return -1;
    }
    return 0;
}

static int send_data_to_server(const char *server_ip, int server_port, const char *filename,
                               int motion_status, int gpio_pin) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Error: curl_easy_init() failed\n");
        return -1;
    }

    char payload[MAX_PAYLOAD_LEN];
    int ret = snprintf(payload, sizeof(payload),
        "{\"filename\":\"%s\",\"timestamp\":\"%ld.%06ld\",\"motion_status\":%d,\"gpio_pin\":%d}",
        filename, (long)time(NULL), (long)(clock() / 1000), motion_status, gpio_pin);

    if (ret < 0 || (size_t)ret >= sizeof(payload)) {
        fprintf(stderr, "Error: payload buffer too small\n");
        curl_easy_cleanup(curl);
        return -1;
    }

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        fprintf(stderr, "Error: curl_slist_append() failed\n");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, "http://");
    curl_easy_setopt(curl, CURLOPT_URL, server_ip);
    curl_easy_setopt(curl, CURLOPT_PORT, &server_port);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, payload);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);
    curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Error: curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        return -1;
    }

    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    if (http_code != 200) {
        fprintf(stderr, "Warning: HTTP response code %ld\n", http_code);
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *server_ip = argv[1];
    int server_port = atoi(argv[2]);
    if (server_port <= 0 || server_port > 65535) {
        fprintf(stderr, "Error: Invalid port number: %s\n", argv[2]);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode() failed for GPIO %d\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown() failed for GPIO %d\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (curl_global_init(CURL_GLOBAL_DEFAULT) != CURLE_OK) {
        fprintf(stderr, "Error: curl_global_init() failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction() failed: %s\n", strerror(errno));
        curl_global_cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mkdir(CAPTURE_DIR, 0755) != 0 && errno != EEXIST) {
        fprintf(stderr, "Error: mkdir(%s) failed: %s\n", CAPTURE_DIR, strerror(errno));
        curl_global_cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", PIR_GPIO);

    while (running) {
        int motion_detected = gpioRead(PIR_GPIO);
        if (motion_detected < 0) {
            fprintf(stderr, "Error: gpioRead() failed for GPIO %d\n", PIR_GPIO);
            break;
        }

        if (motion_detected) {
            char filename[MAX_FILENAME_LEN];
            if (create_timestamped_filename(filename, sizeof(filename)) != 0) {
                fprintf(stderr, "Error: Failed to create filename\n");
                break;
            }

            if (capture_image(filename) != 0) {
                fprintf(stderr, "Error: Failed to capture image\n");
                break;
            }

            if (send_data_to_server(server_ip, server_port, filename, 1, PIR_GPIO) != 0) {
                fprintf(stderr, "Error: Failed to send data to server\n");
            }

            printf("Motion detected on GPIO %d. Image saved: %s\n", PIR_GPIO, filename);

            time_t last_motion_time = time(NULL);
            while (running && (time(NULL) - last_motion_time) < DEBOUNCE_SEC) {
                gpioDelay(POLL_INTERVAL_US);
            }
        } else {
            gpioDelay(POLL_INTERVAL_US);
        }
    }

    printf("\nShutting down...\n");
    curl_global_cleanup();
    gpioTerminate();
    return EXIT_SUCCESS;
}

