#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define PIR_PIN 17
#define GPIO_CHIP "/dev/gpiochip0"
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_MS 50
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "[%s] %s\n", ts, message);
    } else {
        fprintf(fp, "[unknown] %s\n", message);
    }
    fclose(fp);
}

static int capture_image(const char *filename) {
    char command[512];
    int ret = snprintf(command, sizeof(command),
        "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview 2>> %s",
        filename, LOG_FILE);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        log_event("Error: command buffer too small");
        return -1;
    }
    int status = system(command);
    if (status == -1) {
        log_event("Error: system() failed to launch libcamera-still");
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        char msg[256];
        snprintf(msg, sizeof(msg), "libcamera-still exited with status %d", WEXITSTATUS(status));
        log_event(msg);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        log_event("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        perror("gpiod_chip_get_line");
        log_event("Failed to get PIR GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_falling_edge_events(pir_line, "pir-motion") < 0) {
        perror("gpiod_line_request_falling_edge_events");
        log_event("Failed to request falling-edge events on PIR line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_event("Motion detection system started");

    while (running) {
        struct timespec ts = { .tv_sec = POLL_TIMEOUT_MS / 1000,
                               .tv_nsec = (POLL_TIMEOUT_MS % 1000) * 1000000L };
        int ev = gpiod_line_event_wait(pir_line, &ts);
        if (ev < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_wait");
            log_event("Error waiting for PIR event");
            break;
        }
        if (ev == 0) continue;

        struct gpiod_line_event event;
        if (gpiod_line_event_read(pir_line, &event) < 0) {
            perror("gpiod_line_event_read");
            log_event("Error reading PIR event");
            continue;
        }

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        struct timespec last_event = event.ts;

        if (now.tv_sec - last_event.tv_sec > 0) {
            log_event("Motion detected");
        } else if (now.tv_nsec - last_event.tv_nsec > DEBOUNCE_MS * 1000000L) {
            log_event("Motion detected (debounced)");
        }

        time_t rawtime = time(NULL);
        struct tm tm;
        if (localtime_r(&rawtime, &tm)) {
            char filename[128];
            snprintf(filename, sizeof(filename), "%s/%04d%02d%02d_%02d%02d%02d_000.jpg",
                     IMAGE_DIR, tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                     tm.tm_hour, tm.tm_min, tm.tm_sec);
            if (capture_image(filename) == 0) {
                char msg[256];
                snprintf(msg, sizeof(msg), "Image captured: %s", filename);
                log_event(msg);
            } else {
                log_event("Failed to capture image");
            }
        } else {
            log_event("Failed to get local time");
        }
    }

    gpiod_line_release(pir_line);
    gpiod_chip_close(chip);
    log_event("Motion detection system stopped");
    return EXIT_SUCCESS;
}

