#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define ANGLE_INCREMENT 5
#define NEUTRAL_ANGLE 90
#define PWM_FREQUENCY 50
#define DELAY_MS 100

static volatile int keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int angle_to_pulse_width(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle %d out of range [%d, %d]\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }
    return MIN_PULSE_WIDTH + (int)((float)(angle - MIN_ANGLE) / (MAX_ANGLE - MIN_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));
}

int set_servo_angle(int pin, int angle) {
    int pulse_width = angle_to_pulse_width(angle);
    if (pulse_width < 0) return -1;
    if (gpioServo(pin, pulse_width) != 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d with pulse %d\n", pin, pulse_width);
        return -1;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, handle_signal);

    int pan_angle = NEUTRAL_ANGLE;
    int tilt_angle = NEUTRAL_ANGLE;

    printf("Pan-Tilt Camera Mount (pigpio)\n");
    printf("Controls: up/down/left/right (arrow keys), q/Ctrl+C to quit\n");

    while (keep_running) {
        int c = getchar();
        if (c == 'q' || c == 'Q' || c == '\n') {
            break;
        }

        int new_pan = pan_angle;
        int new_tilt = tilt_angle;

        switch (c) {
            case 'a':
                new_pan = pan_angle - ANGLE_INCREMENT;
                if (new_pan < MIN_ANGLE) new_pan = MIN_ANGLE;
                break;
            case 'd':
                new_pan = pan_angle + ANGLE_INCREMENT;
                if (new_pan > MAX_ANGLE) new_pan = MAX_ANGLE;
                break;
            case 'w':
                new_tilt = tilt_angle + ANGLE_INCREMENT;
                if (new_tilt > MAX_ANGLE) new_tilt = MAX_ANGLE;
                break;
            case 's':
                new_tilt = tilt_angle - ANGLE_INCREMENT;
                if (new_tilt < MIN_ANGLE) new_tilt = MIN_ANGLE;
                break;
            default:
                break;
        }

        if (set_servo_angle(PAN_SERVO_PIN, new_pan) != 0) {
            fprintf(stderr, "Warning: failed to set pan servo\n");
        }
        if (set_servo_angle(TILT_SERVO_PIN, new_tilt) != 0) {
            fprintf(stderr, "Warning: failed to set tilt servo\n");
        }

        pan_angle = new_pan;
        tilt_angle = new_tilt;

        gpioDelay(DELAY_MS * 1000);
    }

    // Return to neutral position
    set_servo_angle(PAN_SERVO_PIN, NEUTRAL_ANGLE);
    set_servo_angle(TILT_SERVO_PIN, NEUTRAL_ANGLE);

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return 0;
}

