}

static int ssd1306_data(const unsigned char *data, int len) {
    char buf[1 + 128];
    if (len > 128) len = 128;
    buf[0] = 0x40;
    memcpy(buf + 1, data, len);
    if (i2cWriteDevice(i2c_handle, buf, len + 1) != 0) {
