#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define PULSES_PER_LITER 450.0
#define LCD_I2C_BUS 1
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define LCD_BACKLIGHT 0x08
#define LCD_ENABLE 0x04
#define LCD_RW 0x02
#define LCD_RS 0x01
#define LCD_EN 0x04
#define LCD_BL 0x08
#define LCD_RS_VAL 0x01
#define LCD_BL_VAL 0x08

// Global variables
static volatile int pulse_count = 0;
static volatile double volume_total = 0.0;
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);
void lcd_byte(int bits, int mode);
void lcd_string(char *str);
void lcd_clear(void);
void lcd_set_cursor(int row, int col);
void lcd_print_flow_rate(double flow_rate);
void lcd_print_volume(double volume);
void lcd_update(double flow_rate, double volume);

// Pulse callback function
void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_count++;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Function to send a byte to the LCD
void lcd_byte(int bits, int mode) {
    int i;
    int data_pin = LCD_RS | LCD_EN | LCD_BL;
    int rs_pin = LCD_RS;
    int en_pin = LCD_EN;
    int bl_pin = LCD_BL;

    gpioWrite(data_pin, 0);
    gpioWrite(rs_pin, mode);
    gpioWrite(bl_pin, LCD_BL_VAL);

    for (i = 0; i < 8; i++) {
        if (bits & (1 << i)) {
            gpioWrite(data_pin, 1);
        } else {
            gpioWrite(data_pin, 0);
        }
        gpioDelay(1); // 1 microsecond delay
    }

    gpioWrite(en_pin, 1);
    gpioDelay(1);
    gpioWrite(en_pin, 0);
    gpioDelay(100); // 100 microseconds delay
}

// Function to send a string to the LCD
void lcd_string(char *str) {
    while (*str) {
        lcd_byte(*str++, LCD_CHR);
    }
}

// Function to clear the LCD
void lcd_clear(void) {
    lcd_byte(0x01, LCD_CMD);
    gpioDelay(2000); // 2 milliseconds delay
}

// Function to set the cursor position on the LCD
void lcd_set_cursor(int row, int col) {
    int address;
    if (row == 0) {
        address = LCD_LINE_1;
    } else {
        address = LCD_LINE_2;
    }
    address += col;
    lcd_byte(address, LCD_CMD);
}

// Function to print the flow rate on the LCD
void lcd_print_flow_rate(double flow_rate) {
    char buffer[LCD_WIDTH + 1];
    snprintf(buffer, sizeof(buffer), "Flow: %.2f L/min", flow_rate);
    lcd_set_cursor(0, 0);
    lcd_string(buffer);
}

// Function to print the volume on the LCD
void lcd_print_volume(double volume) {
    char buffer[LCD_WIDTH + 1];
    snprintf(buffer, sizeof(buffer), "Vol: %.2f L", volume);
    lcd_set_cursor(1, 0);
    lcd_string(buffer);
}

// Function to update the LCD display
void lcd_update(double flow_rate, double volume) {
    lcd_clear();
    lcd_print_flow_rate(flow_rate);
    lcd_print_volume(volume);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input with pull-down resistor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_DOWN);

    // Set up interrupt for pulse counting
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C for LCD
    i2c_handle = i2cOpen(LCD_I2C_BUS, LCD_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (running) {
        // Calculate flow rate
        double flow_rate = (double)pulse_count / PULSES_PER_LITER / 60.0;

        // Update total volume
        volume_total += flow_rate / 60.0;

        // Print flow rate and volume to console
        printf("Flow Rate: %.2f L/min, Total Volume: %.2f L\n", flow_rate, volume_total);

        // Update LCD display every 10 seconds
        if (i2c_handle >= 0) {
            lcd_update(flow_rate, volume_total);
        }

        // Reset pulse count
        pulse_count = 0;

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

