#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27
#define PULSES_PER_LITER 7.5
#define SAMPLE_INTERVAL_SEC 1
#define NO_FLOW_TIMEOUT_SEC 5

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t pulse_count = 0;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    pulse_count++;
}

static int lcd_write_byte(int handle, unsigned char data, unsigned char mode) {
    unsigned char buf[2] = {data | mode, 0x08};
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        return -1;
    }
    return 0;
}

static int lcd_send_command(int handle, unsigned char cmd) {
    return lcd_write_byte(handle, cmd, 0x00);
}

static int lcd_send_data(int handle, unsigned char data) {
    return lcd_write_byte(handle, data, 0x40);
}

static int lcd_init(int handle) {
    if (lcd_send_command(handle, 0x33) < 0) return -1;
    if (lcd_send_command(handle, 0x32) < 0) return -1;
    if (lcd_send_command(handle, 0x28) < 0) return -1;
    if (lcd_send_command(handle, 0x0C) < 0) return -1;
    if (lcd_send_command(handle, 0x06) < 0) return -1;
    if (lcd_send_command(handle, 0x01) < 0) return -1;
    return 0;
}

static int lcd_clear(int handle) {
    return lcd_send_command(handle, 0x01);
}

static int lcd_set_cursor(int handle, int row, int col) {
    unsigned char addr = (row == 0) ? 0x80 : 0xC0;
    addr += col;
    return lcd_send_command(handle, addr);
}

static int lcd_print(int handle, const char *str) {
    while (*str) {
        if (lcd_send_data(handle, (unsigned char)*str) < 0) return -1;
        str++;
    }
    return 0;
}

static float calculate_flow_rate(int pulses) {
    return ((float)pulses / PULSES_PER_LITER) * (60.0f / SAMPLE_INTERVAL_SEC);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on GPIO%d.\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(FLOW_SENSOR_GPIO, pulse_callback) != 0) {
        fprintf(stderr, "Error: Failed to set alert function on GPIO%d.\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, LCD_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (lcd_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: LCD initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    time_t last_flow_time = time(NULL);

    while (running) {
        sleep(SAMPLE_INTERVAL_SEC);

        int pulses = pulse_count;
        pulse_count = 0;

        float flow_rate = calculate_flow_rate(pulses);

        if (lcd_clear(i2c_handle) != 0) {
            fprintf(stderr, "Error: Failed to clear LCD.\n");
            break;
        }

        if (lcd_set_cursor(i2c_handle, 0, 0) != 0) {
            fprintf(stderr, "Error: Failed to set cursor.\n");
            break;
        }

        if (lcd_print(i2c_handle, "Flow Rate:") != 0) {
            fprintf(stderr, "Error: Failed to print to LCD.\n");
            break;
        }

        if (lcd_set_cursor(i2c_handle, 1, 0) != 0) {
            fprintf(stderr, "Error: Failed to set cursor.\n");
            break;
        }

        char buffer[17];
        snprintf(buffer, sizeof(buffer), "%.2f L/min", flow_rate);
        if (lcd_print(i2c_handle, buffer) != 0) {
            fprintf(stderr, "Error: Failed to print to LCD.\n");
            break;
        }

        time_t current_time = time(NULL);
        if (difftime(current_time, last_flow_time) >= NO_FLOW_TIMEOUT_SEC) {
            if (lcd_clear(i2c_handle) != 0) break;
            if (lcd_set_cursor(i2c_handle, 0, 0) != 0) break;
            if (lcd_print(i2c_handle, "Sensor Absent") != 0) break;
            if (lcd_set_cursor(i2c_handle, 1, 0) != 0) break;
            if (lcd_print(i2c_handle, "Check Wiring") != 0) break;
            last_flow_time = current_time;
        }
    }

    if (i2c_handle >= 0) {
        lcd_clear(i2c_handle);
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

