#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define SCAN_DELAY_US 800

static const unsigned int row_pins[NUM_ROWS] = {17, 18, 27, 22, 23, 24, 25, 4};
static const unsigned int col_pins[NUM_COLS] = {5, 6, 12, 13, 19, 16, 26, 20};

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_row(struct gpiod_line *line, int val) {
    if (gpiod_line_set_value(line, val) < 0) {
        perror("gpiod_line_set_value (row)");
        exit(EXIT_FAILURE);
    }
}

static void set_col(struct gpiod_line *line, int val) {
    if (gpiod_line_set_value(line, val) < 0) {
        perror("gpiod_line_set_value (col)");
        exit(EXIT_FAILURE);
    }
}

static void display_wave(struct gpiod_line *row_lines[NUM_ROWS],
                         struct gpiod_line *col_lines[NUM_COLS],
                         int direction, int offset) {
    for (int r = 0; r < NUM_ROWS; r++) {
        set_row(row_lines[r], 0);
    }
    for (int c = 0; c < NUM_COLS; c++) {
        set_col(col_lines[c], 1);
    }

    for (int r = 0; r < NUM_ROWS; r++) {
        int target_col;
        if (direction == 1) {
            target_col = (r + offset) % NUM_COLS;
        } else {
            target_col = (NUM_COLS - 1 - (r + offset)) % NUM_COLS;
        }
        set_row(row_lines[r], 1);
        set_col(col_lines[target_col], 0);
        usleep(SCAN_DELAY_US);
        set_row(row_lines[r], 0);
        set_col(col_lines[target_col], 1);
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *row_lines[NUM_ROWS];
    struct gpiod_line *col_lines[NUM_COLS];
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Failed to get row line %u\n", row_pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(row_lines[i], "led_matrix", 0) < 0) {
            fprintf(stderr, "Failed to request row line %u as output\n", row_pins[i]);
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Failed to get col line %u\n", col_pins[i]);
