/*
 * VL53L3CX Multi-Target ToF Sensor Reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * NOTE: The VL53L3CX requires proprietary firmware downloaded via I2C
 * to configure the sensor. This program stubs the firmware download
 * with a descriptive comment and implements the I2C communication
 * layer, error handling, and application logic.
 *
 * Build: gcc -o vl53l3cx_reader vl53l3cx_reader.c -lpigpio -lrt
 * Run:   sudo ./vl53l3cx_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L3CX_ADDR 0x29
#define NUM_TARGETS 16
#define POLL_DELAY_US 100000  /* 100 ms */

/* VL53L3CX ULD API register addresses */
#define VL53L3CX_REG_SOFT_RESET              0x0003
#define VL53L3CX_REG_MODEL_ID                0x010F
#define VL53L3CX_REG_SYSTEM_MODE             0x0080
#define VL53L3CX_REG_RANGE_START             0x0081
#define VL53L3CX_REG_RESULT_RANGE_STATUS     0x0089
#define VL53L3CX_REG_RESULT_DISTANCE         0x0096
#define VL53L3CX_REG_RESULT_NUM_OF_TARGETS   0x0098
#define VL53L3CX_REG_RESULT_TARGET_LIST      0x009A

#define VL53L3CX_MODEL_ID_EXPECTED 0xEA
#define VL53L3CX_MODE_STANDBY  0x00
#define VL53L3CX_MODE_RANGING  0x02

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Stub: Download proprietary firmware to configure the VL53L3CX.
 * In a real application, this would involve reading the firmware
 * from a file and sending it via I2C using the ST ULD API.
 */
static int download_firmware(void) {
    fprintf(stderr, "WARNING: Stubbed firmware download. In a real application, "
                    "read the firmware from a file and send it via I2C using the "
                    "ST ULD API.\n");
    return 0;
}

/*
 * Stub: Initialize the VL53L3CX using the ST ULD API.
 * In a real application, this would involve writing to the ULD API
 * registers to configure the sensor for multi-target ranging.
 */
static int initialize_sensor(void) {
    fprintf(stderr, "WARNING: Stubbed sensor initialization. In a real application, "
                    "write to the ST ULD API registers to configure the sensor.\n");
    return 0;
}

/*
 * Read a 16-bit register from the VL53L3CX.
 * Returns 0 on success, -1 on error.
 */
static int read_reg16(uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to write register address 0x%04X\n", reg);
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read register 0x%04X\n", reg);
        return -1;
    }

    *value = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Write a 16-bit value to a 16-bit register.
 * Returns 0 on success, -1 on error.
 */
static int write_reg16(uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 4) != 4) {
        fprintf(stderr, "Error: Failed to write register 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

/*
 * Read the distance measurements for all detected targets.
 * Returns 0 on success, -1 on error.
 */
static int read_targets(uint16_t *distances) {
    uint16_t num_targets = 0;
    uint16_t status = 0;
    uint8_t target_data[NUM_TARGETS * 2];

    /* Check if data is ready */
    if (read_reg16(VL53L3CX_REG_RESULT_RANGE_STATUS, &status) != 0) {
        return -1;
    }

    if ((status & 0x01) == 0) {
        return 1; /* Data not ready yet */
    }

    /* Read number of targets */
    if (read_reg16(VL53L3CX_REG_RESULT_NUM_OF_TARGETS, &num_targets) != 0) {
        return -1;
    }

    if (num_targets > NUM_TARGETS) {
        fprintf(stderr, "Error: Too many targets (%u).\n", num_targets);
        return -1;
    }

    /* Read target distance data */
    if (i2cReadI2CBlockData(i2c_handle, VL53L3CX_REG_RESULT_TARGET_LIST,
                            (char *)target_data, num_targets * 2) != (int)(num_targets * 2)) {
        fprintf(stderr, "Error: Failed to read target list.\n");
        return -1;
    }

    for (uint16_t i = 0; i < num_targets; i++) {
        distances[i] = ((uint16_t)target_data[i * 2] << 8) | target_data[i * 2 + 1];
    }

    return 0;
}

int main(void) {
    uint16_t distances[NUM_TARGETS];
    uint16_t model_id = 0;
    int ret;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection */
    i2c_handle = i2cOpen(I2C_BUS, VL53L3CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at bus %d, addr 0x%02X.\n",
                I2C_BUS, VL53L3CX_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler.\n");
    }

    /* Read and verify model ID */
    if (read_reg16(VL53L3CX_REG_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error: Failed to read model ID. Sensor may be absent.\n");
        goto cleanup;
    }

    if (model_id != VL53L3CX_MODEL_ID_EXPECTED) {
        fprintf(stderr, "Error: Unexpected model ID 0x%04X (expected 0x%04X).\n",
                model_id, VL53L3CX_MODEL_ID_EXPECTED);
        goto cleanup;
    }

    printf("VL53L3CX detected (Model ID: 0x%04X).\n", model_id);

    /* Download proprietary firmware */
    if (download_firmware() != 0) {
        fprintf(stderr, "Error: Firmware download failed.\n");
        goto cleanup;
    }

    /* Initialize the sensor */
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        goto cleanup;
    }

    printf("Starting multi-target ranging. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (running) {
        /* Start ranging */
        if (write_reg16(VL53L3CX_REG_SYSTEM_MODE, VL53L3CX_MODE_RANGING) != 0) {
            fprintf(stderr, "Error: Failed to start ranging.\n");
            break;
        }

        /* Read target distances */
        ret = read_targets(distances);
        if (ret == 0) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[32];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

            printf("[%s] Targets: %u, Distances: ", timestamp, 0);
            for (uint16_t i = 0; i < NUM_TARGETS && i < 16; i++) {
                printf("%u ", distances[i]);
            }
            printf("\n");
            fflush(stdout);
        } else if (ret < 0) {
            fprintf(stderr, "Error: Failed to read target distances.\n");
        }

        /* Wait before next measurement */
        gpioDelay(POLL_DELAY_US);
    }

cleanup:
    printf("\nShutting down...\n");

    /* Stop ranging */
    if (i2c_handle >= 0) {
        write_reg16(VL53L3CX_REG_SYSTEM_MODE, VL53L3CX_MODE_STANDBY);
        i2cClose(i2c_handle);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

