#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1145_ADDR        0x60
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY  0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_IRQ_STATUS 0x12
#define SI1145_REG_IRQ_ENABLE 0x13
#define SI1145_REG_COMMAND 0x18
#define SI1145_REG_PS1_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA0 0x2C

#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_PS_FORCE 0x05
#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_CMD_PSALS_FORCE 0x07

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_word(int handle, uint8_t reg, uint16_t *value) {
    int result = i2cReadWordData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading word from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint16_t)result;
    return 0;
}

static int initialize_sensor(int handle) {
    uint8_t part_id;
    if (read_register(handle, SI1145_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read PART ID\n");
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Unexpected PART ID: 0x%02X (expected 0x45)\n", part_id);
        return -1;
    }

    if (write_register(handle, SI1145_REG_HW_KEY, 0x17) != 0) return -1;
    if (write_register(handle, SI1145_REG_IRQ_ENABLE, 0x00) != 0) return -1;
    if (write_register(handle, SI1145_REG_MEAS_RATE0, 0x08) != 0) return -1;
    if (write_register(handle, SI1145_REG_MEAS_RATE1, 0x00) != 0) return -1;

    if (write_register(handle, SI1145_REG_COMMAND, SI1145_CMD_RESET) != 0) return -1;
    gpioDelay(10000);

    uint8_t irq_status;
    do {
        if (read_register(handle, SI1145_REG_IRQ_STATUS, &irq_status) != 0) return -1;
        gpioDelay(10000);
    } while (irq_status & 0x01);

    if (write_register(handle, SI1145_REG_COMMAND, SI1145_CMD_PSALS_FORCE) != 0) return -1;
    gpioDelay(10000);

    return 0;
}

static int read_sensor_data(int handle, uint16_t *proximity, uint16_t *ambient_light) {
    if (read_word(handle, SI1145_REG_PS1_DATA0, proximity) != 0) return -1;
    if (read_word(handle, SI1145_REG_ALS_VIS_DATA0, ambient_light) != 0) return -1;
    return 0;
}

static void log_data(FILE *fp, uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(fp, "%s, Proximity: %u, Ambient Light: %u\n", timestamp, proximity, ambient_light);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    uint16_t proximity, ambient_light;
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &proximity, &ambient_light) == 0) {
            log_data(log_file, proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        gpioDelay(500000);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

