#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Si1145 I2C address (7-bit) */
#define SI1145_ADDR 0x60

/* Si1145 register addresses */
#define REG_PART_ID       0x00
#define REG_HW_KEY        0x07
#define REG_MEAS_RATE0    0x08
#define REG_MEAS_RATE1    0x09
#define REG_PS_LED21      0x0F
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_PS1_DATA0     0x18
#define REG_PS1_DATA1     0x19
#define REG_CH_LIST       0x4F
#define REG_COMMAND       0x30

/* Expected PART_ID for Si1145 */
#define SI1145_PART_ID    0x45

/* Commands */
#define CMD_ALS_FORCE     0x06
#define CMD_PS_FORCE      0x07

/* CH_LIST bit masks */
#define CH_LIST_PS1       0x01
#define CH_LIST_ALS_VIS   0x20

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d\n",
                reg, value, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, rc=%d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_word_le(uint8_t reg_lo, uint16_t *value)
{
    int rc = i2cReadWordData(i2c_handle, reg_lo);
    if (rc < 0) {
        fprintf(stderr, "I2C word read failed: reg=0x%02X, rc=%d\n", reg_lo, rc);
        return -1;
    }
    *value = (uint16_t)rc;
    return 0;
}

static int init_si1145(void)
{
    uint8_t part_id;

    if (read_reg(REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read PART_ID - sensor absent or bus error\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n",
                part_id, SI1145_PART_ID);
        return -1;
    }

    if (write_reg(REG_HW_KEY, 0x17) < 0)
        return -1;

    if (write_reg(REG_MEAS_RATE0, 0x08) < 0)
        return -1;
    if (write_reg(REG_MEAS_RATE1, 0x00) < 0)
        return -1;
    if (write_reg(REG_PS_LED21, 0x01) < 0)
        return -1;

    if (write_reg(REG_CH_LIST, CH_LIST_PS1 | CH_LIST_ALS_VIS) < 0)
        return -1;

    return 0;
}

static int read_sensor_data(uint16_t *proximity, uint16_t *ambient_light)
{
    if (write_reg(REG_COMMAND, CMD_ALS_FORCE) < 0)
        return -1;
    if (write_reg(REG_COMMAND, CMD_PS_FORCE) < 0)
        return -1;

    gpioDelay(10000); /* 10 ms conversion delay */

    if (read_word_le(REG_PS1_DATA0, proximity) < 0)
        return -1;
    if (read_word_le(REG_ALS_VIS_DATA0, ambient_light) < 0)
        return -1;

    return 0;
}

static void log_data(uint16_t proximity, uint16_t ambient_light)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, proximity, ambient_light);
    fflush(log_file);
}

int main(void)
{
    uint16_t proximity, ambient_light;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at addr 0x%02X: %d\n",
                SI1145_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1145() < 0) {
        fprintf(stderr, "Si1145 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si1145 data logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        if (read_sensor_data(&proximity, &ambient_light) == 0) {
            log_data(proximity, ambient_light);
            printf("Proximity: %u, Ambient Light: %u\n",
                   proximity, ambient_light);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        sleep(1);
    }

    printf("\nShutting down...\n");
    if (log_file)
        fclose(log_file);
    if (i2c_handle >= 0)
        i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

