#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define APDS9960_ADDR 0x39
#define I2C_BUS 1

#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0xF1
#define APDS9960_CONFIG2 0x90
#define APDS9960_ID 0x92
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B
#define APDS9960_PDATA 0x9C

#define PROXIMITY_THRESHOLD 200
#define LOG_FILE "color_proximity_log.csv"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int initialize_apds9960(void) {
    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to disable APDS9960\n");
        return -1;
    }
    gpioDelay(1000);

    if (i2cWriteByteData(i2c_handle, APDS9960_ATIME, 0xDB) < 0) {
        fprintf(stderr, "Error: Failed to set ATIME\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, APDS9960_WTIME, 0xF6) < 0) {
        fprintf(stderr, "Error: Failed to set WTIME\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, APDS9960_PPULSE, 0x87) < 0) {
        fprintf(stderr, "Error: Failed to set PPULSE\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, APDS9960_CONTROL, 0x03) < 0) {
        fprintf(stderr, "Error: Failed to set CONTROL\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, APDS9960_CONFIG2, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set CONFIG2\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error: Failed to enable APDS9960\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int read_apds9960_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint8_t *proximity) {
    char buffer[8];
    if (i2cReadI2CBlockData(i2c_handle, APDS9960_CDATAL, buffer, 8) < 0) {
        fprintf(stderr, "Error: Failed to read APDS9960 data block\n");
        return -1;
    }
    *red = (uint16_t)((buffer[1] << 8) | buffer[0]);
    *green = (uint16_t)((buffer[3] << 8) | buffer[2]);
    *blue = (uint16_t)((buffer[5] << 8) | buffer[4]);
    *proximity = (uint8_t)buffer[7];
    return 0;
}

static int log_data(uint16_t red, uint16_t green, uint16_t blue, uint8_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, red, green, blue, proximity) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    uint16_t red, green, blue;
    uint8_t proximity;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, APDS9960_ADDR);
        gpioTerminate();
        return 1;
    }

    if (initialize_apds9960() < 0) {
        fprintf(stderr, "Error: APDS9960 initialisation failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Red,Green,Blue,Proximity\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        if (read_apds9960_data(&red, &green, &blue, &proximity) == 0) {
            if (proximity > PROXIMITY_THRESHOLD) {
                if (log_data(red, green, blue, proximity) < 0) {
                    fprintf(stderr, "Error: Logging failed, attempting to re-initialize sensor\n");
                    i2cClose(i2c_handle);
                    i2c_handle = -1;
                    gpioDelay(100000);
                    i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
                    if (i2c_handle < 0) {
                        fprintf(stderr, "Error: Failed to re-open I2C bus\n");
                        terminate = 1;
                        break;
                    }
                    if (initialize_apds9960() < 0) {
                        fprintf(stderr, "Error: APDS9960 re-initialisation failed\n");
                        terminate = 1;
                        break;
                    }
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data, attempting to re-initialize sensor\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000);
            i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Failed to re-open I2C bus\n");
                terminate = 1;
                break;
            }
            if (initialize_apds9960() < 0) {
                fprintf(stderr, "Error: APDS9960 re-initialisation failed\n");
                terminate = 1;
                break;
            }
        }
        gpioDelay(100000);
    }

    cleanup();
    return 0;
}

