#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L0X_ADDR   0x29
#define TRIGGER_PIN    17
#define LOG_FILE       "distance_log.txt"

/* VL53L0X register addresses */
#define REG_SYSRANGE_START        0x00
#define REG_RESULT_INTERRUPT_STATUS 0x13
#define REG_RESULT_RANGE_STATUS   0x14
#define REG_SYSTEM_INTERRUPT_CLEAR 0x0B

#define SYSRANGE_START_SINGLE     0x01
#define RESULT_INTERRUPT_NEWDATA  0x01

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write one byte to a register; returns 0 on success, -1 on error. */
static int vl53l0x_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* Read one byte from a register; returns 0 on success, -1 on error. */
static int vl53l0x_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* Read N bytes starting at a register; returns 0 on success, -1 on error. */
static int vl53l0x_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C block read failed (reg=0x%02X, len=%u): %s\n",
                reg, len, pigpio_error(rc));
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "I2C block read short read (reg=0x%02X, got %d, want %u)\n",
                reg, rc, len);
        return -1;
    }
    return 0;
}

/* Trigger a single measurement and read the 16-bit distance in mm. */
static int vl53l0x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t data[14];
    int attempts;

    /* 1. Start a single ranging measurement. */
    if (vl53l0x_write_reg(handle, REG_SYSRANGE_START, SYSRANGE_START_SINGLE) != 0)
        return -1;

    /* 2. Poll RESULT_INTERRUPT_STATUS bit 0 (NEW_DATA) with a timeout. */
    for (attempts = 0; attempts < 100; attempts++) {
        if (vl53l0x_read_reg(handle, REG_RESULT_INTERRUPT_STATUS, &status) != 0)
            return -1;
        if (status & RESULT_INTERRUPT_NEWDATA)
            break;
        gpioDelay(1000); /* 1 ms */
    }
    if (attempts >= 100) {
        fprintf(stderr, "Timeout waiting for VL53L0X new-data interrupt.\n");
        return -1;
    }

    /* 3. Read the 14-byte result block starting at RESULT_RANGE_STATUS. */
    if (vl53l0x_read_block(handle, REG_RESULT_RANGE_STATUS, data, sizeof(data)) != 0)
        return -1;

    /* 4. Extract the 16-bit distance from bytes 10-11 (little-endian). */
    *distance_mm = (uint16_t)((data[11] << 8) | data[10]);

    /* 5. Clear the interrupt so the next measurement can report. */
    if (vl53l0x_write_reg(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    return 0;
}

static void log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%u\n", timestamp, distance_mm);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;

    /* --- Install signal handler for graceful shutdown --- */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus to VL53L0X --- */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, VL53L0X_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Verify sensor presence by reading the device ID register (0x010A) --- */
    uint8_t dev_id = 0;
    if (vl53l0x_read_reg(g_i2c_handle, 0x010A, &dev_id) != 0) {
        fprintf(stderr, "VL53L0X not detected at 0x%02X on bus %d.\n",
                VL53L0X_ADDR, I2C_BUS);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure trigger pin as input with pull-up --- */
    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_UP);

    /* --- Open log file in append mode --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L0X distance logger started. Trigger on GPIO %d (BCM).\n",
           TRIGGER_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop: wait for falling edge on trigger pin --- */
    while (g_running) {
        if (gpioRead(TRIGGER_PIN) == 0) {
            uint16_t distance = 0;
            if (vl53l0x_read_distance(g_i2c_handle, &distance) == 0) {
                log_distance(g_log_file, distance);
                printf("Distance: %u mm\n", distance);
            } else {
                fprintf(stderr, "Failed to read distance.\n");
            }
            /* Debounce: wait until pin goes high again (or timeout) */
            int waited = 0;
            while (gpioRead(TRIGGER_PIN) == 0 && g_running && waited < 100) {
                gpioDelay(1000);
                waited++;
            }
        }
        gpioDelay(10000); /* 10 ms idle poll */
    }

    /* --- Graceful cleanup --- */
    printf("\nShutting down...\n");
    if (g_log_file != NULL)
        fclose(g_log_file);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

