    /* --- Verify sensor presence by reading the device ID register (0x010A) --- */
    uint8_t dev_id = 0;
    if (vl53l0x_read_reg(g_i2c_handle, 0x010A, &dev_id) != 0) {
        fprintf(stderr, "VL53L0X not detected at 0x%02X on bus %d.\n",
                VL53L0X_ADDR, I2C_BUS);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure trigger pin as input with pull-up --- */
    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_UP);

    /* --- Open log file in append mode --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L0X distance logger started. Trigger on GPIO %d (BCM).\n",
           TRIGGER_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop: wait for falling edge on trigger pin --- */
    while (g_running) {
        if (gpioRead(TRIGGER_PIN) == 0) {
            uint16_t distance = 0;
            if (vl53l0x_read_distance(g_i2c_handle, &distance) == 0) {
                log_distance(g_log_file, distance);
                printf("Distance: %u mm\n", distance);
            } else {
                fprintf(stderr, "Failed to read distance.\n");
            }
            /* Debounce: wait until pin goes high again (or timeout) */
            int waited = 0;
            while (gpioRead(TRIGGER_PIN) == 0 && g_running && waited < 100) {
                gpioDelay(1000);
                waited++;
            }
        }
        gpioDelay(10000); /* 10 ms idle poll */
    }

    /* --- Graceful cleanup --- */
    printf("\nShutting down...\n");
    if (g_log_file != NULL)
        fclose(g_log_file);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

