#include <pigpio.h>

#define I2C_BUS        1
#define CH101_ADDR     0x45
#define TRIGGER_CMD    0x01
#define TRIGGER_DELAY_US 50000   /* 50 ms */
#define SAMPLE_PERIOD_US 200000 /* 200 ms */
#define LOG_FILE       "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly.          */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a 16-bit register address.                 */
/* ------------------------------------------------------------------ */
static int ch101_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice(reg=0x%02X) failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a 16-bit register address.                */
/* ------------------------------------------------------------------ */
static int ch101_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char cmd = (char)reg;
    char data[2];

    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice(reg=0x%02X) failed\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: i2cReadDevice(reg=0x%02X) failed\n", reg);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a measurement and read the 16-bit distance in mm.          */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int read_distance(int handle, uint16_t *distance_mm)
{
    if (ch101_write_reg(handle, TRIGGER_CMD, 0x0001) != 0)
        return -1;

    gpioDelay(TRIGGER_DELAY_US);

    uint16_t dist;
    if (ch101_read_reg(handle, TRIGGER_CMD, &dist) != 0)
        return -1;

    *distance_mm = dist;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Build a 'YYYY-MM-DD HH:MM:SS' timestamp into a local buffer.        */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo);
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources.                                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, CH101_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file ---------------------------------------------- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handling -------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    printf("CH101 distance logger started. Press Ctrl-C to stop.\n");

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        uint16_t distance;

        if (read_distance(g_i2c_handle, &distance) == 0) {
            char ts[32];
            get_timestamp(ts, sizeof(ts));

            fprintf(g_log_file, "%s, %u\n", ts, distance);
            fflush(g_log_file);
            printf("%s, %u mm\n", ts, distance);
        } else {
            fprintf(stderr, "Warning: distance read failed, retrying next cycle\n");
        }

        /* Sleep in small increments so SIGINT is caught promptly. */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(SAMPLE_PERIOD_US / 10);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

