#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x6A
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 20.0
#define LOG_FILE "distance_log.txt"
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_distance(int handle, float *distance_out) {
    char buf[2];
    int bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "I2C read error: expected 2 bytes, got %d\n", bytes_read);
        return -1;
    }
    int raw = (buf[0] << 8) | buf[1];
    *distance_out = (float)raw / 10.0;
    return 0;
}

static int log_distance(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, Distance: %.2f cm\n", ts, distance);
    fclose(fp);
    return 0;
}

static void control_led(int state) {
    gpioWrite(GPIO_LED, state);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GPIO_LED, 0);

    while (running) {
        float distance;
        if (read_distance(i2c_handle, &distance) == 0) {
            if (log_distance(distance) != 0) {
                fprintf(stderr, "Logging failed\n");
            }
            control_led(distance < DISTANCE_THRESHOLD ? 1 : 0);
        } else {
            fprintf(stderr, "Sensor read failed; turning LED off\n");
            gpioWrite(GPIO_LED, 0);
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(GPIO_LED, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

