#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ICU20201_ADDR 0x6A
#define WHO_AM_I_REG 0x00
#define WHO_AM_I_VAL 0x0D
#define DISTANCE_REG 0x04
#define LED_GPIO 17
#define LOG_FILE "tof_log.txt"
#define POLL_DELAY_US 50000

static int i2c_handle = -1;
static int led_gpio = LED_GPIO;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) return -1;
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg8(int handle, uint8_t reg, uint8_t val) {
    return i2cWriteByteData(handle, reg, val);
}

static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *val) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) return -1;
    *val = (uint16_t)rc;
    return 0;
}

static int init_icu20201(int handle) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(handle, WHO_AM_I_REG, &who_am_i) != 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X). Sensor absent or wrong address.\n",
                who_am_i, WHO_AM_I_VAL);
        return -1;
    }
    return 0;
}

static int read_distance(int handle, uint16_t *distance) {
    return i2c_read_reg16(handle, DISTANCE_REG, distance);
}

static void log_data(uint16_t distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Distance: %u mm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance);
    fclose(fp);
}

static void control_led(uint16_t distance, int threshold) {
    gpioWrite(led_gpio, (distance < threshold) ? 1 : 0);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <distance_threshold_mm>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int threshold = atoi(argv[1]);
    if (threshold <= 0 || threshold > 1000) {
        fprintf(stderr, "Error: Threshold must be between 1 and 1000 mm.\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_icu20201(i2c_handle) != 0) {
        fprintf(stderr, "Error: ICU-20201 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(led_gpio, PI_OUTPUT);
    gpioWrite(led_gpio, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ICU-20201 distance monitoring started. Threshold: %d mm. Press Ctrl+C to exit.\n", threshold);

    while (running) {
        uint16_t distance = 0;
        if (read_distance(i2c_handle, &distance) != 0) {
            fprintf(stderr, "Error: Failed to read distance from sensor.\n");
        } else {
            log_data(distance);
            control_led(distance, threshold);
            printf("Distance: %u mm\n", distance);
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(led_gpio, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

