#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define B5L_ADDR       0x50
#define LOG_FILE       "intrusion_log.txt"
#define SAMPLE_COUNT   10
#define THRESHOLD_MM   1000
#define SAMPLE_DELAY_US 10000   /* 10 ms between measurement cycles */
#define CYCLE_DELAY_US  100000  /* 100 ms between samples */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 4-byte command frame to the B5L sensor. */
static int b5l_write_command(int fd, const uint8_t *cmd, size_t len)
{
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 15-byte response frame from the B5L sensor. */
static int b5l_read_response(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/*
 * Request a distance measurement and parse the 15-byte response.
 * Returns distance in mm on success, -1 on error.
 */
static int b5l_get_distance(int fd)
{
    uint8_t cmd[4] = {0x50, 0x0A, 0x00, 0x01};
    uint8_t resp[15];

    if (b5l_write_command(fd, cmd, sizeof(cmd)) != 0)
        return -1;

    usleep(10000); /* 10 ms measurement settle time */

    if (b5l_read_response(fd, resp, sizeof(resp)) != 0)
        return -1;

    /* Validate frame header (byte 0 should be 0x50) */
    if (resp[0] != 0x50) {
        fprintf(stderr, "B5L header mismatch: 0x%02X (expected 0x50)\n", resp[0]);
        return -1;
    }

    /* Distance is a 16-bit big-endian value at bytes 11 and 12 */
    int distance = ((resp[11] << 8) | resp[12]) & 0xFFFF;
    return distance;
}

/* Calculate the average of SAMPLE_COUNT distance readings. */
static int b5l_average_distance(int fd)
{
    long sum = 0;
    int valid = 0;

    for (int i = 0; i < SAMPLE_COUNT; i++) {
        int d = b5l_get_distance(fd);
        if (d < 0) {
            fprintf(stderr, "Sample %d failed; continuing.\n", i + 1);
            continue;
        }
        sum += d;
        valid++;
        usleep(CYCLE_DELAY_US);
    }

    if (valid == 0)
        return -1;

    return (int)(sum / valid);
}

/* Log an intrusion event with timestamp and distance. */
static void log_intrusion(int distance_mm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s - Intrusion detected! Distance: %d mm\n", ts, distance_mm);
    } else {
        fprintf(fp, "<unknown time> - Intrusion detected! Distance: %d mm\n", distance_mm);
    }

    fclose(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, B5L_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", B5L_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("B5L-LD50-07050 intrusion detector running. Press Ctrl+C to exit.\n");

    while (g_running) {
        int avg = b5l_average_distance(fd);
        if (avg < 0) {
            fprintf(stderr, "All samples failed; skipping cycle.\n");
        } else if (avg < THRESHOLD_MM) {
            printf("Intrusion detected! Distance: %d mm\n", avg);
            log_intrusion(avg);
        } else {
            printf("Distance: %d mm (no intrusion)\n", avg);
        }
        usleep(SAMPLE_DELAY_US);
    }

    printf("\nExiting gracefully.\n");
    close(fd);
    return EXIT_SUCCESS;
}

