#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L0X_ADDR             0x29
#define VL53L0X_REG_IDENT_MODEL  0xC0
#define VL53L0X_REG_SYSRANGE_START 0x00
#define VL53L0X_REG_RESULT_INT_STATUS 0x13
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x14
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x0B
#define VL53L0X_EXPECTED_MODEL_ID 0xEE

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *out) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

static int i2c_read_word_le(int handle, uint8_t reg, uint16_t *out) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C block read failed (reg=0x%02X, rc=%d): %s\n",
                reg, rc, strerror(errno));
        return -1;
    }
    *out = (uint16_t)((uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    return 0;
}

static int vl53l0x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_byte(handle, VL53L0X_REG_IDENT_MODEL, &model_id) < 0) {
        fprintf(stderr, "Failed to read model ID register.\n");
        return -1;
    }
    if (model_id != VL53L0X_EXPECTED_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID 0x%02X (expected 0x%02X).\n",
                model_id, VL53L0X_EXPECTED_MODEL_ID);
        return -1;
    }
    printf("VL53L0X detected (model ID 0x%02X).\n", model_id);
    return 0;
}

static int vl53l0x_read_distance(int handle, uint16_t *distance_mm) {
    if (i2c_write_byte(handle, VL53L0X_REG_SYSRANGE_START, 0x01) < 0) {
        return -1;
    }

    uint8_t status = 0;
    int waited_ms = 0;
    const int max_wait_ms = 100;

    while (waited_ms < max_wait_ms) {
        if (i2c_read_byte(handle, VL53L0X_REG_RESULT_INT_STATUS, &status) < 0) {
            return -1;
        }
        if (status & 0x01) {
            break;
        }
        gpioDelay(2000); /* 2 ms */
        waited_ms += 2;
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "Timeout waiting for VL53L0X measurement.\n");
        return -1;
    }

    if (i2c_read_word_le(handle, VL53L0X_REG_RESULT_RANGE_STATUS, distance_mm) < 0) {
        return -1;
    }

    if (i2c_write_byte(handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        return -1;
    }

    return 0;
}

static void print_timestamp(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s ", buffer);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, VL53L0X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device on bus 1 at 0x%02X: %s\n",
                VL53L0X_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l0x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L0X initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting distance readings every 500 ms. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance = 0;
        if (vl53l0x_read_distance(g_i2c_handle, &distance) == 0) {
            print_timestamp();
            printf("Distance: %u mm\n", distance);
            fflush(stdout);
        } else {
            print_timestamp();
            fprintf(stderr, "Warning: failed to read distance.\n");
        }
        gpioDelay(500000); /* 500 ms */
    }

    printf("\nExiting gracefully...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

