#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI1182_ADDR    0x39

/* Si1182 register addresses */
#define REG_IRQ_STATUS  0x25
#define REG_PS1_DATA0   0x2A   /* Proximity LSB  */
#define REG_PS1_DATA1   0x2B   /* Proximity MSB  */
#define REG_CONFIG      0x18

/* CONFIG: bit 0 = PROX_EN (1 = enable proximity mode) */
#define CONFIG_PROX_EN  0x01

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to a register; returns 0 on success, -1 on error. */
static int reg_write(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* Read a single byte from a register; returns 0 on success, -1 on error. */
static int reg_read(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* Read a 16-bit little-endian value from two consecutive registers. */
static int reg_read16(int handle, uint8_t reg_lsb, uint16_t *out)
{
    uint8_t lo, hi;
    if (reg_read(handle, reg_lsb, &lo) < 0)
        return -1;
    if (reg_read(handle, reg_lsb + 1, &hi) < 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* Initialize the Si1182 for proximity mode. Returns 0 on success, -1 on error. */
static int init_si1182(int handle)
{
    uint8_t cfg;

    /* Probe the CONFIG register to confirm the sensor is present. */
    if (reg_read(handle, REG_CONFIG, &cfg) < 0) {
        fprintf(stderr, "Si1182 not responding at 0x%02X (sensor absent or bus error)\n",
                SI1182_ADDR);
        return -1;
    }

    /* Enable proximity mode. */
    if (reg_write(handle, REG_CONFIG, CONFIG_PROX_EN) < 0)
        return -1;

    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed on bus %d addr 0x%02X: %s\n",
                I2C_BUS, SI1182_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1182(g_i2c_handle) < 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si1182 proximity sensor initialized. Reading every 500 ms...\n");

    while (g_running) {
        uint8_t irq;
        if (reg_read(g_i2c_handle, REG_IRQ_STATUS, &irq) < 0) {
            fprintf(stderr, "IRQ status read error; continuing\n");
            gpioDelay(500000);
            continue;
        }

        if (irq & 0x01) {
            uint16_t prox;
            if (reg_read16(g_i2c_handle, REG_PS1_DATA0, &prox) == 0) {
                printf("Proximity: %u\n", prox);
            } else {
                fprintf(stderr, "Proximity data read error\n");
            }
        }

        gpioDelay(500000); /* 500 ms */
    }

    printf("\nExiting cleanly...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

