#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75030_ADDR  0x4C
#define DISTANCE_REG   0x00
#define SCALE_FACTOR   0.125f   /* mm per count */
#define POLL_MS        500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Read a 16-bit little-endian register from the MLX75030.
 * Returns 0 on success and stores the distance in mm in *out_mm.
 * Returns -1 on I2C error.
 */
static int read_distance_mm(int fd, float *out_mm)
{
    uint8_t reg = DISTANCE_REG;
    ssize_t w = write(fd, &reg, 1);
    if (w != 1) {
        fprintf(stderr, "write(reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }

    uint8_t buf[2];
    ssize_t r = read(fd, buf, 2);
    if (r != 2) {
        fprintf(stderr, "read(reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }

    uint16_t raw = (uint16_t)((buf[1] << 8) | buf[0]);
    *out_mm = (float)raw * SCALE_FACTOR;
    return 0;
}

int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    int fd = i2c_open(I2C_BUS, MLX75030_ADDR);
    if (fd < 0)
        return EXIT_FAILURE;

    /* Probe: try a zero-length write to confirm the slave ACK's. */
    if (write(fd, NULL, 0) < 0) {
        fprintf(stderr, "MLX75030 not responding at 0x%02X: %s\n",
                MLX75030_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    struct timespec sleep_ts = { 0, POLL_MS * 1000000L };

    while (g_running) {
        float distance_mm;
        if (read_distance_mm(fd, &distance_mm) == 0) {
            printf("Distance: %.2f mm\n", distance_mm);
            fflush(stdout);
        }
        /* On I2C error, the read_distance_mm call already printed a message. */

        if (nanosleep(&sleep_ts, NULL) != 0) {
            if (errno == EINTR)
                continue;
            perror("nanosleep");
            break;
        }
    }

    if (close(fd) != 0)
        perror("close");

    return EXIT_SUCCESS;
}

