#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define OPT3101_ADDR 0x44
#define I2C_BUS 1

#define REG_RESULT_DISTANCE 0x00
#define REG_RESULT_AMBIENT 0x04
#define REG_RESULT_ERROR 0x08

#define REG_CONFIG_REG0 0x0C
#define REG_CONFIG_REG1 0x0D

#define DISTANCE_SCALE 0.001f
#define AMBIENT_SCALE 0.001f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int opt3101_init(int handle) {
    // Configure OPT3101: Enable measurement, set range, etc.
    // For simplicity, we write known configuration values.
    if (i2cWriteByteData(handle, REG_CONFIG_REG0, 0x01) < 0) {
        fprintf(stderr, "Error writing to CONFIG_REG0\n");
        return -1;
    }
    if (i2cWriteByteData(handle, REG_CONFIG_REG1, 0x02) < 0) {
        fprintf(stderr, "Error writing to CONFIG_REG1\n");
        return -1;
    }
    return 0;
}

int opt3101_read_distance(int handle, float *distance) {
    int raw = i2cReadWordData(handle, REG_RESULT_DISTANCE);
    if (raw < 0) {
        fprintf(stderr, "Error reading distance register\n");
        return -1;
    }
    *distance = (float)raw * DISTANCE_SCALE;
    return 0;
}

int opt3101_read_ambient(int handle, float *ambient) {
    int raw = i2cReadWordData(handle, REG_RESULT_AMBIENT);
    if (raw < 0) {
        fprintf(stderr, "Error reading ambient register\n");
        return -1;
    }
    *ambient = (float)raw * AMBIENT_SCALE;
    return 0;
}

int opt3101_read_error(int handle, int *error) {
    int raw = i2cReadByteData(handle, REG_RESULT_ERROR);
    if (raw < 0) {
        fprintf(stderr, "Error reading error register\n");
        return -1;
    }
    *error = raw;
    return 0;
}

void log_data(float distance, float ambient, int error) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("[%s] Distance: %.3f mm, Ambient: %.3f lux, Error: 0x%02X\n",
           timestamp, distance, ambient, error);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (opt3101_init(i2c_handle) < 0) {
        fprintf(stderr, "OPT3101 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        float distance, ambient;
        int error;

        if (opt3101_read_distance(i2c_handle, &distance) == 0 &&
            opt3101_read_ambient(i2c_handle, &ambient) == 0 &&
            opt3101_read_error(i2c_handle, &error) == 0) {
            log_data(distance, ambient, error);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(500000); // 500 ms
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return 0;
}

