/*
 * HC-SR04 Ultrasonic Distance Sensor Reader for Raspberry Pi 3 Model B+
 * Library: pigpio (modern GPIO API)
 * Trigger: GPIO 17 (BCM)   Echo: GPIO 18 (BCM)
 *
 * Wiring notes:
 *   - HC-SR04 VCC -> 5V (external supply)
 *   - HC-SR04 GND -> GND
 *   - HC-SR04 TRIG -> GPIO 17 (via 1 kOhm series resistor)
 *   - HC-SR04 ECHO -> GPIO 18 (via 1 kOhm series resistor)
 *   - Pi GPIO 17/18 are 3.3V tolerant; the HC-SR04 operates at 5V.
 *     The 1 kOhm series resistors protect the Pi from potential overvoltage.
 *
 * Build: gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* 10 us trigger pulse            */
#define ECHO_TIMEOUT_US  200000      /* 200 ms timeout for echo edges  */
#define MAX_PULSE_US     38000       /* HC-SR04 max range timeout ~38 ms */
#define LOG_INTERVAL_S   1           /* seconds between readings      */
#define SPEED_OF_SOUND   0.0343      /* cm/us at 20 C                 */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Returns the elapsed microseconds between two gpioTick() values.
 * gpioTick() is a 32-bit microsecond counter that wraps every ~71.6 min.
 * The subtraction is correct even across a wrap because pigpio handles
 * the wrap internally when gpioTick() is used in a difference.
 */
static uint32_t tick_diff_us(uint32_t start, uint32_t end)
{
    return end - start;
}

/*
 * Send a 10 us trigger pulse.
 * Returns 0 on success, -1 on write failure.
 */
static int trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1;
    }
    return 0;
}

/*
 * Measure the echo pulse width in microseconds.
 * Returns:
 *   > 0  : pulse duration in us
 *   -1   : timeout waiting for rising edge
 *   -2   : timeout waiting for falling edge
 *   -3   : pulse duration out of valid range
 */
static int measure_echo_us(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* Wait for echo rising edge (GPIO goes HIGH) */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            return -1;  /* timeout */
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (GPIO goes LOW) */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            return -2;  /* timeout */
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = tick_diff_us(start_tick, end_tick);

    if (pulse_us <= 0 || pulse_us > MAX_PULSE_US) {
        return -3;  /* invalid pulse */
    }

    return (int)pulse_us;
}

/*
 * Compute distance in cm from pulse width in microseconds.
 * distance = (pulse_us * speed_of_sound) / 2
 */
static float calculate_distance(int pulse_us)
{
    return ((float)pulse_us * SPEED_OF_SOUND) / 2.0f;
}

/*
 * Log a reading with a timestamp.
 */
static void log_reading(float distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Distance: %.2f cm\n", timestamp, distance);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO, INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000);  /* 50 ms settle time */

    printf("HC-SR04 distance reader started. Press Ctrl+C to exit.\n");
    printf("Trigger: GPIO %d  Echo: GPIO %d\n", TRIGGER_PIN, ECHO_PIN);

    while (g_running) {
        if (trigger_sensor() != 0) {
            fprintf(stderr, "Warning: trigger failed, retrying next cycle\n");
            sleep(LOG_INTERVAL_S);
            continue;
        }

        int pulse_us = measure_echo_us();
        if (pulse_us < 0) {
            fprintf(stderr, "Warning: echo measurement failed (code %d)\n", pulse_us);
            sleep(LOG_INTERVAL_S);
            continue;
        }

        float distance = calculate_distance(pulse_us);
        log_reading(distance);

        sleep(LOG_INTERVAL_S);
    }

    /* Clean shutdown */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

