#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 1.0f
#define RANGE_BIN_COUNT 64
#define RANGE_RESOLUTION 0.0486f
#define ALERT_DURATION_MS 2000
#define LOG_FILE "intrusion_log.csv"

static const uint8_t MAGIC_WORD[8] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, B115200);
    cfsetispeed(&tty, B115200);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_lflag = 0;
    tty.c_oflag = 0;
    tty.c_iflag = 0;

    tty.c_cc[VMIN] = 1;
    tty.c_cc[VTIME] = 10;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_exact(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("Error reading from UART");
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART read returned 0 (sensor absent?)\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static int read_radar_frame(int fd, uint16_t *range_profile) {
    uint8_t header[8];
    if (read_exact(fd, header, sizeof(header)) != 0) return -1;

    if (memcmp(header, MAGIC_WORD, sizeof(header)) != 0) {
        fprintf(stderr, "Invalid magic word: 0x%02X%02X%02X%02X%02X%02X%02X%02X\n",
                header[0], header[1], header[2], header[3], header[4], header[5], header[6], header[7]);
        return -1;
    }

    uint8_t data[RANGE_BIN_COUNT * 2];
    if (read_exact(fd, data, sizeof(data)) != 0) return -1;

    for (int i = 0; i < RANGE_BIN_COUNT; i++) {
        range_profile[i] = (uint16_t)data[i * 2] | ((uint16_t)data[i * 2 + 1] << 8);
    }
    return 0;
}

static float calculate_distance(const uint16_t *range_profile) {
    float max_val = 0.0f;
    for (int i = 0; i < RANGE_BIN_COUNT; i++) {
        float dist = (float)i * RANGE_RESOLUTION;
        if (range_profile[i] > max_val) {
            max_val = (float)range_profile[i];
        }
    }
    return max_val * RANGE_RESOLUTION;
}

static void log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f\n", timestamp, distance);
    fflush(log_file);
}

static void trigger_alert(void) {
    gpioWrite(GPIO_LED, 1);
    gpioDelay(ALERT_DURATION_MS * 1000);
    gpioWrite(GPIO_LED, 0);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    uart_fd = init_uart(UART_DEVICE);
    if (uart_fd < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(uart_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Distance (m)\n");
        fflush(log_file);
    }

    uint16_t range_profile[RANGE_BIN_COUNT];

    while (running) {
        if (read_radar_frame(uart_fd, range_profile) != 0) {
            fprintf(stderr, "Failed to read radar frame, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        float distance = calculate_distance(range_profile);

        if (distance > DISTANCE_THRESHOLD) {
            printf("Intrusion detected! Distance: %.3f m\n", distance);
            log_intrusion(distance);
            trigger_alert();
        }

        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioWrite(GPIO_LED, 0);
    if (uart_fd >= 0) close(uart_fd);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

