#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x69
#define DISTANCE_REG_H 0x31
#define DISTANCE_REG_L 0x32
#define ALERT_PIN      17
#define DISTANCE_THRESHOLD 10.0f
#define LOG_FILE       "distance_log.txt"
#define SAMPLE_US      100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read the 16-bit distance value from the ICU-20201.
 * Returns 0 on success and stores the distance in *out_distance.
 * Returns -1 on I2C error, -2 on sensor-absent (zero-length read).
 */
static int read_distance(int handle, float *out_distance)
{
    char buf[2];
    int  rc;

    rc = i2cReadI2CBlockData(handle, DISTANCE_REG_H, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %d\n",
                DISTANCE_REG_H, rc);
        return -1;
    }
    if (rc == 0) {
        fprintf(stderr, "Sensor absent: zero-length read from 0x%02X\n",
                I2C_ADDR);
        return -2;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *out_distance = (float)raw;
    return 0;
}

static void log_distance(float distance)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, Distance: %.2f cm\n", ts, distance);
    fclose(fp);
}

static void trigger_alert(int pin)
{
    gpioWrite(pin, 1);
    gpioDelay(500000); /* 500 ms */
    gpioWrite(pin, 0);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, OUTPUT) failed\n", ALERT_PIN);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALERT_PIN, 0);

    printf("ICU-20201 distance monitor started. Logging to %s\n", LOG_FILE);

    while (g_running) {
        float distance;
        int rc = read_distance(g_i2c_handle, &distance);

        if (rc == 0) {
            log_distance(distance);
            if (distance < DISTANCE_THRESHOLD) {
                trigger_alert(ALERT_PIN);
            }
        } else if (rc == -2) {
            /* Sensor absent: back off briefly and retry rather than spamming */
            gpioDelay(500000);
        }
        /* rc == -1: I2C error already reported; back off and retry */

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(ALERT_PIN, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

