#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define LOG_FILE       "distance_log.csv"

#define REG_MODEL_ID        0x010F
#define REG_SOFT_RESET      0x0000
#define REG_SYSTEM_MODE_START 0x0007
#define REG_SYSRANGE_START  0x0000
#define REG_RESULT_INT_STATUS 0x013
#define REG_RESULT_RANGE_STATUS 0x078
#define REG_SYSTEM_INTERRUPT_CLEAR 0x014

#define EXPECTED_MODEL_ID   0xEA
#define RANGE_TIMEOUT_MS    100
#define POLL_INTERVAL_US    100000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int write_reg16(int handle, uint16_t reg, uint8_t val)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)val;
    return i2cWriteDevice(handle, buf, 3);
}

static int read_reg16(int handle, uint16_t reg, uint8_t *val)
{
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, (char *)val, 1) != 1)
        return -1;
    return 0;
}

static int read_reg16_16(int handle, uint16_t reg, uint16_t *val)
{
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0)
        return -1;
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;
    *val = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int init_vl53l1x(int handle)
{
    uint8_t model_id = 0;
    if (read_reg16(handle, REG_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Error: failed to read model ID\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X)\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }
    printf("VL53L1X detected (model ID 0x%02X)\n", model_id);

    if (write_reg16(handle, REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: soft reset write failed\n");
        return -1;
    }
    gpioDelay(2000);

    if (write_reg16(handle, REG_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error: failed to start ranging\n");
        return -1;
    }

    uint8_t status = 0;
    int waited = 0;
    while (waited < RANGE_TIMEOUT_MS) {
        if (read_reg16(handle, REG_SYSRANGE_START, &status) < 0) {
            fprintf(stderr, "Error: failed to read SYSRANGE_START\n");
            return -1;
        }
        if ((status & 0x01) == 0)
            break;
        gpioDelay(1000);
        waited++;
    }
    if (waited >= RANGE_TIMEOUT_MS) {
        fprintf(stderr, "Error: ranging did not start within timeout\n");
        return -1;
    }
    printf("VL53L1X ranging started\n");
    return 0;
}

static int read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t int_status = 0;
    if (read_reg16(handle, REG_RESULT_INT_STATUS, &int_status) < 0)
        return -1;
    if ((int_status & 0x01) == 0)
        return 1;

    uint16_t dist = 0;
    if (read_reg16_16(handle, REG_RESULT_RANGE_STATUS, &dist) < 0)
        return -1;

    if (write_reg16(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    *distance_mm = dist;
    return 0;
}

static void log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%u\n", ts, distance_mm);
    fflush(fp);
}

static void check_distance(uint16_t distance_mm)
{
    if (distance_mm < 300)
        printf("STOP\n");
    else if (distance_mm < 600)
        printf("APPROACH\n");
    else if (distance_mm < 1200)
        printf("SLOW\n");
    else
        printf("CLEAR\n");
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_vl53l1x(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open %s\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(g_log_file, 0, SEEK_END);
    long fsize = ftell(g_log_file);
    if (fsize == 0)
        fprintf(g_log_file, "timestamp,distance_mm\n");

    printf("Parking assistance started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance = 0;
        int rc = read_distance(g_i2c_handle, &distance);
        if (rc == 0) {
            log_distance(g_log_file, distance);
            check_distance(distance);
        } else if (rc < 0) {
            fprintf(stderr, "Warning: I2C read error\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (g_log_file)
        fclose(g_log_file);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

