}

static int read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t int_status = 0;
    if (read_reg16(handle, REG_RESULT_INT_STATUS, &int_status) < 0)
        return -1;
    if ((int_status & 0x01) == 0)
        return 1;

    uint16_t dist = 0;
    if (read_reg16_16(handle, REG_RESULT_RANGE_STATUS, &dist) < 0)
        return -1;

    if (write_reg16(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    *distance_mm = dist;
    return 0;
}

static void log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%u\n", ts, distance_mm);
    fflush(fp);
}

static void check_distance(uint16_t distance_mm)
{
    if (distance_mm < 300)
        printf("STOP\n");
    else if (distance_mm < 600)
        printf("APPROACH\n");
    else if (distance_mm < 1200)
        printf("SLOW\n");
    else
        printf("CLEAR\n");
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_vl53l1x(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open %s\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(g_log_file, 0, SEEK_END);
    long fsize = ftell(g_log_file);
    if (fsize == 0)
        fprintf(g_log_file, "timestamp,distance_mm\n");

    printf("Parking assistance started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance = 0;
        int rc = read_distance(g_i2c_handle, &distance);
        if (rc == 0) {
            log_distance(g_log_file, distance);
            check_distance(distance);
        } else if (rc < 0) {
            fprintf(stderr, "Warning: I2C read error\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (g_log_file)
        fclose(g_log_file);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

