#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x45
#define LED_GPIO       18
#define SAMPLE_US      100000   /* 100 ms */
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000    /* 10 ms */

/* CH201 register addresses (from datasheet) */
#define REG_RESULT_STATUS  0x00
#define REG_RESULT_DISTANCE 0x02
#define REG_CONFIG_REG     0x04
#define REG_MEAS_CMD       0x05

/* Config: 12-bit resolution, 100 Hz measurement rate, continuous mode */
#define CONFIG_VALUE       0x0000

/* Measurement command: start continuous ranging */
#define MEAS_CMD_VALUE     0x01

/* Status bits */
#define STATUS_DATA_READY  0x01

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit value to a 16-bit-addressed register (big-endian on wire). */
static int i2c_write_reg16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);
    return i2cWriteDevice(handle, buf, 3);
}

/* Read a 16-bit value from a 16-bit-addressed register. */
static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char cmd = (char)reg;
    if (i2cWriteDevice(handle, &cmd, 1) != 0)
        return -1;

    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* Read distance with retries. Returns 0 on success, -1 on failure. */
static int read_distance(int handle, uint16_t *distance_mm)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        uint16_t status = 0;
        if (i2c_read_reg16(handle, REG_RESULT_STATUS, &status) != 0) {
            fprintf(stderr, "I2C read status failed (attempt %d)\n", attempt + 1);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (status & STATUS_DATA_READY) {
            uint16_t dist = 0;
            if (i2c_read_reg16(handle, REG_RESULT_DISTANCE, &dist) != 0) {
                fprintf(stderr, "I2C read distance failed (attempt %d)\n", attempt + 1);
                gpioDelay(RETRY_DELAY_US);
                continue;
            }
            *distance_mm = dist;
            return 0;
        }
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* Map distance to blink frequency (Hz). */
static double map_distance_to_frequency(uint16_t distance_mm)
{
    if (distance_mm < 50) return 10.0;
    if (distance_mm > 500) return 1.0;
    return 10.0 - (double)distance_mm / 50.0;
}

/* Half-cycle: turn LED on or off, hold for remainder of 100 ms. */
static void blink_led_half_cycle(int gpio, double frequency)
{
    if (frequency <= 0.0) {
        gpioWrite(gpio, 0);
        gpioDelay((uint32_t)(SAMPLE_US * 0.9));
        return;
    }

    double period_us = 1000000.0 / frequency;
    double half_period_us = period_us / 2.0;

    if (half_period_us < 1000) half_period_us = 1000;

    gpioWrite(gpio, 1);
    gpioDelay((uint32_t)half_period_us);
    gpioWrite(gpio, 0);
    gpioDelay((uint32_t)(SAMPLE_US - half_period_us));
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Configure sensor: 12-bit, 100 Hz, continuous */
    if (i2c_write_reg16(g_i2c_handle, REG_CONFIG_REG, CONFIG_VALUE) != 0) {
        fprintf(stderr, "Failed to write config register\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start continuous ranging */
    if (i2c_write_reg16(g_i2c_handle, REG_MEAS_CMD, MEAS_CMD_VALUE) != 0) {
        fprintf(stderr, "Failed to start measurements\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("CH201 ranging started. Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance_mm = 0;
        if (read_distance(g_i2c_handle, &distance_mm) != 0) {
            fprintf(stderr, "Distance read failed after %d retries\n", MAX_RETRIES);
            gpioDelay(SAMPLE_US);
            continue;
        }

        double frequency = map_distance_to_frequency(distance_mm);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);

        printf("%s  Distance: %u mm  Blink: %.2f Hz\n", ts, distance_mm, frequency);
        fflush(stdout);

        blink_led_half_cycle(LED_GPIO, frequency);
    }

    /* Cleanup */
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

