#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CH101_ADDR     0x49

#define REG_MEAS_TRIGGER 0x04
#define REG_MEAS_STATUS  0x06
#define REG_DIST_HIGH    0x08
#define REG_DIST_LOW     0x09

#define STATUS_DATA_READY 0x01
#define STATUS_ERROR      0x02

#define MEAS_TIMEOUT_MS   50
#define SAMPLE_PERIOD_MS  500

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int ch101_init(int fd)
{
    if (i2c_write_reg8(fd, REG_MEAS_TRIGGER, 0x00) < 0)
        return -1;
    usleep(10000);
    return 0;
}

static int ch101_read_distance(int fd, uint16_t *distance_mm)
{
    if (i2c_write_reg8(fd, REG_MEAS_TRIGGER, 0x01) < 0)
        return -1;

    for (int elapsed = 0; elapsed < MEAS_TIMEOUT_MS; elapsed += 2) {
        uint8_t status;
        if (i2c_read_reg8(fd, REG_MEAS_STATUS, &status) < 0)
            return -1;
        if (status & STATUS_DATA_READY) {
            uint8_t hi, lo;
            if (i2c_read_reg8(fd, REG_DIST_HIGH, &hi) < 0)
                return -1;
            if (i2c_read_reg8(fd, REG_DIST_LOW, &lo) < 0)
                return -1;
            *distance_mm = ((uint16_t)hi << 8) | (uint16_t)lo;
            return 0;
        }
        if (status & STATUS_ERROR) {
            fprintf(stderr, "CH101 measurement error (status=0x%02X)\n", status);
            return -1;
        }
        usleep(2000);
    }
    fprintf(stderr, "CH101 measurement timeout\n");
    return -1;
}

static void log_data(FILE *fp, uint16_t distance)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%u\n", ts, (unsigned)distance);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                CH101_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    if (ch101_init(g_i2c_fd) < 0) {
        fprintf(stderr, "CH101 init failed\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    g_log_fp = fopen("distance_log.csv", "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(distance_log.csv) failed: %s\n", strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    while (g_running) {
        uint16_t dist;
        if (ch101_read_distance(g_i2c_fd, &dist) == 0) {
            log_data(g_log_fp, dist);
        } else {
            fprintf(stderr, "Measurement failed; skipping sample.\n");
        }
        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

