#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x4C
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define POLL_INTERVAL_MS 100

/* MLX75030 register addresses (from datasheet) */
#define REG_DISTANCE 0x00
#define REG_CONFIG   0x01

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read a 16-bit big-endian register from the MLX75030.
 * Returns 0 on success, -1 on failure.
 */
static int read_register16(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    int result;

    result = i2cWriteByte(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error writing register address 0x%02X: %d\n", reg, result);
        return -1;
    }

    gpioDelay(1000); /* 1 ms settle delay */

    result = i2cReadDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading register 0x%02X: expected 2 bytes, got %d\n", reg, result);
        return -1;
    }

    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int read_distance(int handle, uint16_t *distance) {
    int retries = 0;
    int result;

    while (retries < RETRY_COUNT) {
        result = read_register16(handle, REG_DISTANCE, distance);
        if (result == 0) {
            return 0;
        }
        retries++;
        if (retries < RETRY_COUNT) {
            gpioDelay(RETRY_DELAY_MS * 1000);
        }
    }

    fprintf(stderr, "Failed to read distance after %d retries.\n", RETRY_COUNT);
    return -1;
}

static void log_distance(uint16_t distance) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    printf("[%s.%03ld] Distance: %u mm\n", timestamp, ts.tv_nsec / 1000000, distance);
    fflush(stdout);
}

int main(void) {
    uint16_t distance;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d, addr 0x%02X: %d\n",
                I2C_BUS, MLX75030_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /*
     * Configure the MLX75030.
     * A full configuration sequence is required per the datasheet.
     * This simplified sequence initializes the sensor and sets a basic range.
     */
    if (i2cWriteByteData(i2c_handle, REG_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error writing config register 0x01\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(10000); /* 10 ms settle */

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX75030 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_distance(i2c_handle, &distance) == 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }
        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

