static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* Write a 16-bit register address followed by one 8-bit data byte.
   Returns 0 on success, -1 on I2C error. */
static int vl53l4cx_write_reg8(uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    if (i2cWriteDevice(i2c_handle, buf, 3) != 3) {
        fprintf(stderr, "Error: I2C write to register 0x%04X failed.\n", reg);
        return -1;
    }
    return 0;
}

/* Read a 16-bit register address followed by one 8-bit data byte.
   Returns the byte value, or -1 on error. */
static int vl53l4cx_read_reg8(uint16_t reg)
{
    char addr_buf[2];
    char data_buf[1];

    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(i2c_handle, addr_buf, 2) != 2) {
        fprintf(stderr, "Error: I2C write (address) for register 0x%04X failed.\n", reg);
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data_buf, 1) != 1) {
        fprintf(stderr, "Error: I2C read from register 0x%04X failed.\n", reg);
        return -1;
    }

    return (uint8_t)data_buf[0];
}

/* Read a 16-bit register (two consecutive 8-bit registers).
   Returns the 16-bit value, or -1 on error. */
static int vl53l4cx_read_reg16(uint16_t reg)
{
    char addr_buf[2];
    char data_buf[2];

    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(i2c_handle, addr_buf, 2) != 2) {
        fprintf(stderr, "Error: I2C write (address) for register 0x%04X failed.\n", reg);
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data_buf, 2) != 2) {
        fprintf(stderr, "Error: I2C read from register 0x%04X failed.\n", reg);
        return -1;
    }

    return ((uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
}

/* Initialize the VL53L4CX sensor. Returns 0 on success, -1 on error. */
static int vl53l4cx_init(void)
{
    /* Soft reset: write 0x00 to register 0x7FFF */
    if (vl53l4cx_write_reg8(VL53L4CX_REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "Error: VL53L4CX soft reset failed.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Start ranging: write 0x00 to register 0x0009 */
    if (vl53l4cx_write_reg8(VL53L4CX_REG_SYSTEM_START, 0x00) != 0) {
        fprintf(stderr, "Error: VL53L4CX ranging start failed.\n");
        return -1;
    }

    return 0;
}

/* Read distance from the VL53L4CX. Returns distance in mm on success, -1 on error. */
static int vl53l4cx_read_distance(void)
{
    int status;
    int distance;

    /* Check interrupt status register (0x0046), bit 0 */
    status = vl53l4cx_read_reg8(VL53L4CX_REG_INT_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read interrupt status.\n");
        return -1;
    }

    if ((status & 0x01) == 0) {
        return -1; /* No new data available yet */
    }

    /* Read distance: high byte from 0x0096, low byte from 0x0097 */
    distance = vl53l4cx_read_reg16(VL53L4CX_REG_RESULT_DIST_HIGH);
    if (distance < 0) {
        fprintf(stderr, "Error: Failed to read distance data.\n");
        return -1;
    }

    return distance;
}

/* Get a timestamp string with microsecond precision. */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(buf + strlen(buf), len - strlen(buf), ".%06ld", ts.tv_nsec / 1000);
}

int main(void)
{
    char timestamp[32];

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    /* Open I2C bus 1 at address 0x29 */
    i2c_handle = i2cOpen(I2C_BUS, VL53L4CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n",
                I2C_BUS, VL53L4CX_ADDR);
        gpioTerminate();
        return 1;
    }

    /* Initialize the VL53L4CX sensor */
    if (vl53l4cx_init() != 0) {
        fprintf(stderr, "Error: VL53L4CX initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Install signal handlers for graceful shutdown */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("VL53L4CX distance sensor reading started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        int distance = vl53l4cx_read_distance();

        if (distance >= 0) {
            get_timestamp(timestamp, sizeof(timestamp));
            printf("Timestamp: %s, Distance: %d mm\n", timestamp, distance);
            fflush(stdout);
        }

        gpioDelay(500000); /* 500 ms */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

