#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100
#define POLL_INTERVAL_US 500000

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_REG_SOFT_RESET              0x0001
#define VL53L1X_REG_I2C_SLAVE_DEVICE_ADDR   0x0001
#define VL53L1X_REG_SYSTEM_MODE_START       0x0007
#define VL53L1X_REG_RESULT_FINAL_DIST_MM    0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a 16-bit register address followed by a 16-bit value (big-endian). */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

/* Read a 16-bit register: write address, then read 2 bytes. */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char addr[2];
    char data[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) != 0) return -1;
    if (i2cReadDevice(handle, data, 2) != 2) return -1;
    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int init_vl53l1x(int handle) {
    /* Soft reset: write 0x0000 to SOFT_RESET */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x0000) != 0) {
        fprintf(stderr, "Error: VL53L1X soft reset write failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Set I2C slave address to default 0x29 */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_I2C_SLAVE_DEVICE_ADDR, 0x29) != 0) {
        fprintf(stderr, "Error: VL53L1X set I2C address failed\n");
        return -1;
    }

    /* Start continuous ranging mode */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x0001) != 0) {
        fprintf(stderr, "Error: VL53L1X start ranging failed\n");
        return -1;
    }

    gpioDelay(10000); /* 10 ms for first measurement */
    return 0;
}

static int read_distance(int handle, uint16_t *distance_mm) {
    return vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_FINAL_DIST_MM, distance_mm);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at 0x%02X on bus %d\n",
                VL53L1X_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_vl53l1x(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    uint16_t distance;
    int consecutive_errors = 0;

    while (running) {
        if (read_distance(i2c_handle, &distance) == 0) {
            consecutive_errors = 0;
            printf("Distance: %u mm\n", distance);

            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(BUZZER_GPIO, 1);
            } else {
                gpioWrite(BUZZER_GPIO, 0);
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Error: I2C read failed (consecutive: %d)\n", consecutive_errors);
            if (consecutive_errors >= 5) {
                fprintf(stderr, "Error: Too many consecutive I2C failures, re-initialising sensor...\n");
                i2cClose(i2c_handle);
                i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
                if (i2c_handle < 0) {
                    fprintf(stderr, "Error: Could not re-open I2C device\n");
                    break;
                }
                if (init_vl53l1x(i2c_handle) != 0) {
                    fprintf(stderr, "Error: VL53L1X re-initialisation failed\n");
                    break;
                }
                consecutive_errors = 0;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

