    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo stuck low (timeout)\n");
            return ERROR_DISTANCE;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout if stuck high) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo stuck high (timeout)\n");
            return ERROR_DISTANCE;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance_cm = (float)pulse_us * 34300.0f / 2.0f / 1000000.0f;

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range\n", distance_cm);
