static int map_distance_to_angle(float distance_cm)
{
    if (distance_cm <= MIN_DISTANCE_CM) return MIN_ANGLE_DEG;
    if (distance_cm >= MAX_DISTANCE_CM) return MAX_ANGLE_DEG;

    float normalized = (distance_cm - MIN_DISTANCE_CM) /
                       (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    return (int)(MIN_ANGLE_DEG + normalized * (MAX_ANGLE_DEG - MIN_ANGLE_DEG));
}

static int angle_to_pulse_us(int angle_deg)
{
