    if (angle_deg > MAX_ANGLE_DEG) angle_deg = MAX_ANGLE_DEG;

    return SERVO_MIN_PULSE_US +
           (int)((float)(angle_deg - MIN_ANGLE_DEG) *
                 (SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US) /
                 (MAX_ANGLE_DEG - MIN_ANGLE_DEG));
}

static void log_data(float distance_cm, int angle_deg)
{
    FILE *fp = fopen("sensor_data.log", "a");
    if (!fp) {
        perror("Error opening sensor_data.log");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %.2f cm, Angle: %d deg\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                distance_cm, angle_deg);
    } else {
