        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: sigaction failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set servo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000); /* 100 ms settle */

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = measure_distance();

        if (distance == ERROR_DISTANCE) {
            fprintf(stderr, "Error: distance measurement failed\n");
        } else {
            int angle = map_distance_to_angle(distance);
            int pulse_us = angle_to_pulse_us(angle);

            if (gpioServo(SERVO_PIN, pulse_us) < 0) {
                fprintf(stderr, "Error: failed to set servo pulse\n");
            }

            log_data(distance, angle);
            printf("Distance: %.2f cm, Angle: %d deg, Pulse: %d us\n",
                   distance, angle, pulse_us);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Graceful shutdown: stop servo, release resources */
    gpioServo(SERVO_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();

    printf("\nParking Assist System stopped.\n");
    return EXIT_SUCCESS;
}

