#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/msg.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100
#define POLL_TIMEOUT_MS 100
#define MSG_QUEUE_KEY 1234
#define MSG_QUEUE_SIZE 10

#define REG_MODEL_ID 0x010F
#define REG_SOFT_RESET 0x0000
#define REG_SYSTEM_START 0x0080
#define REG_RANGE_STATUS 0x0089
#define REG_DISTANCE 0x0096
#define REG_TIMING_BUDGET 0x0000

#define EXPECTED_MODEL_ID 0xEA

typedef struct {
    long mtype;
    int distance;
} distance_msg_t;

static int i2c_handle = -1;
static int msg_queue_id = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *data, int len) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) return -1;
    return i2cReadDevice(handle, (char *)data, len);
}

static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, REG_MODEL_ID, &model_id, 1) != 1) {
        fprintf(stderr, "Error: Failed to read model ID: %s\n", strerror(errno));
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: Unexpected model ID 0x%02X (expected 0x%02X)\n", model_id, EXPECTED_MODEL_ID);
        return -1;
    }
    printf("VL53L1X detected (model ID 0x%02X)\n", model_id);

    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "Error: Software reset write failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1000);
    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x01) != 0) {
        fprintf(stderr, "Error: Software reset release failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1000);

    if (i2c_write_reg16(handle, REG_TIMING_BUDGET, 0x0028) != 0) {
        fprintf(stderr, "Error: Timing budget write failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1000);

    if (i2c_write_reg16(handle, REG_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "Error: Ranging start write failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1000);
    return 0;
}

static int read_distance(int handle, int *distance) {
    uint8_t status = 0;
    int timeout = 0;
    while (timeout < POLL_TIMEOUT_MS) {
        if (i2c_read_reg16(handle, REG_RANGE_STATUS, &status, 1) != 1) {
            fprintf(stderr, "Error: Failed to read range status: %s\n", strerror(errno));
            return -1;
        }
        if (status & 0x01) break;
        gpioDelay(1000);
        timeout++;
    }
    if (timeout >= POLL_TIMEOUT_MS) {
        fprintf(stderr, "Error: Data not ready after timeout\n");
        return -1;
    }
    uint8_t dist_data[2];
    if (i2c_read_reg16(handle, REG_DISTANCE, dist_data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read distance: %s\n", strerror(errno));
        return -1;
    }
    *distance = (dist_data[0] << 8) | dist_data[1];
    return 0;
}

static void log_distance(int distance) {
    distance_msg_t msg;
    msg.mtype = 1;
    msg.distance = distance;
    if (msgsnd(msg_queue_id, &msg, sizeof(distance_msg_t), IPC_NOWAIT) == -1) {
        fprintf(stderr, "Warning: Failed to send message to queue: %s\n", strerror(errno));
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    msg_queue_id = msgget(MSG_QUEUE_KEY, IPC_CREAT | 0666);
    if (msg_queue_id == -1) {
        fprintf(stderr, "Error: msgget failed: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct msqid_ds queue_info;
    if (msgctl(msg_queue_id, IPC_STAT, &queue_info) == -1) {
        fprintf(stderr, "Error: msgctl IPC_STAT failed: %s\n", strerror(errno));
        msg_queue_id = -1;
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (queue_info.msg_qnum == 0) {
        fprintf(stderr, "Warning: Message queue is empty\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting distance measurement...\n");
    while (!terminate) {
        int distance = 0;
        if (read_distance(i2c_handle, &distance) == 0) {
            printf("Distance: %d mm\n", distance);
            log_distance(distance);
            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(BUZZER_GPIO, 1);
            } else {
                gpioWrite(BUZZER_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Error: Failed to read distance\n");
        }
        gpioDelay(50000);
    }

    printf("\nCleaning up...\n");
    gpioWrite(BUZZER_GPIO, 0);
    if (msg_queue_id != -1) msgctl(msg_queue_id, IPC_RMID, NULL);
    if (i2c_handle != -1) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

