static void log_distance(int distance) {
    distance_msg_t msg;
    msg.mtype = 1;
    msg.distance = distance;
    if (msgsnd(msg_queue_id, &msg, sizeof(distance_msg_t), IPC_NOWAIT) == -1) {
        fprintf(stderr, "Warning: Failed to send message to queue: %s\n", strerror(errno));
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    msg_queue_id = msgget(MSG_QUEUE_KEY, IPC_CREAT | 0666);
    if (msg_queue_id == -1) {
        fprintf(stderr, "Error: msgget failed: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

