        gpioTerminate();
        return 1;
    }
    if (queue_info.msg_qnum == 0) {
        fprintf(stderr, "Warning: Message queue is empty\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting distance measurement...\n");
    while (!terminate) {
        int distance = 0;
        if (read_distance(i2c_handle, &distance) == 0) {
            printf("Distance: %d mm\n", distance);
            log_distance(distance);
            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(BUZZER_GPIO, 1);
            } else {
                gpioWrite(BUZZER_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Error: Failed to read distance\n");
        }
        gpioDelay(50000);
    }

    printf("\nCleaning up...\n");
    gpioWrite(BUZZER_GPIO, 0);
    if (msg_queue_id != -1) msgctl(msg_queue_id, IPC_RMID, NULL);
    if (i2c_handle != -1) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

