#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define BUZZER_PIN  22

#define SPEED_OF_SOUND_CM_S  34300.0
#define TRIGGER_PULSE_US     10
#define ECHO_TIMEOUT_US      30000   /* 30 ms — covers ~5 m round trip */
#define LOOP_DELAY_US        100000  /* 100 ms */
#define DISTANCE_THRESHOLD_CM 30.0
#define MIN_VALID_CM          2.0
#define MAX_VALID_CM          400.0

static volatile sig_atomic_t running = 1;
static volatile uint32_t echo_start_tick = 0;
static volatile uint32_t echo_end_tick   = 0;
static volatile int      echo_done       = 0;
static volatile int      echo_error      = 0;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * pigpio alert callback for the echo pin.
 * level: 0 = falling edge (start of echo), 1 = rising edge (end of echo)
 * tick:  32-bit microsecond counter (wraps every ~71.6 min)
 */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        echo_end_tick = tick;
        echo_done = 1;
    } else if (level == 0) {
        echo_start_tick = tick;
    }
}

/*
 * Send a 10 us trigger pulse.
 * Returns 0 on success, -1 on write failure.
 */
static int trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1;
    }
    gpioDelay(5);
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1;
    }
    return 0;
}

/*
 * Compute distance in cm from echo pulse width.
 * Handles 32-bit tick wraparound.
 * Returns -1.0 on error (no echo or invalid pulse).
 */
static double calculate_distance(uint32_t start_tick, uint32_t end_tick)
{
    uint32_t pulse_us;
    if (end_tick >= start_tick) {
        pulse_us = end_tick - start_tick;
    } else {
        pulse_us = (0xFFFFFFFFu - start_tick) + end_tick + 1u;
    }

    /*
     * Speed of sound: 34300 cm/s = 0.0343 cm/us.
     * Distance = (pulse_us * speed) / 2  (round trip).
     */
    double distance = (double)pulse_us * SPEED_OF_SOUND_CM_S / 2000000.0;
    return distance;
}

static void control_buzzer(double distance)
{
    if (distance < DISTANCE_THRESHOLD_CM) {
        if (gpioWrite(BUZZER_PIN, 1) < 0) {
            fprintf(stderr, "Error: gpioWrite(BUZZER, 1) failed\n");
        }
    } else {
        if (gpioWrite(BUZZER_PIN, 0) < 0) {
            fprintf(stderr, "Error: gpioWrite(BUZZER, 0) failed\n");
        }
    }
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO modes --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO, INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Ensure trigger starts LOW --- */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) init failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Register echo alert callback --- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking sensor ready. Trigger=GPIO%d, Echo=GPIO%d, Buzzer=GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main measurement loop --- */
    while (running) {
        echo_done = 0;
        echo_error = 0;
        echo_start_tick = 0;
        echo_end_tick = 0;

        if (trigger_sensor() < 0) {
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        /* Wait for echo with timeout */
        uint32_t wait_start = gpioTick();
        while (!echo_done && running) {
            if ((gpioTick() - wait_start) > ECHO_TIMEOUT_US) {
                echo_error = 1;
                break;
            }
            gpioDelay(100);
        }

        if (echo_error) {
            fprintf(stderr, "Error: Echo timeout — sensor absent or wiring fault\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        if (!echo_done) {
            fprintf(stderr, "Error: No echo received after trigger\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        double distance = calculate_distance(echo_start_tick, echo_end_tick);

        if (distance < MIN_VALID_CM || distance > MAX_VALID_CM) {
            fprintf(stderr, "Warning: Distance %.2f cm out of valid range [%.1f, %.1f]\n",
                    distance, MIN_VALID_CM, MAX_VALID_CM);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        printf("Distance: %.2f cm\n", distance);
        control_buzzer(distance);

        gpioDelay(LOOP_DELAY_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

