    *val = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int init_vl53l1x(void) {
    if (vl53l1x_write(VL53L1X_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (vl53l1x_write(VL53L1X_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(10000);
    if (vl53l1x_write(VL53L1X_SYSTEM_START, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (vl53l1x_write(VL53L1X_SYSTEM_START, 0x01) != 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int read_distance(void) {
    uint16_t dist;
    if (vl53l1x_read16(VL53L1X_RESULT_DISTANCE, &dist) != 0) return -1;
    return (int)dist;
}

static void set_servo(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int us = SERVO_CLOSE_US + (angle * (SERVO_OPEN_US - SERVO_CLOSE_US) / 180);
    gpioServo(SERVO_PIN, us);
}

static void open_gate(void) {
    set_servo(90);
    gate_state = 1;
    log_event("Gate opened");
}

static void close_gate(void) {
    set_servo(0);
    gate_state = 0;
    log_event("Gate closed");
}

static void handle_command(const char *cmd) {
    if (strcmp(cmd, "force_open") == 0) {
        open_gate();
    } else if (strcmp(cmd, "force_close") == 0) {
        close_gate();
    } else if (strcmp(cmd, "status_request") == 0) {
        char resp[64];
        snprintf(resp, sizeof(resp), "Gate is %s", gate_state ? "open" : "closed");
        char *msg = malloc(strlen(resp) + 1);
        if (msg) {
            strcpy(msg, resp);
            int rc = mqtt_publish(MQTT_TOPIC, msg, strlen(msg), 0);
            free(msg);
        }
    }
}

static void cleanup(void) {
    close_gate();
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file) fclose(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        log_event("I2C open failed");
        cleanup();
        return 1;
    }

    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X init failed\n");
        log_event("VL53L1X init failed");
        cleanup();
        return 1;
    }

    set_servo(0);
    log_event("Gate controller started");

    while (running) {
        int dist = read_distance();
        if (dist < 0) {
            fprintf(stderr, "Read error, retrying...\n");
            log_event("Sensor read error");
            gpioDelay(1000000);
            continue;
        }
        if (dist < DISTANCE_THRESHOLD && gate_state == 0) {
            open_gate();
        } else if (dist > DISTANCE_THRESHOLD && gate_state == 1) {
            close_gate();
        }
        gpioDelay(500000);
    }

    cleanup();
    return 0;
}

