/*
 * HC-SR04 Ultrasonic Distance Measurement — Raspberry Pi 4 Model B
 *
 * Wiring:
 *   TRIG -> GPIO 23 (BCM 23, physical pin 16)
 *   ECHO -> GPIO 24 (BCM 24, physical pin 18) via 5V->3.3V voltage divider
 *
 * The HC-SR04 ECHO output is 5V; the Raspberry Pi GPIO pins are 3.3V tolerant.
 * A voltage divider (e.g., 1k/2k) on the ECHO line brings the signal down to
 * a safe level.  A pull-down resistor on ECHO ensures a clean LOW when the
 * sensor is idle.
 *
 * Build:  gcc -O2 -Wall -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIG_PIN        23
#define ECHO_PIN        24

#define TRIG_PULSE_US   10          /* 10 us trigger pulse            */
#define SAMPLE_PERIOD_US 200000     /* 200 ms between measurements    */
#define ECHO_TIMEOUT_US 60000       /* 60 ms max echo wait            */
#define MIN_PULSE_US    100         /* noise/invalid threshold        */
#define MAX_PULSE_US    30000       /* timeout / no-object threshold  */
#define SOUND_SPEED_CM_US 0.0343  /* 343 m/s in cm/us               */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Echo callback — pigpio ticks are 32-bit microseconds (wraps ~72 min) */
/* ------------------------------------------------------------------ */
static volatile uint32_t g_rise_tick = 0;
static volatile uint32_t g_fall_tick = 0;
static volatile bool     g_got_rise = false;
static volatile bool     g_got_fall = false;

static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        g_rise_tick  = tick;
        g_got_rise   = true;
        g_got_fall   = false;
    } else if (level == 0 && g_got_rise) {
        g_fall_tick  = tick;
        g_got_fall   = true;
    }
}

/* ------------------------------------------------------------------ */
/* Distance measurement                                                 */
/* ------------------------------------------------------------------ */
static double measure_distance(void)
{
    g_rise_tick  = 0;
    g_fall_tick  = 0;
    g_got_rise   = false;
    g_got_fall   = false;

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 0) failed\n");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIG_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 1) failed\n");
        return -1.0;
    }
    gpioDelay(TRIG_PULSE_US);
    if (gpioWrite(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 0) failed\n");
        return -1.0;
    }

    /* Wait for echo with timeout */
    uint32_t waited = 0;
    while (!g_got_fall && waited < ECHO_TIMEOUT_US) {
        gpioDelay(100);
        waited += 100;
    }

    if (!g_got_fall) {
        return -1.0; /* timeout / no object */
    }

    /* pigpio ticks are 32-bit; handle wraparound */
    uint32_t pulse_us = g_fall_tick - g_rise_tick;

    if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
        return -1.0; /* noise or out-of-range */
    }

    return (double)pulse_us * SOUND_SPEED_CM_US / 2.0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_reading(double distance)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    if (distance >= 0.0) {
        printf("[%s] Distance: %.2f cm\n", ts, distance);
        if (g_log_fp) {
            fprintf(g_log_fp, "%s, Distance: %.2f cm\n", ts, distance);
            fflush(g_log_fp);
        }
    } else {
        fprintf(stderr, "[%s] WARNING: Invalid reading (timeout or noise)\n", ts);
        if (g_log_fp) {
            fprintf(g_log_fp, "%s, WARNING: Invalid reading (timeout or noise)\n", ts);
            fflush(g_log_fp);
        }
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO configuration --- */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIG) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(50);

    /* --- Register echo alert callback --- */
    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFunc(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_fp = fopen("distance_log.txt", "a");
    if (!g_log_fp) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        double dist = measure_distance();
        log_reading(dist);
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

