code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define MOTOR_FORWARD_PIN 17
#define MOTOR_BACKWARD_PIN 18
#define TRIGGER_PIN 24

#define DISTANCE_THRESHOLD_LOW 100
#define DISTANCE_THRESHOLD_HIGH 300

#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    int result = i2cWriteDevice(handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "I2C write error (reg 0x%04X): %d\n", reg, result);
    }
    return result;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *data, int len) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "I2C write (reg select 0x%04X) error: %d\n", reg, result);
        return result;
    }
    result = i2cReadDevice(handle, (char *)data, len);
    if (result != len) {
        fprintf(stderr, "I2C read error (reg 0x%04X): expected %d, got %d\n", reg, len, result);
    }
    return result;
}

static int vl53l1x_init(int handle) {
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(1000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_START, 0x01) != 0) return -1;
    gpioDelay(1000);
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    uint8_t data[2];
    int retries = 0;
    int delay_ms = 10;

    while (retries < 10) {
        if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_START, 0x01) != 0) {
            retries++;
            gpioDelay(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }
        gpioDelay(1000);

        uint8_t ready = 0;
        int poll_retries = 0;
        while (poll_retries < 50) {
            if (i2c_read_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, &ready, 1) != 1) {
                poll_retries++;
                gpioDelay(1000);
                continue;
            }
            if (ready & 0x01) break;
            poll_retries++;
            gpioDelay(1000);
        }
        if (!(ready & 0x01)) {
            retries++;
            gpioDelay(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }

        if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, data, 2) != 2) {
            retries++;
            gpioDelay(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }

        *distance = ((uint16_t)data[0] << 8) | data[1];
        if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
            fprintf(stderr, "Warning: failed to clear interrupt\n");
        }
        return 0;
    }
    return -1;
}

static void control_motor(int distance) {
    if (distance < DISTANCE_THRESHOLD_LOW) {
        gpioWrite(MOTOR_FORWARD_PIN, 1);
        gpioWrite(MOTOR_BACKWARD_PIN, 0);
        printf("Distance: %d mm - Motor: Forward\n", distance);
    } else if (distance > DISTANCE_THRESHOLD_HIGH) {
        gpioWrite(MOTOR_FORWARD_PIN, 0);
        gpioWrite(MOTOR_BACKWARD_PIN, 1);
        printf("Distance: %d mm - Motor: Backward\n", distance);
    } else {
        gpioWrite(MOTOR_FORWARD_PIN, 0);
        gpioWrite(MOTOR_BACKWARD_PIN, 0);
        printf("Distance: %d mm - Motor: Stop\n", distance);
    }
}

static void trigger_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    uint16_t distance;
    if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
        control_motor(distance);
    } else {
        fprintf(stderr, "Failed to read distance from VL53L1X\n");
        gpioWrite(MOTOR_FORWARD_PIN, 0);
        gpioWrite(MOTOR_BACKWARD_PIN, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", VL53L1X_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);
    gpioSetMode(TRIGGER_PIN, PI_INPUT);

    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);

    if (gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, trigger_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
