static void set_led_pattern(int electrode) {
    if (electrode < 0 || electrode >= NUM_ELECTRODES) return;
    for (int i = 0; i < 4; i++) {
        int val = proximity_patterns[electrode][i];
        if (gpiod_line_set_value(led_lines[i], val) < 0) {
            fprintf(stderr, "Failed to set LED %d: %s\n", i, strerror(errno));
        }
    }
}

static void cleanup(void) {
    for (int i = 0; i < 4; i++) {
        if (led_lines[i]) {
            gpiod_line_set_value(led_lines[i], 0);
            gpiod_line_release(led_lines[i]);
            led_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    log_file = fopen("proximity_log.txt", "a");
    if (!log_file) {
        perror("fopen log");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        fclose(log_file);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", MPR121_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        led_lines[i] = gpiod_chip_get_line(chip, led_pins[i]);
        if (!led_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", led_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(led_lines[i], "mpr121_proximity", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", led_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
    }

    log_event("System started");

    while (running) {
        uint16_t touch_status;
        if (read_touch_status(&touch_status) < 0) {
            log_event("Error reading touch status");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        int active_electrode = -1;
        for (int i = 0; i < NUM_ELECTRODES; i++) {
            if (touch_status & (1 << i)) {
                active_electrode = i;
                break;
            }
        }

        if (active_electrode >= 0) {
            set_led_pattern(active_electrode);
            char msg[128];
            snprintf(msg, sizeof(msg), "Electrode %d touched", active_electrode);
            log_event(msg);
        } else {
            for (int i = 0; i < 4; i++) {
                gpiod_line_set_value(led_lines[i], 0);
            }
            log_event("No electrode touched");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    log_event("System shutting down");
    cleanup();
    return 0;
}

