    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, rc=%d\n", reg, rc);
    }
    return rc;
}

static int mpr121_init(void) {
    int id = mpr121_read(MPR121_ID);
    if (id < 0) {
        fprintf(stderr, "Failed to read MPR121 ID\n");
        return -1;
    }
