#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 30000
#define MIN_DISTANCE_CM 2.0f
#define MAX_DISTANCE_CM 400.0f
#define LOG_FILE "distance_log.txt"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_reading(float distance_cm) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    gmtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo);

    if (log_file) {
        fprintf(log_file, "%s,%.2f\n", timestamp, distance_cm);
        fflush(log_file);
    }
}

static void log_error(const char *msg) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    gmtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo);

    if (log_file) {
        fprintf(log_file, "%s,ERROR,%s\n", timestamp, msg);
        fflush(log_file);
    }
    fprintf(stderr, "%s,ERROR,%s\n", timestamp, msg);
}

static int trigger_sensor(struct gpiod_line *trigger_line) {
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    usleep(5);
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
        return -1;
    }
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static float measure_distance(struct gpiod_line *echo_line) {
    struct timespec start, end;
    long long elapsed_us;
    int val;

    if (trigger_sensor(NULL) < 0) {
        return -1.0f;
    }

    /* Wait for echo rising edge */
    clock_gettime(CLOCK_MONOTONIC, &start);
    do {
        val = gpiod_line_get_value(echo_line);
        if (val < 0) {
            fprintf(stderr, "Failed to read echo: %s\n", strerror(errno));
            return -1.0f;
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed_us = (end.tv_sec - start.tv_sec) * 1000000LL +
                     (end.tv_nsec - start.tv_nsec) / 1000LL;
        if (elapsed_us > ECHO_TIMEOUT_US) {
            return -1.0f; /* sensor absent or no echo */
        }
    } while (val == 0);

    /* Measure echo pulse width */
    clock_gettime(CLOCK_MONOTONIC, &start);
    do {
        val = gpiod_line_get_value(echo_line);
        if (val < 0) {
            fprintf(stderr, "Failed to read echo: %s\n", strerror(errno));
            return -1.0f;
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed_us = (end.tv_sec - start.tv_sec) * 1000000LL +
                     (end.tv_nsec - start.tv_nsec) / 1000LL;
        if (elapsed_us > ECHO_TIMEOUT_US) {
            return -1.0f; /* echo stuck high */
        }
    } while (val == 1);

    float pulse_us = (float)elapsed_us;
    float distance_cm = (pulse_us * 0.0343f) / 2.0f;

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        return -1.0f;
    }

    return distance_cm;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger_line = NULL;
    struct gpiod_line *echo_line = NULL;
    int ret = EXIT_FAILURE;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger_line, "hcsr04-trigger", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo_line, "hcsr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    while (program_running) {
        float distance = measure_distance(echo_line);

        if (distance >= 0.0f) {
            log_reading(distance);
        } else {
            log_error("Sensor read error or out of range");
        }

        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

