    clock_gettime(CLOCK_MONOTONIC, &start);
    do {
        val = gpiod_line_get_value(echo_line);
        if (val < 0) {
            fprintf(stderr, "Failed to read echo: %s\n", strerror(errno));
            return -1.0f;
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed_us = (end.tv_sec - start.tv_sec) * 1000000LL +
                     (end.tv_nsec - start.tv_nsec) / 1000LL;
        if (elapsed_us > ECHO_TIMEOUT_US) {
            return -1.0f; /* sensor absent or no echo */
        }
    } while (val == 0);

    /* Measure echo pulse width */
    clock_gettime(CLOCK_MONOTONIC, &start);
    do {
        val = gpiod_line_get_value(echo_line);
        if (val < 0) {
            fprintf(stderr, "Failed to read echo: %s\n", strerror(errno));
            return -1.0f;
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed_us = (end.tv_sec - start.tv_sec) * 1000000LL +
                     (end.tv_nsec - start.tv_nsec) / 1000LL;
        if (elapsed_us > ECHO_TIMEOUT_US) {
            return -1.0f; /* echo stuck high */
        }
    } while (val == 1);

    float pulse_us = (float)elapsed_us;
    float distance_cm = (pulse_us * 0.0343f) / 2.0f;

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        return -1.0f;
    }

    return distance_cm;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger_line = NULL;
    struct gpiod_line *echo_line = NULL;
    int ret = EXIT_FAILURE;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger_line, "hcsr04-trigger", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo_line, "hcsr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    while (program_running) {
        float distance = measure_distance(echo_line);

        if (distance >= 0.0f) {
            log_reading(distance);
        } else {
            log_error("Sensor read error or out of range");
        }

        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

