#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define TRIGGER_PULSE_US 10
#define SAMPLE_INTERVAL_US 1000000  /* 1 second */
#define MIN_PULSE_US 58.0f          /* ~1 cm */
#define MAX_PULSE_US 25000.0f       /* ~4 m  */
#define SPEED_OF_SOUND_M_S 343.0f

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ISR callback context */
typedef struct {
    uint32_t start_tick;
    uint32_t end_tick;
    int      got_start;
    int      got_end;
} echo_ctx_t;

static echo_ctx_t g_echo = {0};

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * ISR: fires on every edge of ECHO_PIN.
 * pigpio ticks are 32-bit microseconds and wrap every ~71.6 min.
 */
static void echo_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    echo_ctx_t *ctx = (echo_ctx_t *)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        ctx->start_tick = tick;
        ctx->got_start = 1;
        ctx->got_end = 0;
    } else if (level == 0 && ctx->got_start) {
        /* Falling edge: echo pulse ends */
        ctx->end_tick = tick;
        ctx->got_end = 1;
    }
}

static void trigger_sensor(void)
{
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIG_PIN, 0);
}

static float calculate_distance(uint32_t pulse_us)
{
    return (float)pulse_us * SPEED_OF_SOUND_M_S / 2e6f;
}

static void log_distance(float distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_fp, "%s, Distance: %.2f cm\n", timestamp, distance * 100.0f);
    fflush(g_log_fp);
}

int main(void)
{
    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIG_PIN %d as output.\n", TRIG_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIG_PIN, 0);
    gpioDelay(50000);  /* 50 ms settle */

    /* --- Open log file --- */
    g_log_fp = fopen("distance_log.txt", "a");
    if (g_log_fp == NULL) {
        perror("Error opening distance_log.txt");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Register ISR on echo pin --- */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_isr, &g_echo) != 0) {
        fprintf(stderr, "Error: failed to register ISR on ECHO_PIN %d.\n", ECHO_PIN);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG=GPIO%d, ECHO=GPIO%d (3.3V-compatible via divider).\n", TRIG_PIN, ECHO_PIN);
    printf("Logging to distance_log.txt every 1 s. Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        trigger_sensor();

        /* Wait for echo ISR to capture a full pulse */
        gpioDelay(100000);  /* 100 ms timeout */

        if (g_echo.got_start && g_echo.got_end) {
            uint32_t pulse_us = g_echo.end_tick - g_echo.start_tick;

            /* Validate pulse width */
            if (pulse_us > 0 && pulse_us < MAX_PULSE_US && pulse_us > MIN_PULSE_US) {
                float distance = calculate_distance(pulse_us);
                log_distance(distance);
                printf("Distance: %.2f cm\n", distance * 100.0f);
            } else {
                fprintf(stderr, "Warning: invalid pulse width %u us (out of range %.0f-%.0f us).\n",
                        pulse_us, MIN_PULSE_US, MAX_PULSE_US);
            }
        } else if (g_echo.got_start) {
            fprintf(stderr, "Warning: echo start received but no end within 100 ms.\n");
        }

        /* Reset ISR context for next cycle */
        g_echo.got_start = 0;
        g_echo.got_end = 0;

        /* Sleep for the remainder of the 1 s interval */
        gpioDelay(SAMPLE_INTERVAL_US - 100000);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);  /* disable ISR */
    gpioWrite(TRIG_PIN, 0);
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

