    *value = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    return 0;
}

static int init_vl53l1x(int handle)
{
    /* Start ranging */
    if (vl53l1x_write_reg(handle, REG_SYSTEM_START, 0x01) != 0) {
        syslog(LOG_ERR, "Failed to start ranging");
        return -1;
    }
    /* Set continuous mode */
    if (vl53l1x_write_reg(handle, REG_SYSTEM_MODE, 0x00) != 0) {
        syslog(LOG_ERR, "Failed to set continuous mode");
        return -1;
    }
    /* No timeout */
    if (vl53l1x_write_reg(handle, 0x0019, 0x00) != 0) {
        syslog(LOG_ERR, "Failed to set timeout");
        return -1;
    }
    return 0;
}

static void log_data(int distance_mm, uint8_t status)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    syslog(LOG_INFO, "Timestamp: %s, Distance: %d mm, Status: 0x%02X",
           timestamp, distance_mm, status);
}

static void log_error(const char *message)
{
    syslog(LOG_ERR, "%s", message);
}

int main(void)
{
    openlog("vl53l1x_sensor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", TRIGGER_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Enable sensor by setting XSHUT high (active-low trigger) */
    if (gpioWrite(TRIGGER_PIN, TRIGGER_ACTIVE_LOW ? 1 : 0) != 0) {
        syslog(LOG_ERR, "Failed to write trigger pin");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device at bus %d addr 0x%02X",
               I2C_BUS, VL53L1X_ADDR);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (init_vl53l1x(g_i2c_handle) != 0) {
        syslog(LOG_ERR, "VL53L1X initialisation failed");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "VL53L1X sensor initialised on I2C bus %d, addr 0x%02X",
           I2C_BUS, VL53L1X_ADDR);

    while (g_running) {
        uint16_t distance = 0;
        uint8_t status = 0;

        if (vl53l1x_read_reg16(g_i2c_handle, REG_DISTANCE, &distance) == 0 &&
            vl53l1x_read_reg(g_i2c_handle, REG_STATUS, &status) == 0) {
            log_data((int)distance, status);
        } else {
            log_error("Failed to read distance or status from VL53L1X");
        }

        gpioDelay(100000); /* 100 ms */
    }

    syslog(LOG_INFO, "Shutting down VL53L1X sensor");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

