#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define GATE_GPIO      24
#define DISTANCE_THRESHOLD_CM 20.0f
#define POLL_DELAY_US  100000  /* 100 ms */

/* VL53L1X register addresses */
#define REG_MODEL_ID        0x010F
#define REG_SYSTEM_MODE     0x0021
#define REG_RANGE_START     0x0015
#define REG_DISTANCE_H      0x0089
#define REG_DISTANCE_L      0x008A

#define EXPECTED_MODEL_ID   0xEA

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */
static void log_message(const char *msg)
{
    if (!g_log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(g_log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* VL53L1X helpers                                                    */
/* ------------------------------------------------------------------ */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;
    return i2cWriteDevice(handle, buf, 3);
}

static int vl53l1x_read_reg16(int handle, uint16_t reg, uint8_t *buf, int len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) != 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle)
{
    uint8_t model_id = 0;
    if (vl53l1x_read_reg16(handle, REG_MODEL_ID, &model_id, 1) != 1) {
        log_message("Error: failed to read model ID.");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        char msg[64];
        snprintf(msg, sizeof(msg),
                 "Error: unexpected model ID 0x%02X (expected 0x%02X).",
                 model_id, EXPECTED_MODEL_ID);
        log_message(msg);
        return -1;
    }

    /* Short ranging mode */
    if (vl53l1x_write_reg16(handle, REG_SYSTEM_MODE, 0x00) != 0) {
        log_message("Error: failed to set ranging mode.");
        return -1;
    }

    /* Start ranging */
    if (vl53l1x_write_reg16(handle, REG_RANGE_START, 0x01) != 0) {
        log_message("Error: failed to start ranging.");
        return -1;
    }

    return 0;
}

static int vl53l1x_read_distance_cm(int handle, float *distance_cm)
{
    uint8_t buf[2];
    if (vl53l1x_read_reg16(handle, REG_DISTANCE_H, buf, 2) != 2) {
        log_message("Error: failed to read distance registers.");
        return -1;
    }
    uint16_t dist_mm = ((uint16_t)buf[0] << 8) | buf[1];
    *distance_cm = (float)dist_mm / 10.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Gate control                                                       */
/* ------------------------------------------------------------------ */
static void gate_open(void)
{
    if (gpioWrite(GATE_GPIO, 1) != 0) {
        log_message("Error: failed to set gate GPIO high.");
        return;
    }
    log_message("Gate opened.");
}

static void gate_close(void)
{
    if (gpioWrite(GATE_GPIO, 0) != 0) {
        log_message("Error: failed to set gate GPIO low.");
        return;
    }
    log_message("Gate closed.");
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        log_message("Program terminated.");
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_log_file = fopen("gate_log.txt", "a");
    if (!g_log_file) {
        perror("fopen gate_log.txt");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GATE_GPIO, PI_OUTPUT) != 0) {
        log_message("Error: failed to set gate GPIO mode.");
        cleanup();
        return EXIT_FAILURE;
    }
    gate_close();

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        char msg[64];
        snprintf(msg, sizeof(msg),
                 "Error: i2cOpen failed (handle=%d).", g_i2c_handle);
        log_message(msg);
        cleanup();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) != 0) {
        log_message("Error: VL53L1X initialisation failed.");
        cleanup();
        return EXIT_FAILURE;
    }

    log_message("Gate control system started.");

    while (g_running) {
        float distance_cm = 0.0f;
        if (vl53l1x_read_distance_cm(g_i2c_handle, &distance_cm) == 0) {
            char msg[64];
            snprintf(msg, sizeof(msg),
                     "Distance: %.2f cm", distance_cm);
            log_message(msg);

            if (distance_cm < DISTANCE_THRESHOLD_CM) {
                gate_open();
            } else {
                gate_close();
            }
        }
        /* On read error the distance stays at 0.0; the gate reflects the
           last valid state so the gate does not oscillate on transient
           sensor failures. */

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

