#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000
#define SAMPLE_PERIOD_US 100000
#define MOVING_AVG_SIZE  5

#define MIN_DISTANCE_CM 2.0f
#define MAX_DISTANCE_CM 400.0f
#define SOUND_SPEED_CM_S 34300.0f

#define SERVO_MIN_PULSE_US 500
#define SERVO_MAX_PULSE_US 2500
#define SERVO_MIN_ANGLE   0
#define SERVO_MAX_ANGLE   180

#define LOG_FILE "distance_log.csv"

static volatile sig_atomic_t program_running = 1;
static volatile uint32_t echo_start_tick = 0;
static volatile uint32_t echo_end_tick   = 0;
static volatile int      echo_received    = 0;
static volatile int      echo_valid       = 0;

static float distance_history[MOVING_AVG_SIZE];
static int   distance_index = 0;
static int   distance_count = 0;

static FILE *log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    if (level == 1) {
        echo_start_tick = tick;
        echo_received  = 0;
    } else if (level == 0) {
        echo_end_tick = tick;
        echo_received = 1;
        echo_valid    = 1;
    }
}

static float calculate_distance(uint32_t pulse_width_us)
{
    if (pulse_width_us == 0) return -1.0f;
    float distance = (float)pulse_width_us * SOUND_SPEED_CM_S / 2000000.0f;
    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) return -1.0f;
    return distance;
}

static float moving_average(float new_value)
{
    distance_history[distance_index] = new_value;
    distance_index = (distance_index + 1) % MOVING_AVG_SIZE;
    if (distance_count < MOVING_AVG_SIZE) distance_count++;
    float sum = 0.0f;
    for (int i = 0; i < distance_count; i++) sum += distance_history[i];
    return sum / (float)distance_count;
}

static int map_distance_to_angle(float distance)
{
    if (distance < 0.0f) return 90;
    float log_dist = log10f(distance + 1.0f);
    float norm = log_dist / log10f(MAX_DISTANCE_CM + 1.0f);
    if (norm < 0.0f) norm = 0.0f;
    if (norm > 1.0f) norm = 1.0f;
    return (int)(norm * (float)(SERVO_MAX_ANGLE - SERVO_MIN_ANGLE) + SERVO_MIN_ANGLE);
}

static int angle_to_pulse_us(int angle)
{
    if (angle < SERVO_MIN_ANGLE) angle = SERVO_MIN_ANGLE;
    if (angle > SERVO_MAX_ANGLE) angle = SERVO_MAX_ANGLE;
    return (int)(SERVO_MIN_PULSE_US +
                 (float)(angle - SERVO_MIN_ANGLE) *
                 (float)(SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US) /
                 (float)(SERVO_MAX_ANGLE - SERVO_MIN_ANGLE));
}

static int log_data(float distance, int servo_angle)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(log_file, "%s,%.2f,%d\n", timestamp, distance, servo_angle) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioServo(SERVO_PIN, 0);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set servo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on echo pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register echo alert\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fprintf(log_file, "Timestamp,Distance(cm),ServoAngle(deg)\n") < 0) {
        perror("fprintf header");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fflush(log_file);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    memset(distance_history, 0, sizeof(distance_history));

    while (program_running) {
        echo_received = 0;
        echo_valid    = 0;

        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Failed to set trigger high\n");
            break;
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Failed to set trigger low\n");
            break;
        }

        uint32_t start_wait = gpioTick();
        while (!echo_received && program_running) {
