#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1102_ADDR 0x60
#define SI1102_REG_PROX_HIGH 0x08
#define SI1102_REG_PROX_LOW 0x09
#define GPIO_PIN 27
#define DEFAULT_THRESHOLD 1000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t proximity_flag = 0;
static volatile int proximity_value = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_proximity(int handle, int *value) {
    int high = i2cReadByteData(handle, SI1102_REG_PROX_HIGH);
    if (high < 0) return -1;
    int low = i2cReadByteData(handle, SI1102_REG_PROX_LOW);
    if (low < 0) return -1;
    *value = (high << 8) | low;
    return 0;
}

static void proximity_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    proximity_flag = 1;
}

static void log_proximity(int value, int threshold) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    if (log_file) {
        fprintf(log_file, "%s, Proximity: %d, Status: %s\n",
                timestamp, value,
                (value <= threshold) ? "SAFE" : "ALERT");
        fflush(log_file);
    }
}

int main(int argc, char *argv[]) {
    int i2c_addr = SI1102_ADDR;
    int threshold = DEFAULT_THRESHOLD;
    int opt;

    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_addr = (int)strtol(optarg, NULL, 0);
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_addr] [-t threshold]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, i2c_addr, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X\n", i2c_addr);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("proximity.log", "a");
