#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SPEAKER_PIN 18

#define MIN_FREQUENCY 200
#define MAX_FREQUENCY 2000
#define MIN_DISTANCE  2.0
#define MAX_DISTANCE  200.0
#define PWM_RANGE     1000
#define PWM_DUTY      500
#define ECHO_TIMEOUT  200000  /* 200 ms in microseconds */
#define TRIGGER_PULSE 10      /* 10 us trigger pulse */
#define LOOP_DELAY    50000   /* 50 ms between measurements */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure distance using the HC-SR04.
 * Returns distance in cm, or -1.0 on timeout or error.
 */
static float measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger is low before starting */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioTrigger(TRIGGER_PIN, TRIGGER_PULSE, 1) < 0) {
        fprintf(stderr, "Error: gpioTrigger failed\n");
        return -1.0;
    }

    /* Wait for echo to go high (start of pulse) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo start timeout\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo to go low (end of pulse) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo end timeout\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance = (pulse_us / 10000.0) * 34300.0 / 2.0;

    if (distance < 0.0 || distance > 400.0) {
        fprintf(stderr, "Warning: Distance out of range (%.2f cm)\n", distance);
        return -1.0;
    }
    return distance;
}

/*
 * Map distance to frequency using a logarithmic scale.
 * Returns -1.0 if distance is invalid.
 */
static float distance_to_frequency(float distance) {
    if (distance < 0.0) return -1.0;
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;
    return MIN_FREQUENCY + (int)(log10(distance + 1.0) * 1000.0);
}

/*
 * Set speaker frequency using hardware-timed PWM.
 * Returns 0 on success, -1 on error.
 */
static int set_speaker_frequency(int frequency) {
    if (frequency <= 0) {
        fprintf(stderr, "Error: Invalid frequency %d\n", frequency);
        return -1;
    }
    if (gpioHardwarePWM(SPEAKER_PIN, frequency, PWM_DUTY) < 0) {
        fprintf(stderr, "Error: gpioHardwarePWM failed for %d Hz\n", frequency);
        return -1;
    }
    return 0;
}

int main(void) {
    float distance, frequency;
    int previous_frequency = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SPEAKER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(SPEAKER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range (0-1000) */
    if (gpioSetPWMrange(SPEAKER_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM duty cycle (50%) */
    if (gpioPWM(SPEAKER_PIN, PWM_DUTY) < 0) {
        fprintf(stderr, "Error: gpioPWM initial set failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        gpioHardwarePWM(SPEAKER_PIN, 0, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        gpioHardwarePWM(SPEAKER_PIN, 0, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (running) {
        distance = measure_distance();

        if (distance > 0.0) {
            frequency = distance_to_frequency(distance);
            if (frequency > 0) {
                if (set_speaker_frequency((int)frequency) == 0) {
                    previous_frequency = (int)frequency;
                }
            } else {
                fprintf(stderr, "Warning: Invalid frequency for distance %.2f cm\n", distance);
            }
        } else {
            fprintf(stderr, "Warning: Invalid distance reading\n");
        }

        gpioDelay(LOOP_DELAY);
    }

    /* Clean shutdown */
    gpioHardwarePWM(SPEAKER_PIN, 0, 0);
    gpioTerminate();
    printf("\nTheremin stopped.\n");
    return EXIT_SUCCESS;
}

