static float measure_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -2.0f;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 1) failed\n");
        return -2.0f;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -2.0f;
    }

    /* Wait for echo rising edge (timeout) */
    timeout_tick = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo start timeout\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    timeout_tick = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo end timeout\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    return (float)pulse_us * 0.0343f / 2.0f;  /* cm = us * 0.0343 / 2 */
}

/*
 * Map distance to frequency with clamping.
 * Returns frequency in Hz.
 */
static int distance_to_frequency(float distance)
