#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define TRIGGER_PULSE_US 10
#define TIMEOUT_US       50000   /* 50 ms */
#define MIN_DISTANCE_CM  2.0
#define MAX_DISTANCE_CM  400.0
#define CLOSE_THRESHOLD_CM 10.0
#define SAMPLE_PERIOD_US 500000  /* 500 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * Measure the echo pulse width in microseconds.
 * Returns:
 *   > 0  : pulse width in microseconds
 *   -1   : timeout (no echo received)
 *   -2   : pigpio read error
 */
static long measure_echo_pulse(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Wait for echo to go high (start of pulse) */
    start_tick = gpioTick();
    timeout_tick = start_tick + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            return -1;  /* timeout */
        }
    }
    start_tick = gpioTick();

    /* Wait for echo to go low (end of pulse) */
    timeout_tick = start_tick + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            return -1;  /* timeout */
        }
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

static double calculate_distance_cm(long pulse_width_us)
{
    return (double)pulse_width_us / 2.0 / 29.1;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set echo pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(50000);  /* 50 ms settle */

    while (running) {
        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to set trigger high.\n");
            break;
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to set trigger low.\n");
            break;
        }

        long pulse_width = measure_echo_pulse();
        if (pulse_width == -1) {
            printf("Invalid reading (timeout)\n");
        } else if (pulse_width == -2) {
            printf("Invalid reading (pigpio read error)\n");
        } else {
            double distance = calculate_distance_cm(pulse_width);
            if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
                printf("Invalid reading (out of range: %.2f cm)\n", distance);
            } else {
                printf("Distance: %.2f cm", distance);
                if (distance < CLOSE_THRESHOLD_CM) {
                    printf(" - Too close!");
                }
                printf("\n");
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

