 *   SCLK -> GPIO11 (Pin 23, SPI0 SCLK)
 *   DOUT -> GPIO9  (Pin 21, SPI0 MISO)
 *   DIN  -> GPIO10 (Pin 19, SPI0 MOSI)
 *   CS   -> GPIO8  (Pin 24, SPI0 CE0)
 *
 * SPI Mode: 0 (CPOL=0, CPHA=0)
 * Clock:    1 MHz
 *
 * Register map (16-bit addresses, big-endian on wire):
 *   0x00 - 0x01  Measurement Result (mm)
 *   0x02 - 0x03  Configuration
 *   0x04 - 0x05  Status
 *   0x06 - 0x07  Interrupt
 *   0x08 - 0x09  Clock
 *   0x0A - 0x0B  Range
 *   0x0C - 0x0D  Distance (mm) - read after measurement
 *
 * Measurement sequence:
 *   1. Write 0x01 to register 0x01 to enter continuous measurement mode.
 *   2. Write 0x00 to register 0x02 to set range to 5 m.
 *   3. Write 0x01 to register 0x00 to trigger a single measurement.
 *   4. Wait ~10 ms for conversion.
 *   5. Read registers 0x0C (low byte) and 0x0D (high byte) via SPI transfer.
 */

#define SPI_CHANNEL    0       /* CE0 / GPIO8 */
#define SPI_SPEED      1000000 /* 1 MHz */
#define SPI_FLAGS      0       /* Mode 0, active-low CS */

#define REG_MEAS_RES   0x00
#define REG_CONFIG     0x02
#define REG_TRIGGER    0x00
#define REG_DIST_LOW   0x0C
#define REG_DIST_HIGH  0x0D

#define TRIGGER_MEAS   0x01
#define CONFIG_RANGE_5M 0x00

#define LOG_FILE       "distance_log.csv"
#define READ_DELAY_US  100000   /* 100 ms */
#define CONV_DELAY_US  10000    /* 10 ms  */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                          */
/* ------------------------------------------------------------------ */

/*
 * Write a 16-bit value to a 16-bit register address.
 * ICU-20201 expects 16-bit addresses sent MSB-first, then 16-bit data
 * MSB-first.  pigpio's spiWrite sends bytes in the order they are given,
 * so we pack: [addr_msb, addr_lsb, data_msb, data_lsb].
 */
static int spi_write_reg16(uint8_t addr, uint16_t value)
{
    char tx[4];
    tx[0] = (char)(addr >> 8);
    tx[1] = (char)(addr & 0xFF);
    tx[2] = (char)(value >> 8);
    tx[3] = (char)(value & 0xFF);

    if (spiWrite(g_spi_handle, tx, 4) != 4) {
        fprintf(stderr, "SPI write to register 0x%02X failed\n", addr);
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit register value.
 * Send the 16-bit address (MSB-first), then read 2 data bytes.
 */
static int spi_read_reg16(uint8_t addr, uint16_t *out)
{
    char tx[2];
    char rx[2];

    tx[0] = (char)(addr >> 8);
    tx[1] = (char)(addr & 0xFF);

    if (spiXfer(g_spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read from register 0x%02X failed\n", addr);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor operations                                                    */
/* ------------------------------------------------------------------ */
static int sensor_init(void)
{
    /* Enter continuous measurement mode */
    if (spi_write_reg16(REG_CONFIG, CONFIG_RANGE_5M) != 0)
        return -1;

    /* Trigger a single measurement */
    if (spi_write_reg16(REG_TRIGGER, TRIGGER_MEAS) != 0)
        return -1;

    gpioDelay(CONV_DELAY_US);
    return 0;
}

static int sensor_read_distance(uint16_t *distance_mm)
{
    uint16_t dist_low, dist_high;

    /* Trigger a new measurement */
    if (spi_write_reg16(REG_TRIGGER, TRIGGER_MEAS) != 0)
        return -1;

    gpioDelay(CONV_DELAY_US);

    /* Read distance low byte */
    if (spi_read_reg16(REG_DIST_LOW, &dist_low) != 0)
        return -1;

    /* Read distance high byte */
    if (spi_read_reg16(REG_DIST_HIGH, &dist_high) != 0)
        return -1;

    *distance_mm = ((uint16_t)dist_high << 8) | dist_low;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                              */
/* ------------------------------------------------------------------ */
static int log_distance(uint16_t distance_mm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance_mm);

    if (fclose(fp) != 0) {
        perror("fclose(" LOG_FILE ")");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (sensor_init() != 0) {
        fprintf(stderr, "Sensor initialisation failed - check wiring and power\n");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ICU-20201 distance logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t distance_mm;

        if (sensor_read_distance(&distance_mm) == 0) {
            printf("Distance: %u mm\n", distance_mm);
            if (log_distance(distance_mm) != 0) {
                fprintf(stderr, "Warning: failed to log distance\n");
            }
        } else {
            fprintf(stderr, "Sensor read error - continuing\n");
        }

        gpioDelay(READ_DELAY_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

