#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1175_ADDR        0x60
#define SI1175_REG_ALS_VIS_DATA0 0x22
#define SI1175_REG_ALS_VIS_DATA1 0x23
#define I2C_BUS            "/dev/i2c-1"
#define LOG_FILE           "proximity_log.csv"
#define SAMPLE_INTERVAL_S  5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_als_visible(int fd, uint16_t *out)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, SI1175_REG_ALS_VIS_DATA0, &lo) < 0)
        return -1;
    if (i2c_read_reg8(fd, SI1175_REG_ALS_VIS_DATA1, &hi) < 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SI1175_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,als_visible\n");
        fflush(g_log_fp);
    }

    printf("Si1175 proximity logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t als_vis = 0;
        if (read_als_visible(g_i2c_fd, &als_vis) < 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
        } else {
            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *tm = localtime_r(&now, &tm_buf);
            char ts[32];
            if (tm) {
                strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm);
            } else {
                snprintf(ts, sizeof(ts), "1970-01-01T00:00:00");
            }
            fprintf(g_log_fp, "%s,%u\n", ts, (unsigned)als_vis);
            fflush(g_log_fp);
            printf("%s  ALS_VIS=%u\n", ts, (unsigned)als_vis);
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

