#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1120_ADDR        0x60
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_ALS_LOW  0x22
#define SI1120_REG_ALS_HIGH 0x23
#define SI1120_REG_PS1_LOW  0x18
#define SI1120_REG_PS1_HIGH 0x19
#define SI1120_REG_RESET   0x30
#define SI1120_RESET_VAL   0x01
#define SI1120_PART_ID     0x41
#define I2C_BUS            1
#define SAMPLE_PERIOD_US   500000
#define MAX_RETRIES        3
#define RETRY_DELAY_US     10000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int v = i2cReadByteData(handle, reg);
        if (v >= 0) {
            *value = (uint8_t)v;
            return 0;
        }
        fprintf(stderr, "Warning: I2C read reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, pigpio_error(v));
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int write_register(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int r = i2cWriteByteData(handle, reg, value);
        if (r == 0)
            return 0;
        fprintf(stderr, "Warning: I2C write reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, pigpio_error(r));
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int read_16bit_le(int handle, uint8_t low_reg, uint16_t *out)
{
    uint8_t lo, hi;
    if (read_register(handle, low_reg, &lo) != 0)
        return -1;
    if (read_register(handle, low_reg + 1, &hi) != 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int initialize_sensor(int handle)
{
    uint8_t part_id;
    if (read_register(handle, SI1120_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error: cannot read part ID from Si1120.\n");
        return -1;
    }
    if (part_id != SI1120_PART_ID) {
        fprintf(stderr, "Error: unexpected part ID 0x%02X (expected 0x%02X).\n",
                part_id, SI1120_PART_ID);
        return -1;
    }
    if (write_register(handle, SI1120_REG_RESET, SI1120_RESET_VAL) != 0) {
        fprintf(stderr, "Error: Si1120 reset failed.\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed: %s\n", pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: Si1120 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("si1120_log.txt", "a");
    if (g_log_file == NULL) {
        perror("fopen");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si1120 ALS + PS1 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t als, ps1;
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[32];

        if (read_16bit_le(g_i2c_handle, SI1120_REG_ALS_LOW, &als) != 0) {
            fprintf(stderr, "Error: failed to read ALS data.\n");
        } else if (read_16bit_le(g_i2c_handle, SI1120_REG_PS1_LOW, &ps1) != 0) {
            fprintf(stderr, "Error: failed to read PS1 data.\n");
        } else {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(g_log_file, "%s, ALS: %u, PS1: %u\n", timestamp, als, ps1);
            fflush(g_log_file);
            printf("%s, ALS: %u, PS1: %u\n", timestamp, als, ps1);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

