#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SI1145_ADDR 0x60
#define I2C_BUS 1
#define LOG_FILE "proximity_log.txt"
#define MAX_RETRIES 3

/* Si1145 register addresses */
#define REG_HW_KEY      0x07
#define REG_MEAS_RATE   0x06
#define REG_INT_CFG     0x1A
#define REG_ALS_VIS_IR  0x21
#define REG_ALS_VIS_GAIN 0x24
#define REG_PS_ADC_MISC 0x22
#define REG_PS_ADC_GAIN 0x0D
#define REG_PS_LED21    0x0C
#define REG_PS_LED3     0x0F
#define REG_PS_FORCE    0x80
#define REG_PS1_DATA0   0x16
#define REG_PS1_DATA1   0x17

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_register(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (pigpio rc=%d)\n",
                value, reg, rc);
        return -1;
    }
    return 0;
}

static int read_register(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (pigpio rc=%d)\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int initialize_sensor(void) {
    if (write_register(REG_HW_KEY, 0x03) < 0) return -1;
    if (write_register(REG_MEAS_RATE, 0x02) < 0) return -1;
    if (write_register(REG_INT_CFG, 0x00) < 0) return -1;
    if (write_register(REG_ALS_VIS_IR, 0x0B) < 0) return -1;
    if (write_register(REG_ALS_VIS_GAIN, 0x00) < 0) return -1;
    if (write_register(REG_PS_ADC_MISC, 0x49) < 0) return -1;
    if (write_register(REG_PS_LED21, 0x03) < 0) return -1;
    if (write_register(REG_PS_LED3, 0x0F) < 0) return -1;
    if (write_register(REG_PS_ADC_GAIN, 0x07) < 0) return -1;
    if (write_register(REG_PS_FORCE, 0x03) < 0) return -1;
    return 0;
}

static int read_proximity(uint16_t *proximity) {
    uint8_t lo, hi;
    if (read_register(REG_PS1_DATA0, &lo) < 0) return -1;
    if (read_register(REG_PS1_DATA1, &hi) < 0) return -1;
    *proximity = (uint16_t)((hi << 8) | lo);
    return 0;
}

static void log_data(uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Proximity: %u\n", timestamp, proximity);
    fflush(log_file);
}

static void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    uint16_t proximity;
    int retries;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X (pigpio rc=%d)\n",
                I2C_BUS, SI1145_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        retries = 0;
        while (retries < MAX_RETRIES && !terminate) {
            if (read_proximity(&proximity) == 0) {
                log_data(proximity);
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "I2C read failed, retrying (%d/%d)...\n",
                        retries, MAX_RETRIES);
                gpioDelay(100000); /* 100 ms */
            }
        }
        if (retries == MAX_RETRIES) {
            log_error("Max retries reached, exiting");
            break;
        }
        gpioDelay(100000); /* 100 ms */
    }

    cleanup();
    return EXIT_SUCCESS;
}

