#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define BUZZER_PIN  27

#define DISTANCE_THRESHOLD_CM 20.0
#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define TRIGGER_PULSE_US 10
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static volatile uint32_t echo_start_tick = 0;
static volatile uint32_t echo_end_tick   = 0;
static volatile int      echo_rising_seen = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        echo_start_tick = tick;
        echo_rising_seen = 1;
    } else if (level == 0 && echo_rising_seen) {
        echo_end_tick = tick;
        echo_rising_seen = 0;

        uint32_t pulse_us = echo_end_tick - echo_start_tick;
        if (pulse_us > 0) {
            double distance_cm = (double)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0;
            printf("Distance: %.2f cm\n", distance_cm);
            fflush(stdout);
        }
    }
}

static int trigger_sensor(void) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER_PIN, 1) failed\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER_PIN, 0) failed\n");
        return -1;
    }
    return 0;
}

static void control_buzzer(double distance_cm) {
    int level = (distance_cm < DISTANCE_THRESHOLD_CM) ? 1 : 0;
    if (gpioWrite(BUZZER_PIN, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(BUZZER_PIN, %d) failed\n", level);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER_PIN, PI_OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO_PIN, PI_INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER_PIN, PI_OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx(ECHO_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        if (trigger_sensor() < 0) {
            break;
        }
        gpioDelay(POLL_INTERVAL_US);

        uint32_t pulse_us = echo_end_tick - echo_start_tick;
        if (pulse_us > 0) {
            double distance_cm = (double)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0;
            printf("Distance: %.2f cm\n", distance_cm);
            fflush(stdout);
            control_buzzer(distance_cm);
        }
    }

    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

