#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define SPEED_OF_SOUND 34300.0
#define MAX_DISTANCE 400.0
#define MIN_DISTANCE 20.0
#define MAX_SERVO_ANGLE 180
#define MIN_SERVO_ANGLE 0
#define SERVO_MIN_PULSEWIDTH 500
#define SERVO_MAX_PULSEWIDTH 2500
#define SERVO_MID_PULSEWIDTH 1500
#define DISTANCE_MID 110.0
#define DISTANCE_MIN 20.0
#define DISTANCE_MAX 200.0
#define ECHO_TIMEOUT_US 30000
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

static double measure_distance(void) {
    uint32_t start_tick, end_tick;
    int timeout;

    trigger_sensor();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 0) {
        gpioDelay(1);
        timeout++;
        if (timeout > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin stuck low (timeout).\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin stuck high (timeout).\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    double distance = (double)diff * SPEED_OF_SOUND / 2000000.0;

    if (distance > MAX_DISTANCE || distance < MIN_DISTANCE) {
        fprintf(stderr, "Warning: Distance out of range (%.2f cm).\n", distance);
        return -1.0;
    }

    return distance;
}

static int calculate_servo_angle(double distance) {
    if (distance < 0) return 0;
    if (distance >= DISTANCE_MAX) return MIN_SERVO_ANGLE;
    if (distance <= DISTANCE_MIN) return MAX_SERVO_ANGLE;

    double ratio = (DISTANCE_MAX - distance) / (DISTANCE_MAX - DISTANCE_MIN);
    int angle = (int)(ratio * (MAX_SERVO_ANGLE - MIN_SERVO_ANGLE) + MIN_SERVO_ANGLE);
    if (angle < MIN_SERVO_ANGLE) angle = MIN_SERVO_ANGLE;
    if (angle > MAX_SERVO_ANGLE) angle = MAX_SERVO_ANGLE;
    return angle;
}

static void set_servo_angle(int angle) {
    int pulsewidth = SERVO_MIN_PULSEWIDTH + (int)((double)angle / MAX_SERVO_ANGLE * (SERVO_MAX_PULSEWIDTH - SERVO_MIN_PULSEWIDTH));
    gpioServo(SERVO_PIN, pulsewidth);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        double distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Error: Invalid distance reading.\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        int angle = calculate_servo_angle(distance);
        set_servo_angle(angle);

        printf("Distance: %.2f cm, Servo Angle: %d degrees\n", distance, angle);
        fflush(stdout);

        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return 0;
}

