                for (int pw = GATE_CLOSED_PW; pw <= GATE_OPEN_PW; pw += 10) {
                    gpioServo(SERVO_PIN, pw);
                    usleep(10000);
                }
                gate_open = 1;
                log_event("Gate opened");
            } else if (gate_open && distance > DISTANCE_THRESHOLD_CLOSE) {
                for (int pw = GATE_OPEN_PW; pw >= GATE_CLOSED_PW; pw -= 10) {
                    gpioServo(SERVO_PIN, pw);
