#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SI7005_ADDR 0x40
#define SI7005_REG_TEMP 0x01
#define SI7005_REG_HUMIDITY 0x02
#define SI7005_REG_CONFIG 0x03
#define SI7005_CONFIG_TEMP_EN 0x00
#define SI7005_CONFIG_HEATER_OFF 0x00
#define I2C_BUS 1
#define READ_INTERVAL_SEC 2
#define CONVERSION_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int open_i2c_device(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device on bus %d, addr 0x%02X: %d\n",
                I2C_BUS, SI7005_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int configure_sensor(void) {
    int rc = i2cWriteByteData(i2c_handle, SI7005_REG_CONFIG,
                              SI7005_CONFIG_TEMP_EN | SI7005_CONFIG_HEATER_OFF);
    if (rc < 0) {
        fprintf(stderr, "Error writing CONFIG register: %d\n", rc);
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_MS * 1000);
    return 0;
}

static int read_register(uint8_t reg, uint16_t *value) {
    int rc = i2cReadWordData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint16_t)(rc & 0xFFFF);
    return 0;
}

static int read_sensor_data(float *temperature, float *humidity) {
    uint16_t raw_temp, raw_humidity;

    if (read_register(SI7005_REG_TEMP, &raw_temp) < 0) return -1;
    if (read_register(SI7005_REG_HUMIDITY, &raw_humidity) < 0) return -1;

    *temperature = ((175.72f * (float)raw_temp) / 65536.0f) - 46.85f;
    *humidity = ((125.0f * (float)raw_humidity) / 65536.0f) - 6.0f;

    if (*humidity < 0.0f) *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;

    return 0;
}

static void log_data(float temperature, float humidity) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    if (open_i2c_device() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (configure_sensor() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float temperature, humidity;

    while (running) {
        if (read_sensor_data(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Sensor read failed; re-opening I2C device...\n");
            if (open_i2c_device() < 0) {
                fprintf(stderr, "Failed to re-open I2C device. Exiting.\n");
                break;
            }
            if (configure_sensor() < 0) {
                fprintf(stderr, "Failed to re-configure sensor. Exiting.\n");
                break;
            }
        }
        sleep(READ_INTERVAL_SEC);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

