#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define WHO_AM_I     0x75
#define PWR_MGMT_1   0x6B
#define SMPLRT_DIV   0x19
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG  0x1B
#define ACCEL_XOUT_H 0x3B

/* Expected WHO_AM_I value for MPU-6050 */
#define MPU6050_WHO_AM_I 0x68

/* Global I2C handle for signal handler cleanup */
static int i2c_handle = -1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    exit(0);
}

/* Read a single byte from an MPU-6050 register */
static int mpu_read_byte(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* Write a single byte to an MPU-6050 register */
static int mpu_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

/* Initialize the MPU-6050: verify identity, reset, configure ranges, sample rate */
static int mpu_init(int handle) {
    uint8_t who_am_i = 0;

    /* Verify sensor identity */
    if (mpu_read_byte(handle, WHO_AM_I, &who_am_i) < 0) {
        return -1;
    }
    if (who_am_i != MPU6050_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, MPU6050_WHO_AM_I);
        return -1;
    }

    /* Reset device via PWR_MGMT_1 (bit 7 = reset) */
    if (mpu_write_byte(handle, PWR_MGMT_1, 0x80) < 0) {
        return -1;
    }
    gpioDelay(100000); /* 100 ms for reset to complete */

    /* Wake up: clear sleep bit (bit 6 = sleep) */
    if (mpu_write_byte(handle, PWR_MGMT_1, 0x00) < 0) {
        return -1;
    }
    gpioDelay(100000); /* 100 ms stabilization */

    /* Sample rate divider = 7 -> 1 kHz / (1 + 7) = 125 Hz */
    if (mpu_write_byte(handle, SMPLRT_DIV, 0x07) < 0) {
        return -1;
    }

    /* Accelerometer range = ±2 g (AFS_SEL = 0) */
    if (mpu_write_byte(handle, ACCEL_CONFIG, 0x00) < 0) {
        return -1;
    }

    /* Gyroscope range = ±250 deg/s (FS_SEL = 0) */
    if (mpu_write_byte(handle, GYRO_CONFIG, 0x00) < 0) {
        return -1;
    }

    return 0;
}

/* Read 14-byte data block (accel XYZ, temp, gyro XYZ) and parse into signed int16 */
static int mpu_read_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                         int16_t *gx, int16_t *gy, int16_t *gz) {
    char buf[14];
    int rc = i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buf, 14);
    if (rc != 14) {
        fprintf(stderr, "Error reading data block: expected 14 bytes, got %d\n", rc);
        return -1;
    }

    *ax = (int16_t)((buf[0]  << 8) | (uint8_t)buf[1]);
    *ay = (int16_t)((buf[2]  << 8) | (uint8_t)buf[3]);
    *az = (int16_t)((buf[4]  << 8) | (uint8_t)buf[5]);
    /* buf[6..7] = temperature (skipped) */
    *gx = (int16_t)((buf[8]  << 8) | (uint8_t)buf[9]);
    *gy = (int16_t)((buf[10] << 8) | (uint8_t)buf[11]);
    *gz = (int16_t)((buf[12] << 8) | (uint8_t)buf[13]);
    return 0;
}

int main(void) {
    int16_t ax, ay, az, gx, gy, gz;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 at MPU-6050 address */
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %d\n", MPU6050_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize sensor */
    if (mpu_init(i2c_handle) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Register signal handlers for graceful shutdown */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPU-6050 initialized. Logging data every 100 ms. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (1) {
        if (mpu_read_data(i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  Gyro: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    /* Unreachable in normal operation, but kept for completeness */
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

