#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SHT40_ADDR        0x44
#define I2C_BUS           1
#define MEASURE_CMD       0xFD
#define MEASURE_DELAY_US  10000   /* 10 ms */
#define LOOP_DELAY_US     5000000 /* 5 s  */
#define MAX_RETRIES       3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (polynomial 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Open the I2C bus and configure the SHT40 slave address.
 * Returns 0 on success, -1 on failure.
 */
static int init_i2c(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, SHT40_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

/*
 * Read temperature and humidity from the SHT40.
 * Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.
 */
static int read_sht40(float *temperature, float *humidity)
{
    uint8_t cmd = MEASURE_CMD;
    uint8_t buf[6];

    /* Send measurement command */
    if (i2cWriteDevice(g_i2c_handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice (cmd 0x%02X) failed\n", cmd);
        return -1;
    }

    gpioDelay(MEASURE_DELAY_US);

    /* Read 6 bytes: T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC */
    if (i2cReadDevice(g_i2c_handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: i2cReadDevice failed (expected 6 bytes)\n");
        return -1;
    }

    /* Validate CRC-8 for temperature */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: temperature CRC mismatch (calc=0x%02X, got=0x%02X)\n",
                crc8(buf, 2), buf[2]);
        return -2;
    }

    /* Validate CRC-8 for humidity */
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: humidity CRC mismatch (calc=0x%02X, got=0x%02X)\n",
                crc8(buf + 3, 2), buf[5]);
        return -2;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t rh_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = -6.0f  + 125.0f * (float)rh_raw / 65535.0f;

    if (*humidity < 0.0f)   *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;

    return 0;
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SHT40 sensor reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature, humidity;
        int rc = -1;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            rc = read_sht40(&temperature, &humidity);
            if (rc == 0)
                break;

            fprintf(stderr, "Warning: read attempt %d/%d failed (rc=%d)\n",
                    attempt + 1, MAX_RETRIES, rc);

            if (init_i2c() != 0) {
                fprintf(stderr, "Error: I2C re-init failed; will retry next cycle\n");
                break;
            }
        }

        if (rc == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "Error: sensor read failed after %d attempts; "
                            "exiting\n", MAX_RETRIES);
            break;
        }

        /* Sleep 5 s, but wake early on signal */
        for (int i = 0; i < 50 && g_running; i++)
            gpioDelay(100000); /* 100 ms */
    }

    /* Cleanup */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

