    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SHT40 sensor reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature, humidity;
        int rc = -1;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            rc = read_sht40(&temperature, &humidity);
            if (rc == 0)
                break;

            fprintf(stderr, "Warning: read attempt %d/%d failed (rc=%d)\n",
                    attempt + 1, MAX_RETRIES, rc);

            if (init_i2c() != 0) {
                fprintf(stderr, "Error: I2C re-init failed; will retry next cycle\n");
                break;
            }
        }

        if (rc == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "Error: sensor read failed after %d attempts; "
                            "exiting\n", MAX_RETRIES);
            break;
        }

        /* Sleep 5 s, but wake early on signal */
        for (int i = 0; i < 50 && g_running; i++)
            gpioDelay(100000); /* 100 ms */
    }

    /* Cleanup */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

