#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "temperature_log.csv"
#define READ_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, float *temp_c) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp_c = (float)raw / 100.0f;
    return 0;
}

static int log_temperature(float ambient, float object) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    if (fprintf(log_fp, "%s,%.2f,%.2f\n", timestamp, ambient, object) < 0) {
        return -1;
    }
    fflush(log_fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("Failed to acquire I2C bus access / sensor not present");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        float ambient = 0.0f, object = 0.0f;
        int err = 0;

        if (i2c_read_reg16(i2c_fd, AMBIENT_TEMP_REG, &ambient) != 0) {
            fprintf(stderr, "Error reading ambient temperature\n");
            err = 1;
        }

        if (!err && i2c_read_reg16(i2c_fd, OBJECT_TEMP_REG, &object) != 0) {
            fprintf(stderr, "Error reading object temperature\n");
            err = 1;
        }

        if (!err) {
            if (log_temperature(ambient, object) != 0) {
                fprintf(stderr, "Error writing to log file\n");
            }
        }

        sleep(READ_INTERVAL_SEC);
    }

    if (log_fp) {
        fclose(log_fp);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return EXIT_SUCCESS;
}

