#define SAMPLE_INTERVAL_SEC 5
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static FILE *error_log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void log_error(const char *message) {
    if (error_log_file) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
        fprintf(error_log_file, "%s: %s\n", timestamp, message);
        fflush(error_log_file);
    }
    fprintf(stderr, "Error: %s\n", message);
}

static int read_sts30_temperature(int handle, float *temperature) {
    char cmd[2] = {0x36, 0x00};
    char buf[3];
    int result;

    result = i2cWriteDevice(handle, cmd, 2);
    if (result != 0) {
        log_error("Failed to write measurement command to STS30-DIS");
        return -1;
    }

    gpioDelay(20000); // 20ms delay for measurement

    result = i2cReadDevice(handle, buf, 3);
    if (result != 3) {
        log_error("Failed to read temperature data from STS30-DIS");
        return -1;
    }

    int16_t raw_temperature = (buf[0] << 8) | buf[1];
    *temperature = (float)raw_temperature / 100.0;
    return 0;
}

