#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SHT40_ADDR     0x44
#define MEASURE_CMD    0xFD
#define LOG_FILE       "sht40_log.txt"
#define SAMPLE_PERIOD  5
#define MEASURE_DELAY  10000  /* microseconds */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log = NULL;

/* Sensirion CRC-8: polynomial 0x31, initial value 0xFF */
static uint8_t sht40_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cleanup(void) {
    if (g_log) {
        fflush(g_log);
        fclose(g_log);
        g_log = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

static int init_i2c(void) {
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                SHT40_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int read_sht40(float *temperature, float *humidity) {
    uint8_t cmd = MEASURE_CMD;
    ssize_t w = write(g_i2c_fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }

    usleep(MEASURE_DELAY);

    uint8_t buf[6];
    ssize_t r = read(g_i2c_fd, buf, sizeof(buf));
    if (r != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read error: expected 6 bytes, got %zd (%s)\n",
                r, r < 0 ? strerror(errno) : "short read");
        return -1;
    }

    /* Validate CRC for temperature (bytes 0-1, CRC byte 2) */
    if (sht40_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    /* Validate CRC for humidity (bytes 3-4, CRC byte 5) */
    if (sht40_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t raw_t = (uint16_t)((buf[0] << 8) | buf[1]);
    uint16_t raw_h = (uint16_t)((buf[3] << 8) | buf[4]);

    *temperature = -45.0f + 175.0f * (float)raw_t / 65535.0f;
    *humidity    = 100.0f * (float)raw_h / 65535.0f;

    return 0;
}

static void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
            ts, temperature, humidity);
    fflush(g_log);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return 1;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }

    printf("SHT40 greenhouse monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature, humidity;
        if (read_sht40(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
            printf("%s  T=%.2f C  RH=%.2f %%\n",
                   "Reading", temperature, humidity);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return 0;
}

