            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Send the continuous-measurement command with retries + backoff    */
/* ------------------------------------------------------------------ */
static int sdp31_trigger_measurement(void)
{
    for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(g_i2c_handle, (char *)CMD_CONT_MEAS, 2);
        if (rc == 0)
            return 0;

        fprintf(stderr, "[WARN] I2C write failed (attempt %d/%d, rc=%d)\n",
                attempt, MAX_RETRIES, rc);

        if (attempt < MAX_RETRIES)
            gpioDelay(RETRY_BASE_US * (1 << (attempt - 1)));
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes from the SDP31 and convert to Pa / °C                  */
/* ------------------------------------------------------------------ */
static int sdp31_read(float *pressure_pa, float *temperature_c)
{
    uint8_t buf[6];

    for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        int rc = i2cReadDevice(g_i2c_handle, (char *)buf, 6);
        if (rc == 6) {
            /* CRC check on pressure (bytes 0-1, CRC byte 2) */
            if (crc8(buf, 2) != buf[2]) {
                fprintf(stderr, "[WARN] Pressure CRC mismatch (attempt %d)\n", attempt);
                continue;
            }
            /* CRC check on temperature (bytes 3-4, CRC byte 5) */
            if (crc8(buf + 3, 2) != buf[5]) {
                fprintf(stderr, "[WARN] Temperature CRC mismatch (attempt %d)\n", attempt);
                continue;
            }

            int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
            int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

            *pressure_pa    = (float)raw_pressure    / 60.0f;   /* Pa   */
            *temperature_c  = (float)raw_temperature / 200.0f;  /* °C   */
            return 0;
        }

        fprintf(stderr, "[WARN] I2C read failed (attempt %d/%d, rc=%d)\n",
                attempt, MAX_RETRIES, rc);

        if (attempt < MAX_RETRIES)
            gpioDelay(RETRY_BASE_US * (1 << (attempt - 1)));
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Append one CSV line to the log file                                 */
/* ------------------------------------------------------------------ */
static int log_data(float pressure_pa, float temperature_c)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return -1;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(g_log_file, "%s,%.2f,%.2f\n", ts, pressure_pa, temperature_c) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed\n");
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "[ERROR] fflush failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup — safe to call from any exit path                          */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (rc=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file ---------------------------------------------- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open %s\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signals ---------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fprintf(stderr, "[INFO] SDP31 logging started -> %s\n", LOG_FILE);

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        if (sdp31_trigger_measurement() != 0) {
            fprintf(stderr, "[ERROR] Measurement trigger failed; retrying next cycle\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        /* SDP31 continuous measurement takes ~1 ms; wait a bit more */
        gpioDelay(2000);

        float pressure_pa, temperature_c;
        if (sdp31_read(&pressure_pa, &temperature_c) != 0) {
            fprintf(stderr, "[ERROR] Sensor read failed; skipping sample\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (log_data(pressure_pa, temperature_c) != 0) {
            fprintf(stderr, "[ERROR] Logging failed\n");
        }

        gpioDelay(SAMPLE_US);
    }

    fprintf(stderr, "[INFO] Shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

