#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7015_ADDR    0x40
#define CMD_TEMP_NOHOLD 0xF3
#define CMD_HUM_NOHOLD  0xF5
#define LOG_FILE       "sensor_data.txt"
#define SAMPLE_INTERVAL_S 5
#define MEAS_TIMEOUT_MS 20

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

static int read_measurement(int handle, uint8_t cmd, uint16_t *raw_out)
{
    char buf[2];
    int rc;

    rc = i2cWriteByte(handle, cmd);
    if (rc < 0) {
        fprintf(stderr, "I2C write command 0x%02X failed: %s\n",
                cmd, pigpio_error(rc));
        return -1;
    }

    for (int elapsed = 0; elapsed < MEAS_TIMEOUT_MS; elapsed += 2) {
        gpioDelay(2000); /* 2 ms */

        rc = i2cReadDevice(handle, buf, 2);
        if (rc == 2) {
            *raw_out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }

        if (rc < 0) {
            fprintf(stderr, "I2C read failed after command 0x%02X: %s\n",
                    cmd, pigpio_error(rc));
            return -1;
        }
    }

    fprintf(stderr, "Measurement timeout for command 0x%02X\n", cmd);
    return -1;
}

static float convert_temperature(uint16_t raw)
{
    return (175.72f * (float)raw / 65536.0f) - 46.85f;
}

static float convert_humidity(uint16_t raw)
{
    float rh = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (rh < 0.0f)   rh = 0.0f;
    if (rh > 100.0f) rh = 100.0f;
    return rh;
}

static int log_data(float temp, float hum)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Humidity: %.2f %%RH\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, temp, hum);
    } else {
        fprintf(fp, "Timestamp error, Temperature: %.2f C, Humidity: %.2f %%RH\n", temp, hum);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, SI7015_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7015 sensor logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t raw_t = 0, raw_h = 0;
        int ok = 1;

        if (read_measurement(g_i2c_handle, CMD_TEMP_NOHOLD, &raw_t) != 0) {
            ok = 0;
        }

        if (ok && read_measurement(g_i2c_handle, CMD_HUM_NOHOLD, &raw_h) != 0) {
            ok = 0;
        }

        if (ok) {
            float temp = convert_temperature(raw_t);
            float hum  = convert_humidity(raw_h);

            printf("Temperature: %.2f C, Humidity: %.2f %%RH\n", temp, hum);

            if (log_data(temp, hum) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing...\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

