    if (!log_fp) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!err_fp) {
        perror("Failed to open error log file");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("STS30-DIS temperature logger started. Press Ctrl+C to stop.\n");

    while (running) {
        float temp;
        if (read_temperature(&temp) == 0) {
            log_temperature(temp);
        }
        for (int i = 0; i < SAMPLE_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

