}

static int read_sht40(float *temperature, float *humidity) {
    uint8_t cmd = MEASURE_CMD;
    ssize_t w = write(i2c_fd, &cmd, 1);
    if (w != 1) {
        perror("write(measure cmd)");
        return -1;
    }
    usleep(MEASURE_DELAY_MS * 1000);

    uint8_t buf[6];
    ssize_t r = read(i2c_fd, buf, 6);
    if (r != 6) {
        perror("read(sensor data)");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t rh_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity = 100.0f * (float)rh_raw / 65535.0f;
    return 0;
}

