        perror("sigaction");
        return 1;
    }

    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen(" LOG_FILE ")");
        close(i2c_fd);
        return 1;
    }

    printf("SHT40 greenhouse monitor started. Press Ctrl+C to stop.\n");

    while (running) {
        float temperature, humidity;
