#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define BUFFER_SIZE 60
#define RETRY_COUNT 3
#define MEASUREMENT_DELAY_US 10000
#define POLL_INTERVAL_US 2000000

typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} SensorData;

static SensorData circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_si7021(int handle, float *temperature, float *humidity) {
    char cmd[1];
    char data[2];
    int retries;

    cmd[0] = 0xE3;
    retries = RETRY_COUNT;
    while (retries-- > 0) {
        if (i2cWriteDevice(handle, cmd, 1) == 0) {
            gpioDelay(MEASUREMENT_DELAY_US);
            if (i2cReadDevice(handle, data, 2) == 2) {
                uint16_t raw_temp = ((uint16_t)data[0] << 8) | (uint8_t)data[1];
                *temperature = (175.72f * raw_temp) / 65536.0f - 46.85f;
                return 0;
            }
        }
        gpioDelay(1000);
    }
    fprintf(stderr, "Failed to read temperature after %d retries.\n", RETRY_COUNT);
    return -1;
}

static int read_humidity(int handle, float *humidity) {
    char cmd[1];
    char data[2];
    int retries;

    cmd[0] = 0xE5;
    retries = RETRY_COUNT;
    while (retries-- > 0) {
        if (i2cWriteDevice(handle, cmd, 1) == 0) {
            gpioDelay(MEASUREMENT_DELAY_US);
            if (i2cReadDevice(handle, data, 2) == 2) {
                uint16_t raw_hum = ((uint16_t)data[0] << 8) | (uint8_t)data[1];
                *humidity = (125.0f * raw_hum) / 65536.0f - 6.0f;
                return 0;
            }
        }
        gpioDelay(1000);
    }
    fprintf(stderr, "Failed to read humidity after %d retries.\n", RETRY_COUNT);
    return -1;
}

static void add_to_buffer(float temperature, float humidity) {
    time_t now = time(NULL);
    circular_buffer[buffer_index].timestamp = now;
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].humidity = humidity;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void print_buffer(void) {
    printf("\n--- Sensor Data Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&circular_buffer[idx].timestamp);
        if (tm_info) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("[%s] Temp: %.2f C, Hum: %.2f %%\n", time_str,
                   circular_buffer[idx].temperature, circular_buffer[idx].humidity);
        } else {
            printf("[unknown] Temp: %.2f C, Hum: %.2f %%\n",
                   circular_buffer[idx].temperature, circular_buffer[idx].humidity);
        }
    }
    printf("-----------------------\n");
}

static void control_fan(float temperature) {
    static int fan_on = 0;
    if (temperature > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1);
        fan_on = 1;
        printf("Fan ON (Temp: %.2f C)\n", temperature);
    } else if (temperature < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0);
        fan_on = 0;
        printf("Fan OFF (Temp: %.2f C)\n", temperature);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X on bus %d\n", SI7021_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float temperature, humidity;

    while (running) {
        if (read_si7021(i2c_handle, &temperature, NULL) == 0 &&
            read_humidity(i2c_handle, &humidity) == 0) {
            add_to_buffer(temperature, humidity);
            print_buffer();
            control_fan(temperature);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(FAN_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

