#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SCD40_ADDR 0x62
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define POLL_INTERVAL_MS 100
#define MEASUREMENT_DELAY_S 1

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int send_command(uint16_t cmd) {
    char buf[2] = { (char)(cmd >> 8), (char)(cmd & 0xFF) };
    int rc = i2cWriteDevice(i2c_handle, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "Error sending command 0x%04X: %d\n", cmd, rc);
        return -1;
    }
    return 0;
}

static int read_measurement(uint16_t *co2, float *temp, float *hum) {
    char buf[9];
    int rc = i2cReadDevice(i2c_handle, buf, 9);
    if (rc != 9) {
        fprintf(stderr, "Error reading measurement: expected 9 bytes, got %d\n", rc);
        return -1;
    }

    if (crc8((uint8_t *)buf, 2) != (uint8_t)buf[2]) {
        fprintf(stderr, "CRC error on CO2 word\n");
        return -1;
    }
    if (crc8((uint8_t *)buf + 3, 2) != (uint8_t)buf[5]) {
        fprintf(stderr, "CRC error on temperature word\n");
        return -1;
    }
    if (crc8((uint8_t *)buf + 6, 2) != (uint8_t)buf[8]) {
        fprintf(stderr, "CRC error on humidity word\n");
        return -1;
    }

    uint16_t co2_raw = ((uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    uint16_t temp_raw = ((uint8_t)buf[3] << 8) | (uint8_t)buf[4];
    uint16_t hum_raw = ((uint8_t)buf[6] << 8) | (uint8_t)buf[7];

    *co2 = co2_raw;
    *temp = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *hum = 100.0f * (float)hum_raw / 65535.0f;
    return 0;
}

static int log_data(uint16_t co2, float temp, float hum) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);

    if (fprintf(log_file, "%s,%u,%.2f,%.2f\n", ts, co2, temp, hum) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        send_command(0x3F86);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", SCD40_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (send_command(0x21B1) != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        cleanup();
        return 1;
    }

    sleep(MEASUREMENT_DELAY_S);

    while (!terminate) {
        char ready_buf[2] = { 0xE4, 0xB8 };
        int rc = i2cWriteDevice(i2c_handle, ready_buf, 2);
        if (rc < 0) {
            fprintf(stderr, "Error writing ready flag address: %d\n", rc);
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }

        char ready_resp[3];
        rc = i2cReadDevice(i2c_handle, ready_resp, 3);
        if (rc != 3) {
            fprintf(stderr, "Error reading ready flag: %d\n", rc);
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (crc8((uint8_t *)ready_resp, 2) != (uint8_t)ready_resp[2]) {
            fprintf(stderr, "CRC error on ready flag\n");
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }

        uint16_t ready = ((uint8_t)ready_resp[0] << 8) | (uint8_t)ready_resp[1];
        if (ready == 0x0001) {
            uint16_t co2;
            float temp, hum;
            if (read_measurement(&co2, &temp, &hum) == 0) {
                if (log_data(co2, temp, hum) != 0) {
                    fprintf(stderr, "Logging failed\n");
                }
            } else {
                fprintf(stderr, "Measurement read failed\n");
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    cleanup();
    return 0;
}

