#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS        1
#define SCD40_ADDR     0x62
#define LED_GPIO       17
#define BUFFER_SIZE    20
#define CO2_THRESHOLD  1000
#define POLL_TIMEOUT   1000000  /* 1 s timeout waiting for data-ready */
#define MEAS_INTERVAL  5        /* seconds between measurements */

/* SCD40 commands (16-bit, big-endian on the wire) */
#define CMD_START_PERIODIC  0x21B1
#define CMD_STOP_PERIODIC   0x3F86
#define CMD_GET_DATA_READY  0xE4B8
#define CMD_READ_MEASUREMENT 0xEC05

typedef struct {
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static circular_buffer_t g_buffer;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ---- I2C helpers ---- */
static int i2c_write_cmd(int handle, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (cmd 0x%04X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int handle, uint8_t *buf, int len) {
    int rc = i2cReadDevice(handle, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "I2C read failed: expected %d bytes, got %d (%s)\n",
                len, rc, rc < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

/* ---- SCD40 helpers ---- */
static int scd40_start_periodic(int handle) {
    return i2c_write_cmd(handle, CMD_START_PERIODIC);
}

static int scd40_stop_periodic(int handle) {
    return i2c_write_cmd(handle, CMD_STOP_PERIODIC);
}

static int scd40_data_ready(int handle, bool *ready) {
    if (i2c_write_cmd(handle, CMD_GET_DATA_READY) < 0)
        return -1;

    gpioDelay(2000); /* 2 ms processing time */

    uint8_t buf[3];
    if (i2c_read_bytes(handle, buf, 3) < 0)
        return -1;

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on data-ready status\n");
        return -1;
    }

    uint16_t status = (uint16_t)((buf[0] << 8) | buf[1]);
    *ready = (status & 0x0001) != 0;
    return 0;
}

static int scd40_read_measurement(int handle, sensor_data_t *data) {
    if (i2c_write_cmd(handle, CMD_READ_MEASUREMENT) < 0)
        return -1;

    gpioDelay(2000); /* 2 ms processing time */

    uint8_t buf[9];
    if (i2c_read_bytes(handle, buf, 9) < 0)
        return -1;

    /* Validate CRC for each 2-byte word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on measurement word %d\n", i);
            return -1;
        }
    }

    data->co2        = (uint16_t)((buf[0] << 8) | buf[1]);
    data->temperature = (uint16_t)((buf[3] << 8) | buf[4]);
    data->humidity   = (uint16_t)((buf[6] << 8) | buf[7]);
    return 0;
}

/* ---- Circular buffer ---- */
static void buffer_init(circular_buffer_t *buf) {
    buf->head = 0;
    buf->count = 0;
}

static void buffer_add(circular_buffer_t *buf, sensor_data_t d) {
    buf->data[buf->head] = d;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE)
        buf->count++;
}

/* ---- Signal handling ---- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        scd40_stop_periodic(g_i2c_handle);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ---- Main ---- */
int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    g_i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, SCD40_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (scd40_start_periodic(g_i2c_handle) < 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }

    buffer_init(&g_buffer);

    printf("SCD40 monitoring started. CO2 threshold: %d ppm. Press Ctrl+C to exit.\n",
           CO2_THRESHOLD);

    while (g_running) {
        bool ready = false;
        int poll_start = gpioTick();

        /* Poll data-ready with timeout */
        while (!ready && g_running) {
            if (scd40_data_ready(g_i2c_handle, &ready) < 0) {
                fprintf(stderr, "Data-ready poll failed; retrying...\n");
                gpioDelay(100000); /* 100 ms backoff */
                continue;
            }
            if (!ready) {
                if (gpioTick() - poll_start > POLL_TIMEOUT) {
                    fprintf(stderr, "Timeout waiting for data-ready\n");
                    break;
                }
                gpioDelay(100000); /* 100 ms */
            }
        }

        if (!g_running)
            break;

        if (!ready) {
            /* Sensor may be absent or bus error; skip this cycle */
            gpioDelay(MEAS_INTERVAL * 1000000);
            continue;
        }

        sensor_data_t data;
        if (scd40_read_measurement(g_i2c_handle, &data) < 0) {
            fprintf(stderr, "Measurement read failed; retrying...\n");
            gpioDelay(MEAS_INTERVAL * 1000000);
            continue;
        }

        buffer_add(&g_buffer, data);
        printf("CO2: %u ppm, Temp: %u, Hum: %u\n",
               data.co2, data.temperature, data.humidity);

        if (data.co2 > CO2_THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
            printf("CO2 threshold exceeded! LED ON\n");
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(MEAS_INTERVAL * 1000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

