#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 5000000  /* 5 seconds */
#define EDGE_TIMEOUT_US 50000       /* 50 ms timeout waiting for edge */
#define MAX_CONSECUTIVE_ERRORS 3

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Wait for the GPIO pin to reach the requested level (0 or 1),
 * returning 0 on success or -1 on timeout.
 */
static int wait_for_level(int level) {
    uint32_t start = gpioTick();
    while (gpioRead(GPIO_PIN) != level) {
        if ((gpioTick() - start) > EDGE_TIMEOUT_US) {
            return -1;
        }
    }
    return 0;
}

/*
 * Measure one TMP05 cycle: TH = high-pulse width, TL = total cycle width.
 * Returns 0 on success, -1 on timeout or sensor-absent / stuck-line.
 */
static int read_tmp05(uint32_t *th, uint32_t *tl) {
    /* Wait for falling edge (start of high pulse) */
    if (wait_for_level(0) != 0) {
        return -1;
    }
    uint32_t t_start = gpioTick();

    /* Wait for rising edge (end of high pulse) */
    if (wait_for_level(1) != 0) {
        return -1;
    }
    *th = gpioTick() - t_start;

    /* Wait for falling edge (end of low pulse) */
    if (wait_for_level(0) != 0) {
        return -1;
    }
    *tl = gpioTick() - t_start;
    return 0;
}

/*
 * Convert TMP05 pulse widths to degrees Celsius.
 * Formula: Temperature = 4215 - (2143 * TH / TL)
 */
static float calculate_temperature(uint32_t th, uint32_t tl) {
    if (tl == 0) {
        return -273.15f;  /* Sentinel for division-by-zero */
    }
    return 4215.0f - (2143.0f * (float)th / (float)tl);
}

static void log_temperature(float temperature) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_fp, "%s, %.2f\n", timestamp, temperature);
    fflush(log_fp);
}

static void log_error(const char *message) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_fp, "%s, ERROR: %s\n", timestamp, message);
    fflush(log_fp);
}

int main(void) {
    uint32_t th, tl;
    float temperature;
    int consecutive_errors = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
