                    consecutive_errors, MAX_CONSECUTIVE_ERRORS);

            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                log_error("SENSOR MALFUNCTION - consecutive read failures exceeded threshold");
                consecutive_errors = 0;  /* Reset to avoid flooding log */
            }
        } else {
            consecutive_errors = 0;
            temperature = calculate_temperature(th, tl);

            if (temperature < -40.0f || temperature > 150.0f) {
                log_error("Temperature reading out of valid range");
            } else {
                log_temperature(temperature);
