    int16_t raw_temperature = (data[3] << 8) | data[4];
    int16_t scale_factor = (data[6] << 8) | data[7];

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor (0)\n");
        return -1;
    }

    *pressure = (float)raw_pressure / (float)scale_factor;
    *temperature = (float)raw_temperature / 100.0f;

    return 0;
}

static void log_data(float pressure, float temperature) {
    FILE *fp = fopen(CSV_FILENAME, "a");
    if (!fp) {
        perror("Failed to open CSV file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction failed");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    printf("SDP810 sensor logging started. Press Ctrl+C to stop.\n");

    while (running) {
        float pressure, temperature;

        if (read_sdp810(i2c_fd, &pressure, &temperature) == 0) {
            log_data(pressure, temperature);
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Sensor read failed\n");
        }

        usleep(LOG_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (i2c_fd >= 0)
        close(i2c_fd);

    return 0;
}

