#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT35_ADDR     0x44
#define MEASURE_CMD    0x2400  /* single-shot, high repeatability, clock-stretching disabled */
#define MEASURE_DELAY_US 15000  /* 15 ms worst-case conversion time */
#define SAMPLE_INTERVAL_S 5
#define CSV_FILENAME   "environment.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF) ---- */
static unsigned char crc8(const unsigned char *data, int len)
{
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler for clean shutdown ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Write a CSV header if the file is new or empty ---- */
static int ensure_csv_header(const char *path)
{
    FILE *fp = fopen(path, "r");
    if (fp) {
        fseek(fp, 0, SEEK_END);
        long sz = ftell(fp);
        fclose(fp);
        if (sz > 0)
            return 0;  /* file already has content */
    }
    fp = fopen(path, "w");
    if (!fp) {
        perror("fopen (header)");
        return -1;
    }
    fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
    fclose(fp);
    return 0;
}

/* ---- Read temperature and humidity from SHT35 ----
 * Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.
 */
static int read_sht35(int handle, float *temperature, float *humidity)
{
    unsigned char cmd[2] = {
        (unsigned char)((MEASURE_CMD >> 8) & 0xFF),
        (unsigned char)(MEASURE_CMD & 0xFF)
    };
    unsigned char data[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "Error: i2cWriteDevice failed\n");
        return -1;
    }

    gpioDelay(MEASURE_DELAY_US);

    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: i2cReadDevice failed\n");
        return -1;
    }

    /* Validate CRC for temperature (bytes 0-1, CRC byte 2) */
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Error: temperature CRC mismatch\n");
        return -2;
    }
    /* Validate CRC for humidity (bytes 3-4, CRC byte 5) */
    if (crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "Error: humidity CRC mismatch\n");
        return -2;
    }

    unsigned short temp_raw = ((unsigned short)data[0] << 8) | data[1];
    unsigned short hum_raw  = ((unsigned short)data[3] << 8) | data[4];

    *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *humidity    = 100.0f * (float)hum_raw  / 65535.0f;

    return 0;
}

/* ---- Log a reading to CSV ---- */
static int log_data(const char *filename, float temperature, float humidity)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("fopen (append)");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void)
{
    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Ensure CSV header ---- */
    if (ensure_csv_header(CSV_FILENAME) != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SHT35 logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           CSV_FILENAME, SAMPLE_INTERVAL_S);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        float temperature, humidity;

        int rc = read_sht35(g_i2c_handle, &temperature, &humidity);
        if (rc == 0) {
            if (log_data(CSV_FILENAME, temperature, humidity) != 0)
                fprintf(stderr, "Warning: failed to log data\n");
            else
                printf("Logged: T=%.2f C  RH=%.2f %%\n", temperature, humidity);
        } else if (rc == -1) {
            fprintf(stderr, "Warning: I2C communication error, retrying next cycle\n");
        } else {
            fprintf(stderr, "Warning: CRC error, skipping sample\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

