}

static int wait_for_data(int fd, int timeout_ms) {
    uint8_t status = 0;
    for (int i = 0; i < timeout_ms; i++) {
        if (i2c_read_bytes(fd, &status, 1) != 0) return -1;
        if ((status & 0x0F) != 0) return 0;
        usleep(1000);
    }
    fprintf(stderr, "Timeout waiting for Si7021 data ready\n");
    return -1;
}

static int read_measurement(int fd, uint8_t cmd, uint16_t *raw) {
    if (i2c_write_cmd(fd, cmd) != 0) return -1;
    if (wait_for_data(fd, POLL_TIMEOUT_MS) != 0) return -1;
    uint8_t buf[3];
    if (i2c_read_bytes(fd, buf, 3) != 0) return -1;
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on measurement 0x%02X\n", cmd);
        return -1;
    }
    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int read_temperature(int fd, float *temp) {
    uint16_t raw;
    if (read_measurement(fd, CMD_MEASURE_T, &raw) != 0) return -1;
    *temp = (175.72f * (float)raw) / 65536.0f - 46.85f;
    return 0;
}

static int read_humidity(int fd, float *hum) {
    uint16_t raw;
    if (read_measurement(fd, CMD_MEASURE_RH, &raw) != 0) return -1;
    *hum = (125.0f * (float)raw) / 65536.0f - 6.0f;
    if (*hum < 0.0f) *hum = 0.0f;
    if (*hum > 100.0f) *hum = 100.0f;
    return 0;
}

static int read_temperature_rh(int fd, float *temp) {
    if (i2c_write_cmd(fd, CMD_MEASURE_T_RH) != 0) return -1;
    if (wait_for_data(fd, POLL_TIMEOUT_MS) != 0) return -1;
    uint8_t buf[3];
    if (i2c_read_bytes(fd, buf, 3) != 0) return -1;
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on T_RH measurement\n");
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp = (175.72f * (float)raw) / 65536.0f - 46.85f;
    return 0;
}

static void log_data(float temp, float hum) {
    FILE *fp = fopen("environment.log", "a");
    if (!fp) {
        fprintf(stderr, "Failed to open environment.log: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    if (temp < -50.0f || hum < 0.0f || hum > 100.0f) {
        fprintf(fp, "%s,ERROR,ERROR\n", ts);
        fprintf(stderr, "Logging error line: %s,ERROR,ERROR\n", ts);
    } else {
        fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, hum);
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", SI7021_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (i2c_write_cmd(g_i2c_fd, CMD_RESET) != 0) {
        fprintf(stderr, "Warning: sensor reset failed; continuing anyway\n");
    }
    usleep(15000);

    while (g_running) {
        float temp = -100.0f, hum = -1.0f;
        int ok = 0;

        if (read_humidity(g_i2c_fd, &hum) == 0) {
            if (read_temperature_rh(g_i2c_fd, &temp) == 0) {
                ok = 1;
            } else {
                fprintf(stderr, "Temperature read failed; resetting sensor\n");
                i2c_write_cmd(g_i2c_fd, CMD_RESET);
                usleep(15000);
            }
        } else {
            fprintf(stderr, "Humidity read failed; resetting sensor\n");
            i2c_write_cmd(g_i2c_fd, CMD_RESET);
            usleep(15000);
        }

        if (ok) {
            log_data(temp, hum);
        }

        for (int s = 0; s < SAMPLE_INTERVAL_S && g_running; s++) {
            sleep(1);
        }
    }

    if (g_i2c_fd >= 0) {
        i2c_write_cmd(g_i2c_fd, CMD_RESET);
        close(g_i2c_fd);
    }
    return 0;
}

