#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD_MSB 0x36
#define MEASURE_CMD_LSB 0x2F
#define CONVERSION_DELAY_US 20000
#define SAMPLE_INTERVAL_US 1000000
#define DATA_FILE "airflow.dat"

static int i2c_handle = -1;
static FILE *data_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sdp810(float *pressure, float *temperature) {
    uint8_t cmd[2] = {MEASURE_CMD_MSB, MEASURE_CMD_LSB};
    uint8_t buf[9];

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to write measurement command to I2C device.\n");
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    if (i2cReadDevice(i2c_handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "Error: Failed to read 9 bytes from I2C device.\n");
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: Pressure CRC mismatch.\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    uint16_t scale_factor = (uint16_t)((buf[6] << 8) | buf[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Error: Invalid scale factor (0).\n");
        return -1;
    }

    *pressure = ((float)raw_pressure / (float)scale_factor) - 1000.0f;
    *temperature = ((float)raw_temperature / 200.0f) - 45.0f;

    return 0;
}

static int log_data(float pressure, float temperature) {
    if (data_file == NULL) {
        data_file = fopen(DATA_FILE, "ab");
        if (data_file == NULL) {
            fprintf(stderr, "Error: Failed to open data file '%s': %s\n", DATA_FILE, strerror(errno));
            return -1;
        }
    }

    if (fwrite(&pressure, sizeof(float), 1, data_file) != 1) {
        fprintf(stderr, "Error: Failed to write pressure to file: %s\n", strerror(errno));
        return -1;
    }
    if (fwrite(&temperature, sizeof(float), 1, data_file) != 1) {
        fprintf(stderr, "Error: Failed to write temperature to file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(data_file) != 0) {
        fprintf(stderr, "Error: Failed to flush data file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at bus %d, address 0x%02X (pigpio error %d).\n", I2C_BUS, SDP810_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGTERM handler: %s\n", strerror(errno));
    }

    printf("SDP810 HVAC airflow monitor started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        float pressure, temperature;

        if (read_sdp810(&pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);
            if (log_data(pressure, temperature) != 0) {
                fprintf(stderr, "Warning: Failed to log data sample.\n");
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping sample.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");

    if (data_file != NULL) {
        if (fclose(data_file) != 0) {
            fprintf(stderr, "Warning: Failed to close data file: %s\n", strerror(errno));
        }
        data_file = NULL;
    }

    if (i2c_handle >= 0) {
        if (i2cClose(i2c_handle) != 0) {
            fprintf(stderr, "Warning: Failed to close I2C handle.\n");
        }
        i2c_handle = -1;
    }

    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

