#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LPS33HW_ADDR 0x5D
#define WHO_AM_I 0x0F
#define WHO_AM_I_VAL 0xB1
#define CTRL_REG1 0x10
#define CTRL_REG1_VAL 0xB0
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C
#define LOG_FILE "environmental_data.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    localtime_r(&now, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(stderr, "%s, ERROR: %s\n", timestamp, message);
    if (log_file) {
        fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
        fflush(log_file);
    }
}

static int read_register(uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(i2c_handle, reg);
    if (result < 0) {
        log_error("Failed to read register");
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        log_error("Failed to write register");
        return -1;
    }
    return 0;
}

static int read_pressure(int32_t *pressure) {
    uint8_t xl, l, h;
    if (read_register(PRESS_OUT_XL, &xl) < 0) return -1;
    if (read_register(PRESS_OUT_L, &l) < 0) return -1;
    if (read_register(PRESS_OUT_H, &h) < 0) return -1;
    *pressure = (int32_t)((((uint32_t)h << 16) | ((uint32_t)l << 8) | (uint32_t)xl) >> 8);
    if (*pressure & 0x00800000) *pressure |= 0xFF000000;
    return 0;
}

static int read_temperature(int16_t *temperature) {
    uint8_t l, h;
    if (read_register(TEMP_OUT_L, &l) < 0) return -1;
    if (read_register(TEMP_OUT_H, &h) < 0) return -1;
    *temperature = (int16_t)(((uint16_t)h << 8) | (uint16_t)l);
    return 0;
}

static void log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    localtime_r(&now, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t who_am_i = 0;
    if (read_register(WHO_AM_I, &who_am_i) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (write_register(CTRL_REG1, CTRL_REG1_VAL) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (program_running) {
        int32_t raw_pressure;
        int16_t raw_temperature;

        if (read_pressure(&raw_pressure) == 0 && read_temperature(&raw_temperature) == 0) {
            float pressure = (float)raw_pressure / 4096.0f;
            float temperature = 42.5f + (float)raw_temperature / 480.0f;
            log_data(pressure, temperature);
        } else {
            log_error("Failed to read sensor data");
        }
        gpioDelay(1000000);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

