#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define TEMP_REG       0x00
#define LED_GPIO       17
#define BUFFER_SIZE    10
#define TEMP_THRESHOLD 28.0f
#define POLL_DELAY_US  1000000  /* 1 second */

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static CircularBuffer temp_buffer = {0};

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/*
 * Read temperature from STLM75.
 * pigpio's i2cReadWordData returns a 16-bit word whose low byte is
 * the first byte received and high byte is the second byte received.
 * The STLM75 sends the MSB first, so we swap the bytes before
 * extracting the 9-bit two's-complement value.
 */
static int read_temperature(float *out_temp)
{
    int raw = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %d\n", TEMP_REG, raw);
        return -1;
    }

    /* Swap bytes: pigpio returns little-endian, STLM75 sends MSB first */
    int swapped = ((raw & 0xFF) << 8) | ((raw >> 8) & 0xFF);

    /*
     * STLM75 9-bit two's-complement:
     *   bit 15 = sign
     *   bits 14..7 = data (8 bits)
     *   bits 6..0 = 0 (always)
     * Shift right 7 to get the signed 9-bit value, then divide by 2.
     */
    int9_t signed_val = (int9_t)(swapped >> 7);
    *out_temp = (float)signed_val / 2.0f;
    return 0;
}

static void buffer_add(CircularBuffer *cb, float value)
{
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static float buffer_average(const CircularBuffer *cb)
{
    if (cb->count == 0)
        return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++)
        sum += cb->buffer[i];
    return sum / (float)cb->count;
}

static void control_led(float avg_temp)
{
    gpioWrite(LED_GPIO, (avg_temp > TEMP_THRESHOLD) ? 1 : 0);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("STLM75 temperature monitor started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float temp;
        if (read_temperature(&temp) == 0) {
            buffer_add(&temp_buffer, temp);
            float avg = buffer_average(&temp_buffer);
            control_led(avg);
            printf("Temp: %.2f C | Avg: %.2f C | LED: %s\n",
                   temp, avg,
                   (avg > TEMP_THRESHOLD) ? "ON" : "OFF");
        } else {
            fprintf(stderr, "Read failed; skipping iteration.\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0)
        i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

