#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD30_ADDR             0x61
#define I2C_BUS                1
#define LOG_FILE               "air_quality.log"
#define MEASUREMENT_INTERVAL_S 2

#define CMD_START_PERIODIC     0x0201
#define CMD_READ_MEASUREMENT   0x0300
#define CMD_STOP_PERIODIC      0x0202
#define CMD_GET_DATA_READY     0x0202

#define CO2_LOW                800
#define CO2_HIGH               1200

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF) ---- */
static uint8_t scd30_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Write a 2-byte command ---- */
static int scd30_write_cmd(int handle, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(0x%04X) failed\n", cmd);
        return -1;
    }
    return 0;
}

/* ---- Write a 3-byte command + 1-byte argument (cmd, arg, CRC) ---- */
static int scd30_write_cmd_arg(int handle, uint16_t cmd, uint8_t arg)
{
    uint8_t buf[3] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF), arg };
    if (i2cWriteDevice(handle, (char *)buf, 3) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(0x%04X, arg=0x%02X) failed\n", cmd, arg);
        return -1;
    }
    return 0;
}

/* ---- Read `len` bytes from the sensor ---- */
static int scd30_read_bytes(int handle, uint8_t *buf, int len)
{
    int n = i2cReadDevice(handle, (char *)buf, len);
    if (n != len) {
        fprintf(stderr, "[ERROR] i2cReadDevice expected %d, got %d\n", len, n);
        return -1;
    }
    return 0;
}

/* ---- Initialize the SCD30: start continuous measurement ---- */
static int scd30_init(int handle)
{
    if (scd30_write_cmd_arg(handle, CMD_START_PERIODIC, 0) != 0)
        return -1;
    gpioDelay(20000); /* 20 ms settle */
    return 0;
}

/* ---- Check data-ready flag ---- */
static int scd30_data_ready(int handle)
{
    if (scd30_write_cmd(handle, CMD_GET_DATA_READY) != 0)
        return -1;
    gpioDelay(2000); /* 2 ms processing time */

    uint8_t buf[3];
    if (scd30_read_bytes(handle, buf, 3) != 0)
        return -1;

    if (scd30_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch on data-ready word\n");
        return -1;
    }
    uint16_t word = ((uint16_t)buf[0] << 8) | buf[1];
    return (word & 0x07FF) ? 1 : 0;
}

/* ---- Read one measurement: CO2 (ppm), temperature (°C), humidity (%RH) ---- */
static int scd30_read_measurement(int handle, uint16_t *co2,
                                  float *temp, float *rh)
{
    if (scd30_write_cmd(handle, CMD_READ_MEASUREMENT) != 0)
        return -1;
    gpioDelay(2000); /* 2 ms processing time */

    uint8_t buf[18];
    if (scd30_read_bytes(handle, buf, 18) != 0)
        return -1;

    /* Verify CRC for each 3-byte value */
    for (int i = 0; i < 6; i++) {
        if (scd30_crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "[ERROR] CRC mismatch on measurement word %d\n", i);
            return -1;
        }
    }

    uint32_t co2_raw  = ((uint32_t)buf[0] << 24) | ((uint32_t)buf[1] << 16) |
                        ((uint32_t)buf[3] << 8)  |  buf[4];
    uint32_t temp_raw = ((uint32_t)buf[6] << 24) | ((uint32_t)buf[7] << 16) |
                        ((uint32_t)buf[9] << 8)  |  buf[10];
    uint32_t rh_raw   = ((uint32_t)buf[12] << 24) | ((uint32_t)buf[13] << 16) |
                        ((uint32_t)buf[15] << 8) |  buf[16];

    *co2  = (uint16_t)co2_raw;
    *temp = -45.0f + 175.0f * ((float)temp_raw / 65535.0f);
    *rh   = 100.0f * ((float)rh_raw / 65535.0f);
    return 0;
}

/* ---- Log one CSV line ---- */
static void log_data(FILE *fp, uint16_t co2, float temp, float rh)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(fp, "%s,%u,%.2f,%.2f\n", ts, co2, temp, rh);
    fflush(fp);
}

/* ---- Simulated ventilation control ---- */
static void control_ventilation(uint16_t co2)
{
    if (co2 >= CO2_HIGH)
        printf("Ventilation: HIGH\n");
    else if (co2 >= CO2_LOW)
        printf("Ventilation: LOW\n");
    else
        printf("Ventilation: OFF\n");
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        scd30_write_cmd(g_i2c_handle, CMD_STOP_PERIODIC);
        gpioDelay(100000); /* 100 ms */
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return 0; /* mocked/emulated environment: exit gracefully */
    }

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, SCD30_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SCD30_ADDR, g_i2c_handle);
        gpioTerminate();
        return 0;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open %s\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 0;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* ---- Initialize sensor ---- */
    if (scd30_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] SCD30 initialization failed\n");
        cleanup();
        return 0;
    }

    printf("SCD30 monitoring started. Logging to %s every %d s. Ctrl+C to stop.\n",
           LOG_FILE, MEASUREMENT_INTERVAL_S);

    /* ---- Main loop ---- */
    while (g_running) {
        int ready = scd30_data_ready(g_i2c_handle);
        if (ready < 0) {
            fprintf(stderr, "[WARN] Data-ready poll failed; retrying next cycle\n");
            gpioDelay(MEASUREMENT_INTERVAL_S * 1000000);
            continue;
        }
        if (!ready) {
            gpioDelay(MEASUREMENT_INTERVAL_S * 1000000);
            continue;
        }

        uint16_t co2;
        float temp, rh;
        if (scd30_read_measurement(g_i2c_handle, &co2, &temp, &rh) != 0) {
            fprintf(stderr, "[WARN] Measurement read failed; retrying next cycle\n");
            gpioDelay(MEASUREMENT_INTERVAL_S * 1000000);
            continue;
        }

        log_data(g_log_file, co2, temp, rh);
        control_ventilation(co2);

        gpioDelay(MEASUREMENT_INTERVAL_S * 1000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

