#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SDP32_ADDR 0x21
#define I2C_BUS 1
#define SAMPLE_INTERVAL_DEFAULT 1000
#define SDP32_MEAS_CMD_LEN 2
#define SDP32_MEAS_CMD_MSB 0x36
#define SDP32_MEAS_CMD_LSB 0x2F
#define SDP32_READ_LEN 9
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int send_measurement_command(int handle) {
    uint8_t cmd[SDP32_MEAS_CMD_LEN] = {SDP32_MEAS_CMD_MSB, SDP32_MEAS_CMD_LSB};
    int result = i2cWriteDevice(handle, (char *)cmd, SDP32_MEAS_CMD_LEN);
    if (result != 0) {
        fprintf(stderr, "Error sending measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, float *pressure_pa, float *temperature_c) {
    uint8_t buffer[SDP32_READ_LEN];
    int result = i2cReadDevice(handle, (char *)buffer, SDP32_READ_LEN);
    if (result != SDP32_READ_LEN) {
        fprintf(stderr, "Error reading sensor data: expected %d bytes, got %d\n", SDP32_READ_LEN, result);
        return -1;
    }

    if (crc8(&buffer[0], 2) != buffer[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
