#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP810_ADDR    0x25
#define CMD_CONT_MEAS  0x3615
#define CONV_DELAY_US  45000   /* 45 ms worst-case conversion time */
#define SAMPLE_PERIOD  1000000 /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read one continuous-measurement frame from the SDP810.
 * Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.
 */
static int read_sdp810(int handle, float *pressure, float *temperature)
{
    uint8_t cmd[2] = {
        (uint8_t)((CMD_CONT_MEAS >> 8) & 0xFF),
        (uint8_t)(CMD_CONT_MEAS & 0xFF)
    };

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed (sensor may be absent or bus error)\n");
        return -1;
    }

    gpioDelay(CONV_DELAY_US);

    uint8_t buf[9];
    int n = i2cReadDevice(handle, (char *)buf, 9);
    if (n != 9) {
        fprintf(stderr, "Error: i2cReadDevice returned %d (expected 9)\n", n);
        return -1;
    }

    /* Validate CRC on each 3-byte word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "Error: CRC mismatch on word %d\n", i);
            return -2;
        }
    }

    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_p        = (int16_t)((buf[6] << 8) | buf[7]);

    if (scale_p == 0) {
        fprintf(stderr, "Error: scale factor for pressure is zero\n");
        return -1;
    }

    *pressure    = (float)raw_pressure / (float)scale_p;
    *temperature = (float)raw_temperature / 200.0f;

    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d) — check wiring and address\n",
                g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SDP810 continuous measurement started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float pressure, temperature;

        int rc = read_sdp810(g_i2c_handle, &pressure, &temperature);
        if (rc == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   pressure, temperature);
        } else if (rc == -1) {
            fprintf(stderr, "Warning: I2C bus error — continuing\n");
        } else {
            fprintf(stderr, "Warning: CRC error — continuing\n");
        }

        gpioDelay(SAMPLE_PERIOD);
    }

    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

