#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HDC1000_ADDR        0x40
#define TEMP_REG            0x00
#define CONFIG_REG          0x02
#define I2C_BUS             "/dev/i2c-1"
#define READ_INTERVAL_SEC   5
#define CONV_DELAY_MS       20

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_byte(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_bytes: write pointer 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "i2c_read_bytes: read %zu bytes from 0x%02X failed: %s\n",
                len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int hdc1000_init(int fd)
{
    /*
     * Configuration Register (pointer 0x02):
     *   Bit 12 (T_EN) = 1  -> enable temperature measurement
     *   Bit 13 (H_EN) = 1  -> enable humidity measurement
     *   Bits 10:11 (TRES) = 10 -> 14-bit temperature resolution
     *   Bits 14:15 (HRES) = 10 -> 14-bit humidity resolution
     *   Bit 11 (HEAT) = 0  -> heater disabled (default)
     * => 0x0000 | (1 << 12) | (1 << 13) | (2 << 10) | (2 << 14)
     *   = 0x0000 | 0x0400 | 0x0800 | 0x0080 | 0x4000
     *   = 0x4C00
     */
    if (i2c_write_byte(fd, CONFIG_REG, 0xC0) < 0)
        return -1;
    return 0;
}

static int hdc1000_read(int fd, float *temperature, float *humidity)
{
    uint8_t buf[4];

    if (i2c_write_byte(fd, TEMP_REG, 0x00) < 0)
        return -1;

    usleep(CONV_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, TEMP_REG, buf, sizeof(buf)) < 0)
        return -1;

    uint16_t raw_temp = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t raw_hum  = ((uint16_t)buf[2] << 8) | buf[3];

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity    = ((float)raw_hum  / 65536.0f) * 100.0f;

    return 0;
}

int main(void)
{
    int fd = -1;
    float temperature, humidity;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        fprintf(stderr, "Ensure the I2C bus is enabled (raspi-config) and the sensor is connected.\n");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                HDC1000_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (hdc1000_init(fd) < 0) {
        fprintf(stderr, "HDC1000 initialization failed (sensor absent or bus error).\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("HDC1000 initialized on %s (addr 0x%02X). Reading every %d s.\n",
           I2C_BUS, HDC1000_ADDR, READ_INTERVAL_SEC);

    while (g_running) {
        if (hdc1000_read(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read temperature/humidity.\n");
        }

        for (int i = 0; i < READ_INTERVAL_SEC && g_running; i++)
            sleep(1);
    }

    printf("\nExiting cleanly.\n");
    if (fd >= 0)
        close(fd);
    return EXIT_SUCCESS;
}

