#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define TEMP_MEASURE_CMD 0xE3
#define TEMP_READ_CMD 0xE0
#define MEASURE_DELAY_US 10000
#define POLL_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(float *temperature) {
    char cmd = TEMP_MEASURE_CMD;
    char buf[2];

    // Send measurement command
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to write measurement command to Si7051.\n");
        return -1;
    }

    // Wait for measurement to complete
    gpioDelay(MEASURE_DELAY_US);

    // Send read command
    cmd = TEMP_READ_CMD;
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to write read command to Si7051.\n");
        return -1;
    }

    // Read 2 bytes of temperature data
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read temperature data from Si7051.\n");
        return -1;
    }

    uint16_t raw_temp = ((uint16_t)buf[0] << 8) | (uint16_t)buf[1];
    *temperature = (175.72f * raw_temp / 65536.0f) - 46.85f;

    return 0;
}

