    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d.\n", SI7051_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handlers for graceful shutdown
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si7051 Temperature Sensor Reader\n");
    printf("Reading every %d seconds. Press Ctrl+C to exit.\n", POLL_INTERVAL_S);

    while (running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Error: Failed to read temperature.\n");
        }

        // Sleep in 1-second increments to allow responsive signal handling
        for (int i = 0; i < POLL_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }

    // Clean up resources
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

