#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define MLX90833_ADDR 0x60
#define READ_INTERVAL_US 500000

/*
 * MLX90833 (datasheet) register addresses (16-bit, big-endian on the bus):
 *   0x0000 - 0x000F : Reserved
 *   0x0010 - 0x001F : Configuration
 *   0x0020 - 0x002F : Status
 *   0x0030 - 0x003F : Pressure (24-bit, 2's complement)
 *   0x0040 - 0x004F : Temperature (24-bit, 2's complement)
 *   0x0050 - 0x005F : Scale factors
 *   0x0060 - 0x006F : Calibration
 *   0x0070 - 0x007F : Reserved
 */
#define PRESSURE_REG 0x0030
#define CONFIG_REG   0x0010

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read a 24-bit 2's complement value from a 3-byte register.
 * pigpio's i2cReadI2CBlockData returns data in little-endian byte order
 * (low byte first), so we swap bytes to get the big-endian register value.
 */
static int32_t read_24bit_value(int handle, uint16_t reg) {
    char buf[3];
    int rc;

    rc = i2cReadI2CBlockData(handle, reg, buf, 3);
    if (rc != 3) {
        fprintf(stderr, "Error reading register 0x%04X: rc=%d (errno=%d: %s)\n",
                reg, rc, errno, strerror(errno));
        return 0;
    }

    /* Swap bytes to convert little-endian on-bus data to big-endian register value */
    uint32_t raw = ((uint32_t)(uint8_t)buf[2] << 16) |
                   ((uint32_t)(uint8_t)buf[1] << 8)  |
                   ((uint32_t)(uint8_t)buf[0]);

    /* Sign-extend 24-bit value to 32-bit int */
    if (raw & 0x00800000) {
        raw |= 0xFF000000;
    }

    return (int32_t)raw;
}

static int write_config(int handle, uint16_t reg, uint16_t value) {
    char buf[2];
    int rc;

    buf[0] = (value >> 8) & 0xFF;
    buf[1] = value & 0xFF;

    rc = i2cWriteI2CBlockData(handle, reg, buf, 2);
    if (rc != 0) {
        fprintf(stderr, "Error writing config register 0x%04X: rc=%d (errno=%d: %s)\n",
                reg, rc, errno, strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90833_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, MLX90833_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /*
     * Basic configuration: enable pressure measurement.
     * The exact register bits depend on the MLX90833 variant; this is a
     * representative starting point. Adjust per your specific datasheet.
     */
    if (write_config(i2c_handle, CONFIG_REG, 0x0001) != 0) {
        fprintf(stderr, "Failed to configure MLX90833\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Allow sensor to settle after configuration */
    gpioDelay(100000); /* 100 ms */

    while (running) {
        int32_t pressure_raw = read_24bit_value(i2c_handle, PRESSURE_REG);

        if (pressure_raw == 0) {
            /*
             * A zero reading could indicate a sensor-absent or bus error.
             * We log it and continue so the loop doesn't hang on a single failure.
             */
            fprintf(stderr, "Warning: Pressure read returned 0 (sensor may be absent or bus error)\n");
        } else {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            printf("%s: Pressure: %d Pa\n", timestamp, pressure_raw);
            fflush(stdout);
        }

        gpioDelay(READ_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

