#define I2C_BUS        1
#define I2C_ADDR       0x63
#define READ_INTERVAL  5.0
#define MEAS_DELAY_US  7000

/* ICP-10101 commands */
#define CMD_READ_OTP    0x50
#define CMD_MEAS_HP     0x40

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* Calibration coefficients (OTP read) */
static uint16_t cal_a0, cal_a1, cal_a2, cal_a3;
static float     scale_factor_lut, scale_factor_h, scale_factor_p;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read 8 bytes of OTP calibration data (command 0x50) */
static int read_calibration(void)
{
    char cmd = CMD_READ_OTP;
    char buf[8];

    if (i2cWriteDevice(g_i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write OTP read command\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms settle */

    if (i2cReadDevice(g_i2c_handle, buf, 8) != 8) {
        fprintf(stderr, "Error: failed to read 8 OTP bytes\n");
        return -1;
    }

    cal_a0 = (uint16_t)((buf[0] << 8) | buf[1]);
    cal_a1 = (uint16_t)((buf[2] << 8) | buf[3]);
    cal_a2 = (uint16_t)((buf[4] << 8) | buf[5]);
    cal_a3 = (uint16_t)((buf[6] << 8) | buf[7]);

    /* Compute scaling factors per datasheet */
    scale_factor_lut = (float)cal_a0 / 65536.0f;
    scale_factor_h   = (float)cal_a1 / 65536.0f;
    scale_factor_p   = (float)cal_a2 / 65536.0f;

    return 0;
}

/* Trigger high-precision measurement and read 6 bytes */
static int read_measurement(float *temperature, float *pressure)
{
    char cmd = CMD_MEAS_HP;
    char buf[6];

    if (i2cWriteDevice(g_i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write measurement command\n");
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);

    if (i2cReadDevice(g_i2c_handle, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read measurement data\n");
        return -1;
    }

    /* All 0xFF indicates sensor absent or not responding */
    if (buf[0] == 0xFF && buf[1] == 0xFF &&
        buf[2] == 0xFF && buf[3] == 0xFF &&
        buf[4] == 0xFF && buf[5] == 0xFF) {
        fprintf(stderr, "Error: sensor absent or not responding (0xFF)\n");
        return -1;
    }

    uint16_t raw_t = (uint16_t)((buf[0] << 8) | buf[1]);
    uint32_t raw_p = (uint32_t)(((uint16_t)buf[2] << 16) |
                               ((uint16_t)buf[3] << 8)  |
                               (uint16_t)buf[4]);

    /* Datasheet compensation formulas */
    float t = (float)raw_t * scale_factor_lut;
    float p = (float)raw_p * scale_factor_p;
    float h = (float)raw_t * scale_factor_h;

    *temperature = t;
    *pressure    = p;
    return 0;
}

