    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (read_calibration() != 0) {
        fprintf(stderr, "Error: calibration read failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ICP-10101 initialised. Logging every %.1f s. Press Ctrl+C to stop.\n",
