#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX90819_ADDR  0x60
#define PRESSURE_MSB   0xAA
#define PRESSURE_LSB   0xAB
#define SCALE_FACTOR   0.1f
#define POLL_INTERVAL  1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write to register 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from register failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_pressure(int fd, float *pressure_kPa) {
    uint8_t msb, lsb;

    if (i2c_write_byte(fd, PRESSURE_MSB) < 0)
        return -1;

    usleep(10000);

    if (i2c_read_byte(fd, &msb, 1) < 0)
        return -1;

    if (i2c_write_byte(fd, PRESSURE_LSB) < 0)
        return -1;

    usleep(10000);

    if (i2c_read_byte(fd, &lsb, 1) < 0)
        return -1;

    uint16_t raw = ((uint16_t)msb << 8) | lsb;
    *pressure_kPa = (float)raw * SCALE_FACTOR;
    return 0;
}

int main(void) {
    int fd = -1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90819_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MLX90819_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MLX90819 pressure sensor reader started on %s (addr 0x%02X). Press Ctrl+C to exit.\n", I2C_BUS, MLX90819_ADDR);

    while (g_running) {
        float pressure;
        if (read_pressure(fd, &pressure) == 0) {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];
            localtime_r(&now, &tm_info);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
            printf("[%s] Pressure: %.2f kPa\n", ts, pressure);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read pressure value.\n");
        }
        sleep(POLL_INTERVAL);
    }

    printf("\nExiting gracefully...\n");
    if (fd >= 0)
        close(fd);
    return EXIT_SUCCESS;
}

