#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define PRESSURE_REG   0x00
#define SCALE_FACTOR   0.01f
#define MIN_PRESSURE   200.0f
#define MAX_PRESSURE   250.0f
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_US      1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio error %d).\n", g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_pressure(float *pressure_out)
{
    char buf[2];
    int  result;

    result = i2cReadI2CBlockData(g_i2c_handle, PRESSURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: i2cReadI2CBlockData returned %d (expected 2).\n", result);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *pressure_out = (float)raw * SCALE_FACTOR;
    return 0;
}

static void log_pressure(float pressure)
{
    time_t     rawtime;
    struct tm *timeinfo;
    char       timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: gmtime failed.\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(g_log_file, "%s,%.2f\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed.\n");
    }
    fflush(g_log_file);
}

static void check_pressure_range(float pressure)
{
    if (pressure < MIN_PRESSURE || pressure > MAX_PRESSURE) {
        fprintf(stderr, "WARNING: Pressure %.2f kPa is outside safe range [%.0f, %.0f] kPa.\n",
                pressure, MIN_PRESSURE, MAX_PRESSURE);
    }
}

int main(void)
{
    float pressure;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a+");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    if (fseek(g_log_file, 0, SEEK_END) == 0) {
        long sz = ftell(g_log_file);
        if (sz == 0) {
            fprintf(g_log_file, "timestamp,pressure_kPa\n");
            fflush(g_log_file);
        }
    } else {
        fprintf(stderr, "Warning: fseek failed; assuming file exists and has header.\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction failed; signals may not be caught cleanly.\n");
    }

    printf("Tire pressure monitoring started. Logging to %s\n", LOG_FILE);

    while (g_running) {
        if (read_pressure(&pressure) == 0) {
            log_pressure(pressure);
            check_pressure_range(pressure);
        } else {
            fprintf(stderr, "Error: I2C read failed. Re-initialising bus...\n");
            if (init_i2c() != 0) {
                fprintf(stderr, "Error: I2C re-init failed. Exiting.\n");
                break;
            }
            /* Retry once after re-initialisation */
            if (read_pressure(&pressure) == 0) {
                log_pressure(pressure);
                check_pressure_range(pressure);
            } else {
                fprintf(stderr, "Error: I2C read failed after re-init. Exiting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_US);
    }

    /* Clean shutdown */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();

    printf("Shutdown complete.\n");
    return EXIT_SUCCESS;
}

