#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 4
#define TICK_US 3
#define SYNC_TICKS 56
#define NIBBLE_MIN_TICKS 12
#define NIBBLE_MAX_TICKS 271
#define NUM_NIBBLES 4
#define LOG_FILE "pressure_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sent_nibble(int gpio_pin, int *pulse_width) {
    uint32_t start_tick = gpioTick();
    while (gpioRead(gpio_pin) == 1) {
        if (gpioTick() - start_tick > 1000000) {
            fprintf(stderr, "SENT timeout waiting for falling edge\n");
            return -1;
        }
    }
    uint32_t low_start = gpioTick();
    while (gpioRead(gpio_pin) == 0) {
        if (gpioTick() - low_start > 1000000) {
            fprintf(stderr, "SENT timeout waiting for rising edge\n");
            return -1;
        }
    }
    uint32_t high_start = gpioTick();
    while (gpioRead(gpio_pin) == 1) {
        if (gpioTick() - high_start > 1000000) {
            fprintf(stderr, "SENT timeout waiting for falling edge\n");
            return -1;
        }
    }
    uint32_t end_tick = gpioTick();
    *pulse_width = (int)(end_tick - high_start);
    return 0;
}

static int read_sent_frame(int gpio_pin, uint16_t *raw_pressure) {
    int nibbles[NUM_NIBBLES];
    int pulse_width;

    // Read synchronization pulse
    if (read_sent_nibble(gpio_pin, &pulse_width) != 0) return -1;
    if (pulse_width < (SYNC_TICKS - 10) || pulse_width > (SYNC_TICKS + 10)) {
        fprintf(stderr, "SENT sync pulse width invalid: %d ticks\n", pulse_width);
        return -1;
    }

    // Read status nibble
    if (read_sent_nibble(gpio_pin, &pulse_width) != 0) return -1;
    if (pulse_width < NIBBLE_MIN_TICKS || pulse_width > NIBBLE_MAX_TICKS) {
        fprintf(stderr, "SENT status nibble pulse width invalid: %d ticks\n", pulse_width);
        return -1;
    }
    nibbles[0] = (pulse_width - 12) / 3;

    // Read 3 data nibbles
    for (int i = 1; i < NUM_NIBBLES; i++) {
        if (read_sent_nibble(gpio_pin, &pulse_width) != 0) return -1;
        if (pulse_width < NIBBLE_MIN_TICKS || pulse_width > NIBBLE_MAX_TICKS) {
            fprintf(stderr, "SENT data nibble %d pulse width invalid: %d ticks\n", i, pulse_width);
            return -1;
        }
        nibbles[i] = (pulse_width - 12) / 3;
    }

    // Read checksum nibble
    if (read_sent_nibble(gpio_pin, &pulse_width) != 0) return -1;
    if (pulse_width < NIBBLE_MIN_TICKS || pulse_width > NIBBLE_MAX_TICKS) {
        fprintf(stderr, "SENT checksum nibble pulse width invalid: %d ticks\n", pulse_width);
        return -1;
    }
    int checksum_nibble = (pulse_width - 12) / 3;

    // Validate checksum
    int calc_checksum = (nibbles[0] + nibbles[1] + nibbles[2] + nibbles[3]) & 0x0F;
    if (calc_checksum != checksum_nibble) {
        fprintf(stderr, "SENT checksum mismatch: calc=0x%X, recv=0x%X\n", calc_checksum, checksum_nibble);
        return -1;
    }

    // Extract 12-bit raw pressure value
    *raw_pressure = ((uint16_t)nibbles[1] << 8) | ((uint16_t)nibbles[2] << 4) | nibbles[3];
    return 0;
}

static float convert_to_pressure(uint16_t raw_pressure) {
    return (float)raw_pressure * 0.01f;
}

static void log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Brake pressure monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t raw_pressure;
        if (read_sent_frame(GPIO_PIN, &raw_pressure) == 0) {
            float pressure = convert_to_pressure(raw_pressure);
            log_pressure(pressure);
            printf("Pressure: %.2f Pa\n", pressure);
        } else {
            fprintf(stderr, "Error reading pressure data\n");
        }
        gpioDelay(100000); // 100 ms
    }

    gpioTerminate();
    printf("Brake pressure monitoring stopped.\n");
    return 0;
}

