#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TMP117_DEVICE_ID_REG 0x0017
#define TMP117_TEMP_REG 0x00
#define DATA_FILE "greenhouse_temps.dat"
#define SLEEP_INTERVAL 60

static int i2c_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_device_id(int handle, uint16_t *device_id) {
    char buf[2];
    if (i2cReadI2CBlockData(handle, TMP117_DEVICE_ID_REG, buf, 2) != 2) {
        return -1;
    }
    *device_id = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int read_temperature(int handle, float *temperature) {
    char buf[2];
    if (i2cReadI2CBlockData(handle, TMP117_TEMP_REG, buf, 2) != 2) {
        return -1;
    }
    int16_t raw = ((int16_t)buf[0] << 8) | (uint8_t)buf[1];
    *temperature = (float)raw * 0.0078125f;
    return 0;
}

static int write_temperature_to_file(FILE *file, float temperature) {
    float temp_f = temperature;
    if (fwrite(&temp_f, sizeof(float), 1, file) != 1) {
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint16_t device_id = 0;
    if (read_device_id(i2c_handle, &device_id) != 0) {
        fprintf(stderr, "Error reading device ID from TMP117\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (device_id != 0x0117) {
        fprintf(stderr, "Unexpected device ID: 0x%04X (expected 0x0117)\n", device_id);
        cleanup();
        return EXIT_FAILURE;
    }

    fp = fopen(DATA_FILE, "ab");
    if (fp == NULL) {
        perror("Error opening data file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Greenhouse temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature = 0.0f;
        if (read_temperature(i2c_handle, &temperature) == 0) {
            if (write_temperature_to_file(fp, temperature) != 0) {
                perror("Error writing temperature to file");
            } else {
                printf("Temperature: %.2f °C\n", temperature);
            }
        } else {
            fprintf(stderr, "Error reading temperature from TMP117\n");
        }

        for (int i = 0; i < SLEEP_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

