#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS        1
#define TMP117_ADDR    0x48
#define TEMP_REG       0x00
#define BUFFER_SIZE    10
#define SAMPLE_PERIOD  5.0
#define LOG_FILE       "temperature_log.dat"
#define ERROR_TEMP     -999.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static float g_buffer[BUFFER_SIZE];
static int   g_buf_idx = 0;
static int   g_buf_count = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: pigpio error %d\n",
                I2C_BUS, TMP117_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static float read_temperature(void)
{
    char buf[2];
    int  result;

    result = i2cReadI2CBlockData(g_i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "I2C read error: expected 2 bytes, got %d (pigpio error %d)\n",
                result, result);
        return ERROR_TEMP;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    float temp = (float)raw * 0.0078125f;
    return temp;
}

static void add_to_buffer(float temp)
{
    g_buffer[g_buf_idx] = temp;
    g_buf_idx = (g_buf_idx + 1) % BUFFER_SIZE;
    if (g_buf_count < BUFFER_SIZE) g_buf_count++;
}

static int write_buffer_to_file(void)
{
    FILE *fp = fopen(LOG_FILE, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    size_t written = fwrite(g_buffer, sizeof(float), g_buf_count, fp);
    if (written != (size_t)g_buf_count) {
        fprintf(stderr, "Error writing buffer to %s: wrote %zu of %d\n",
                LOG_FILE, written, g_buf_count);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TMP117 temperature logger started. Logging to %s every %.1f s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float temp = read_temperature();

        if (temp == ERROR_TEMP) {
            fprintf(stderr, "Skipping sample due to I2C read failure.\n");
        } else {
            add_to_buffer(temp);
            printf("Temperature: %.4f C\n", temp);
        }

        if (write_buffer_to_file() != 0) {
            fprintf(stderr, "Warning: failed to persist buffer to file.\n");
        }

        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Temperature logger stopped.\n");
    return EXIT_SUCCESS;
}

