static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float flow_rate;
    float temperature;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int initialize_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    char buffer[4];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }

    uint16_t raw_flow = ((uint16_t)(uint8_t)buffer[0] << 8) | (uint8_t)buffer[1];
    uint16_t raw_temp = ((uint16_t)(uint8_t)buffer[2] << 8) | (uint8_t)buffer[3];

    data->flow_rate = ((float)raw_flow / 16384.0f) - 0.1f) / 0.8f * 25.0f;
    data->temperature = ((float)raw_temp / 4096.0f) - 0.1f) / 0.8f * 80.0f - 40.0f;

    return 0;
}

static void log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Flow: %.2f SLPM, Temperature: %.2f C\n",
            timestamp, data->flow_rate, data->temperature);
    fflush(log_file);
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    if (initialize_i2c() != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    sensor_data_t sensor_data;
    int consecutive_errors = 0;

    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(&sensor_data);
            consecutive_errors = 0;
        } else {
            log_error("Failed to read sensor data");
            if (initialize_i2c() != 0) {
                log_error("Failed to re-initialize I2C");
                consecutive_errors++;
                if (consecutive_errors >= 3) {
                    log_error("Too many consecutive I2C initialization failures, exiting");
                    break;
                }
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

