/*
 * DHT11 single-wire temperature/humidity sensor reader for Raspberry Pi Zero W
 * Uses pigpio for microsecond-accurate bit-banging.
 *
 * Wiring:
 *   DHT11 VCC  -> 3.3 V (pin 1)
 *   DHT11 DATA -> GPIO 4 (pin 7, BCM 4)
 *   DHT11 GND  -> GND   (pin 6)
 *
 * Build:  gcc -O2 -Wall -o dht11 dht11.c -lpigpio -lrt
 * Run:    sudo ./dht11
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT11_GPIO          4
#define READ_INTERVAL_SEC   2
#define MAX_RETRIES         5
#define LOG_FILE            "dht11_readings.txt"
#define ERROR_LOG_FILE      "dht11_errors.log"

/* DHT11 timing constants (microseconds) */
#define START_LOW_US        18000   /* >18 ms low to start */
#define START_HIGH_US       30      /* 20-40 us high to release */
#define RESP_LOW_US         80      /* Sensor response low  */
#define RESP_HIGH_US        80      /* Sensor response high */
#define BIT_LOW_US          50      /* Each bit low start    */
#define BIT_HIGH_US_0       26      /* '0' bit high (26-28 us) */
#define BIT_HIGH_US_1       70      /* '1' bit high (70 us)   */
#define BIT_THRESHOLD       45      /* (70-26)/2 + 26        */
#define TIMEOUT_US          200     /* Per-phase timeout      */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped entry to the error log.                         */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg, int status)
{
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("fopen(error_log)");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s - [%s] status=%d\n", ts, msg, status);
    } else {
        fprintf(fp, "(unknown time) - [%s] status=%d\n", msg, status);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Write a timestamped reading to the data log.                        */
/* ------------------------------------------------------------------ */
static void log_reading(float temp, float hum)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(data_log)");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s, Temperature: %.1f C, Humidity: %.1f %%\n",
                ts, temp, hum);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Wait for the line to reach the requested level within TIMEOUT_US.    */
/* Returns 0 on success, -1 on timeout.                                */
/* ------------------------------------------------------------------ */
static int wait_level(int gpio, int level, uint32_t timeout_us)
{
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if ((gpioTick() - start) > timeout_us)
            return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 40 bits from the DHT11 and return humidity (byte 0) and         */
/* temperature (byte 2).  Returns 0 on success, -1 on error.            */
/* ------------------------------------------------------------------ */
static int read_dht11(uint8_t *data)
{
    uint8_t bits[5] = {0, 0, 0, 0, 0};

    /* ---- Start signal: pull low >18 ms, then high 20-40 us ---- */
    if (gpioSetMode(DHT11_GPIO, PI_OUTPUT) < 0)
        return -1;
    if (gpioWrite(DHT11_GPIO, 0) < 0)
        return -1;
    gpioDelay(START_LOW_US);
    if (gpioWrite(DHT11_GPIO, 1) < 0)
        return -1;
    gpioDelay(START_HIGH_US);

    /* ---- Switch to input and wait for sensor response (low then high) ---- */
    if (gpioSetMode(DHT11_GPIO, PI_INPUT) < 0)
        return -1;

    if (wait_level(DHT11_GPIO, 0, TIMEOUT_US) < 0) {
        log_error("Sensor response low timeout", -1);
        return -1;
    }
    if (wait_level(DHT11_GPIO, 1, TIMEOUT_US) < 0) {
        log_error("Sensor response high timeout", -1);
        return -1;
    }

    /* ---- Read 40 data bits ---- */
    for (int i = 0; i < 40; i++) {
        /* Low preamble (~50 us) */
        if (wait_level(DHT11_GPIO, 0, TIMEOUT_US) < 0) {
            log_error("Bit low timeout", i);
            return -1;
        }
        /* High pulse: ~26-28 us = '0', ~70 us = '1' */
        if (wait_level(DHT11_GPIO, 1, TIMEOUT_US) < 0) {
            log_error("Bit high timeout", i);
            return -1;
        }
        uint32_t high_us = gpioTick() - (uint32_t)(start + BIT_LOW_US);
        int bit = (high_us > BIT_THRESHOLD) ? 1 : 0;
        bits[i / 8] = (bits[i / 8] << 1) | bit;
    }

    /* ---- Checksum ---- */
    uint8_t checksum = (uint8_t)(bits[0] + bits[1] + bits[2] + bits[3]);
    if (checksum != bits[4]) {
        log_error("Checksum mismatch", -2);
        return -1;
    }

    memcpy(data, bits, 5);
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int rc = EXIT_SUCCESS;

    /* ---- Main loop ---- */
    while (g_running) {
        uint8_t data[5];
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_dht11(data) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(200000); /* 200 ms between retries */
        }

        if (ok) {
            /* DHT11: humidity = data[0], temperature = data[2] */
            float temp = (float)data[2];
            float hum  = (float)data[0];
            log_reading(temp, hum);
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temp, hum);
        } else {
            log_error("DHT11 read failed after retries", -3);
            fprintf(stderr, "DHT11 read failed after %d retries\n", MAX_RETRIES);
        }

        /* Sleep READ_INTERVAL_SEC, but wake early on signal */
        for (int s = 0; s < READ_INTERVAL_SEC && g_running; s++)
            sleep(1);
    }

    /* ---- Cleanup ---- */
    gpioSetMode(DHT11_GPIO, PI_INPUT);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return rc;
}

