        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sht31d(float *temperature, float *humidity) {
    uint8_t cmd[2] = {MEASURE_CMD_MSB, MEASURE_CMD_LSB};
    uint8_t buf[6];

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
            fprintf(stderr, "I2C write failed (attempt %d)\n", attempt + 1);
            gpioDelay(100000);
            continue;
        }

        gpioDelay(15000);

        if (i2cReadDevice(i2c_handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d)\n", attempt + 1);
            gpioDelay(100000);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "Temperature CRC mismatch (attempt %d)\n", attempt + 1);
            gpioDelay(100000);
            continue;
        }

        if (crc8(buf + 3, 2) != buf[5]) {
            fprintf(stderr, "Humidity CRC mismatch (attempt %d)\n", attempt + 1);
            gpioDelay(100000);
            continue;
        }

        uint16_t raw_temp = ((uint16_t)buf[0] << 8) | buf[1];
        uint16_t raw_hum  = ((uint16_t)buf[3] << 8) | buf[4];

        *temperature = -45.0f + 175.0f * (float)raw_temp / 65535.0f;
        *humidity    = 100.0f * (float)raw_hum  / 65535.0f;

        return 0;
    }

    return -1;
}

static void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file);
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,ERROR,%s\n", timestamp, message);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X on bus %d\n", SHT31_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, humidity;

    while (!terminate) {
        if (read_sht31d(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            log_error("Failed to read SHT31-D sensor after retries");
        }

        for (int i = 0; i < READ_INTERVAL_SEC && !terminate; i++) {
            sleep(1);
        }
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();

    return 0;
}

