    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_channel_data(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading block from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint16_t)((uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    return 0;
}

static float calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    if (red == 0 || green == 0 || blue == 0) {
        return 0.0f;
    }
    float r = (float)red;
    float g = (float)green;
    float b = (float)blue;
    float n = (r + g + b) / 3.0f;
    float n_r = r / n;
    float n_g = g / n;
    float n_b = b / n;
    float x = (n_r + n_g) / (n_r + n_g + n_b);
    float cct = 449.0f * (x - 0.334f) / (0.224f - x);
