        cleanup();
        return 1;
    }

    if (device_id_1 != EXPECTED_DEVICE_ID || device_id_2 != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Device ID mismatch: sensor1=0x%02X, sensor2=0x%02X (expected 0x%02X)\n",
                device_id_1, device_id_2, EXPECTED_DEVICE_ID);
        cleanup();
        return 1;
    }

    log_file = fopen("cct_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
        fflush(log_file);
    }

    while (running) {
