            read_channel_data(i2c_handle_1, REG_BLUE_DATA, &blue_1) != 0) {
            fprintf(stderr, "Error reading data from sensor 1\n");
        } else if (read_channel_data(i2c_handle_2, REG_RED_DATA, &red_2) != 0 ||
                   read_channel_data(i2c_handle_2, REG_GREEN_DATA, &green_2) != 0 ||
