#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define MLX90824_ADDR 0x60
#define RAW_PRESSURE_REG 0x0A2C
#define RAW_TEMPERATURE_REG 0x0A2E
#define OUTPUT_MIN 0
#define OUTPUT_MAX 32768
#define P_MIN_KPA 0.0
#define P_MAX_KPA 800.0
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 2000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register16(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int read_pressure_kpa(int handle, double *pressure_kpa) {
    uint16_t raw;
    if (read_register16(handle, RAW_PRESSURE_REG, &raw) != 0) {
        return -1;
    }
    *pressure_kpa = ((double)raw - OUTPUT_MIN) * (P_MAX_KPA - P_MIN_KPA) / (OUTPUT_MAX - OUTPUT_MIN);
    return 0;
}

static int read_temperature_c(int handle, double *temperature_c) {
    uint16_t raw;
    if (read_register16(handle, RAW_TEMPERATURE_REG, &raw) != 0) {
        return -1;
    }
    *temperature_c = (double)raw * 0.01 - 40.0;
    return 0;
}

static void log_data(FILE *fp, double pressure_kpa, double temperature_c) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, Pressure: %.2f kPa, Temperature: %.2f C\n", timestamp, pressure_kpa, temperature_c);
    fflush(fp);
}

static void log_error(FILE *fp, const char *msg) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, ERROR: %s\n", timestamp, msg);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d, addr 0x%02X: %s\n", I2C_BUS, MLX90824_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Tire Pressure Monitoring System started. Logging to %s every 2 seconds.\n", LOG_FILE);

    while (!terminate) {
        double pressure_kpa, temperature_c;
        int pressure_ok = read_pressure_kpa(i2c_handle, &pressure_kpa);
        int temp_ok = read_temperature_c(i2c_handle, &temperature_c);

        if (pressure_ok == 0 && temp_ok == 0) {
            log_data(log_file, pressure_kpa, temperature_c);
        } else {
            if (pressure_ok != 0) {
                log_error(log_file, "Failed to read pressure register");
            }
            if (temp_ok != 0) {
                log_error(log_file, "Failed to read temperature register");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

