#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define LM75B_ADDR     0x48
#define TEMP_REG       0x00
#define FAN_GPIO       18
#define BUFFER_SIZE    60
#define SAMPLE_PERIOD  1.0
#define TEMP_THRESHOLD_ON  28.0
#define TEMP_THRESHOLD_OFF 26.0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Read temperature from LM75B. Returns 0 on success, -1 on error. */
static int read_temperature(int handle, float *temp_out) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, TEMP_REG, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): rc=%d\n", TEMP_REG, rc);
        return -1;
    }

    /* LM75B: 9-bit signed, 0.5 °C resolution. D9-D1 hold the value, D0 is always 0. */
    int16_t raw = (int16_t)((uint16_t)buf[0] << 8 | (uint16_t)buf[1]);
    raw >>= 5;                       /* arithmetic shift keeps sign */
    *temp_out = (float)raw * 0.5f;
    return 0;
}

static void control_fan(float avg_temp) {
    static int fan_on = 0;
    if (avg_temp > TEMP_THRESHOLD_ON && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON  (avg %.2f °C)\n", avg_temp);
        } else {
            fprintf(stderr, "Failed to set fan GPIO %d high\n", FAN_GPIO);
        }
    } else if (avg_temp < TEMP_THRESHOLD_OFF && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (avg %.2f °C)\n", avg_temp);
        } else {
            fprintf(stderr, "Failed to set fan GPIO %d low\n", FAN_GPIO);
        }
    }
}

int main(void) {
    float buffer[BUFFER_SIZE];
    int   idx = 0;
    int   count = 0;
    float sum = 0.0f;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, LM75B_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", FAN_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    printf("LM75B fan controller started (bus %d, addr 0x%02X, fan GPIO %d)\n",
           I2C_BUS, LM75B_ADDR, FAN_GPIO);

    while (g_running) {
        float temp;
        if (read_temperature(g_i2c_handle, &temp) != 0) {
            fprintf(stderr, "Temperature read failed; retrying next cycle\n");
        } else {
            buffer[idx] = temp;
            idx = (idx + 1) % BUFFER_SIZE;
            if (count < BUFFER_SIZE) count++;
            sum = 0.0f;
            for (int i = 0; i < count; i++) sum += buffer[i];
            float avg = (count > 0) ? (sum / (float)count) : 0.0f;
            printf("Temp: %.2f °C | Avg: %.2f °C | Fan: %s\n",
                   temp, avg, (count > 0 && avg > TEMP_THRESHOLD_ON) ? "ON" : "OFF");
            control_fan(avg);
        }
        time_sleep(SAMPLE_PERIOD);
    }

    /* Graceful shutdown */
    gpioWrite(FAN_GPIO, 0);
    if (g_i2c_handle >= 0) i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

