#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define STTS2004_ADDR  0x4A
#define TEMP_REG       0x00
#define LED_PIN        17
#define TEMP_HIGH      28.0f
#define TEMP_LOW       27.0f
#define POLL_INTERVAL  1
#define MAX_CONSEC_ERR 5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void)
{
    int i2c_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    int led_state = 0;
    int consecutive_errors = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                STTS2004_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "stts2004_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n",
                LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("STTS2004 temperature monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t raw;
        if (i2c_read_reg16(i2c_fd, TEMP_REG, &raw) == 0) {
            consecutive_errors = 0;
            int16_t temp_raw = (int16_t)raw;
            float temperature = (float)temp_raw / 16.0f;
            printf("Temperature: %.2f °C\n", temperature);

            if (temperature > TEMP_HIGH && led_state == 0) {
                if (gpiod_line_set_value(led_line, 1) < 0) {
                    fprintf(stderr, "Failed to set LED high: %s\n",
                            strerror(errno));
                } else {
                    led_state = 1;
                }
            } else if (temperature < TEMP_LOW && led_state == 1) {
                if (gpiod_line_set_value(led_line, 0) < 0) {
                    fprintf(stderr, "Failed to set LED low: %s\n",
                            strerror(errno));
                } else {
                    led_state = 0;
                }
            }
        } else {
            consecutive_errors++;
            if (consecutive_errors >= MAX_CONSEC_ERR) {
                fprintf(stderr, "Too many consecutive I2C errors (%d). Exiting.\n",
                        consecutive_errors);
                break;
            }
        }

        sleep(POLL_INTERVAL);
    }

    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

