#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASUREMENT_CMD 0x362F
#define MEASUREMENT_DELAY_US 45000
#define LOG_FILE "flow_data.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int initialize_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", SDP800_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    uint8_t cmd[2] = { (MEASUREMENT_CMD >> 8) & 0xFF, MEASUREMENT_CMD & 0xFF };
    uint8_t buffer[9];

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error writing measurement command to I2C device\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    if (i2cReadDevice(i2c_handle, (char *)buffer, 9) != 9) {
        fprintf(stderr, "Error reading 9 bytes from I2C device\n");
        return -1;
    }

    if (crc8(buffer, 2) != buffer[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t raw_temperature = (int16_t)((buffer[3] << 8) | buffer[4]);
    int16_t scale_factor = (int16_t)((buffer[6] << 8) | buffer[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor (0) from sensor\n");
        return -1;
    }

    data->differential_pressure = (float)raw_pressure / (float)scale_factor;
    data->temperature = (float)raw_temperature / 200.0f;

    return 0;
}

static int log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
            return -1;
        }
    }

    fprintf(log_file, "%s, %.2f Pa, %.2f C\n", timestamp, data->differential_pressure, data->temperature);
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (initialize_i2c() != 0) {
        return EXIT_FAILURE;
    }

    sensor_data_t sensor_data;

    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            if (log_data(&sensor_data) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(100000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

