#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define MEASURE_RH_NO_HOLD 0xF5
#define MEASURE_TEMP_NO_HOLD 0xF3
#define READ_TEMP_PREV_RH 0xE0
#define MEASURE_DELAY_US 25000
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL_S 60
#define LOG_FILE "environment.log"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_id(int handle, uint8_t *id) {
    if (i2cWriteByte(handle, 0xFA) < 0) return -1;
    gpioDelay(1000);
    char buf[8];
    int n = i2cReadDevice(handle, buf, 8);
    if (n != 8) return -1;
    memcpy(id, buf, 8);
    return 0;
}

static int read_raw_humidity(int handle, uint16_t *raw) {
    if (i2cWriteByte(handle, MEASURE_RH_NO_HOLD) < 0) return -1;
    gpioDelay(MEASURE_DELAY_US);
    char buf[2];
    int n = i2cReadDevice(handle, buf, 2);
    if (n != 2) return -1;
    *raw = ((uint16_t)(buf[0] << 8)) | (uint8_t)buf[1];
    return 0;
}

static int read_raw_temperature(int handle, uint16_t *raw) {
    if (i2cWriteByte(handle, READ_TEMP_PREV_RH) < 0) return -1;
    gpioDelay(MEASURE_DELAY_US);
    char buf[2];
    int n = i2cReadDevice(handle, buf, 2);
    if (n != 2) return -1;
    *raw = ((uint16_t)(buf[0] << 8)) | (uint8_t)buf[1];
    return 0;
}

static float convert_temperature(uint16_t raw) {
    return (175.72f * (float)raw / 65536.0f) - 46.85f;
}

static float convert_humidity(uint16_t raw) {
    float h = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (h < 0.0f) h = 0.0f;
    if (h > 100.0f) h = 100.0f;
    return h;
}

static void log_data(float temp, float hum) {
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    fprintf(stdout, "%s,%.2f,%.2f\n", ts, temp, hum);
    fflush(stdout);
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, hum);
        fflush(fp);
        fclose(fp);
    } else {
        fprintf(stderr, "Error: cannot open %s for append\n", LOG_FILE);
    }
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    fprintf(stderr, "%s ERROR: %s\n", ts, msg);
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s ERROR: %s\n", ts, msg);
        fflush(fp);
        fclose(fp);
    }
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (%d)\n", i2c_handle);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
