           sensor_id[0], sensor_id[1], sensor_id[2], sensor_id[3],
           sensor_id[4], sensor_id[5], sensor_id[6], sensor_id[7]);

    while (running) {
        uint16_t raw_h = 0, raw_t = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_raw_humidity(i2c_handle, &raw_h) == 0) {
