#define CONFIG_REG 0x02
#define I2C_BUS 1
#define LOG_FILE "enviro_log.txt"
#define MEASUREMENT_DELAY_US 20000
#define LOOP_DELAY_US 5000000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_hdc1080(int handle) {
    /*
     * Configuration register (0x02):
     *   Bit 7-6: Temperature resolution (10 = 14-bit)
     *   Bit 5-4: Humidity resolution (10 = 14-bit)
     *   Bit 3: Heater enable (0 = off)
     *   Bit 2: Mode (0 = continuous)
     *   Bit 1-0: Reserved (00)
     * Value = 0x40
     */
    if (i2cWriteByteData(handle, CONFIG_REG, 0x40) < 0) {
        fprintf(stderr, "Error: Failed to write HDC1080 configuration register.\n");
        return -1;
    }
    return 0;
}

static int read_hdc1080(int handle, float *temperature, float *humidity) {
    char buf[4];
    int result;

    /* Write pointer to temperature register (0x00) to trigger a read */
    result = i2cWriteByte(handle, TEMP_REG);
    if (result < 0) {
        fprintf(stderr, "Error: Failed to write temperature pointer (pigpio error %d).\n", result);
        return -1;
    }

    /* Wait for conversion: 14-bit temp + 14-bit humidity takes ~12.5 ms max */
    gpioDelay(MEASUREMENT_DELAY_US);

    /* Read 4 bytes: 2 bytes temperature, 2 bytes humidity */
    result = i2cReadDevice(handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error: Failed to read 4 bytes from HDC1080 (read %d bytes, pigpio error %d).\n", result, result);
        return -1;
    }

    uint16_t raw_temp = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    uint16_t raw_humidity = ((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3];

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity = ((float)raw_humidity / 65536.0f) * 100.0f;

    return 0;
}

static int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void) {
    float temperature, humidity;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (pigpio error %d).\n", I2C_BUS, HDC1080_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
