    if (init_hdc1080(i2c_handle) < 0) {
        fprintf(stderr, "Error: HDC1080 initialization failed. Check sensor wiring and I2C address.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

