    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HDC1080 logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        if (read_hdc1080(i2c_handle, &temperature, &humidity) == 0) {
            if (log_data(temperature, humidity) == 0) {
                printf("Logged: %.2f C, %.2f %%\n", temperature, humidity);
            } else {
                fprintf(stderr, "Warning: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Warning: Failed to read sensor data.\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

