#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define STS40_ADDR        0x44
#define I2C_BUS           "/dev/i2c-1"
#define LOG_FILE          "temperature_log.txt"
#define SAMPLE_INTERVAL_S 5
#define CONVERSION_MS     10

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;
static FILE *g_log = NULL;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int init_i2c(void) {
    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(g_fd, I2C_SLAVE, STS40_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                STS40_ADDR, strerror(errno));
        close(g_fd);
        g_fd = -1;
        return -1;
    }
    return 0;
}

static int read_temperature(float *temp_c) {
    uint8_t cmd[2] = {0x2C, 0xE0};
    ssize_t w = write(g_fd, cmd, sizeof(cmd));
    if (w != (ssize_t)sizeof(cmd)) {
        fprintf(stderr, "Error writing measurement command: %s\n",
                w < 0 ? strerror(errno) : "short write");
        return -1;
    }

    usleep(CONVERSION_MS * 1000);

    uint8_t buf[3];
    ssize_t r = read(g_fd, buf, sizeof(buf));
    if (r != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "Error reading temperature data: %s\n",
                r < 0 ? strerror(errno) : "short read");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on temperature data\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp_c = -45.0f + (175.0f * (float)raw / 65535.0f);
    return 0;
}

static void log_temperature(float temp_c) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    if (g_log) {
        fprintf(g_log, "%s, %.2f\n", ts, temp_c);
        fflush(g_log);
    } else {
        fprintf(stderr, "Error: log file not open\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_i2c() < 0)
        return 1;

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_fd);
        return 1;
    }

    while (g_running) {
        float temp_c;
        if (read_temperature(&temp_c) == 0) {
            log_temperature(temp_c);
        } else {
            fprintf(stderr, "Temperature read failed; will retry next cycle\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    if (g_fd >= 0) {
        close(g_fd);
        g_fd = -1;
    }
    return 0;
}

