    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    if (g_log) {
        fprintf(g_log, "%s, %.2f\n", ts, temp_c);
        fflush(g_log);
    } else {
        fprintf(stderr, "Error: log file not open\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_i2c() < 0)
        return 1;

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_fd);
        return 1;
    }

    while (g_running) {
        float temp_c;
        if (read_temperature(&temp_c) == 0) {
