#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

#define SCD40_ADDR 0x62
#define I2C_BUS 1
#define BUFFER_SIZE 100
#define LOG_FILE "/var/log/scd40_error.log"
#define DATA_DIR "/var/log/scd40_data"
#define READ_INTERVAL_SEC 5
#define LOG_INTERVAL_SEC 60

#define CMD_START_PERIODIC 0x21B1
#define CMD_READ_MEASUREMENT 0xE000
#define CMD_STOP_PERIODIC 0x3F86

typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;
static circular_buffer_t data_buffer;
static pthread_t logging_thread;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static void log_error(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s (errno: %s)\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message, strerror(errno));
    fclose(fp);
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int send_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int result = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (result != 0) {
        log_error("Failed to send command");
        return -1;
    }
    return 0;
}

static int read_measurement(float *co2, float *temperature, float *humidity) {
    if (send_command(CMD_READ_MEASUREMENT) != 0) return -1;
    gpioDelay(20000);
    uint8_t buf[9];
    int result = i2cReadDevice(i2c_handle, (char *)buf, 9);
    if (result != 9) {
        log_error("Failed to read measurement data");
        return -1;
    }
    if (crc8(&buf[0], 2) != buf[2]) {
        log_error("CO2 CRC mismatch");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        log_error("Temperature CRC mismatch");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        log_error("Humidity CRC mismatch");
        return -1;
    }
    uint16_t co2_raw = (buf[0] << 8) | buf[1];
    uint16_t temp_raw = (buf[3] << 8) | buf[4];
    uint16_t hum_raw = (buf[6] << 8) | buf[7];
    *co2 = (float)co2_raw;
    *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *humidity = 100.0f * (float)hum_raw / 65535.0f;
    return 0;
}

static void init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
}

static void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    else buffer->count++;
    pthread_mutex_unlock(&buffer->mutex);
}

static void *logging_thread_func(void *arg) {
    (void)arg;
    while (running) {
        sleep(LOG_INTERVAL_SEC);
        if (!running) break;
        pthread_mutex_lock(&data_buffer.mutex);
        int count = data_buffer.count;
        int head = data_buffer.head;
        int tail = data_buffer.tail;
        pthread_mutex_unlock(&data_buffer.mutex);
        if (count > 0) {
            char filename[256];
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            snprintf(filename, sizeof(filename), "%s/scd40_data_%d%02d%02d_%02d%02d%02d.csv",
                     DATA_DIR, tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                     tm.tm_hour, tm.tm_min, tm.tm_sec);
            int dir_exists = (access(DATA_DIR, F_OK) == 0);
            if (!dir_exists) {
                if (mkdir(DATA_DIR, 0755) != 0) {
                    log_error("Failed to create data directory");
                    return NULL;
                }
            }
            FILE *fp = fopen(filename, "w");
            if (!fp) {
                log_error("Failed to open CSV file for writing");
                return NULL;
            }
            fprintf(fp, "Timestamp,CO2,Temperature,Humidity\n");
            int idx = tail;
            for (int i = 0; i < count; i++) {
                sensor_data_t d;
                pthread_mutex_lock(&data_buffer.mutex);
                d = data_buffer.data[idx];
                idx = (idx + 1) % BUFFER_SIZE;
                pthread_mutex_unlock(&data_buffer.mutex);
                fprintf(fp, "%ld,%.2f,%.2f,%.2f\n", (long)d.timestamp, d.co2, d.temperature, d.humidity);
            }
            fclose(fp);
            pthread_mutex_lock(&data_buffer.mutex);
            data_buffer.head = 0;
            data_buffer.tail = 0;
            data_buffer.count = 0;
            pthread_mutex_unlock(&data_buffer.mutex);
        }
    }
    return NULL;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        send_command(CMD_STOP_PERIODIC);
        gpioDelay(100000);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    pthread_mutex_destroy(&data_buffer.mutex);
    pthread_join(logging_thread, NULL);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (init_i2c() != 0) return 1;
    if (send_command(CMD_START_PERIODIC) != 0) {
        log_error("Failed to start periodic measurement");
        cleanup();
        return 1;
    }
    gpioDelay(1000000);
    init_circular_buffer(&data_buffer);
    if (pthread_create(&logging_thread, NULL, logging_thread_func, NULL) != 0) {
        log_error("Failed to create logging thread");
        cleanup();
        return 1;
    }
    while (running) {
        float co2, temperature, humidity;
        if (read_measurement(&co2, &temperature, &humidity) == 0) {
            sensor_data_t data = { .timestamp = time(NULL), .co2 = co2, .temperature = temperature, .humidity = humidity };
            add_to_buffer(&data_buffer, data);
        }
        sleep(READ_INTERVAL_SEC);
    }
    cleanup();
    return 0;
}

