#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define ICP10110_ADDR 0x63
#define WHO_AM_I_REG 0x08
#define WHO_AM_I_VAL 0x08
#define CALIB_REG 0x05
#define MEASURE_REG 0x00
#define MEASURE_CMD 0x00
#define MEASURE_DELAY_US 10000
#define SAMPLE_INTERVAL_S 5
#define LOG_FILE "environmental_data.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

typedef struct {
    float c0;
    float c1;
    float c00;
    float c10;
    float c01;
    float c11;
} icp10110_calib_t;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_calibration(int handle, icp10110_calib_t *cal) {
    char buf[8];
    if (i2cReadI2CBlockData(handle, CALIB_REG, buf, 8) != 8) {
        fprintf(stderr, "Error: Failed to read calibration coefficients\n");
        return -1;
    }
    uint16_t c0_raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    uint16_t c1_raw = ((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3];
    uint16_t c00_raw = ((uint16_t)(uint8_t)buf[4] << 8) | (uint8_t)buf[5];
    uint16_t c10_raw = ((uint16_t)(uint8_t)buf[6] << 8) | (uint8_t)buf[7];
    cal->c0 = (float)c0_raw;
    cal->c1 = (float)c1_raw;
    cal->c00 = (float)c00_raw;
    cal->c10 = (float)c10_raw;
    cal->c01 = 0.0f;
    cal->c11 = 0.0f;
    return 0;
}

static int read_sensor_data(int handle, const icp10110_calib_t *cal, float *pressure, float *temperature) {
    char cmd = MEASURE_CMD;
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to trigger measurement\n");
        return -1;
    }
    gpioDelay(MEASURE_DELAY_US);
    char buf[6];
    if (i2cReadI2CBlockData(handle, MEASURE_REG, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read sensor data\n");
        return -1;
    }
    uint32_t p_raw = ((uint32_t)(uint8_t)buf[0] << 16) | ((uint32_t)(uint8_t)buf[1] << 8) | (uint8_t)buf[2];
    uint32_t t_raw = ((uint32_t)(uint8_t)buf[3] << 16) | ((uint32_t)(uint8_t)buf[4] << 8) | (uint8_t)buf[5];
    float p_comp = cal->c0 + cal->c1 * (float)p_raw + cal->c00 * (float)t_raw + cal->c10 * (float)p_raw * (float)t_raw;
    float t_comp = cal->c0 + cal->c1 * (float)t_raw + cal->c00 * (float)p_raw + cal->c10 * (float)p_raw * (float)t_raw;
    *pressure = p_comp / 100.0f;
    *temperature = t_comp / 100.0f;
    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(fp);
    printf("%s,%.2f,%.2f\n", timestamp, pressure, temperature);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, ICP10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", ICP10110_ADDR);
        gpioTerminate();
        return 1;
    }
    int who = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n", who, WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    icp10110_calib_t cal;
    if (read_calibration(i2c_handle, &cal) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    while (program_running) {
        float pressure, temperature;
        if (read_sensor_data(i2c_handle, &cal, &pressure, &temperature) == 0) {
            log_data(log_file, pressure, temperature);
        }
        for (int i = 0; i < SAMPLE_INTERVAL_S && program_running; i++) {
            sleep(1);
        }
    }
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

