#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x63
#define LED_CHIP       "gpiochip4"
#define LED_LINE       17
#define OTP_REG        0x66
#define CMD_MEASURE    0x4011
#define MEASURE_DELAY_MS 20
#define POLL_DELAY_MS  1000
#define CRC_POLY       0x31
#define CRC_INIT       0xFFFF

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC_POLY;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_otp(int fd, uint16_t *c0, uint16_t *c1, uint16_t *c2, uint16_t *c3) {
    if (i2c_write_cmd(fd, OTP_REG) < 0) return -1;
    usleep(1000);
    uint8_t buf[8];
    if (i2c_read_data(fd, buf, 8) < 0) return -1;
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "OTP CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "OTP CRC mismatch\n");
        return -1;
    }
    *c0 = (buf[0] << 8) | buf[1];
    *c1 = (buf[3] << 8) | buf[4];
    *c2 = (buf[6] << 8) | buf[7];
    *c3 = 0;
    return 0;
}

static int read_sensor(int fd, uint16_t c0, uint16_t c1, uint16_t c2,
                       float *pressure, float *temperature) {
    if (i2c_write_cmd(fd, CMD_MEASURE) < 0) return -1;
    usleep(MEASURE_DELAY_MS * 1000);
    uint8_t buf[6];
    if (i2c_read_data(fd, buf, 6) < 0) return -1;
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    uint32_t raw_p = ((uint32_t)buf[0] << 8) | buf[1];
    uint32_t raw_t = ((uint32_t)buf[3] << 8) | buf[4];
    float t = (float)raw_t / 65536.0f;
    float p = (float)raw_p / 65536.0f;
    float p_comp = c0 + c1 * p + c2 * t;
    *pressure = p_comp * 100.0f;
    *temperature = t * 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa = { .sa_handler = sigint_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(LED_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", LED_CHIP, strerror(errno));
        close(fd);
        return 1;
    }
    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_LINE);
    if (!led) {
        fprintf(stderr, "Cannot get line %d: %s\n", LED_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }
    if (gpiod_line_request_output(led, "icp10125_led", 0) < 0) {
        fprintf(stderr, "Cannot request LED line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    uint16_t c0, c1, c2, c3;
    if (read_otp(fd, &c0, &c1, &c2, &c3) < 0) {
        fprintf(stderr, "Failed to read OTP coefficients\n");
        gpiod_line_release(led);
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    printf("ICP-10125 initialized. Reading pressure every %d ms.\n", POLL_DELAY_MS);

    while (running) {
        float pressure, temperature;
        if (read_sensor(fd, c0, c1, c2, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
            if (pressure < 95000.0f) {
                printf("WARNING: High altitude detected!\n");
                for (int i = 0; i < 5 && running; i++) {
                    gpiod_line_set_value(led, 1);
                    usleep(100000);
                    gpiod_line_set_value(led, 0);
                    usleep(100000);
                }
            } else {
                for (int i = 0; i < 2 && running; i++) {
                    gpiod_line_set_value(led, 1);
                    usleep(500000);
                    gpiod_line_set_value(led, 0);
                    usleep(500000);
                }
            }
        } else {
            fprintf(stderr, "Sensor read error, retrying...\n");
        }
        usleep(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(fd);
    return 0;
}

