#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define FAN_GPIO 18
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define TEMP_SCALE 0.02
#define TEMP_OFFSET 273.15
#define FAN_ON_TEMP 30.0
#define FAN_OFF_TEMP 28.0
#define LOG_FILE "temperature_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000
#define POLL_INTERVAL_US 2000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, uint8_t reg, float *temp) {
    int raw = -1;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        raw = i2cReadWordData(handle, reg);
        if (raw >= 0) break;
        fprintf(stderr, "I2C read attempt %d failed (reg 0x%02X), retrying...\n", attempt + 1, reg);
        gpioDelay(RETRY_DELAY_US);
    }
    if (raw < 0) {
        fprintf(stderr, "Failed to read register 0x%02X after %d attempts.\n", reg, MAX_RETRIES);
        return -1;
    }
    uint16_t raw_u = (uint16_t)raw;
    *temp = (float)raw_u * TEMP_SCALE - TEMP_OFFSET;
    return 0;
}

static int log_temperature(float ambient, float object) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, Ambient: %.2f C, Object: %.2f C\n", ts, ambient, object);
    } else {
        fprintf(fp, "(time error), Ambient: %.2f C, Object: %.2f C\n", ambient, object);
    }
    fclose(fp);
    return 0;
}

static void control_fan(float object_temp) {
    static int fan_on = 0;
    if (object_temp > FAN_ON_TEMP && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON (Object: %.2f C)\n", object_temp);
        } else {
            fprintf(stderr, "Failed to turn fan ON.\n");
        }
    } else if (object_temp < FAN_OFF_TEMP && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (Object: %.2f C)\n", object_temp);
        } else {
            fprintf(stderr, "Failed to turn fan OFF.\n");
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X.\n", I2C_BUS, MLX90614_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output.\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX90614 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float ambient = 0.0f, object = 0.0f;
        int amb_ok = read_temperature(i2c_handle, AMBIENT_TEMP_REG, &ambient);
        int obj_ok = read_temperature(i2c_handle, OBJECT_TEMP_REG, &object);

        if (amb_ok == 0 && obj_ok == 0) {
            printf("Ambient: %.2f C, Object: %.2f C\n", ambient, object);
            if (log_temperature(ambient, object) != 0) {
                fprintf(stderr, "Logging failed.\n");
            }
            control_fan(object);
        } else {
            fprintf(stderr, "Sensor read error (ambient=%s, object=%s).\n",
                    amb_ok ? "OK" : "FAIL", obj_ok ? "OK" : "FAIL");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

