#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define HTTP_PORT 8080
#define MAX_RETRIES 3
#define MEASUREMENT_DELAY_US 10000
#define READ_DELAY_US 5000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int server_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_sht40(int handle, float *temperature, float *humidity) {
    unsigned char cmd = 0xFD;
    unsigned char buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
            fprintf(stderr, "Error writing measurement command (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(READ_DELAY_US);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "Error reading sensor data (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(READ_DELAY_US);
            continue;
        }

        unsigned int raw_temperature = ((unsigned int)buf[0] << 8) | buf[1];
        unsigned int raw_humidity = ((unsigned int)buf[3] << 8) | buf[4];

        *temperature = -45.0f + 175.0f * (float)raw_temperature / 65535.0f;
        *humidity = -6.0f + 125.0f * (float)raw_humidity / 65535.0f;

        if (*humidity < 0.0f) *humidity = 0.0f;
        if (*humidity > 100.0f) *humidity = 100.0f;

        return 0;
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries.\n", MAX_RETRIES);
    return -1;
}

void handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received;
    float temperature, humidity;

    while ((bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        if (strstr(buffer, "GET / HTTP/1.1") != NULL) {
            if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
                char response[512];
                snprintf(response, sizeof(response),
                         "HTTP/1.1 200 OK\r\n"
                         "Content-Type: text/html\r\n"
                         "Connection: close\r\n"
                         "\r\n"
                         "<!DOCTYPE html>\n"
                         "<html><head><title>SHT40 Data</title></head>\n"
                         "<body><h1>SHT40 Sensor Data</h1>\n"
                         "<p>Temperature: %.2f °C</p>\n"
                         "<p>Humidity: %.2f %%</p>\n"
                         "</body></html>\n",
                         temperature, humidity);
                send(client_socket, response, strlen(response), 0);
            } else {
                const char *error_response = "HTTP/1.1 500 Internal Server Error\r\n"
                                             "Content-Type: text/html\r\n"
                                             "Connection: close\r\n"
                                             "\r\n"
                                             "<!DOCTYPE html>\n"
                                             "<html><head><title>Error</title></head>\n"
                                             "<body><h1>Error: Failed to read sensor data</h1></body></html>\n";
                send(client_socket, error_response, strlen(error_response), 0);
            }
            break;
        } else {
            const char *not_found_response = "HTTP/1.1 404 Not Found\r\n"
                                             "Content-Type: text/html\r\n"
                                             "Connection: close\r\n"
                                             "\r\n"
                                             "<!DOCTYPE html>\n"
                                             "<html><head><title>Not Found</title></head>\n"
                                             "<body><h1>Not Found</h1></body></html>\n";
            send(client_socket, not_found_response, strlen(not_found_response), 0);
            break;
        }
    }

    if (bytes_received == 0) {
        fprintf(stderr, "Client disconnected.\n");
    } else if (bytes_received == -1) {
        fprintf(stderr, "recv failed: %s\n", strerror(errno));
    }

    close(client_socket);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %s\n", SHT40_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        fprintf(stderr, "Socket creation failed: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        fprintf(stderr, "setsockopt failed: %s\n", strerror(errno));
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sockaddr_in server_address;
    memset(&server_address, 0, sizeof(server_address));
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(HTTP_PORT);

    if (bind(server_fd, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        fprintf(stderr, "Bind failed: %s\n", strerror(errno));
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        fprintf(stderr, "Listen failed: %s\n", strerror(errno));
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d...\n", HTTP_PORT);

    while (running) {
        struct sockaddr_in client_address;
        socklen_t client_address_len = sizeof(client_address);
        int client_socket = accept(server_fd, (struct sockaddr *)&client_address, &client_address_len);

        if (client_socket < 0) {
            if (errno == EINTR && !running) break;
            fprintf(stderr, "Accept failed: %s\n", strerror(errno));
            continue;
        }

        handle_client(client_socket);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (server_fd >= 0) close(server_fd);
    gpioTerminate();

    return 0;
}

