#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HDC2010_ADDR        0x40
#define REG_TEMP_LOW        0x00
#define REG_TEMP_HIGH       0x01
#define REG_HUM_LOW         0x02
#define REG_HUM_HIGH        0x03
#define REG_MEAS_CONFIG     0x0E
#define REG_CONFIG          0x0F
#define MEAS_TRIGGER        0x01
#define CONFIG_HEATER_OFF   0x00
#define CONFIG_14BIT        0x00
#define MEAS_TIMEOUT_US     500000
#define POLL_INTERVAL_US    1000
#define MAX_RETRIES         3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int write_reg(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(g_i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n", reg, val, rc);
        return -1;
    }
    return 0;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int read_temp_humidity(float *temperature, float *humidity) {
    uint8_t meas_config;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (write_reg(REG_MEAS_CONFIG, MEAS_TRIGGER) != 0) {
            retries++;
            gpioDelay(100000);
            continue;
        }

        uint32_t elapsed = 0;
        while (elapsed < MEAS_TIMEOUT_US) {
            if (read_reg(REG_MEAS_CONFIG, &meas_config) != 0) {
                retries++;
                gpioDelay(100000);
                goto trigger_retry;
            }
            if ((meas_config & 0x01) == 0) break;
            gpioDelay(POLL_INTERVAL_US);
            elapsed += POLL_INTERVAL_US;
        }

        if (elapsed >= MEAS_TIMEOUT_US) {
            fprintf(stderr, "Measurement timeout\n");
            retries++;
            gpioDelay(100000);
            continue;
        }

        uint8_t temp_low, temp_high, hum_low, hum_high;
        if (read_reg(REG_TEMP_LOW, &temp_low) != 0 ||
            read_reg(REG_TEMP_HIGH, &temp_high) != 0 ||
            read_reg(REG_HUM_LOW, &hum_low) != 0 ||
            read_reg(REG_HUM_HIGH, &hum_high) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
