#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD_MSB 0x36
#define MEASURE_CMD_LSB 0x2F
#define READ_DELAY_US 45000
#define LOOP_DELAY_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* CRC-8 polynomial 0x31, initial value 0xFF (Sensirion convention) */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int send_command(int handle, uint8_t msb, uint8_t lsb) {
    char cmd[2] = { (char)msb, (char)lsb };
    int rc = i2cWriteDevice(handle, cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed (rc=%d)\n", rc);
        return -1;
    }
    return 0;
}

static int read_bytes(int handle, uint8_t *buf, int count) {
    int rc = i2cReadDevice(handle, (char *)buf, count);
    if (rc != count) {
        fprintf(stderr, "Error: i2cReadDevice returned %d (expected %d)\n", rc, count);
        return -1;
    }
    return 0;
}

static int read_sdp800(int handle, int16_t *pressure, int16_t *temperature) {
    if (send_command(handle, MEASURE_CMD_MSB, MEASURE_CMD_LSB) != 0)
        return -1;

    gpioDelay(READ_DELAY_US);

    uint8_t buf[6];
    if (read_bytes(handle, buf, 6) != 0)
        return -1;

    /* Verify CRC for pressure (bytes 0-1, CRC at byte 2) */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: pressure CRC mismatch\n");
        return -1;
    }

    /* Verify CRC for temperature (bytes 3-4, CRC at byte 5) */
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: temperature CRC mismatch\n");
        return -1;
    }

    *pressure = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (int16_t)((buf[3] << 8) | buf[4]);
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("SDP800-500Pa differential pressure sensor reader\n");
    printf("I2C bus %d, address 0x%02X\n", I2C_BUS, SDP800_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        int16_t pressure, temperature;
        if (read_sdp800(i2c_handle, &pressure, &temperature) == 0) {
            printf("Pressure: %d Pa, Temperature: %d (raw)\n", pressure, temperature);
        } else {
            fprintf(stderr, "Warning: sensor read failed, continuing...\n");
        }
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0)
        i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

