#define KD 0.1

#define MAX_PROFILE_ENTRIES 100

typedef struct {
    time_t timestamp;
    float target_temperature;
} TemperatureProfile;

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static FILE *log_file = NULL;
static TemperatureProfile profile[MAX_PROFILE_ENTRIES];
static int profile_size = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    int bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    int speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    relay_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!relay_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(relay_line, "reflow_oven", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        relay_line = NULL;
        return -1;
    }

    return 0;
}

static int read_max6675(float *temperature) {
    unsigned char tx[2] = {0x00, 0x00};
    unsigned char rx[2] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED_HZ,
        .delay_usecs = SPI_DELAY_US,
        .bits_per_word = SPI_BITS,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    int raw = (rx[0] << 8) | rx[1];
    if (raw & 0x0001) {
        fprintf(stderr, "MAX6675 open circuit detected (raw=0x%04X)\n", raw);
        return -2;
    }

    *temperature = (float)((raw >> 3) * 0.25);
    return 0;
}

static int load_temperature_profile(void) {
    FILE *fp = fopen(PROFILE_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening profile file %s: %s\n", PROFILE_FILE, strerror(errno));
        return -1;
    }

    profile_size = 0;
    while (profile_size < MAX_PROFILE_ENTRIES) {
        if (!fscanf(fp, "%ld,%f", &profile[profile_size].timestamp, &profile[profile_size].target_temperature)) {
            break;
        }
        profile_size++;
    }

    fclose(fp);
    return 0;
}

static float pid_control(float current_temperature, float target_temperature) {
    static float integral = 0.0;
    static float previous_error = 0.0;
    float error = target_temperature - current_temperature;
    integral += error;
    float derivative = error - previous_error;
    previous_error = error;

    float output = KP * error + KI * integral + KD * derivative;

    if (output < 0.0) output = 0.0;
    if (output > 1.0) output = 1.0;

    return output;
}

static void log_data(float current_temperature, float target_temperature, float pid_output) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, current_temperature, target_temperature, pid_output);
    fflush(log_file);
}

static void cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
        relay_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (gpio_init() < 0) {
        close(spi_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    if (load_temperature_profile() < 0) {
        cleanup();
        return 1;
    }

    time_t current_time = time(NULL);
    int current_profile_index = 0;

    while (running) {
        float current_temperature;
        int ret = read_max6675(&current_temperature);

        if (ret == -1) {
            fprintf(stderr, "SPI communication error. Retrying...\n");
            usleep(100000);
            continue;
        } else if (ret == -2) {
            fprintf(stderr, "MAX6675 open circuit. Retrying...\n");
            usleep(100000);
            continue;
        }

        if (current_time >= profile[current_profile_index].timestamp) {
            if (current_profile_index < profile_size - 1) {
                current_profile_index++;
            }
        }

        float target_temperature = profile[current_profile_index].target_temperature;
        float pid_output = pid_control(current_temperature, target_temperature);

        int relay_on_time_us = (int)(pid_output * RELAY_PERIOD_US);
        int relay_off_time_us = RELAY_PERIOD_US - relay_on_time_us;

        if (relay_on_time_us > 0) {
            if (gpiod_line_set_value(relay_line, 1) < 0) {
                fprintf(stderr, "Error setting relay ON: %s\n", strerror(errno));
            }
            usleep(relay_on_time_us);
        }
        if (relay_off_time_us > 0) {
            if (gpiod_line_set_value(relay_line, 0) < 0) {
                fprintf(stderr, "Error setting relay OFF: %s\n", strerror(errno));
            }
            usleep(relay_off_time_us);
        }

        log_data(current_temperature, target_temperature, pid_output);
        current_time = time(NULL);
    }

    cleanup();
    return 0;
}

