#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR_GPIO 4
#define RELAY_GPIO 17
#define PWM_GPIO 18
#define PWM_RANGE 100
#define PWM_PERIOD_NS 10000000  /* 10 ms -> 100 Hz */
#define LOG_FILE "greenhouse.log"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *pwm_line = NULL;

typedef struct {
    double Kp;
    double Ki;
    double Kd;
    double integral;
    double prev_error;
} PIDController;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(double *temp) {
    char path[128];
    char line[256];
    FILE *fp;
    int crc_ok = 0;

    snprintf(path, sizeof(path), "/sys/bus/w1/devices/28-000000000000/w1_slave");

    fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening sensor file: %s\n", strerror(errno));
        return -1;
    }

    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (strstr(line, "YES") != NULL) {
        crc_ok = 1;
    } else {
        fprintf(stderr, "CRC check failed for sensor data.\n");
        return -1;
    }

    char *temp_str = strstr(line, "t=");
    if (!temp_str) {
        fprintf(stderr, "Temperature data not found.\n");
        return -1;
    }

    long temp_raw = strtol(temp_str + 2, NULL, 10);
    *temp = (double)temp_raw / 1000.0;
    return 0;
}

static void set_relay(int state) {
    if (relay_line) {
        if (gpiod_line_set_value(relay_line, state) < 0) {
            fprintf(stderr, "Error setting relay GPIO: %s\n", strerror(errno));
        }
    }
}

static void set_pwm_duty(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;

    if (pwm_line) {
        struct timespec ts_on = {0, duty * PWM_PERIOD_NS / PWM_RANGE};
        struct timespec ts_off = {0, (PWM_RANGE - duty) * PWM_PERIOD_NS / PWM_RANGE};

        if (gpiod_line_set_value(pwm_line, 1) < 0) {
            fprintf(stderr, "Error setting PWM high: %s\n", strerror(errno));
            return;
        }
        nanosleep(&ts_on, NULL);
        if (gpiod_line_set_value(pwm_line, 0) < 0) {
            fprintf(stderr, "Error setting PWM low: %s\n", strerror(errno));
            return;
        }
        nanosleep(&ts_off, NULL);
    }
}

static double pid_control(PIDController *pid, double setpoint, double actual) {
    double error = setpoint - actual;
    double proportional = pid->Kp * error;
    pid->integral += pid->Ki * error;
    double derivative = pid->Kd * (error - pid->prev_error);
    double output = proportional + pid->integral + derivative;
    pid->prev_error = error;
    return output;
}

static void log_data(double avg_temp, double setpoint, double pid_out, int duty) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_fp, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, avg_temp, setpoint, pid_out, duty);
    fflush(log_fp);
}

static void cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
        relay_line = NULL;
    }
    if (pwm_line) {
        gpiod_line_set_value(pwm_line, 0);
        gpiod_line_release(pwm_line);
        pwm_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(int argc, char *argv[]) {
    double setpoint = 25.0;
    double Kp = 1.0, Ki = 0.1, Kd = 0.01;
    PIDController pid = {Kp, Ki, Kd, 0.0, 0.0};
    double temp;
    int duty;

    if (argc > 1) setpoint = atof(argv[1]);
    if (argc > 2) Kp = atof(argv[2]);
    if (argc > 3) Ki = atof(argv[3]);
    if (argc > 4) Kd = atof(argv[4]);

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        fclose(log_fp);
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        fprintf(stderr, "Error getting relay GPIO line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(relay_line, "greenhouse_relay", 0) < 0) {
        fprintf(stderr, "Error requesting relay GPIO output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    pwm_line = gpiod_chip_get_line(chip, PWM_GPIO);
    if (!pwm_line) {
        fprintf(stderr, "Error getting PWM GPIO line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(pwm_line, "greenhouse_pwm", 0) < 0) {
        fprintf(stderr, "Error requesting PWM GPIO output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Greenhouse PID controller started. Setpoint: %.2f, Kp: %.2f, Ki: %.2f, Kd: %.2f\n", setpoint, Kp, Ki, Kd);

    while (running) {
        if (read_temperature(&temp) != 0) {
            fprintf(stderr, "Error reading temperature. Skipping cycle.\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        double pid_out = pid_control(&pid, setpoint, temp);

        if (pid_out > 0) {
            set_relay(1);
            duty = (int)pid_out;
            if (duty > PWM_RANGE) duty = PWM_RANGE;
            set_pwm_duty(duty);
        } else {
            set_relay(0);
            set_pwm_duty(0);
        }

        log_data(temp, setpoint, pid_out, duty);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

