#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define AHT20_ADDR     0x38
#define GPIO_CHIP      "gpiochip4"
#define GPIO_LINE      17
#define HUMIDITY_HIGH  60.0f
#define HUMIDITY_LOW   55.0f
#define POLL_INTERVAL  5
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 10
#define MEASURE_DELAY_MS 80

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, cmd, len) == (ssize_t)len)
            return 0;
        fprintf(stderr, "I2C write attempt %d/%d failed: %s\n",
                attempt + 1, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES - 1)
            usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (read(fd, buf, len) == (ssize_t)len)
            return 0;
        fprintf(stderr, "I2C read attempt %d/%d failed: %s\n",
                attempt + 1, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES - 1)
            usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int aht20_init(int fd) {
