#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <syslog.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define MEASURE_CMD_HIGH 0x3E
#define MEASURE_CMD_LOW 0xB0
#define MEASURE_CMD_HOLD 0xBE
#define MEASURE_CMD_SOFT 0xAC
#define MEASURE_CMD_RESET 0xBA
#define MEASURE_CMD_READ_PREV 0x84

#define SERVER_IP "api.example.com"
#define SERVER_PORT 80
#define SERVER_PATH "/humidity"
#define POLL_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int sock_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        syslog(LOG_ERR, "I2C write failed (cmd 0x%02X): %s", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_htu21d(int fd, float *humidity) {
    uint8_t cmd[2] = {MEASURE_CMD_HIGH, MEASURE_CMD_LOW};
    uint8_t data[6];

    if (write(fd, cmd, 2) != 2) {
        syslog(LOG_ERR, "Failed to send measurement command: %s", strerror(errno));
        return -1;
    }

    usleep(15000);

    if (i2c_read_bytes(fd, data, 6) != 0) return -1;

    if (crc8(data, 2) != data[2]) {
        syslog(LOG_ERR, "Humidity CRC mismatch");
        return -1;
    }
    if (crc8(data + 3, 2) != data[5]) {
        syslog(LOG_ERR, "Temperature CRC mismatch");
        return -1;
    }

    uint16_t raw_humidity = (data[0] << 8) | data[1];
    uint16_t raw_temp = (data[3] << 8) | data[4];

    *humidity = -6.0f + 125.0f * (float)raw_humidity / 65536.0f;
    if (*humidity < 0.0f) *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;

    return 0;
}

static int send_http_post(const char *json_data) {
    struct sockaddr_in server_addr;
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid server IP: %s", SERVER_IP);
        close(fd);
        return -1;
    }

    if (connect(fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        syslog(LOG_ERR, "Connection to server failed: %s", strerror(errno));
        close(fd);
        return -1;
    }

    char request[512];
    int req_len = snprintf(request, sizeof(request),
        "POST %s HTTP/1.1\r\n"
        "Host: %s\r\n"
        "Content-Type: application/json\r\n"
        "Content-Length: %zu\r\n"
        "Connection: close\r\n"
        "\r\n"
        "%s",
        SERVER_PATH, SERVER_IP, strlen(json_data), json_data);

    if (write(fd, request, req_len) != req_len) {
        syslog(LOG_ERR, "Failed to send HTTP request: %s", strerror(errno));
        close(fd);
        return -1;
    }

    char response[1024];
    ssize_t n = read(fd, response, sizeof(response) - 1);
    if (n < 0) {
        syslog(LOG_ERR, "Failed to read HTTP response: %s", strerror(errno));
        close(fd);
        return -1;
    }
    response[n] = '\0';

    if (strstr(response, "200 OK") == NULL) {
        syslog(LOG_ERR, "HTTP POST failed with status: %s", response);
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int main(void) {
    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %s: %s", I2C_BUS, strerror(errno));
        closelog();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(i2c_fd);
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "HTU21D sensor initialized at 0x%02X on %s", HTU21D_ADDR, I2C_BUS);

    while (running) {
        float humidity;
        if (read_htu21d(i2c_fd, &humidity) == 0) {
            char json_data[128];
            snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);
            if (send_http_post(json_data) != 0) {
                syslog(LOG_ERR, "Failed to send humidity data to server");
            } else {
                syslog(LOG_INFO, "Sent humidity: %.2f%%", humidity);
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity from sensor");
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    if (i2c_fd >= 0) close(i2c_fd);
    if (sock_fd >= 0) close(sock_fd);
    closelog();
    return 0;
}

