#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_REG_CHIP_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_CHIP_ID 0x58
#define BMP280_CALIB_START 0x88
#define BMP280_CALIB_LEN 24
#define PRESSURE_HIGH_THRESHOLD 1020.0
#define PRESSURE_LOW_THRESHOLD 980.0
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 2000000
#define CONVERSION_WAIT_US 10000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_t;

static bmp280_calib_t calib;
static int32_t t_fine;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_calibration(int handle) {
    uint8_t buf[BMP280_CALIB_LEN];
    if (i2c_read_block(handle, BMP280_CALIB_START, buf, BMP280_CALIB_LEN) != 0) {
        return -1;
    }
    calib.dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    calib.dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    calib.dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    calib.dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    calib.dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    calib.dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    calib.dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    calib.dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    calib.dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    calib.dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    calib.dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    calib.dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int32_t compensate_temperature(int32_t adc_T) {
    int32_t var1, var2;
    var1 = ((((adc_T >> 3) - ((int32_t)calib.dig_T1 << 1))) * ((int32_t)calib.dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)calib.dig_T1)) * ((adc_T >> 4) - ((int32_t)calib.dig_T1))) >> 12) * ((int32_t)calib.dig_T3)) >> 14;
    t_fine = var1 + var2;
    return (t_fine * 5 + 128) >> 8;
}

static uint32_t compensate_pressure(int32_t adc_P) {
    int32_t var1, var2;
    uint32_t p;
    var1 = ((int32_t)t_fine >> 1) - 64000;
    var2 = (((var1 >> 2) * (var1 >> 2)) >> 11) * ((int32_t)calib.dig_P6);
    var2 = var2 + ((var1 * ((int32_t)calib.dig_P5)) << 1);
    var2 = (var2 >> 2) + (((int32_t)calib.dig_P4) << 16);
    var1 = (((calib.dig_P3 * (((var1 >> 2) * (var1 >> 2)) >> 13)) >> 3) + ((((int32_t)calib.dig_P2) * var1) >> 1)) >> 18;
    var1 = ((((32768 + var1)) * ((int32_t)calib.dig_P1)) >> 15);
    if (var1 == 0) return 0;
    p = (((uint32_t)(((1048576 - adc_P) - (var2 >> 12))) * 3125)) / (uint32_t)var1;
    var1 = (((int32_t)calib.dig_P9) * ((int32_t)(((p >> 3) * (p >> 3)) >> 13))) >> 12;
    var2 = (((int32_t)(p >> 2)) * ((int32_t)calib.dig_P8)) >> 13;
    p = (uint32_t)((int32_t)p + ((var1 + var2 + calib.dig_P7) >> 4));
    return p;
}

static int read_bmp280(int handle, double *temperature, double *pressure) {
    uint8_t data[6];
    if (i2c_write_byte(handle, BMP280_REG_CTRL_MEAS, 0x27) != 0) return -1;
    gpioDelay(CONVERSION_WAIT_US);
    if (i2c_read_block(handle, BMP280_REG_PRESS_MSB, data, 6) != 0) return -1;
    int32_t adc_P = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    int32_t adc_T = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);
    int32_t t = compensate_temperature(adc_T);
    *temperature = t / 100.0;
    uint32_t p = compensate_pressure(adc_P);
    *pressure = p / 100.0;
    return 0;
}

static void log_pressure_breach(double pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Pressure: %.2f hPa\n", ts, pressure);
    fclose(fp);
}

static int init_bmp280(int handle) {
    uint8_t chip_id;
    if (i2c_read_block(handle, BMP280_REG_CHIP_ID, &chip_id, 1) != 0) return -1;
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Invalid chip ID: 0x%02X (expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2c_write_byte(handle, BMP280_REG_RESET, 0xB6) != 0) return -1;
    gpioDelay(2000);
    if (read_calibration(handle) != 0) return -1;
    if (i2c_write_byte(handle, BMP280_REG_CONFIG, 0x00) != 0) return -1;
    return 0;
}

static int open_i2c_and_init(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %d\n", BMP280_I2C_ADDR, i2c_handle);
        return -1;
    }
    if (init_bmp280(i2c_handle) != 0) {
        fprintf(stderr, "BMP280 initialization failed\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (open_i2c_and_init() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("BMP280 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        double temperature, pressure;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && running) {
            if (read_bmp280(i2c_handle, &temperature, &pressure) == 0) {
                success = 1;
                break;
            }
            retries++;
            fprintf(stderr, "Read failed, retrying (%d/%d)...\n", retries, MAX_RETRIES);
            if (open_i2c_and_init() != 0) {
                fprintf(stderr, "I2C re-init failed, exiting.\n");
                break;
            }
        }

        if (success) {
            printf("Temperature: %.2f C, Pressure: %.2f hPa\n", temperature, pressure);
            if (pressure > PRESSURE_HIGH_THRESHOLD || pressure < PRESSURE_LOW_THRESHOLD) {
                log_pressure_breach(pressure);
            }
        } else {
            fprintf(stderr, "Failed to read sensor after %d retries.\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return 0;
}

