/*
 * Raspberry Pi 4B environmental logger
 * Sensors: TMP117 (I2C 0x48), AHT20 (I2C 0x38), PIR on GPIO 17
 * Log: daily CSV "Timestamp,Temperature(C),Humidity(%%),MotionDetected"
 * Build: gcc -o logger logger.c -lgpiod -lrt
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TMP117_ADDR    0x48
#define AHT20_ADDR     0x38
#define PIR_CHIP       "gpiochip4"
#define PIR_LINE       17
#define LOG_DIR        "logs"
#define SAMPLE_INTERVAL_S 1
#define I2C_RETRIES    3
#define I2C_RETRY_DELAY_MS 10
#define TMP117_LSB     0.0078125f

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t *cmd, size_t len) {
    for (int i = 0; i < I2C_RETRIES; i++) {
        if (write(fd, cmd, len) == (ssize_t)len) return 0;
        usleep(I2C_RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len) {
    for (int i = 0; i < I2C_RETRIES; i++) {
        if (read(fd, buf, len) == (ssize_t)len) return 0;
        usleep(I2C_RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int read_tmp117(int fd, float *temp) {
    uint8_t reg = 0x00;
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (i2c_read_data(fd, buf, 2) != 0) return -1;
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temp = raw * TMP117_LSB;
    return 0;
}

static int read_aht20(int fd, float *temp, float *hum) {
    uint8_t init_cmd[3] = {0xBE, 0x08, 0x00};
    if (i2c_write_cmd(fd, init_cmd, 3) != 0) return -1;
    usleep(15000);

    uint8_t measure_cmd[3] = {0xAC, 0x33, 0x00};
    if (i2c_write_cmd(fd, measure_cmd, 3) != 0) return -1;
    usleep(50000);

    uint8_t buf[7];
    if (i2c_read_data(fd, buf, 7) != 0) return -1;

    if (buf[0] & 0x80) return -1;

    uint32_t hum_raw = ((uint32_t)(buf[1] & 0x3F) << 12) |
                      ((uint32_t)buf[2] << 4) |
                      ((uint32_t)buf[3] >> 4);
    uint32_t temp_raw = ((uint32_t)buf[3] & 0x0F) << 16 |
                        ((uint32_t)buf[4] << 8) |
                        (uint32_t)buf[5];

    *hum = (float)hum_raw / 1048576.0f * 100.0f;
    *temp = (float)temp_raw / 1048576.0f * 200.0f - 50.0f;
    return 0;
}

static int get_current_date(char *buf, size_t len) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (!tm) return -1;
    strftime(buf, len, "%Y-%m-%d", tm);
    return 0;
}

static int open_log_file(const char *date) {
    char path[256];
    snprintf(path, sizeof(path), "%s/data_%s.csv", LOG_DIR, date);
    FILE *f = fopen(path, "a");
    if (!f) {
        char header[256];
        if (get_current_date(header, sizeof(header)) == 0) {
            snprintf(path, sizeof(path), "%s/data_%s.csv", LOG_DIR, date);
            f = fopen(path, "w");
            if (f) {
                fprintf(f, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
                fclose(f);
            }
        }
    }
    return fileno(f);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
