#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN   22
#define MOTOR_IN1_PIN   23
#define MOTOR_IN2_PIN   24
#define POLL_INTERVAL_SEC 2
#define MOTOR_RUN_SEC    5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_event(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s] %s\n", ts, msg);
    } else {
        printf("[unknown-time] %s\n", msg);
    }
    fflush(stdout);
}

static int motor_stop(struct gpiod_line *ena, struct gpiod_line *in1,
                      struct gpiod_line *in2)
{
    if (gpiod_line_set_value(in1, 0) < 0) {
        log_event("Error: failed to set IN1 low");
        return -1;
    }
    if (gpiod_line_set_value(in2, 0) < 0) {
        log_event("Error: failed to set IN2 low");
        return -1;
    }
    if (gpiod_line_set_value(ena, 0) < 0) {
        log_event("Error: failed to set ENA low");
        return -1;
    }
    return 0;
}

static int motor_forward(struct gpiod_line *ena, struct gpiod_line *in1,
                         struct gpiod_line *in2)
{
    if (gpiod_line_set_value(in1, 1) < 0) {
        log_event("Error: failed to set IN1 high");
        return -1;
    }
    if (gpiod_line_set_value(in2, 0) < 0) {
        log_event("Error: failed to set IN2 low");
        return -1;
    }
    if (gpiod_line_set_value(ena, 1) < 0) {
        log_event("Error: failed to set ENA high");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *rain_line = NULL;
    struct gpiod_line *ena_line = NULL;
    struct gpiod_line *in1_line = NULL;
    struct gpiod_line *in2_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (chip == NULL) {
        chip = gpiod_chip_open_by_name("gpiochip2");
    }
    if (chip == NULL) {
        chip = gpiod_chip_open_by_name("gpiochip1");
    }
    if (chip == NULL) {
        perror("gpiod_chip_open");
        log_event("Error: could not open any GPIO chip");
        return EXIT_FAILURE;
    }

    rain_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    ena_line  = gpiod_chip_get_line(chip, MOTOR_ENA_PIN);
    in1_line  = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    in2_line  = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);

    if (rain_line == NULL || ena_line == NULL || in1_line == NULL || in2_line == NULL) {
        perror("gpiod_chip_get_line");
        log_event("Error: could not acquire any GPIO line");
        goto cleanup;
    }

    if (gpiod_line_request_input(rain_line, "rain_sensor") < 0) {
        perror("gpiod_line_request_input(rain)");
        log_event("Error: failed to request rain sensor line as input");
        goto cleanup;
    }
    if (gpiod_line_request_output(ena_line, "motor_ena", 0) < 0) {
        perror("gpiod_line_request_output(ena)");
        log_event("Error: failed to request ENA line as output");
        goto cleanup;
    }
    if (gpiod_line_request_output(in1_line, "motor_in1", 0) < 0) {
        perror("gpiod_line_request_output(in1)");
        log_event("Error: failed to request IN1 line as output");
        goto cleanup;
    }
    if (gpiod_line_request_output(in2_line, "motor_in2", 0) < 0) {
        perror("gpiod_line_request_output(in2)");
        log_event("Error: failed to request IN2 line as output");
        goto cleanup;
    }

    log_event("Rain sensor monitoring started (GPIO17, active-low).");
    log_event("Motor control ready (ENA=GPIO22, IN1=GPIO23, IN2=GPIO24).");

    while (program_running) {
        int val = gpiod_line_get_value(rain_line);
        if (val < 0) {
            perror("gpiod_line_get_value(rain)");
            log_event("Error: failed to read rain sensor");
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (val == 0) {
            log_event("Rain detected!");
            if (motor_forward(ena_line, in1_line, in2_line) == 0) {
                log_event("Motor running forward for 5 seconds.");
                for (int i = 0; i < MOTOR_RUN_SEC && program_running; i++) {
                    sleep(1);
                }
                if (motor_stop(ena_line, in1_line, in2_line) < 0) {
                    log_event("Error: failed to stop motor after run");
                } else {
                    log_event("Motor stopped.");
                }
            } else {
                log_event("Error: failed to start motor forward");
            }
        }

        if (program_running) {
            sleep(POLL_INTERVAL_SEC);
        }
    }

    log_event("Shutting down gracefully.");
    ret = EXIT_SUCCESS;

cleanup:
    if (rain_line)   gpiod_line_release(rain_line);
    if (ena_line)    gpiod_line_release(ena_line);
    if (in1_line)    gpiod_line_release(in1_line);
    if (in2_line)    gpiod_line_release(in2_line);
    if (chip)        gpiod_chip_close(chip);
    return ret;
}

