#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_RANGE 255
#define SAMPLE_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — turn LED off and terminate pigpio cleanly.        */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read CPU load as a percentage (0.0 to 100.0).                       */
/* Returns -1.0 on error.                                              */
/* ------------------------------------------------------------------ */
static double read_cpu_load(void)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1.0;
    }

    unsigned long long user, nice, system, idle, iowait, irq, softirq;
    unsigned long long prev_idle, prev_nonidle;
    unsigned long long now_idle, now_nonidle;
    double load;

    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq) != 7) {
        fprintf(stderr, "Error parsing /proc/stat\n");
        fclose(fp);
        return -1.0;
    }
    fclose(fp);

    prev_idle = idle + iowait;
    prev_nonidle = user + nice + system + irq + softirq;

    usleep(SAMPLE_INTERVAL_US);

    fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Error reopening /proc/stat: %s\n", strerror(errno));
        return -1.0;
    }
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq) != 7) {
        fprintf(stderr, "Error parsing /proc/stat (second read)\n");
        fclose(fp);
        return -1.0;
    }
    fclose(fp);

    now_idle = idle + iowait;
    now_nonidle = user + nice + system + irq + softirq;

    unsigned long long idle_delta = now_idle - prev_idle;
    unsigned long long nonidle_delta = now_nonidle - prev_nonidle;

    if (idle_delta == 0) {
        load = 100.0;
    } else {
        load = (double)(nonidle_delta) / (double)(idle_delta + nonidle_delta) * 100.0;
    }

    return load;
}

/* ------------------------------------------------------------------ */
/* Map load (0.0 to 100.0) to RGB (0-255 clamped).                     */
/* ------------------------------------------------------------------ */
static void map_load_to_rgb(double load, int *r, int *g, int *b)
{
    if (load < 0.0) load = 0.0;
    if (load > 100.0) load = 100.0;

    if (load < 50.0) {
        /* Green -> Yellow */
        *r = (int)((load / 50.0) * 255.0);
        *g = 255;
        *b = 0;
    } else {
        /* Yellow -> Red */
        *r = 255;
        *g = (int)((100.0 - load) / 50.0) * 255.0;
        *b = 0;
    }
}

/* ------------------------------------------------------------------ */
/* Common-anode LED: full brightness = 0, off = PWM_RANGE.              */
/* ------------------------------------------------------------------ */
static void set_led_color(int r, int g, int b)
{
    if (r < 0) r = 0; if (r > 255) r = 255;
    if (g < 0) g = 0; if (g > 255) g = 255;
    if (b < 0) b = 0; if (b > 255) b = 255;

    int red_pwm  = PWM_RANGE - r;
    int green_pwm = PWM_RANGE - g;
    int blue_pwm  = PWM_RANGE - b;

    gpioPWM(RED_PIN,  red_pwm);
    gpioPWM(GREEN_PIN, green_pwm);
    gpioPWM(BLUE_PIN, blue_pwm);
}

/* ------------------------------------------------------------------ */
/* Turn LED off (common-anode: all channels to full off).              */
/* ------------------------------------------------------------------ */
static void led_off(void)
{
    gpioPWM(RED_PIN,  PWM_RANGE);
    gpioPWM(GREEN_PIN, PWM_RANGE);
    gpioPWM(BLUE_PIN, PWM_RANGE);
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Configure PWM pins */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(RED_PIN,  PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }

    /* Start with LED off */
    led_off();

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("CPU Load RGB LED running. Press Ctrl+C to exit.\n");

    while (g_running) {
        double load = read_cpu_load();
        if (load < 0.0) {
            fprintf(stderr, "Error reading CPU load, turning LED off.\n");
            led_off();
            sleep(1);
            continue;
        }

        int r, g, b;
        map_load_to_rgb(load, &r, &g, &b);
        set_led_color(r, g, b);

        printf("CPU Load: %.1f%% -> R:%d G:%d B:%d\n", load, r, g, b);

        sleep(1);
    }

    /* Graceful shutdown */
    led_off();
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return 0;
}

