#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_REG_CHIP_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB 0x88
#define BMP280_CHIP_ID 0x58

#define UDP_SERVER_IP "192.168.1.100"
#define UDP_SERVER_PORT 5000
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int udp_socket = -1;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_t;

static bmp280_calib_t calib;
static int32_t t_fine;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    int bytes = i2cReadDevice(handle, (char *)buf, len);
    if (bytes != (int)len) return -1;
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val) {
    return i2cWriteByteData(handle, reg, val);
}

static int read_calibration(int handle, bmp280_calib_t *c) {
    uint8_t buf[24];
    if (i2c_read_reg(handle, BMP280_REG_CALIB, buf, 24) < 0) return -1;
    c->dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    c->dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    c->dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    c->dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    c->dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    c->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    c->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    c->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    c->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    c->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    c->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    c->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int32_t compensate_temperature(int32_t adc_T) {
    int32_t var1, var2;
    var1 = ((((adc_T >> 3) - ((int32_t)calib.dig_T1 << 1))) * ((int32_t)calib.dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)calib.dig_T1)) * ((adc_T >> 4) - ((int32_t)calib.dig_T1))) >> 12) * ((int32_t)calib.dig_T3)) >> 14;
    t_fine = var1 + var2;
    return (t_fine * 5 + 128) >> 8;
}

static uint32_t compensate_pressure(int32_t adc_P) {
    int32_t var1, var2;
    uint32_t p;
    var1 = ((int32_t)t_fine >> 1) - 64000;
    var2 = (((var1 >> 2) * (var1 >> 2)) >> 11) * ((int32_t)calib.dig_P6);
    var2 = var2 + ((var1 * ((int32_t)calib.dig_P5)) << 1);
    var2 = (var2 >> 2) + (((int32_t)calib.dig_P4) << 16);
    var1 = (((calib.dig_P3 * (((var1 >> 2) * (var1 >> 2)) >> 13)) >> 3) + ((((int32_t)calib.dig_P2) * var1) >> 1)) >> 18;
    var1 = ((((32768 + var1)) * ((int32_t)calib.dig_P1)) >> 15);
    if (var1 == 0) return 0;
    p = (((uint32_t)(((1048576 - adc_P) - (var2 >> 12))) * 3125)) / (uint32_t)var1;
    var1 = (((int32_t)calib.dig_P9) * ((int32_t)(((p >> 3) * (p >> 3)) >> 13))) >> 12;
    var2 = (((int32_t)(p >> 2)) * ((int32_t)calib.dig_P8)) >> 13;
    p = (uint32_t)((int32_t)p + ((var1 + var2 + calib.dig_P7) >> 4));
    return p;
}

static int read_sensor(int handle, float *temp, float *press) {
    uint8_t buf[6];
    if (i2c_write_reg(handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) return -1;
    gpioDelay(10000);
    if (i2c_read_reg(handle, BMP280_REG_PRESS_MSB, buf, 6) < 0) return -1;
    int32_t adc_P = (buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4);
    int32_t adc_T = (buf[3] << 12) | (buf[4] << 4) | (buf[5] >> 4);
    *temp = compensate_temperature(adc_T) / 100.0f;
    *press = compensate_pressure(adc_P) / 100.0f;
    return 0;
}

static int send_udp(const char *data, const char *ip, int port) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip, &addr.sin_addr) <= 0) return -1;
    if (sendto(udp_socket, data, strlen(data), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    uint8_t chip_id;
    if (i2c_read_reg(i2c_handle, BMP280_REG_CHIP_ID, &chip_id, 1) < 0) {
        fprintf(stderr, "Failed to read chip ID\n");
        goto cleanup;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Wrong chip ID: 0x%02X (expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
        goto cleanup;
    }

    if (read_calibration(i2c_handle, &calib) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        goto cleanup;
    }

    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        fprintf(stderr, "Socket creation failed: %s\n", strerror(errno));
        goto cleanup;
    }

    while (running) {
        float temp, press;
        if (read_sensor(i2c_handle, &temp, &press) == 0) {
            char json[128];
            snprintf(json, sizeof(json), "{\"temperature\":%.2f,\"pressure\":%.2f}", temp, press);
            if (send_udp(json, UDP_SERVER_IP, UDP_SERVER_PORT) < 0) {
                fprintf(stderr, "UDP send failed: %s\n", strerror(errno));
            }
        } else {
            fprintf(stderr, "Sensor read failed\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

cleanup:
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (udp_socket >= 0) close(udp_socket);
    gpioTerminate();
    return 0;
}

