}

static int read_sensor(int handle, float *temp, float *press) {
    uint8_t buf[6];
    if (i2c_write_reg(handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) return -1;
    gpioDelay(10000);
    if (i2c_read_reg(handle, BMP280_REG_PRESS_MSB, buf, 6) < 0) return -1;
    int32_t adc_P = (buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4);
    int32_t adc_T = (buf[3] << 12) | (buf[4] << 4) | (buf[5] >> 4);
    *temp = compensate_temperature(adc_T) / 100.0f;
    *press = compensate_pressure(adc_P) / 100.0f;
