}

static int send_udp(const char *data, const char *ip, int port) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip, &addr.sin_addr) <= 0) return -1;
    if (sendto(udp_socket, data, strlen(data), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) return -1;
    return 0;
}

