#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define FAN_GPIO        18
#define SPI_CHANNEL     0
#define SPI_SPEED       500000
#define SPI_FLAGS       0
#define PWM_RANGE       255
#define PWM_FREQ        1000
#define BUFFER_SIZE     20
#define SAMPLE_PERIOD_US 1000000

#define TEMP_LOW        25.0f
#define TEMP_MED        40.0f
#define TEMP_HIGH       60.0f

#define MAX31855_FAULT   0x00020000
#define MAX31855_OC      0x00000001
#define MAX31855_SCG     0x00000002
#define MAX31855_SCV     0x00000004

typedef struct {
    time_t timestamp;
    float  temperature;
    int    pwm_duty;
} Reading;

static Reading buffer[BUFFER_SIZE];
static int    buffer_index = 0;
static int    buffer_count = 0;
static int    spi_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d.\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d.\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioPWM(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise PWM on GPIO%d.\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (channel %d, %d Hz).\n",
                SPI_CHANNEL, SPI_SPEED);
        gpioPWM(FAN_GPIO, 0);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
}

static int read_temperature(float *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    if (spiXfer(spi_handle, tx, rx, 4) != 4) {
        fprintf(stderr, "Error: SPI transfer failed.\n");
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & MAX31855_FAULT) {
        fprintf(stderr, "Error: MAX31855 fault detected (raw=0x%08X).\n", raw);
        if (raw & MAX31855_OC)
            fprintf(stderr, "  - Open-circuit fault\n");
        if (raw & MAX31855_SCG)
            fprintf(stderr, "  - Short to GND fault\n");
        if (raw & MAX31855_SCV)
            fprintf(stderr, "  - Short to VCC fault\n");
        return -1;
    }

    int16_t thermocouple_raw = (int16_t)(raw >> 18);
    *temperature = thermocouple_raw * 0.25f;
    return 0;
}

static int calculate_pwm_duty(float temperature) {
    if (temperature < TEMP_LOW)
        return 0;
    if (temperature < TEMP_MED)
        return (int)((temperature - TEMP_LOW) * 50.0f / (TEMP_MED - TEMP_LOW));
    if (temperature < TEMP_HIGH)
        return (int)((temperature - TEMP_MED) * 150.0f / (TEMP_HIGH - TEMP_MED) + 50);
    return PWM_RANGE;
}

static void log_reading(float temperature, int pwm_duty) {
    buffer[buffer_index].timestamp  = time(NULL);
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].pwm_duty    = pwm_duty;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE)
        buffer_count++;
}

static void print_buffer(void) {
    printf("\n--- Temperature Log (%d entries) ---\n", buffer_count);
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm = localtime(&buffer[idx].timestamp);
        if (tm)
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
        else
            snprintf(ts, sizeof(ts), "?");
        printf("[%s] Temp: %.2f C  PWM: %d/%d\n",
               ts, buffer[idx].temperature,
               buffer[idx].pwm_duty, PWM_RANGE);
    }
    printf("-------------------------------------\n");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize() != 0)
        return 1;

    printf("Temperature-controlled fan started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            int pwm_duty = calculate_pwm_duty(temperature);
            if (gpioPWM(FAN_GPIO, pwm_duty) != 0) {
                fprintf(stderr, "Warning: gpioPWM failed for duty %d.\n", pwm_duty);
            }
            log_reading(temperature, pwm_duty);
            printf("Temp: %.2f C  PWM: %d/%d\n",
                   temperature, pwm_duty, PWM_RANGE);
        } else {
            fprintf(stderr, "Skipping fan update due to read error.\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    print_buffer();
    cleanup();
    printf("Exiting cleanly.\n");
    return 0;
}

