static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(void) {
    int rc;
    rc = i2cReadByteData(i2c_handle, 0xAA);
    if (rc < 0) return -1;
    ac1 = (rc << 8) | i2cReadByteData(i2c_handle, 0xAC);
    rc = i2cReadByteData(i2c_handle, 0xAC + 1);
