    ac3 = (i2cReadByteData(i2c_handle, 0xB0) << 8) | i2cReadByteData(i2c_handle, 0xB1);
    ac4 = (i2cReadByteData(i2c_handle, 0xB2) << 8) | i2cReadByteData(i2c_handle, 0xB3);
    ac5 = (i2cReadByteData(i2c_handle, 0xB4) << 8) | i2cReadByteData(i2c_handle, 0xB5);
    ac6 = (i2cReadByteData(i2c_handle, 0xB6) << 8) | i2cReadByteData(i2c_handle, 0xB7);
    b1 = (i2cReadByteData(i2c_handle, 0xB8) << 8) | i2cReadByteData(i2c_handle, 0xB9);
    b2 = (i2cReadByteData(i2c_handle, 0xBA) << 8) | i2cReadByteData(i2c_handle, 0xBB);
    mb = (i2cReadByteData(i2c_handle, 0xBC) << 8) | i2cReadByteData(i2c_handle, 0xBD);
    mc = (i2cReadByteData(i2c_handle, 0xBE) << 8) | i2cReadByteData(i2c_handle, 0xBF);
    md = (i2cReadByteData(i2c_handle, 0xC0) << 8) | i2cReadByteData(i2c_handle, 0xC1);
    return 0;
}

static int read_raw_temperature(void) {
    if (i2cWriteByteData(i2c_handle, 0xF4, 0x2E) < 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadByteData(i2c_handle, 0xF6);
    int lsb = i2cReadByteData(i2c_handle, 0xF7);
    if (msb < 0 || lsb < 0) return -1;
    return (msb << 8) | lsb;
