        fprintf(stderr, "Error: Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetTimerFuncEx(0, 500, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set up hardware timer.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("BMP180 logging started. Press Ctrl+C to stop.\n");

    while (running) {
        gpioDelay(100000);
    }

    gpioSetTimerFuncEx(0, 500, NULL, NULL);
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return 0;
}

