        fprintf(stderr, "Chip ID mismatch: got 0x%02X, expected 0x%02X\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }
    if (bmp280_read_calibration(fd, cal) != 0)
        return -1;
    if (i2c_write_reg(fd, BMP280_REG_RESET, 0xB6) != 0)
        return -1;
    usleep(2000);
    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x00) != 0)
        return -1;
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x27) != 0)
        return -1;
    return 0;
}

static int bmp280_read(int fd, const bmp280_calib_t *cal, float *temp, float *press) {
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x27) != 0)
        return -1;
    for (int i = 0; i < MEAS_TIMEOUT_MS; i++) {
        uint8_t status;
        if (i2c_read_reg(fd, BMP280_REG_STATUS, &status) != 0)
            return -1;
        if ((status & 0x08) == 0)
            break;
        usleep(1000);
        if (i == MEAS_TIMEOUT_MS - 1) {
            fprintf(stderr, "BMP280 measurement timeout\n");
            return -1;
        }
    }
    uint8_t buf[6];
    if (i2c_read_block(fd, BMP280_REG_PRESS_MSB, buf, 6) != 0)
        return -1;
    int32_t raw_press = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | ((int32_t)buf[2] >> 4);
    int32_t raw_temp  = ((int32_t)buf[3] << 12) | ((int32_t)buf[4] << 4) | ((int32_t)buf[5] >> 4);
    int32_t var1, var2, t_fine;
    var1 = ((((raw_temp >> 3) - ((int32_t)cal->dig_T1 << 1))) * ((int32_t)cal->dig_T2)) >> 11;
    var2 = (((((raw_temp >> 4) - ((int32_t)cal->dig_T1)) * ((raw_temp >> 4) - ((int32_t)cal->dig_T1))) >> 12) * ((int32_t)cal->dig_T3)) >> 14;
    t_fine = var1 + var2;
    *temp = ((t_fine * 5 + 128) >> 8) / 100.0f;
    int64_t v1, v2, p;
    v1 = ((int64_t)t_fine) - 128000;
    v2 = v1 * v1 * (int64_t)cal->dig_P6;
    v2 = v2 + ((v1 * (int64_t)cal->dig_P5) << 17);
    v2 = v2 + (((int64_t)cal->dig_P4) << 35);
    v1 = ((v1 * v1 * (int64_t)cal->dig_P3) >> 8) + ((v1 * (int64_t)cal->dig_P2) << 12);
    v1 = (((((int64_t)1) << 47) + v1)) * ((int64_t)cal->dig_P1) >> 33;
    if (v1 == 0) {
        fprintf(stderr, "BMP280 compensation divide-by-zero\n");
        return -1;
    }
    p = 1048576 - raw_press;
    p = (((p << 31) - v2) * 3125) / v1;
    v1 = (((int64_t)cal->dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    v2 = (((int64_t)cal->dig_P8) * p) >> 19;
    p = ((p + v1 + v2) >> 8) + (((int64_t)cal->dig_P7) << 4);
    *press = (float)p / 25600.0f;
    return 0;
}

static void log_data(float temp, float press) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[20];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", ts, temp, press);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int addr = BMP280_ADDR_1;
    int found = 0;
    for (int attempt = 0; attempt < 2 && g_running; attempt++) {
        g_i2c_fd = open(I2C_BUS, O_RDWR);
        if (g_i2c_fd < 0) {
            fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
            sleep(1);
            continue;
        }
        if (ioctl(g_i2c_fd, I2C_SLAVE, addr) < 0) {
            fprintf(stderr, "ioctl I2C_SLAVE 0x%02X: %s\n", addr, strerror(errno));
            close(g_i2c_fd);
            g_i2c_fd = -1;
            if (addr == BMP280_ADDR_1) addr = BMP280_ADDR_2;
            else addr = BMP280_ADDR_1;
            sleep(1);
            continue;
        }
        bmp280_calib_t cal;
        if (bmp280_init(g_i2c_fd, &cal) == 0) {
            found = 1;
            break;
        }
        close(g_i2c_fd);
        g_i2c_fd = -1;
        if (addr == BMP280_ADDR_1) addr = BMP280_ADDR_2;
        else addr = BMP280_ADDR_1;
        sleep(1);
    }
    if (!found) {
        fprintf(stderr, "BMP280 not found at 0x%02X or 0x%02X\n", BMP280_ADDR_1, BMP280_ADDR_2);
        return 1;
    }
    printf("BMP280 initialized at 0x%02X\n", addr);

    while (g_running) {
        float temp, press;
        if (bmp280_read(g_i2c_fd, &cal, &temp, &press) == 0) {
            log_data(temp, press);
            printf("T=%.2f °C  P=%.2f hPa\n", temp, press);
        } else {
            fprintf(stderr, "Read failed; attempting re-init\n");
            close(g_i2c_fd);
            g_i2c_fd = -1;
            sleep(1);
            if (g_running) {
                if (ioctl(g_i2c_fd, I2C_SLAVE, addr) < 0) {
                    fprintf(stderr, "ioctl I2C_SLAVE: %s\n", strerror(errno));
                    sleep(1);
                }
                if (bmp280_init(g_i2c_fd, &cal) != 0) {
                    fprintf(stderr, "Re-init failed\n");
                }
            }
        }
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++)
            sleep(1);
    }
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

