#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 1
#define PWM_RANGE 1000
#define PWM_FREQUENCY 1000
#define CONFIG_FILE "config.json"
#define MAX_TEMP_ERROR 80.0
#define SAMPLE_INTERVAL_US 100000

#define MAX31865_CONFIG_REG 0x80
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x07

#define R_REF 430.0
#define R0 100.0
#define A 0.0039083
#define B -0.0000005775

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static double target_temp = 25.0;
static double Kp = 1.0;
static double Ki = 0.1;
static double Kd = 0.01;
static double integral = 0.0;
static double last_error = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename, double *target, double *kp, double *ki, double *kd) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open config file '%s'; using defaults\n", filename);
        return -1;
    }
    char line[256];
    int found = 0;
    while (fgets(line, sizeof(line), fp)) {
        char key[64];
        char val[64];
        if (sscanf(line, " \"%[^\"]\" : \"%[^\"]\"", key, val) == 2) {
            if (strcmp(key, "target_temp") == 0) *target = atof(val);
            else if (strcmp(key, "Kp") == 0) *kp = atof(val);
            else if (strcmp(key, "Ki") == 0) *ki = atof(val);
            else if (strcmp(key, "Kd") == 0) *kd = atof(val);
            found = 1;
        }
    }
    fclose(fp);
    if (!found) {
        fprintf(stderr, "Warning: config file '%s' missing keys; using defaults\n", filename);
        return -1;
    }
    return 0;
}

static int spi_write_reg(uint8_t reg, uint8_t val) {
    char tx[2] = { (char)(reg | 0x80), (char)val };
    char rx[2] = {0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) return -1;
    return 0;
}

static int spi_read_reg(uint8_t reg, uint8_t *val) {
    char tx[2] = { (char)(reg & 0x7F), 0x00 };
    char rx[2] = {0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) return -1;
    *val = (uint8_t)rx[1];
    return 0;
}

static int max31865_init(void) {
    if (spi_write_reg(MAX31865_CONFIG_REG, 0xC1) != 0) {
        fprintf(stderr, "Error: failed to write MAX31865 config register\n");
        return -1;
    }
    return 0;
}

static int max31865_read_rtd(double *temp_out) {
    uint8_t msb = 0, lsb = 0, fault = 0;
    if (spi_read_reg(MAX31865_RTD_MSB_REG, &msb) != 0) return -1;
    if (spi_read_reg(MAX31865_RTD_LSB_REG, &lsb) != 0) return -1;
    if (spi_read_reg(MAX31865_FAULT_REG, &fault) != 0) return -1;
    if (fault & 0x01) {
        fprintf(stderr, "MAX31865 fault: RTD open circuit\n");
        return -1;
    }
    if (fault & 0x02) {
        fprintf(stderr, "MAX31865 fault: RTD short to GND\n");
        return -1;
    }
