static int read_config(const char *filename, double *target, double *kp, double *ki, double *kd) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open config file '%s'; using defaults\n", filename);
        return -1;
    }
    char line[256];
    int found = 0;
    while (fgets(line, sizeof(line), fp)) {
        char key[64];
        char val[64];
        if (sscanf(line, " \"%[^\"]\" : \"%[^\"]\"", key, val) == 2) {
