#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP180_ADDR 0x77
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "breach_log.txt"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3

#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE_OSS1 0x34

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, 2) == 2) return 0;
        if (errno == EINTR) continue;
        usleep(10000);
    }
    return -1;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            if (errno == EINTR) continue;
            usleep(10000);
            continue;
        }
        if (read(fd, buf, len) == len) return 0;
        if (errno == EINTR) continue;
        usleep(10000);
    }
    return -1;
}

static int read_calibration(int fd) {
    uint8_t buf[22];
    if (i2c_read_bytes(fd, 0xAA, buf, 22) != 0) return -1;
    ac1 = (buf[0] << 8) | buf[1];
    ac2 = (buf[2] << 8) | buf[3];
    ac3 = (buf[4] << 8) | buf[5];
    ac4 = (buf[6] << 8) | buf[7];
    ac5 = (buf[8] << 8) | buf[9];
    ac6 = (buf[10] << 8) | buf[11];
    b1 = (buf[12] << 8) | buf[13];
    b2 = (buf[14] << 8) | buf[15];
    mb = (buf[16] << 8) | buf[17];
    mc = (buf[18] << 8) | buf[19];
    md = (buf[20] << 8) | buf[21];
    return 0;
}

static int read_raw_temp(int fd, int32_t *raw) {
    if (i2c_write_byte(fd, BMP180_REG_CONTROL, BMP180_CMD_TEMP) != 0) return -1;
    usleep(5000);
    uint8_t buf[2];
    if (i2c_read_bytes(fd, BMP180_REG_MSB, buf, 2) != 0) return -1;
    *raw = (buf[0] << 8) | buf[1];
    return 0;
}

static int read_raw_pressure(int fd, int32_t *raw) {
    if (i2c_write_byte(fd, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE_OSS1) != 0) return -1;
    usleep(5000);
    uint8_t buf[3];
    if (i2c_read_bytes(fd, BMP180_REG_MSB, buf, 3) != 0) return -1;
    *raw = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> 8;
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    return x1 + x2;
}

static int32_t compute_b5_inv(int32_t up) {
    int32_t x1 = ((up - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    return x1 + x2;
}

static float calc_temperature(int32_t ut) {
    int32_t b5 = compute_b5(ut);
    return ((b5 + 8) >> 4) / 10.0f;
}

static float calc_pressure(int32_t up, int32_t ut) {
    int32_t b5 = compute_b5_inv(up);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << 0) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (float)p / 100.0f;
}

static void log_breach(float temp, float press) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_fp, "%s - Temperature: %.2f C, Pressure: %.2f hPa\n", ts, temp, press);
    fflush(log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", BMP180_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (read_calibration(i2c_fd) != 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("Monitoring BMP180 at 0x%02X on %s. Press Ctrl+C to exit.\n", BMP180_ADDR, I2C_BUS);

    while (running) {
        int32_t ut, up;
        if (read_raw_temp(i2c_fd, &ut) != 0) {
            fprintf(stderr, "Temp read failed: %s\n", strerror(errno));
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }
        if (read_raw_pressure(i2c_fd, &up) != 0) {
            fprintf(stderr, "Pressure read failed: %s\n", strerror(errno));
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float temp = calc_temperature(ut);
        float press = calc_pressure(up, ut);

        if (temp > 30.0f || press < 950.0f) {
            log_breach(temp, press);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

