#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define I2C_BUS        1
#define BMP180_ADDR    0x77
#define FAN_GPIO       18
#define TEMP_THRESHOLD 30.0f
#define BUFFER_SIZE    60
#define SAMPLE_US      500000  /* 500 ms */

/* BMP180 registers */
#define BMP180_REG_CONTROL  0xF4
#define BMP180_REG_MSB      0xF6
#define BMP180_REG_LSB      0xF7
#define BMP180_REG_XLSB     0xF8
#define BMP180_REG_CAL_AC1  0xAA

/* Oversampling setting (0 = ultra low power, 4.5 ms) */
#define OSS 0

typedef struct {
    time_t timestamp;
    float  temperature;
    float  pressure;
} Reading;

typedef struct {
    Reading buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* Calibration coefficients */
static int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_calibration(void) {
    uint8_t data[22];
    if (i2cReadI2CBlockData(g_i2c_handle, BMP180_REG_CAL_AC1, (char *)data, 22) != 22) {
        fprintf(stderr, "Error: failed to read 22-byte calibration block\n");
        return -1;
    }
    ac1 = (int16_t)((data[0]  << 8) | data[1]);
    ac2 = (int16_t)((data[2]  << 8) | data[3]);
    ac3 = (int16_t)((data[4]  << 8) | data[5]);
    ac4 = (uint16_t)((data[6]  << 8) | data[7]);
    ac5 = (uint16_t)((data[8]  << 8) | data[9]);
    ac6 = (uint16_t)((data[10] << 8) | data[11]);
    b1  = (int16_t)((data[12] << 8) | data[13]);
    b2  = (int16_t)((data[14] << 8) | data[15]);
    mb  = (int16_t)((data[16] << 8) | data[17]);
    mc  = (int16_t)((data[18] << 8) | data[19]);
    md  = (int16_t)((data[20] << 8) | data[21]);
    return 0;
}

/* Returns temperature in 0.1 °C units (raw * 100) */
static int32_t read_raw_temperature(void) {
    if (i2cWriteByteData(g_i2c_handle, BMP180_REG_CONTROL, 0x2E) < 0) {
        fprintf(stderr, "Error: failed to write temperature command\n");
        return -1;
    }
    gpioDelay(5000); /* 4.5 ms max conversion time */
    uint8_t data[2];
    if (i2cReadI2CBlockData(g_i2c_handle, BMP180_REG_MSB, (char *)data, 2) != 2) {
        fprintf(stderr, "Error: failed to read temperature data\n");
        return -1;
    }
    return (int32_t)((data[0] << 8) | data[1]);
}

/* Returns pressure in Pa (OSS=0: 4.5 ms, OSS=1: 7.5 ms, OSS=2: 13.5 ms) */
static int32_t read_raw_pressure(void) {
    uint8_t cmd = 0x34 + (OSS << 6);
    if (i2cWriteByteData(g_i2c_handle, BMP180_REG_CONTROL, cmd) < 0) {
        fprintf(stderr, "Error: failed to write pressure command\n");
        return -1;
    }
    gpioDelay(5000 + (OSS == 2 ? 8000 : 0)); /* 4.5 ms + 8 ms for OSS=2 */
    uint8_t data[3];
    if (i2cReadI2CBlockData(g_i2c_handle, BMP180_REG_MSB, (char *)data, 3) != 3) {
        fprintf(stderr, "Error: failed to read pressure data\n");
        return -1;
    }
    return ((int32_t)data[0] << 16 | (int32_t)data[1] << 8 | data[2]) >> (8 - OSS);
}

static float calculate_temperature(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    return ((b5 + 8) >> 4) / 10.0f;
}

static float calculate_pressure(int32_t up, int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    int32_t x3 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x4 = ((int32_t)ac2 * b6) >> 11;
    int32_t b3 = (((int32_t)ac1 * 4 + x3 + x4) << OSS) + 2;
    b3 >>= 2;
    uint32_t x1_p = ((uint32_t)ac3 * b6) >> 13;
    uint32_t x2_p = ((uint32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    uint32_t x3_p = ((uint32_t)ac4 * (x1_p + x2_p + 32768)) >> 15;
    uint32_t b4 = (uint32_t)ac4 * (uint32_t)ac6 >> 10;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000UL) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1_p = (p >> 8) * (p >> 8);
    x1_p = (x1_p * 3038) >> 16;
    x2_p = (-7357 * p) >> 16;
    return (float)(p + ((x1_p + x2_p + 3791) >> 4));
}

static void buffer_add(CircularBuffer *cb, float temp, float pres) {
    cb->buffer[cb->head].timestamp = time(NULL);
    cb->buffer[cb->head].temperature = temp;
    cb->buffer[cb->head].pressure = pres;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static void timer_callback(void *user) {
    (void)user;
    int32_t ut = read_raw_temperature();
    if (ut < 0) return;
    int32_t up = read_raw_pressure();
    if (up < 0) return;
    float temp = calculate_temperature(ut);
    float pres = calculate_pressure(up, ut);
    buffer_add(&g_cb, temp, pres);
    gpioWrite(FAN_GPIO, temp > TEMP_THRESHOLD ? 1 : 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (read_calibration() != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);

    g_cb.head = 0;
    g_cb.count = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetTimerFuncEx(0, SAMPLE_US, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetTimerFuncEx failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        gpioDelay(100000); /* 100 ms sleep to reduce CPU usage */
    }

    /* Cleanup */
    gpioSetTimerFuncEx(0, SAMPLE_US, NULL, NULL);
    gpioWrite(FAN_GPIO, 0);
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

