#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define PWM_RANGE 255
#define MAX_DUTY_CYCLE 204  /* ~80% of 255 */
#define DEFAULT_TARGET_TEMP 25.0
#define LOG_FILE "heater_log.csv"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_max31855(int handle, float *temp_c) {
    char rx[4] = {0};
    int ret = spiRead(handle, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "SPI read failed (returned %d)\n", ret);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        if (raw & 0x00000004) {
            fprintf(stderr, "MAX31855 fault: open circuit\n");
        } else if (raw & 0x00000002) {
            fprintf(stderr, "MAX31855 fault: short to GND\n");
        } else if (raw & 0x00000001) {
            fprintf(stderr, "MAX31855 fault: short to VCC\n");
        } else {
            fprintf(stderr, "MAX31855 fault: unknown\n");
        }
        return -2;
    }

    int16_t thermocouple_raw = (int16_t)((raw >> 18) & 0x3FFF);
    if (thermocouple_raw & 0x2000) {
        thermocouple_raw |= 0xC000;
    }
    *temp_c = thermocouple_raw * 0.25f;
    return 0;
}

static int set_heater_duty(int duty) {
    if (duty < 0) duty = 0;
    if (duty > MAX_DUTY_CYCLE) duty = MAX_DUTY_CYCLE;
    if (gpioPWM(HEATER_GPIO, duty) < 0) {
        fprintf(stderr, "gpioPWM failed\n");
        return -1;
    }
    return 0;
}

static void log_data(float temp, int duty) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%d\n", ts, temp, duty);
    fflush(log_file);
}

int main(void) {
    float target_temp = DEFAULT_TARGET_TEMP;
    float Kp = 1.0f, Ki = 0.1f;
    float integral = 0.0f;
    int last_error = 0;
    int last_duty = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return 1;
    }
    gpioPWM(HEATER_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "fopen failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Temperature_C,Duty_Cycle\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting heater control (target=%.1f°C). Ctrl+C to exit.\n", target_temp);

    while (running) {
        float temp;
        int rc = read_max31855(spi_handle, &temp);

        if (rc == 0) {
            float error = target_temp - temp;
            integral += error;

            int duty = (int)(Kp * error + Ki * integral);
            if (duty < 0) duty = 0;
            if (duty > MAX_DUTY_CYCLE) duty = MAX_DUTY_CYCLE;

            if (duty != last_duty) {
                if (set_heater_duty(duty) == 0) {
                    last_duty = duty;
                }
            }

            log_data(temp, duty);
            printf("T=%.2f°C  duty=%d\n", temp, duty);
        } else {
            fprintf(stderr, "Sensor read failed (rc=%d). Heater OFF.\n", rc);
            if (set_heater_duty(0) != 0) {
                fprintf(stderr, "Failed to turn off heater.\n");
            }
            log_data(-999.0f, 0);
        }

        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    gpioPWM(HEATER_GPIO, 0);
    spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

