#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define PWM_RANGE 255
#define POLL_US   500000  /* 0.5 s */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read CPU temperature in millidegrees Celsius from the sysfs file.
 * Returns 0 on success and stores the value in *out_temp; returns -1 on error.
 */
static int read_cpu_temp(int *out_temp)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: error closing %s: %s\n", TEMP_FILE, strerror(errno));
        /* Non-fatal: we already got the value */
    }

    if (temp < 0 || temp > 200000) {
        fprintf(stderr, "Temperature out of plausible range: %d m°C\n", temp);
        return -1;
    }

    *out_temp = temp;
    return 0;
}

/*
 * Set the RGB LED color using hardware PWM.
 * Common-anode LED: duty 255 = off, duty 0 = fully on.
 * So we invert the desired brightness (0-255) before calling gpioPWM.
 */
static void set_led_color(int r, int g, int b)
{
    gpioPWM(RED_PIN,   PWM_RANGE - r);
    gpioPWM(GREEN_PIN, PWM_RANGE - g);
    gpioPWM(BLUE_PIN,  PWM_RANGE - b);
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins as hardware PWM outputs --- */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
