#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define DHT22_TIMEOUT_US 100000
#define DHT22_START_LOW_US 1000
#define DHT22_START_HIGH_US 30
#define DHT22_READ_TIMEOUT_US 1000
#define DHT22_BIT_THRESHOLD 50

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    float temperature;
    float humidity;
    int valid;
} DHT22Data;

int read_dht22(int gpio, DHT22Data *data) {
    data->temperature = -999.0f;
    data->humidity = -999.0f;
    data->valid = 0;

    uint8_t bits[40] = {0};
    int bit_idx = 0;
    int last_state = PI_HIGH;
    int timeout = 0;

    // Send start signal
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, PI_LOW);
    gpioDelay(DHT22_START_LOW_US);
    gpioWrite(gpio, PI_HIGH);
    gpioDelay(DHT22_START_HIGH_US);
    gpioSetMode(gpio, PI_INPUT);

    // Wait for sensor response
    timeout = 0;
    while (gpioRead(gpio) == PI_HIGH) {
        gpioDelay(1);
        timeout++;
        if (timeout > DHT22_TIMEOUT_US) return -1;
    }
    timeout = 0;
    while (gpioRead(gpio) == PI_LOW) {
        gpioDelay(1);
        timeout++;
        if (timeout > DHT22_TIMEOUT_US) return -1;
    }
    timeout = 0;
    while (gpioRead(gpio) == PI_HIGH) {
        gpioDelay(1);
        timeout++;
        if (timeout > DHT22_TIMEOUT_US) return -1;
    }

    // Read 40 bits
    for (bit_idx = 0; bit_idx < 40; bit_idx++) {
        timeout = 0;
        while (gpioRead(gpio) == PI_LOW) {
            gpioDelay(1);
            timeout++;
            if (timeout > DHT22_TIMEOUT_US) return -1;
        }
        timeout = 0;
        while (gpioRead(gpio) == PI_HIGH) {
            gpioDelay(1);
            timeout++;
            if (timeout > DHT22_TIMEOUT_US) return -1;
        }
        bits[bit_idx] = (timeout > DHT22_BIT_THRESHOLD) ? 1 : 0;
    }

    // Validate checksum
    uint8_t checksum = (bits[0] + bits[1] + bits[2] + bits[3]) & 0xFF;
    if (checksum != bits[4]) return -1;

    // Parse data
    uint16_t raw_humidity = (bits[0] << 8) | bits[1];
    uint16_t raw_temp = (bits[2] << 8) | bits[3];
    data->humidity = (float)raw_humidity / 10.0f;
    data->temperature = (float)raw_temp / 10.0f;
    if (raw_temp & 0x8000) data->temperature = -data->temperature;
    data->valid = 1;
    return 0;
}

int post_data(const char *url, float temperature, float humidity) {
    char payload[256];
    snprintf(payload, sizeof(payload),
             "{\"temperature\": %.1f, \"humidity\": %.1f}",
             temperature, humidity);

    CURL *curl = curl_easy_init();
    if (!curl) return -1;

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, payload);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    CURLcode res = curl_easy_perform(curl);
    int ret = 0;
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        ret = -1;
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return ret;
}

int main() {
    const char *url = "http://yourserver.com/api/humidity";

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    while (running) {
        DHT22Data data;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_dht22(DHT22_GPIO, &data) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "DHT22 read failed (attempt %d/%d)\n", attempt + 1, MAX_RETRIES);
            gpioDelay(2000000);
        }

        if (success) {
            if (post_data(url, data.temperature, data.humidity) != 0) {
                fprintf(stderr, "HTTP POST failed\n");
            } else {
                printf("Temperature: %.1f C, Humidity: %.1f %%\n",
                       data.temperature, data.humidity);
            }
        } else {
            fprintf(stderr, "DHT22 read failed after %d attempts\n", MAX_RETRIES);
        }

        gpioDelay(60000000);
    }

    gpioTerminate();
    return 0;
}

