#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <getopt.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_PIN 4
#define DEFAULT_SERVER_URL "http://your-server.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_SEC 2
#define READ_INTERVAL_SEC 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_msg(int priority, const char *msg) {
    syslog(priority, "%s", msg);
    fprintf(stderr, "%s\n", msg);
}

static int read_dht22(int pin, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    uint32_t tick;
    int i, j;

    /* Start signal: pull low for >= 1 ms, then high for 20-40 us, then release */
    gpioSetMode(pin, PI_OUTPUT);
    gpioWrite(pin, 0);
    gpioDelay(2000); /* 2 ms low */
    gpioWrite(pin, 1);
    gpioDelay(30);  /* 30 us high */
    gpioWrite(pin, 0);
    gpioSetMode(pin, PI_INPUT);

    /* Wait for sensor response: low ~80 us, high ~80 us */
    tick = gpioTick();
    while (gpioRead(pin) == 1) {
        if (gpioTick() - tick > 1000) return -1;
    }
    tick = gpioTick();
    while (gpioRead(pin) == 0) {
        if (gpioTick() - tick > 1000) return -1;
    }
    tick = gpioTick();
    while (gpioRead(pin) == 1) {
        if (gpioTick() - tick > 1000) return -1;
    }

    /* Read 40 bits */
    for (i = 0; i < 40; i++) {
        /* Wait for low-to-high transition (end of ~50 us low pulse) */
        tick = gpioTick();
        while (gpioRead(pin) == 0) {
            if (gpioTick() - tick > 1000) return -1;
        }
        /* Measure high pulse width: ~26-28 us = '0', ~70 us = '1' */
        tick = gpioTick();
        while (gpioRead(pin) == 1) {
            if (gpioTick() - tick > 1000) return -1;
        }
        uint32_t width = gpioTick() - tick;
        data[i / 8] <<= 1;
        if (width > 50) {
            data[i / 8] |= 1;
        }
    }

    /* Checksum */
    int checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
    if (checksum != data[4]) {
        return -2;
    }

    *humidity = (float)((data[0] << 8) | data[1]) / 10.0f;
    return 0;
}

static int post_humidity(const char *url, float humidity) {
    CURL *curl = NULL;
    CURLcode res;
    char json[128];
    int attempt;

    snprintf(json, sizeof(json), "{\"humidity\": %.1f}", humidity);

    for (attempt = 0; attempt < MAX_RETRIES; attempt++) {
        curl = curl_easy_init();
        if (!curl) {
            log_msg(LOG_ERR, "curl_easy_init() failed");
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json));
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
        curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            char buf[256];
            snprintf(buf, sizeof(buf), "curl_easy_perform() failed: %s", curl_easy_strerror(res));
            log_msg(LOG_ERR, buf);
            curl_easy_cleanup(curl);
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        long http_code = 0;
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
        if (http_code < 200 || http_code >= 300) {
            char buf[256];
            snprintf(buf, sizeof(buf), "HTTP error: %ld", http_code);
            log_msg(LOG_ERR, buf);
            curl_easy_cleanup(curl);
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        curl_easy_cleanup(curl);
        return 0;
    }

    log_msg(LOG_ERR, "Failed to POST humidity after 3 retries");
    return -1;
}

int main(int argc, char *argv[]) {
    const char *server_url = DEFAULT_SERVER_URL;
    int opt;

    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                server_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s server_url]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);
    log_msg(LOG_INFO, "Starting DHT22 monitor on BCM GPIO 4");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        log_msg(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    curl_global_init(CURL_GLOBAL_DEFAULT);

    while (running) {
        float humidity = 0.0f;
        int rc = read_dht22(DHT22_PIN, &humidity);

        if (rc == 0) {
            if (post_humidity(server_url, humidity) != 0) {
                log_msg(LOG_ERR, "Failed to POST humidity");
            } else {
                log_msg(LOG_INFO, "Humidity posted: %.1f%%", humidity);
            }
        } else if (rc == -2) {
            log_msg(LOG_ERR, "DHT22 checksum error");
        } else {
            log_msg(LOG_ERR, "DHT22 read error (sensor absent or bus error)");
        }

        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    log_msg(LOG_INFO, "Shutting down");
    gpioTerminate();
    curl_global_cleanup();
    closelog();
    return EXIT_SUCCESS;
}

