#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define CPU_TEMP_PATH "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_PATH "/sys/class/thermal/cooling_device0/cur_state"
#define MAX_STATE_PATH "/sys/class/thermal/cooling_device0/max_state"
#define LOG_PATH "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(CPU_TEMP_PATH, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", CPU_TEMP_PATH, strerror(errno));
        return -1;
    }
    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading CPU temperature: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp;
}

static int write_fan_state(int state) {
    FILE *fp = fopen(FAN_STATE_PATH, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_STATE_PATH, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", state) < 0) {
        fprintf(stderr, "Error writing fan state: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int read_max_state(void) {
    FILE *fp = fopen(MAX_STATE_PATH, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", MAX_STATE_PATH, strerror(errno));
        return -1;
