#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_FLAGS 0

#define MAX31855_FAULT_OPEN_CIRCUIT 0x01
#define MAX31855_FAULT_SHORT_GND 0x02
#define MAX31855_FAULT_SHORT_VCC 0x04

#define DEFAULT_KP 1.0
#define DEFAULT_KI 0.1
#define DEFAULT_KD 0.01
#define DEFAULT_TARGET_TEMP 50.0
#define DEFAULT_LOG_INTERVAL 1.0

#define HEATER_PWM_FREQ 1000
#define HEATER_PWM_RANGE 100

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static double kp = DEFAULT_KP;
static double ki = DEFAULT_KI;
static double kd = DEFAULT_KD;
static double target_temp = DEFAULT_TARGET_TEMP;
static double integral = 0.0;
static double last_error = 0.0;
static double last_time = 0.0;
static double log_interval = DEFAULT_LOG_INTERVAL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", ts, msg);
    fflush(log_file);
}

static int read_max31855(int handle, float *temp_c) {
    char buf[4] = {0};
    int ret = spiRead(handle, buf, 4);
    if (ret != 4) {
        log_message("SPI read error");
        return -1;
    }
    uint32_t raw = ((uint32_t)(uint8_t)buf[0] << 24) |
                   ((uint32_t)(uint8_t)buf[1] << 16) |
                   ((uint32_t)(uint8_t)buf[2] << 8)  |
                   ((uint32_t)(uint8_t)buf[3]);
    if (raw & 0x00010000) {
        if (raw & MAX31855_FAULT_OPEN_CIRCUIT) log_message("Thermocouple open circuit");
        if (raw & MAX31855_FAULT_SHORT_GND) log_message("Thermocouple short to GND");
        if (raw & MAX31855_FAULT_SHORT_VCC) log_message("Thermocouple short to VCC");
        return -2;
    }
    int16_t thermocouple_raw = (int16_t)(raw >> 18);
    *temp_c = thermocouple_raw * 0.25;
    return 0;
}

static void set_heater_pwm(int duty) {
    if (duty < 0) duty = 0;
    if (duty > 100) duty = 100;
    gpioPWM(HEATER_GPIO, duty);
}

static double calculate_pid(double current_temp, double target) {
    double error = target - current_temp;
    double dt = time_time() - last_time;
    if (dt <= 0.0) dt = 0.01;
    integral += error * dt;
    double derivative = (error - last_error) / dt;
    double output = kp * error + ki * integral + kd * derivative;
    last_error = error;
    last_time = time_time();
    return output;
}

static void cleanup(void) {
    set_heater_pwm(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        log_message("Program terminated");
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, HEATER_PWM_FREQ);
    gpioSetPWMrange(HEATER_GPIO, HEATER_PWM_RANGE);
    set_heater_pwm(0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("heater_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Log file open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Program started");

    while (running) {
        float temp;
        int rc = read_max31855(spi_handle, &temp);
        if (rc == 0) {
            double pid_out = calculate_pid((double)temp, target_temp);
            int duty = (int)pid_out;
            if (duty < 0) duty = 0;
            if (duty > 100) duty = 100;
            set_heater_pwm(duty);
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s, Temp: %.2f, Duty: %d, PID: %.2f\n", ts, temp, duty, pid_out);
            fflush(log_file);
            if (temp > 100.0 || temp < 0.0) {
                log_message("Temperature out of range, heater disabled");
                set_heater_pwm(0);
            }
        } else if (rc == -2) {
            log_message("Thermocouple fault, heater disabled");
            set_heater_pwm(0);
            integral = 0.0;
            last_error = 0.0;
            last_time = time_time();
        }
        time_sleep(log_interval);
    }

    cleanup();
    return 0;
}

