#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"
#define PWM_FREQUENCY 25000
#define MIN_TEMP 40000
#define MAX_TEMP 70000
#define POLL_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("Error opening temperature file");
        return -1;
    }
    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp_milli;
}

static int calculate_duty_cycle(int temp_milli) {
    if (temp_milli <= MIN_TEMP) return 0;
    if (temp_milli >= MAX_TEMP) return 100;
    return (int)(((float)(temp_milli - MIN_TEMP) / (MAX_TEMP - MIN_TEMP)) * 100.0f);
}

static int set_fan_speed(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;
    int range = 255;
    int pwm_value = (duty_cycle * range) / 100;
    if (gpioPWM(FAN_GPIO, pwm_value) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }
    return 0;
}

static int log_data(int temp_milli, int duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%d,%.2f\n", timestamp, temp_milli / 1000, duty_cycle);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error setting PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Error initializing PWM duty cycle\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handlers");
        gpioPWM(FAN_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    if (fp == NULL) {
        fp = fopen(LOG_FILE, "w");
        if (fp) {
            fprintf(fp, "Timestamp,Temperature(C),DutyCycle(%%)\n");
            fclose(fp);
        } else {
            perror("Error creating log file");
            gpioPWM(FAN_GPIO, 0);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    } else {
        fclose(fp);
    }

    printf("CPU temperature monitoring and fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        int temp_milli = read_cpu_temp();
        if (temp_milli < 0) {
            fprintf(stderr, "Error reading CPU temperature, retrying in %d seconds...\n", POLL_INTERVAL);
            sleep(POLL_INTERVAL);
            continue;
        }

        int duty_cycle = calculate_duty_cycle(temp_milli);

        if (set_fan_speed(duty_cycle) != 0) {
            fprintf(stderr, "Error setting fan speed, retrying in %d seconds...\n", POLL_INTERVAL);
            sleep(POLL_INTERVAL);
            continue;
        }

        if (log_data(temp_milli, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data, retrying in %d seconds...\n", POLL_INTERVAL);
        }

        printf("Temperature: %d mC, Duty Cycle: %d%%\n", temp_milli, duty_cycle);
        sleep(POLL_INTERVAL);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
    printf("Fan stopped, pigpio terminated.\n");
