#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 18
#define PULSES_PER_REVOLUTION 360
#define LOG_FILE "encoder_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_A_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", SENSOR_A_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(SENSOR_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", SENSOR_B_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on GPIO%d.\n", SENSOR_A_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on GPIO%d.\n", SENSOR_B_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_sensor_state(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error: Failed to read GPIO%d.\n", pin);
        return -1;
    }
    return value;
}

static float calculate_angle(int current_state, int previous_state) {
    int a = read_sensor_state(SENSOR_A_PIN);
    int b = read_sensor_state(SENSOR_B_PIN);

    if (a < 0 || b < 0) {
        return -1.0f;
    }

    int current_quadrature = (a << 1) | b;
    int previous_quadrature = (previous_state >> 1) | (previous_state & 1);

    int delta = current_quadrature - previous_quadrature;

    if (delta == 1) {
        return 0.0f;
    } else if (delta == -3) {
        return 0.0f;
    } else if (delta == 3) {
        return 90.0f;
    } else if (delta == -1) {
        return 270.0f;
    } else {
        return -1.0f;
    }
}

static int log_data(float angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Error: Failed to get local time.\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error: Failed to format timestamp.\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, angle) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: Failed to close log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    int previous_state = (read_sensor_state(SENSOR_A_PIN) << 1) | read_sensor_state(SENSOR_B_PIN);
    if (previous_state < 0) {
        gpioTerminate();
        return 1;
    }

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float angle = calculate_angle(previous_state);

        if (angle >= 0.0f) {
            if (log_data(angle) != 0) {
                fprintf(stderr, "Warning: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Warning: Invalid quadrature transition.\n");
        }

        previous_state = (read_sensor_state(SENSOR_A_PIN) << 1) | read_sensor_state(SENSOR_B_PIN);

        if (previous_state < 0) {
            fprintf(stderr, "Error: Failed to read sensor state.\n");
            break;
        }

        gpioDelay(1000);
    }

    gpioTerminate();
    printf("\nEncoder monitoring stopped.\n");
    return 0;
}

