/*
 * ADPD144RI photometric sensor reader for Raspberry Pi 3 Model B+
 * Uses libgpiod for GPIO and Linux I2C character-device interface.
 *
 * Wiring:
 *   ADPD144RI SDA -> GPIO 2 (I2C bus 1 SDA)
 *   ADPD144RI SCL -> GPIO 3 (I2C bus 1 SCL)
 *   ADPD144RI VDD -> 3.3 V
 *   ADPD144RI GND -> GND
 *   LED anode -> GPIO 17 (via 330 ohm resistor) -> GND
 *
 * Build: gcc -O2 -Wall -o adpd144ri adpd144ri.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS         "/dev/i2c-1"
#define ADPD144RI_ADDR  0x39

#define REG_FIFO_DATA   0x60
#define REG_FIFO_CTRL   0x61
#define REG_MODE        0x00
#define REG_INT_EN      0x01
#define REG_INT_STATUS  0x02
#define REG_INT_CLR     0x03

#define GPIO_CHIP       "gpiochip0"
#define LED_PIN         17
#define IR_THRESHOLD    2000
#define SAMPLE_DELAY_MS 100

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int adpd144ri_init(int fd)
{
    /* Standby mode to allow configuration changes */
    if (i2c_write_reg8(fd, REG_MODE, 0x00) < 0)
        return -1;
    usleep(1000);

    /* Clear any pending interrupt */
    if (i2c_write_reg8(fd, REG_INT_CLR, 0x01) < 0)
        return -1;

    /* Enable FIFO data ready interrupt */
    if (i2c_write_reg8(fd, REG_INT_EN, 0x01) < 0)
        return -1;

    /* Start continuous conversion mode */
    if (i2c_write_reg8(fd, REG_MODE, 0x01) < 0)
        return -1;

    return 0;
}

static int adpd144ri_read(int fd, uint16_t *red, uint16_t *ir)
{
    if (i2c_read_reg16(fd, REG_FIFO_DATA, red) < 0)
        return -1;
    if (i2c_read_reg16(fd, REG_FIFO_DATA + 2, ir) < 0)
        return -1;
    return 0;
}

static void log_data(FILE *fp, uint16_t red, uint16_t ir)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, red, ir);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                ADPD144RI_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Probe sensor by reading FIFO_DATA */
    uint16_t probe;
    if (i2c_read_reg16(i2c_fd, REG_FIFO_DATA, &probe) < 0) {
        fprintf(stderr, "ADPD144RI not detected at address 0x%02X\n", ADPD144RI_ADDR);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (adpd144ri_init(i2c_fd) < 0) {
        fprintf(stderr, "ADPD144RI initialization failed\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open log file */
    FILE *log_fp = fopen("adpd144ri_log.txt", "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request LED line */
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        fclose(log_fp);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_fp);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led, "adpd144ri", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n",
                LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_fp);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("ADPD144RI monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t red, ir;
        if (adpd144ri_read(i2c_fd, &red, &ir) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
            usleep(SAMPLE_DELAY_MS * 1000);
            continue;
        }

        log_data(log_fp, red, ir);

        int led_state = (ir > IR_THRESHOLD) ? 1 : 0;
        if (gpiod_line_set_value(led, led_state) < 0) {
            fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
        }

        usleep(SAMPLE_DELAY_MS * 1000);
    }

    /* Cleanup */
    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    fclose(log_fp);
    close(i2c_fd);

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

