#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x70
#define REG_STATE      0x00
#define LOG_FILE       "air_quality_log.csv"
#define SAMPLE_PERIOD  5.0
#define READ_BYTES     7

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

static int initialize(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return -1;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    fprintf(g_log_file, "Timestamp,IAQ,TVOC,eCO2\n");
    fflush(g_log_file);

    return 0;
}

static int read_sensor_data(uint8_t *data)
{
    int bytes_read = i2cReadI2CBlockData(g_i2c_handle, REG_STATE,
                                         (char *)data, READ_BYTES);
    if (bytes_read != READ_BYTES) {
        fprintf(stderr, "Error: I2C read returned %d bytes (expected %d).\n",
                bytes_read, READ_BYTES);
        return -1;
    }
    return 0;
}

static int process_sensor_data(const uint8_t *data,
                               int *tvoc, int *eco2)
{
    uint16_t tvoc_raw = ((uint16_t)data[1] << 8) | data[2];
    uint16_t eco2_raw = ((uint16_t)data[5] << 8) | data[6];

    if (tvoc_raw == 0xFFFF) {
        fprintf(stderr, "Warning: sensor reports TVOC=0xFFFF (invalid).\n");
        *tvoc = 0;
    } else {
        *tvoc = (int)tvoc_raw;
    }

    if (eco2_raw == 0xFFFF) {
        fprintf(stderr, "Warning: sensor reports eCO2=0xFFFF (invalid).\n");
        *eco2 = 0;
    } else {
        *eco2 = (int)eco2_raw;
    }
    return 0;
}

static int calculate_iaq(int tvoc, int eco2)
{
    double tvoc_contrib = (double)tvoc / 10.0;
    double eco2_contrib = (double)(eco2 - 400) / 50.0;
    double iaq = 100.0 - tvoc_contrib - eco2_contrib;

    if (iaq < 0.0)   iaq = 0.0;
    if (iaq > 100.0) iaq = 100.0;
    return (int)iaq;
}

static int log_data(int iaq, int tvoc, int eco2)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s,%d,%d,%d\n", timestamp, iaq, tvoc, eco2) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed.\n");
        return -1;
    }
    fflush(g_log_file);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize() != 0) {
        return 1;
    }

    uint8_t sensor_data[READ_BYTES];
    int tvoc, eco2, iaq;

    while (g_running) {
        if (read_sensor_data(sensor_data) == 0) {
            if (process_sensor_data(sensor_data, &tvoc, &eco2) == 0) {
                iaq = calculate_iaq(tvoc, eco2);
                if (log_data(iaq, tvoc, eco2) != 0) {
                    fprintf(stderr, "Warning: logging failed.\n");
                }
            }
        } else {
            fprintf(stderr, "Warning: sensor read failed; will retry next cycle.\n");
        }

        time_sleep(SAMPLE_PERIOD);
    }

    cleanup();
    return 0;
}

