#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>
#include <gpiod.h>

#define I2S_DEVICE "/dev/snd/pcmC0D0c"
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17
#define SAMPLE_RATE 48000
#define BITS_PER_SAMPLE 24
#define PCM_FILE "audio_capture.pcm"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2s_init(int *fd) {
    int ret;
    unsigned int channels = 2;
    unsigned int rate = SAMPLE_RATE;
    unsigned int f_rate = 0;
    unsigned int bits = BITS_PER_SAMPLE;
    unsigned int bps = 0;
    unsigned int pad = 0;
    unsigned int delay = 0;
    unsigned int start_delay = 0;
    unsigned int stop_delay = 0;
    unsigned int channels_delay = 0;
    unsigned int mode = PCM_MODE_DATA;

    ret = snd_card_next(NULL, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to get default card: %s\n", strerror(-ret));
        return -1;
    }

    ret = snd_card_get_longname(0, NULL, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to get card name: %s\n", strerror(-ret));
        return -1;
    }

    ret = snd_pcm_open(fd, I2S_DEVICE, mode, 0);
    if (ret < 0) {
