#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18
#define PWM_FREQUENCY 100
#define PWM_RANGE 255
#define DEBOUNCE_DELAY_US 50000
#define POLL_INTERVAL_US 50000
#define MAX_FLAME_DURATION_MS 1000
#define LOG_FILE "flame_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s %s\n", ts, message);
    } else {
        fprintf(fp, "(time-error) %s\n", message);
    }
    fclose(fp);
}

static int read_flame_sensor(void) {
    int v = gpioRead(FLAME_SENSOR_PIN);
    if (v < 0) {
        log_event("ERROR: gpioRead failed on flame sensor");
        return -1;
    }
    return (v == 0) ? 1 : 0;
}

static void set_fan_speed(int flame_duration_ms) {
    if (flame_duration_ms <= 0) {
        gpioPWM(FAN_PIN, 0);
        return;
    }
    double normalized = (double)flame_duration_ms / MAX_FLAME_DURATION_MS;
    if (normalized > 1.0) normalized = 1.0;
    double duty = 80.0 * pow(normalized, 2.0);
    int pwm = (int)(duty / 100.0 * PWM_RANGE);
    if (pwm < 0) pwm = 0;
    if (pwm > PWM_RANGE) pwm = PWM_RANGE;
    gpioPWM(FAN_PIN, pwm);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(FAN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set fan pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(FAN_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("System started");

    int last_state = 0;
    uint32_t flame_start_tick = 0;
    int flame_active = 0;

    while (running) {
        int flame = read_flame_sensor();
        if (flame < 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (flame && !last_state) {
            flame_start_tick = gpioTick();
            flame_active = 1;
            log_event("Flame detected");
        } else if (!flame && last_state) {
            flame_active = 0;
            log_event("Flame ended");
        }

        if (flame_active) {
            uint32_t now = gpioTick();
            uint32_t elapsed_ms = (now - flame_start_tick) / 1000;
            if (elapsed_ms > MAX_FLAME_DURATION_MS) {
                set_fan_speed(MAX_FLAME_DURATION_MS);
            } else {
                set_fan_speed((int)elapsed_ms);
            }
        } else {
            set_fan_speed(0);
        }

        last_state = flame;
        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("System shutting down");
    gpioPWM(FAN_PIN, 0);
    gpioWrite(FLAME_SENSOR_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

