#define START_FREQUENCY 77.0
#define END_FREQUENCY 79.0
#define NUM_CHIRPS 64
#define NUM_SAMPLES 256
#define FRAME_PERIOD_MS 100

typedef struct {
    uint32_t magic_number;
    uint64_t timestamp;
    float start_frequency;
    float end_frequency;
    int num_chirps;
    int num_samples;
    int frame_period_ms;
} RadarConfig;

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_gpio(void) {
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        return -1;
    }
    if (gpioSetMode(DATA_READY_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set data ready pin mode\n");
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize trigger pin state\n");
        return -1;
    }
    return 0;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d: %d\n", SPI_CHANNEL, spi_handle);
        return -1;
    }
    return 0;
}

static int init_log_file(void) {
    log_file = fopen(LOG_FILE, "wb");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return -1;
    }
    RadarConfig config;
    config.magic_number = MAGIC_NUMBER;
    config.timestamp = 0;
    config.start_frequency = START_FREQUENCY;
    config.end_frequency = END_FREQUENCY;
    config.num_chirps = NUM_CHIRPS;
    config.num_samples = NUM_SAMPLES;
    config.frame_period_ms = FRAME_PERIOD_MS;
    if (fwrite(&config, sizeof(config), 1, log_file) != 1) {
        perror("Failed to write log file header");
        fclose(log_file);
        log_file = NULL;
        return -1;
    }
    fflush(log_file);
    return 0;
}

static int read_heatmap(uint16_t *heatmap) {
    char tx_buf[FRAME_SIZE];
    char rx_buf[FRAME_SIZE];
    memset(tx_buf, 0, FRAME_SIZE);
    memset(rx_buf, 0, FRAME_SIZE);
    int result = spiXfer(spi_handle, tx_buf, rx_buf, FRAME_SIZE);
    if (result != FRAME_SIZE) {
        fprintf(stderr, "SPI transfer failed: expected %d bytes, got %d\n", FRAME_SIZE, result);
        return -1;
    }
    memcpy(heatmap, rx_buf, FRAME_SIZE);
    return 0;
}

static int log_frame(uint16_t *heatmap, int frame_number) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime failed");
        return -1;
    }
    uint64_t timestamp = (uint64_t)ts.tv_sec * 1000 + (uint64_t)ts.tv_nsec / 1000000;
    if (fprintf(log_file, "%llu,%d,", (unsigned long long)timestamp, frame_number) < 0) {
        perror("fprintf failed");
        return -1;
    }
    for (int i = 0; i < HEATMAP_SIZE; i++) {
        if (fprintf(log_file, "%u,", heatmap[i]) < 0) {
            perror("fprintf failed");
            return -1;
        }
    }
    if (fprintf(log_file, "\n") < 0) {
        perror("fprintf failed");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }
    if (init_gpio() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (init_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (init_log_file() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        cleanup();
        return EXIT_FAILURE;
    }
    uint16_t *heatmap = malloc(FRAME_SIZE);
    if (heatmap == NULL) {
        perror("malloc failed");
        cleanup();
        return EXIT_FAILURE;
    }
    int frame_number = 0;
    while (!terminate) {
        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Failed to assert trigger\n");
            break;
        }
        gpioDelay(1000);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Failed to deassert trigger\n");
            break;
        }
        int timeout = 0;
        while (!terminate && !gpioRead(DATA_READY_PIN)) {
            gpioDelay(1000);
            timeout += 1000;
            if (timeout > 5000000) {
                fprintf(stderr, "Timeout waiting for data ready\n");
                break;
            }
        }
        if (terminate) break;
        if (read_heatmap(heatmap) != 0) {
            fprintf(stderr, "Failed to read heatmap\n");
            break;
        }
        if (log_frame(heatmap, frame_number) != 0) {
            fprintf(stderr, "Failed to log frame\n");
            break;
        }
        frame_number++;
        gpioDelay(FRAME_PERIOD_MS * 1000);
    }
    free(heatmap);
    cleanup();
    return EXIT_SUCCESS;
}

