#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define OPT3001_ADDR 0x44
#define I2C_BUS 1
#define LOG_FILE "light_data.txt"
#define SAMPLE_INTERVAL_US 1000000

/* OPT3001 register addresses */
#define REG_RESULT 0x00
#define REG_CONFIG 0x01

/* Configuration register bits */
#define CFG_AUTO_RANGE 0x0001
#define CFG_CONV_TIME_100MS 0x0000
#define CFG_CONTINUOUS 0x0000
#define CFG_RESET 0x0004

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static int opt3001_write_config(int handle) {
    uint16_t config = CFG_AUTO_RANGE | CFG_CONTINUOUS | CFG_CONV_TIME_100MS;
    char buf[3];
    buf[0] = REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Error: Failed to write OPT3001 config register.\n");
        return -1;
    }
    return 0;
}

static int opt3001_read_result(int handle, uint16_t *result) {
    char reg = REG_RESULT;
    char data[2];

    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: Failed to set result register pointer.\n");
        return -1;
    }

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read result register.\n");
        return -1;
    }

    *result = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static float calculate_lux(uint16_t raw) {
    uint16_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;
    return 0.01f * (float)(1 << exponent) * (float)mantissa;
}

static void log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, lux);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
