    /* --- Main polling loop --- */
    while (g_running) {
        int level = gpioRead(TILT_SENSOR_GPIO);

        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed for GPIO %d (code %d).\n",
                    TILT_SENSOR_GPIO, level);
            break;
        }

        if (level != last_state) {
            print_timestamp();
            if (level == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }
            fflush(stdout);
            last_state = level;
        }

        usleep(POLL_INTERVAL_US);
    }

    /* --- Clean shutdown --- */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

