#include <string.h>
#include <unistd.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 Register Addresses
#define SI1145_REG_PARTID 0x00
#define SI1145_REG_REVID 0x01
#define SI1145_REG_SEQID 0x02
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_UV_INDEX0 0x2C
#define SI1145_REG_UV_INDEX1 0x2D
#define SI1145_REG_COMMAND 0x46
#define SI1145_REG_CHLIST 0x01

// Si1145 Commands
#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_ALS_FORCE 0x06

// Expected PART ID
#define SI1145_PART_ID 0x45

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float uv_index;
    int als_visible;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Function to initialize the Si1145 sensor
int si1145_init(int handle) {
    int ret;

    // Reset the sensor
    ret = i2cWriteByteData(handle, SI1145_REG_COMMAND, SI1145_CMD_RESET);
    if (ret < 0) {
        fprintf(stderr, "Error resetting Si1145: %d\n", ret);
        return -1;
    }
    gpioDelay(10000); // 10ms delay for reset

    // Verify PART ID
    int part_id = i2cReadByteData(handle, SI1145_REG_PARTID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART ID: %d\n", part_id);
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }

    // Write HW_KEY
    ret = i2cWriteByteData(handle, SI1145_REG_HW_KEY, 0x17);
    if (ret < 0) {
        fprintf(stderr, "Error writing HW_KEY: %d\n", ret);
        return -1;
    }

    // Configure CHLIST: Enable UV and ALS_VIS
    ret = i2cWriteByteData(handle, SI1145_REG_CHLIST, 0x81); // UV_EN | ALS_VIS_EN
    if (ret < 0) {
        fprintf(stderr, "Error writing CHLIST: %d\n", ret);
        return -1;
    }

    // Set measurement rate to 0 (manual mode)
    ret = i2cWriteByteData(handle, SI1145_REG_MEAS_RATE0, 0x00);
    if (ret < 0) {
        fprintf(stderr, "Error writing MEAS_RATE0: %d\n", ret);
        return -1;
    }
    ret = i2cWriteByteData(handle, SI1145_REG_MEAS_RATE1, 0x00);
    if (ret < 0) {
        fprintf(stderr, "Error writing MEAS_RATE1: %d\n", ret);
        return -1;
    }

    return 0;
}

// Function to read UV index and ALS data from the Si1145 sensor
int si1145_read_data(int handle, sensor_data_t *data) {
    int ret;
    int uv_low, uv_high, als_low, als_high;

    // Trigger ALS measurement
    ret = i2cWriteByteData(handle, SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE);
    if (ret < 0) {
        fprintf(stderr, "Error triggering ALS measurement: %d\n", ret);
        return -1;
    }
    gpioDelay(10000); // 10ms delay for measurement

    // Read UV index (2 bytes)
    uv_low = i2cReadByteData(handle, SI1145_REG_UV_INDEX0);
    if (uv_low < 0) {
        fprintf(stderr, "Error reading UV index low byte: %d\n", uv_low);
        return -1;
    }
    uv_high = i2cReadByteData(handle, SI1145_REG_UV_INDEX1);
    if (uv_high < 0) {
        fprintf(stderr, "Error reading UV index high byte: %d\n", uv_high);
        return -1;
    }
    data->uv_index = (float)((uv_high << 8) | uv_low);

    // Read ALS visible (2 bytes)
    als_low = i2cReadByteData(handle, SI1145_REG_ALS_VIS_DATA0);
    if (als_low < 0) {
        fprintf(stderr, "Error reading ALS visible low byte: %d\n", als_low);
        return -1;
    }
    als_high = i2cReadByteData(handle, SI1145_REG_ALS_VIS_DATA1);
    if (als_high < 0) {
        fprintf(stderr, "Error reading ALS visible high byte: %d\n", als_high);
        return -1;
    }
    data->als_visible = (als_high << 8) | als_low;

    return 0;
}

// Function to log data to a CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, data.uv_index, data.als_visible);
    fflush(log_file);
}

int main() {
    sensor_data_t sensor_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Si1145 sensor
    if (si1145_init(i2c_handle) < 0) {
        fprintf(stderr, "Si1145 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (si1145_read_data(i2c_handle, &sensor_data) == 0) {
            // Print data to console
            printf("UV Index: %.2f, ALS Visible: %d\n", sensor_data.uv_index, sensor_data.als_visible);

            // Log data to file
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup
    printf("\nCleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

