#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR1_ADDR   0x36
#define SENSOR2_ADDR   0x37
#define FLOW_REG       0x00
#define CMD_REG        0x08
#define START_MEAS_CMD 0x3608
#define FLOW_SCALE     0.036f
#define ALARM_GPIO     17
#define ALARM_THRESHOLD 0.5f
#define LOG_FILE       "flow_log.txt"
#define POLL_INTERVAL  1

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Sensirion 8-bit CRC: polynomial 0x31, initial value 0xFF */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t reg, uint16_t cmd) {
    uint8_t buf[3] = { reg, (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static float read_flow_rate(int fd) {
    uint8_t buf[9];
    if (i2c_read_data(fd, FLOW_REG, buf, sizeof(buf)) != 0)
        return -1.0f;

    /* Validate CRC for each 3-byte measurement */
    for (int i = 0; i < 3; i++) {
        if (sensirion_crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on measurement %d\n", i);
            return -1.0f;
        }
    }

    int16_t raw_flow = (int16_t)((buf[0] << 8) | buf[1]);
    return (float)raw_flow * FLOW_SCALE;
}

static void log_flow_rates(FILE *fp, float f1, float f2, float avg) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min, Average: %.2f ml/min\n",
            ts, f1, f2, avg);
    fflush(fp);
}

int main(void) {
    struct sigaction sa = { .sa_handler = sig_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd1 = open(I2C_BUS, O_RDWR);
    if (fd1 < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(fd1, I2C_SLAVE, SENSOR1_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", SENSOR1_ADDR, strerror(errno));
        close(fd1);
        return 1;
    }

    int fd2 = open(I2C_BUS, O_RDWR);
    if (fd2 < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        close(fd1);
        return 1;
    }
    if (ioctl(fd2, I2C_SLAVE, SENSOR2_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", SENSOR2_ADDR, strerror(errno));
        close(fd1);
        close(fd2);
        return 1;
    }

    /* Start continuous measurement on both sensors */
    if (i2c_write_cmd(fd1, CMD_REG, START_MEAS_CMD) != 0 ||
        i2c_write_cmd(fd2, CMD_REG, START_MEAS_CMD) != 0) {
        fprintf(stderr, "Failed to start measurement on one or both sensors\n");
        close(fd1);
        close(fd2);
        return 1;
    }
    usleep(100000); /* 100 ms for first measurement */

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        close(fd1);
        close(fd2);
        return 1;
    }
    struct gpiod_line *alarm_line = gpiod_chip_get_line(chip, ALARM_GPIO);
    if (!alarm_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", ALARM_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        close(fd1);
        close(fd2);
        return 1;
    }
    if (gpiod_line_request_output(alarm_line, "flow_alarm", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", ALARM_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        close(fd1);
        close(fd2);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        close(fd1);
        close(fd2);
        return 1;
    }

    while (running) {
        float f1 = read_flow_rate(fd1);
        float f2 = read_flow_rate(fd2);

        if (f1 < 0.0f || f2 < 0.0f) {
            fprintf(stderr, "Error reading flow rates, skipping cycle\n");
        } else {
            float avg = (f1 + f2) / 2.0f;
            log_flow_rates(fp, f1, f2, avg);

            int alarm_state = (avg < ALARM_THRESHOLD) ? 1 : 0;
            if (gpiod_line_set_value(alarm_line, alarm_state) < 0) {
                fprintf(stderr, "Failed to set alarm GPIO: %s\n", strerror(errno));
            }
        }

        sleep(POLL_INTERVAL);
    }

    /* Cleanup */
    gpiod_line_set_value(alarm_line, 0);
    gpiod_line_release(alarm_line);
    gpiod_chip_close(chip);
    fclose(fp);
    close(fd1);
    close(fd2);
    return 0;
}

