#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x55
#define D7S_REG_MODE   0x1D
#define D7S_REG_STATUS 0x1B
#define D7S_REG_X_LSB  0x2A
#define D7S_REG_X_MSB  0x2B
#define D7S_REG_Y_LSB  0x2C
#define D7S_REG_Y_MSB  0x2D
#define D7S_REG_Z_LSB  0x2E
#define D7S_REG_Z_MSB  0x2F
#define D7S_MODE_ACTIVE 0x10
#define D7S_STATUS_ACTIVE 0x01
#define SCALE_FACTOR   0.0009765625f
#define SAMPLE_PERIOD_US 500000
#define ACTIVATE_TIMEOUT_S 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

static void sighandler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int i2c_read_reg16_le(int fd, uint8_t reg_lsb, int16_t *out) {
    uint8_t lsb, msb;
    if (i2c_read_reg8(fd, reg_lsb, &lsb) < 0) return -1;
    if (i2c_read_reg8(fd, reg_lsb + 1, &msb) < 0) return -1;
    *out = (int16_t)((msb << 8) | lsb);
    return 0;
}

static int d7s_init(int fd) {
    if (i2c_write_reg8(fd, D7S_REG_MODE, D7S_MODE_ACTIVE) < 0) return -1;
    for (int i = 0; i < ACTIVATE_TIMEOUT_S * 10; i++) {
        uint8_t status;
        if (i2c_read_reg8(fd, D7S_REG_STATUS, &status) < 0) return -1;
        if (status & D7S_STATUS_ACTIVE) return 0;
        usleep(100000);
    }
    fprintf(stderr, "D7S did not become active within %d s\n", ACTIVATE_TIMEOUT_S);
    return -1;
}

static void log_sample(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.6f,%.6f,%.6f\n", ts, x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", D7S_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (d7s_init(g_i2c_fd) < 0) {
        fprintf(stderr, "D7S initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }

    g_csv = fopen("fan_health.csv", "a");
    if (!g_csv) {
        fprintf(stderr, "Cannot open fan_health.csv: %s\n", strerror(errno));
        close(g_i2c_fd);
        return 1;
    }
    fseek(g_csv, 0, SEEK_END);
    if (ftell(g_csv) == 0) {
        fprintf(g_csv, "timestamp,x_g,y_g,z_g\n");
        fflush(g_csv);
    }

    printf("Fan vibration monitoring started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t raw_x, raw_y, raw_z;
        if (i2c_read_reg16_le(g_i2c_fd, D7S_REG_X_LSB, &raw_x) < 0 ||
            i2c_read_reg16_le(g_i2c_fd, D7S_REG_Y_LSB, &raw_y) < 0 ||
            i2c_read_reg16_le(g_i2c_fd, D7S_REG_Z_LSB, &raw_z) < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        float x = (float)raw_x * SCALE_FACTOR;
        float y = (float)raw_y * SCALE_FACTOR;
        float z = (float)raw_z * SCALE_FACTOR;
        log_sample(g_csv, x, y, z);
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    if (g_csv) fclose(g_csv);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

