#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* TMAG5170-Q1 I2C address (A0=A1=0) */
#define TMAG5170_ADDR 0x0E

/* TMAG5170-Q1 register addresses */
#define TMAG5170_REG_DEVICE_ID       0x00
#define TMAG5170_REG_X_MSB           0x01
#define TMAG5170_REG_X_LSB           0x02
#define TMAG5170_REG_Y_MSB           0x03
#define TMAG5170_REG_Y_LSB           0x04
#define TMAG5170_REG_Z_MSB           0x05
#define TMAG5170_REG_Z_LSB           0x06
#define TMAG5170_REG_DEVICE_CONFIG   0x07
#define TMAG5170_REG_RANGE_CONFIG    0x08

/* Expected device ID for TMAG5170-Q1 */
#define TMAG5170_DEVICE_ID 0x8D

/* Range configuration: 50 mT (bits [7:4] = 0000) */
#define TMAG5170_RANGE_50MT 0x00

/* Device config: continuous conversion, all axes enabled (bits [7:4] = 0000,
   bits [3:2] = 00 (all axes), bit [1] = 0 (continuous), bit [0] = 0) */
#define TMAG5170_DEVICE_CONFIG 0x00

/* LSB scale factor for 50 mT range: 1 LSB = 0.1 mT */
#define TMAG5170_LSB_SCALE_50MT 0.1f

#define I2C_BUS 1
#define LOG_FILE "magnetic_log.csv"
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_axis(int handle, uint8_t msb_reg, uint8_t lsb_reg, int16_t *raw)
{
    uint8_t msb = 0, lsb = 0;
    if (read_register(handle, msb_reg, &msb) < 0)
        return -1;
    if (read_register(handle, lsb_reg, &lsb) < 0)
        return -1;
    *raw = (int16_t)((msb << 8) | lsb);
    return 0;
}

static int initialize_sensor(int handle)
{
    uint8_t device_id = 0;

    /* Verify device ID */
    if (read_register(handle, TMAG5170_REG_DEVICE_ID, &device_id) < 0) {
        fprintf(stderr, "Failed to read device ID register\n");
        return -1;
    }
    if (device_id != TMAG5170_DEVICE_ID) {
        fprintf(stderr, "Unexpected device ID: 0x%02X (expected 0x%02X)\n",
                device_id, TMAG5170_DEVICE_ID);
        return -1;
    }

    /* Configure range: 50 mT */
    if (write_register(handle, TMAG5170_REG_RANGE_CONFIG, TMAG5170_RANGE_50MT) < 0)
        return -1;

    /* Configure device: continuous conversion, all axes enabled */
    if (write_register(handle, TMAG5170_REG_DEVICE_CONFIG, TMAG5170_DEVICE_CONFIG) < 0)
        return -1;

    return 0;
}

static int log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, TMAG5170_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X (rc=%d)\n",
                I2C_BUS, TMAG5170_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_sensor(g_i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,x_mT,y_mT,z_mT\n");
        fflush(g_log_file);
    }

    printf("Logging TMAG5170-Q1 magnetic field data to %s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    while (g_running) {
        int16_t raw_x = 0, raw_y = 0, raw_z = 0;

        if (read_axis(g_i2c_handle, TMAG5170_REG_X_MSB, TMAG5170_REG_X_LSB, &raw_x) < 0 ||
            read_axis(g_i2c_handle, TMAG5170_REG_Y_MSB, TMAG5170_REG_Y_LSB, &raw_y) < 0 ||
            read_axis(g_i2c_handle, TMAG5170_REG_Z_MSB, TMAG5170_REG_Z_LSB, &raw_z) < 0) {
            fprintf(stderr, "Error reading sensor data, continuing...\n");
        } else {
            float x = (float)raw_x * TMAG5170_LSB_SCALE_50MT;
            float y = (float)raw_y * TMAG5170_LSB_SCALE_50MT;
            float z = (float)raw_z * TMAG5170_LSB_SCALE_50MT;

            if (log_data(g_log_file, x, y, z) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

