        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);
    return 0;
}

static int read_sensor(void) {
    int value = gpioRead(GPIO_PIN);
    if (value < 0) {
        fprintf(stderr, "gpioRead failed on pin %d\n", GPIO_PIN);
        return -1;
    }
    return value;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int reinit_attempts = 0;

    while (running) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            reinit_attempts++;
            if (reinit_attempts >= MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max reinit attempts reached, exiting.\n");
                break;
            }
            sleep(60);
            if (initialize_gpio() != 0) {
                log_message("FATAL: pigpio re-initialization failed");
                break;
            }
            continue;
        }
        reinit_attempts = 0;

        if (sensor_value == 1) {
            printf("ALERT: Water detected!\n");
            fflush(stdout);
            log_message("ALERT: Water detected");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

