#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_GPIO 4          /* BCM GPIO 4, physical pin 7 */
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_US 1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_pulse_count = 0;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs.      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — fires on every edge of SENSOR_GPIO.         */
/* ------------------------------------------------------------------ */
static void pulse_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    (void)tick;
    if (level == 1) {                 /* rising edge */
        g_pulse_count++;
    }
}

/* ------------------------------------------------------------------ */
/* Compute RPM from pulses counted in one SAMPLE_INTERVAL_US window.  */
/* ------------------------------------------------------------------ */
static double calculate_rpm(void)
{
    int pulses = (int)g_pulse_count;
    g_pulse_count = 0;
    return (double)pulses * 60.0 / (double)SAMPLE_INTERVAL_US / 1000000.0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped RPM line to the log file and stdout.           */
/* ------------------------------------------------------------------ */
static void log_rpm(double rpm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (g_log_fp != NULL) {
        if (fprintf(g_log_fp, "%s %.2f\n", timestamp, rpm) < 0) {
            fprintf(stderr, "fprintf to log failed\n");
        }
        if (fflush(g_log_fp) != 0) {
            fprintf(stderr, "fflush failed\n");
        }
    }
    printf("%s %.2f\n", timestamp, rpm);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup — safe to call from any exit path.                         */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Disable callback and timer before terminating pigpio. */
    gpioSetAlertFuncEx(SENSOR_GPIO, NULL, NULL);
    gpioSetTimerFunc(0, 0, NULL);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO %d\n", SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Register alert callback ---- */
    if (gpioSetAlertFuncEx(SENSOR_GPIO, pulse_callback, NULL) != 0) {
        fprintf(stderr, "gpioSetAlertFuncEx failed for GPIO %d\n", SENSOR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- 1-second sampling timer ---- */
    if (gpioSetTimerFunc(0, SAMPLE_INTERVAL_US, NULL) != 0) {
        fprintf(stderr, "gpioSetTimerFunc failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started on GPIO %d. Press Ctrl+C to exit.\n",
           SENSOR_GPIO);

    /* ---- Main loop ---- */
    while (g_running) {
        gpioDelay(SAMPLE_INTERVAL_US);   /* 1-second tick */
        if (!g_running) break;

        double rpm = calculate_rpm();
        log_rpm(rpm);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

