#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27
#define LOG_FILE "rotation_log.txt"

/* Quadrature state machine: 0=both low, 1=A high, 2=B high, 3=both high */
typedef enum { STATE_00 = 0, STATE_01, STATE_10, STATE_11 } QuadState;

static volatile QuadState current_state = STATE_00;
static volatile QuadState previous_state = STATE_00;
static volatile int last_edge_gpio = -1;
static FILE *log_file = NULL;
static pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t state_cond = PTHREAD_COND_INITIALIZER;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
    pthread_mutex_lock(&state_mutex);
    pthread_cond_signal(&state_cond);
    pthread_mutex_unlock(&state_mutex);
}

static void log_rotation(const char *direction) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s\n", timestamp, direction);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
    }
}

static void sensor_alert(int gpio, int level, uint32_t tick) {
    (void)tick;
    if (level != 1) return; /* Only rising edges */

    pthread_mutex_lock(&state_mutex);

    int a = (gpio == SENSOR_A_GPIO) ? 1 : 0;
    int b = (gpio == SENSOR_B_GPIO) ? 1 : 0;
    QuadState new_state = (QuadState)((a << 1) | b);

    if (new_state == previous_state) {
        pthread_mutex_unlock(&state_mutex);
        return;
    }

    /* Determine direction: 0->1 = CW, 0->2 = CCW, 1->2 = CCW, 1->3 = CW, etc. */
    const char *direction = "UNKNOWN";
    if (previous_state == STATE_00 && new_state == STATE_01) direction = "CW";
    if (previous_state == STATE_00 && new_state == STATE_10) direction = "CCW";
