#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define TOUCH_PIN  17
#define LED_PIN    18
#define DEBOUNCE_MS 50

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int led_state = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch_line) {
        perror("gpiod_chip_get_line(touch)");
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line(led)");
        goto cleanup;
    }

    if (gpiod_line_request_rising_edge_events(touch_line, "touch_sensor") < 0) {
        perror("gpiod_line_request_rising_edge_events(touch)");
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "touch_led", 0) < 0) {
        perror("gpiod_line_request_output(led)");
        goto cleanup;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    struct timespec last_event = {0, 0};

    while (running) {
        struct timespec ts = {0, 100000000}; /* 100 ms timeout */
        int ev = gpiod_line_event_wait(touch_line, &ts);

        if (ev < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("gpiod_line_event_wait");
            goto cleanup;
        }

        if (ev == 0) {
            continue; /* timeout, loop back */
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(touch_line, &event) < 0) {
            perror("gpiod_line_event_read");
            goto cleanup;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
            continue;
        }

        struct timespec now = event.ts;
        long diff_ms = (now.tv_sec - last_event.tv_sec) * 1000L +
                       (now.tv_nsec - last_event.tv_nsec) / 1000000L;

        if (diff_ms < DEBOUNCE_MS) {
            continue;
        }

        last_event = now;

        led_state = !led_state;
        if (gpiod_line_set_value(led_line, led_state) < 0) {
            perror("gpiod_line_set_value(led)");
            goto cleanup;
        }

        printf("Touch detected! LED toggled to %s\n", led_state ? "ON" : "OFF");
        fflush(stdout);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Exiting.\n");
    return ret;
}

