#define POLL_DELAY_US 50000  /* 50 ms debounce */

typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int overflow_count = 0;
static volatile sig_atomic_t shutdown_requested = 0;

static void signal_handler(int sig) {
    (void)sig;
    shutdown_requested = 1;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_2_PIN);
        return -1;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_1_PIN);
        return -1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_2_PIN);
        return -1;
    }

    /* Ensure LEDs are off at startup */
    if (gpioWrite(LED_1_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d.\n", LED_1_PIN);
        return -1;
    }
    if (gpioWrite(LED_2_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d.\n", LED_2_PIN);
        return -1;
    }

    return 0;
}

static void log_event(int sensor_pin, int state) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Warning: time() failed; logging with 0 timestamp.\n");
        now = 0;
    }

    log_buffer[buffer_index].sensor_pin = sensor_pin;
    log_buffer[buffer_index].timestamp = now;
    log_buffer[buffer_index].state = state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
