        fprintf(stderr, "Error: initial gpioRead failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (!shutdown_requested) {
        int state1 = gpioRead(SENSOR_1_PIN);
        int state2 = gpioRead(SENSOR_2_PIN);

        if (state1 < 0 || state2 < 0) {
            fprintf(stderr, "Error: gpioRead failed.\n");
            break;
        }

        if (state1 != prev_state1) {
            log_event(SENSOR_1_PIN, state1);
            control_led(SENSOR_1_PIN, state1);
            prev_state1 = state1;
        }

        if (state2 != prev_state2) {
            log_event(SENSOR_2_PIN, state2);
            control_led(SENSOR_2_PIN, state2);
            prev_state2 = state2;
        }

        gpioDelay(POLL_DELAY_US);
    }

    print_log_buffer();
    printf("Overflow events: %d\n", overflow_count);
    cleanup();
    return EXIT_SUCCESS;
}

