#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define DEBOUNCE_DELAY_US 5000  // 5 ms debounce
#define PULSES_PER_REVOLUTION 2
#define LOG_FILE "shaft_log.txt"

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t last_sensor1_state = 0;
static volatile sig_atomic_t last_sensor2_state = 0;
static volatile uint32_t last_sensor1_tick = 0;
static volatile uint32_t last_sensor2_tick = 0;
static volatile uint32_t last_rpm_tick = 0;
static volatile int rpm_count = 0;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

void log_data(int sensor1_state, int sensor2_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
    fclose(fp);
}

void sensor_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level != PI_TIMEOUT) {
        uint32_t current_tick = tick;
        uint32_t last_tick;
        int *last_state = (gpio == SENSOR_1_GPIO) ? &last_sensor1_state : &last_sensor2_state;
        uint32_t *last_tick_ptr = (gpio == SENSOR_1_GPIO) ? &last_sensor1_tick : &last_sensor2_tick;

        if (current_tick >= *last_tick_ptr) {
            uint32_t diff = current_tick - *last_tick_ptr;
            if (diff > DEBOUNCE_DELAY_US) {
                if (level != *last_state) {
                    *last_state = level;
                    log_data((gpio == SENSOR_1_GPIO) ? level : *last_sensor2_state,
                             (gpio == SENSOR_2_GPIO) ? level : *last_sensor1_state);
                }
                *last_tick_ptr = current_tick;
            }
        }
    }
}

void calculate_rpm(uint32_t current_tick) {
    if (current_tick - last_rpm_tick >= 1000000) {
        int current_rpm_count = rpm_count;
        rpm_count = 0;
        double time_diff = (double)(current_tick - last_rpm_tick) / 1000000.0;
        if (time_diff > 0) {
            double rpm = (double)current_rpm_count / time_diff * 60.0 / PULSES_PER_REVOLUTION;
            printf("RPM: %.2f\n", rpm);
        }
        last_rpm_tick = current_tick;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_DOWN);

    if (gpioSetAlertFunc(SENSOR_1_GPIO, sensor_callback) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d\n", SENSOR_1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetAlertFunc(SENSOR_2_GPIO, sensor_callback) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d\n", SENSOR_2_GPIO);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(10000); // 10 ms
        uint32_t current_tick = gpioTick();
        calculate_rpm(current_tick);
    }

    printf("\nExiting...\n");
    gpioTerminate();
    return 0;
}

