#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define ALARM_GPIO    27
#define THRESHOLD_SEC 2
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event_type, int sensor_id) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s - Sensor %d: %s\n", timestamp, sensor_id, event_type);
        fflush(log_file);
    }
    printf("%s - Sensor %d: %s\n", timestamp, sensor_id, event_type);
}

static int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "gpioRead failed on GPIO %d: %s\n", gpio_pin, pigpio_error(value));
        return -1;
    }
    return value;
}

static void set_alarm(int state) {
    int rc = gpioWrite(ALARM_GPIO, state);
    if (rc < 0) {
        fprintf(stderr, "gpioWrite failed on GPIO %d: %s\n", ALARM_GPIO, pigpio_error(rc));
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        goto cleanup;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        goto cleanup;
    }
    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ALARM_GPIO);
        goto cleanup;
    }

    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR_1_GPIO);
        goto cleanup;
    }
    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR_2_GPIO);
        goto cleanup;
    }

    if (gpioWrite(ALARM_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to initialize alarm GPIO %d LOW\n", ALARM_GPIO);
        goto cleanup;
    }

    printf("Bridge integrity monitoring started. Press Ctrl+C to exit.\n");

    int alarm_active = 0;
    uint32_t alarm_start_tick = 0;

    while (running) {
        int s1 = read_sensor(SENSOR_1_GPIO);
        int s2 = read_sensor(SENSOR_2_GPIO);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error, continuing...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (s1 == 1 && !alarm_active) {
            log_event("Tilt Start", 1);
            alarm_active = 1;
            alarm_start_tick = gpioTick();
            set_alarm(1);
        } else if (s2 == 1 && !alarm_active) {
            log_event("Tilt Start", 2);
            alarm_active = 1;
            alarm_start_tick = gpioTick();
            set_alarm(1);
        }

        if (alarm_active) {
            uint32_t elapsed = gpioTick() - alarm_start_tick;
            if (elapsed >= (uint32_t)(THRESHOLD_SEC * 1000000)) {
                log_event("Threshold Exceeded", (s1 == 1) ? 1 : 2);
            }
        }

        if (s1 == 0 && s2 == 0 && alarm_active) {
            log_event("Tilt End", (s1 == 1) ? 1 : 2);
            set_alarm(0);
            alarm_active = 0;
        }

        gpioDelay(POLL_DELAY_US);
    }

cleanup:
    printf("\nShutting down...\n");
    set_alarm(0);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

