 * Run:   sudo ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- D7S-A0011 constants (datasheet) ---- */
#define D7S_I2C_ADDR        0x1D   /* 7-bit I2C address */
#define D7S_REG_CTRL1       0x1F   /* Control register 1 */
#define D7S_REG_CTRL2       0x20   /* Control register 2 */
#define D7S_REG_ACC_X_L     0x28   /* X-axis acceleration, little-endian */
#define D7S_REG_ACC_X_H     0x29
#define D7S_REG_ACC_Y_L     0x2A
#define D7S_REG_ACC_Y_H     0x2B
#define D7S_REG_ACC_Z_L     0x2C
#define D7S_REG_ACC_Z_H     0x2D

#define D7S_CTRL1_POWER_DOWN 0x01  /* bit 0: 1 = power-down, 0 = operational */

/* ---- Application constants ---- */
#define I2C_BUS             1
#define LED_GPIO            17
#define VIBRATION_THRESHOLD 500.0f
#define POLL_INTERVAL_US    100000  /* 100 ms */
#define LED_ON_TIME_US      1000000 /* 1 s */
#define MAX_RETRIES         3

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read a single byte register; returns 0 on success, -1 on error.    */
static int read_reg8(int handle, uint8_t reg, uint8_t *out)
{
    int v = i2cReadByteData(handle, reg);
    if (v < 0)
        return -1;
    *out = (uint8_t)v;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte register; returns 0 on success, -1 on error.   */
static int write_reg8(int handle, uint8_t reg, uint8_t val)
{
    return (i2cWriteByteData(handle, reg, val) < 0) ? -1 : 0;
}

/* ------------------------------------------------------------------ */
/* Read a block of `len` bytes starting at `reg` (pigpio i2cReadI2CBlockData).*/
static int read_block(int handle, uint8_t reg, uint8_t *buf, uint8_t len)
{
    int n = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    return (n == (int)len) ? 0 : -1;
}

/* ------------------------------------------------------------------ */
/* Initialize the D7S: verify presence and clear power-down bit.       */
static int init_d7s(int handle)
{
    uint8_t ctrl1 = 0;

    /* Probe: read CTRL1 to confirm the sensor is present. */
    if (read_reg8(handle, D7S_REG_CTRL1, &ctrl1) != 0) {
        fprintf(stderr, "[ERROR] D7S not responding on I2C bus %d addr 0x%02X.\n",
                I2C_BUS, D7S_I2C_ADDR);
        return -1;
    }

    /* Clear power-down bit so the sensor is operational. */
    if (write_reg8(handle, D7S_REG_CTRL1, ctrl1 & ~D7S_CTRL1_POWER_DOWN) != 0) {
        fprintf(stderr, "[ERROR] Failed to write D7S CTRL1.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 3-axis acceleration (little-endian, 6 bytes).                  */
static int read_acceleration(int handle, int16_t *ax, int16_t *ay, int16_t *az)
{
    uint8_t buf[6];

    if (read_block(handle, D7S_REG_ACC_X_L, buf, sizeof(buf)) != 0) {
        fprintf(stderr, "[ERROR] Failed to read acceleration block.\n");
        return -1;
    }

    *ax = (int16_t)((buf[1] << 8) | buf[0]);
    *ay = (int16_t)((buf[3] << 8) | buf[2]);
    *az = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
static float calculate_vibration_magnitude(int16_t ax, int16_t ay, int16_t az)
{
    float x = (float)ax;
    float y = (float)ay;
    float z = (float)az;
    return sqrtf(x * x + y * y + z * z);
}

/* ------------------------------------------------------------------ */
static void log_event(float magnitude)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s - Vibration magnitude exceeded threshold: %.2f\n",
            timestamp, magnitude);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
static void trigger_led(void)
{
    gpioWrite(LED_GPIO, 1);
    gpioDelay(LED_ON_TIME_US);
    gpioWrite(LED_GPIO, 0);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- LED GPIO setup ---- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] Failed to set GPIO %d as output.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, D7S_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed on bus %d addr 0x%02X: %d\n",
                I2C_BUS, D7S_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (init_d7s(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] D7S initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen("seismic_events.log", "a");
    if (!g_log_file) {
        perror("[FATAL] fopen seismic_events.log");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int16_t ax = 0, ay = 0, az = 0;
        int ok = 0;

        /* Retry loop for transient I2C errors. */
        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (read_acceleration(g_i2c_handle, &ax, &ay, &az) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(10000); /* 10 ms backoff before retry */
        }

        if (!ok) {
            fprintf(stderr, "[WARN] Acceleration read failed after %d attempts; skipping cycle.\n",
                    MAX_RETRIES);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        float magnitude = calculate_vibration_magnitude(ax, ay, az);

        if (magnitude > VIBRATION_THRESHOLD) {
            printf("Vibration magnitude: %.2f (threshold: %.2f) - triggering LED.\n",
                   magnitude, VIBRATION_THRESHOLD);
            trigger_led();
            log_event(magnitude);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* ---- Graceful cleanup ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

