#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22
#define LED_PIN 18
#define POLL_INTERVAL_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_lines[4];
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    for (int i = 0; i < 4; i++) {
        sensor_lines[i] = NULL;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    int sensor_pins[4] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN, SENSOR4_PIN};
    for (int i = 0; i < 4; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!sensor_lines[i]) {
            fprintf(stderr, "Failed to get sensor line %d\n", sensor_pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_input(sensor_lines[i], "ky032-sensor") < 0) {
            fprintf(stderr, "Failed to request sensor line %d as input\n", sensor_pins[i]);
            goto cleanup;
        }
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line (LED)");
        goto cleanup;
    }
    if (gpiod_line_request_output(led_line, "ky032-led", 0) < 0) {
        perror("gpiod_line_request_output (LED)");
        goto cleanup;
    }

    printf("Obstacle detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int any_detected = 0;
        for (int i = 0; i < 4; i++) {
            int val = gpiod_line_get_value(sensor_lines[i]);
            if (val < 0) {
                perror("gpiod_line_get_value");
                goto cleanup;
            }
            if (val == 0) {
                any_detected = 1;
                break;
            }
        }

        if (gpiod_line_set_value(led_line, any_detected ? 1 : 0) < 0) {
            perror("gpiod_line_set_value (LED)");
            goto cleanup;
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    for (int i = 0; i < 4; i++) {
        if (sensor_lines[i]) {
            gpiod_line_release(sensor_lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

