/*
 * flame_monitor.c - KY-026 flame sensor monitor for Raspberry Pi 3 B+
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    sudo ./flame_monitor   (needs /var/log/flame_events.log write access)
 *
 * Five KY-026 digital outputs (LOW = flame) on BCM GPIO 2, 3, 4, 17, 27.
 * Rising-edge transition + 50 ms debounce -> event logged to
 *   /var/log/flame_events.log
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/file.h>
#include <gpiod.h>

#define NUM_SENSORS 5
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_US 1000000  /* 1 s */
#define LOG_FILE "/var/log/flame_events.log"

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int sensor_id)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        syslog(LOG_ERR, "time() failed: %s", strerror(errno));
        return;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        syslog(LOG_ERR, "gmtime_r() failed");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        syslog(LOG_ERR, "strftime() failed");
        return;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "fopen(%s): %s", LOG_FILE, strerror(errno));
        return;
    }

    int fd = fileno(fp);
    if (fd < 0) {
        syslog(LOG_ERR, "fileno() failed: %s", strerror(errno));
        fclose(fp);
        return;
    }

    if (flock(fd, LOCK_EX) != 0) {
        syslog(LOG_ERR, "flock(LOCK_EX): %s", strerror(errno));
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s - Sensor ID: %d (GPIO %u) - Flame Detected\n",
                ts, sensor_id, sensor_pins[sensor_id - 1]) < 0) {
        syslog(LOG_ERR, "fprintf() failed: %s", strerror(errno));
    }

    if (fflush(fp) != 0) {
        syslog(LOG_WARNING, "fflush() failed: %s", strerror(errno));
    }

    if (flock(fd, LOCK_UN) != 0) {
        syslog(LOG_WARNING, "flock(LOCK_UN): %s", strerror(errno));
    }

    if (fclose(fp) != 0) {
        syslog(LOG_WARNING, "fclose() failed: %s", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Sensor read with debounce                                        */
/* ------------------------------------------------------------------ */
static int read_sensor_debounced(struct gpiod_line *line, int sensor_id)
{
    int v1 = gpiod_line_get_value(line);
    if (v1 < 0) {
        syslog(LOG_ERR, "gpiod_line_get_value(sensor %d): %s",
               sensor_id, strerror(errno));
        return -1;
    }

    if (v1 == 0) {
        /* LOW = flame detected - confirm with 50 ms debounce read */
        usleep(DEBOUNCE_MS * 1000);

        int v2 = gpiod_line_get_value(line);
        if (v2 < 0) {
            syslog(LOG_ERR, "gpiod_line_get_value(sensor %d, debounce): %s",
                   sensor_id, strerror(errno));
            return -1;
        }
        if (v2 != 0) {
            /* transient - not a real flame */
            return 0;
        }
        return 1;  /* confirmed flame */
    }
    return 0;  /* HIGH = no flame */
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (install_signal_handlers() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
