                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "flame_monitor") != 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(GPIO %u): %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        lines_acquired++;
    }

    syslog(LOG_INFO, "Monitoring %d KY-026 sensors on GPIO %u, %u, %u, %u, %u",
           NUM_SENSORS,
           sensor_pins[0], sensor_pins[1], sensor_pins[2],
           sensor_pins[3], sensor_pins[4]);

    int prev_state[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++)
        prev_state[i] = 0;

    while (g_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = read_sensor_debounced(lines[i], i + 1);
            if (val < 0) {
