            prev_state[i] = val;
        }
        usleep(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down gracefully");

cleanup:
    for (int i = 0; i < lines_acquired; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);
    closelog();
    return EXIT_SUCCESS;
}

