#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define VEML7700_REG_CONFIG 0x00
#define VEML7700_REG_ALS_CONF 0x04
#define VEML7700_REG_ALS_DATA 0x04
#define LED_GPIO 18
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define LUX_THRESHOLD_1 100.0f
#define LUX_THRESHOLD_2 500.0f
#define LUX_THRESHOLD_3 1000.0f
#define LUX_TO_RAW_MULTIPLIER 0.0576f
#define CONFIG_VALUE 0x0000  /* ALS gain 1/8, integration 100 ms */

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int veml7700_write_config(int handle, uint16_t config_value) {
    char buf[2];
    buf[0] = (char)(config_value & 0xFF);
    buf[1] = (char)((config_value >> 8) & 0xFF);
    if (i2cWriteI2CBlockData(handle, VEML7700_REG_CONFIG, buf, 2) < 0) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int veml7700_read_als(int handle, uint16_t *als_value) {
    char buf[2];
    if (i2cReadI2CBlockData(handle, VEML7700_REG_ALS_DATA, buf, 2) < 0) {
        fprintf(stderr, "Error reading ALS data: %s\n", strerror(errno));
        return -1;
    }
    *als_value = (uint16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    return 0;
}

static float calculate_lux(uint16_t als_value) {
    return (float)als_value * LUX_TO_RAW_MULTIPLIER;
}

static int set_led_brightness(int gpio, int brightness) {
    if (gpioPWM(gpio, brightness) < 0) {
        fprintf(stderr, "Error setting PWM: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void log_data(FILE *fp, float lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Lux: %.2f, Brightness: %d, Error: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, lux, brightness, error_code);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

