 *   Bits  9-8: 0x1 = 100 ms conversion time
 *   Bits  7-6: 0x0 = 1 LSB = 0.01 lux
 *   Bits  5-4: 0x0 = 16-bit result
 *   Bits  3-2: 0x0 = no interrupt
 *   Bits  1-0: 0x0 = no polarity
 */
#define OPT3001_CONFIG_WORD 0xC810

/* I2C bus on Raspberry Pi 4 (GPIO 2/3) */
#define I2C_BUS 1

/* Sampling interval in microseconds (1 second) */
#define SAMPLE_INTERVAL_US 1000000

/* Conversion time in microseconds (100 ms) */
#define CONVERSION_TIME_US 100000

/* Global I2C handle for signal handler */
static int i2c_handle = -1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    exit(0);
}

/*
 * Byte-swap a 16-bit word from little-endian (pigpio) to
 * big-endian (OPT3001).
 */
static uint16_t swap_bytes(uint16_t word) {
    return (uint16_t)(((word & 0xFF00) >> 8) | ((word & 0x00FF) << 8));
}

/*
 * Write a 16-bit big-endian configuration word to the OPT3001.
 * pigpio's i2cWriteWordData sends the word in little-endian, so we
 * swap bytes before writing.
 */
static int opt3001_write_config(int handle, uint16_t config) {
    uint16_t swapped = swap_bytes(config);
    int rc = i2cWriteWordData(handle, OPT3001_CONFIG_REG, swapped);
    if (rc < 0) {
        fprintf(stderr, "Error writing config register (rc=%d): %s\n",
                rc, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit big-endian result word from the OPT3001.
 * pigpio's i2cReadWordData returns the word in little-endian, so we
 * swap bytes after reading.
 */
static int opt3001_read_result(int handle, uint16_t *result) {
    int rc = i2cReadWordData(handle, OPT3001_RESULT_REG);
    if (rc < 0) {
        fprintf(stderr, "Error reading result register (rc=%d): %s\n",
                rc, strerror(errno));
        return -1;
    }
    uint16_t swapped = swap_bytes((uint16_t)rc);
    *result = swapped;
    return 0;
}

/*
 * Convert the 16-bit raw result to lux.
 * Bits 15-12: exponent (0-15)
 * Bits 11-0:  mantissa (0-4095)
 * lux = mantissa * 0.01 * (2^exponent)
 */
static float raw_to_lux(uint16_t raw) {
    uint16_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;
    return (float)mantissa * 0.01f * (float)(1 << exponent);
}

/*
 * Log a lux value to 'light_data.txt' with a timestamp.
 */
static int log_data(float lux) {
    FILE *fp = fopen("light_data.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 at OPT3001 address 0x44 */
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X (rc=%d): %s\n",
                I2C_BUS, OPT3001_ADDR, i2c_handle, strerror(errno));
        gpioTerminate();
        return 1;
    }

    /* Configure the OPT3001 for continuous conversion */
    if (opt3001_write_config(i2c_handle, OPT3001_CONFIG_WORD) != 0) {
        fprintf(stderr, "Failed to configure OPT3001\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Wait for the first conversion to complete (100 ms) */
    gpioDelay(CONVERSION_TIME_US);

    /* Install signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    printf("OPT3001 light sensor monitoring started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (1) {
        uint16_t raw_result;
        if (opt3001_read_result(i2c_handle, &raw_result) == 0) {
            float lux = raw_to_lux(raw_result);
            printf("Lux: %.2f\n", lux);
            if (log_data(lux) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
        } else {
            fprintf(stderr, "Warning: failed to read sensor data\n");
        }

        /* Sleep for 1 second (pigpio delay is in microseconds) */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Unreachable in normal operation, but kept for completeness */
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

