#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x08
#define LOG_FILE       "cooling_log.csv"
#define FLOW_SCALE     90.0f
#define FLOW_MIN       0.0f
#define FLOW_MAX       100.0f
#define SAMPLE_US      1000000  /* 1 second */
#define INIT_DELAY_US  2000     /* 2 ms after 0x3608 */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_fp = NULL;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup helper ---- */
static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ---- Initialize I2C and sensor ---- */
static int init_sensor(void) {
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio code %d)\n", g_i2c_handle);
        return -1;
    }

    /* Start continuous measurement: 0x3608 */
    uint8_t cmd[2] = {0x36, 0x08};
    int rc = i2cWriteDevice(g_i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed (pigpio code %d)\n", rc);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    gpioDelay(INIT_DELAY_US);
    return 0;
}

/* ---- Read flow with CRC validation ---- */
static int read_flow(int16_t *raw_out, int *flags_out) {
    uint8_t buf[3];
    int rc = i2cReadDevice(g_i2c_handle, (char *)buf, 3);
    if (rc != 3) {
        fprintf(stderr, "Error: i2cReadDevice returned %d (expected 3)\n", rc);
        return -1;
    }

    /* Validate CRC over the two data bytes */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch (calc=0x%02X, got=0x%02X)\n",
                crc8(buf, 2), buf[2]);
