        fprintf(g_log_fp, "Timestamp,Flow Rate (ml/min),Raw,Status\n");
        fflush(g_log_fp);
    }

    printf("Monitoring SLF3S-1300F on I2C bus %d, addr 0x%02X. Press Ctrl+C to stop.\n",
           I2C_BUS, I2C_ADDR);

