#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>
#include <gpiod.h>

#define GPIO_LEFT   17
#define GPIO_MIDDLE 27
#define GPIO_RIGHT  22
#define LOG_FILE    "path_log.csv"
#define POLL_MS     50

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1)
        return -1;
    if (localtime_r(&rawtime, &timeinfo) == NULL)
        return -1;
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0)
        return -1;
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3];
    const unsigned int offsets[3] = { GPIO_LEFT, GPIO_MIDDLE, GPIO_RIGHT };
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    for (int i = 0; i < 3; i++)
        lines[i] = NULL;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, offsets[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    offsets[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "ky033_obstacle") < 0) {
            fprintf(stderr, "Failed to request GPIO %u as input: %s\n",
                    offsets[i], strerror(errno));
            goto cleanup;
        }
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    if (fprintf(log_fp, "timestamp,left,middle,right\n") < 0) {
        fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
        goto cleanup;
    }
    if (fflush(log_fp) == EOF) {
        fprintf(stderr, "Failed to flush header: %s\n", strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        int values[3];
        bool read_error = false;

        for (int i = 0; i < 3; i++) {
            int v = gpiod_line_get_value(lines[i]);
            if (v < 0) {
                fprintf(stderr, "Failed to read GPIO %u: %s\n",
                        offsets[i], strerror(errno));
                read_error = true;
                break;
            }
            values[i] = v;
        }

        if (read_error)
            break;

        char ts[32];
        if (get_timestamp(ts, sizeof(ts)) != 0) {
            fprintf(stderr, "Failed to generate timestamp: %s\n", strerror(errno));
            break;
        }

        if (fprintf(log_fp, "%s,%d,%d,%d\n", ts, values[0], values[1], values[2]) < 0) {
            fprintf(stderr, "Failed to write CSV row: %s\n", strerror(errno));
            break;
        }
        if (fflush(log_fp) == EOF) {
            fprintf(stderr, "Failed to flush CSV row: %s\n", strerror(errno));
            break;
        }

        usleep(POLL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp != NULL) {
        if (fclose(log_fp) == EOF)
            fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
    }
    for (int i = 0; i < 3; i++) {
        if (lines[i] != NULL)
            gpiod_line_release(lines[i]);
    }
    if (chip != NULL)
        gpiod_chip_close(chip);
    return ret;
}

