/*
 * Flame-detection safety system for Raspberry Pi 3 Model B+
 * Uses libgpiod (character-device API) — no wiringPi.
 *
 * KY-026 flame sensor (digital output):
 *   GPIO17 (physical pin 11) — active-low: LOW = flame detected
 * Active buzzer:
 *   GPIO18 (physical pin 12) — HIGH = buzzer ON
 *
 * Build: gcc -Wall -Wextra -O2 -o flame_alert flame_alert.c -lgpiod
 */

#include <errno.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define FLAME_PIN      17
#define BUZZER_PIN     18
#define POLL_INTERVAL_MS  500
#define BUZZER_DURATION_MS 2000
#define SLICE_MS         100
#define LOG_FILE        "alert_log.txt"
#define CHIP_NAME       "gpiochip0"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_event(const char *message)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return -1;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        perror("localtime_r");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s - %s\n", ts, message) < 0) {
        perror("fprintf(log)");
        return -1;
    }
    if (fflush(g_log_fp) != 0) {
        perror("fflush(log)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Buzzer control                                                      */
/* ------------------------------------------------------------------ */
static int buzzer_on(struct gpiod_line *line)
{
    if (gpiod_line_set_value(line, 1) != 0) {
        perror("gpiod_line_set_value(buzzer ON)");
        return -1;
    }
    return 0;
}

static int buzzer_off(struct gpiod_line *line)
{
    if (gpiod_line_set_value(line, 0) != 0) {
        perror("gpiod_line_set_value(buzzer OFF)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(struct gpiod_chip *chip,
                    struct gpiod_line *flame_line,
                    struct gpiod_line *buzzer_line)
{
    if (buzzer_line) {
        (void)gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (flame_line) {
        gpiod_line_release(flame_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (g_log_fp) {
        if (fclose(g_log_fp) != 0) {
            perror("fclose(log)");
        }
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        goto out;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(log)");
        goto out;
    }

    if (log_event("System started") != 0) {
        goto out;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto out;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_PIN);
    if (!flame_line) {
        perror("gpiod_chip_get_line(flame)");
        goto out;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("gpiod_chip_get_line(buzzer)");
        goto out;
    }

    if (gpiod_line_request_input(flame_line, "flame_sensor") != 0) {
        perror("gpiod_line_request_input(flame)");
        goto out;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) != 0) {
        perror("gpiod_line_request_output(buzzer)");
        goto out;
    }

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    int prev_flame = 1;   /* assume no flame at startup (HIGH) */

    while (g_running) {
        int val = gpiod_line_get_value(flame_line);
        if (val < 0) {
            perror("gpiod_line_get_value(flame)");
            break;
        }

        /* Software edge detection: trigger on HIGH -> LOW transition */
        if (prev_flame == 1 && val == 0) {
            printf("Flame detected!\n");
            if (log_event("Flame detected!") != 0) {
                fprintf(stderr, "Failed to log flame event.\n");
            }

            if (buzzer_on(buzzer_line) != 0) {
                fprintf(stderr, "Failed to activate buzzer.\n");
            } else {
                for (int elapsed = 0; elapsed < BUZZER_DURATION_MS && g_running; elapsed += SLICE_MS) {
                    usleep(SLICE_MS * 1000);
                }
                if (buzzer_off(buzzer_line) != 0) {
                    fprintf(stderr, "Failed to deactivate buzzer.\n");
                }
            }
        }

        prev_flame = val;

        for (int elapsed = 0; elapsed < POLL_INTERVAL_MS && g_running; elapsed += SLICE_MS) {
            usleep(SLICE_MS * 1000);
        }
    }

    if (log_event("System stopped") != 0) {
        fprintf(stderr, "Failed to log shutdown.\n");
    }
    ret = EXIT_SUCCESS;

out:
    cleanup(chip, flame_line, buzzer_line);
    return ret;
}

