            if (log_event("Flame detected!") != 0) {
                fprintf(stderr, "Failed to log flame event.\n");
            }

            if (buzzer_on(buzzer_line) != 0) {
                fprintf(stderr, "Failed to activate buzzer.\n");
            } else {
                for (int elapsed = 0; elapsed < BUZZER_DURATION_MS && g_running; elapsed += SLICE_MS) {
                    usleep(SLICE_MS * 1000);
                }
                if (buzzer_off(buzzer_line) != 0) {
                    fprintf(stderr, "Failed to deactivate buzzer.\n");
                }
            }
        }

        prev_flame = val;

        for (int elapsed = 0; elapsed < POLL_INTERVAL_MS && g_running; elapsed += SLICE_MS) {
            usleep(SLICE_MS * 1000);
        }
    }

    if (log_event("System stopped") != 0) {
        fprintf(stderr, "Failed to log shutdown.\n");
    }
    ret = EXIT_SUCCESS;

out:
    cleanup(chip, flame_line, buzzer_line);
    return ret;
}

