#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TOUCH_SENSOR_PIN 4
#define LED_PIN 17
#define LOG_FILE "touch_log.txt"
#define DEBOUNCE_MS 200
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO%d.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void log_touch_event(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Warning: gmtime_r failed; logging without timestamp.\n");
        fprintf(log_fp, "Touch detected at unknown time\n");
        fflush(log_fp);
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        fprintf(stderr, "Warning: strftime failed; logging without timestamp.\n");
        fprintf(log_fp, "Touch detected at unknown time\n");
        fflush(log_fp);
        return;
    }
    fprintf(log_fp, "Touch detected at %s\n", timestamp);
    fflush(log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_state = gpioRead(TOUCH_SENSOR_PIN);
    if (last_state < 0) {
        fprintf(stderr, "Error: initial gpioRead failed on GPIO%d.\n", TOUCH_SENSOR_PIN);
        fclose(log_fp);
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = gpioRead(TOUCH_SENSOR_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (current_state == 1 && last_state == 0) {
            gpioWrite(LED_PIN, !gpioRead(LED_PIN));
            log_touch_event();
            gpioDelay(DEBOUNCE_MS * 1000);
        }

        last_state = current_state;
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

