/*
 * TMAG5110A1 Hall-effect latch sensor monitor (pigpio)
 *
 * Board:  Raspberry Pi 4 Model B
 * Sensors: Texas Instruments TMAG5110A1 (3-sensor variant)
 * Pins:    GPIO4, GPIO17, GPIO27  (BCM numbering)
 *
 * Latch behavior:
 *   The TMAG5110A1 OUT pin is open-drain.  With the internal pull-up enabled
 *   (gpioSetPullUpDown()), the pin reads HIGH when no south pole is present
 *   and LOW when a south pole is detected.  A logic LOW therefore indicates
 *   a magnet is present.
 *
 * Build:  gcc -Wall -Wextra -O2 -o magnet_monitor magnet_monitor.c -lpigpio -lrt
 * Run:    sudo ./magnet_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_SENSORS 3
#define POLL_DELAY_US 100000          /* 100 ms */
#define LOG_FILE_NAME "magnet_log.txt"

static const int sensor_pins[NUM_SENSORS] = {4, 17, 27};
static const char *sensor_names[NUM_SENSORS] = {"SENSOR_1", "SENSOR_2", "SENSOR_3"};

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *sensor_name, int state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(log_file, "%s - %s: %s\n",
                timestamp, sensor_name,
                state ? "magnet_removed" : "magnet_present") < 0) {
        fprintf(stderr, "fprintf() to log file failed\n");
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush() on log file failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                          */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpioSetMode(sensor_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n",
                    sensor_pins[i]);
            return -1;
        }
        if (gpioSetPullUpDown(sensor_pins[i], PI_PUD_UP) != 0) {
            fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed\n",
                    sensor_pins[i]);
            return -1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int prev_state[NUM_SENSORS];
    int current_state[NUM_SENSORS];
    int first_read = 1;

    /* --- Signal handlers ------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO setup ------------------------------------------------- */
    if (initialize_gpio() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --------------------------------------------- */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        perror("fopen(" LOG_FILE_NAME ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring %d TMAG5110A1 sensors on GPIO%d, GPIO%d, GPIO%d.\n",
           NUM_SENSORS, sensor_pins[0], sensor_pins[1], sensor_pins[2]);
    printf("Logging state changes to '%s'.  Press Ctrl+C to exit.\n",
           LOG_FILE_NAME);

    /* --- Main polling loop ----------------------------------------- */
    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            current_state[i] = gpioRead(sensor_pins[i]);
            if (current_state[i] < 0) {
                fprintf(stderr, "gpioRead(%d) failed\n", sensor_pins[i]);
                current_state[i] = 0;   /* treat read error as no magnet */
            }

            /*
             * First read: record the initial state without logging a
             * transition.  Subsequent reads compare against the previous
             * state and log only on change.
             */
            if (first_read) {
                prev_state[i] = current_state[i];
                first_read = 0;
            } else if (current_state[i] != prev_state[i]) {
                log_event(sensor_names[i], current_state[i]);
                prev_state[i] = current_state[i];
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    /* --- Cleanup ---------------------------------------------------- */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            perror("fclose(log_file)");
        }
        log_file = NULL;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

