#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x4A

#define REG_PART_ID 0x00
#define REG_HW_REV 0x01
#define REG_LED_CURRENT 0x0F
#define REG_AVG_CONFIG 0x04
#define REG_ENABLE 0x01
#define REG_HR_DATA 0x2A

#define EXPECTED_PART_ID 0x02
#define EXPECTED_HW_REV 0x01

#define MIN_BPM 30
#define MAX_BPM 220
#define MOVING_AVG_SIZE 5

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static float heart_rate_buffer[MOVING_AVG_SIZE] = {0};
static int buffer_index = 0;
static int buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_register(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (pigpio rc=%d)\n", value, reg, rc);
        return -1;
    }
    return 0;
}

static int read_register(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (pigpio rc=%d)\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_heart_rate(float *bpm) {
    int raw = i2cReadWordData(i2c_handle, REG_HR_DATA);
    if (raw < 0) {
        fprintf(stderr, "Error reading heart rate register (pigpio rc=%d)\n", raw);
        return -1;
    }
    uint16_t hr_raw = (uint16_t)raw;
    *bpm = (float)hr_raw * 0.5f;
    return 0;
}

static float moving_average(float new_value) {
    heart_rate_buffer[buffer_index] = new_value;
    buffer_index = (buffer_index + 1) % MOVING_AVG_SIZE;
    if (buffer_count < MOVING_AVG_SIZE) buffer_count++;

    float sum = 0.0f;
    for (int i = 0; i < buffer_count; i++) sum += heart_rate_buffer[i];
    return sum / buffer_count;
}

static int log_heart_rate(float bpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, bpm) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static int initialize_sensor(void) {
    uint8_t part_id, hw_rev;

    if (read_register(REG_PART_ID, &part_id) < 0) return -1;
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }
    if (read_register(REG_HW_REV, &hw_rev) < 0) return -1;
    if (hw_rev != EXPECTED_HW_REV) {
        fprintf(stderr, "Unexpected HW_REV: 0x%02X (expected 0x%02X)\n", hw_rev, EXPECTED_HW_REV);
        return -1;
    }

    if (write_register(REG_LED_CURRENT, 0x3F) < 0) return -1;
    if (write_register(REG_AVG_CONFIG, 0x04) < 0) return -1;
    if (write_register(REG_ENABLE, 0x01) < 0) return -1;

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
