 *
 * Reads an 8-channel TTP226 capacitive touch sensor (OUT1..OUT8) on
 * GPIO 5..12 (BCM) and drives an 8-bit binary counter on GPIO 17..24.
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 * Run:    sudo ./touch_counter   (root needed for /dev/gpiochip0 access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 10
#define STABILIZE_MS 200

static const unsigned int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
static const unsigned int output_pins[NUM_CHANNELS] = {17, 18, 19, 20, 21, 22, 23, 24};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_touch_event(int channel, int counter)
{
    FILE *fp = fopen("touch_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open touch_log.txt: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    if (localtime_r(&t, &tm_info)) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_info);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }

    fprintf(fp, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
    fclose(fp);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_line_settings *in_settings = NULL;
    struct gpiod_line_settings *out_settings = NULL;
    struct gpiod_line_request *sensor_req = NULL;
    struct gpiod_line_request *output_req = NULL;
    int prev_state[NUM_CHANNELS];
    int counter = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open(/dev/gpiochip0): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    in_settings = gpiod_line_settings_new();
    out_settings = gpiod_line_settings_new();
    if (!in_settings || !out_settings) {
        fprintf(stderr, "gpiod_line_settings_new: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_settings_set_direction(in_settings, GPIOD_LINE_DIRECTION_INPUT) < 0) {
        fprintf(stderr, "gpiod_line_settings_set_direction(input): %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_settings_set_direction(out_settings, GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        fprintf(stderr, "gpiod_line_settings_set_direction(output): %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_line_settings_set_output_value(out_settings, GPIOD_LINE_VALUE_INACTIVE);

    line_cfg = gpiod_line_config_new();
    if (!line_cfg) {
        fprintf(stderr, "gpiod_line_config_new: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_config_add_line_settings(line_cfg, sensor_pins, NUM_CHANNELS, in_settings) < 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings(sensor): %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_config_add_line_settings(line_cfg, output_pins, NUM_CHANNELS, out_settings) < 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings(output): %s\n", strerror(errno));
        goto cleanup;
    }

    sensor_req = gpiod_chip_request_lines(chip, NULL, line_cfg);
    if (!sensor_req) {
        fprintf(stderr, "gpiod_chip_request_lines(sensor): %s\n", strerror(errno));
        goto cleanup;
    }

    output_req = gpiod_chip_request_lines(chip, NULL, line_cfg);
    if (!output_req) {
        fprintf(stderr, "gpiod_chip_request_lines(output): %s\n", strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        int val = gpiod_line_request_get_value(sensor_req, sensor_pins[i]);
        if (val < 0) {
            fprintf(stderr, "gpiod_line_request_get_value(sensor, pin %u): %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        prev_state[i] = val;
    }

    usleep(STABILIZE_MS * 1000);

    while (program_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_request_get_value(sensor_req, sensor_pins[i]);
            if (val < 0) {
                fprintf(stderr, "gpiod_line_request_get_value(sensor, pin %u): %s\n",
                        sensor_pins[i], strerror(errno));
                continue;
            }

            if (val == 1 && prev_state[i] == 0) {
                counter = (counter + 1) & 0xFF;
                for (int b = 0; b < NUM_CHANNELS; b++) {
                    int wval = (counter >> b) & 1;
                    if (gpiod_line_request_set_value(output_req, output_pins[b], wval) < 0) {
                        fprintf(stderr, "gpiod_line_request_set_value(output, pin %u): %s\n",
                                output_pins[b], strerror(errno));
                    }
                }
                log_touch_event(i + 1, counter);
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
                fflush(stdout);
            }
            prev_state[i] = val;
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (output_req) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            gpiod_line_request_set_value(output_req, output_pins[i], GPIOD_LINE_VALUE_INACTIVE);
        }
        gpiod_line_request_release(output_req);
    }
    if (sensor_req) {
        gpiod_line_request_release(sensor_req);
    }
    if (line_cfg) {
        gpiod_line_config_free(line_cfg);
    }
    if (out_settings) {
        gpiod_line_settings_free(out_settings);
    }
    if (in_settings) {
        gpiod_line_settings_free(in_settings);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

