#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_SENSORS 4
#define POLL_INTERVAL_MS 100
#define CSV_FILENAME "tracking_log.csv"

static const unsigned int sensor_pins[NUM_SENSORS] = {17, 18, 27, 22};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int write_header_if_new(FILE *fp) {
    long pos = ftell(fp);
    if (pos < 0) {
        fprintf(stderr, "ftell failed: %s\n", strerror(errno));
        return -1;
    }
    if (pos == 0) {
        if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            return -1;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "Failed to flush header: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

static int log_data(FILE *fp, int s1, int s2, int s3, int s4) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, s1, s2, s3, s4) < 0) {
        fprintf(stderr, "Failed to write CSV row: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Failed to flush CSV row: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    int pins[NUM_SENSORS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_SENSORS; i++) {
        pins[i] = sensor_pins[i];
        lines[i] = NULL;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpiod_line_request_input(lines[i], "ky033-tracking") < 0) {
            fprintf(stderr, "Failed to request GPIO %u as input: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    FILE *fp = fopen(CSV_FILENAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", CSV_FILENAME, strerror(errno));
        goto cleanup;
    }

    if (write_header_if_new(fp) < 0) {
        goto cleanup;
    }

    printf("KY-033 tracking started. Logging to %s. Press Ctrl+C to exit.\n", CSV_FILENAME);

    while (program_running) {
        int values[NUM_SENSORS];
        int read_error = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read GPIO %u: %s\n", pins[i], strerror(errno));
                read_error = 1;
                break;
            }
            values[i] = val;
        }

        if (read_error) {
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (log_data(fp, values[0], values[1], values[2], values[3]) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        if (fclose(fp) != 0) {
            fprintf(stderr, "Failed to close %s: %s\n", CSV_FILENAME, strerror(errno));
            ret = EXIT_FAILURE;
        }
    }
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

