#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_17 17
#define GPIO_18 18
#define LOG_FILE "/var/log/tilt_events.log"
#define POLL_INTERVAL_MS 100
#define DEBOUNCE_MS 50

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line17 = NULL;
static struct gpiod_line *line18 = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void cleanup(void) {
    if (line17) {
        gpiod_line_release(line17);
        line17 = NULL;
    }
    if (line18) {
        gpiod_line_release(line18);
        line18 = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int log_event(int sensor_number) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Error: localtime() failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_number) < 0) {
        fprintf(stderr, "Error: failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    int ret;
    int prev_val17 = 1, prev_val18 = 1;
    struct timespec last_event17 = {0, 0};
    struct timespec last_event18 = {0, 0};

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error: failed to open gpiochip4: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        fprintf(stderr, "Error: failed to get GPIO line %d: %s\n", GPIO_17, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        fprintf(stderr, "Error: failed to get GPIO line %d: %s\n", GPIO_18, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input_flags(line17, "tilt-monitor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to request GPIO line %d as input with pull-up: %s\n", GPIO_17, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input_flags(line18, "tilt-monitor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to request GPIO line %d as input with pull-up: %s\n", GPIO_18, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started on GPIO %d and %d. Press Ctrl+C to exit.\n", GPIO_17, GPIO_18);

    while (program_running) {
        int val17 = gpiod_line_get_value(line17);
        int val18 = gpiod_line_get_value(line18);

        if (val17 < 0) {
            fprintf(stderr, "Error: failed to read GPIO %d: %s\n", GPIO_17, strerror(errno));
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (val18 < 0) {
            fprintf(stderr, "Error: failed to read GPIO %d: %s\n", GPIO_18, strerror(errno));
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (val17 == 0 && prev_val17 == 1) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            long elapsed_ms = (now.tv_sec - last_event17.tv_sec) * 1000L +
                              (now.tv_nsec - last_event17.tv_nsec) / 1000000L;
            if (elapsed_ms >= DEBOUNCE_MS) {
                if (log_event(1) == 0) {
                    last_event17 = now;
                }
            }
        }
        prev_val17 = val17;

        if (val18 == 0 && prev_val18 == 1) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            long elapsed_ms = (now.tv_sec - last_event18.tv_sec) * 1000L +
                              (now.tv_nsec - last_event18.tv_nsec) / 1000000L;
            if (elapsed_ms >= DEBOUNCE_MS) {
                if (log_event(2) == 0) {
                    last_event18 = now;
                }
            }
        }
        prev_val18 = val18;

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

