    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    if (!left_line || !center_line || !right_line) {
        perror("Failed to get GPIO lines");
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(left_line, "tracing-sensor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0 ||
        gpiod_line_request_input_flags(center_line, "tracing-sensor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0 ||
        gpiod_line_request_input_flags(right_line, "tracing-sensor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("Failed to request GPIO lines as input with pull-up");
        goto cleanup;
    }

    printf("Tracing sensor data logging started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int left_val = gpiod_line_get_value(left_line);
        int center_val = gpiod_line_get_value(center_line);
        int right_val = gpiod_line_get_value(right_line);

        if (left_val < 0 || center_val < 0 || right_val < 0) {
            fprintf(stderr, "Error reading sensor values\n");
            break;
        }

        printf("Left: %d, Center: %d, Right: %d\n", left_val, center_val, right_val);
        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (left_line) gpiod_line_release(left_line);
    if (center_line) gpiod_line_release(center_line);
    if (right_line) gpiod_line_release(right_line);
    if (chip) gpiod_chip_close(chip);

    printf("Program terminated.\n");
    return ret;
}

