#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1175_ADDR 0x49
#define SI1175_REG_ALS_VIS_LSB 0x24
#define SI1175_REG_ALS_VIS_MSB 0x25
#define I2C_BUS "/dev/i2c-1"
#define SAMPLE_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

static int read_si1175_als_vis(int fd, uint16_t *als_vis) {
    uint8_t lsb, msb;
    if (i2c_read_reg8(fd, SI1175_REG_ALS_VIS_LSB, &lsb) < 0) {
        return -1;
    }
    if (i2c_read_reg8(fd, SI1175_REG_ALS_VIS_MSB, &msb) < 0) {
        return -1;
    }
    *als_vis = ((uint16_t)msb << 8) | lsb;
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        perror("Failed to acquire I2C bus access / sensor absent");
        goto cleanup;
    }

    printf("Si1175 ALS-VIS reader started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t als_vis;
        if (read_si1175_als_vis(fd, &als_vis) < 0) {
            fprintf(stderr, "Error reading Si1175 ALS-VIS data: %s\n", strerror(errno));
        } else {
            printf("ALS-VIS: %u\n", als_vis);
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

