#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define LEFT_PIN  2
#define MIDDLE_PIN 3
#define RIGHT_PIN 4
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    int pins[3] = {LEFT_PIN, MIDDLE_PIN, RIGHT_PIN};
    int values[3];
    int ret = EXIT_FAILURE;

    /* Install signal handler for SIGINT (Ctrl+C) */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the gpiochip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get each line individually */
    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get line %d: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Request each line as input */
    for (int i = 0; i < 3; i++) {
        if (gpiod_line_request_input(lines[i], "keywish-sensor") < 0) {
            fprintf(stderr, "Failed to request line %d as input: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Keywish 3-Way Tracking Sensor Reader (libgpiod)\n");
    printf("Pins: L=GPIO%d, M=GPIO%d, R=GPIO%d\n", LEFT_PIN, MIDDLE_PIN, RIGHT_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (!terminate) {
        int read_error = 0;

        for (int i = 0; i < 3; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading line %d: %s\n",
                        pins[i], strerror(errno));
                read_error = 1;
                break;
            }
            values[i] = val;
        }

        if (!read_error) {
            printf("L:%d M:%d R:%d\n", values[0], values[1], values[2]);
            fflush(stdout);
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    for (int i = 0; i < 3; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (terminate) {
        printf("\nExiting gracefully...\n");
    }
    return ret;
}

