#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 200

/* BCM GPIO numbers for TTP226 TP1..TP8 */
static const unsigned int touch_pins[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
        printf("[%ld.%03ld] ", (long)ts.tv_sec, ts.tv_nsec / 1000000L);
    } else {
        printf("[?s] ");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_CHANNELS; i++)
        lines[i] = NULL;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get and request each touch line as input */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, touch_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get line %u: %s\n", touch_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "ttp226-touch") < 0) {
            fprintf(stderr, "Failed to request line %u as input: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");

    while (program_running) {
        print_timestamp();
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read line %u: %s\n",
                        touch_pins[i], strerror(errno));
                goto cleanup;
            }
            printf("CH%d=%d ", i + 1, val);
        }
        printf("\n");
        fflush(stdout);

        /* Sleep POLL_INTERVAL_MS, but wake early on signal */
        struct timespec sleep_ts = {
            .tv_sec  = POLL_INTERVAL_MS / 1000,
            .tv_nsec = (POLL_INTERVAL_MS % 1000) * 1000000L
        };
        while (nanosleep(&sleep_ts, &sleep_ts) == -1 && errno == EINTR && program_running)
            ;
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL)
            gpiod_line_release(lines[i]);
    }
    if (chip != NULL)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting gracefully.\n");
    return ret;
}

