#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define PWM_FREQ   1000
#define PWM_RANGE  255
#define FADE_STEPS 50
#define FADE_DELAY_US (5000000 / FADE_STEPS)  /* 5 s total */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Convert a hue (0.0 .. 1.0) to RGB with full saturation and value.
 * Returns 0 on success, -1 on invalid hue.
 */
static int hue_to_rgb(float hue, int *r, int *g, int *b)
{
    if (hue < 0.0f || hue > 1.0f) {
        syslog(LOG_ERR, "hue out of range: %.3f", hue);
        return -1;
    }

    float h = hue * 6.0f;
    int   i = (int)h;
    float f = h - (float)i;
    float p = 0.0f;
    float q = 1.0f;
    float t = 1.0f - f;

    switch (i % 6) {
        case 0: p = 0.0f; q = 1.0f; break;
        case 1: p = t; q = 1.0f; break;
        case 2: p = 0.0f; q = f; break;
        case 3: p = 0.0f; q = t; break;
        case 4: p = f; q = 0.0f; break;
        case 5: p = 1.0f; q = 0.0f; break;
    }

    float r_f = p + (q - p) * 255.0f;
    float g_f = p + (q - p) * 255.0f;
    float b_f = p + (q - p) * 255.0f;

    *r = (int)r_f;
    *g = (int)g_f;
    *b = (int)b_f;
    return 0;
}

/*
 * Common-anode LED: invert duty cycle.
 */
static void set_led_color(int r, int g, int b)
{
    int ir = 255 - r;
    int ig = 255 - g;
    int ib = 255 - b;

    if (gpioPWM(RED_PIN, ir) != 0)
        syslog(LOG_ERR, "gpioPWM failed on RED_PIN (duty %d)", ir);
    if (gpioPWM(GREEN_PIN, ig) != 0)
        syslog(LOG_ERR, "gpioPWM failed on GREEN_PIN (duty %d)", ig);
    if (gpioPWM(BLUE_PIN, ib) != 0)
        syslog(LOG_ERR, "gpioPWM failed on BLUE_PIN (duty %d)", ib);
