#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TCS34725_ADDR  0x29

#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x01
#define TCS34725_ID      0x12
#define TCS34725_CDATAL  0x14
#define TCS34725_RDATAL  0x16
#define TCS34725_GDATAL  0x18
#define TCS34725_BDATAL  0x1A
#define TCS34725_CONTROL 0x0F

#define ENABLE_PON       0x01
#define ENABLE_AEN      0x02

#define RED_THRESHOLD   200
#define POLL_MS         200

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16_le(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c read16 reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int tcs34725_init(int fd) {
    uint8_t id = 0;
    if (i2c_read_reg8(fd, TCS34725_ID, &id) < 0) return -1;
    if (id != 0x44) {
        fprintf(stderr, "Unexpected sensor ID 0x%02X (expected 0x44)\n", id);
        return -1;
    }
    if (i2c_write_reg8(fd, TCS34725_ENABLE, ENABLE_PON) < 0) return -1;
    usleep(3000);
    if (i2c_write_reg8(fd, TCS34725_ENABLE, ENABLE_PON | ENABLE_AEN) < 0) return -1;
    if (i2c_write_reg8(fd, TCS34725_ATIME, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, TCS34725_CONTROL, 0x00) < 0) return -1;
    return 0;
}

static int tcs34725_read(int fd, uint16_t *c, uint16_t *r, uint16_t *g, uint16_t *b) {
    if (i2c_read_reg16_le(fd, TCS34725_CDATAL, c) < 0) return -1;
    if (i2c_read_reg16_le(fd, TCS34725_RDATAL, r) < 0) return -1;
    if (i2c_read_reg16_le(fd, TCS34725_GDATAL, g) < 0) return -1;
    if (i2c_read_reg16_le(fd, TCS34725_BDATAL, b) < 0) return -1;
    return 0;
}

static void calibrate(uint16_t c, uint16_t r, uint16_t g, uint16_t b,
                      float *c_g, float *r_g, float *g_g, float *b_g,
                      float *c_o, float *r_o, float *g_o, float *b_o) {
    *c_g = (float)c / 255.0f;
    *r_g = (float)r / 255.0f;
    *g_g = (float)g / 255.0f;
    *b_g = (float)b / 255.0f;
    *c_o = 0.0f;
    *r_o = 0.0f;
    *g_o = 0.0f;
    *b_o = 0.0f;
}

static void apply_calibration(uint16_t c, uint16_t r, uint16_t g, uint16_t b,
                              float c_g, float r_g, float g_g, float b_g,
                              float c_o, float r_o, float g_o, float b_o,
                              uint16_t *c_cal, uint16_t *r_cal, uint16_t *g_cal, uint16_t *b_cal) {
    *c_cal = (uint16_t)(c_g * c + c_o);
    *r_cal = (uint16_t)(r_g * r + r_o);
    *g_cal = (uint16_t)(g_g * g + g_o);
    *b_cal = (uint16_t)(b_g * b + b_o);
}

int main(void) {
    struct sigaction sa = { .sa_handler = sighandler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", TCS34725_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "TCS34725 init failed\n");
        close(fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open failed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    struct gpiod_line *led = gpiod_chip_get_line(chip, 17);
    if (!led) {
        fprintf(stderr, "gpiod get line 17 failed: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }
    if (gpiod_line_request_output(led, "tcs34725_led", 0) < 0) {
        fprintf(stderr, "gpiod request output failed: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    uint16_t c, r, g, b;
    float c_g, r_g, g_g, b_g, c_o, r_o, g_o, b_o;

    while (g_running) {
        if (tcs34725_read(fd, &c, &r, &g, &b) < 0) {
            fprintf(stderr, "Read failed, re-initializing...\n");
            if (tcs34725_init(fd) < 0) {
                fprintf(stderr, "Re-init failed, exiting\n");
                break;
            }
            usleep(POLL_MS * 1000);
            continue;
        }

        calibrate(c, r, g, b, &c_g, &r_g, &g_g, &b_g, &c_o, &r_o, &g_o, &b_o);

        uint16_t c_cal, r_cal, g_cal, b_cal;
        apply_calibration(c, r, g, b, c_g, r_g, g_g, b_g, c_o, r_o, g_o, b_o,
                          &c_cal, &r_cal, &g_cal, &b_cal);

        printf("C: %5u  R: %5u  G: %5u  B: %5u  ->  C: %5u  R: %5u  G: %5u  B: %5u\n",
               c, r, g, b, c_cal, r_cal, g_cal, b_cal);

        int led_state = (r_cal > RED_THRESHOLD) ? 1 : 0;
        if (gpiod_line_set_value(led, led_state) < 0) {
            fprintf(stderr, "gpiod set value failed: %s\n", strerror(errno));
        }

        usleep(POLL_MS * 1000);
    }

    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    i2c_write_reg8(fd, TCS34725_ENABLE, 0x00);
    close(fd);
    return 0;
}

