        if (tcs34725_read(fd, &c, &r, &g, &b) < 0) {
            fprintf(stderr, "Read failed, re-initializing...\n");
            if (tcs34725_init(fd) < 0) {
                fprintf(stderr, "Re-init failed, exiting\n");
                break;
            }
            usleep(POLL_MS * 1000);
            continue;
        }

        calibrate(c, r, g, b, &c_g, &r_g, &g_g, &b_g, &c_o, &r_o, &g_o, &b_o);

        uint16_t c_cal, r_cal, g_cal, b_cal;
        apply_calibration(c, r, g, b, c_g, r_g, g_g, b_g, c_o, r_o, g_o, b_o,
                          &c_cal, &r_cal, &g_cal, &b_cal);

        printf("C: %5u  R: %5u  G: %5u  B: %5u  ->  C: %5u  R: %5u  G: %5u  B: %5u\n",
               c, r, g, b, c_cal, r_cal, g_cal, b_cal);

        int led_state = (r_cal > RED_THRESHOLD) ? 1 : 0;
        if (gpiod_line_set_value(led, led_state) < 0) {
            fprintf(stderr, "gpiod set value failed: %s\n", strerror(errno));
        }

        usleep(POLL_MS * 1000);
    }

    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    i2c_write_reg8(fd, TCS34725_ENABLE, 0x00);
    close(fd);
    return 0;
}

