#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define LED_PIN 18
#define NUM_LEDS 10
#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES 0x10
#define BH1750_MEASUREMENT_DELAY_US 180000
#define MAX_LUX 1000.0
#define MIN_LUX 0.0
#define MIN_BRIGHTNESS 0
#define MAX_BRIGHTNESS 255
#define PWM_RANGE 255
#define PWM_FREQ 800000
#define PWM_DUTY_CYCLE 0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;
    gpioPWM(LED_PIN, brightness);
}

static void set_leds_brightness(const int *brightness_values) {
    for (int i = 0; i < NUM_LEDS; i++) {
        set_led_brightness(brightness_values[i]);
    }
}

static int read_bh1750(float *lux_out) {
    if (i2cWriteByte(i2c_handle, BH1750_CONT_HIGH_RES) < 0) {
        fprintf(stderr, "Error: Failed to write to BH1750.\n");
        return -1;
    }
    gpioDelay(BH1750_MEASUREMENT_DELAY_US);

    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read from BH1750.\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int map_lux_to_brightness(float lux) {
    if (lux < MIN_LUX) lux = MIN_LUX;
    if (lux > MAX_LUX) lux = MAX_LUX;
    float normalized = (lux - MIN_LUX) / (MAX_LUX - MIN_LUX);
    float log_val = log10f(normalized + 1.0f);
    float brightness = (log_val / log10f(2.0f)) * (MAX_BRIGHTNESS - MIN_BRIGHTNESS) + MIN_BRIGHTNESS;
    return (int)brightness;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus (sensor may be absent).\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(LED_PIN, PWM_FREQ);
    gpioSetPWMrange(LED_PIN, PWM_RANGE);
    gpioPWM(LED_PIN, PWM_DUTY_CYCLE);

    int led_brightness_values[NUM_LEDS];
    for (int i = 0; i < NUM_LEDS; i++) {
        led_brightness_values[i] = 0;
    }

    while (running) {
        float lux = 0.0f;
        if (read_bh1750(&lux) != 0) {
            fprintf(stderr, "Warning: BH1750 read failed, retrying...\n");
            gpioDelay(1000000);
            continue;
        }

        int brightness = map_lux_to_brightness(lux);
        if (brightness < MIN_BRIGHTNESS) brightness = MIN_BRIGHTNESS;
        if (brightness > MAX_BRIGHTNESS) brightness = MAX_BRIGHTNESS;

        for (int i = 0; i < NUM_LEDS; i++) {
            led_brightness_values[i] = brightness;
        }
        set_leds_brightness(led_brightness_values);

        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        gpioDelay(500000);
    }

    set_leds_brightness(NULL);
    gpioPWM(LED_PIN, PWM_DUTY_CYCLE);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

