#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define BH1750_ADDR 0x23
#define BH1750_ONE_TIME_HIGH_RES 0x20
#define BH1750_CONV_TIME_MS 120

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define NUM_LEDS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read: unexpected EOF\n");
            return -1;
        }
        total += n;
    }
    return 0;
}

static int read_bh1750(int fd, float *lux_out) {
    if (i2c_write_byte(fd, BH1750_ONE_TIME_HIGH_RES) < 0) return -1;
    usleep(BH1750_CONV_TIME_MS * 1000);

    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int spi_transfer(int fd, const uint8_t *tx, uint8_t *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void set_apa102_brightness(int fd, uint8_t brightness) {
    if (brightness > 31) brightness = 31;

    uint8_t frame[NUM_LEDS * 4 + 4];
    memset(frame, 0, sizeof(frame));

    for (int i = 0; i < NUM_LEDS; i++) {
        frame[i * 4]     = 0xE0 | brightness;
        frame[i * 4 + 1] = 0x00;
        frame[i * 4 + 2] = 0x00;
        frame[i * 4 + 3] = 0x00;
    }
    frame[NUM_LEDS * 4] = 0xFF;
    frame[NUM_LEDS * 4 + 1] = 0xFF;
    frame[NUM_LEDS * 4 + 2] = 0xFF;
    frame[NUM_LEDS * 4 + 3] = 0xFF;

    uint8_t rx[NUM_LEDS * 4 + 4];
    if (spi_transfer(fd, frame, rx, sizeof(frame)) < 0) {
        fprintf(stderr, "SPI transfer failed for APA102\n");
    }
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        set_apa102_brightness(spi_fd, 0);
        close(spi_fd);
        spi_fd = -1;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                BH1750_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n",
                SPI_DEVICE, strerror(errno));
        cleanup();
        return 1;
    }

    uint8_t spi_mode = SPI_MODE_0;
    uint8_t spi_bits = 8;
    uint32_t spi_speed = SPI_SPEED_HZ;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("BH1750 light sensor and APA102 LED control started.\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        float lux = 0.0f;
        if (read_bh1750(i2c_fd, &lux) < 0) {
            fprintf(stderr, "BH1750 read failed; turning off LEDs.\n");
            set_apa102_brightness(spi_fd, 0);
            sleep(1);
            continue;
        }

        if (lux < 10.0f) lux = 10.0f;
        if (lux > 300.0f) lux = 300.0f;

        uint8_t brightness = (uint8_t)((lux - 10.0f) / 290.0f * 31.0f);
        set_apa102_brightness(spi_fd, brightness);

        printf("Lux: %.2f  Brightness: %u\n", lux, brightness);
        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

