#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDR 0x10
#define VEML7700_CONFIG_REG 0x00
#define VEML7700_ALS_DATA_REG 0x04
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 18
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200
#define MAX_LUX 120000.0
#define GAMMA 2.2

static volatile int keep_running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3] = {reg, (value >> 8) & 0xFF, value & 0xFF};
    if (write(fd, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int init_veml7700(int fd) {
    if (i2c_write_reg16(fd, VEML7700_CONFIG_REG, 0x0000) < 0) {
        fprintf(stderr, "Failed to write VEML7700 config: %s\n", strerror(errno));
        return -1;
    }
    usleep(100000);
    return 0;
}

float read_lux(int fd) {
    uint16_t raw;
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_read_reg16(fd, VEML7700_ALS_DATA_REG, &raw) == 0) {
            float lux = (float)raw * 0.0288f;
            if (lux > MAX_LUX) lux = MAX_LUX;
            if (lux < 0) lux = 0;
            return lux;
        }
        retries++;
        if (retries < MAX_RETRIES) {
            fprintf(stderr, "I2C read error (attempt %d/%d): %s\n", retries, MAX_RETRIES, strerror(errno));
            usleep(RETRY_DELAY_MS * 1000);
        }
    }
    fprintf(stderr, "Failed to read lux after %d retries\n", MAX_RETRIES);
    return -1.0f;
}

int map_lux_to_brightness(float lux) {
    if (lux < 0) lux = 0;
    if (lux > MAX_LUX) lux = MAX_LUX;
    float normalized = lux / MAX_LUX;
    float gamma_corrected = powf(normalized, 1.0f / GAMMA);
    return (int)(gamma_corrected * 255.0f);
}

void set_led_brightness(struct gpiod_line *line, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;
    int on_time_us = (brightness * 1000) / 255;
    int off_time_us = 1000 - on_time_us;
    if (on_time_us > 0) {
        gpiod_line_set_value(line, 1);
        usleep(on_time_us);
    }
    if (off_time_us > 0) {
        gpiod_line_set_value(line, 0);
        usleep(off_time_us);
    }
}

void cleanup(void) {
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_veml7700(i2c_fd) < 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(line, "ws2812b", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_LINE, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    while (keep_running) {
        float lux = read_lux(i2c_fd);
        if (lux < 0) {
            fprintf(stderr, "Error reading lux, skipping iteration\n");
            usleep(LOOP_DELAY_MS * 1000);
            continue;
        }
        int brightness = map_lux_to_brightness(lux);
        set_led_brightness(line, brightness);
        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        usleep(LOOP_DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

