#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define BH1750_CONT_HRES 0x10
#define LED_GPIO       17
#define BUFFER_SIZE    60
#define SAMPLE_DELAY_US 1000000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int gpio_export(int gpio) {
    char buf[4];
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        if (errno != EBUSY) {
            fprintf(stderr, "Failed to open export: %s\n", strerror(errno));
            return -1;
        }
        return 0;
    }
    snprintf(buf, sizeof(buf), "%d", gpio);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Failed to export GPIO %d: %s\n", gpio, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_unexport(int gpio) {
    char buf[4];
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open unexport: %s\n", strerror(errno));
        return -1;
    }
    snprintf(buf, sizeof(buf), "%d", gpio);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Failed to unexport GPIO %d: %s\n", gpio, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(int gpio, const char *dir) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", gpio);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open direction: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, dir, strlen(dir)) < 0) {
        fprintf(stderr, "Failed to set direction: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_write(int gpio, int val) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", gpio);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open value: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, val ? "1" : "0", 1) < 0) {
        fprintf(stderr, "Failed to write value: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static float calculate_lux(uint16_t raw) {
    return (float)raw / 1.2f;
}

static float calculate_average_lux(const float *buf, int size) {
    float sum = 0.0f;
    int count = 0;
    for (int i = 0; i < size; i++) {
        if (buf[i] >= 0.0f) {
            sum += buf[i];
            count++;
        }
    }
    return (count > 0) ? (sum / count) : 0.0f;
}

static float calculate_blink_rate(float lux) {
    float rate = 0.5f + (lux / 1000.0f) * 4.5f;
    if (rate < 0.5f) rate = 0.5f;
    if (rate > 5.0f) rate = 5.0f;
    return rate;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (i2c_write_cmd(i2c_fd, BH1750_CONT_HRES) < 0) {
        close(i2c_fd);
        return 1;
    }

    if (gpio_export(LED_GPIO) < 0) {
        close(i2c_fd);
        return 1;
    }

    if (gpio_set_direction(LED_GPIO, "out") < 0) {
        gpio_unexport(LED_GPIO);
        close(i2c_fd);
        return 1;
    }

    float lux_buffer[BUFFER_SIZE];
    for (int i = 0; i < BUFFER_SIZE; i++) lux_buffer[i] = -1.0f;

    while (running) {
        uint8_t data[2];
        if (i2c_read_bytes(i2c_fd, data, 2) < 0) {
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
        float lux = calculate_lux(raw);

        int idx = (int)(lux / 10.0f);
        if (idx < 0) idx = 0;
        if (idx >= BUFFER_SIZE) idx = BUFFER_SIZE - 1;

        lux_buffer[idx] = lux;

        float avg_lux = calculate_average_lux(lux_buffer, BUFFER_SIZE);
        float blink_rate = calculate_blink_rate(avg_lux);

        int period_us = (int)(1000000.0 / blink_rate);
        int half_period_us = period_us / 2;

        if (gpio_write(LED_GPIO, 1) < 0) break;
        usleep(half_period_us);
        if (gpio_write(LED_GPIO, 0) < 0) break;
        usleep(half_period_us);
    }

    gpio_write(LED_GPIO, 0);
    gpio_unexport(LED_GPIO);
    close(i2c_fd);
    return 0;
}

