    for (int i = 0; i < BUFFER_SIZE; i++) lux_buffer[i] = -1.0f;

    while (running) {
        uint8_t data[2];
        if (i2c_read_bytes(i2c_fd, data, 2) < 0) {
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
        float lux = calculate_lux(raw);

        int idx = (int)(lux / 10.0f);
        if (idx < 0) idx = 0;
        if (idx >= BUFFER_SIZE) idx = BUFFER_SIZE - 1;

        lux_buffer[idx] = lux;

        float avg_lux = calculate_average_lux(lux_buffer, BUFFER_SIZE);
        float blink_rate = calculate_blink_rate(avg_lux);

        int period_us = (int)(1000000.0 / blink_rate);
        int half_period_us = period_us / 2;

        if (gpio_write(LED_GPIO, 1) < 0) break;
        usleep(half_period_us);
        if (gpio_write(LED_GPIO, 0) < 0) break;
        usleep(half_period_us);
    }

    gpio_write(LED_GPIO, 0);
    gpio_unexport(LED_GPIO);
    close(i2c_fd);
    return 0;
}

