#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define LED_PIN 17
#define BUTTON_PIN 18
#define CHIP_NAME "gpiochip0"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static struct gpiod_line *button_line = NULL;
static volatile sig_atomic_t keep_running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

void cleanup_resources(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (button_line) {
        gpiod_line_release(button_line);
        button_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line (LED)");
        cleanup_resources();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "blink_led", 0) < 0) {
        perror("gpiod_line_request_output (LED)");
        cleanup_resources();
        return EXIT_FAILURE;
    }

    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("gpiod_chip_get_line (BUTTON)");
        cleanup_resources();
        return EXIT_FAILURE;
    }

    struct gpiod_line_request_config button_config = {
        .consumer = "blink_button",
        .request_type = GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP
    };

    if (gpiod_line_request(button_line, &button_config, 0) < 0) {
        perror("gpiod_line_request (BUTTON)");
        cleanup_resources();
        return EXIT_FAILURE;
    }

    printf("Blinking LED on BCM GPIO%d. Press the button on BCM GPIO%d to stop.\n", LED_PIN, BUTTON_PIN);

    while (keep_running) {
        if (gpiod_line_set_value(led_line, 1) < 0) {
            perror("gpiod_line_set_value (LED on)");
            break;
        }
        sleep(1);

        if (!keep_running) break;

        if (gpiod_line_set_value(led_line, 0) < 0) {
            perror("gpiod_line_set_value (LED off)");
            break;
        }
        sleep(1);

        struct timespec ts = {1, 0};
        int ret = gpiod_line_event_wait(button_line, &ts);
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            break;
        } else if (ret > 0) {
            struct gpiod_line_event event;
            if (gpiod_line_event_read(button_line, &event) == 0) {
                if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                    printf("Button pressed! Stopping.\n");
                    break;
                }
            }
        }
    }

    cleanup_resources();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

