#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define LED_PIN 24
#define BUTTON_PIN 22
#define CHIP_NAME "gpiochip0"
#define BLINK_INTERVAL_MS 500

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the gpiochip device */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the LED line */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line(LED)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get the button line */
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("gpiod_chip_get_line(BUTTON)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request LED line as output, initially low */
    ret = gpiod_line_request_output(led_line, "led_blink", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(LED)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request button line as input with internal pull-down */
    ret = gpiod_line_request_input_flags(button_line, "button_blink",
                                          GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN);
    if (ret < 0) {
        perror("gpiod_line_request_input_flags(BUTTON)");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("LED blinking controlled by button. Press Ctrl+C to exit.\n");

    while (keep_running) {
        int button_val = gpiod_line_get_value(button_line);
        if (button_val < 0) {
            perror("gpiod_line_get_value(BUTTON)");
            break;
        }

        if (button_val == 1) {
            /* Button pressed: blink LED */
            ret = gpiod_line_set_value(led_line, 1);
            if (ret < 0) {
                perror("gpiod_line_set_value(LED, 1)");
                break;
            }
            usleep(BLINK_INTERVAL_MS * 1000);

            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                perror("gpiod_line_set_value(LED, 0)");
                break;
            }
            usleep(BLINK_INTERVAL_MS * 1000);
        } else {
            /* Button released: turn LED off immediately */
            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                perror("gpiod_line_set_value(LED, 0)");
                break;
            }
            usleep(10000); /* 10 ms debounce */
        }
    }

    /* Clean up: ensure LED is off, then release lines and close chip */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

