#define PWM_FREQ_HZ 100
#define PWM_PERIOD_US (1000000 / PWM_FREQ_HZ)
#define PWM_DUTY_MAX 100
#define UPDATE_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_us(unsigned int us) {
    struct timespec ts = {
        .tv_sec = us / 1000000,
        .tv_nsec = (long)(us % 1000000) * 1000
    };
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        /* retry on interrupt */
    }
}

static void pwm_write(struct gpiod_line *line, int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > PWM_DUTY_MAX) duty_percent = PWM_DUTY_MAX;

    unsigned int on_us = (PWM_PERIOD_US * duty_percent) / PWM_DUTY_MAX;
    unsigned int off_us = PWM_PERIOD_US - on_us;

    if (on_us > 0) {
        if (gpiod_line_set_value(line, 1) < 0) {
            fprintf(stderr, "PWM set high failed: %s\n", strerror(errno));
            return;
        }
        sleep_us(on_us);
    }
    if (off_us > 0) {
        if (gpiod_line_set_value(line, 0) < 0) {
            fprintf(stderr, "PWM set low failed: %s\n", strerror(errno));
            return;
        }
        sleep_us(off_us);
