        fprintf(stderr, "Failed to request GREEN line as output: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(blue_line, "rgb-pwm", 0) < 0) {
        fprintf(stderr, "Failed to request BLUE line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    srand((unsigned int)time(NULL));

    while (running) {
        int r = rand() % (PWM_DUTY_MAX + 1);
        int g = rand() % (PWM_DUTY_MAX + 1);
        int b = rand() % (PWM_DUTY_MAX + 1);

        pwm_write(red_line, r);
