#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <unistd.h>
#include <pigpio.h>

#define LSM303_ACCEL_ADDR 0x19
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define GPIO_PIN 17
#define LOG_FILE "impact_log.txt"
#define DEFAULT_THRESHOLD 2.0f
#define SAMPLE_RATE_HZ 10
#define PULSE_DURATION_MS 50

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, expected %u, got %d)\n", reg, len, rc);
        return -1;
    }
    return 0;
}

static int init_lsm303(int handle) {
    if (i2c_write_byte(handle, CTRL_REG1_A, 0x27) < 0) return -1;
    if (i2c_write_byte(handle, CTRL_REG4_A, 0x00) < 0) return -1;
    return 0;
}

static int read_accel(int handle, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_block(handle, OUT_X_L_A | 0x80, buf, 6) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;
    return 0;
}

static float calc_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

static void log_impact(float x, float y, float z, float mag) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, X: %.3f, Y: %.3f, Z: %.3f, Mag: %.3f\n", ts, x, y, z, mag);
    fclose(fp);
}

static void pulse_gpio(int pin, int duration_ms) {
    gpioWrite(pin, 1);
    gpioDelay(duration_ms * 1000);
    gpioWrite(pin, 0);
}

int main(int argc, char *argv[]) {
    float threshold = DEFAULT_THRESHOLD;
    if (argc > 1) {
        threshold = atof(argv[1]);
        if (threshold <= 0.0f) {
            fprintf(stderr, "Invalid threshold, using default %.2fG\n", DEFAULT_THRESHOLD);
            threshold = DEFAULT_THRESHOLD;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_lsm303(i2c_handle) < 0) {
        fprintf(stderr, "LSM303 init failed (sensor absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    printf("Impact detection started (threshold %.2fG). Ctrl+C to exit.\n", threshold);

    while (running) {
        float x, y, z;
        if (read_accel(i2c_handle, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
            gpioDelay(1000000 / SAMPLE_RATE_HZ);
            continue;
        }
        float mag = calc_magnitude(x, y, z);
        if (mag > threshold) {
            printf("Impact detected! Mag: %.3fG\n", mag);
            log_impact(x, y, z, mag);
            pulse_gpio(GPIO_PIN, PULSE_DURATION_MS);
        }
        gpioDelay(1000000 / SAMPLE_RATE_HZ);
    }

    printf("\nShutting down...\n");
    gpioWrite(GPIO_PIN, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

