#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define LED_GPIO 18
#define SAMPLE_INTERVAL_US 500000
#define RETRY_DELAY_US 100000

#define REG_MODE 0x0D
#define REG_ALS_LSB 0x64
#define REG_ALS_MSB 0x65
#define REG_RED_LSB 0x66
#define REG_RED_MSB 0x67
#define REG_GREEN_LSB 0x68
#define REG_GREEN_MSB 0x69
#define REG_BLUE_LSB 0x6A
#define REG_BLUE_MSB 0x6B

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d\n", reg, value, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, rc=%d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_16bit(uint8_t lsb_reg, uint16_t *out) {
    uint8_t lsb, msb;
    if (read_reg(lsb_reg, &lsb) < 0) return -1;
    if (read_reg(lsb_reg + 1, &msb) < 0) return -1;
    *out = (uint16_t)((msb << 8) | lsb);
    return 0;
}

static int init_adpd188bi(void) {
    if (write_reg(REG_MODE, 0x01) < 0) {
        fprintf(stderr, "Failed to set MODE register\n");
        return -1;
    }
    return 0;
}

static void log_data(uint16_t als, uint16_t r, uint16_t g, uint16_t b) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, r, g, b);
    fflush(log_file);
}

static void control_led(uint16_t als) {
    int duty = (int)((float)als / 65535.0f * 255.0f);
    if (duty > 255) duty = 255;
    if (duty < 0) duty = 0;
    gpioPWM(LED_GPIO, duty);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %d\n", I2C_BUS, ADPD188BI_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_adpd188bi() < 0) {
        fprintf(stderr, "ADPD188BI initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("color_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open color_log.csv\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
        fflush(log_file);
