    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %d\n", I2C_BUS, ADPD188BI_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_adpd188bi() < 0) {
        fprintf(stderr, "ADPD188BI initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("color_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open color_log.csv\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
        fflush(log_file);
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, 1000);
    gpioSetPWMrange(LED_GPIO, 255);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        uint16_t als, r, g, b;

        if (read_16bit(REG_ALS_LSB, &als) < 0 ||
            read_16bit(REG_RED_LSB, &r) < 0 ||
            read_16bit(REG_GREEN_LSB, &g) < 0 ||
            read_16bit(REG_BLUE_LSB, &b) < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        log_data(als, r, g, b);
        control_led(als);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "Shutting down...\n");
    gpioPWM(LED_GPIO, 0);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

