#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* FXOS8700CQ I2C address (SA0 tied to GND) */
#define FXOS8700_ADDR 0x1F

/* FXOS8700CQ register addresses */
#define FXOS8700_WHO_AM_I   0x0D
#define FXOS8700_CTRL_REG1  0x2A
#define FXOS8700_XYZ_DATA_CFG 0x0E
#define FXOS8700_OUT_X_MSB  0x01

/* Expected chip ID */
#define FXOS8700_WHO_AM_I_VAL 0xC7

/* ±2g sensitivity: 4096 counts/g */
#define ACCEL_SENSITIVITY 4096.0f
#define GRAVITY 9.81f
#define IMPACT_THRESHOLD (2.0f * GRAVITY)

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* Read WHO_AM_I and verify sensor identity */
static int verify_sensor(void)
{
    int id = i2cReadByteData(i2c_handle, FXOS8700_WHO_AM_I);
    if (id < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register (pigpio error %d)\n", id);
        return -1;
    }
    if (id != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                id, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }
    return 0;
}

/* Initialize FXOS8700CQ: standby -> ±2g -> active */
static int init_fxos8700(void)
{
    /* Standby mode (clear ACTIVE bit) */
    if (i2cWriteByteData(i2c_handle, FXOS8700_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error writing CTRL_REG1 (standby)\n");
        return -1;
    }

    /* ±2g range, all axes enabled (0x00) */
    if (i2cWriteByteData(i2c_handle, FXOS8700_XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Error writing XYZ_DATA_CFG\n");
        return -1;
    }

    /* Active mode, 200 Hz ODR (0x01) */
    if (i2cWriteByteData(i2c_handle, FXOS8700_CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error writing CTRL_REG1 (active)\n");
        return -1;
    }

    return 0;
}

/* Read 6 bytes of acceleration data (OUT_X_MSB through OUT_Z_LSB) */
static int read_acceleration(float *x, float *y, float *z)
{
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, FXOS8700_OUT_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    /* 14-bit left-justified: shift right by 2, then convert to m/s^2 */
    int16_t raw_x = (int16_t)(((uint16_t)buffer[0] << 8) | (uint8_t)buffer[1]) >> 2;
    int16_t raw_y = (int16_t)(((uint16_t)buffer[2] << 8) | (uint8_t)buffer[3]) >> 2;
    int16_t raw_z = (int16_t)(((uint16_t)buffer[4] << 8) | (uint8_t)buffer[5]) >> 2;

    *x = (float)raw_x / ACCEL_SENSITIVITY * GRAVITY;
    *y = (float)raw_y / ACCEL_SENSITIVITY * GRAVITY;
    *z = (float)raw_z / ACCEL_SENSITIVITY * GRAVITY;

    return 0;
}

/* Log impact event to file */
static void log_impact(float x, float y, float z, float magnitude)
{
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening impact_log.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fclose(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X (pigpio error %d)\n",
                FXOS8700_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (verify_sensor() != 0) {
        fprintf(stderr, "FXOS8700CQ not detected or wrong chip ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_fxos8700() != 0) {
        fprintf(stderr, "FXOS8700CQ initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    while (running) {
        float x, y, z;

        if (read_acceleration(&x, &y, &z) == 0) {
            float magnitude = sqrtf(x * x + y * y + z * z);

            if (magnitude > IMPACT_THRESHOLD) {
                log_impact(x, y, z, magnitude);
                printf("Impact detected! Magnitude: %.3f m/s^2\n", magnitude);
            }
        }

        gpioDelay(50000); /* 50 ms */
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

