#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define GYRO_ADDR        0x69
#define WHO_AM_I_REG     0x0F
#define WHO_AM_I_VAL     0xD3
#define CTRL_REG1        0x20
#define CTRL_REG4        0x23
#define OUT_X_L_REG      0x28
#define NUM_CALIBRATION_SAMPLES  100
#define SAMPLE_PERIOD_US  50000   /* 50 ms -> 20 Hz */
#define THRESHOLD_DPS     50.0f
#define GYRO_SENSITIVITY  0.00875f /* dps/LSB at 250 dps full-scale */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    /* Set register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_block: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Read len bytes (auto-increment via i2c-dev ioctl) */
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_block: read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_gyro(int fd) {
    uint8_t whoami = 0;
    if (i2c_read_block(fd, WHO_AM_I_REG, &whoami, 1) != 0)
        return -1;
    if (whoami != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg8(fd, CTRL_REG1, 0x0F) != 0)
        return -1;
    if (i2c_write_reg8(fd, CTRL_REG4, 0x00) != 0)
        return -1;
    return 0;
}

static int read_gyro_data(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_L_REG, buf, 6) != 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x * GYRO_SENSITIVITY;
    *y = (float)raw_y * GYRO_SENSITIVITY;
    *z = (float)raw_z * GYRO_SENSITIVITY;
    return 0;
}

static int calibrate_gyro(int fd, float *x_offset, float *y_offset, float *z_offset) {
    float x_sum = 0.0f, y_sum = 0.0f, z_sum = 0.0f;
    float x, y, z;

    printf("Calibrating gyroscope (keep stationary)...\n");
    for (int i = 0; i < NUM_CALIBRATION_SAMPLES; i++) {
        if (read_gyro_data(fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Calibration read failed at sample %d\n", i);
            return -1;
        }
        x_sum += x;
        y_sum += y;
        z_sum += z;
        usleep(10000); /* 10 ms between samples */
    }
    *x_offset = x_sum / NUM_CALIBRATION_SAMPLES;
    *y_offset = y_sum / NUM_CALIBRATION_SAMPLES;
    *z_offset = z_sum / NUM_CALIBRATION_SAMPLES;
    printf("Calibration complete. Offsets: X=%.3f, Y=%.3f, Z=%.3f\n",
           *x_offset, *y_offset, *z_offset);
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    localtime_r(&t, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open /dev/i2c-1 failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

