#define ADXL345_ADDRESS 0x53
#define ADXL345_DEVID   0x00
#define ADXL345_POWER   0x2D
#define ADXL345_DATAX0  0x32
#define ADXL345_RANGE   0x2C
#define ADXL345_DATA_FORMAT 0x31

#define LED_GPIO 17
#define ACCEL_THRESHOLD 2.0f
#define SAMPLE_PERIOD_US 100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_adxl345(void) {
    int devid = i2cReadByteData(i2c_handle, ADXL345_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error reading DEVID register: %d\n", devid);
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Unexpected DEVID: 0x%02X (expected 0xE5)\n", devid);
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, ADXL345_RANGE, 0x00) < 0) {
        fprintf(stderr, "Error setting range register\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, ADXL345_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error setting data format register\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, ADXL345_POWER, 0x08) < 0) {
        fprintf(stderr, "Error enabling measurement mode\n");
        return -1;
    }

    return 0;
}

static int read_acceleration(float *x, float *y, float *z) {
    char raw[6];
    int16_t x_raw, y_raw, z_raw;

    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, raw, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    x_raw = (int16_t)((raw[1] << 8) | raw[0]);
    y_raw = (int16_t)((raw[3] << 8) | raw[2]);
    z_raw = (int16_t)((raw[5] << 8) | raw[4]);

    *x = (float)x_raw / 256.0f;
    *y = (float)y_raw / 256.0f;
    *z = (float)z_raw / 256.0f;

    return 0;
}

static void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(log_file);
}

static void control_led(float x, float y, float z) {
    int led_state = (fabsf(x) > ACCEL_THRESHOLD ||
                     fabsf(y) > ACCEL_THRESHOLD ||
                     fabsf(z) > ACCEL_THRESHOLD) ? 1 : 0;
    gpioWrite(LED_GPIO, led_state);
}

int main(void) {
    float x, y, z;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_adxl345() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    log_file = fopen("accel_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            log_data(x, y, z);
            control_led(x, y, z);
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    gpioWrite(LED_GPIO, 0);
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

