#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

/* LSM303DLHC I2C addresses */
#define ACCEL_ADDR 0x19
#define MAG_ADDR   0x1E

/* LSM303DLHC register addresses */
#define CTRL_REG1_A 0x20
#define MR_REG_M    0x02
#define OUT_X_L_A   0x28
#define OUT_X_H_M   0x03

/* Scaling factors */
#define ACCEL_SCALE 0.000244f  /* 1 mg/LSB at +/-2g */
#define MAG_SCALE   0.00014f   /* 0.14 mGauss/LSB */

/* Global handles for signal-safe cleanup */
static int accel_handle = -1;
static int mag_handle   = -1;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; no I2C calls in signal context      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes from accelerometer (auto-increment)                    */
/* ------------------------------------------------------------------ */
static int read_accel(int handle, float *ax, float *ay, float *az)
{
    char buf[6];
    int  rc;

    rc = i2cReadI2CBlockData(handle, OUT_X_L_A | 0x80, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Accel read failed (rc=%d)\n", rc);
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[1] << 8) | (uint8_t)buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | (uint8_t)buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | (uint8_t)buf[4]);

    *ax = (float)raw_x * ACCEL_SCALE;
    *ay = (float)raw_y * ACCEL_SCALE;
    *az = (float)raw_z * ACCEL_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes from magnetometer (auto-increment)                     */
/* ------------------------------------------------------------------ */
static int read_mag(int handle, float *mx, float *my, float *mz)
{
    char buf[6];
    int  rc;

    rc = i2cReadI2CBlockData(handle, OUT_X_H_M | 0x80, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Mag read failed (rc=%d)\n", rc);
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);

    *mx = (float)raw_x * MAG_SCALE;
    *my = (float)raw_y * MAG_SCALE;
    *mz = (float)raw_z * MAG_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Tilt-compensated heading (degrees 0-360)                             */
/* ------------------------------------------------------------------ */
static float calc_heading(float ax, float ay, float az,
                          float mx, float my, float mz)
{
    float roll  = atan2f(ay, az);
    float pitch = atan2f(-ax, sqrtf(ay * ay + az * az));

    float mx_c = mx * cosf(pitch) + mz * sinf(pitch);
    float my_c = mx * sinf(roll) * sinf(pitch) +
                 my * cosf(roll) -
                 mz * sinf(roll) * cosf(pitch);

    float heading = atan2f(my_c, mx_c) * 180.0f / (float)M_PI;
    if (heading < 0.0f)
        heading += 360.0f;
    return heading;
}

/* ------------------------------------------------------------------ */
/* Append one CSV line to the log file                                 */
/* ------------------------------------------------------------------ */
static int log_data(float heading, float ax, float ay, float az,
                    float mx, float my, float mz)
{
    FILE *fp = fopen("compass_log.txt", "a");
    if (!fp) {
        perror("fopen compass_log.txt");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                heading, ax, ay, az, mx, my, mz);
