        fprintf(fp, "1970-01-01 00:00:00,%.2f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
                heading, ax, ay, az, mx, my, mz);
    }

    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                         */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (accel_handle >= 0) {
        i2cClose(accel_handle);
        accel_handle = -1;
