#define ENABLE_MEASUREMENT 0x80
#define SAMPLE_INTERVAL_US 10000
#define LOG_FILE "audio_log.dat"

static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_sensor(int handle) {
    if (i2cWriteByteData(handle, CTRL_REG, ENABLE_MEASUREMENT) < 0) {
        fprintf(stderr, "Error writing control register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, int16_t *data) {
    int raw = i2cReadWordData(handle, DATA_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading data register: %s\n", strerror(errno));
        return -1;
    }
    *data = (int16_t)raw;
    return 0;
}

static void get_timestamp(struct timespec *ts) {
    clock_gettime(CLOCK_REALTIME, ts);
}

static void log_data(FILE *fp, struct timespec ts, int16_t s1, int16_t s2, int16_t tdoa) {
    fprintf(fp, "%ld.%09ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, s1, s2, tdoa);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
        i2c_handle2 = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

