        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    fprintf(log_file, "sec,nsec,sensor1,sensor2,tdoa\n");

    while (!terminate) {
        int16_t s1 = 0, s2 = 0;
        int ok1 = read_sensor_data(i2c_handle1, &s1);
        int ok2 = read_sensor_data(i2c_handle2, &s2);

        if (ok1 != 0 || ok2 != 0) {
            fprintf(stderr, "Error reading sensor data, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
