        struct timespec ts;
        get_timestamp(&ts);
        int16_t tdoa = s1 - s2;
        log_data(log_file, ts, s1, s2, tdoa);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

