#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

/* ADIS16488A register addresses */
#define REG_X_GYRO   0x04
#define REG_Y_GYRO   0x06
#define REG_Z_GYRO   0x08
#define REG_X_ACCEL  0x0A
#define REG_Y_ACCEL  0x0C
#define REG_Z_ACCEL  0x0E

/* SPI configuration */
#define SPI_CHANNEL  0
#define SPI_SPEED    1000000  /* 1 MHz */
#define SPI_FLAGS    0b11000000000  /* CPOL=1, CPHA=1, aux=0 */

/* Sensitivities (ADIS16488A default settings) */
#define GYRO_SENSITIVITY  0.005f   /* deg/sec/LSB */
#define ACCEL_SENSITIVITY 0.00025f /* g/LSB */

/* Timing */
#define SAMPLE_PERIOD_US  100000  /* 100 ms */
#define STALL_DELAY_US     40      /* 40 us between request and data transfer */

/* Globals for cleanup */
static int  spi_handle = -1;
static FILE *csv_file  = NULL;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs.      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called by atexit() and on normal exit.             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (csv_file != NULL) {
        fclose(csv_file);
        csv_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16488A.                         */
/* Protocol: send [0x00, addr], wait STALL_DELAY_US, then read back.   */
/* Returns 0 on success, -1 on SPI error.                             */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t addr, int16_t *out)
{
    char tx[2] = { 0x00, (char)addr };
    char rx[2] = { 0 };

    /* Request the register */
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI request failed for register 0x%02X\n", addr);
        return -1;
    }

    /* Stall delay between request and data read */
    gpioDelay(STALL_DELAY_US);

    /* Read the data back */
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI data read failed for register 0x%02X\n", addr);
        return -1;
    }

    *out = (int16_t)(((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single axis value with error checking.                       */
/* ------------------------------------------------------------------ */
static int read_axis(uint8_t addr, float *value)
{
    int16_t raw;
    if (read_register(addr, &raw) != 0)
        return -1;
    *value = (float)raw * GYRO_SENSITIVITY;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all six axis values.                                           */
/* ------------------------------------------------------------------ */
static int read_imu(float *gx, float *gy, float *gz,
                    float *ax, float *ay, float *az)
{
    if (read_axis(REG_X_GYRO,  gx) != 0 ||
        read_axis(REG_Y_GYRO,  gy) != 0 ||
        read_axis(REG_Z_GYRO,  gz) != 0 ||
        read_axis(REG_X_ACCEL, ax) != 0 ||
        read_axis(REG_Y_ACCEL, ay) != 0 ||
        read_axis(REG_Z_ACCEL, az) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample row to the CSV file.                                  */
/* ------------------------------------------------------------------ */
static void log_sample(float gx, float gy, float gz,
                       float ax, float ay, float az)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    long ms = ts.tv_nsec / 1000000L;

    fprintf(csv_file, "%s.%03ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, ms, gx, gy, gz, ax, ay, az);
    fflush(csv_file);
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open CSV */
    csv_file = fopen("imu_data.csv", "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open imu_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(csv_file, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
    fflush(csv_file);

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Cleanup on normal exit */
    atexit(cleanup);

    /* Main sampling loop */
    while (running) {
        float gx, gy, gz, ax, ay, az;

        if (read_imu(&gx, &gy, &gz, &ax, &ay, &az) == 0) {
            log_sample(gx, gy, gz, ax, ay, az);
        } else {
            fprintf(stderr, "IMU read error — sample skipped\n");
        }

        /* Non-blocking sleep so signals are caught promptly */
        uint32_t remaining = SAMPLE_PERIOD_US;
        while (remaining > 0 && running) {
            uint32_t chunk = remaining > 10000 ? 10000 : remaining;
            gpioDelay(chunk);
            remaining -= chunk;
        }
    }

    return EXIT_SUCCESS;
}

