#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "/dev/gpiochip0"
#define CS_PIN 8

#define ADIS16448_REG_XGYRO_OUT 0x04
#define ADIS16448_REG_YGYRO_OUT 0x06
#define ADIS16448_REG_ZGYRO_OUT 0x08
#define ADIS16448_REG_XACCL_OUT 0x0A
#define ADIS16448_REG_YACCL_OUT 0x0C
#define ADIS16448_REG_ZACCL_OUT 0x0E

#define GYRO_SCALE 0.02f
#define ACCL_SCALE 0.00025f

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_xfer(int fd, const uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }
    return 0;
}

static int adis_read_reg(int fd, struct gpiod_line *cs, uint8_t reg, int16_t *out) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = {0};

    if (gpiod_line_set_value(cs, 0) < 0) {
        perror("gpiod_line_set_value low");
        return -1;
    }
    if (spi_xfer(fd, tx, rx, 2) < 0) {
        gpiod_line_set_value(cs, 1);
        return -1;
    }
    if (gpiod_line_set_value(cs, 1) < 0) {
        perror("gpiod_line_set_value high");
        return -1;
    }

    uint8_t tx2[2] = {0x00, 0x00};
    uint8_t rx2[2] = {0};
    if (gpiod_line_set_value(cs, 0) < 0) {
        perror("gpiod_line_set_value low 2");
        return -1;
    }
    if (spi_xfer(fd, tx2, rx2, 2) < 0) {
        gpiod_line_set_value(cs, 1);
        return -1;
    }
    if (gpiod_line_set_value(cs, 1) < 0) {
        perror("gpiod_line_set_value high 2");
        return -1;
    }

    *out = (int16_t)((rx[0] << 8) | rx2[0]);
    return 0;
}

int main(void) {
    struct sigaction sa = { .sa_handler = sig_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
