#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16448 Register Addresses */
#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 /* 1 MHz */
#define SPI_MODE 0

/* Scaling factors */
#define GYRO_SCALE 0.05f   /* deg/sec/LSB */
#define ACCL_SCALE 0.00025f /* g/LSB */

/* Global variables */
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for Ctrl+C */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Function to read a 16-bit register from the ADIS16448 */
static int read_register(uint8_t reg_addr, int16_t *value) {
    char tx_buf[2];
    char rx_buf[2];
    int result;

    /* Set bit 15 for read command */
    tx_buf[0] = (char)(reg_addr | 0x8000);
    tx_buf[1] = 0x00;

    /* First transfer: send read command */
    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI read command failed for register 0x%02X (result=%d)\n", reg_addr, result);
        return -1;
    }

    /* Wait for data to be ready (datasheet: ~40 us stall time) */
    gpioDelay(50); /* 50 us */

    /* Second transfer: dummy write to clock out data */
    tx_buf[0] = 0x00;
    tx_buf[1] = 0x00;
    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI data read failed for register 0x%02X (result=%d)\n", reg_addr, result);
        return -1;
    }

    /* Combine the two bytes into a 16-bit signed integer */
    *value = (int16_t)(((uint16_t)rx_buf[0] << 8) | (uint8_t)rx_buf[1]);
    return 0;
}

/* Function to read gyroscope data */
static int read_gyro_data(float *gyro_x, float *gyro_y, float *gyro_z) {
    int16_t raw_x, raw_y, raw_z;

    if (read_register(X_GYRO_OUT, &raw_x) != 0) return -1;
    if (read_register(Y_GYRO_OUT, &raw_y) != 0) return -1;
    if (read_register(Z_GYRO_OUT, &raw_z) != 0) return -1;

    *gyro_x = (float)raw_x * GYRO_SCALE;
    *gyro_y = (float)raw_y * GYRO_SCALE;
    *gyro_z = (float)raw_z * GYRO_SCALE;

    return 0;
}

/* Function to read accelerometer data */
static int read_accel_data(float *accel_x, float *accel_y, float *accel_z) {
    int16_t raw_x, raw_y, raw_z;

    if (read_register(X_ACCL_OUT, &raw_x) != 0) return -1;
    if (read_register(Y_ACCL_OUT, &raw_y) != 0) return -1;
    if (read_register(Z_ACCL_OUT, &raw_z) != 0) return -1;

    *accel_x = (float)raw_x * ACCL_SCALE;
    *accel_y = (float)raw_y * ACCL_SCALE;
    *accel_z = (float)raw_z * ACCL_SCALE;

    return 0;
}

/* Cleanup function */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    float gyro_x, gyro_y, gyro_z;
    float accel_x, accel_y, accel_z;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    /* Main loop */
    while (!terminate) {
        if (read_gyro_data(&gyro_x, &gyro_y, &gyro_z) == 0 &&
            read_accel_data(&accel_x, &accel_y, &accel_z) == 0) {
            printf("Gyro: X=%.2f, Y=%.2f, Z=%.2f (deg/s)\n", gyro_x, gyro_y, gyro_z);
            printf("Accel: X=%.4f, Y=%.4f, Z=%.4f (g)\n", accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    /* Clean up and exit */
    cleanup();
    return EXIT_SUCCESS;
}

