#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6886_ADDR 0x68

#define WHO_AM_I 0x75
#define WHO_AM_I_VAL 0x86
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C burst write (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6886_init(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I\n");
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_reg8(fd, ACCEL_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, GYRO_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_raw_data(int fd, int16_t *ax, int16_t *ay, int16_t *az, int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buf[14];
    if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 14) < 0) return -1;
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    *gx = (int16_t)((buf[8] << 8) | buf[9]);
    *gy = (int16_t)((buf[10] << 8) | buf[11]);
    *gz = (int16_t)((buf[12] << 8) | buf[13]);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6886_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (mpu6886_init(i2c_fd) < 0) {
        fprintf(stderr, "MPU6886 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    printf("MPU6886 initialized. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t ax, ay, az, gx, gy, gz;
        int retries = 3;
        int success = 0;

        while (retries > 0 && running) {
            if (read_raw_data(i2c_fd, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
                success = 1;
                break;
            }
            retries--;
            if (retries > 0) usleep(10000);
        }

        if (success) {
            printf("Accel: X=%6d Y=%6d Z=%6d  Gyro: X=%6d Y=%6d Z=%6d\n", ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Failed to read sensor data after retries\n");
        }

        usleep(50000);
    }

    printf("\nExiting...\n");
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

