#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADXL345_ADDR 0x53
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_REG_FILTER_CTL 0x2C
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37
#define ADXL345_DEVID 0xE5
#define LED_PIN 17
#define IMPACT_THRESHOLD 2.5f
#define SCALE_FACTOR 256.0f
#define POLL_DELAY_US 10000
#define LED_ON_DELAY_US 500000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int adxl345_init(void) {
    int devid = i2cReadByteData(i2c_handle, ADXL345_REG_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error reading DEVID: %d\n", devid);
        return -1;
    }
    if (devid != ADXL345_DEVID) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0x%02X)\n", devid, ADXL345_DEVID);
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Error resetting ADXL345\n");
        return -1;
    }
    gpioDelay(1000);

    if (i2cWriteByteData(i2c_handle, ADXL345_REG_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error setting data format\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, ADXL345_REG_BW_RATE, 0x0F) < 0) {
        fprintf(stderr, "Error setting bandwidth rate\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error enabling measurement mode\n");
        return -1;
    }

    gpioDelay(1000);
    return 0;
}

static int read_acceleration(float *x, float *y, float *z) {
    char data[6];
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DATAX0, data, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    int16_t x_raw = (int16_t)((data[1] << 8) | data[0]);
    int16_t y_raw = (int16_t)((data[3] << 8) | data[2]);
    int16_t z_raw = (int16_t)((data[5] << 8) | data[4]);

    *x = (float)x_raw / SCALE_FACTOR;
    *y = (float)y_raw / SCALE_FACTOR;
    *z = (float)z_raw / SCALE_FACTOR;
    return 0;
}

static float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

static void log_impact(float magnitude, float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Magnitude: %.2f g, X: %.2f g, Y: %.2f g, Z: %.2f g\n",
            timestamp, magnitude, x, y, z);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (adxl345_init() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float x, y, z, magnitude;

    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > IMPACT_THRESHOLD) {
                gpioWrite(LED_PIN, 1);
                log_impact(magnitude, x, y, z);
                gpioDelay(LED_ON_DELAY_US);
                gpioWrite(LED_PIN, 0);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return 0;
}

