#define WHO_AM_I_VAL 0x12
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43
#define ACCEL_SCALE 2.0f
#define GYRO_SCALE 250.0f
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_icm20602(void) {
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake ICM-20602 (PWR_MGMT_1 write)\n");
        return -1;
    }
    gpioDelay(10000);
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set accelerometer config\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set gyroscope config\n");
        return -1;
    }
    return 0;
}

static int read_icm20602_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z,
                              int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char accel_buf[6];
    char gyro_buf[6];

    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, accel_buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read accelerometer data\n");
        return -1;
    }
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, gyro_buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        return -1;
    }

    *accel_x = (int16_t)((accel_buf[0] << 8) | accel_buf[1]);
    *accel_y = (int16_t)((accel_buf[2] << 8) | accel_buf[3]);
    *accel_z = (int16_t)((accel_buf[4] << 8) | accel_buf[5]);
    *gyro_x = (int16_t)((gyro_buf[0] << 8) | gyro_buf[1]);
    *gyro_y = (int16_t)((gyro_buf[2] << 8) | gyro_buf[3]);
    *gyro_z = (int16_t)((gyro_buf[4] << 8) | gyro_buf[5]);

    return 0;
}

static void log_data(int16_t ax, int16_t ay, int16_t az,
                     int16_t gx, int16_t gy, int16_t gz) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%ld.%09ld,%d,%d,%d,%d,%d,%d\n",
            (long)ts.tv_sec, ts.tv_nsec, ax, ay, az, gx, gy, gz);
    fflush(log_file);
}

int main(void) {
    int16_t ax, ay, az, gx, gy, gz;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at 0x%02X\n", ICM20602_ADDR);
        gpioTerminate();
        return 1;
    }

    int who = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: Could not read WHO_AM_I register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n", who, WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_icm20602() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "timestamp,accel_x,accel_y,accel_z,gyro_x,gyro_y,gyro_z\n");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        if (read_icm20602_data(&ax, &ay, &az, &gx, &gy, &gz) == 0) {
            log_data(ax, ay, az, gx, gy, gz);
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

