#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define MMA8451Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VAL 0x1A
#define OUT_X_MSB_REG 0x01
#define OUT_X_LSB_REG 0x02
#define OUT_Y_MSB_REG 0x03
#define OUT_Y_LSB_REG 0x04
#define OUT_Z_MSB_REG 0x05
#define OUT_Z_LSB_REG 0x06
#define STATUS_REG 0x00
#define STATUS_ZYXDA_BIT 0x01
#define STATUS_ZYXDA_MASK 0x07
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define CTRL_REG3 0x2C
#define CTRL_REG4 0x2D
#define CTRL_REG5 0x2E
#define CTRL_REG6 0x2F
#define DEVIATION_THRESHOLD 2.0f
#define LED_GPIO_LINE 17
#define LED_ON_DURATION_MS 500
#define POLL_INTERVAL_MS 100
#define ACCEL_SCALE 1024.0f

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451Q_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MMA8451Q_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(i2c_fd, WHO_AM_I_REG, &who_am_i) < 0) {
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (i2c_write_reg8(i2c_fd, CTRL_REG1, 0x00) < 0) { close(i2c_fd); i2c_fd = -1; return -1; }
    if (i2c_write_reg8(i2c_fd, CTRL_REG2, 0x00) < 0) { close(i2c_fd); i2c_fd = -1; return -1; }
    if (i2c_write_reg8(i2c_fd, CTRL_REG3, 0x00) < 0) { close(i2c_fd); i2c_fd = -1; return -1; }
    if (i2c_write_reg8(i2c_fd, CTRL_REG4, 0x0C) < 0) { close(i2c_fd); i2c_fd = -1; return -1; }
    if (i2c_write_reg8(i2c_fd, CTRL_REG5, 0x00) < 0) { close(i2c_fd); i2c_fd = -1; return -1; }
    if (i2c_write_reg8(i2c_fd, CTRL_REG6, 0x00) < 0) { close(i2c_fd); i2c_fd = -1; return -1; }
    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }
    led_line = gpiod_chip_get_line(chip, LED_GPIO_LINE);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(led_line, "mma8451q_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        led_line = NULL;
        return -1;
    }
    return 0;
}

static int read_acceleration(float *x, float *y, float *z) {
    uint8_t status = 0;
    if (i2c_read_reg8(i2c_fd, STATUS_REG, &status) < 0) return -1;
    if ((status & STATUS_ZYXDA_MASK) == 0) return 1;
    int16_t raw_x, raw_y, raw_z;
    if (i2c_read_reg16(i2c_fd, OUT_X_MSB_REG, &raw_x) < 0) return -1;
    if (i2c_read_reg16(i2c_fd, OUT_Y_MSB_REG, &raw_y) < 0) return -1;
    if (i2c_read_reg16(i2c_fd, OUT_Z_MSB_REG, &raw_z) < 0) return -1;
    *x = (float)raw_x / ACCEL_SCALE;
    *y = (float)raw_y / ACCEL_SCALE;
    *z = (float)raw_z / ACCEL_SCALE;
    return 0;
}

static int detect_impact(float x, float y, float z) {
    return (fabsf(x) > DEVIATION_THRESHOLD || fabsf(y) > DEVIATION_THRESHOLD || fabsf(z) > DEVIATION_THRESHOLD);
}

static void log_impact(float x, float y, float z) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Failed to open impact_log.txt: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Impact: X=%.2f, Y=%.2f, Z=%.2f\n", ts, x, y, z);
    fclose(fp);
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed.\n");
        return 1;
    }
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        cleanup();
        return 1;
    }
    printf("MMA8451Q impact detection started. Press Ctrl+C to exit.\n");
    while (running) {
        float x, y, z;
        int rc = read_acceleration(&x, &y, &z);
        if (rc < 0) {
            fprintf(stderr, "Error reading acceleration data.\n");
        } else if (rc == 0) {
            if (detect_impact(x, y, z)) {
                printf("Impact detected: X=%.2f, Y=%.2f, Z=%.2f\n", x, y, z);
                if (gpiod_line_set_value(led_line, 1) < 0) {
                    fprintf(stderr, "Failed to turn LED on: %s\n", strerror(errno));
                }
                log_impact(x, y, z);
                usleep(LED_ON_DURATION_MS * 1000);
                if (gpiod_line_set_value(led_line, 0) < 0) {
                    fprintf(stderr, "Failed to turn LED off: %s\n", strerror(errno));
                }
            }
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }
    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

