#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define LSM6DSR_ADDR 0x6A
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VAL 0x6A
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28

#define ACCEL_SCALE 0.000244f
#define GYRO_SCALE 0.00875f
#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 2.5f
#define SAMPLE_RATE_HZ 104
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} imu_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_lsm6dsr(void) {
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x40) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL1_XL\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x40) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL2_G\n");
        return -1;
    }
    return 0;
}

static int read_imu_data(imu_data_t *data) {
    char buf[12];
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buf, 12) != 12) {
        fprintf(stderr, "Error: Failed to read IMU data block\n");
        return -1;
    }
    int16_t raw_gyro_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_gyro_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_gyro_z = (int16_t)((buf[5] << 8) | buf[4]);
    int16_t raw_accel_x = (int16_t)((buf[7] << 8) | buf[6]);
    int16_t raw_accel_y = (int16_t)((buf[9] << 8) | buf[8]);
    int16_t raw_accel_z = (int16_t)((buf[11] << 8) | buf[10]);
    data->gyro_x = raw_gyro_x * GYRO_SCALE;
    data->gyro_y = raw_gyro_y * GYRO_SCALE;
    data->gyro_z = raw_gyro_z * GYRO_SCALE;
    data->accel_x = raw_accel_x * ACCEL_SCALE;
    data->accel_y = raw_accel_y * ACCEL_SCALE;
    data->accel_z = raw_accel_z * ACCEL_SCALE;
    return 0;
}

static void log_data(const imu_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            timestamp, data->accel_x, data->accel_y, data->accel_z,
            data->gyro_x, data->gyro_y, data->gyro_z);
    fflush(log_file);
}

static void detect_fall(const imu_data_t *data) {
    static int state = 0;
    static uint32_t freefall_start = 0;
    static uint32_t impact_start = 0;
    static int in_freefall = 0;
    float mag = sqrtf(data->accel_x * data->accel_x +
                      data->accel_y * data->accel_y +
                      data->accel_z * data->accel_z);
    uint32_t now = gpioTick();

    if (state == 0) {
        if (mag < FREEFALL_THRESHOLD) {
            state = 1;
            freefall_start = now;
            in_freefall = 1;
        }
    } else if (state == 1) {
        if (mag > IMPACT_THRESHOLD) {
            state = 2;
            impact_start = now;
        } else if (now - freefall_start > 1000000) {
            state = 0;
            in_freefall = 0;
        }
    } else if (state == 2) {
        if (now - impact_start > 100000) {
            state = 0;
            in_freefall = 0;
        }
    }

    if (state == 2) {
        printf("FALL DETECTED!\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    int who = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n", who, WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_lsm6dsr() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("motion_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("LSM6DSR logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        imu_data_t data;
        if (read_imu_data(&data) == 0) {
            log_data(&data);
            detect_fall(&data);
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

