#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ADIS16266 Register Addresses */
#define ADIS16266_REG_WHO_AM_I       0x00
#define ADIS16266_REG_X_GYRO_OUT     0x14

/* ADIS16266 Expected WHO_AM_I value */
#define ADIS16266_WHO_AM_I_VAL       0x3F5A

/* SPI Configuration */
#define SPI_CHANNEL    0
#define SPI_SPEED      1000000  /* 1 MHz */
#define SPI_FLAGS      0x3       /* Mode 3: CPOL=1, CPHA=1 */

/* ADIS16266 Scale Factor: 0.0305 deg/sec/LSB */
#define ADIS16266_SCALE_FACTOR 0.0305f

/* Sampling interval in microseconds (10 ms) */
#define SAMPLE_INTERVAL_US 10000

/* Global variables */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static int  adis16266_read_register(uint8_t reg_addr, uint16_t *value);
static int  adis16266_write_register(uint8_t reg_addr, uint16_t value);
static int  adis16266_init(void);
static int  adis16266_read_gyro_rate(float *gyro_rate);
static void log_data(float gyro_rate);
static void signal_handler(int signal);
static void cleanup(void);

/*
 * Read a 16-bit register from the ADIS16266.
 * The ADIS16266 requires two SPI transactions: one to send the read command
 * and one to read the response.  pigpio's spiXfer sends the data in the
 * tx buffer and fills the rx buffer with the device's response.
 */
static int adis16266_read_register(uint8_t reg_addr, uint16_t *value) {
    char tx_cmd[2], rx_cmd[2];
    char tx_data[2], rx_data[2];
    char tx_buf[4], rx_buf[4];

    /* Build read command: [reg_addr | 0x80, 0x00] */
    tx_cmd[0] = reg_addr | 0x80;
    tx_cmd[1] = 0x00;

    /* Send read command (no data payload) */
    if (spiXfer(spi_handle, tx_cmd, rx_cmd, 2) != 2) {
        fprintf(stderr, "SPI read command failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    /* Small delay between command and data read (per datasheet) */
    gpioDelay(10);

    /* Build dummy write for data read: [0x00, 0x00] */
    tx_data[0] = 0x00;
    tx_data[1] = 0x00;

    /* Read response */
    if (spiXfer(spi_handle, tx_data, rx_data, 2) != 2) {
        fprintf(stderr, "SPI data read failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    *value = ((uint16_t)(uint8_t)rx_data[0] << 8) | (uint8_t)rx_data[1];
    return 0;
}

/*
 * Write a 16-bit value to a 16-bit register on the ADIS16266.
 * The ADIS16266 requires two SPI transactions: one to send the write command
 * and one to write the data.
 */
static int adis16266_write_register(uint8_t reg_addr, uint16_t value) {
    char tx_cmd[2], rx_cmd[2];
    char tx_data[2], rx_data[2];
    char tx_buf[4], rx_buf[4];

    /* Build write command: [reg_addr & 0x7F, 0x00] */
    tx_cmd[0] = reg_addr & 0x7F;
    tx_cmd[1] = 0x00;

    /* Send write command (no data payload) */
    if (spiXfer(spi_handle, tx_cmd, rx_cmd, 2) != 2) {
        fprintf(stderr, "SPI write command failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    /* Small delay between command and data write (per datasheet) */
    gpioDelay(10);

    /* Build data to write: [high byte, low byte] */
    tx_data[0] = (value >> 8) & 0xFF;
    tx_data[1] = value & 0xFF;

    /* Read dummy to clock out the write data */
    if (spiXfer(spi_handle, tx_data, rx_data, 2) != 2) {
        fprintf(stderr, "SPI data write failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    return 0;
}

/*
 * Initialize the ADIS16266.
 * Verifies the WHO_AM_I register and sets the device to a known state.
 */
static int adis16266_init(void) {
    uint16_t who_am_i = 0;

    /* Read WHO_AM_I register */
    if (adis16266_read_register(ADIS16266_REG_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }

    /* Verify device identity */
    if (who_am_i != ADIS16266_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%04X, got 0x%04X\n",
                ADIS16266_WHO_AM_I_VAL, who_am_i);
        return -1;
    }

    printf("ADIS16266 detected (WHO_AM_I = 0x%04X)\n", who_am_i);

    /*
     * Placeholder initialization sequence.
     * The ADIS16266 requires specific register writes for proper operation.
     * Refer to the ADIS16266 datasheet for the exact initialization sequence.
     */
    if (adis16266_write_register(0x02, 0x0001) != 0) {
        fprintf(stderr, "Failed to write initialization register 0x02\n");
        return -1;
    }
    if (adis16266_write_register(0x03, 0x0002) != 0) {
        fprintf(stderr, "Failed to write initialization register 0x03\n");
        return -1;
    }

    return 0;
}

/*
 * Read the X_GYRO_OUT register and convert the raw value to degrees/sec.
 */
static int adis16266_read_gyro_rate(float *gyro_rate) {
    uint16_t raw_value = 0;

    if (adis16266_read_register(ADIS16266_REG_X_GYRO_OUT, &raw_value) != 0) {
        fprintf(stderr, "Failed to read X_GYRO_OUT register\n");
        return -1;
    }

    *gyro_rate = (float)raw_value * ADIS16266_SCALE_FACTOR;
    return 0;
}

/*
 * Log the timestamp and gyro rate to the CSV file.
 */
static void log_data(float gyro_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f\n", timestamp, gyro_rate);
    fflush(log_file);
}

/*
 * Signal handler for graceful shutdown.
 */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/*
 * Cleanup resources.
 */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", pigpio_error(spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADIS16266 */
    if (adis16266_init() != 0) {
        fprintf(stderr, "ADIS16266 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file once */
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open gyro_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,Gyro Rate (deg/sec)\n");
    fflush(log_file);

    /* Register signal handler */
    signal(SIGINT, signal_handler);

    /* Main loop */
    while (!terminate) {
        float gyro_rate = 0.0f;

        if (adis16266_read_gyro_rate(&gyro_rate) == 0) {
            log_data(gyro_rate);
        } else {
            fprintf(stderr, "Failed to read gyro rate\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

