#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* L3G4200D I2C address (SA0 tied to VDD) */
#define GYRO_ADDR 0x69

/* L3G4200D register addresses */
#define WHO_AM_I   0x0F
#define CTRL_REG1  0x20
#define CTRL_REG4  0x23
#define OUT_X_L    0x28

/* Expected device ID */
#define WHO_AM_I_VAL 0xD3

/* Sensitivity: 8.75 mdps/LSB => divide by 114.285 for dps */
#define SENSITIVITY_DPS 114.285f

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Sampling interval in microseconds (10 ms) */
#define SAMPLE_INTERVAL_US 10000

/* Retry count for I2C writes */
#define MAX_RETRIES 3

/* Global resources for signal handler */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

/* Signal handler for graceful termination */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a single byte to an I2C register with retries */
static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0) {
            return 0;
        }
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d/%d): rc=%d\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        gpioDelay(1000); /* 1 ms backoff */
    }
    return -1;
}

/* Read a single byte from an I2C register */
static int i2c_read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: rc=%d\n", reg, rc);
    }
    return rc;
}

/* Read 6 bytes of gyro data starting at OUT_X_L in one block */
static int i2c_read_gyro_data(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int rc = i2cReadI2CBlockData(handle, OUT_X_L, buffer, 6);
    if (rc != 6) {
        fprintf(stderr, "I2C block read failed: rc=%d\n", rc);
        return -1;
    }
    *x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);
    return 0;
}

/* Convert raw LSB values to degrees per second */
static gyro_data_t convert_data(int16_t raw_x, int16_t raw_y, int16_t raw_z) {
    gyro_data_t data;
    data.x = (float)raw_x / SENSITIVITY_DPS;
    data.y = (float)raw_y / SENSITIVITY_DPS;
    data.z = (float)raw_z / SENSITIVITY_DPS;
    return data;
}

/* Log data with nanosecond timestamp to CSV */
static void log_data(FILE *fp, gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%09ld,%.3f,%.3f,%.3f\n",
            timestamp, ts.tv_nsec, data.x, data.y, data.z);
    fflush(fp);
}

/* Initialize the L3G4200D: verify ID, set normal mode, +-250 dps */
static int init_gyro(int handle) {
    int id = i2c_read_reg(handle, WHO_AM_I);
    if (id < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (id != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                id, WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: enable all axes, normal mode (0x0F) */
    if (i2c_write_reg(handle, CTRL_REG1, 0x0F) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG1\n");
        return -1;
    }

    /* CTRL_REG4: +-250 dps full-scale (0x00) */
    if (i2c_write_reg(handle, CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG4\n");
        return -1;
    }

    return 0;
}

/* Cleanup all resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: rc=%d\n",
                I2C_BUS, GYRO_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize gyroscope */
    if (init_gyro(i2c_handle) != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open gyro_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header */
    fprintf(log_file, "Timestamp,X,Y,Z\n");
    fflush(log_file);

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    int16_t raw_x, raw_y, raw_z;
    gyro_data_t gyro_data;

    /* Main sampling loop */
    while (!terminate) {
        if (i2c_read_gyro_data(i2c_handle, &raw_x, &raw_y, &raw_z) == 0) {
            gyro_data = convert_data(raw_x, raw_y, raw_z);
            log_data(log_file, gyro_data);
        } else {
            fprintf(stderr, "Failed to read gyro data, skipping sample\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

