#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE "flame_events.log"
#define POLL_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler for Ctrl+C (SIGINT)                                 */
/* ------------------------------------------------------------------ */
static void signal_handler(int signal)
{
    (void)signal;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read the flame sensor.  Returns 1 if flame is detected, 0 if not,   */
/* -1 on pigpio read error.                                           */
/* ------------------------------------------------------------------ */
static int read_flame_sensor(int gpio_pin)
{
    int value = gpioRead(gpio_pin);
    if (value == PI_BAD_GPIO) {
        fprintf(stderr, "Error: gpioRead failed for GPIO %d (PI_BAD_GPIO)\n",
                gpio_pin);
        return -1;
    }
    return (value == 0) ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/* Log a timestamped event line to the log file and flush immediately.  */
/* ------------------------------------------------------------------ */
static void log_event(FILE *fp, const char *event_message)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s - %s\n", timestamp, event_message) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file: %s\n",
                strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path.                         */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
