#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x53
#define REG_X_LSB      0x28
#define REG_X_MSB      0x29
#define REG_Y_LSB      0x2A
#define REG_Y_MSB      0x2B
#define REG_Z_LSB      0x2C
#define REG_Z_MSB      0x2D
#define SAMPLE_MS      100
#define LOG_FILE       "vibration_log.csv"

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_d7s_xyz(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t xl, xh, yl, yh, zl, zh;
    if (i2c_read_reg8(fd, REG_X_LSB, &xl) < 0) return -1;
    if (i2c_read_reg8(fd, REG_X_MSB, &xh) < 0) return -1;
    if (i2c_read_reg8(fd, REG_Y_LSB, &yl) < 0) return -1;
    if (i2c_read_reg8(fd, REG_Y_MSB, &yh) < 0) return -1;
    if (i2c_read_reg8(fd, REG_Z_LSB, &zl) < 0) return -1;
    if (i2c_read_reg8(fd, REG_Z_MSB, &zh) < 0) return -1;
    *x = (int16_t)((xh << 8) | xl);
    *y = (int16_t)((yh << 8) | yl);
    *z = (int16_t)((zh << 8) | zl);
    return 0;
}

static void get_iso8601_utc(char *buf, size_t len) {
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
}

int main(void) {
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", D7S_ADDR, strerror(errno));
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "w");
    if (!fp) {
        fprintf(stderr, "fopen %s failed: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }
    fprintf(fp, "Timestamp,X,Y,Z\n");
    fflush(fp);

    printf("D7S vibration monitor started. Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        int16_t x, y, z;
        if (read_d7s_xyz(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Sensor read error; skipping sample.\n");
        } else {
            char ts[32];
            get_iso8601_utc(ts, sizeof(ts));
            fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z);
            fflush(fp);
            printf("%s  X=%d Y=%d Z=%d\n", ts, x, y, z);
        }
        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp) fclose(fp);
    if (fd >= 0) close(fd);
    return rc;
}

