#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MMA8452_ADDR   0x1D
#define WHO_AM_I       0x0D
#define WHO_AM_I_VAL   0x2A
#define CTRL_REG1      0x2A
#define OUT_X_MSB      0x01
#define OUT_X_LSB      0x02
#define OUT_Y_MSB      0x03
#define OUT_Y_LSB      0x04
#define OUT_Z_MSB      0x05
#define OUT_Z_LSB      0x06
#define TILT_THRESHOLD 45.0
#define LOG_FILE       "fall_log.txt"
#define POLL_DELAY_US  10000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int init_mma8452(int fd) {
    uint8_t who;
    if (i2c_read_reg(fd, WHO_AM_I, &who) < 0) {
        fprintf(stderr, "I2C read error (WHO_AM_I): %s\n", strerror(errno));
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }
    printf("MMA8452 detected (WHO_AM_I=0x%02X)\n", who);

    uint8_t ctrl1;
    if (i2c_read_reg(fd, CTRL_REG1, &ctrl1) < 0) {
        fprintf(stderr, "I2C read error (CTRL_REG1): %s\n", strerror(errno));
        return -1;
    }

    ctrl1 &= ~(1 << 0); /* standby */
    ctrl1 &= ~(1 << 1); /* no self-test */
    ctrl1 &= ~(1 << 2); /* no high-pass filter */
    ctrl1 &= ~(1 << 3); /* no full-res mode */
    ctrl1 &= ~(1 << 4); /* no 100 Hz mode */
    ctrl1 |=  (2 << 3); /* 100 Hz ODR */
    ctrl1 &= ~(1 << 5); /* no 100 Hz mode */
    ctrl1 &= ~(1 << 6); /* no 100 Hz mode */
    ctrl1 &= ~(1 << 7); /* no 100 Hz mode */

    if (i2c_write_reg(fd, CTRL_REG1, ctrl1) < 0) {
        fprintf(stderr, "I2C write error (CTRL_REG1 standby): %s\n", strerror(errno));
        return -1;
    }

    usleep(1000);

    ctrl1 |= (1 << 0); /* active mode */
    if (i2c_write_reg(fd, CTRL_REG1, ctrl1) < 0) {
        fprintf(stderr, "I2C write error (CTRL_REG1 active): %s\n", strerror(errno));
        return -1;
    }

    printf("MMA8452 initialized: 100 Hz ODR, active mode\n");
    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_MSB, buf, 6) < 0) {
        fprintf(stderr, "I2C block read error: %s\n", strerror(errno));
        return -1;
    }
    *x = (int16_t)(((uint16_t)buf[0] << 8) | buf[1]) >> 4;
    *y = (int16_t)(((uint16_t)buf[2] << 8) | buf[3]) >> 4;
    *z = (int16_t)(((uint16_t)buf[4] << 8) | buf[5]) >> 4;
    return 0;
}

static double calc_tilt_x(int16_t x, int16_t y, int16_t z) {
    double denom = sqrt((double)y * y + (double)z * z);
    if (denom < 1e-6) return 0.0;
    return atan2((double)x, denom) * 180.0 / M_PI;
}

static void log_fall(int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_fp, "%s, X: %d, Y: %d, Z: %d\n", ts, x, y, z);
    fflush(log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MMA8452_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", MMA8452_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_mma8452(i2c_fd) < 0) {
        fprintf(stderr, "MMA8452 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("Monitoring tilt (threshold %.1f deg)... Ctrl+C to exit.\n", TILT_THRESHOLD);

    while (running) {
        int16_t x, y, z;
        if (read_accel(i2c_fd, &x, &y, &z) < 0) {
            usleep(POLL_DELAY_US);
            continue;
        }

        double tilt = calc_tilt_x(x, y, z);
        if (fabs(tilt) > TILT_THRESHOLD) {
            log_fall(x, y, z);
        }

        usleep(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

