#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LIS3MDL_ADDR   0x1E
#define WHO_AM_I       0x0F
#define WHO_AM_I_VAL   0x3D
#define CTRL_REG1      0x20
#define CTRL_REG2      0x21
#define CTRL_REG3      0x22
#define CTRL_REG4      0x23
#define OUT_X_L        0x28
#define OUT_X_H        0x29
#define OUT_Y_L        0x2A
#define OUT_Y_H        0x2B
#define OUT_Z_L        0x2C
#define OUT_Z_H        0x2D

#define MAG_SCALE      0.146f   /* mG/LSB for +/-4 gauss */
#define METAL_THRESHOLD 800.0f  /* mG */
#define SAMPLE_HZ      10
#define SAMPLE_DELAY_US (1000000 / SAMPLE_HZ)
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read block from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int lis3mdl_init(int fd) {
    uint8_t who;
    if (i2c_read_reg(fd, WHO_AM_I, &who) < 0) return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg(fd, CTRL_REG1, 0x70) < 0) return -1; /* 80 Hz, high perf */
    if (i2c_write_reg(fd, CTRL_REG2, 0x00) < 0) return -1; /* no self-test */
    if (i2c_write_reg(fd, CTRL_REG3, 0x00) < 0) return -1; /* all axes high perf */
    if (i2c_write_reg(fd, CTRL_REG4, 0x0C) < 0) return -1; /* continuous mode */
    return 0;
}

static int read_magnetometer(int fd, float *x, float *y, float *z) {
    uint8_t raw[6];
    if (i2c_read_block(fd, OUT_X_L, raw, 6) < 0) return -1;
    int16_t x_raw = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t y_raw = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t z_raw = (int16_t)((raw[5] << 8) | raw[4]);
    *x = (float)x_raw * MAG_SCALE;
    *y = (float)y_raw * MAG_SCALE;
    *z = (float)z_raw * MAG_SCALE;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", LIS3MDL_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (lis3mdl_init(g_i2c_fd) == 0) break;
        retries++;
        if (retries < MAX_RETRIES) {
            fprintf(stderr, "Init failed, retrying (%d/%d)...\n", retries, MAX_RETRIES);
            usleep(100000);
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "LIS3MDL init failed after %d retries.\n", MAX_RETRIES);
        close(g_i2c_fd);
        return 1;
    }

    g_log_fp = fopen("magnetic_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open magnetic_log.txt: %s\n", strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("LIS3MDL initialized. Logging to magnetic_log.txt at %d Hz. Press Ctrl+C to stop.\n", SAMPLE_HZ);

    while (g_running) {
        float x, y, z;
        if (read_magnetometer(g_i2c_fd, &x, &y, &z) == 0) {
            log_data(g_log_fp, x, y, z);
            float mag = sqrtf(x * x + y * y + z * z);
            if (mag > METAL_THRESHOLD) {
                fprintf(stderr, "ALERT: Metal detected! Total field magnitude: %.2f mG\n", mag);
            }
        } else {
            fprintf(stderr, "Read error, continuing...\n");
        }
        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down cleanly...\n");
    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

