#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0

#define ADXL354B_REG_PARTID 0x01
#define ADXL354B_REG_RESET 0x1F
#define ADXL354B_REG_STATUS 0x04
#define ADXL354B_REG_POWER_CTL 0x2D
#define ADXL354B_REG_XDATA 0x08
#define ADXL354B_REG_YDATA 0x0B
#define ADXL354B_REG_ZDATA 0x0E

#define ADXL354B_PARTID_VAL 0x1D
#define ADXL354B_RESET_VAL 0x52
#define ADXL354B_POWER_CTL_RUN 0x01
#define ADXL354B_STATUS_STABLE 0x01

#define SENSITIVITY 0.0000039f
#define LOG_FILE "vibration_log.txt"
#define SAMPLE_INTERVAL_US 100000
#define SPI_RETRIES 3

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_read_register(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg | 0x80 | 0x40), 0x00 };
    char rx[2] = {0};
    int ret;

    for (int attempt = 0; attempt < SPI_RETRIES; attempt++) {
        ret = spiXfer(spi_handle, tx, rx, 2);
        if (ret == 2) {
            *value = (uint8_t)rx[1];
            return 0;
        }
        gpioDelay(1000);
    }
    return -1;
}

static int spi_write_register(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    char rx[2] = {0};
    int ret;

    for (int attempt = 0; attempt < SPI_RETRIES; attempt++) {
        ret = spiXfer(spi_handle, tx, rx, 2);
        if (ret == 2) return 0;
        gpioDelay(1000);
    }
    return -1;
}

static int read_axis(uint8_t reg, float *accel) {
    char tx[3] = { (char)(reg | 0x80 | 0x40), 0x00, 0x00 };
    char rx[3] = {0};
    int ret;

    for (int attempt = 0; attempt < SPI_RETRIES; attempt++) {
        ret = spiXfer(spi_handle, tx, rx, 3);
        if (ret == 3) break;
        gpioDelay(1000);
    }
    if (ret != 3) return -1;

    int32_t raw = ((int32_t)(uint8_t)rx[1] << 12) | ((int32_t)(uint8_t)rx[2] << 4);
    raw >>= 4;
    if (raw & 0x80000) raw |= 0xFFF00000;
    *accel = (float)raw * SENSITIVITY;
    return 0;
}

static int initialize_adxl354b(void) {
    uint8_t partid = 0;
    if (spi_read_register(ADXL354B_REG_PARTID, &partid) != 0) {
        fprintf(stderr, "Error: Failed to read PARTID register.\n");
        return -1;
    }
    if (partid != ADXL354B_PARTID_VAL) {
        fprintf(stderr, "Error: Incorrect PARTID (0x%02X, expected 0x%02X).\n", partid, ADXL354B_PARTID_VAL);
        return -1;
    }

    if (spi_write_register(ADXL354B_REG_RESET, ADXL354B_RESET_VAL) != 0) {
        fprintf(stderr, "Error: Failed to reset ADXL354B.\n");
        return -1;
    }
    gpioDelay(1000);

    uint8_t status = 0;
    int timeout = 100;
    do {
        if (spi_read_register(ADXL354B_REG_STATUS, &status) != 0) {
            fprintf(stderr, "Error: Failed to read STATUS register.\n");
            return -1;
        }
        gpioDelay(2000);
        timeout--;
    } while (!(status & ADXL354B_STATUS_STABLE) && timeout > 0);

    if (timeout == 0) {
        fprintf(stderr, "Error: ADXL354B did not stabilize.\n");
        return -1;
    }

    if (spi_write_register(ADXL354B_REG_POWER_CTL, ADXL354B_POWER_CTL_RUN) != 0) {
        fprintf(stderr, "Error: Failed to set RUN bit in POWER_CTL.\n");
        return -1;
    }
    gpioDelay(1000);
    return 0;
}

static void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %.6f g, Y: %.6f g, Z: %.6f g\n", timestamp, x, y, z);
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d).\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_adxl354b() != 0) {
        fprintf(stderr, "Error: ADXL354B initialization failed.\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL354B vibration logger started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        float x, y, z;
        if (read_axis(ADXL354B_REG_XDATA, &x) != 0 ||
            read_axis(ADXL354B_REG_YDATA, &y) != 0 ||
            read_axis(ADXL354B_REG_ZDATA, &z) != 0) {
            fprintf(stderr, "Warning: SPI read error, skipping sample.\n");
        } else {
            log_data(x, y, z);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

