#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ADIS16362 Register Addresses */
#define ADIS16362_X_GYRO   0x04
#define ADIS16362_Y_GYRO   0x06
#define ADIS16362_Z_GYRO   0x08
#define ADIS16362_X_ACCL   0x0A
#define ADIS16362_Y_ACCL   0x0C
#define ADIS16362_Z_ACCL   0x0E

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_BAUD    1000000  /* 1 MHz */
#define SPI_FLAGS   0x3      /* Mode 3: active-high, sampled on trailing edge */

/* Scaling factors */
#define GYRO_SCALE  0.05f   /* deg/sec/LSB */
#define ACCL_SCALE  0.0025f /* g/LSB */

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 10000

/* Global resources for signal handler cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (SIGINT / Ctrl+C)             */
/* ------------------------------------------------------------------ */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16362.                         */
/* Returns 0 on success, -1 on SPI transfer error.                    */
/* ------------------------------------------------------------------ */
static int read_adis16362_register(uint8_t reg_addr, int16_t *out_value) {
    char tx_buf[3];
    char rx_buf[3];
    int  bytes_read;

    /*
     * ADIS16362 SPI read protocol:
     *   1. Send the register address with MSB set (0x80 | reg_addr).
     *   2. Send one dummy byte to clock out the data.
     *   3. The 16-bit data is returned on the next 16-bit transfer.
     *
     * We perform a single 3-byte transfer where the first two bytes
     * are the address + dummy, and the third byte is the dummy for
     * the data read.  pigpio's spiXfer returns the number of bytes
     * actually transferred; we expect 3.
     */
    tx_buf[0] = (char)(0x80 | (reg_addr & 0x7F));
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;

    bytes_read = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X (read %d bytes)\n",
                reg_addr, bytes_read);
        return -1;
    }

    /*
     * The ADIS16362 returns data MSB-first.  The first transfer
     * (tx_buf[1], rx_buf[1]) clocks out the MSB of the register
     * value; the second transfer (tx_buf[2], rx_buf[2]) clocks out
     * the LSB.  We combine them into a signed 16-bit value.
     */
    *out_value = (int16_t)(((uint8_t)rx_buf[1] << 8) | (uint8_t)rx_buf[2]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single axis (gyro or accel) and convert to engineering units.*/
/* ------------------------------------------------------------------ */
static float read_axis(uint8_t reg_addr, float scale) {
    int16_t raw;
    if (read_adis16362_register(reg_addr, &raw) != 0) {
        return 0.0f;
    }
    return (float)raw * scale;
}

/* ------------------------------------------------------------------ */
/* Log one sample to the CSV file.                                      */
/* ------------------------------------------------------------------ */
static void log_data(float x_gyro, float y_gyro, float z_gyro,
                     float x_accel, float y_accel, float z_accel) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    if (fprintf(log_file, "%ld.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                (long)ts.tv_sec, ts.tv_nsec,
                x_gyro, y_gyro, z_gyro,
                x_accel, y_accel, z_accel) < 0) {
        perror("fprintf");
    }
    if (fflush(log_file) != 0) {
        perror("fflush");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path.                         */
/* ------------------------------------------------------------------ */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0, 1 MHz, Mode 3 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open imu_log.csv: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
        fflush(log_file);
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADIS16362 IMU logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (program_running) {
        float x_gyro   = read_axis(ADIS16362_X_GYRO,   GYRO_SCALE);
        float y_gyro   = read_axis(ADIS16362_Y_GYRO,   GYRO_SCALE);
        float z_gyro   = read_axis(ADIS16362_Z_GYRO,   GYRO_SCALE);
        float x_accel  = read_axis(ADIS16362_X_ACCL,  ACCL_SCALE);
        float y_accel  = read_axis(ADIS16362_Y_ACCL,  ACCL_SCALE);
        float z_accel  = read_axis(ADIS16362_Z_ACCL,  ACCL_SCALE);

        log_data(x_gyro, y_gyro, z_gyro, x_accel, y_accel, z_accel);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

