#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 27
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_timestamp(const char *msg) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo != NULL) {
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] %s\n", buffer, msg);
    } else {
        printf("[unknown time] %s\n", msg);
    }
    fflush(stdout);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *request = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    struct gpiod_line_values *vals = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line_cfg = gpiod_line_config_new();
    if (!line_cfg) {
        perror("gpiod_line_config_new");
        goto cleanup;
    }

    gpiod_line_config_reset(line_cfg);

    unsigned int offsets[2] = {SENSOR_1_PIN, SENSOR_2_PIN};
    if (gpiod_line_config_add_line_settings(line_cfg, offsets, 2, NULL) != 0) {
        perror("gpiod_line_config_add_line_settings");
        goto cleanup;
    }

    req_cfg = gpiod_request_config_new();
    if (!req_cfg) {
        perror("gpiod_request_config_new");
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "ky032-collision");

    request = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (!request) {
        perror("gpiod_chip_request_lines");
        goto cleanup;
    }

    vals = gpiod_line_values_new();
    if (!vals) {
        perror("gpiod_line_values_new");
        goto cleanup;
    }

    while (program_running) {
        if (gpiod_line_request_get_values(request, vals) != 0) {
            perror("gpiod_line_request_get_values");
            log_timestamp("Error reading sensor values");
        } else {
            int val1 = gpiod_line_values_get_value(vals, SENSOR_1_PIN);
            int val2 = gpiod_line_values_get_value(vals, SENSOR_2_PIN);

            if (val1 < 0 || val2 < 0) {
                log_timestamp("Error reading sensor values (individual)");
            } else {
                const char *msg1 = (val1 == 0) ? "Obstacle detected" : "Path clear";
                const char *msg2 = (val2 == 0) ? "Obstacle detected" : "Path clear";
                printf("Sensor 1 (GPIO%d): %s | Sensor 2 (GPIO%d): %s\n",
                       SENSOR_1_PIN, msg1, SENSOR_2_PIN, msg2);
                fflush(stdout);
            }
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    log_timestamp("Program terminated");
    ret = EXIT_SUCCESS;

cleanup:
    if (vals) gpiod_line_values_free(vals);
    if (request) gpiod_line_request_release(request);
    if (req_cfg) gpiod_request_config_free(req_cfg);
    if (line_cfg) gpiod_line_config_free(line_cfg);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

