#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define CS_GPIO_LINE 8
#define CS_CONSUMER "adis16266"

#define ADIS16266_REG_XGYRO_OUT 0x04
#define ADIS16266_REG_YGYRO_OUT 0x06
#define ADIS16266_REG_ZGYRO_OUT 0x08
#define ADIS16266_REG_MSC_CTRL 0x24

#define ADIS16266_SCALE_FACTOR 0.02f

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int fd, const uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        return -1;
    }
    return 0;
}

static int adis16266_read_register(int fd, struct gpiod_line *cs_line, uint8_t reg, uint16_t *value) {
    uint8_t tx[3] = { (uint8_t)(reg | 0x80), 0x00, 0x00 };
    uint8_t rx[3] = { 0 };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        return -1;
    }

    if (spi_transfer(fd, tx, rx, 3) < 0) {
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        return -1;
    }

    usleep(10);

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        return -1;
    }

    tx[0] = (uint8_t)(reg & 0x7F);
    rx[0] = 0;

    if (spi_transfer(fd, tx, rx, 2) < 0) {
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        return -1;
    }

    *value = ((uint16_t)rx[0] << 8) | rx[1];
    return 0;
}

static int adis16266_write_register(int fd, struct gpiod_line *cs_line, uint8_t reg, uint16_t value) {
    uint8_t tx[3] = { (uint8_t)(reg & 0x7F), (uint8_t)(value >> 8), (uint8_t)(value & 0xFF) };
    uint8_t rx[3] = { 0 };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        return -1;
    }

    if (spi_transfer(fd, tx, rx, 3) < 0) {
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        return -1;
    }

    return 0;
}

