#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR I2C 7-bit address */
#define LSM6DSR_ADDR 0x6B

/* LSM6DSR register addresses */
#define WHO_AM_I   0x0F
#define CTRL1_XL   0x10
#define CTRL2_G    0x11
#define OUTX_L_G   0x22

/* Expected WHO_AM_I value for LSM6DSR */
#define LSM6DSR_WHO_AM_I 0x6B

/* Sensitivity values (datasheet) */
#define GYRO_SENSITIVITY 0.00875f   /* mdps/LSB at +-250 dps */
#define ACCEL_SENSITIVITY 0.000061f /* mg/LSB at +-2g   */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_who_am_i(int handle, uint8_t *who_am_i)
{
    int rc = i2cReadByteData(handle, WHO_AM_I);
    if (rc < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register (pigpio rc=%d)\n", rc);
        return -1;
    }
    *who_am_i = (uint8_t)rc;
    return 0;
}

static int configure_sensor(int handle)
{
    /* CTRL1_XL: ODR=104 Hz (0100), FS=+-2g (00), BW=400 Hz (000) -> 0x42 */
    if (i2cWriteByteData(handle, CTRL1_XL, 0x42) < 0) {
        fprintf(stderr, "Error writing CTRL1_XL\n");
        return -1;
    }

    /* CTRL2_G: ODR=104 Hz (0100), FS=+-250 dps (00), FS1=0 -> 0x42 */
    if (i2cWriteByteData(handle, CTRL2_G, 0x42) < 0) {
        fprintf(stderr, "Error writing CTRL2_G\n");
        return -1;
    }

    return 0;
}

static int read_burst(int handle, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, OUTX_L_G, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "Error reading burst block (pigpio rc=%d, expected %u)\n",
                rc, len);
        return -1;
    }
    return 0;
}

static void convert_data(const int16_t *raw_g, const int16_t *raw_a,
                         float *gx, float *gy, float *gz,
                         float *ax, float *ay, float *az)
{
    *gx = (float)raw_g[0] * GYRO_SENSITIVITY;
    *gy = (float)raw_g[1] * GYRO_SENSITIVITY;
    *gz = (float)raw_g[2] * GYRO_SENSITIVITY;
    *ax = (float)raw_a[0] * ACCEL_SENSITIVITY;
    *ay = (float)raw_a[1] * ACCEL_SENSITIVITY;
    *az = (float)raw_a[2] * ACCEL_SENSITIVITY;
}

int main(void)
{
    uint8_t who_am_i = 0;
    uint8_t buf[12];
    int16_t raw_g[3], raw_a[3];
    float gx, gy, gz, ax, ay, az;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at LSM6DSR address */
    g_i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X (pigpio rc=%d)\n",
                LSM6DSR_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor identity */
    if (read_who_am_i(g_i2c_handle, &who_am_i) != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (who_am_i != LSM6DSR_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, LSM6DSR_WHO_AM_I);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure sensor */
    if (configure_sensor(g_i2c_handle) != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("LSM6DSR initialized. Reading data every 100 ms (Ctrl+C to stop)...\n");
    fflush(stdout);

    /* Main loop */
    while (g_running) {
        if (read_burst(g_i2c_handle, buf, sizeof(buf)) != 0) {
            break;
        }

        /* buf[0..2] = gyro X/Y/Z (little-endian) */
        raw_g[0] = (int16_t)((buf[1] << 8) | buf[0]);
        raw_g[1] = (int16_t)((buf[3] << 8) | buf[2]);
        raw_g[2] = (int16_t)((buf[5] << 8) | buf[4]);

        /* buf[6..8] = accel X/Y/Z (little-endian) */
        raw_a[0] = (int16_t)((buf[7] << 8) | buf[6]);
        raw_a[1] = (int16_t)((buf[9] << 8) | buf[8]);
        raw_a[2] = (int16_t)((buf[11] << 8) | buf[10]);

        convert_data(raw_g, raw_a, &gx, &gy, &gz, &ax, &ay, &az);

        printf("Gyro: X=%.2f, Y=%.2f, Z=%.2f (dps) | Accel: X=%.2f, Y=%.2f, Z=%.2f (g)\n",
               gx, gy, gz, ax, ay, az);
        fflush(stdout);

        /* 100 ms delay (microseconds) */
        gpioDelay(100000);
    }

    /* Clean shutdown */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

