 * Read a single byte register from the FXOS8700.
 * Returns the byte value (0-255) on success, or -1 on error.
 */
static int fxos8700_read_reg(int handle, uint8_t reg)
{
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

/*
 * Write a single byte to a FXOS8700 register.
 * Returns 0 on success, -1 on error.
 */
static int fxos8700_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %d\n",
                reg, value, result);
        return -1;
    }
    return 0;
}

/*
 * Initialize the FXOS8700 for hybrid mode: accelerometer + magnetometer.
 * Returns 0 on success, -1 on error.
