static int fxos8700_init(int handle)
{
    int who_am_i = fxos8700_read_reg(handle, FXOS8700_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                who_am_i, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /*
     * CTRL_REG1 (0x2A):
     *   0x00 = standby (required before configuration)
     *   0x20 = active mode
     *   0x01 = high-resolution mode (14-bit accel)
     * Combined: 0x21
     */
    if (fxos8700_write_reg(handle, FXOS8700_CTRL_REG1, 0x21) < 0)
        return -1;

    /*
     * CTRL_REG2 (0x2B):
     *   0x00 = no auto-increment, no sleep
     */
    if (fxos8700_write_reg(handle, FXOS8700_CTRL_REG2, 0x00) < 0)
        return -1;

    /*
     * M_CTRL_REG1 (0x5B):
     *   0x00 = continuous conversion mode
     */
    if (fxos8700_write_reg(handle, FXOS8700_M_CTRL_REG1, 0x00) < 0)
        return -1;

    /*
     * M_CTRL_REG2 (0x5C):
     *   0x00 = 8-average, 100 Hz ODR
     */
    if (fxos8700_write_reg(handle, FXOS8700_M_CTRL_REG2, 0x00) < 0)
        return -1;

    return 0;
}

