#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAZ0 0x36

// Tilt threshold in degrees
#define TILT_THRESHOLD 30.0

// Log file path
#define LOG_FILE "/var/log/tilt_events.log"

// I2C device path
#define I2C_DEVICE "/dev/i2c-1"

// Global variables for I2C file descriptor and program termination flag
static int i2c_fd = -1;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_init(const char *device, int address);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len);
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z);
double calculate_tilt_angle(int16_t x, int16_t y, int16_t z);
void log_tilt_event(double angle);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

// Initialize I2C device
int i2c_init(const char *device, int address) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", device, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", address, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Write a byte to an I2C register
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Read multiple bytes from an I2C register
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "Error reading %zu bytes from register 0x%02X: %s\n", len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Read acceleration data from ADXL345
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_bytes(fd, ADXL345_DATAX0, buf, 6) < 0) {
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Calculate tilt angle in degrees
double calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    double x_angle = atan2((double)y, sqrt((double)x * x + (double)z * z)) * 180.0 / M_PI;
    double y_angle = atan2((double)x, sqrt((double)y * y + (double)z * z)) * 180.0 / M_PI;
    return x_angle > y_angle ? x_angle : y_angle;
}

// Log tilt event to file
void log_tilt_event(double angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: Tilt angle exceeded threshold (%.2f degrees)\n", timestamp, angle);
    fclose(fp);
}

int main() {
    // Register signal handler for Ctrl+C
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_DEVICE, ADXL345_ADDRESS);
    if (i2c_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize ADXL345: enable measurement mode
    if (i2c_write_byte(i2c_fd, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Failed to initialize ADXL345. Check wiring and sensor presence.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXL345 initialized. Monitoring tilt events...\n");

    // Main loop
    while (program_running) {
        int16_t x, y, z;

        if (read_acceleration(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read acceleration data. Retrying...\n");
            usleep(100000);
            continue;
        }

        double angle = calculate_tilt_angle(x, y, z);

        if (angle > TILT_THRESHOLD) {
            log_tilt_event(angle);
        }

        usleep(100000); // 100 ms delay
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

