#include <unistd.h>
#include <pigpio.h>

#define SENSOR_GPIO 17
#define SAMPLE_INTERVAL_US 1000   /* 1 ms between samples */
#define MONITOR_WINDOW_SEC 5      /* 5-second monitoring window */
#define WINDOW_SAMPLES (MONITOR_WINDOW_SEC * 1000 / 1000) /* 5000 */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buffer[80];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &timeinfo);
    printf("[%s] ", buffer);
}

int main(int argc, char *argv[])
{
    int threshold = 0;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold_count>\n", argv[0]);
        fprintf(stderr, "  threshold_count: minimum high-readings per 5-second window (positive integer)\n");
        return EXIT_FAILURE;
    }

    threshold = atoi(argv[1]);
    if (threshold <= 0) {
        fprintf(stderr, "Error: threshold must be a positive integer.\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring KY-038 sound sensor on GPIO%d. Threshold: %d high-readings per 5-second window.\n",
           SENSOR_GPIO, threshold);
    printf("Press Ctrl+C to exit.\n");

