        } else {
            printf("Status: %d high-readings in %d ms (%.1f%%)\n",
                   high_count, sample_count,
                   (sample_count > 0) ? ((float)high_count / sample_count) * 100.0f : 0.0f);
        }
        fflush(stdout);

        /* Sleep for the remainder of the 5-second window, but wake early on signal */
        int remaining_ms = (MONITOR_WINDOW_SEC * 1000) - elapsed_ms;
        if (remaining_ms > 0) {
            gpioDelay(remaining_ms * 1000);
        }
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

