/*
 * door_access.c — libgpiod-based door-lock controller for Raspberry Pi 4
 *
 * Build:  gcc -Wall -o door_access door_access.c -lgpiod
 * Run:    ./door_access
 *
 * Hardware:
 *   Door A  relay + TIP120 on GPIO17 (active-HIGH: HIGH = de-energized = unlocked)
 *   Door B  relay + TIP120 on GPIO27
 *   Locks are energized (closed) when the line is LOW.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define DOOR_A_PIN  17
#define DOOR_B_PIN  27
#define UNLOCK_SEC  5
#define LOG_FILE    "access_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int generate_code(void)
{
    return (rand() % 900000) + 100000;
}

static int log_access(int code)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%06d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, code);

    if (fclose(fp) != 0) {
        perror("fclose(log)");
        return -1;
    }
    return 0;
}

static int unlock_door(struct gpiod_line *line, int duration_sec)
{
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value(UNLOCK)");
        return -1;
    }
    printf("Door unlocked for %d seconds.\n", duration_sec);

    for (int i = 0; i < duration_sec && g_running; i++)
        sleep(1);

    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value(LOCK)");
        return -1;
    }
    printf("Door re-locked.\n");
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_a = NULL, *line_b = NULL;
    int code = 0;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto out;

    srand((unsigned)time(NULL));
    code = generate_code();
    printf("Current security code: %06d\n", code);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name(gpiochip4)");
        goto out;
    }

    line_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!line_a) {
        perror("gpiod_chip_get_line(DOOR_A_PIN)");
        goto cleanup_chip;
    }

    line_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!line_b) {
        perror("gpiod_chip_get_line(DOOR_B_PIN)");
        goto cleanup_chip;
    }

    if (gpiod_line_request_output(line_a, "door_access", 0) < 0) {
        perror("gpiod_line_request_output(DOOR_A)");
        goto cleanup_chip;
    }

    if (gpiod_line_request_output(line_b, "door_access", 0) < 0) {
        perror("gpiod_line_request_output(DOOR_B)");
        goto release_line_a;
    }

    printf("Door access system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        printf("Enter security code: ");
        fflush(stdout);

        char input[32];
        if (!fgets(input, sizeof(input), stdin)) {
            if (feof(stdin)) {
                printf("\nEOF received, exiting.\n");
                break;
            }
            perror("fgets");
            continue;
        }

        int entered = atoi(input);
        if (entered == code) {
            printf("Access granted.\n");
            if (unlock_door(line_a, UNLOCK_SEC) != 0)
                break;
            if (log_access(code) != 0)
                fprintf(stderr, "Warning: failed to log access.\n");
            code = generate_code();
            printf("New security code: %06d\n", code);
        } else {
            printf("Access denied.\n");
        }
    }

    rc = EXIT_SUCCESS;

release_line_a:
    gpiod_line_release(line_a);
cleanup_chip:
    gpiod_line_release(line_b);
    gpiod_chip_close(chip);
out:
    /* Ensure both locks are re-energized (LOW) on exit */
    if (line_a)
        gpiod_line_set_value(line_a, 0);
    if (line_b)
        gpiod_line_set_value(line_b, 0);
    return rc;
}

