    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    while (running) {
        float lux;
        if (read_bh1750(i2c_fd, &lux) == 0) {
            log_data(lux);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

