    if (i2cWriteByteData(handle, 0x0C, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, 0x0B, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, 0x0A, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, 0x09, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, 0x08, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, 0x07, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, 0x06, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, 0x05, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, 0x04, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, 0x03, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, 0x02, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, 0x01, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, 0x00, 0x00) < 0) return -1;
    return 0;
}

static int read_touch_data(int handle, int *touch_values) {
    char buf[24];
    if (i2cReadI2CBlockData(handle, 0x00, buf, 24) != 24) return -1;
    for (int i = 0; i < NUM_ELECTRODES; i++) {
        touch_values[i] = (buf[2 * i] << 8) | buf[2 * i + 1];
    }
    return 0;
}

static float map_to_frequency(int max_touch) {
    float normalized = (float)max_touch / 4095.0f;
    return MIN_FREQ + (MAX_FREQ - MIN_FREQ) * normalized;
}

static void log_frequency(float freq) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, %.2f Hz\n", ts, freq);
    fclose(fp);
}

static void cleanup(void) {
    if (client_fd >= 0) { close(client_fd); client_fd = -1; }
    if (server_fd >= 0) { close(server_fd); server_fd = -1; }
    if (i2c_handle >= 0) { i2cClose(i2c_handle); i2c_handle = -1; }
    gpioPWM(PWM_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 init failed\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        cleanup();
        return 1;
    }
    gpioSetPWMfrequency(PWM_GPIO, 1000);
    gpioPWM(PWM_GPIO, 0);

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        cleanup();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        cleanup();
        return 1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen");
        cleanup();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);

    while (running) {
        struct sockaddr_in caddr;
        socklen_t clen = sizeof(caddr);
        client_fd = accept(server_fd, (struct sockaddr *)&caddr, &clen);
        if (client_fd < 0) {
            if (errno == EINTR) continue;
            perror("accept");
            break;
        }

        char buf[1024];
        ssize_t n = recv(client_fd, buf, sizeof(buf) - 1, 0);
        if (n <= 0) {
            close(client_fd);
            client_fd = -1;
            continue;
        }
        buf[n] = '\0';

        if (strncmp(buf, "MOTION_DETECTED:", 16) != 0) {
            close(client_fd);
            client_fd = -1;
            continue;
        }

        char *key = strstr(buf, SECRET_KEY);
        if (!key || key + strlen(SECRET_KEY) != buf + strlen(buf)) {
            close(client_fd);
            client_fd = -1;
            continue;
        }

        printf("Motion detected, playing for %d seconds...\n", PLAYBACK_DURATION_S);
        int touch_values[NUM_ELECTRODES];
        int max_touch = 0;
        for (int i = 0; i < PLAYBACK_DURATION_S * 10 && running; i++) {
            if (read_touch_data(i2c_handle, touch_values) < 0) {
                fprintf(stderr, "I2C read error\n");
                break;
            }
            for (int j = 0; j < NUM_ELECTRODES; j++) {
                if (touch_values[j] > max_touch) max_touch = touch_values[j];
            }
            float freq = map_to_frequency(max_touch);
            gpioSetPWMfrequency(PWM_GPIO, (int)freq);
            gpioPWM(PWM_GPIO, 128);
            log_frequency(freq);
            gpioDelay(SAMPLE_INTERVAL_US);
        }

        gpioPWM(PWM_GPIO, 0);
        close(client_fd);
        client_fd = -1;
    }

    cleanup();
    return 0;
}

