#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// LSM303DLHC I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC registers
#define LSM303_OUT_X_L_M 0x08
#define LSM303_CTRL_REG1_M 0x20

// GPIO and PWM configuration
#define GPIO_CHIP "/dev/gpiochip0"
#define LED_PIN 17
#define PWM_PERIOD_NS 10000000  // 10 ms period (100 Hz)

// Global variables for cleanup
static int i2c_fd = -1;
static struct gpiod_line *led_line = NULL;
static struct gpiod_chip *chip = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

// Function prototypes
int init_i2c(void);
int init_magnetometer(void);
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z);
void set_led_brightness(int brightness);
void cleanup(void);
void signal_handler(int sig);

// Initialize I2C bus
int init_i2c(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

// Initialize LSM303DLHC magnetometer
int init_magnetometer(void) {
    // Set to 10 Hz continuous conversion mode
    uint8_t ctrl_reg1_m = 0x18; // 10 Hz, continuous conversion
    if (write(i2c_fd, &ctrl_reg1_m, 1) != 1) {
        fprintf(stderr, "Failed to write CTRL_REG1_M: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read magnetometer data (X, Y, Z)
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t reg = LSM303_OUT_X_L_M;
    uint8_t data[6];

    // Write register address
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Failed to write register address: %s\n", strerror(errno));
        return -1;
    }

    // Read 6 bytes of data
    if (read(i2c_fd, data, 6) != 6) {
        fprintf(stderr, "Failed to read magnetometer data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes (little-endian)
    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Set LED brightness using hardware PWM via libgpiod
void set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;

    // Calculate duty cycle in nanoseconds (0-10,000,000 for 10 Hz)
    long duty_ns = (long)brightness * PWM_PERIOD_NS / 255;

    // Set line value to high
    if (gpiod_line_set_value(led_line, 1) < 0) {
        fprintf(stderr, "Failed to set line high: %s\n", strerror(errno));
        return;
    }

    // Set line PWM period
    if (gpiod_line_set_config(led_line, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT, 0, 0) < 0) {
        fprintf(stderr, "Failed to set line config: %s\n", strerror(errno));
        return;
    }

    // Use nanosleep to achieve PWM (simple blocking approach)
    // Note: This is a simplified blocking PWM. For production, use a hardware PWM peripheral.
    struct timespec on_time = {0, duty_ns};
    struct timespec off_time = {0, PWM_PERIOD_NS - duty_ns};

    nanosleep(&on_time, NULL);
    gpiod_line_set_value(led_line, 0);
    nanosleep(&off_time, NULL);
}

// Cleanup resources
void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    // Open log file
    log_file = fopen("magnetometer_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize magnetometer
    if (init_magnetometer() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO using libgpiod
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Request line for output
    if (gpiod_line_request_output(led_line, "led_pwm", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Magnetometer data acquisition started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int16_t x, y, z;

        // Read magnetometer data
        if (read_magnetometer(&x, &y, &z) == 0) {
            // Compute Z-axis magnitude (absolute value)
            int z_magnitude = abs(z);

            // Map Z-axis magnitude to LED brightness (0-255)
            int brightness = (int)((float)z_magnitude / 32768.0 * 255.0);
            if (brightness > 255) brightness = 255;

            // Set LED brightness
            set_led_brightness(brightness);

            // Log data
            fprintf(log_file, "X: %d, Y: %d, Z: %d, Magnitude: %d, Brightness: %d\n", x, y, z, z_magnitude, brightness);
            fflush(log_file);
        } else {
            fprintf(stderr, "Error reading magnetometer data. Skipping sample.\n");
        }

        // Delay 100 ms
        usleep(100000);
    }

    // Cleanup
    cleanup();
    printf("Exiting gracefully.\n");
    return 0;
}

