#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HMC5883L_ADDR 0x1E
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

#define SAMPLE_WINDOW 100
#define SAMPLE_DELAY_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

static int16_t x_offset = 0;
static int16_t y_offset = 0;
static int16_t z_offset = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_magnetometer(void) {
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to Configuration Register A\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to Configuration Register B\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to Mode Register\n");
        return -1;
    }
    return 0;
}

static int read_magnetometer_data(magnetometer_data_t *data) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    data->x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->z = (int16_t)((buffer[2] << 8) | buffer[3]);
    data->y = (int16_t)((buffer[4] << 8) | buffer[5]);
    return 0;
}

static void update_offsets(magnetometer_data_t raw_data) {
    x_offset += raw_data.x;
    y_offset += raw_data.y;
    z_offset += raw_data.z;
}

static void apply_offsets(magnetometer_data_t raw_data, magnetometer_data_t *corrected) {
    corrected->x = raw_data.x - x_offset;
    corrected->y = raw_data.y - y_offset;
    corrected->z = raw_data.z - z_offset;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_magnetometer() < 0) {
        fprintf(stderr, "Magnetometer initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    magnetometer_data_t raw_data, corrected_data;
    int sample_count = 0;

    while (running) {
        if (read_magnetometer_data(&raw_data) == 0) {
            update_offsets(raw_data);
            if (sample_count >= SAMPLE_WINDOW) {
                x_offset /= SAMPLE_WINDOW;
                y_offset /= SAMPLE_WINDOW;
                z_offset /= SAMPLE_WINDOW;
            }
            apply_offsets(raw_data, &corrected_data);
            printf("X: %d, Y: %d, Z: %d\n", corrected_data.x, corrected_data.y, corrected_data.z);
            fflush(stdout);
            sample_count++;
        } else {
            fprintf(stderr, "Failed to read magnetometer data\n");
        }
        usleep(SAMPLE_DELAY_US);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

