/*
 * LSM303D accelerometer monitor for Raspberry Pi Zero W.
 *
 * I2C:  /dev/i2c-1, LSM303D at 0x1D (SA0 tied high)
 * GPIO: libgpiod line request on GPIO23 (BCM 23, physical pin 16) for INT1.
 *
 * Build: gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

/* ---- LSM303D constants (accelerometer) ---- */
#define LSM303D_ADDR        0x1D
#define WHO_AM_I            0x0F
#define WHO_AM_I_VAL        0x49
#define CTRL_REG1           0x20
#define CTRL_REG4           0x23
#define INT1_CFG            0x30
#define INT1_THS            0x31
#define INT1_DURATION       0x32
#define OUT_X_L_A           0x28
#define AUTO_INC_MASK       0x80

/* ---- GPIO / timing ---- */
#define GPIO_CHIP           "gpiochip0"
#define GPIO_LINE           23          /* BCM 23, physical pin 16 */
#define BUFFER_SIZE         64
#define SAMPLE_PERIOD_US    10000       /* 10 ms */
#define INT_DUMP_COUNT      10

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_line = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (i2c_smbus_read_byte_data(fd, reg) < 0) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint8_t)i2c_smbus_read_byte_data(fd, reg);
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    if (i2c_smbus_write_byte_data(fd, reg, val) < 0) {
        fprintf(stderr, "I2C write reg 0x%02X = 0x%02X failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (i2c_smbus_read_i2c_block_data(fd, reg | AUTO_INC_MASK, len, buf) < 0) {
        fprintf(stderr, "I2C block read reg 0x%02X (%zu bytes) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_lsm303d(int fd)
{
    uint8_t who;

    if (i2c_read_reg8(fd, WHO_AM_I, &who) < 0)
        return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* 50 Hz ODR, XYZ axes enabled */
    if (i2c_write_reg8(fd, CTRL_REG1, 0x57) < 0)
        return -1;

    /* +-2g full-scale, high-resolution disabled */
    if (i2c_write_reg8(fd, CTRL_REG4, 0x00) < 0)
        return -1;

    /* Threshold: 2000 mg -> register value = 2000 / 16 = 125 = 0x7D */
    if (i2c_write_reg8(fd, INT1_THS, 0x7D) < 0)
        return -1;

    /* Duration: 0 (immediate) */
    if (i2c_write_reg8(fd, INT1_DURATION, 0x00) < 0)
        return -1;

    /* Any-axis-high event */
    if (i2c_write_reg8(fd, INT1_CFG, 0x2A) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_accel(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_block(fd, OUT_X_L_A, buf, sizeof(buf)) < 0)
        return -1;

    raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    /* +-2g full-scale -> 0.061 mg/LSB */
    *x = (float)raw_x * 0.061f / 1000.0f;
    *y = (float)raw_y * 0.061f / 1000.0f;
    *z = (float)raw_z * 0.061f / 1000.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
static void dump_buffer(float *buf, int count)
{
    printf("--- INT1 event ---\n");
    for (int i = 0; i < count && i < BUFFER_SIZE; i++) {
        printf("  [%3d] X=%.3f Y=%.3f Z=%.3f\n",
               i, buf[i * 3], buf[i * 3 + 1], buf[i * 3 + 2]);
    }
    printf("--- end dump ---\n");
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_line) {
        gpiod_line_release(g_line);
        g_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Disable accelerometer before closing */
        (void)i2c_write_reg8(g_i2c_fd, CTRL_REG1, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    float accel[BUFFER_SIZE][3];
    int   buf_idx = 0;
    int   buf_count = 0;
    struct timespec ts;

    /* ---- I2C ---- */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open /dev/i2c-1 failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                LSM303D_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_lsm303d(g_i2c_fd) < 0) {
        fprintf(stderr, "LSM303D initialization failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- GPIO (libgpiod) ---- */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open(%s) failed: %s\n",
                GPIO_CHIP, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    g_line = gpiod_chip_get_line(g_chip, GPIO_LINE);
    if (!g_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                GPIO_LINE, strerror(errno));
        gpiod_chip_close(g_chip);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_rising_edge_events(g_line, "lsm303d_int1") < 0) {
        fprintf(stderr, "gpiod_line_request_rising_edge_events failed: %s\n",
                strerror(errno));
        gpiod_line_release(g_line);
        gpiod_chip_close(g_chip);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- Signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction SIGINT failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LSM303D monitoring started. Press Ctrl-C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        float x, y, z;

        if (read_accel(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Warning: accelerometer read failed, skipping sample\n");
        } else {
            accel[buf_idx][0] = x;
            accel[buf_idx][1] = y;
            accel[buf_idx][2] = z;
            buf_idx = (buf_idx + 1) % BUFFER_SIZE;
            if (buf_count < BUFFER_SIZE)
                buf_count++;
        }

        /* Poll for INT1 rising edge (non-blocking) */
        struct timespec poll_ts = {0, 100000}; /* 100 ms */
        int ev = gpiod_line_event_wait(g_line, &poll_ts);
        if (ev < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "gpiod_line_event_wait error: %s\n", strerror(errno));
            break;
        }
        if (ev > 0) {
            struct gpiod_line_event event;
            if (gpiod_line_event_read(g_line, &event) < 0) {
                fprintf(stderr, "gpiod_line_event_read error: %s\n", strerror(errno));
                continue;
            }
            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                clock_gettime(CLOCK_REALTIME, &ts);
                printf("INT1 rising edge at %ld.%09ld\n",
                       (long)ts.tv_sec, ts.tv_nsec);
                dump_buffer(accel, buf_count);
            }
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

