        if (read_accel(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Warning: accelerometer read failed, skipping sample\n");
        } else {
            accel[buf_idx][0] = x;
            accel[buf_idx][1] = y;
            accel[buf_idx][2] = z;
            buf_idx = (buf_idx + 1) % BUFFER_SIZE;
            if (buf_count < BUFFER_SIZE)
                buf_count++;
        }

        /* Poll for INT1 rising edge (non-blocking) */
        struct timespec poll_ts = {0, 100000}; /* 100 ms */
        int ev = gpiod_line_event_wait(g_line, &poll_ts);
        if (ev < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "gpiod_line_event_wait error: %s\n", strerror(errno));
            break;
        }
        if (ev > 0) {
            struct gpiod_line_event event;
            if (gpiod_line_event_read(g_line, &event) < 0) {
                fprintf(stderr, "gpiod_line_event_read error: %s\n", strerror(errno));
                continue;
            }
            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                clock_gettime(CLOCK_REALTIME, &ts);
                printf("INT1 rising edge at %ld.%09ld\n",
                       (long)ts.tv_sec, ts.tv_nsec);
                dump_buffer(accel, buf_count);
            }
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

