#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define SOLENOID1_PIN 17
#define SOLENOID2_PIN 27
#define DELAY_MS 500
#define CONSUMER "reciprocating_actuator"

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static int set_line(struct gpiod_line *line, int val) {
    if (gpiod_line_set_value(line, val) < 0) {
        fprintf(stderr, "Failed to set line value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void delay_ms(int ms) {
