#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <time.h>
#include <pigpio.h>

#define LOCK_1_GPIO 17
#define LOCK_2_GPIO 27
#define EXPECTED_CODE "123456"
#define CODE_LENGTH 6
#define SERIAL_PORT_1 "/dev/serial0"
#define SERIAL_PORT_2 "/dev/serial1"
#define BAUD_RATE B9600
#define TIMEOUT_SEC 5
#define UNLOCK_DURATION_SEC 2

static volatile sig_atomic_t running = 1;
static int ser_fd1 = -1;
static int ser_fd2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_serial(const char *port, int baud) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", port, strerror(errno));
        return -1;
    }
    if (fcntl(fd, F_SETFL, 0) < 0) {
        fprintf(stderr, "Error clearing O_NDELAY on %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr on %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }
    cfsetispeed(&tty, baud);
    cfsetospeed(&tty, baud);
    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHONL | ISIG | IEXTEN);
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;
    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr on %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }
    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_serial_code(int fd, char *code, size_t max_len) {
    code[0] = '\0';
    size_t idx = 0;
    time_t start = time(NULL);
    while (running) {
        if (time(NULL) - start > TIMEOUT_SEC) {
            return -1;
        }
        char ch;
        ssize_t n = read(fd, &ch, 1);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            fprintf(stderr, "Error reading from serial port: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            continue;
        }
        if (ch >= '0' && ch <= '9') {
            if (idx < max_len - 1) {
                code[idx++] = ch;
            }
        } else {
            if (idx > 0) {
                code[idx] = '\0';
                idx = 0;
            }
        }
        if (idx == CODE_LENGTH) {
            code[idx] = '\0';
            return 0;
        }
    }
    return -1;
}

static int compare_code(const char *a, const char *b) {
    if (strlen(a) != strlen(b)) {
        return 0;
    }
    int result = 0;
    for (size_t i = 0; i < strlen(a); i++) {
        result |= (unsigned char)(a[i] ^ b[i]);
    }
    return (result == 0);
}

static int unlock_doors(void) {
    if (gpioWrite(LOCK_1_GPIO, 1) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", LOCK_1_GPIO);
        return -1;
    }
    if (gpioWrite(LOCK_2_GPIO, 1) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", LOCK_2_GPIO);
        gpioWrite(LOCK_1_GPIO, 0);
        return -1;
    }
    return 0;
}

static int lock_doors(void) {
    if (gpioWrite(LOCK_1_GPIO, 0) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", LOCK_1_GPIO);
        return -1;
    }
    if (gpioWrite(LOCK_2_GPIO, 0) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", LOCK_2_GPIO);
        gpioWrite(LOCK_1_GPIO, 0);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (ser_fd1 >= 0) {
        close(ser_fd1);
        ser_fd1 = -1;
    }
    if (ser_fd2 >= 0) {
        close(ser_fd2);
        ser_fd2 = -1;
    }
    lock_doors();
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    if (gpioSetMode(LOCK_1_GPIO, PI_OUTPUT) != 0 || gpioSetMode(LOCK_2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO modes\n");
        gpioTerminate();
        return 1;
    }
    if (lock_doors() != 0) {
        fprintf(stderr, "Error locking doors on startup\n");
        gpioTerminate();
        return 1;
    }
    ser_fd1 = init_serial(SERIAL_PORT_1, BAUD_RATE);
    if (ser_fd1 < 0) {
        gpioTerminate();
        return 1;
    }
    ser_fd2 = init_serial(SERIAL_PORT_2, BAUD_RATE);
    if (ser_fd2 < 0) {
        close(ser_fd1);
        ser_fd1 = -1;
        gpioTerminate();
        return 1;
    }
    char code1[CODE_LENGTH + 1];
    char code2[CODE_LENGTH + 1];
    int code1_ready = 0;
    int code2_ready = 0;
    while (running) {
        if (!code1_ready) {
            int rc = read_serial_code(ser_fd1, code1, sizeof(code1));
            if (rc == 0) {
                code1_ready = 1;
            } else if (rc < 0) {
                fprintf(stderr, "Timeout reading code from port 1\n");
                code1_ready = 0;
            }
        }
        if (!code2_ready) {
            int rc = read_serial_code(ser_fd2, code2, sizeof(code2));
            if (rc == 0) {
                code2_ready = 1;
            } else if (rc < 0) {
                fprintf(stderr, "Timeout reading code from port 2\n");
                code2_ready = 0;
            }
        }
        if (code1_ready && code2_ready) {
            if (compare_code(code1, code2) && compare_code(code1, EXPECTED_CODE)) {
                printf("Codes match! Unlocking doors...\n");
                if (unlock_doors() == 0) {
                    sleep(UNLOCK_DURATION_SEC);
                    if (lock_doors() != 0) {
                        fprintf(stderr, "Error re-locking doors after unlock\n");
                    } else {
                        printf("Doors re-locked.\n");
                    }
                } else {
                    fprintf(stderr, "Error unlocking doors\n");
                }
            } else {
                fprintf(stderr, "Codes do not match or are incorrect.\n");
            }
            code1_ready = 0;
            code2_ready = 0;
        }
        usleep(100000);
    }
    cleanup();
    return 0;
}

