#define PIR_PIN 4
#define RELAY_PIN 17
#define STRIKE_DURATION_MS 1000
#define POLL_INTERVAL_MS 50
#define FAILSAFE_TIMEOUT_S 10

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(priority, "%s: %s", timestamp, message);
}

int main(void) {
    openlog("door_strike", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to register signal handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get PIR line %d: %s", PIR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get relay line %d: %s", RELAY_PIN, strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(pir_line, "door_strike_pir") < 0) {
        syslog(LOG_ERR, "Failed to request PIR line as input: %s", strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "door_strike_relay", 0) < 0) {
        syslog(LOG_ERR, "Failed to request relay line as output: %s", strerror(errno));
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    log_event(LOG_INFO, "Door strike system started.");

    time_t motion_start = 0;
    int relay_state = 0;

    while (program_running) {
        int pir_value = gpiod_line_get_value(pir_line);
