                motion_start = time(NULL);
                log_event(LOG_INFO, "Motion detected.");
            }

            if (relay_state == 0) {
                if (gpiod_line_set_value(relay_line, 1) < 0) {
                    syslog(LOG_ERR, "Failed to energize relay: %s", strerror(errno));
                } else {
                    relay_state = 1;
                    log_event(LOG_INFO, "Relay energized (strike activated).");
                }
            }

            if (difftime(time(NULL), motion_start) > FAILSAFE_TIMEOUT_S) {
                syslog(LOG_WARNING, "Failsafe triggered: PIR stuck HIGH for %d seconds. De-energizing relay.", FAILSAFE_TIMEOUT_S);
                if (gpiod_line_set_value(relay_line, 0) < 0) {
                    syslog(LOG_ERR, "Failed to de-energize relay during failsafe: %s", strerror(errno));
                } else {
                    relay_state = 0;
                    log_event(LOG_INFO, "Relay de-energized (failsafe).");
                }
                motion_start = 0;
            }
        } else {
            if (motion_start != 0) {
                if (relay_state == 1) {
                    if (gpiod_line_set_value(relay_line, 0) < 0) {
                        syslog(LOG_ERR, "Failed to de-energize relay: %s", strerror(errno));
                    } else {
                        relay_state = 0;
                        log_event(LOG_INFO, "Relay de-energized (strike ended).");
                    }
                }
                motion_start = 0;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    log_event(LOG_INFO, "Shutting down door strike system.");

    if (relay_state == 1) {
        if (gpiod_line_set_value(relay_line, 0) < 0) {
            syslog(LOG_ERR, "Failed to de-energize relay on shutdown: %s", strerror(errno));
        }
    }

    gpiod_line_release(pir_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    closelog();

    return EXIT_SUCCESS;
}

