#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <string.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define RELAY_ON_TIME_SEC 300
#define RELAY_PAUSE_SEC 60
#define TIMER_INTERVAL_SEC 60

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(int relay_pin, int state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "Relay on GPIO%d %s", relay_pin, state ? "activated" : "deactivated");
}

static void activate_relay(int relay_pin) {
    if (gpioWrite(relay_pin, 0) != 0) {
        syslog(LOG_ERR, "Failed to activate relay on GPIO%d", relay_pin);
        return;
    }
    log_event(relay_pin, 1);
}

static void deactivate_relay(int relay_pin) {
    if (gpioWrite(relay_pin, 1) != 0) {
        syslog(LOG_ERR, "Failed to deactivate relay on GPIO%d", relay_pin);
        return;
    }
    log_event(relay_pin, 0);
}

static void timer_callback(int timer_id, void *user_data) {
    (void)timer_id;
    (void)user_data;

    static const int relay_pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    static int current_relay = 0;
    static int state = 0;
    static int elapsed = 0;

    elapsed += TIMER_INTERVAL_SEC;

    if (state == 0) {
        if (elapsed >= RELAY_ON_TIME_SEC) {
            deactivate_relay(relay_pins[current_relay]);
            state = 1;
            elapsed = 0;
        }
    } else if (state == 1) {
        if (elapsed >= RELAY_PAUSE_SEC) {
            activate_relay(relay_pins[current_relay]);
            state = 0;
            elapsed = 0;
        }
    }

    current_relay = (current_relay + 1) % 4;
}

int main(void) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            syslog(LOG_ERR, "Failed to set GPIO%d as output", pins[i]);
            gpioTerminate();
            closelog();
            return EXIT_FAILURE;
        }
        if (gpioWrite(pins[i], 1) != 0) {
            syslog(LOG_ERR, "Failed to initialize relay on GPIO%d to OFF", pins[i]);
            gpioTerminate();
            closelog();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register signal handler");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL_SEC, timer_callback, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set up timer");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Irrigation system started");

    while (program_running) {
        sleep(1);
    }

    syslog(LOG_INFO, "Shutting down irrigation system");

    gpioSetTimerFuncEx(0, 0, NULL, NULL);

    for (int i = 0; i < 4; i++) {
        gpioWrite(pins[i], 1);
    }

    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

