#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/stat.h>
#include <sys/types.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define ACCEL_XOUT_H 0x3B
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define BUFFER_SIZE 100
#define SAMPLE_HZ 100
#define SAMPLE_PERIOD_NS (1000000000LL / SAMPLE_HZ)

typedef struct {
    float x;
    float y;
    float z;
} AccelData;

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int sysfs_dir_fd = -1;
static int sysfs_file_fd = -1;
static struct sigaction sa;
static struct timespec next_sample;

static AccelData circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_reg8(fd, ACCEL_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_accel_data(int fd, AccelData *data) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 6) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    data->x = (float)raw_x / 16384.0f;
    data->y = (float)raw_y / 16384.0f;
    data->z = (float)raw_z / 16384.0f;
    return 0;
}

static void add_to_buffer(AccelData data) {
    circular_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static int create_sysfs_dir(void) {
    char path[256];
    snprintf(path, sizeof(path), "/sys/kernel/mpu6050_accel");
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) {
            snprintf(path, sizeof(path), "%s/latest", path);
            sysfs_file_fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
            if (sysfs_file_fd < 0) {
                fprintf(stderr, "Failed to open sysfs file: %s\n", strerror(errno));
                return -1;
            }
            return 0;
        }
        fprintf(stderr, "Path exists but is not a directory: %s\n", path);
        return -1;
    }
    if (mkdir(path, 0755) < 0) {
        fprintf(stderr, "Failed to create sysfs directory: %s\n", strerror(errno));
        return -1;
    }
    snprintf(path, sizeof(path), "%s/latest", path);
    sysfs_file_fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (sysfs_file_fd < 0) {
        fprintf(stderr, "Failed to open sysfs file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void write_sysfs_data(const AccelData *data) {
    char buffer[256];
    snprintf(buffer, sizeof(buffer), "%.3f,%.3f,%.3f", data->x, data->y, data->z);
    if (write(sysfs_file_fd, buffer, strlen(buffer)) < 0) {
        fprintf(stderr, "Failed to write to sysfs file: %s\n", strerror(errno));
    }
}

static void timer_handler(int sig) {
    (void)sig;
