#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define NUM_RELAYS 4
#define CONSUMER "smart_lighting"

static const unsigned int relay_pins[NUM_RELAYS] = {18, 23, 24, 25};
static const int prime_intervals[NUM_RELAYS] = {2, 3, 5, 7};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_relay(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Failed to set relay value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    struct timespec next_time[NUM_RELAYS];
    int relay_states[NUM_RELAYS] = {0};
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = NULL;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        clock_gettime(CLOCK_MONOTONIC, &next_time[i]);
    }

    while (running) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);

            long diff_sec = now.tv_sec - next_time[i].tv_sec;
            long diff_nsec = now.tv_nsec - next_time[i].tv_nsec;
            if (diff_nsec < 0) {
                diff_sec--;
                diff_nsec += 1000000000L;
            }

            if (diff_sec >= 0 || diff_nsec >= 0) {
                relay_states[i] = !relay_states[i];
                if (set_relay(lines[i], relay_states[i]) < 0) {
                    goto cleanup;
                }
                printf("Relay %d (GPIO %u) toggled to %d\n", i + 1, relay_pins[i], relay_states[i]);

                next_time[i].tv_sec = now.tv_sec + prime_intervals[i];
                next_time[i].tv_nsec = now.tv_nsec;
            }
        }
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

