#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// MPU-6050 I2C address (AD0 tied to GND)
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define MPU6050_WHO_AM_I   0x75
#define MPU6050_WHO_AM_I_VAL 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_GYRO_XOUT_H 0x43

// Gyroscope sensitivity for +-250 degrees/sec range (default)
#define GYRO_SENSITIVITY 131.0f

// Angular velocity threshold (degrees/second)
#define VELOCITY_THRESHOLD 50.0f

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} GyroData;

// Circular buffer structure
typedef struct {
    GyroData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Global variables
static int i2c_fd = -1;
static CircularBuffer gyro_buffer;
static volatile sig_atomic_t running = 1;

// Function prototypes
int init_i2c(void);
int init_mpu6050(void);
int read_gyro_data(GyroData *data);
void add_to_buffer(CircularBuffer *buffer, GyroData data);
void check_threshold(GyroData data);
void signal_handler(int signal);
void cleanup(void);

// Initialize I2C communication
int init_i2c(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Initialize MPU-6050
int init_mpu6050(void) {
    uint8_t who_am_i = 0;

    // Read WHO_AM_I register to verify sensor presence
    if (write(i2c_fd, (uint8_t[]){MPU6050_WHO_AM_I}, 1) != 1) {
        fprintf(stderr, "Failed to write WHO_AM_I register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(i2c_fd, &who_am_i, 1) != 1) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }

    if (who_am_i != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n", MPU6050_WHO_AM_I_VAL, who_am_i);
        return -1;
    }

    // Wake up the MPU-6050 (clear sleep bit)
    uint8_t pwr_mgmt_1 = 0;
    pwr_mgmt_1 = 0x00; // Wake up, internal oscillator, no sleep
    if (write(i2c_fd, (uint8_t[]){MPU6050_PWR_MGMT_1, pwr_mgmt_1}, 2) != 2) {
        fprintf(stderr, "Failed to write PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read gyroscope data from MPU-6050
int read_gyro_data(GyroData *data) {
    uint8_t buffer[6];

    // Write the starting register address (GYRO_XOUT_H)
    if (write(i2c_fd, (uint8_t[]){MPU6050_GYRO_XOUT_H}, 1) != 1) {
        fprintf(stderr, "Failed to write register address: %s\n", strerror(errno));
        return -1;
    }

    // Read 6 bytes of data (X, Y, Z axis)
    if (read(i2c_fd, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read gyroscope data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes (big-endian)
    int16_t gyro_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t gyro_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t gyro_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert to degrees/second
    data->x = (float)gyro_x / GYRO_SENSITIVITY;
    data->y = (float)gyro_y / GYRO_SENSITIVITY;
    data->z = (float)gyro_z / GYRO_SENSITIVITY;

    return 0;
}

// Add data to the circular buffer
void add_to_buffer(CircularBuffer *buffer, GyroData data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Check if the angular velocity exceeds the threshold
void check_threshold(GyroData data) {
    float magnitude = sqrtf(data.x * data.x + data.y * data.y + data.z * data.z);
    if (magnitude > VELOCITY_THRESHOLD) {
        printf("Angular velocity threshold exceeded! Magnitude: %.2f deg/s\n", magnitude);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Cleanup resources
void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    // Initialize I2C
    if (init_i2c() != 0) {
        return EXIT_FAILURE;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPU-6050 gyroscope monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        GyroData gyro_data;

        // Read gyroscope data
        if (read_gyro_data(&gyro_data) == 0) {
            // Add data to the circular buffer
            add_to_buffer(&gyro_buffer, gyro_data);

            // Check if the angular velocity exceeds the threshold
            check_threshold(gyro_data);
        } else {
            fprintf(stderr, "Failed to read gyroscope data. Retrying...\n");
        }

        // Delay for 100 milliseconds
        usleep(100000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();

    return EXIT_SUCCESS;
}

