/*
 * MH-Z19B CO2 Monitor for Raspberry Pi 3 Model B+
 * UART: /dev/serial0 @ 9600 baud (TXD=GPIO14, RXD=GPIO15)
 * Logs JSON to co2_log.json every 5 s and prints to stdout.
 * Errors go to co2_error.log.
 *
 * Build: gcc -Wall -Wextra -o co2_monitor co2_monitor.c -lpigpio -lrt
 * Run:   sudo ./co2_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE      "/dev/serial0"
#define BAUD_RATE        9600
#define READ_INTERVAL_S  5
#define READ_TIMEOUT_MS  1000
#define READ_CMD_LEN     9
#define READ_RESP_LEN    9
#define LOG_FILE         "co2_log.json"
#define ERR_FILE         "co2_error.log"

static volatile sig_atomic_t g_running = 1;
static int  g_uart_fd = -1;
static FILE *g_log_fp  = NULL;
static FILE *g_err_fp  = NULL;

/* ---- prototypes ---- */
static void signal_handler(int sig);
static void log_error(const char *msg);
static int  init_uart(void);
static int  read_co2(uint16_t *co2_ppm);
static void log_co2(uint16_t co2_ppm, int error);
static void cleanup(void);

/* ---- signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- timestamp helper ---- */
static void timestamp_str(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;
    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t pos = strlen(buf);
    snprintf(buf + pos, len - pos, ".%06ld", ts.tv_nsec / 1000);
}

/* ---- error logger ---- */
static void log_error(const char *msg)
{
    char ts[32];
    timestamp_str(ts, sizeof ts);
    if (g_err_fp) {
        fprintf(g_err_fp, "%s - %s\n", ts, msg);
        fflush(g_err_fp);
    }
    fprintf(stderr, "%s - %s\n", ts, msg);
}

/* ---- UART init ---- */
static int init_uart(void)
{
    g_uart_fd = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (g_uart_fd < 0) {
        log_error("serOpen failed");
        return -1;
    }
    return 0;
}

/* ---- read CO2: returns 0 on success, -1 on error ---- */
static int read_co2(uint16_t *co2_ppm)
{
    uint8_t cmd[READ_CMD_LEN] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};
    uint8_t resp[READ_RESP_LEN];
    int     total;
    int     elapsed;

    /* send command */
    if (serWrite(g_uart_fd, (char *)cmd, READ_CMD_LEN) != READ_CMD_LEN) {
        log_error("serWrite failed");
        return -1;
    }

    /* wait for response (no ACK; data arrives after command) */
    time_sleep(0.1);

    /* read exactly 9 bytes with timeout */
    total = 0;
    elapsed = 0;
    while (total < READ_RESP_LEN && elapsed < READ_TIMEOUT_MS) {
        int avail = serDataAvailable(g_uart_fd);
        if (avail < 0) {
            log_error("serDataAvailable failed");
            return -1;
        }
        if (avail > 0) {
            int n = serRead(g_uart_fd, (char *)(resp + total), avail);
            if (n < 0) {
                log_error("serRead failed");
                return -1;
            }
            total += n;
            elapsed = 0; /* reset on data */
        } else {
            time_sleep(0.001);
            elapsed++;
        }
    }

    if (total != READ_RESP_LEN) {
        log_error("Timeout waiting for MH-Z19B response");
        return -1;
    }

    /* validate checksum: sum bytes 1-7, invert, increment */
    uint8_t checksum = 0;
    for (int i = 1; i < 8; i++)
        checksum += resp[i];
    checksum = (~checksum) + 1;
    if (checksum != resp[8]) {
        log_error("Checksum mismatch on MH-Z19B response");
        return -1;
    }

    *co2_ppm = (uint16_t)((resp[2] << 8) | resp[3]);
    return 0;
}

/* ---- log one JSON line ---- */
static void log_co2(uint16_t co2_ppm, int error)
{
    char ts[32];
    timestamp_str(ts, sizeof ts);

    if (g_log_fp) {
        fprintf(g_log_fp,
                "{\"timestamp\":\"%s\",\"co2_ppm\":%u,\"error\":%d}\n",
                ts, co2_ppm, error);
        fflush(g_log_fp);
    }

    printf("{\"timestamp\":\"%s\",\"co2_ppm\":%u,\"error\":%d}\n",
           ts, co2_ppm, error);
}

/* ---- cleanup ---- */
static void cleanup(void)
{
    if (g_uart_fd >= 0) {
        serClose(g_uart_fd);
        g_uart_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_err_fp) {
        fclose(g_err_fp);
        g_err_fp = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    /* pigpio init */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* open log files */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    g_err_fp = fopen(ERR_FILE, "a");
    if (!g_err_fp) {
        perror("fopen err");
        fclose(g_log_fp);
        g_log_fp = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* open UART */
    if (init_uart() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* signals */
    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MH-Z19B CO2 monitor started. Logging to %s every %d s.\n",
           LOG_FILE, READ_INTERVAL_S);

    while (g_running) {
        uint16_t co2_ppm = 0;
        int      rc = read_co2(&co2_ppm);
        if (rc == 0) {
            log_co2(co2_ppm, 0);
        } else {
            log_co2(0, 1);
        }
        /* sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_S * 10 && g_running; i++)
            time_sleep(0.1);
    }

    cleanup();
    printf("Shutdown complete.\n");
    return EXIT_SUCCESS;
}

