#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

/* HMC5883L I2C address */
#define HMC5883L_ADDR 0x1E

/* HMC5883L register addresses */
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE     0x02
#define HMC5883L_DATA_X_MSB 0x03

/* GPIO pin for output (BCM numbering) */
#define OUTPUT_PIN 17

/* Target heading in degrees */
#define TARGET_HEADING 90.0

/* Hard-iron offset calibration values */
#define HARD_IRON_X_OFFSET 100.0
#define HARD_IRON_Y_OFFSET -50.0

/* Heading deviation threshold in degrees */
#define HEADING_THRESHOLD 10.0

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 100000

/* Global variables */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Circular buffer structure */
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static CircularBuffer heading_buffer;

/* Function prototypes */
static int initialize_magnetometer(void);
static int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
static float calculate_heading(int16_t x, int16_t y);
static void compensate_hard_iron(float *heading, int16_t x, int16_t y);
static void set_output_pin(int state);
static void signal_handler(int signal);
static void init_circular_buffer(CircularBuffer *cb);
static void add_to_circular_buffer(CircularBuffer *cb, float heading);
static float get_average_heading(CircularBuffer *cb);

/* Initialize the circular buffer */
static void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

/* Add a heading to the circular buffer */
static void add_to_circular_buffer(CircularBuffer *cb, float heading) {
    cb->buffer[cb->head] = heading;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

/* Calculate the average heading from the circular buffer */
static float get_average_heading(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Initialize the HMC5883L magnetometer */
static int initialize_magnetometer(void) {
    /* Configure HMC5883L: 8-average, 15 Hz, normal measurement */
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to CONFIG_A register\n");
        return -1;
    }

    /* Configure gain: 1.3 Gauss */
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to CONFIG_B register\n");
        return -1;
    }

    /* Set continuous measurement mode */
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to MODE register\n");
        return -1;
    }

    return 0;
}

/* Read raw magnetometer data (X, Z, Y) from the sensor */
static int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char data[6];

    /* Read 6 bytes starting from DATA_X_MSB in a single burst transaction */
    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, data, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    /* Combine MSB and LSB for each axis (X, Z, Y order) */
    *x = (int16_t)((data[0] << 8) | data[1]);
    *z = (int16_t)((data[2] << 8) | data[3]);
    *y = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

/* Calculate the heading in degrees from the raw magnetometer data */
static float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2f((float)y, (float)x) * 180.0f / M_PI;
    if (heading < 0.0f) {
        heading += 360.0f;
    }
    return heading;
}

/* Compensate for hard-iron distortion */
static void compensate_hard_iron(float *heading, int16_t x, int16_t y) {
    *heading = calculate_heading(x - HARD_IRON_X_OFFSET, y - HARD_IRON_Y_OFFSET);
}

/* Set the output pin state */
static void set_output_pin(int state) {
    gpioWrite(OUTPUT_PIN, state);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 at the HMC5883L address */
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize the magnetometer */
    if (initialize_magnetometer() < 0) {
        fprintf(stderr, "Magnetometer initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Set the output pin as an output */
    gpioSetMode(OUTPUT_PIN, PI_OUTPUT);

    /* Initialize the circular buffer */
    init_circular_buffer(&heading_buffer);

    /* Set up signal handling for graceful shutdown */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Magnetometer data acquisition started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        int16_t x, y, z;

        /* Read magnetometer data */
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            /* Calculate and compensate the heading */
            float heading;
            compensate_hard_iron(&heading, x, y);

            /* Add the heading to the circular buffer */
            add_to_circular_buffer(&heading_buffer, heading);

            /* Calculate the average heading */
            float avg_heading = get_average_heading(&heading_buffer);

            /* Check if the heading deviates from the target heading */
            if (fabsf(heading - TARGET_HEADING) > HEADING_THRESHOLD) {
                set_output_pin(1);
            } else {
                set_output_pin(0);
            }

            /* Print the heading and average heading */
            printf("Heading: %.2f, Average Heading: %.2f\n", heading, avg_heading);
        } else {
            fprintf(stderr, "Failed to read magnetometer data, retrying...\n");
        }

        /* Wait for the next sample interval */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean up resources */
    printf("\nCleaning up...\n");
    set_output_pin(0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

