#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define RED_PIN    17
#define GREEN_PIN  27
#define BLUE_PIN   22

#define BH1750_ADDR 0x23
#define I2C_BUS    "/dev/i2c-1"

#define RED_THRESHOLD  50
#define GREEN_THRESHOLD 150
#define BLUE_THRESHOLD 300

#define BH1750_CONT_HIGH_RES 0x10
#define BH1750_CONV_TIME_MS 120

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, unsigned char reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, unsigned char *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_lux(int fd, float *lux_out) {
    if (i2c_write_byte(fd, BH1750_CONT_HIGH_RES) < 0) return -1;
