#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define PWM_DUTY_MAX 255
#define PWM_DUTY_MIN 0

#define DISTANCE_MIN 10.0
#define DISTANCE_MAX 100.0
#define DISTANCE_THRESHOLD 50.0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_motor_speed(int in1, int in2, int duty) {
    if (gpioWrite(in1, 1) < 0) {
        fprintf(stderr, "gpioWrite(in1=%d, 1) failed\n", in1);
        return -1;
    }
    if (gpioPWM(in2, duty) < 0) {
        fprintf(stderr, "gpioPWM(in2=%d, %d) failed\n", in2, duty);
        return -1;
    }
    return 0;
}

static int stop_motor(int in1, int in2) {
    if (gpioWrite(in1, 0) < 0) {
        fprintf(stderr, "gpioWrite(in1=%d, 0) failed\n", in1);
        return -1;
    }
    if (gpioPWM(in2, 0) < 0) {
        fprintf(stderr, "gpioPWM(in2=%d, 0) failed\n", in2);
        return -1;
    }
    return 0;
}

static int map_distance_to_duty(double distance) {
    if (distance < DISTANCE_MIN) distance = DISTANCE_MIN;
    if (distance > DISTANCE_MAX) distance = DISTANCE_MAX;
    double duty = (DISTANCE_MAX - distance) / (DISTANCE_MAX - DISTANCE_MIN) * PWM_DUTY_MAX;
    if (duty < 0.0) duty = 0.0;
    if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;
    return (int)duty;
}

static int control_motor(int in1, int in2, double distance) {
    int duty = map_distance_to_duty(distance);
    if (distance < DISTANCE_THRESHOLD) {
        return set_motor_speed(in1, in2, duty);
    } else {
        return stop_motor(in1, in2);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_B_IN4, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    double motor_a_distance = 50.0;
    double motor_b_distance = 75.0;

    while (running) {
        if (control_motor(MOTOR_A_IN1, MOTOR_A_IN2, motor_a_distance) < 0) {
            fprintf(stderr, "Motor A control error\n");
            break;
        }
        if (control_motor(MOTOR_B_IN3, MOTOR_B_IN4, motor_b_distance) < 0) {
            fprintf(stderr, "Motor B control error\n");
            break;
        }
        gpioDelay(100000);
    }

    stop_motor(MOTOR_A_IN1, MOTOR_A_IN2);
    stop_motor(MOTOR_B_IN3, MOTOR_B_IN4);
    gpioTerminate();
    return EXIT_SUCCESS;
}

