        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(IN1, PI_OUTPUT) != 0 ||
        gpioSetMode(IN2, PI_OUTPUT) != 0 ||
        gpioSetMode(IN3, PI_OUTPUT) != 0 ||
        gpioSetMode(IN4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set motor GPIO modes.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0 ||
        gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set button GPIO modes.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up resistors.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Door lock control ready. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            printf("Locking door...\n");
            rotate(STEPS_PER_TURN, 1);
            while (gpioRead(LOCK_BUTTON) == 0 && running) {
                gpioDelay(10000);
            }
            printf("Door locked.\n");
            break;
        }
        if (gpioRead(UNLOCK_BUTTON) == 0) {
            printf("Unlocking door...\n");
            rotate(STEPS_PER_TURN, -1);
            while (gpioRead(UNLOCK_BUTTON) == 0 && running) {
                gpioDelay(10000);
            }
            printf("Door unlocked.\n");
            break;
        }
        gpioDelay(10000);
    }

    cleanup();
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

