#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define PWR_MGMT_1_RESET 0x80
#define PWR_MGMT_1_SLEEP 0x40
#define PWR_MGMT_1_CYCLE 0x80

#define SERVO_GPIO 18
#define PWM_CHIP 2
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 20000000
#define PWM_RANGE 2000000
#define PWM_DUTY_MIN 500000
#define PWM_DUTY_MAX 2500000

#define LOG_FILE "solar_tracker.log"
#define SAMPLE_DELAY_MS 100
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int pwm_exported = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int mpu6050_init(int fd) {
    if (i2c_write_reg(fd, PWR_MGMT_1, PWR_MGMT_1_SLEEP) < 0) return -1;
    usleep(100000);
    if (i2c_write_reg(fd, PWR_MGMT_1, PWR_MGMT_1_CYCLE) < 0) return -1;
    usleep(100000);
    return 0;
}

static int read_accel(int fd, int16_t *ax, int16_t *ay, int16_t *az) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 6) < 0) return -1;
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int duty = PWM_DUTY_MIN + (int)((float)angle / 180.0 * (PWM_DUTY_MAX - PWM_DUTY_MIN));
    char path[256];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_CHANNEL);
    FILE *fp = fopen(path, "w");
    if (!fp) return;
    fprintf(fp, "%d", PWM_PERIOD_NS);
    fclose(fp);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    fp = fopen(path, "w");
    if (!fp) return;
    fprintf(fp, "%d", duty);
    fclose(fp);
}

static void log_data(float pitch, float roll, int servo_angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, pitch, roll, servo_angle);
    fclose(fp);
}

static int pwm_export(void) {
    char path[256];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/export", PWM_CHIP);
    FILE *fp = fopen(path, "w");
    if (!fp) return -1;
    fprintf(fp, "%d", PWM_CHANNEL);
    fclose(fp);
    return 0;
}

static int pwm_unexport(void) {
    char path[256];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/unexport", PWM_CHIP);
    FILE *fp = fopen(path, "w");
    if (!fp) return -1;
    fprintf(fp, "%d", PWM_CHANNEL);
    fclose(fp);
    return 0;
}

static int pwm_enable(int enable) {
    char path[256];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
    FILE *fp = fopen(path, "w");
    if (!fp) return -1;
    fprintf(fp, "%d", enable);
    fclose(fp);
    return 0;
}

static int pwm_write_str(const char *path, const char *val) {
    FILE *fp = fopen(path, "w");
    if (!fp) return -1;
    fprintf(fp, "%s", val);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    int retries = 0;
    while (mpu6050_init(i2c_fd) < 0) {
        fprintf(stderr, "MPU-6050 init failed (attempt %d/%d): %s\n", retries + 1, MAX_RETRIES, strerror(errno));
        retries++;
        if (retries >= MAX_RETRIES) {
            fprintf(stderr, "Max retries reached. Exiting.\n");
            close(i2c_fd);
            return 1;
        }
        usleep(RETRY_DELAY_MS * 1000);
    }

    if (pwm_export() < 0) {
        fprintf(stderr, "Failed to export PWM: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    pwm_exported = 1;
    usleep(100000);

    char path[256];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_CHANNEL);
    if (pwm_write_str(path, "20000000") < 0) {
        fprintf(stderr, "Failed to set PWM period: %s\n", strerror(errno));
        pwm_unexport();
        close(i2c_fd);
        return 1;
    }
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    if (pwm_write_str(path, "1500000") < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle: %s\n", strerror(errno));
        pwm_unexport();
        close(i2c_fd);
        return 1;
    }
    if (pwm_enable(1) < 0) {
        fprintf(stderr, "Failed to enable PWM: %s\n", strerror(errno));
        pwm_unexport();
        close(i2c_fd);
        return 1;
    }

    int servo_angle = 90;
    set_servo_angle(servo_angle);

    while (running) {
        int16_t ax, ay, az;
        if (read_accel(i2c_fd, &ax, &ay, &az) < 0) {
            fprintf(stderr, "Accel read failed: %s\n", strerror(errno));
            usleep(SAMPLE_DELAY_MS * 1000);
            continue;
        }

        float pitch = atan2f((float)ay, sqrtf((float)ax * ax + (float)az * az)) * 180.0f / M_PI;
        float roll = atan2f((float)ax, sqrtf((float)ay * ay + (float)az * az)) * 180.0f / M_PI;

        if (pitch > 30.0f) pitch = 30.0f;
        if (pitch < -30.0f) pitch = -30.0f;
        if (roll > 30.0f) roll = 30.0f;
        if (roll < -30.0f) roll = -30.0f;

        servo_angle = 90 + (int)pitch;
        if (servo_angle < 0) servo_angle = 0;
        if (servo_angle > 180) servo_angle = 180;

        set_servo_angle(servo_angle);
        log_data(pitch, roll, servo_angle);
        usleep(SAMPLE_DELAY_MS * 1000);
    }

    set_servo_angle(90);
    pwm_enable(0);
    if (pwm_exported) pwm_unexport();
    if (i2c_fd >= 0) close(i2c_fd);
    printf("Shutdown complete.\n");
    return 0;
}

