#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCHEDULE_FILE "lighting_schedule.txt"
#define NUM_RELAYS 4
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define FADE_DURATION 1800
#define POLL_INTERVAL 1

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};
static volatile sig_atomic_t running = 1;

typedef struct {
    int relay_number;
    int state;
    time_t scheduled_time;
} ScheduleEntry;

static ScheduleEntry schedule[NUM_RELAYS];
static int schedule_entries = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_schedule(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (schedule_entries < NUM_RELAYS) {
            int relay_number, state;
            time_t scheduled_time;

            if (sscanf(line, "%d:%d:%d,%d,%d",
                       &scheduled_time, &relay_number, &state) == 3) {
                if (relay_number >= 1 && relay_number <= NUM_RELAYS) {
                    schedule[schedule_entries].relay_number = relay_number;
                    schedule[schedule_entries].state = state;
                    schedule[schedule_entries].scheduled_time = scheduled_time;
                    schedule_entries++;
                } else {
                    fprintf(stderr, "Invalid relay number: %d\n", relay_number);
                }
            } else {
                fprintf(stderr, "Invalid schedule entry format: %s", line);
            }
        } else {
            fprintf(stderr, "Warning: schedule file contains more entries than relays.\n");
            break;
        }
    }

    fclose(fp);
    return 0;
}

static void set_relay(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", pin);
    }
}

static void fade_relay(int pin, int target_brightness, int duration_ms) {
    int current_brightness = gpioGetPWMdutycycle(pin);
    if (current_brightness < 0) current_brightness = 0;

    int steps = (duration_ms > 0) ? duration_ms : 1;
    int step_delay_us = (steps > 0) ? (1000000 / steps) : 1000000;

    for (int i = 0; i < steps && running; i++) {
        if (current_brightness < target_brightness) {
            current_brightness += (target_brightness - current_brightness) / steps;
        } else if (current_brightness > target_brightness) {
            current_brightness -= (current_brightness - target_brightness) / steps;
        }

        if (gpioPWM(pin, current_brightness) != 0) {
            fprintf(stderr, "Error setting PWM on GPIO %d\n", pin);
        }
        gpioDelay(step_delay_us);
    }
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        set_relay(relay_pins[i], 0);
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error setting GPIO %d as output\n", relay_pins[i]);
            cleanup();
            return 1;
        }
        if (gpioSetPWMfrequency(relay_pins[i], PWM_FREQUENCY) != 0) {
            fprintf(stderr, "Error setting PWM frequency on GPIO %d\n", relay_pins[i]);
            cleanup();
            return 1;
        }
        if (gpioSetPWMrange(relay_pins[i], PWM_RANGE) != 0) {
