#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_FREQUENCY  200
#define MAX_FREQUENCY  2000
#define MIN_DISTANCE   2.0
#define MAX_DISTANCE   30.0
#define TIMEOUT_US     30000   /* 30 ms timeout for echo */
#define LOOP_DELAY_US  20000   /* 20 ms between measurements */
#define TRIGGER_PULSE_US 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure distance in cm using the HC-SR04.
 * Returns distance on success, or -1.0 on timeout / error.
 */
static float measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger is low for a clean pulse */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to write trigger high\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0;
    }

    /* Wait for echo rising edge (timeout) */
    timeout_tick = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo start\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    timeout_tick = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo end\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    /* speed of sound ~343 m/s => 58 cm per ms; 1 us = 0.0343 cm */
    float distance = (float)pulse_width * 0.0343f / 2.0f;
    return distance;
}

/*
 * Map distance to frequency with clamping.
 * Returns frequency in Hz.
 */
static int map_distance_to_frequency(float distance) {
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;

    float normalized = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);
    int frequency = (int)(MIN_FREQUENCY + normalized * (MAX_FREQUENCY - MIN_FREQUENCY));
    if (frequency < MIN_FREQUENCY) frequency = MIN_FREQUENCY;
    if (frequency > MAX_FREQUENCY) frequency = MAX_FREQUENCY;
    return frequency;
}

/*
 * Generate a PWM square wave at the given frequency on BUZZER_PIN.
 * frequency = 0 silences the buzzer.
 */
static void set_buzzer_frequency(int frequency) {
    if (frequency <= 0) {
        gpioPWM(BUZZER_PIN, 0);
        return;
    }
    int range = 2000000 / frequency;
    if (range < 1) range = 1;
    if (gpioSetPWMfrequency(BUZZER_PIN, frequency) < 0) {
        fprintf(stderr, "Warning: failed to set PWM frequency\n");
        return;
    }
    if (gpioPWM(BUZZER_PIN, range) < 0) {
        fprintf(stderr, "Warning: failed to set PWM range\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler\n");
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000); /* 100 ms settle */

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance();
        if (distance < 0.0f) {
            fprintf(stderr, "Error: distance measurement failed\n");
        } else {
            int frequency = map_distance_to_frequency(distance);
            set_buzzer_frequency(frequency);
            printf("Distance: %.2f cm -> Frequency: %d Hz\n", distance, frequency);
        }
        gpioDelay(LOOP_DELAY_US);
    }

    /* Graceful shutdown */
    gpioPWM(BUZZER_PIN, 0);
    gpioTerminate();
    printf("\nTheremin stopped.\n");
    return EXIT_SUCCESS;
}

