#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27
#define PWM_FREQ  1000
#define PWM_RANGE 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_led_color(int red, int green, int blue) {
    if (gpioPWM(RED_PIN, red) != 0)
        fprintf(stderr, "Warning: gpioPWM failed on RED_PIN\n");
    if (gpioPWM(GREEN_PIN, green) != 0)
        fprintf(stderr, "Warning: gpioPWM failed on GREEN_PIN\n");
    if (gpioPWM(BLUE_PIN, blue) != 0)
        fprintf(stderr, "Warning: gpioPWM failed on BLUE_PIN\n");
}

static void turn_off_led(void) {
    set_led_color(0, 0, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }

    printf("Color proximity alert running. Press Ctrl+C to exit.\n");

    while (running) {
        double proximity = (sin(time(NULL) / 10.0) + 1.0) / 2.0;

        int red   = (int)(proximity * 255.0);
        int green = (int)((1.0 - proximity) * 255.0);
        int blue  = 0;

        if (red < 0) red = 0;
        if (red > 255) red = 255;
        if (green < 0) green = 0;
        if (green > 255) green = 255;
        if (blue < 0) blue = 0;
        if (blue > 255) blue = 255;

        set_led_color(red, green, blue);
        printf("Proximity: %.2f  RGB: (%d, %d, %d)\n", proximity, red, green, blue);

        usleep(50000);
    }

    printf("\nShutting down...\n");
    turn_off_led();
    gpioTerminate();
    return EXIT_SUCCESS;
}

