#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define PWR_MGMT_1     0x6B
#define GYRO_XOUT_H    0x43
#define GYRO_SENS_250  131.0f
#define LOG_FILE       "gyro_log.txt"
#define SAMPLE_MS      100

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_block write(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_block read(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int16_t combine(uint8_t hi, uint8_t lo) {
    return (int16_t)((uint16_t)hi << 8 | (uint16_t)lo);
}

static void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake MPU-6050 (sensor absent or bus error)\n");
        close(fd);
        return EXIT_FAILURE;
    }
    usleep(100000);

    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 logging to %s (Ctrl+C to stop)\n", LOG_FILE);

    while (g_running) {
        uint8_t raw[6];
        if (i2c_read_block(fd, GYRO_XOUT_H, raw, 6) < 0) {
            fprintf(stderr, "Gyro read failed; continuing\n");
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        int16_t rx = combine(raw[0], raw[1]);
        int16_t ry = combine(raw[2], raw[3]);
        int16_t rz = combine(raw[4], raw[5]);

        float x = (float)rx / GYRO_SENS_250;
        float y = (float)ry / GYRO_SENS_250;
        float z = (float)rz / GYRO_SENS_250;

        log_data(log, x, y, z);
        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down cleanly...\n");
    fclose(log);
    close(fd);
    return EXIT_SUCCESS;
}

