#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define DEBOUNCE_US 50000   /* 50 ms debounce */
#define MELODY_DURATION_US 1000000 /* 1 second total playback */
#define PWM_DUTY_50 128      /* 50% of 255 */

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t melody_playing = 0;
static volatile uint32_t last_interrupt_tick = 0;

/*
 * Melody: frequency (Hz) and duration (microseconds).
 * Frequencies are rounded to the nearest integer that pigpio can
 * generate via hardware PWM (pigpio supports 32-bit frequency).
 */
static const int melody_frequencies[] = {
    440, 523, 659, 784, 988, 1319, 1760, 2349, 3296, 4699
};
static const int melody_durations[] = {
    100000, 100000, 100000, 100000, 100000, 100000, 100000, 100000, 100000, 100000
};
static const int melody_length =
    sizeof(melody_frequencies) / sizeof(melody_frequencies[0]);

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Interrupt handler: runs in a pigpio thread.
 * Only sets a flag; heavy work is done in the main loop.
 */
static void button_interrupt_handler(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;

    if (level == 0) { /* active-low button press */
        uint32_t diff = tick - last_interrupt_tick;
        if (diff > DEBOUNCE_US) {
            last_interrupt_tick = tick;
            melody_playing = 1;
        }
    }
}

static int set_buzzer_frequency(int frequency) {
    if (frequency <= 0) {
        return gpioHardwarePWM(BUZZER_PIN, 0, 0); /* silence */
    }
    int actual = gpioHardwarePWM(BUZZER_PIN, frequency, PWM_DUTY_50);
    if (actual < 0) {
        fprintf(stderr, "gpioHardwarePWM failed for %d Hz: %d\n", frequency, actual);
        return -1;
    }
    return 0;
}

int main(void) {
    int ret;

    /* --- Initialize pigpio --- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", ret);
        return EXIT_FAILURE;
    }

    /* --- Configure button pin --- */
    ret = gpioSetMode(BUTTON_PIN, PI_INPUT);
    if (ret < 0) {
        fprintf(stderr, "gpioSetMode(BUTTON_PIN) failed: %d\n", ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    ret = gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);
    if (ret < 0) {
        fprintf(stderr, "gpioSetPullUpDown(BUTTON_PIN) failed: %d\n", ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure buzzer pin --- */
    ret = gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "gpioSetMode(BUZZER_PIN) failed: %d\n", ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Register interrupt handler --- */
    ret = gpioSetISRFuncEx(BUTTON_PIN, RISING_EDGE, 0, button_interrupt_handler, NULL);
    if (ret < 0) {
        fprintf(stderr, "gpioSetISRFuncEx failed: %d\n", ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Musical doorbell ready. Press the button (GPIO17) to play the melody.\n");
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (running) {
        if (melody_playing) {
            melody_playing = 0;

            for (int i = 0; i < melody_length && running; i++) {
                if (set_buzzer_frequency(melody_frequencies[i]) < 0) {
                    break;
                }
                gpioDelay(melody_durations[i]);
            }

            /* Ensure buzzer is silent after melody */
            gpioHardwarePWM(BUZZER_PIN, 0, 0);
        }
        gpioDelay(10000); /* 10 ms poll interval */
    }

    /* --- Cleanup --- */
    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    gpioSetISRFuncEx(BUTTON_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioTerminate();
    printf("\nClean shutdown complete.\n");
    return EXIT_SUCCESS;
}

