    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s GPIO%d=%d\n", timestamp, GPIO_PIN, value) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

static void check_earthquake(int *window, int *index, int value) {
    window[*index] = value;
    *index = (*index + 1) % WINDOW_SIZE;

    int high_count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        if (window[i] == 1) {
            high_count++;
        }
    }

    if (high_count >= EARTHQUAKE_THRESHOLD) {
        time_t rawtime;
        struct tm timeinfo;
        char timestamp[32];

        time(&rawtime);
        if (localtime_r(&rawtime, &timeinfo) != NULL) {
            if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) > 0) {
                printf("EARTHQUAKE ALERT at %s\n", timestamp);
                fflush(stdout);
            }
        }
    }
}

int main(int argc, char *argv[]) {
    int timeout_ms = DEFAULT_TIMEOUT_MS;

    if (argc > 1) {
        timeout_ms = atoi(argv[1]);
        if (timeout_ms <= 0) {
            fprintf(stderr, "Invalid timeout value: %s\n", argv[1]);
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        fclose(log_fp);
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (line == NULL) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_fp);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_both_edges_events(line, "sw420-vibration") != 0) {
        fprintf(stderr, "gpiod_line_request_both_edges_events failed: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_fp);
        return EXIT_FAILURE;
    }

    int window[WINDOW_SIZE] = {0};
    int window_index = 0;

    printf("Monitoring SW-420 vibration sensor on GPIO%d (libgpiod). Press Ctrl+C to exit.\n", GPIO_PIN);
    fflush(stdout);

    while (program_running) {
        struct timespec ts;
        ts.tv_sec = timeout_ms / 1000;
        ts.tv_nsec = (timeout_ms % 1000) * 1000000L;

        int ret = gpiod_line_event_wait(line, &ts);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "gpiod_line_event_wait failed: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) {
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) != 0) {
            fprintf(stderr, "gpiod_line_event_read failed: %s\n", strerror(errno));
            continue;
        }

        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
            continue;
        }

        log_event(log_fp, value);
        check_earthquake(window, &window_index, value);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    if (log_fp != NULL) {
        fsync(fileno(log_fp));
        fclose(log_fp);
    }

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

