#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define LSM303_I2C_ADDR 0x1E
#define CRA_REG_M 0x00
#define MR_REG_M 0x02
#define OUT_X_L_M 0x03
#define OUT_X_H_M 0x04
#define OUT_Z_L_M 0x05
#define OUT_Z_H_M 0x06
#define OUT_Y_L_M 0x07
#define OUT_Y_H_M 0x08

#define X_OFFSET 10.0f
#define Y_OFFSET -5.0f
#define Z_OFFSET 20.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n", reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_burst: write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "i2c_read_burst: read %zu bytes from 0x%02X failed: %s\n", len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_lsm303(int fd) {
    if (i2c_write_reg8(fd, CRA_REG_M, 0x14) < 0) return -1;
    if (i2c_write_reg8(fd, MR_REG_M, 0x00) < 0) return -1;
    return 0;
}

static int read_raw_xyz(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, OUT_X_L_M, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *z = (int16_t)((buf[3] << 8) | buf[2]);
    *y = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void calibrate(int16_t x, int16_t y, int16_t z, float *cx, float *cy, float *cz) {
    *cx = (float)x - X_OFFSET;
    *cy = (float)y - Y_OFFSET;
    *cz = (float)z - Z_OFFSET;
}

static float calc_heading(float x, float y) {
    float h = atan2f(y, x) * 180.0f / (float)M_PI;
    if (h < 0.0f) h += 360.0f;
    return h;
}

static const char *dir_from_heading(float h) {
    if (h >= 348.75f || h < 11.25f) return "N";
    if (h < 33.75f) return "NNE";
    if (h < 56.25f) return "NE";
    if (h < 67.5f) return "ENE";
    if (h < 157.5f) return "E";
    if (h < 202.5f) return "ESE";
    if (h < 225f) return "SE";
    if (h < 247.5f) return "SSE";
    if (h < 292.5f) return "S";
    if (h < 315f) return "SSW";
    if (h < 337.5f) return "SW";
    return "WSW";
}

static int ensure_log_header(void) {
    long pos = ftell(g_log_fp);
    if (pos < 0) {
        fprintf(stderr, "ftell failed: %s\n", strerror(errno));
        return -1;
    }
    if (pos == 0) {
        if (fprintf(g_log_fp, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            return -1;
        }
        fflush(g_log_fp);
    }
    return 0;
}

static int log_data(float cx, float cy, float cz, float heading) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(g_log_fp, "%s,%.2f,%.2f,%.2f,%.2f\n", ts, cx, cy, cz, heading) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open /dev/i2c-1 failed: %s\n", strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", LSM303_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }
    if (init_lsm303(g_i2c_fd) < 0) {
        fprintf(stderr, "LSM303 initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }

    g_log_fp = fopen("mag_log.csv", "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen mag_log.csv failed: %s\n", strerror(errno));
        close(g_i2c_fd);
        return 1;
    }
    if (ensure_log_header() < 0) {
        fclose(g_log_fp);
        close(g_i2c_fd);
        return 1;
    }

    printf("LSM303DLHC magnetometer logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t rx, ry, rz;
        if (read_raw_xyz(g_i2c_fd, &rx, &ry, &rz) < 0) {
            fprintf(stderr, "Read error; skipping sample\n");
            sleep(1);
            continue;
        }
        float cx, cy, cz;
        calibrate(rx, ry, rz, &cx, &cy, &cz);
        float heading = calc_heading(cx, cy);
        const char *dir = dir_from_heading(heading);
        printf("Heading: %s (%.1f deg)\n", dir, heading);
        if (log_data(cx, cy, cz, heading) < 0) {
            fprintf(stderr, "Logging error; continuing\n");
        }
        sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

