#define LOG_FILE "relay_log.json"

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t relay_state = 0;
static volatile uint32_t last_touch_tick = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t rawtime = time(NULL);
    if (rawtime == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return;
    }

    struct tm timeinfo;
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return;
    }

    const char *state_str = (state == 1) ? "ON" : "OFF";
    fprintf(fp, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n", timestamp, state_str);
    fclose(fp);
}

static void touch_callback(int gpio, int level, uint32_t tick) {
