#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define RELAY_OFF 1
#define RELAY_ON 0
#define MOISTURE_THRESHOLD 30
#define ACTIVATION_DURATION 5
#define GAP_DURATION 1
#define LOG_FILE "irrigation_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 23, 24, 25};
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_RELAYS];
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u: %s\n", relay_pins[i], strerror(errno));
            return -1;
        }

        if (gpiod_line_request_output(lines[i], "irrigation", RELAY_OFF) < 0) {
            fprintf(stderr, "Failed to request output on line %u: %s\n", relay_pins[i], strerror(errno));
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], RELAY_OFF);
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int init_log(void) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

static void log_event(int relay_num, int moisture) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[64];
    if (t) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }
    fprintf(log_file, "%s - Relay %d activated (Moisture: %d)\n", timestamp, relay_num, moisture);
    fflush(log_file);
}

static int simulate_moisture(void) {
    return rand() % 101;
}

static void activate_relay(int relay_num, int moisture) {
    if (gpiod_line_set_value(lines[relay_num], RELAY_ON) < 0) {
        fprintf(stderr, "Failed to activate relay %d: %s\n", relay_num, strerror(errno));
        return;
    }
    log_event(relay_num, moisture);
    sleep(ACTIVATION_DURATION);
    if (gpiod_line_set_value(lines[relay_num], RELAY_OFF) < 0) {
        fprintf(stderr, "Failed to deactivate relay %d: %s\n", relay_num, strerror(errno));
    }
}

int main(void) {
    srand((unsigned int)time(NULL));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup_gpio();
        return 1;
    }

    if (init_log() < 0) {
        cleanup_gpio();
        return 1;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture = simulate_moisture();
        printf("Moisture level: %d\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            for (int i = 0; i < NUM_RELAYS && running; i++) {
                activate_relay(i, moisture);
                if (i < NUM_RELAYS - 1) {
                    sleep(GAP_DURATION);
                }
            }
        }
        sleep(10);
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    if (log_file) {
        fclose(log_file);
    }
    printf("Smart Irrigation System stopped.\n");
    return 0;
}

