/*
 * Miniature automated plant watering system for Raspberry Pi Zero W.
 * Uses pigpio to drive two SG90 servo motors:
 *   GPIO17 (physical pin 11) - water valve servo (closed 0 deg, open 90 deg)
 *   GPIO18 (physical pin 12) - directional nozzle servo (sweeps 0-180 deg)
 *
 * Simulated soil-moisture readings cycle every second through 20, 40, 60, 80, 100.
 * If moisture < 50, the valve opens, the nozzle sweeps through 5 angles,
 * then the valve closes. After each cycle, wait 5 s before the next reading.
 *
 * Build: gcc -Wall -Wextra -O2 -o watering watering.c -lpigpio -lrt
 * Run:   sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_GPIO        17
#define NOZZLE_GPIO       18
#define MOISTURE_THRESHOLD 50
#define SERVO_RETRY_COUNT  3
#define SERVO_RETRY_DELAY  100000   /* 100 ms in microseconds */
#define WATERING_DELAY_US  5000000  /* 5 s in microseconds */
#define CYCLE_DELAY_US    5000000  /* 5 s between cycles */
#define SERVO_SETTLE_US   1000000  /* 1 s settle after each servo move */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — keep it async-signal-safe: no pigpio calls here.  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Move a servo to a given pulse width with retries.                   */
/* Returns 0 on success, -1 on failure after all retries.              */
/* ------------------------------------------------------------------ */
static int set_servo(int gpio, int pulse_width)
{
    for (int attempt = 0; attempt < SERVO_RETRY_COUNT; attempt++) {
        if (gpioServo(gpio, pulse_width) == 0)
            return 0;
        fprintf(stderr, "Warning: gpioServo(%d, %d) failed (attempt %d/%d)\n",
                gpio, pulse_width, attempt + 1, SERVO_RETRY_COUNT);
        if (attempt < SERVO_RETRY_COUNT - 1)
            gpioDelay(SERVO_RETRY_DELAY);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Open the valve (90 deg).                                              */
/* ------------------------------------------------------------------ */
static int open_valve(void)
{
    return set_servo(VALVE_GPIO, 1500);   /* ~90 deg */
}

/* ------------------------------------------------------------------ */
/* Close the valve (0 deg).                                            */
/* ------------------------------------------------------------------ */
static int close_valve(void)
{
    return set_servo(VALVE_GPIO, 500);    /* ~0 deg */
}

/* ------------------------------------------------------------------ */
/* Sweep the nozzle through the five angles.                           */
/* ------------------------------------------------------------------ */
static int sweep_nozzle(void)
{
    static const int angles[] = {500, 700, 1000, 1300, 1500};
    const int n = sizeof(angles) / sizeof(angles[0]);

    for (int i = 0; i < n; i++) {
        if (set_servo(NOZZLE_GPIO, angles[i]) != 0) {
            fprintf(stderr, "Error: failed to set nozzle angle %d\n", i);
            return -1;
        }
        gpioDelay(SERVO_SETTLE_US);
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Watering cycle: valve open -> nozzle sweep -> hold -> valve close.  */
/* ------------------------------------------------------------------ */
static int watering_cycle(void)
{
    if (open_valve() != 0) {
        fprintf(stderr, "Critical: valve failed to open — aborting watering cycle\n");
        return -1;
    }
    gpioDelay(SERVO_SETTLE_US);

    if (sweep_nozzle() != 0) {
        fprintf(stderr, "Warning: nozzle sweep encountered errors\n");
    }

    gpioDelay(WATERING_DELAY_US);

    if (close_valve() != 0) {
        fprintf(stderr, "Warning: valve failed to close — continuing\n");
    }
    gpioDelay(SERVO_SETTLE_US);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times.                       */
/* ------------------------------------------------------------------ */
static void cleanup_servos(void)
{
    gpioServo(VALVE_GPIO, 0);
    gpioServo(NOZZLE_GPIO, 0);
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers BEFORE gpioInitialise --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Ensure servos start in a safe (closed) state --- */
    if (close_valve() != 0) {
        fprintf(stderr, "Warning: could not initialise valve to closed state\n");
    }
    if (set_servo(NOZZLE_GPIO, 500) != 0) {
        fprintf(stderr, "Warning: could not initialise nozzle to 0 deg\n");
    }
    gpioDelay(SERVO_SETTLE_US);

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int moisture = (rand() % 101) + 1;   /* 1-101 */
        printf("Moisture level: %d\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Watering...\n");
            if (watering_cycle() != 0) {
                fprintf(stderr, "Error: watering cycle failed\n");
            }
        } else {
            printf("Moisture sufficient — no watering needed.\n");
        }

        /* Wait before next reading (interruptible by signals) */
        for (int i = 0; i < 50 && g_running; i++)
            gpioDelay(100000);   /* 100 ms × 50 = 5 s */
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup_servos();
    gpioTerminate();
    printf("Plant watering system stopped.\n");
    return EXIT_SUCCESS;
}

