#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define PWR_MGMT_1     0x6B
#define GYRO_XOUT_H    0x43
#define GYRO_SENS_250  131.0f
#define SAMPLE_HZ      10
#define SAMPLE_DELAY_US (1000000 / SAMPLE_HZ)

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read burst from 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int16_t be16(const uint8_t *p) {
    return (int16_t)((uint16_t)p[0] << 8 | (uint16_t)p[1]);
}

int main(void) {
    int fd = -1;
    FILE *log = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        goto cleanup;
    }

    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake MPU-6050 (sensor absent or bus error)\n");
        goto cleanup;
    }
    usleep(100000);

    log = fopen("gyro_log.txt", "w");
    if (!log) {
        fprintf(stderr, "Cannot open gyro_log.txt: %s\n", strerror(errno));
        goto cleanup;
    }
    fprintf(log, "timestamp,x,y,z\n");

    while (g_running) {
        uint8_t raw[6];
        if (i2c_read_burst(fd, GYRO_XOUT_H, raw, 6) < 0) {
            fprintf(stderr, "Gyro read error; continuing\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        int16_t gx = be16(&raw[0]);
        int16_t gy = be16(&raw[2]);
        int16_t gz = be16(&raw[4]);

        float fx = (float)gx / GYRO_SENS_250;
        float fy = (float)gy / GYRO_SENS_250;
        float fz = (float)gz / GYRO_SENS_250;

        time_t now = time(NULL);
        fprintf(log, "%ld,%.2f,%.2f,%.2f\n", (long)now, fx, fy, fz);
        fflush(log);

        usleep(SAMPLE_DELAY_US);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (log) fclose(log);
    if (fd >= 0) close(fd);
    return rc;
}

