#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23
#define STEPS_PER_ROTATION 512
#define STEP_DELAY_US 3000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_set_pull(unsigned gpio, unsigned pud) {
    if (gpioSetPullUpDown(gpio, pud) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%u, %u) failed\n", gpio, pud);
        return -1;
    }
    return 0;
}

static void deenergize(void) {
    safe_write(IN1, 0);
    safe_write(IN2, 0);
    safe_write(IN3, 0);
    safe_write(IN4, 0);
}

static void rotate(int direction) {
    static const int seq[4] = {1, 2, 4, 8};
    int pins[4] = {IN1, IN2, IN3, IN4};
    int step;

    for (step = 0; step < STEPS_PER_ROTATION && running; step++) {
        int idx = step % 4;
        int energized = seq[idx];

        if (safe_write(pins[0], energized & 1) < 0) break;
        if (safe_write(pins[1], energized & 2) < 0) break;
        if (safe_write(pins[2], energized & 4) < 0) break;
        if (safe_write(pins[3], energized & 8) < 0) break;

        if (direction > 0) {
            gpioDelay(STEP_DELAY_US);
        } else {
            gpioDelay(STEP_DELAY_US);
        }
    }

    deenergize();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_set_mode(IN1, PI_OUTPUT) < 0 ||
        safe_set_mode(IN2, PI_OUTPUT) < 0 ||
        safe_set_mode(IN3, PI_OUTPUT) < 0 ||
        safe_set_mode(IN4, PI_OUTPUT) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_set_pull(LOCK_BUTTON, PI_PUD_UP) < 0 ||
        safe_set_pull(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    deenergize();

    printf("Door lock control ready. Press LOCK (GPIO24) or UNLOCK (GPIO23) to rotate.\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            printf("Locking door...\n");
            rotate(1);
            if (!running) break;
            printf("Door locked.\n");
            gpioDelay(200000);
        } else if (gpioRead(UNLOCK_BUTTON) == 0) {
            printf("Unlocking door...\n");
            rotate(-1);
            if (!running) break;
            printf("Door unlocked.\n");
            gpioDelay(200000);
        }
        gpioDelay(10000);
    }

    deenergize();
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

