#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define LOG_FILE "distance_log.txt"
#define TIMEOUT_US 50000   /* 50 ms timeout for echo edges */
#define MIN_GUARD_MS 60    /* 60 ms between measurements */
#define PULSE_US 10       /* 10 us trigger pulse */
#define SPEED_CM_PER_US 0.01715f  /* 343 m/s / 2 */

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    running = 0;
}

static long long now_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
        return 0;
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static void sleep_us(long long us)
{
    struct timespec ts = {
        .tv_sec = us / 1000000LL,
        .tv_nsec = (us % 1000000LL) * 1000LL
    };
    nanosleep(&ts, NULL);
}

static void sleep_ms(long ms)
{
    sleep_us(ms * 1000LL);
}

static void log_distance(float distance)
{
    if (log_fp) {
        fprintf(log_fp, "%.2f\n", distance);
        fflush(log_fp);
    }
}

static float measure_distance(struct gpiod_line *trig, struct gpiod_line *echo)
{
    long long start_us, end_us, deadline;

    /* Ensure trigger is low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low: %s\n", strerror(errno));
        return -1.0f;
    }
    sleep_us(2);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high: %s\n", strerror(errno));
        return -1.0f;
    }
    sleep_us(PULSE_US);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low: %s\n", strerror(errno));
        return -1.0f;
    }

    /* Wait for echo rising edge */
    start_us = now_us();
    deadline = start_us + TIMEOUT_US;
    while (gpiod_line_get_value(echo) == 0) {
        if (now_us() >= deadline) {
            fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
            return -1.0f;
        }
    }
    start_us = now_us();

    /* Wait for echo falling edge */
    deadline = start_us + TIMEOUT_US;
    while (gpiod_line_get_value(echo) == 1) {
        if (now_us() >= deadline) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
            return -1.0f;
        }
    }
    end_us = now_us();

    long long duration = end_us - start_us;
    return (float)duration * SPEED_CM_PER_US;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error: cannot open gpiochip4: %s\n", strerror(errno));
        goto cleanup;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        fprintf(stderr, "Error: cannot get GPIO lines (trigger=%p, echo=%p): %s\n",
                trig, echo, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "Error: cannot request trigger line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Error: cannot request echo line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 distance logger started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance(trig, echo);
        log_distance(distance);
        sleep_ms(MIN_GUARD_MS);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    if (log_fp) fclose(log_fp);
    return ret;
}

