#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define RELAY_PIN      18
#define PROXIMITY_THRESHOLD 50
#define POLL_DELAY_US  100000

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET              0x0000
#define REG_SYSTEM_MODE_START       0x0080
#define REG_RESULT_INTERRUPT_STATUS 0x0044
#define REG_RESULT_DISTANCE_MSB     0x0096
#define REG_RESULT_DISTANCE_LSB     0x0097

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address followed by a 16-bit value (big-endian). */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

/* Read a 16-bit register: write address, then read 2 bytes. */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    char addr[2];
    char data[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;
    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int vl53l1x_init(int handle)
{
    if (vl53l1x_write_reg16(handle, REG_SOFT_RESET, 0x0000) < 0) {
        fprintf(stderr, "Error: VL53L1X soft reset write failed\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms settle */

    if (vl53l1x_write_reg16(handle, REG_SYSTEM_MODE_START, 0x0001) < 0) {
        fprintf(stderr, "Error: VL53L1X start ranging failed\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms settle */
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance)
{
    uint16_t status = 0;
    if (vl53l1x_read_reg16(handle, REG_RESULT_INTERRUPT_STATUS, &status) < 0) {
        fprintf(stderr, "Error: failed to read interrupt status\n");
        return -1;
    }
    if ((status & 0x01) == 0) {
        return 1; /* no new data yet */
    }
    uint16_t dist_msb = 0, dist_lsb = 0;
    if (vl53l1x_read_reg16(handle, REG_RESULT_DISTANCE_MSB, &dist_msb) < 0) {
        fprintf(stderr, "Error: failed to read distance MSB\n");
        return -1;
    }
    if (vl53l1x_read_reg16(handle, REG_RESULT_DISTANCE_LSB, &dist_lsb) < 0) {
        fprintf(stderr, "Error: failed to read distance LSB\n");
        return -1;
    }
    *distance = ((uint16_t)dist_msb << 8) | dist_lsb;
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set relay pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_PIN, 0);

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d) - sensor may be absent\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Proximity door system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance = 0;
        int rc = vl53l1x_read_distance(g_i2c_handle, &distance);
        if (rc == 0) {
            printf("Distance: %u cm\n", distance);
            if (distance <= PROXIMITY_THRESHOLD) {
                gpioWrite(RELAY_PIN, 1);
                printf("Door OPEN\n");
            } else {
                gpioWrite(RELAY_PIN, 0);
            }
        } else if (rc < 0) {
            fprintf(stderr, "Error: distance read failed\n");
        }
        /* rc == 1 means no new data yet - just keep polling */
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

