/*
 * MPU-6050 Gyroscope Reader for Raspberry Pi 3 Model B+
 * Uses Linux i2c-dev (no wiringPi dependency).
 *
 * Wiring:
 *   MPU-6050 VCC -> Pi 3.3V (Pin 1)
 *   MPU-6050 GND -> Pi GND  (Pin 9)
 *   MPU-6050 SCL -> Pi GPIO3 / SCL (Pin 5)
 *   MPU-6050 SDA -> Pi GPIO2 / SDA (Pin 3)
 *
 * Build: gcc -O2 -Wall -o mpu6050_gyro mpu6050_gyro.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43

/* Sensitivity scale factor for ±250 dps range (LSB/dps) */
#define GYRO_SCALE 131.0f

/* I2C bus device on Raspberry Pi 3 Model B+ */
#define I2C_DEV "/dev/i2c-1"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write one byte to an 8-bit register */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t ret = write(fd, buf, sizeof(buf));
    if (ret != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read N bytes starting from an 8-bit register */
static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    ssize_t ret = write(fd, &reg, 1);
    if (ret != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ret = read(fd, buf, len);
    if (ret != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Initialize the MPU-6050: wake from sleep and set ±250 dps range */
static int mpu6050_init(int fd)
{
    /* Wake up the MPU-6050 (clear SLEEP bit) */
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0)
        return -1;
    usleep(100000); /* 100 ms settle time after wake */

    /* Set gyroscope full-scale range to ±250 dps (FS_SEL = 0) */
    if (i2c_write_reg8(fd, GYRO_CONFIG, 0x00) < 0)
        return -1;

    return 0;
}

/* Read and convert gyroscope data (degrees/second) */
static int mpu6050_read_gyro(int fd, float *gx, float *gy, float *gz)
{
    uint8_t buf[6];

    if (i2c_read_burst(fd, GYRO_XOUT_H, buf, sizeof(buf)) < 0)
        return -1;

    /* Raw data is big-endian: high byte first, low byte second */
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    *gx = (float)raw_x / GYRO_SCALE;
    *gy = (float)raw_y / GYRO_SCALE;
    *gz = (float)raw_z / GYRO_SCALE;

    return 0;
}

int main(void)
{
    int fd = -1;
    int ret_code = EXIT_FAILURE;

    /* Register signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus device */
    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the MPU-6050 slave address */
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus for address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Initialize the MPU-6050 */
    if (mpu6050_init(fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed (sensor absent or bus error).\n");
        goto cleanup;
    }

    printf("MPU-6050 Gyroscope Reader\n");
    printf("Reading at 10 Hz (Ctrl+C to stop)...\n");

    /* Main loop: read and print gyroscope data */
    while (g_running) {
        float gx, gy, gz;

        if (mpu6050_read_gyro(fd, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "Failed to read gyroscope data.\n");
            /* Brief pause before retrying to avoid log flooding on persistent bus errors */
            usleep(100000);
            continue;
        }

        printf("X: %7.2f dps | Y: %7.2f dps | Z: %7.2f dps\n", gx, gy, gz);
        fflush(stdout);

        usleep(100000); /* 100 ms -> ~10 Hz */
    }

    printf("\nExiting cleanly.\n");
    ret_code = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);

    return ret_code;
}

