/*
 * Automated Plant Watering System (libgpiod v1)
 * Board:  Raspberry Pi 4 Model B
 * Relays: 4 x 5V relay modules on BCM GPIO17,18,27,22
 *         (physical pins 11,12,13,15)
 * Logic:   Active-low relay modules — HIGH = relay OFF, LOW = relay ON
 * Build:   gcc -o watering watering.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS      4
#define WATERING_SEC    5
#define CYCLE_SEC       86400   /* 24 hours */
#define POLL_SEC        60
#define LOG_FILE        "watering_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_watering_start(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Watering cycle started\n", ts) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_RELAYS; i++)
        lines[i] = NULL;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip --- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* --- Get and request each relay line --- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%u) failed: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], "plant-watering", 1) < 0) {
            /* 1 = HIGH = relay OFF (active-low) at startup */
            fprintf(stderr, "gpiod_line_request_output(%u) failed: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    time_t last_cycle = time(NULL);
    if (last_cycle == (time_t)-1) {
        perror("time");
        goto cleanup;
    }

    while (g_running) {
        time_t now = time(NULL);
        if (now == (time_t)-1) {
            perror("time");
            break;
        }

        if (difftime(now, last_cycle) >= CYCLE_SEC) {
            for (int i = 0; i < NUM_RELAYS && g_running; i++) {
                if (gpiod_line_set_value(lines[i], 0) < 0) {
                    fprintf(stderr, "gpiod_line_set_value(%u, 0) failed: %s\n",
                            relay_pins[i], strerror(errno));
                    goto cleanup;
                }

                printf("Watering relay %u (BCM GPIO%u) for %d seconds...\n",
                       i + 1, relay_pins[i], WATERING_SEC);

                if (log_watering_start() < 0) {
                    fprintf(stderr, "Warning: failed to log watering start\n");
                }

                for (int s = 0; s < WATERING_SEC && g_running; s++)
                    sleep(1);

                if (gpiod_line_set_value(lines[i], 1) < 0) {
                    fprintf(stderr, "gpiod_line_set_value(%u, 1) failed: %s\n",
                            relay_pins[i], strerror(errno));
                    goto cleanup;
                }

                last_cycle = now;
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int s = 0; s < POLL_SEC && g_running; s++)
            sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure all relays are left in the safe (OFF) state */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);
            gpiod_line_release(lines[i]);
        }
    }

    if (chip)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nPlant watering system stopped.\n");

    return ret;
}

