#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define PWM_FREQUENCY 1000
#define SUNRISE_DURATION_SEC 1800
#define LOG_FILE "smart_lighting.log"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int set_relay_state(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Failed to write to GPIO %d", pin);
        log_event(msg);
        return -1;
    }
    return 0;
}

static int set_pwm_duty_cycle(int pin, int duty_cycle) {
    if (gpioPWM(pin, duty_cycle) != 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Failed to set PWM on GPIO %d", pin);
        log_event(msg);
        return -1;
    }
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Failed to set GPIO %d as output", pins[i]);
            log_event(msg);
            gpioTerminate();
            return -1;
        }
    }

    int pwm_pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pwm_pins) / sizeof(pwm_pins[0]); ++i) {
        if (gpioSetPWMfrequency(pwm_pins[i], PWM_FREQUENCY) != PWM_FREQUENCY) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Failed to set PWM frequency on GPIO %d", pwm_pins[i]);
            log_event(msg);
            gpioTerminate();
            return -1;
        }
        if (gpioPWM(pwm_pins[i], 0) != 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Failed to initialise PWM on GPIO %d", pwm_pins[i]);
            log_event(msg);
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

static void cleanup_gpio(void) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioPWM(pins[i], 0);
        gpioWrite(pins[i], 0);
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register signal handler");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_event("Sunrise simulation started");

    int duty_cycle = 0;
    int step_count = 0;
    int steps_per_second = SUNRISE_DURATION_SEC / 256;

    while (running && step_count < 256) {
        if (set_pwm_duty_cycle(RELAY1_PIN, duty_cycle) != 0 ||
            set_pwm_duty_cycle(RELAY2_PIN, duty_cycle) != 0 ||
            set_pwm_duty_cycle(RELAY3_PIN, duty_cycle) != 0 ||
            set_pwm_duty_cycle(RELAY4_PIN, duty_cycle) != 0) {
            log_event("Failed to set PWM duty cycle");
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        char msg[128];
        snprintf(msg, sizeof(msg), "Duty cycle: %d", duty_cycle);
        log_event(msg);

        sleep(steps_per_second);
        duty_cycle++;
        step_count++;
    }

    log_event("Sunrise simulation complete");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

