    log_event("Sunrise simulation started");

    int duty_cycle = 0;
    int step_count = 0;
    int steps_per_second = SUNRISE_DURATION_SEC / 256;

    while (running && step_count < 256) {
        if (set_pwm_duty_cycle(RELAY1_PIN, duty_cycle) != 0 ||
            set_pwm_duty_cycle(RELAY2_PIN, duty_cycle) != 0 ||
            set_pwm_duty_cycle(RELAY3_PIN, duty_cycle) != 0 ||
            set_pwm_duty_cycle(RELAY4_PIN, duty_cycle) != 0) {
            log_event("Failed to set PWM duty cycle");
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        char msg[128];
        snprintf(msg, sizeof(msg), "Duty cycle: %d", duty_cycle);
        log_event(msg);

        sleep(steps_per_second);
        duty_cycle++;
        step_count++;
    }

    log_event("Sunrise simulation complete");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

