#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define WHO_AM_I   0x75
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43

/* Expected WHO_AM_I value for MPU-6050 */
#define MPU6050_WHO_AM_I 0x68

/* Sensitivity scale factor for ±250 deg/s range (LSB/deg/s) */
#define GYRO_SCALE 131.0

/* GPIO pin for LED */
#define LED_PIN 17

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Threshold for angular velocity (deg/s) */
#define VELOCITY_THRESHOLD 250.0

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

/* Global variables */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Structure to hold gyroscope data and timestamp */
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

/* Circular buffer */
static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;

/* Function prototypes */
static int init_mpu6050(void);
static int read_gyro_data(float *x, float *y, float *z);
static void add_to_buffer(float x, float y, float z);
static void check_threshold(float x, float y, float z);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* Initialise the MPU-6050 */
static int init_mpu6050(void) {
    int status;

    /* Wake up the MPU-6050 (clear sleep bit) */
    status = i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %d\n", status);
        return -1;
    }
    gpioDelay(100000); /* 100 ms delay for oscillator to stabilise */

    /* Set sample rate divider to 7 (1 kHz / (1 + 7) = 125 Hz output rate) */
    status = i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07);
    if (status < 0) {
        fprintf(stderr, "Error writing to SMPLRT_DIV: %d\n", status);
        return -1;
    }

    /* Set gyroscope full-scale range to ±250 deg/s (FS_SEL = 0) */
    status = i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG: %d\n", status);
        return -1;
    }

    /* Verify sensor identity */
    status = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (status < 0) {
        fprintf(stderr, "Error reading WHO_AM_I: %d\n", status);
        return -1;
    }
    if (status != MPU6050_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n",
                MPU6050_WHO_AM_I, status);
        return -1;
    }

    return 0;
}

/* Read gyroscope data from the MPU-6050 */
static int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;
    int status;

    /* Read 6 bytes of gyroscope data starting at GYRO_XOUT_H */
    status = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading gyroscope data: %d\n", status);
        return -1;
    }
    if (status != 6) {
        fprintf(stderr, "Short read: got %d bytes, expected 6\n", status);
        return -1;
    }

    /* Combine high and low bytes (big-endian) */
    raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    /* Convert to degrees per second */
    *x = (float)raw_x / GYRO_SCALE;
    *y = (float)raw_y / GYRO_SCALE;
    *z = (float)raw_z / GYRO_SCALE;

    return 0;
}

/* Add data to the circular buffer */
static void add_to_buffer(float x, float y, float z) {
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    clock_gettime(CLOCK_REALTIME, &gyro_buffer[buffer_index].timestamp);
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

/* Check if any axis exceeds the threshold */
static void check_threshold(float x, float y, float z) {
    if (fabsf(x) > VELOCITY_THRESHOLD ||
        fabsf(y) > VELOCITY_THRESHOLD ||
        fabsf(z) > VELOCITY_THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

int main(void) {
    float x, y, z;

    /* Register signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set LED pin as output */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Open I2C connection */
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialise MPU-6050 */
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        cleanup();
        return 1;
    }

    /* Main loop */
    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(x, y, z);
            check_threshold(x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data. Re-initialising...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000); /* 100 ms delay before retry */

            i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C connection: %d\n", i2c_handle);
                break;
            }

            if (init_mpu6050() != 0) {
                fprintf(stderr, "MPU-6050 re-initialisation failed\n");
                break;
            }
        }

        gpioDelay(50000); /* 50 ms delay (20 Hz) */
    }

    /* Cleanup */
    cleanup();
    return 0;
}

