#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define CS_LINE_OFFSET  8
#define GYRO_XOUT_H     0x43
#define GYRO_CONFIG     0x1B
#define GYRO_SCALE      131.0f
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0
#define SAMPLE_DELAY_US 10000
#define MAX_RETRIES     3

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_cs_line = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_transfer(int fd, const uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    return 0;
}

static int mpu9250_write_reg(int fd, uint8_t cs, uint8_t reg, uint8_t value)
{
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), value };
    uint8_t rx[2] = { 0 };

    if (gpiod_line_set_value(g_cs_line, 0) < 0) {
        return -1;
    }
    if (spi_transfer(fd, tx, rx, 2) < 0) {
        gpiod_line_set_value(g_cs_line, 1);
        return -1;
    }
    if (gpiod_line_set_value(g_cs_line, 1) < 0) {
        return -1;
    }
    return 0;
}

static int mpu9250_read_burst(int fd, uint8_t cs, uint8_t reg, uint8_t *buf, size_t len)
{
    uint8_t tx[len + 1];
    uint8_t rx[len + 1];

    memset(tx, 0, sizeof(tx));
    tx[0] = (uint8_t)(reg | 0x80);
    memset(rx, 0, sizeof(rx));

    if (gpiod_line_set_value(g_cs_line, 0) < 0) {
        return -1;
    }
    if (spi_transfer(fd, tx, rx, len + 1) < 0) {
        gpiod_line_set_value(g_cs_line, 1);
        return -1;
    }
    if (gpiod_line_set_value(g_cs_line, 1) < 0) {
        return -1;
    }

    memcpy(buf, rx + 1, len);
    return 0;
}

static int init_mpu9250(int fd)
{
    if (mpu9250_write_reg(fd, 0, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing GYRO_CONFIG: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_gyro_data(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    int16_t raw_x, raw_y, raw_z;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (mpu9250_read_burst(fd, 0, GYRO_XOUT_H, buf, 6) == 0) {
            raw_x = (int16_t)((buf[0] << 8) | buf[1]);
            raw_y = (int16_t)((buf[2] << 8) | buf[3]);
            raw_z = (int16_t)((buf[4] << 8) | buf[5]);

            *x = (float)raw_x / GYRO_SCALE;
            *y = (float)raw_y / GYRO_SCALE;
            *z = (float)raw_z / GYRO_SCALE;
            return 0;
        }
        fprintf(stderr, "SPI read attempt %d/%d failed: %s\n",
                attempt + 1, MAX_RETRIES, strerror(errno));
        usleep(1000);
    }
    return -1;
}

static void log_data(FILE *fp, float x, float y, float z)
{
    struct timespec ts;
    struct tm tm_info;
    char timestamp[40];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp),
             sizeof(timestamp) - strlen(timestamp),
             ".%09ld", ts.tv_nsec);

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }
    fflush(fp);
}

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_cs_line) {
        gpiod_line_release(g_cs_line);
        g_cs_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

int main(void)
{
    struct sigaction sa;
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    g_chip = gpiod_chip_open(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    g_cs_line = gpiod_chip_get_line(g_chip, CS_LINE_OFFSET);
    if (!g_cs_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", CS_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return 1;
    }

    if (gpiod_line_request_output(g_cs_line, "mpu9250-cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        g_cs_line = NULL;
        return 1;
    }

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        cleanup();
        return 1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (init_mpu9250(g_spi_fd) < 0) {
        fprintf(stderr, "MPU-9250 initialization failed.\n");
        cleanup();
        return 1;
    }

    g_log_fp = fopen("gyro_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open gyro_log.txt: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    fprintf(g_log_fp, "# timestamp,x_rate_dps,y_rate_dps,z_rate_dps\n");
    fflush(g_log_fp);

