#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 3900000
#define SPI_MODE 0
#define SPI_BITS 8

#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define GYRO_CONFIG 0x1B
#define GYRO_SMPLRT_DIV 0x19
#define GYRO_WHO_AM_I 0x75
#define MPU6050_WHO_AM_I_VAL 0x68

#define LED_GPIO 17
#define CS_GPIO 8
#define BUFFER_SIZE 64
#define THRESHOLD 200.0f
#define SAMPLE_DELAY_US 100000

#define GYRO_SENSITIVITY 131.0f

typedef struct {
    time_t timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Failed to assert CS: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }
    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6050_read_register(uint8_t reg, uint8_t *value) {
    uint8_t tx[2] = { reg | 0x80, 0x00 };
    uint8_t rx[2] = { 0 };
    if (spi_transfer(tx, rx, 2) < 0) return -1;
    *value = rx[1];
    return 0;
}

static int mpu6050_write_register(uint8_t reg, uint8_t value) {
    uint8_t tx[2] = { reg & 0x7F, value };
    uint8_t rx[2] = { 0 };
    return spi_transfer(tx, rx, 2);
}

static int mpu6050_init(void) {
    uint8_t who_am_i = 0;
    if (mpu6050_read_register(GYRO_WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I\n");
        return -1;
    }
    if (who_am_i != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: 0x%02X (expected 0x%02X)\n", who_am_i, MPU6050_WHO_AM_I_VAL);
        return -1;
    }
    if (mpu6050_write_register(GYRO_CONFIG, 0x00) < 0) return -1;
    if (mpu6050_write_register(GYRO_SMPLRT_DIV, 0x07) < 0) return -1;
    return 0;
}

static int read_gyro_data(float *x, float *y, float *z) {
    uint8_t x_h = 0, x_l = 0, y_h = 0, y_l = 0, z_h = 0, z_l = 0;
    if (mpu6050_read_register(GYRO_XOUT_H, &x_h) < 0) return -1;
    if (mpu6050_read_register(GYRO_XOUT_H, &x_l) < 0) return -1;
    if (mpu6050_read_register(GYRO_YOUT_H, &y_h) < 0) return -1;
    if (mpu6050_read_register(GYRO_YOUT_H, &y_l) < 0) return -1;
    if (mpu6050_read_register(GYRO_ZOUT_H, &z_h) < 0) return -1;
    if (mpu6050_read_register(GYRO_ZOUT_H, &z_l) < 0) return -1;
    int16_t raw_x = (int16_t)((x_h << 8) | x_l);
    int16_t raw_y = (int16_t)((y_h << 8) | y_l);
    int16_t raw_z = (int16_t)((z_h << 8) | z_l);
    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;
    return 0;
}

static void add_to_buffer(float x, float y, float z) {
    gyro_buffer[buffer_index].timestamp = time(NULL);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_buffer(void) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm_info = localtime(&gyro_buffer[idx].timestamp);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("%s,%.2f,%.2f,%.2f\n", ts, gyro_buffer[idx].x, gyro_buffer[idx].y, gyro_buffer[idx].z);
    }
    fflush(stdout);
}

static void check_threshold(float x, float y, float z) {
    if (x > THRESHOLD || x < -THRESHOLD ||
        y > THRESHOLD || y < -THRESHOLD ||
        z > THRESHOLD || z < -THRESHOLD) {
        gpiod_line_set_value(cs_line, 0);
        gpiod_line_set_value(cs_line, 1);
        usleep(500000);
        gpiod_line_set_value(cs_line, 0);
        gpiod_line_set_value(cs_line, 1);
    }
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return 1;
    }
    cs_line = gpiod_chip_get_line(chip, CS_GPIO);
    if (!cs_line) {
        fprintf(stderr, "Failed to get CS GPIO line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(cs_line, "mpu6050_cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (mpu6050_init() < 0) {
        fprintf(stderr, "MPU6050 initialization failed\n");
        cleanup();
        return 1;
    }

    printf("MPU6050 initialized. Reading gyroscope data...\n");

    while (running) {
        float x, y, z;
        if (read_gyro_data(&x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read gyro data\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }
        add_to_buffer(x, y, z);
        check_threshold(x, y, z);
        usleep(SAMPLE_DELAY_US);
    }

    printf("\nExiting...\n");
    print_buffer();
    cleanup();
    return 0;
}

