    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_buffer(void) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm_info = localtime(&gyro_buffer[idx].timestamp);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("%s,%.2f,%.2f,%.2f\n", ts, gyro_buffer[idx].x, gyro_buffer[idx].y, gyro_buffer[idx].z);
    }
    fflush(stdout);
}

static void check_threshold(float x, float y, float z) {
    if (x > THRESHOLD || x < -THRESHOLD ||
        y > THRESHOLD || y < -THRESHOLD ||
        z > THRESHOLD || z < -THRESHOLD) {
        gpiod_line_set_value(cs_line, 0);
        gpiod_line_set_value(cs_line, 1);
        usleep(500000);
        gpiod_line_set_value(cs_line, 0);
        gpiod_line_set_value(cs_line, 1);
    }
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return 1;
    }
    cs_line = gpiod_chip_get_line(chip, CS_GPIO);
    if (!cs_line) {
        fprintf(stderr, "Failed to get CS GPIO line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(cs_line, "mpu6050_cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (mpu6050_init() < 0) {
        fprintf(stderr, "MPU6050 initialization failed\n");
        cleanup();
        return 1;
    }

    printf("MPU6050 initialized. Reading gyroscope data...\n");

    while (running) {
        float x, y, z;
        if (read_gyro_data(&x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read gyro data\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }
        add_to_buffer(x, y, z);
        check_threshold(x, y, z);
        usleep(SAMPLE_DELAY_US);
    }

    printf("\nExiting...\n");
    print_buffer();
    cleanup();
    return 0;
}

