#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40

/* GPIO pin for LED */
#define LED_PIN 21

/* Tilt thresholds (degrees) */
#define TILT_THRESHOLD_ROLL  45.0
#define TILT_THRESHOLD_PITCH 45.0

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 100000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown on SIGINT / SIGTERM            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an MPU-6050 register                             */
/* ------------------------------------------------------------------ */
static int mpu_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of accelerometer data from ACCEL_XOUT_H               */
/* ------------------------------------------------------------------ */
static int mpu_read_accel(int handle, int16_t *ax, int16_t *ay, int16_t *az)
{
    char buf[6];
    int rc = i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Error: i2cReadI2CBlockData failed: %d\n", rc);
        return -1;
    }
    *ax = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    *ay = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    *az = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw accelerometer data to roll and pitch (degrees)          */
/* ------------------------------------------------------------------ */
static void calc_tilt(int16_t ax, int16_t ay, int16_t az,
                      double *roll, double *pitch)
{
    /* Sensitivity for ±2g range: 16384 LSB/g */
    double ax_g = (double)ax / 16384.0;
    double ay_g = (double)ay / 16384.0;
    double az_g = (double)az / 16384.0;

    *roll  = atan2(ay_g, az_g) * 180.0 / M_PI;
    *pitch = atan2(-ax_g, sqrt(ay_g * ay_g + az_g * az_g)) * 180.0 / M_PI;
}

/* ------------------------------------------------------------------ */
/* Log a reading to tilt_log.txt                                      */
/* ------------------------------------------------------------------ */
static void log_data(double roll, double pitch)
{
    FILE *fp = fopen("tilt_log.txt", "a");
    if (!fp) {
        perror("Error opening tilt_log.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, roll, pitch);
    } else {
        fprintf(fp, "timestamp_error,%.2f,%.2f\n", roll, pitch);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path                          */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* Open I2C bus 1 at MPU-6050 address */
    g_i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                MPU6050_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Wake up MPU-6050 (clear SLEEP bit) */
    if (mpu_write_reg(g_i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to wake MPU-6050\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(100000); /* 100 ms settle time */

    /* Set accelerometer full-scale range to ±2g (AFS_SEL = 0) */
    if (mpu_write_reg(g_i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to configure ACCEL_CONFIG\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialised. Sampling every 100 ms. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t ax, ay, az;

        if (mpu_read_accel(g_i2c_handle, &ax, &ay, &az) == 0) {
            double roll, pitch;
            calc_tilt(ax, ay, az, &roll, &pitch);

            log_data(roll, pitch);
            printf("Roll: %.2f deg, Pitch: %.2f deg\n", roll, pitch);

            if (fabs(roll) > TILT_THRESHOLD_ROLL ||
                fabs(pitch) > TILT_THRESHOLD_PITCH) {
                gpioWrite(LED_PIN, 1);
            } else {
                gpioWrite(LED_PIN, 0);
            }
        } else {
            fprintf(stderr, "Warning: sensor read failed, continuing...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

