#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ADXRS290 register addresses (datasheet) */
#define ADXRS290_X_RATE_REG 0x02
#define ADXRS290_Y_RATE_REG 0x04

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* Mode 0, active-low CE */

/* Sensitivity: 200 LSB/deg/s (from datasheet) */
#define GYRO_SENSITIVITY 200.0f

/* Sampling interval: 10 ms -> 100 Hz */
#define SAMPLE_DELAY_US 10000

/* Retry limits */
#define MAX_RETRIES 3

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/*
 * Read a 16-bit register from the ADXRS290.
 * SPI protocol: send address | 0x80 (read bit) | dummy, then the response
 * is the second byte of the transfer.
 * Returns 0 on success, -1 on failure.
 */
static int read_gyro_register(uint8_t reg, int16_t *out)
{
    char tx[2];
    char rx[2];

    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00;

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }

    /* rx[0] is the dummy byte sent back, rx[1] is the high byte of the data */
    *out = (int16_t)((uint16_t)rx[1] << 8);
    return 0;
}

static int read_gyro_data(gyro_data_t *data)
{
    if (read_gyro_register(ADXRS290_X_RATE_REG, &data->x_rate) != 0)
        return -1;
    if (read_gyro_register(ADXRS290_Y_RATE_REG, &data->y_rate) != 0)
        return -1;
    return 0;
}

static void log_data(const gyro_data_t *data)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    fprintf(log_file, "%ld.%06ld,%d,%d\n",
            (long)ts.tv_sec, ts.tv_nsec / 1000,
            data->x_rate, data->y_rate);
    fflush(log_file);
}

static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    int retries = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz): %s\n",
                SPI_CHANNEL, SPI_SPEED, pigpio_error(spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_data.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open gyro_data.csv: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(log_file, "timestamp,x_rate_raw,y_rate_raw\n");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXRS290 Gyroscope Data Logger\n");
    printf("SPI channel %d, %d Hz, 100 Hz sampling. Press Ctrl+C to stop.\n",
           SPI_CHANNEL, SPI_SPEED);

    while (!terminate) {
        gyro_data_t data;

        if (read_gyro_data(&data) != 0) {
            fprintf(stderr, "Gyro read failed, attempting SPI reinit...\n");
            retries++;
            if (spiClose(spi_handle) != 0)
                fprintf(stderr, "spiClose failed during reinit\n");
            spi_handle = -1;

            if (spi_handle < 0) {
                spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
                if (spi_handle < 0) {
                    fprintf(stderr, "SPI reinit failed: %s\n",
                            pigpio_error(spi_handle));
                    if (retries >= MAX_RETRIES) {
                        fprintf(stderr, "Max retries reached. Exiting.\n");
                        break;
                    }
                    gpioDelay(100000);
                    continue;
                }
            }
            continue;
        }

        log_data(&data);
        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

