#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN    17

#define SEISMIC_THRESHOLD_MS 500
#define ALERT_DURATION_MS   2000
#define POLL_DELAY_US       10000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];
    if (t) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    } else {
        strncpy(timestamp, "UNKNOWN", sizeof(timestamp));
    }
    fprintf(log_file, "%s - %s\n", timestamp, message);
    fflush(log_file);
}

static void trigger_alert(void) {
    if (gpioWrite(ALERT_PIN, 1) < 0) {
        log_event("ERROR: Failed to set alert pin HIGH");
        return;
    }
    gpioDelay(ALERT_DURATION_MS * 1000);
    if (gpioWrite(ALERT_PIN, 0) < 0) {
        log_event("ERROR: Failed to set alert pin LOW");
    }
}

static void sensor_callback(int gpio, int level, uint32_t tick) {
    (void)tick;
    static uint32_t last_edge_tick[2] = {0, 0};
    static int last_level[2] = {0, 0};
    static uint32_t last_high_tick[2] = {0, 0};
    static int in_high_state[2] = {0, 0};

    int idx = (gpio == SENSOR_1_PIN) ? 0 : 1;

    if (level != PI_TIMEOUT) {
        uint32_t diff = tick - last_edge_tick[idx];
        if (diff > 0 && diff < (uint32_t)(SEISMIC_THRESHOLD_MS * 1000)) {
            if (level == 1) {
                if (!in_high_state[idx]) {
                    last_high_tick[idx] = tick;
                    in_high_state[idx] = 1;
                }
            } else {
                if (in_high_state[idx]) {
                    in_high_state[idx] = 0;
                }
            }
        }
        last_edge_tick[idx] = tick;
        last_level[idx] = level;
    }

    if (in_high_state[0] && in_high_state[1]) {
        uint32_t elapsed = tick - last_high_tick[0];
        if (elapsed >= (uint32_t)(SEISMIC_THRESHOLD_MS * 1000)) {
            log_event("Seismic event detected!");
            trigger_alert();
            in_high_state[0] = 0;
            in_high_state[1] = 0;
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("seismic_events.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0 ||
        gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) < 0 ||
        gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down resistors\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALERT_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise alert pin LOW\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(SENSOR_1_PIN, sensor_callback) < 0 ||
        gpioSetAlertFunc(SENSOR_2_PIN, sensor_callback) < 0) {
        fprintf(stderr, "Failed to register alert callbacks\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Seismic monitoring system started");

    while (running) {
        gpioDelay(POLL_DELAY_US);
    }

    log_event("Seismic monitoring system stopped");
    gpioWrite(ALERT_PIN, 0);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

