    static int in_high_state[2] = {0, 0};

    int idx = (gpio == SENSOR_1_PIN) ? 0 : 1;

    if (level != PI_TIMEOUT) {
        uint32_t diff = tick - last_edge_tick[idx];
        if (diff > 0 && diff < (uint32_t)(SEISMIC_THRESHOLD_MS * 1000)) {
            if (level == 1) {
                if (!in_high_state[idx]) {
                    last_high_tick[idx] = tick;
                    in_high_state[idx] = 1;
                }
            } else {
                if (in_high_state[idx]) {
                    in_high_state[idx] = 0;
                }
            }
        }
        last_edge_tick[idx] = tick;
        last_level[idx] = level;
    }

    if (in_high_state[0] && in_high_state[1]) {
        uint32_t elapsed = tick - last_high_tick[0];
        if (elapsed >= (uint32_t)(SEISMIC_THRESHOLD_MS * 1000)) {
            log_event("Seismic event detected!");
            trigger_alert();
            in_high_state[0] = 0;
            in_high_state[1] = 0;
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("seismic_events.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0 ||
        gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) < 0 ||
        gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down resistors\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALERT_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise alert pin LOW\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(SENSOR_1_PIN, sensor_callback) < 0 ||
        gpioSetAlertFunc(SENSOR_2_PIN, sensor_callback) < 0) {
        fprintf(stderr, "Failed to register alert callbacks\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Seismic monitoring system started");

    while (running) {
        gpioDelay(POLL_DELAY_US);
    }

    log_event("Seismic monitoring system stopped");
    gpioWrite(ALERT_PIN, 0);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

