#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>
#include <pthread.h>

/* ADXRS290 Register Addresses */
#define ADXRS290_REG_RATE_XL 0x02
#define ADXRS290_REG_RATE_XH 0x03

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 /* 1 MHz */
#define SPI_MODE 0

/* LED GPIO */
#define LED_GPIO 17

/* Angular Velocity Threshold (degrees per second) */
#define VELOCITY_THRESHOLD 20.0

/* Gyroscope Sensitivity (LSB per deg/s) */
#define GYRO_SENSITIVITY 200.0

/* Circular Buffer Size */
#define BUFFER_SIZE 100

/* Structure to hold gyroscope data */
typedef struct {
    struct timespec timestamp;
    double angular_velocity;
} GyroData;

/* Circular buffer structure */
typedef struct {
    GyroData data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

/* Global variables */
static int spi_handle = -1;
static CircularBuffer gyro_buffer;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int initialize_spi(void);
static int read_gyro_data(double *angular_velocity);
static void add_to_buffer(CircularBuffer *buffer, double angular_velocity);
static void check_threshold(double angular_velocity);
static void signal_handler(int signal);
static void cleanup(void);

/* Initialize SPI */
static int initialize_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

/* Read gyroscope data from ADXRS290 */
static int read_gyro_data(double *angular_velocity) {
    char tx_buf[2];
    char rx_buf[2];
    int16_t raw_data;

    /* Read RATE_XL (0x02) */
    tx_buf[0] = ADXRS290_REG_RATE_XL | 0x80; /* MSB = 1 for read */
    tx_buf[1] = 0x00;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error reading RATE_XL\n");
        return -1;
    }
    raw_data = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);

    /* Read RATE_XH (0x03) */
    tx_buf[0] = ADXRS290_REG_RATE_XH | 0x80;
    tx_buf[1] = 0x00;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error reading RATE_XH\n");
        return -1;
    }
    raw_data = (raw_data << 8) | (int16_t)((rx_buf[0] << 8) | rx_buf[1]);

    /* Convert to degrees per second */
    *angular_velocity = (double)raw_data / GYRO_SENSITIVITY;

    return 0;
}

/* Add data to circular buffer */
static void add_to_buffer(CircularBuffer *buffer, double angular_velocity) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head].timestamp = ts;
    buffer->data[buffer->head].angular_velocity = angular_velocity;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

/* Check if angular velocity exceeds threshold */
static void check_threshold(double angular_velocity) {
    if (fabs(angular_velocity) > VELOCITY_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); /* Turn LED on */
    } else {
        gpioWrite(LED_GPIO, 0); /* Turn LED off */
    }
}

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_GPIO, 0); /* Turn off LED */
    gpioTerminate();
}

int main(void) {
    double angular_velocity;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Initialize SPI */
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    /* Set LED GPIO as output */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); /* Ensure LED is off initially */

    /* Initialize circular buffer */
    gyro_buffer.head = 0;
    gyro_buffer.tail = 0;
    gyro_buffer.count = 0;
    if (pthread_mutex_init(&gyro_buffer.mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        cleanup();
        return 1;
    }

    /* Set up signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Main loop */
    while (program_running) {
        if (read_gyro_data(&angular_velocity) == 0) {
            add_to_buffer(&gyro_buffer, angular_velocity);
            check_threshold(angular_velocity);
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }
        gpioDelay(10000); /* 10 ms delay */
    }

    /* Cleanup */
    cleanup();
    pthread_mutex_destroy(&gyro_buffer.mutex);

    return 0;
}

