#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27
#define PWM_RANGE 255
#define PWM_FREQ 100
#define MIN_DURATION 1
#define MAX_DURATION 3600

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_pwm_duty(int gpio, int duty) {
    if (duty < 0 || duty > PWM_RANGE) {
        fprintf(stderr, "Error: duty cycle %d out of range [0-%d]\n", duty, PWM_RANGE);
        return -1;
    }
    if (gpioPWM(gpio, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

static int fade_lamp(int gpio, int duration_ms) {
    if (duration_ms <= 0) {
        fprintf(stderr, "Error: invalid fade duration %d ms\n", duration_ms);
        return -1;
    }

    printf("Fading lamp on GPIO %d over %d ms...\n", gpio, duration_ms);
    fflush(stdout);

    int steps = duration_ms / 10;
    if (steps < 1) steps = 1;

    for (int i = 0; i <= PWM_RANGE && g_running; i++) {
        int duty = (PWM_RANGE * i) / steps;
        if (set_pwm_duty(gpio, duty) != 0) {
            return -1;
        }
        gpioDelay(duration_ms / steps);
    }

    if (set_pwm_duty(gpio, 0) != 0) {
        return -1;
    }
    printf("Lamp on GPIO %d faded to off.\n", gpio);
    fflush(stdout);
    return 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    int gpios[] = {LAMP1_GPIO, LAMP2_GPIO, LAMP3_GPIO};
    for (size_t i = 0; i < sizeof(gpios) / sizeof(gpios[0]); i++) {
        int gpio = gpios[i];
        if (gpioSetMode(gpio, PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed on GPIO %d\n", gpio);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMrange(gpio, PWM_RANGE) != 0) {
            fprintf(stderr, "Error: gpioSetPWMrange failed on GPIO %d\n", gpio);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMfrequency(gpio, PWM_FREQ) != 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency failed on GPIO %d\n", gpio);
            gpioTerminate();
            return -1;
        }
        if (set_pwm_duty(gpio, PWM_RANGE) != 0) {
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void) {
    int gpios[] = {LAMP1_GPIO, LAMP2_GPIO, LAMP3_GPIO};
    for (size_t i = 0; i < sizeof(gpios) / sizeof(gpios[0]); i++) {
        gpioWrite(gpios[i], 0);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_seconds>\n", argv[0]);
        fprintf(stderr, "Fade duration must be an integer between %d and %d.\n", MIN_DURATION, MAX_DURATION);
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    long duration = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || duration < MIN_DURATION || duration > MAX_DURATION) {
        fprintf(stderr, "Error: invalid duration '%s'. Must be an integer between %d and %d.\n", argv[1], MIN_DURATION, MAX_DURATION);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Smart Sunset Simulator started. Fade duration: %ld seconds\n", duration);
    fflush(stdout);

    int lamp_gpios[] = {LAMP1_GPIO, LAMP2_GPIO, LAMP3_GPIO};
    for (size_t i = 0; i < sizeof(lamp_gpios) / sizeof(lamp_gpios[0]) && g_running; i++) {
        int gpio = lamp_gpios[i];
        int duration_ms = (int)((duration * 1000) / (sizeof(lamp_gpios) / sizeof(lamp_gpios[0])));
        if (fade_lamp(gpio, duration_ms) != 0) {
            cleanup_gpio();
            return EXIT_FAILURE;
        }
        if (i < sizeof(lamp_gpios) / sizeof(lamp_gpios[0]) - 1 && g_running) {
            gpioDelay(1000);
        }
    }

    printf("Smart Sunset Simulator finished.\n");
    fflush(stdout);
    cleanup_gpio();
    return EXIT_SUCCESS;
}

