#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define LOG_FILE "touch_relay.log"

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5D
#define MPR121_TOUCH_THRESHOLD 0x41
#define MPR121_RELEASE_THRESHOLD 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CHARGE_TIME 0x5C
#define MPR121_SOFTRESET 0x80
#define MPR121_MODE_CONFIG 0x5E

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void log_error(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d", reg, value, rc);
        log_error(buf);
    }
    return rc;
}

static int mpr121_init(int handle) {
    /* Soft reset */
    if (mpr121_write_reg(handle, MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(1000); /* 1 ms */

    /* Stop mode */
    if (mpr121_write_reg(handle, MPR121_MODE_CONFIG, 0x00) < 0) return -1;

    /* Enable electrode 0 */
    if (mpr121_write_reg(handle, MPR121_ELECTRODE_CONFIG, 0x01) < 0) return -1;

    /* Touch and release thresholds for electrode 0 */
    if (mpr121_write_reg(handle, MPR121_TOUCH_THRESHOLD, 0x0A) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_RELEASE_THRESHOLD, 0x08) < 0) return -1;

    /* Debounce: 3 samples for touch, 3 for release */
    if (mpr121_write_reg(handle, MPR121_DEBOUNCE, 0x21) < 0) return -1;

    /* Charge time: 0.5 us */
    if (mpr121_write_reg(handle, MPR121_CHARGE_TIME, 0x0D) < 0) return -1;

    /* Run mode: baseline tracking, 16 electrodes */
    if (mpr121_write_reg(handle, MPR121_MODE_CONFIG, 0x0D) < 0) return -1;

    gpioDelay(1000); /* 1 ms settle */
    return 0;
}

static int read_touch_status(int handle) {
    int lsb = i2cReadByteData(handle, MPR121_TOUCHSTATUS_L);
    if (lsb < 0) {
        log_error("Failed to read touch status LSB");
        return -1;
    }
    int msb = i2cReadByteData(handle, MPR121_TOUCHSTATUS_H);
    if (msb < 0) {
        log_error("Failed to read touch status MSB");
        return -1;
    }
    return (msb << 8) | lsb;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Failed to open I2C device at bus %d addr 0x%02X: %d", I2C_BUS, MPR121_ADDR, i2c_handle);
        log_error(buf);
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (mpr121_init(i2c_handle) < 0) {
        log_error("MPR121 initialisation failed");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int relay_state = 0;
    int last_touch = 0;

    while (running) {
        int touch = read_touch_status(i2c_handle);
        if (touch < 0) {
            gpioDelay(10000); /* 10 ms backoff on error */
            continue;
        }

        int electrode0 = (touch & 0x01) != 0;

        if (electrode0 && !last_touch) {
            relay_state = !relay_state;
            gpioWrite(RELAY_GPIO, relay_state);
            printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
            gpioDelay(100000); /* 100 ms debounce */
        }

        last_touch = electrode0;
        gpioDelay(10000); /* 10 ms poll interval */
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

