static int log_event(FILE *log_file, const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error: failed to write to log file\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: failed to flush log file\n");
        return -1;
    }

    return 0;
}

static int debounce_read(struct gpiod_line *line) {
    int first = gpiod_line_get_value(line);
    if (first < 0) {
        fprintf(stderr, "Error: failed to read GPIO line\n");
        return -1;
    }

    usleep(DEBOUNCE_DELAY_MS * 1000);

    int second = gpiod_line_get_value(line);
    if (second < 0) {
        fprintf(stderr, "Error: failed to read GPIO line\n");
        return -1;
    }

    if (first != second) {
        usleep(DEBOUNCE_DELAY_MS * 1000);
        int third = gpiod_line_get_value(line);
        if (third < 0) {
            fprintf(stderr, "Error: failed to read GPIO line\n");
            return -1;
        }
        return (first == third) ? first : -1;
    }

    return first;
}

