#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DISPENSE_DURATION_MS 1000
#define CYCLE_DELAY_MS 5000
#define LOG_FILE "dispense_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int activate_solenoid(int pin, int duration_ms) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error: failed to activate solenoid on GPIO %d\n", pin);
        return -1;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: failed to deactivate solenoid on GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static int log_dispense(int pin1, int pin2, int duration_ms) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Solenoid 1 (GPIO %d) and Solenoid 2 (GPIO %d) dispensed for %d ms\n",
            timestamp, pin1, pin2, duration_ms);
    fclose(fp);
    return 0;
}

static int dispense(int pin1, int pin2, int duration_ms) {
    int half_duration = duration_ms / 2;
    if (activate_solenoid(pin1, half_duration) != 0) {
        return -1;
    }
    if (activate_solenoid(pin2, half_duration) != 0) {
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(SOLENOID_1_PIN, 0) != 0 || gpioWrite(SOLENOID_2_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise solenoid pins to LOW\n");
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error registering SIGINT handler");
        gpioWrite(SOLENOID_1_PIN, 0);
        gpioWrite(SOLENOID_2_PIN, 0);
        gpioTerminate();
        return 1;
    }
    while (running) {
        if (dispense(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION_MS) != 0) {
            fprintf(stderr, "Error during dispense cycle\n");
        }
        if (log_dispense(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION_MS) != 0) {
            fprintf(stderr, "Error logging dispense event\n");
        }
        if (running) {
            gpioDelay(CYCLE_DELAY_MS * 1000);
        }
    }
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);
    gpioTerminate();
    return 0;
}

