/* Motor B */
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

/* L298N Enable Pins */
#define MOTOR_A_ENABLE 24
#define MOTOR_B_ENABLE 25

/* PID Gains */
#define KP 1.0
#define KI 0.01
#define KD 0.1

/* Obstacle Avoidance Threshold (cm) */
#define OBSTACLE_THRESHOLD 20.0

/* Obstacle Avoidance Speed (percentage) */
#define OBSTACLE_AVOIDANCE_SPEED 50

/* PWM Range */
#define PWM_RANGE 255

/* Control Loop Interval (ms) */
#define LOOP_INTERVAL_MS 50

/* Log File Name */
#define LOG_FILE "balance_log.txt"

/* Global Variables */
static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* Function Prototypes */
static void signal_handler(int signal);
static void stop_motors(void);
static int initialize_gpio(void);
static void set_motor_speed(int motor_a_speed, int motor_b_speed);
static int pid_control(float tilt_error, float *integral, float *previous_error);
static float simulate_ultrasonic_sensor(void);
static void obstacle_avoidance(float distance);
static void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);

/* Signal Handler */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Stop Motors */
static void stop_motors(void) {
    gpioPWM(MOTOR_A_FORWARD, 0);
    gpioPWM(MOTOR_A_BACKWARD, 0);
    gpioPWM(MOTOR_B_FORWARD, 0);
    gpioPWM(MOTOR_B_BACKWARD, 0);
}

/* Initialize GPIO */
static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    /* Set motor pins as outputs */
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);

    /* Set enable pins as outputs and set HIGH */
    gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT);
    gpioWrite(MOTOR_A_ENABLE, 1);
    gpioWrite(MOTOR_B_ENABLE, 1);

    /* Set PWM range */
    gpioSetPWMrange(MOTOR_A_FORWARD, PWM_RANGE);
    gpioSetPWMrange(MOTOR_A_BACKWARD, PWM_RANGE);
    gpioSetPWMrange(MOTOR_B_FORWARD, PWM_RANGE);
    gpioSetPWMrange(MOTOR_B_BACKWARD, PWM_RANGE);

    return 0;
}

/* Set Motor Speeds */
static void set_motor_speed(int motor_a_speed, int motor_b_speed) {
    /* Clamp motor speeds to +/-255 */
    if (motor_a_speed > 255) motor_a_speed = 255;
    if (motor_a_speed < -255) motor_a_speed = -255;
    if (motor_b_speed > 255) motor_b_speed = 255;
    if (motor_b_speed < -255) motor_b_speed = -255;

    /* Motor A */
    if (motor_a_speed > 0) {
        gpioPWM(MOTOR_A_FORWARD, motor_a_speed);
        gpioPWM(MOTOR_A_BACKWARD, 0);
    } else if (motor_a_speed < 0) {
        gpioPWM(MOTOR_A_FORWARD, 0);
        gpioPWM(MOTOR_A_BACKWARD, -motor_a_speed);
    } else {
        gpioPWM(MOTOR_A_FORWARD, 0);
        gpioPWM(MOTOR_A_BACKWARD, 0);
    }

    /* Motor B */
    if (motor_b_speed > 0) {
        gpioPWM(MOTOR_B_FORWARD, motor_b_speed);
        gpioPWM(MOTOR_B_BACKWARD, 0);
    } else if (motor_b_speed < 0) {
        gpioPWM(MOTOR_B_FORWARD, 0);
        gpioPWM(MOTOR_B_BACKWARD, -motor_b_speed);
    } else {
        gpioPWM(MOTOR_B_FORWARD, 0);
        gpioPWM(MOTOR_B_BACKWARD, 0);
    }
}

/* PID Control */
static int pid_control(float tilt_error, float *integral, float *previous_error) {
    float derivative = tilt_error - *previous_error;
    *integral += tilt_error;

    float output = KP * tilt_error + KI * (*integral) + KD * derivative;

    *previous_error = tilt_error;

    return (int)output;
}

/* Simulate Ultrasonic Sensor */
static float simulate_ultrasonic_sensor(void) {
    return (float)(rand() % 400 + 2);
}

/* Obstacle Avoidance */
static void obstacle_avoidance(float distance) {
    if (distance < OBSTACLE_THRESHOLD) {
        set_motor_speed(-OBSTACLE_AVOIDANCE_SPEED, -OBSTACLE_AVOIDANCE_SPEED);
    }
}

/* Log Data */
static void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %.2f, %d, %d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

int main(void) {
    float tilt_error, integral = 0.0, previous_error = 0.0;
    float distance;
    int motor_a_speed, motor_b_speed;

    /* Register signal handler */
    signal(SIGINT, signal_handler);

    /* Initialize GPIO */
    if (initialize_gpio() != 0) {
        return 1;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    /* Main loop */
    while (running) {
        /* Simulate tilt error */
        tilt_error = (float)(rand() % 21 - 10);

        /* PID Control */
        motor_a_speed = pid_control(tilt_error, &integral, &previous_error);
        motor_b_speed = pid_control(tilt_error, &integral, &previous_error);

        /* Set Motor Speeds */
        set_motor_speed(motor_a_speed, motor_b_speed);

        /* Simulate Ultrasonic Sensor */
        distance = simulate_ultrasonic_sensor();

        /* Obstacle Avoidance */
        obstacle_avoidance(distance);

        /* Log Data */
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        /* Delay */
        gpioDelay(LOOP_INTERVAL_MS * 1000);
    }

    /* Cleanup */
    stop_motors();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

