#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000  /* 50 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure relay starts in the OFF state (active-high relay: LOW = OFF) */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay state on GPIO%d.\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    /* Enable internal pull-down on the touch sensor pin so it reads LOW when untouched */
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO%d (sensor may float).\n", TOUCH_SENSOR_PIN);
    }

    return 0;
}

static void cleanup_gpio(void) {
    /* Best-effort: ensure relay is off before terminating */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Smart light switch ready. Touch the sensor (GPIO%d) to toggle the relay (GPIO%d).\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    int relay_state = 0;
    int last_touch_state = 0;

    while (running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d.\n", TOUCH_SENSOR_PIN);
            break;
        }

        /* Detect rising edge: touch pressed (HIGH) */
        if (touch_state == 1 && last_touch_state == 0) {
            relay_state = !relay_state;
            if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                fprintf(stderr, "Error: failed to write GPIO%d.\n", RELAY_PIN);
                break;
            }
            printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
            gpioDelay(DEBOUNCE_DELAY_US);
        }

        last_touch_state = touch_state;
        gpioDelay(10000); /* 10 ms poll interval */
    }

    cleanup_gpio();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

