/*
 * mood_light.c — Raspberry Pi 3 Model B+
 *
 * Drives a common-cathode RGB LED via pigpio software PWM,
 * with color mapped to ambient noise amplitude from ALSA.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mood_light mood_light.c -lpigpio -lasound
 * Run:    ./mood_light [sensitivity_scale]
 *
 * GPIO:   GPIO17 (red), GPIO18 (green), GPIO27 (blue)
 * ALSA:   default capture device @ 8000 Hz, 16-bit, 1 channel, 1024 period
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#ifdef ALSA_AVAILABLE
#include <alsa/asoundlib.h>
#endif

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define SAMPLE_RATE  8000
#define PERIOD_FRAMES 1024
#define BUFFER_FRAMES (PERIOD_FRAMES * 4)
#define UPDATE_DELAY_US 10000   /* 10 ms */

#define MAX_AMPLITUDE 32768.0f   /* 16-bit signed max */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* ALSA helpers                                                       */
/* ------------------------------------------------------------------ */

#ifdef ALSA_AVAILABLE

static int alsa_init(snd_pcm_t **pcm_handle)
{
    snd_pcm_t *pcm = NULL;
    int err;

    err = snd_pcm_open(&pcm, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_open failed: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_t *hw_params = NULL;
    snd_pcm_hw_params_alloca(&hw_params);
    if (!hw_params) {
        fprintf(stderr, "snd_pcm_hw_params_alloca failed\n");
        snd_pcm_close(pcm);
        return -1;
    }

    err = snd_pcm_hw_params_any(pcm, hw_params);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_any failed: %s\n", snd_strerror(err));
        snd_pcm_close(pcm);
        return -1;
    }

    err = snd_pcm_hw_params_set_access(pcm, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_access failed: %s\n", snd_strerror(err));
        snd_pcm_close(pcm);
        return -1;
    }

    err = snd_pcm_hw_params_set_format(pcm, hw_params, SND_PCM_FORMAT_S16_LE);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_format failed: %s\n", snd_strerror(err));
        snd_pcm_close(pcm);
        return -1;
    }

    err = snd_pcm_hw_params_set_channels(pcm, hw_params, 1);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_channels failed: %s\n", snd_strerror(err));
        snd_pcm_close(pcm);
        return -1;
    }

    err = snd_pcm_hw_params_set_rate_near(pcm, hw_params, &SAMPLE_RATE, 0);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_rate_near failed: %s\n", snd_strerror(err));
        snd_pcm_close(pcm);
        return -1;
    }

    err = snd_pcm_hw_params(pcm, hw_params);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params failed: %s\n", snd_strerror(err));
        snd_pcm_close(pcm);
        return -1;
    }

    err = snd_pcm_prepare(pcm);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_prepare failed: %s\n", snd_strerror(err));
        snd_pcm_close(pcm);
        return -1;
    }

    *pcm_handle = pcm;
    return 0;
}

static void alsa_close(snd_pcm_t **pcm_handle)
{
    if (*pcm_handle) {
        snd_pcm_t *pcm = *pcm_handle;
        snd_pcm_drain(pcm);
        snd_pcm_close(pcm);
        *pcm_handle = NULL;
    }
}

static int alsa_read_samples(snd_pcm_t *pcm, int16_t *buffer, int frames)
{
    int err = snd_pcm_readi(pcm, buffer, frames);
    if (err < 0) {
        if (err == -EPIPE) {
            fprintf(stderr, "ALSA EPIPE — recovering...\n");
            snd_pcm_prepare(pcm);
            snd_pcm_resume(pcm);
            return -1;
        }
        if (err == -ESTRPIPE) {
            fprintf(stderr, "ALSA ESTRPIPE — resuming...\n");
            snd_pcm_resume(pcm);
            return -1;
        }
        fprintf(stderr, "snd_pcm_readi failed: %s\n", snd_strerror(err));
        return -1;
    }
    return err;
}

#else

static int alsa_init(snd_pcm_t **pcm_handle)
{
    (void)pcm_handle;
    return 0;
}

static void alsa_close(snd_pcm_t **pcm_handle)
{
    (void)pcm_handle;
}

static int alsa_read_samples(snd_pcm_t *pcm, int16_t *buffer, int frames)
{
    (void)pcm; (void)buffer; (void)frames;
    return 0;
}

#endif

/* ------------------------------------------------------------------ */
/* Audio processing                                                    */
/* ------------------------------------------------------------------ */

static float calculate_rms(const int16_t *samples, int frames)
{
    double sum_sq = 0.0;
    for (int i = 0; i < frames; i++) {
        double s = (double)samples[i];
        sum_sq += s * s;
    }
    return (float)sqrt(sum_sq / (double)frames);
}

static float map_amplitude_to_color(float amplitude, float sensitivity)
{
    if (sensitivity <= 0.0f)
        sensitivity = 1.0f;

    float normalized = amplitude / MAX_AMPLITUDE;
    if (normalized < 0.0f) normalized = 0.0f;
    if (normalized > 1.0f) normalized = 1.0f;

    float scaled = normalized * sensitivity;
    if (scaled < 0.0f) scaled = 0.0f;
    if (scaled > 1.0f) scaled = 1.0f;

    return scaled;
}

static void set_led_color(int red, int green, int blue)
{
    if (red   < 0) red   = 0;
    if (red   > 255) red   = 255;
    if (green < 0) green = 0;
    if (green > 255) green = 255;
    if (blue  < 0) blue  = 0;
    if (blue  > 255) blue  = 255;

    gpioPWM(RED_PIN,   red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN,  blue);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(int argc, char *argv[])
{
    float sensitivity_scale = 1.0f;

    if (argc > 1) {
        char *endptr = NULL;
        float val = strtof(argv[1], &endptr);
        if (endptr == argv[1] || val <= 0.0f) {
            fprintf(stderr, "Invalid sensitivity scale: %s\n", argv[1]);
            return EXIT_FAILURE;
        }
        sensitivity_scale = val;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    gpioSetPWMrange(RED_PIN,   255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN,  255);

    gpioPWM(RED_PIN,   0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN,  0);

#ifdef ALSA_AVAILABLE
    snd_pcm_t *pcm = NULL;
    if (alsa_init(&pcm) != 0) {
        fprintf(stderr, "ALSA initialisation failed — falling back to simulated audio\n");
    } else {
        printf("ALSA initialised: default capture @ %d Hz, 16-bit, 1 channel\n", SAMPLE_RATE);
    }
#else
    printf("ALSA unavailable — using simulated audio (sine wave)\n");
#endif

    int16_t *audio_buffer = (int16_t *)malloc(BUFFER_FRAMES * sizeof(int16_t));
    if (!audio_buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        gpioTerminate();
#ifdef ALSA_AVAILABLE
        alsa_close(&pcm);
#endif
        return EXIT_FAILURE;
    }

    int frames_read = 0;
    int frames_written = 0;

    while (g_running) {
        int frames_needed = PERIOD_FRAMES - frames_written;
        if (frames_needed > 0) {
#ifdef ALSA_AVAILABLE
            if (pcm) {
                int frames_avail = BUFFER_FRAMES - frames_read;
                if (frames_avail < frames_needed) {
                    frames_needed = frames_avail;
                }
                int err = alsa_read_samples(pcm, audio_buffer + frames_read, frames_needed);
                if (err < 0) {
                    frames_read = 0;
                    frames_written = 0;
                    continue;
                }
                frames_read += err;
            } else {
                for (int i = 0; i < frames_needed; i++) {
                    float t = (float)i / (float)frames_needed * (float)PERIOD_FRAMES * 2.0f * M_PI;
                    audio_buffer[frames_read + i] = (int16_t)(32767.0f * 0.5f * sinf(t));
                }
                frames_read += frames_needed;
            }
#else
            for (int i = 0; i < frames_needed; i++) {
                float t = (float)i / (float)frames_needed * (float)PERIOD_FRAMES * 2.0f * M_PI;
                audio_buffer[frames_read + i] = (int16_t)(32767.0f * 0.5f * sinf(t));
            }
            frames_read += frames_needed;
#endif
        }

        if (frames_read >= PERIOD_FRAMES) {
            float amplitude = calculate_rms(audio_buffer, PERIOD_FRAMES);
            float color_value = map_amplitude_to_color(amplitude, sensitivity_scale);

            int red   = (int)(255.0f * (1.0f - color_value));
            int green = (int)(255.0f * color_value);
            int blue  = 0;

            set_led_color(red, green, blue);

            frames_written = PERIOD_FRAMES;
            frames_read = 0;
        }

        gpioDelay(UPDATE_DELAY_US);
    }

    printf("\nShutting down...\n");
    set_led_color(0, 0, 0);
    gpioTerminate();

#ifdef ALSA_AVAILABLE
    alsa_close(&pcm);
#endif

    free(audio_buffer);
    return EXIT_SUCCESS;
}

