#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define TCS34725_ADDR  0x29

/* TCS34725 register addresses */
#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x81
#define TCS34725_CDATA   0x14
#define TCS34725_RDATA   0x16
#define TCS34725_GDATA   0x18
#define TCS34725_BDATA   0x1A

#define ENABLE_PON  0x01
#define ENABLE_AEN  0x02

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_fp        = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int tcs34725_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, pigpio_error(rc));
    }
    return rc;
}

static int tcs34725_init(int handle)
{
    if (tcs34725_write_reg(handle, TCS34725_ENABLE, ENABLE_PON) < 0)
        return -1;
    gpioDelay(3000);                       /* power-on delay */

    if (tcs34725_write_reg(handle, TCS34725_ATIME, 0xD5) < 0)
        return -1;                          /* 154 ms integration time */

    if (tcs34725_write_reg(handle, TCS34725_ENABLE,
                           ENABLE_PON | ENABLE_AEN) < 0)
        return -1;

    gpioDelay(3000);                       /* wait for first integration */
    return 0;
}

static int tcs34725_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C block read failed (reg=0x%02X, len=%u): %s\n",
                reg, len, pigpio_error(rc));
        return -1;
    }
    return 0;
}

static int tcs34725_read_color(int handle, uint16_t *c, uint16_t *r,
                               uint16_t *g, uint16_t *b)
{
    uint8_t buf[8];

    if (tcs34725_read_block(handle, TCS34725_CDATA, buf, 8) < 0)
        return -1;

    *c = (uint16_t)((buf[1] << 8) | buf[0]);
    *r = (uint16_t)((buf[3] << 8) | buf[2]);
    *g = (uint16_t)((buf[5] << 8) | buf[4]);
    *b = (uint16_t)((buf[7] << 8) | buf[6]);
    return 0;
}

static void cleanup(void)
{
    if (g_fp) {
        fflush(g_fp);
        fclose(g_fp);
        g_fp = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, TCS34725_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, TCS34725_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (tcs34725_init(g_i2c_handle) < 0) {
        fprintf(stderr, "TCS34725 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_fp = fopen("color_data.csv", "w");
    if (!g_fp) {
        perror("Failed to open color_data.csv");
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(g_fp, "timestamp,clear,red,green,blue\n");
    fflush(g_fp);

    while (g_running) {
        uint16_t c, r, g, b;
        int ok = tcs34725_read_color(g_i2c_handle, &c, &r, &g, &b);

        if (ok < 0) {
            c = r = g = b = 0;
        }

        time_t now = time(NULL);
        fprintf(g_fp, "%ld,%u,%u,%u,%u\n", (long)now, c, r, g, b);
        fflush(g_fp);

        gpioDelay(500000);                 /* 500 ms */
    }

    cleanup();
    return EXIT_SUCCESS;
}

