#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define PWM_STEPS 100
#define DAYTIME_DURATION 6
#define SUNRISE_SUNSET_DURATION 1
#define NIGHT_DURATION 14.4

static const unsigned int relay_pins[NUM_RELAYS] = {17, 27, 22, 23};
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_RELAYS];
static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", relay_pins[i]);
            cleanup();
            return -1;
        }

        if (gpiod_line_request_output(lines[i], "sunset-simulator", 1) < 0) {
            perror("gpiod_line_request_output");
            cleanup();
            return -1;
        }
    }
    return 0;
}

static void set_relay_brightness(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_STEPS) duty_cycle = PWM_STEPS;

    for (int i = 0; i < NUM_RELAYS; i++) {
        int on_time_ms = (duty_cycle * 1000) / PWM_STEPS;
        int off_time_ms = 1000 - on_time_ms;

        if (on_time_ms > 0) {
            gpiod_line_set_value(lines[i], 0);
            usleep(on_time_ms * 1000);
        }
        if (off_time_ms > 0) {
            gpiod_line_set_value(lines[i], 1);
            usleep(off_time_ms * 1000);
        }
    }
}

static void sunrise(void) {
    for (int i = 0; i <= PWM_STEPS && keep_running; i++) {
        set_relay_brightness(i);
    }
}

static void daytime(void) {
    for (int i = 0; i < DAYTIME_DURATION * 3600 && keep_running; i++) {
        set_relay_brightness(PWM_STEPS);
        usleep(100000);
    }
}

static void sunset(void) {
    for (int i = PWM_STEPS; i >= 0 && keep_running; i--) {
        set_relay_brightness(i);
    }
}

static void nighttime(void) {
    for (int i = 0; i < (int)(NIGHT_DURATION * 3600) && keep_running; i++) {
        set_relay_brightness(0);
        usleep(100000);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    while (keep_running) {
        sunrise();
        if (!keep_running) break;
        daytime();
        if (!keep_running) break;
        sunset();
        if (!keep_running) break;
        nighttime();
    }

    cleanup();
    return EXIT_SUCCESS;
}

