#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pigpio.h>

#define MOTION_SENSOR_GPIO 17
#define VIDEO_DURATION_SEC 5
#define DEBOUNCE_DELAY_US 200000
#define POLL_INTERVAL_US 100000
#define VIDEO_DIR "/home/pi/videos/"
#define LOG_DIR "/home/pi/logs/"
#define LOG_FILE "motion_log.txt"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: %s exists but is not a directory\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        perror("mkdir");
        return -1;
    }
    return 0;
}

static int capture_video(int duration_sec) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];
    char command[256];
    char filename[128];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);

    snprintf(filename, sizeof(filename), "%s%s.h264", VIDEO_DIR, timestamp);

    snprintf(command, sizeof(command),
             "raspivid -o %s -t %ds --width 1280 --height 720 --fps 30 -q 80 -n -s",
             filename, duration_sec);

    printf("Capturing video: %s\n", filename);
    fflush(stdout);

    int status = system(command);
    if (status == -1) {
        perror("system");
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspivid exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    if (WIFSIGNALED(status)) {
        fprintf(stderr, "raspivid killed by signal %d\n", WTERMSIG(status));
        return -1;
    }

    return 0;
}

static int log_motion_event(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_DIR LOG_FILE, "a");
        if (log_file == NULL) {
            perror("fopen log");
            return -1;
        }
    }

    if (fprintf(log_file, "%s Motion detected on GPIO %d\n", timestamp, MOTION_SENSOR_GPIO) < 0) {
        perror("fprintf log");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (ensure_directory(VIDEO_DIR) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (ensure_directory(LOG_DIR) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTION_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", MOTION_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(MOTION_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", MOTION_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", MOTION_SENSOR_GPIO);
    fflush(stdout);

    uint32_t last_trigger_tick = 0;

    while (program_running) {
        int motion_detected = (gpioRead(MOTION_SENSOR_GPIO) == 0);

        if (motion_detected) {
            uint32_t now = gpioTick();
            uint32_t elapsed = now - last_trigger_tick;

            if (elapsed >= DEBOUNCE_DELAY_US) {
                printf("Motion detected!\n");
                fflush(stdout);

                if (capture_video(VIDEO_DURATION_SEC) != 0) {
                    fprintf(stderr, "Video capture failed\n");
                }

                if (log_motion_event() != 0) {
                    fprintf(stderr, "Logging failed\n");
                }

                last_trigger_tick = now;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    fflush(stdout);

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

