#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

#define ADXL345_ADDRESS 0x53
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32

#define FREEFALL_THRESHOLD 0.2f
#define FREEFALL_DURATION 0.5
#define ALARM_HOLD_TIME 5
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_adxl345(void) {
    if (i2cWriteByteData(i2c_handle, DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error: Failed to write DATA_FORMAT register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Failed to write POWER_CTL register\n");
        return -1;
    }
    return 0;
}

static int read_adxl345(float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Error: Failed to read accelerometer data\n");
        return -1;
    }
    int16_t x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);
    *x = (float)x_raw / 256.0f;
    *y = (float)y_raw / 256.0f;
    *z = (float)z_raw / 256.0f;
    return 0;
}

static int detect_freefall(float x, float y, float z) {
    return (fabsf(x) < FREEFALL_THRESHOLD &&
            fabsf(y) < FREEFALL_THRESHOLD &&
            fabsf(z) < FREEFALL_THRESHOLD);
}

static void log_freefall(float x, float y, float z) {
    FILE *fp = fopen("freefall.log", "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open freefall.log\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fclose(fp);
}

static void trigger_alarm(void) {
    gpioWrite(27, 1);
    gpioDelay(ALARM_HOLD_TIME * 1000000);
    gpioWrite(27, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }
    if (init_adxl345() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(27, PI_OUTPUT);
    gpioWrite(27, 0);
    signal(SIGINT, signal_handler);
    float x, y, z;
    int freefall_count = 0;
    while (running) {
        if (read_adxl345(&x, &y, &z) == 0) {
            if (detect_freefall(x, y, z)) {
                freefall_count++;
                if (freefall_count >= (int)(FREEFALL_DURATION * 10)) {
                    log_freefall(x, y, z);
                    trigger_alarm();
                    freefall_count = 0;
                }
            } else {
                freefall_count = 0;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    gpioWrite(27, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

