static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static volatile int echo_done = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void trigger_pulse(void) {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIG_PIN, 0);
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        pthread_mutex_lock(&pulse_mutex);
        start_tick = tick;
        echo_received = 0;
        echo_done = 0;
        pthread_mutex_unlock(&pulse_mutex);
    } else if (level == 0) {
        pthread_mutex_lock(&pulse_mutex);
        end_tick = tick;
        echo_received = 1;
        echo_done = 1;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

static double calculate_distance(uint32_t start, uint32_t end) {
    uint32_t diff = end - start;
    if (diff > MAX_ECHO_US) return -1.0;
    return (double)diff * SPEED_OF_SOUND_CM_PER_US / 2.0;
}

static void log_distance(double distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
    fprintf(log_file, "%lld,%.2f\n", timestamp_ns, distance);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioWrite(TRIG_PIN, 0);

    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    while (running) {
        pthread_mutex_lock(&pulse_mutex);
        start_tick = 0;
        end_tick = 0;
        echo_received = 0;
        echo_done = 0;
        pthread_mutex_unlock(&pulse_mutex);

        trigger_pulse();

        uint32_t wait_start = gpioTick();
        while (running) {
            pthread_mutex_lock(&pulse_mutex);
            int done = echo_done;
            int rec = echo_received;
            pthread_mutex_unlock(&pulse_mutex);
            if (done) {
                if (rec) {
                    uint32_t st, en;
                    pthread_mutex_lock(&pulse_mutex);
                    st = start_tick;
                    en = end_tick;
                    pthread_mutex_unlock(&pulse_mutex);
                    uint32_t diff = en - st;
                    if (diff > MAX_ECHO_US) {
                        fprintf(stderr, "Echo pulse too long: %u us\n", diff);
                    } else {
                        double dist = calculate_distance(st, en);
                        if (dist > 0 && dist <= MAX_DISTANCE_CM) {
                            log_distance(dist);
                        } else {
                            fprintf(stderr, "Invalid distance: %.2f cm\n", dist);
                        }
                    }
                } else {
                    fprintf(stderr, "Echo timeout\n");
                }
                break;
            }
            if ((gpioTick() - wait_start) > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Echo timeout\n");
                break;
            }
            gpioDelay(100);
        }

        if (running) {
            gpioDelay(TRIGGER_INTERVAL_MS * 1000);
        }
    }

    gpioSetAlertFunc(ECHO_PIN, NULL);
    gpioWrite(TRIG_PIN, 0);
    if (log_file) fclose(log_file);
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
    return 0;
}

