#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define LIS3DH_ADDR_DEFAULT 0x18
#define LIS3DH_REG_CTRL_REG1 0x20
#define LIS3DH_REG_CTRL_REG4 0x23
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_WHO_AM_I 0x0F
#define LIS3DH_WHO_AM_I_VAL 0x33

#define LOG_FILE "/var/log/high_acceleration.log"
#define DEFAULT_THRESHOLD 2.0f
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (rc=%d)\n", value, reg, rc);
        return -1;
    }
    return 0;
}

static int init_lis3dh(int handle, uint8_t addr) {
    int who = i2cReadByteData(handle, LIS3DH_REG_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error reading WHO_AM_I (rc=%d)\n", who);
        return -1;
    }
    if (who != LIS3DH_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, LIS3DH_WHO_AM_I_VAL);
        return -1;
    }
    if (write_register(handle, LIS3DH_REG_CTRL_REG1, 0x57) < 0) return -1;
    if (write_register(handle, LIS3DH_REG_CTRL_REG4, 0x88) < 0) return -1;
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    char buffer[6];
    int rc = i2cReadI2CBlockData(handle, LIS3DH_REG_OUT_X_L, buffer, 6);
    if (rc != 6) {
        fprintf(stderr, "Error reading acceleration block (rc=%d)\n", rc);
        *x = *y = *z = 0.0f;
        return -1;
    }
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    *x = (float)raw_x >> 4;
    *y = (float)raw_y >> 4;
    *z = (float)raw_z >> 4;
    return 0;
}

static void log_event(float x, float y, float z, float threshold) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Acceleration: X=%.4f, Y=%.4f, Z=%.4f, Threshold=%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z, threshold);
    fclose(fp);
}

static void shutdown_system(void) {
    printf("Shutting down system...\n");
    int rc = system("sudo shutdown -h now");
    if (rc != 0) {
        fprintf(stderr, "Error executing shutdown command (rc=%d)\n", rc);
    }
}

int main(int argc, char *argv[]) {
    uint8_t i2c_address = LIS3DH_ADDR_DEFAULT;
    float threshold = DEFAULT_THRESHOLD;
    int opt;

    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
