#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define LEFT_SENSOR_PIN  4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define ALERT_PIN        22

#define BUFFER_SIZE      5
#define POLL_INTERVAL_US 10000  /* 10 ms */
#define ALERT_DURATION_S 2

/* Sensor values: 0 = line detected, 1 = no line */
typedef struct {
    int left;
    int center;
    int right;
} sensor_data_t;

static sensor_data_t sensor_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static volatile sig_atomic_t program_running = 1;

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *left_line  = NULL;
static struct gpiod_line *center_line = NULL;
static struct gpiod_line *right_line = NULL;
static struct gpiod_line *alert_line = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void cleanup(void)
{
    if (alert_line) {
        gpiod_line_set_value(alert_line, 0);
        gpiod_line_release(alert_line);
        alert_line = NULL;
    }
    if (left_line)  { gpiod_line_release(left_line);  left_line  = NULL; }
    if (center_line) { gpiod_line_release(center_line); center_line = NULL; }
    if (right_line) { gpiod_line_release(right_line); right_line = NULL; }
    if (chip)       { gpiod_chip_close(chip);       chip       = NULL; }
}

static int init_gpio(void)
{
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_label("pinctrl-bcm2712");
        if (!chip) {
            chip = gpiod_chip_open_by_number(0);
            if (!chip) {
                fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
                return -1;
            }
        }
    }

    left_line  = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    alert_line = gpiod_chip_get_line(chip, ALERT_PIN);

    if (!left_line || !center_line || !right_line || !alert_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(left_line, "line_follower") < 0 ||
        gpiod_line_request_input(center_line, "line_follower") < 0 ||
        gpiod_line_request_input(right_line, "line_follower") < 0 ||
        gpiod_line_request_output(alert_line, "line_follower", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_sensor(struct gpiod_line *line, const char *name)
{
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Error reading %s sensor: %s\n", name, strerror(errno));
        return -1;
    }
    return val;
}

static void add_to_buffer(sensor_data_t data)
{
    sensor_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static int center_no_line_count(void)
{
    int count = 0;
    for (int i = 0; i < buffer_count; i++) {
        if (sensor_buffer[i].center == 1) count++;
    }
    return count;
}

static void trigger_alert(void)
{
    if (gpiod_line_set_value(alert_line, 1) < 0) {
        fprintf(stderr, "Failed to set alert HIGH: %s\n", strerror(errno));
        return;
    }
    sleep(ALERT_DURATION_S);
    if (gpiod_line_set_value(alert_line, 0) < 0) {
        fprintf(stderr, "Failed to set alert LOW: %s\n", strerror(errno));
    }
}

static void move_forward(void)
{
    printf("Moving forward\n");
}

static void turn_left(void)
{
    printf("Turning left\n");
}

static void turn_right(void)
{
    printf("Turning right\n");
}

static void stop_robot(void)
{
    printf("Stopping robot\n");
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    printf("Line follower started. Press Ctrl+C to exit.\n");

    while (program_running) {
        sensor_data_t data;
        data.left   = read_sensor(left_line,   "left");
        data.center = read_sensor(center_line, "center");
        data.right  = read_sensor(right_line,  "right");

        if (data.left < 0 || data.center < 0 || data.right < 0) {
            fprintf(stderr, "Sensor read error, exiting.\n");
            break;
        }

        add_to_buffer(data);

        if (center_no_line_count() >= 5) {
            trigger_alert();
        }

        if (data.center == 0) {
            move_forward();
        } else if (data.left == 0) {
            turn_left();
        } else if (data.right == 0) {
            turn_right();
        } else {
            stop_robot();
        }

        usleep(POLL_INTERVAL_US);
    }

    cleanup();
    printf("Line follower stopped.\n");
    return 0;
}

