#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SI7210_ADDR 0x30
#define RELAY_GPIO 17
#define FIELD_THRESHOLD_MT 5.0
#define SAMPLE_INTERVAL_US 100000
#define POLL_TIMEOUT_MS 50
#define LOG_FILE "magnetic_events.txt"

static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_si7210_field(int handle, float *field_mt) {
    int status;
    int msb, lsb;
    int raw;

    /* Start one-shot measurement */
    status = i2cWriteByteData(handle, 0xC1, 0x01);
    if (status < 0) {
        log_event("Error: Failed to write measurement start register.");
        return -1;
    }

    /* Poll for completion */
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        status = i2cReadByteData(handle, 0xC1);
        if (status < 0) {
            log_event("Error: Failed to read measurement status register.");
            return -1;
        }
        if (status == 0x00) break;
        gpioDelay(1000); /* 1 ms */
    }

    if (status != 0x00) {
        log_event("Error: Measurement timeout.");
        return -1;
    }

    /* Read 2 bytes from register 0xC0 */
    msb = i2cReadByteData(handle, 0xC0);
    if (msb < 0) {
        log_event("Error: Failed to read MSB from field register.");
        return -1;
    }
    lsb = i2cReadByteData(handle, 0xC0 + 1);
    if (lsb < 0) {
        log_event("Error: Failed to read LSB from field register.");
        return -1;
    }

    raw = (msb << 8) | lsb;
    *field_mt = (float)raw * 25.0 / 1000.0;
    return 0;
}

static void control_relay(int gpio, int state) {
    if (gpioWrite(gpio, state) < 0) {
        log_event("Error: Failed to write relay GPIO.");
    }
}

int main(void) {
    float field_mt;
    int relay_state = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        log_event("Error: Failed to set relay GPIO mode.");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    log_event("Program started.");

    while (program_running) {
        if (read_si7210_field(i2c_handle, &field_mt) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Field: %.2f mT", field_mt);
            log_event(msg);

            if (field_mt > FIELD_THRESHOLD_MT) {
                if (relay_state == 0) {
                    control_relay(RELAY_GPIO, 1);
                    relay_state = 1;
                    log_event("Relay activated.");
                }
            } else {
                if (relay_state == 1) {
                    control_relay(RELAY_GPIO, 0);
                    relay_state = 0;
                    log_event("Relay deactivated.");
                }
            }
        } else {
            control_relay(RELAY_GPIO, 0);
            relay_state = 0;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    log_event("Program shutting down.");
    control_relay(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

