#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define LOG_FILE "relay_log.txt"
#define BUFFER_SIZE 1024

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static FILE *log_file = NULL;

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
    if (client_fd >= 0) {
        shutdown(client_fd, SHUT_RDWR);
        close(client_fd);
        client_fd = -1;
    }
    if (server_fd >= 0) {
        shutdown(server_fd, SHUT_RDWR);
        close(server_fd);
        server_fd = -1;
    }
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);
    return 0;
}

static void cleanup_gpio(void) {
    if (gpioInitialise() >= 0) {
        gpioWrite(GPIO_PIN, 0);
        gpioTerminate();
    }
}

static int setup_socket(void) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        perror("socket creation failed");
        return -1;
    }

    int opt = 1;
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(fd);
        return -1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(fd);
        return -1;
    }

    if (listen(fd, 3) < 0) {
        perror("listen failed");
        close(fd);
        return -1;
    }

    return fd;
}

static int handle_client(int client_fd) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;

    while ((bytes_received = recv(client_fd, buffer, BUFFER_SIZE - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        buffer[strcspn(buffer, "\r\n")] = '\0';

        char command[32];
        strncpy(command, buffer, sizeof(command) - 1);
        command[sizeof(command) - 1] = '\0';

        if (strcmp(command, "ON") == 0 || strcmp(command, "on") == 0) {
            gpioWrite(GPIO_PIN, 1);
            log_event("Relay activated");
            printf("Relay activated\n");
        } else if (strcmp(command, "OFF") == 0 || strcmp(command, "off") == 0) {
            gpioWrite(GPIO_PIN, 0);
            log_event("Relay deactivated");
            printf("Relay deactivated\n");
        } else {
            fprintf(stderr, "Invalid command: %s\n", command);
            log_event("Invalid command received");
        }
    }

    if (bytes_received < 0) {
        perror("recv failed");
        log_event("Connection error");
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return 1;
    }

    if (setup_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    server_fd = setup_socket();
    if (server_fd < 0) {
        cleanup_gpio();
        fclose(log_file);
        return 1;
    }

    printf("Listening on port %d...\n", PORT);
    log_event("Server started");

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            perror("accept failed");
            log_event("Accept failed");
            continue;
        }

        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, client_ip, sizeof(client_ip));
        printf("Connection from %s:%d\n", client_ip, ntohs(client_addr.sin_port));
        log_event("Connection accepted");

        if (handle_client(client_fd) != 0) {
            log_event("Client handling error");
        }

        close(client_fd);
        client_fd = -1;
    }

    printf("Shutting down...\n");
    log_event("Server shutting down");

    if (client_fd >= 0) close(client_fd);
    if (server_fd >= 0) close(server_fd);
    cleanup_gpio();
    fclose(log_file);

    return 0;
}

