#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS              1
#define SENSOR1_ADDR         0x08
#define SENSOR2_ADDR         0x09
#define RELAY_GPIO           18
#define FLOW_THRESHOLD_ML_MIN 5.0f
#define POLL_DELAY_US        100000   /* 100 ms */
#define LOG_FILE             "flow_log.txt"
#define SLF3S_SCALE_FACTOR   1500.0f

static volatile sig_atomic_t g_running = 1;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR) ---- */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Timestamp helper ---- */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;
    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t pos = strlen(buf);
    snprintf(buf + pos, len - pos, ".%03ld", ts.tv_nsec / 1000000);
}

/* ---- Log flow data ---- */
static void log_flow_data(float flow1, float flow2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(fp, "%s, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
            ts, flow1, flow2);
    fflush(fp);
    fclose(fp);
}

/* ---- Read one SLF3S sample ----
 * Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.
 * *flow_out set to 0 on success, NAN on error.
 */
static int read_slf3s(int handle, float *flow_out)
{
    uint8_t cmd[2] = { 0x36, 0x08 };
    uint8_t buf[3];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "I2C write failed on handle %d\n", handle);
        return -1;
    }

    /* SLF3S conversion time: ~45 ms max; 100 ms is safe */
    gpioDelay(POLL_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 3) != 3) {
        fprintf(stderr, "I2C read failed on handle %d\n", handle);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on handle %d\n", handle);
        return -2;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw / SLF3S_SCALE_FACTOR;
    return 0;
}

/* ---- Cleanup helper ---- */
static void cleanup(int h1, int h2)
{
    gpioWrite(RELAY_GPIO, 0);
    if (h1 >= 0) i2cClose(h1);
    if (h2 >= 0) i2cClose(h2);
    gpioTerminate();
}

int main(void)
{
    int h1 = -1, h2 = -1;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    h1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (h1 < 0) {
        fprintf(stderr, "Failed to open I2C for sensor 1 (addr 0x%02X): %d\n",
                SENSOR1_ADDR, h1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    h2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (h2 < 0) {
        fprintf(stderr, "Failed to open I2C for sensor 2 (addr 0x%02X): %d\n",
                SENSOR2_ADDR, h2);
        i2cClose(h1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start continuous measurement on both sensors */
    if (i2cWriteDevice(h1, (char []){ 0x36, 0x08 }, 2) != 0) {
        fprintf(stderr, "Failed to start sensor 1\n");
        cleanup(h1, h2);
        return EXIT_FAILURE;
    }
    if (i2cWriteDevice(h2, (char []){ 0x36, 0x08 }, 2) != 0) {
        fprintf(stderr, "Failed to start sensor 2\n");
        cleanup(h1, h2);
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        cleanup(h1, h2);
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int r1 = read_slf3s(h1, &f1);
        int r2 = read_slf3s(h2, &f2);

        if (r1 == 0 && r2 == 0) {
            int below = (f1 < FLOW_THRESHOLD_ML_MIN) ||
                        (f2 < FLOW_THRESHOLD_ML_MIN);
            gpioWrite(RELAY_GPIO, below ? 1 : 0);
            log_flow_data(f1, f2);
        } else {
            if (r1 != 0)
                fprintf(stderr, "Sensor 1 read error (handle %d)\n", h1);
            if (r2 != 0)
                fprintf(stderr, "Sensor 2 read error (handle %d)\n", h2);
            /* On error, de-energize relay for safety */
            gpioWrite(RELAY_GPIO, 0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup(h1, h2);
    printf("Flow monitoring stopped.\n");
    return EXIT_SUCCESS;
}

