#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN   22
#define MOTOR_IN1_PIN   23
#define MOTOR_IN2_PIN   24

/* ---- Timing constants (microseconds) ---- */
#define POLL_INTERVAL_US  200000   /* 200 ms */
#define MOTOR_RUN_US      5000000  /* 5 s   */
#define DRY_REQUIRED_POLLS 3        /* 3 x 200 ms = 600 ms */

/* ---- Motor states ---- */
typedef enum {
    MOTOR_STOP,
    MOTOR_RUN
} motor_state_t;

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static motor_state_t g_motor_state = MOTOR_STOP;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static int  init_gpio(void);
static void cleanup_gpio(void);
static int  read_rain_sensor(void);
static void close_window(void);
static void stop_motor(void);
static void log_message(int priority, const char *msg);

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin mode");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) != 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pull-up");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set motor pin modes");
        gpioTerminate();
        return -1;
    }

    /* Ensure motor is stopped at startup */
    if (gpioWrite(MOTOR_ENA_PIN, 0) != 0 ||
        gpioWrite(MOTOR_IN1_PIN, 0) != 0 ||
        gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to initialise motor GPIO states");
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup_gpio(void)
{
    /* Best-effort: stop motor and release pigpio */
    stop_motor();
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
static int read_rain_sensor(void)
{
    int level = gpioRead(RAIN_SENSOR_PIN);
    if (level < 0) {
        syslog(LOG_ERR, "Failed to read rain sensor");
        return -1;
    }
    return level;
}

/* ------------------------------------------------------------------ */
static void close_window(void)
{
    log_message(LOG_INFO, "Closing window: motor start");

    if (gpioWrite(MOTOR_ENA_PIN, 1) != 0 ||
        gpioWrite(MOTOR_IN1_PIN, 1) != 0 ||
        gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to start motor");
        stop_motor();
        return;
    }

    g_motor_state = MOTOR_RUN;

    /* Hold motor for 5 s, checking for shutdown signal */
    for (int i = 0; i < 25 && g_running; i++) {
        gpioDelay(200000); /* 200 ms slices */
    }

    stop_motor();
    log_message(LOG_INFO, "Window closed");
}

/* ------------------------------------------------------------------ */
static void stop_motor(void)
{
    if (g_motor_state == MOTOR_RUN) {
        if (gpioWrite(MOTOR_ENA_PIN, 0) != 0 ||
            gpioWrite(MOTOR_IN1_PIN, 0) != 0 ||
            gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
            syslog(LOG_ERR, "Failed to stop motor");
        } else {
            log_message(LOG_INFO, "Motor stopped");
        }
        g_motor_state = MOTOR_STOP;
    }
}

/* ------------------------------------------------------------------ */
static void log_message(int priority, const char *msg)
{
    syslog(priority, "%s", msg);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "Rain-actuated window controller started");

    int dry_count = 0;

    while (g_running) {
        int rain = read_rain_sensor();
        if (rain < 0) {
            /* Sensor read error: back off and retry */
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (rain == 0) {
            /* Rain detected (DO LOW) */
            log_message(LOG_INFO, "Rain detected");

            if (g_motor_state == MOTOR_STOP) {
                close_window();
            }

            dry_count = 0;
        } else {
            /* Dry */
            dry_count++;
            if (dry_count >= DRY_REQUIRED_POLLS) {
                dry_count = 0;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    log_message(LOG_INFO, "Shutting down");
    cleanup_gpio();
    closelog();
    return EXIT_SUCCESS;
}

