#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define BUTTON_LOCK    21
#define BUTTON_UNLOCK  22

#define PULSE_LOCKED   2000   /* microseconds */
#define PULSE_UNLOCKED 1000
#define PULSE_STOP     0

#define DEBOUNCE_US    50000  /* 50 ms debounce */
#define POLL_US        10000  /* 10 ms poll interval */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int set_servo_pulse(int pin, int pulse_us)
{
    if (gpioServo(pin, pulse_us) != 0) {
        fprintf(stderr, "gpioServo(%d, %d) failed\n", pin, pulse_us);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Stop servo pulses before terminating */
    gpioServo(SERVO_PIN, PULSE_STOP);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure button pins as inputs with internal pull-ups */
    if (gpioSetMode(BUTTON_LOCK, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", BUTTON_LOCK);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUTTON_UNLOCK, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", BUTTON_UNLOCK);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_LOCK, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", BUTTON_LOCK);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_UNLOCK, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", BUTTON_UNLOCK);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure servo starts in a known state */
    if (set_servo_pulse(SERVO_PIN, PULSE_STOP) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Door lock control ready.\n");
    printf("  Lock button : GPIO %d (pulse %d us)\n", BUTTON_LOCK, PULSE_LOCKED);
    printf("  Unlock button: GPIO %d (pulse %d us)\n", BUTTON_UNLOCK, PULSE_UNLOCKED);
    printf("  Servo pin   : GPIO %d\n", SERVO_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int lock_state = gpioRead(BUTTON_LOCK);
        int unlock_state = gpioRead(BUTTON_UNLOCK);

        if (lock_state == 0 && unlock_state == 1) {
            /* Button pressed (active low) */
            if (set_servo_pulse(SERVO_PIN, PULSE_LOCKED) == 0) {
                printf("Door LOCKED\n");
            }
            /* Wait for release + debounce */
            while (g_running && gpioRead(BUTTON_LOCK) == 0) {
                gpioDelay(DEBOUNCE_US);
            }
            gpioDelay(DEBOUNCE_US);
        } else if (unlock_state == 0 && lock_state == 1) {
            if (set_servo_pulse(SERVO_PIN, PULSE_UNLOCKED) == 0) {
                printf("Door UNLOCKED\n");
            }
            while (g_running && gpioRead(BUTTON_UNLOCK) == 0) {
                gpioDelay(DEBOUNCE_US);
            }
            gpioDelay(DEBOUNCE_US);
        }

        gpioDelay(POLL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Door lock control stopped.\n");
    return EXIT_SUCCESS;
}

