#define PIR_PIN      4
#define LIGHT_PIN    17
#define LIGHT_ON_SEC 60
#define POLL_US      100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int log_event(const char *event, int duration_sec)
{
    FILE *fp = fopen("security_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s %s %s\n", ts, event,
                duration_sec >= 0 ? "duration=" : "duration=-1",
                duration_sec >= 0 ? (char *)"" : (char *)"N/A") < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(PIR_PIN, PI_INPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_set_mode(LIGHT_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure floodlight is off at startup */
    if (safe_write(LIGHT_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Security Light started. PIR=GPIO%d, Light=GPIO%d\n",
           PIR_PIN, LIGHT_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int pir = gpioRead(PIR_PIN);
        if (pir < 0) {
            fprintf(stderr, "gpioRead(%d) failed\n", PIR_PIN);
            break;
        }

        if (pir == 1) {
            printf("Motion detected!\n");

            if (safe_write(LIGHT_PIN, 1) != 0)
                break;

            time_t on_start = time(NULL);
            if (on_start == (time_t)-1) {
                fprintf(stderr, "time() failed: %s\n", strerror(errno));
                safe_write(LIGHT_PIN, 0);
                break;
            }

            for (int i = 0; i < LIGHT_ON_SEC && g_running; i++)
                gpioDelay(1000000); /* 1 s */

            if (!g_running) {
                safe_write(LIGHT_PIN, 0);
                break;
            }

            time_t on_end = time(NULL);
            if (on_end == (time_t)-1) {
                fprintf(stderr, "time() failed: %s\n", strerror(errno));
                safe_write(LIGHT_PIN, 0);
                break;
            }

            double duration = difftime(on_end, on_start);

            if (safe_write(LIGHT_PIN, 0) != 0)
                break;

            if (log_event("ACTIVATION", (int)duration) != 0)
                fprintf(stderr, "Warning: failed to log activation\n");

            printf("Light deactivated after %.1f s\n", duration);
        }

        gpioDelay(POLL_US);
    }

    /* Clean shutdown: floodlight off, release pigpio */
    safe_write(LIGHT_PIN, 0);
    gpioTerminate();
    printf("Shutdown complete.\n");
    return EXIT_SUCCESS;
}

