#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E
#define MPR121_AUTO_CONFIG0 0x7B
#define MPR121_AUTO_CONFIG1 0x7C
#define MPR121_AUTO_CONFIG2 0x7D
#define MPR121_SOFTRESET 0x80

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int relay_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X val=0x%02X rc=%d\n", reg, val, rc);
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    if (mpr121_write(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(1000);

    if (mpr121_write(MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write(MPR121_FDLR, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHDF, 0x05) < 0) return -1;
    if (mpr121_write(MPR121_NCLF, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_FDLF, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_NHDT, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_NCLT, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FDLT, 0x00) < 0) return -1;

    if (mpr121_write(MPR121_E0TTH, 0x0F) < 0) return -1;
    if (mpr121_write(MPR121_E0RTH, 0x0A) < 0) return -1;

    if (mpr121_write(MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write(MPR121_CONFIG2, 0x20) < 0) return -1;

    if (mpr121_write(MPR121_AUTO_CONFIG0, 0x0B) < 0) return -1;
    if (mpr121_write(MPR121_AUTO_CONFIG1, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_AUTO_CONFIG2, 0x00) < 0) return -1;

    if (mpr121_write(MPR121_ECR, 0x0C) < 0) return -1;

    return 0;
}

static int read_touch_status(uint16_t *status) {
    char buf[2];
    int rc = i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read failed: rc=%d\n", rc);
        return -1;
    }
    *status = (uint16_t)((uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    return 0;
}

static void toggle_relay(void) {
    relay_state = !relay_state;
    if (gpioWrite(RELAY_GPIO, relay_state) < 0) {
        fprintf(stderr, "Failed to write relay GPIO\n");
    } else {
        printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor may be absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t prev_touch = 0;
    printf("MPR121 relay control ready. Touch electrode 0 to toggle.\n");

    while (running) {
        uint16_t touch;
        if (read_touch_status(&touch) < 0) {
            gpioDelay(100000);
            continue;
        }

        uint16_t new_touch = touch & 0x0FFF;
        if ((new_touch & 0x0001) && !(prev_touch & 0x0001)) {
            toggle_relay();
            gpioDelay(200000);
        }
        prev_touch = new_touch;
        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

