static int server_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;

static void log_event(const char *fmt, ...) {
    va_list ap;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);

    if (log_fp) {
        fprintf(log_fp, "%s ", ts);
        va_start(ap, fmt);
        vfprintf(log_fp, fmt, ap);
        va_end(ap);
        fputc('\n', log_fp);
        fflush(log_fp);
    }
    syslog(LOG_INFO, "%s ", ts);
    syslog(LOG_INFO, fmt);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
    if (server_fd >= 0) {
        shutdown(server_fd, SHUT_RDWR);
        close(server_fd);
        server_fd = -1;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        log_event("Failed to open gpiochip4: %s\n", strerror(errno));
        return -1;
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        log_event("Failed to get servo line (BCM %d): %s\n", SERVO_PIN, strerror(errno));
        return -1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_event("Failed to get PIR line (BCM %d): %s\n", PIR_PIN, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(servo_line, "servo_pwm", 0) < 0) {
        log_event("Failed to request servo line as output: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(pir_line, "pir_sensor") < 0) {
        log_event("Failed to request PIR line as input: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    if (servo_line) {
        gpiod_line_set_value(servo_line, 0);
        gpiod_line_release(servo_line);
        servo_line = NULL;
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
        pir_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static void *pwm_thread(void *arg) {
    (void)arg;
    while (running) {
        int val = gpiod_line_get_value(servo_line);
        if (val < 0) {
            log_event("PWM: failed to read servo line: %s\n", strerror(errno));
