}

static void handle_client(int client_fd) {
    char buffer[1024];
    ssize_t bytes = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (bytes <= 0) {
        log_event("Client disconnected.\n");
        close(client_fd);
        return;
    }
    buffer[bytes] = '\0';

    char *cmd = strtok(buffer, " \r\n");
    if (!cmd) {
        log_event("Empty command received.\n");
        send(client_fd, "ERROR: empty command\n", 21, 0);
        close(client_fd);
        return;
    }

    if (strcmp(cmd, "SERVO") == 0) {
        char *arg = strtok(NULL, " \r\n");
