            log_event("PIR read failed: %s\n", strerror(errno));
            send(client_fd, "ERROR: PIR read failed\n", 22, 0);
            close(client_fd);
            return;
        }
        char response[16];
        snprintf(response, sizeof(response), "PIR: %d\n", pir_val);
        send(client_fd, response, strlen(response), 0);
        close(client_fd);
        return;
    }

    log_event("Unknown command: %s\n", cmd);
    send(client_fd, "ERROR: unknown command\n", 21, 0);
    close(client_fd);
}

int main(void) {
    openlog("security_server", LOG_PID | LOG_CONS, LOG_USER);

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        closelog();
        return 1;
    }

    if (init_gpio() != 0) {
        log_event("GPIO initialization failed. Exiting.\n");
        fclose(log_fp);
        closelog();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_event("Socket creation failed: %s\n", strerror(errno));
        cleanup_gpio();
        fclose(log_fp);
        closelog();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_event("setsockopt failed: %s\n", strerror(errno));
        close(server_fd);
        cleanup_gpio();
        fclose(log_fp);
        closelog();
        return 1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        log_event("Bind failed: %s\n", strerror(errno));
        close(server_fd);
        cleanup_gpio();
        fclose(log_fp);
        closelog();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        log_event("Listen failed: %s\n", strerror(errno));
        close(server_fd);
        cleanup_gpio();
        fclose(log_fp);
        closelog();
        return 1;
    }

    log_event("Server listening on port %d\n", PORT);

    pthread_t pwm_tid;
    if (pthread_create(&pwm_tid, NULL, pwm_thread, NULL) != 0) {
        log_event("Failed to create PWM thread: %s\n", strerror(errno));
        close(server_fd);
        cleanup_gpio();
        fclose(log_fp);
        closelog();
        return 1;
    }

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            log_event("Accept failed: %s\n", strerror(errno));
            continue;
        }
        char ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, ip, sizeof(ip));
        log_event("Connection from %s:%d\n", ip, ntohs(client_addr.sin_port));
        handle_client(client_fd);
    }

    pthread_join(pwm_tid, NULL);
    running = 0;
    close(server_fd);
    cleanup_gpio();
    fclose(log_fp);
    closelog();
    return 0;
}

