static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int handle, float *lux_out) {
    char buf[2];

    /* Trigger One-Time High-Resolution mode (0x20) */
    if (i2cWriteByte(handle, 0x20) < 0) {
        fprintf(stderr, "Error: i2cWriteByte failed (trigger 0x20): %s\n", strerror(errno));
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(BH1750_CONV_MS * 1000);

    /* Read 2 bytes of data */
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: i2cReadDevice failed: %s\n", strerror(errno));
        return -1;
    }

    unsigned int raw = ((unsigned int)(unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_relay(int gpio, int state) {
    if (gpioWrite(gpio, state) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed\n", gpio, state);
    }
}

static void log_data(FILE *fp, float lux) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Lux: %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, lux);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Ensure relay is off before terminating pigpio */
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    float lux;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, BH1750_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Grow light control started. Sampling every %d ms. Press Ctrl+C to exit.\n",
           SAMPLE_INTERVAL_MS);

    while (running) {
        if (read_bh1750(i2c_handle, &lux) == 0) {
            printf("Lux: %.2f\n", lux);
            log_data(log_file, lux);

            if (lux < LUX_THRESHOLD) {
                control_relay(RELAY_GPIO, 1);
                printf("Grow light ON\n");
            } else {
                control_relay(RELAY_GPIO, 0);
                printf("Grow light OFF\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read lux value. Retrying in %d ms.\n",
                    SAMPLE_INTERVAL_MS);
            log_data(log_file, -1.0f);
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_MS / 100 && running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

