#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <gpiod.h>

#define DOUT_PIN 23
#define SCK_PIN  24
#define SOLENOID_PIN 25

#define DEFAULT_THRESHOLD 1000.0f
#define DEFAULT_SCALE 100.0f
#define DEFAULT_DURATION_MS 200
#define DEFAULT_POLL_INTERVAL_MS 500
#define MAX_RETRIES 3
#define DOUT_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(struct gpiod_line *dout, struct gpiod_line *sck, int32_t *out) {
    int timeout = 0;
    while (gpiod_line_get_value(dout) == 1) {
        usleep(1000);
        timeout += 1000;
        if (timeout >= DOUT_TIMEOUT_MS * 1000) {
            syslog(LOG_ERR, "HX711 DOUT timeout (%d us)", timeout);
            return -1;
        }
    }

    uint32_t value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpiod_line_set_value(sck, 1) < 0) return -1;
        usleep(1);
        value <<= 1;
        if (gpiod_line_get_value(dout) == 1) {
            value |= 1;
        }
        if (gpiod_line_set_value(sck, 0) < 0) return -1;
        usleep(1);
    }

    if (gpiod_line_set_value(sck, 1) < 0) return -1;
    usleep(1);
    if (gpiod_line_set_value(sck, 0) < 0) return -1;
    usleep(1);

    if (value & 0x800000) {
        value |= 0xFF000000;
    }
    *out = (int32_t)value;
    return 0;
}

static float calculate_weight(int32_t raw, float scale, float offset) {
    return (float)raw / scale - offset;
}

static int trigger_solenoid(struct gpiod_line *sol, int duration_ms) {
    if (gpiod_line_set_value(sol, 1) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid HIGH");
        return -1;
    }
    usleep(duration_ms * 1000);
    if (gpiod_line_set_value(sol, 0) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid LOW");
        return -1;
    }
    return 0;
}

static int tare_sensor(struct gpiod_line *dout, struct gpiod_line *sck, int num_samples) {
    long sum = 0;
    int valid = 0;
    for (int i = 0; i < num_samples; i++) {
        int32_t raw;
        if (read_hx711(dout, sck, &raw) == 0) {
            sum += raw;
            valid++;
        } else {
            syslog(LOG_ERR, "Tare read failed at sample %d", i);
        }
        usleep(10000);
    }
    if (valid == 0) {
        syslog(LOG_ERR, "Tare failed: no valid readings");
        return -1;
    }
    return (int)(sum / valid);
}

int main(int argc, char *argv[]) {
    float threshold = DEFAULT_THRESHOLD;
    float scale = DEFAULT_SCALE;
    int duration_ms = DEFAULT_DURATION_MS;
    int poll_interval_ms = DEFAULT_POLL_INTERVAL_MS;

    int opt;
    while ((opt = getopt(argc, argv, "t:s:d:i:")) != -1) {
        switch (opt) {
            case 't': threshold = atof(optarg); break;
            case 's': scale = atof(optarg); break;
            case 'd': duration_ms = atoi(optarg); break;
            case 'i': poll_interval_ms = atoi(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [--threshold <grams>] [--scale <factor>] [--duration <ms>] [--interval <ms>]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0");
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *dout = gpiod_chip_get_line(chip, DOUT_PIN);
    struct gpiod_line *sck = gpiod_chip_get_line(chip, SCK_PIN);
    struct gpiod_line *sol = gpiod_chip_get_line(chip, SOLENOID_PIN);
    if (!dout || !sck || !sol) {
        syslog(LOG_ERR, "Failed to get GPIO lines");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(dout, "hx711_dout") < 0 ||
        gpiod_line_request_output(sck, "hx711_sck", 0) < 0 ||
        gpiod_line_request_output(sol, "solenoid", 0) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO lines");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    int tare_offset = tare_sensor(dout, 10);
    if (tare_offset < 0) {
        syslog(LOG_ERR, "Tare failed, exiting");
        gpiod_line_release(dout);
        gpiod_line_release(sck);
        gpiod_line_release(sol);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "Tare complete, offset=%d", tare_offset);

    while (running) {
        int sum = 0;
        int valid = 0;
        for (int i = 0; i < 5; i++) {
            int32_t raw;
            if (read_hx711(dout, sck, &raw) == 0) {
                sum += raw;
                valid++;
            } else {
                syslog(LOG_ERR, "Read failed at sample %d", i);
            }
            usleep(10000);
        }

        if (valid == 0) {
            syslog(LOG_ERR, "All reads failed, retrying in %d ms", poll_interval_ms);
            usleep(poll_interval_ms * 1000);
            continue;
        }

        float weight = calculate_weight(sum / valid, scale, tare_offset);
        syslog(LOG_INFO, "Weight: %.2f g", weight);

        if (weight > threshold) {
            syslog(LOG_INFO, "Threshold exceeded, triggering solenoid for %d ms", duration_ms);
            if (trigger_solenoid(sol, duration_ms) < 0) {
                syslog(LOG_ERR, "Solenoid trigger failed");
            }
        }

        usleep(poll_interval_ms * 1000);
    }

    syslog(LOG_INFO, "Shutting down, releasing resources");
    gpiod_line_set_value(sol, 0);
    gpiod_line_release(dout);
    gpiod_line_release(sck);
    gpiod_line_release(sol);
    gpiod_chip_close(chip);
    closelog();
    return EXIT_SUCCESS;
}

