/*
 * relay_controller.c — MQTT-driven relay controller for Raspberry Pi 4
 *
 * Subscribes to home/lights/control (QoS 0) and drives GPIO17 (BCM) HIGH/LOW
 * to energize/de-energize a relay module.  On transient MQTT failures the
 * client reconnects automatically; SIGINT/SIGTERM triggers graceful shutdown.
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c \
 *              -lmosquitto -lpigpio -lrt
 * Run:    sudo ./relay_controller
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT    1883
#define MQTT_CLIENT_ID      "relay_controller_1"
#define MQTT_TOPIC          "home/lights/control"
#define MQTT_KEEPALIVE      60
#define MQTT_RETRY_DELAY    5
#define GPIO_PIN            17
#define MAX_PAYLOAD         256

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging helpers                                                     */
/* ------------------------------------------------------------------ */
static void log_message(const char *msg)
{
    syslog(LOG_INFO, "%s", msg);
}

static void log_error(const char *msg)
{
    syslog(LOG_ERR, "%s", msg);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        log_error("Failed to set GPIO17 as output");
        gpioTerminate();
        return -1;
    }

    /* Relay OFF (de-energized) at startup */
    if (gpioWrite(GPIO_PIN, 0) != 0) {
        log_error("Failed to initialise GPIO17 LOW");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int gpio_set(int state)
{
    if (gpioWrite(GPIO_PIN, state) != 0) {
        log_error("Failed to write GPIO17");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* MQTT helpers                                                        */
/* ------------------------------------------------------------------ */
static int mqtt_connect(void)
{
    int rc;

    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mosq) {
        log_error("mosquitto_new() failed (out of memory)");
        return -1;
    }

    mosquitto_message_callback_set(g_mosq, on_message);
    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_error_callback_set(g_mosq, on_error);

    rc = mosquitto_connect(g_mosq, MQTT_BROKER_ADDRESS,
                           MQTT_BROKER_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        char buf[128];
        snprintf(buf, sizeof(buf),
                 "mosquitto_connect() failed: %s",
                 mosquitto_strerror(rc));
        log_error(buf);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        return -1;
    }

    rc = mosquitto_loop_start(g_mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        char buf[128];
        snprintf(buf, sizeof(buf),
                 "mosquitto_loop_start() failed: %s",
                 mosquitto_strerror(rc));
        log_error(buf);
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        return -1;
    }

    rc = mosquitto_subscribe(g_mosq, NULL, MQTT_TOPIC, 0);
    if (rc != MOSQ_ERR_SUCCESS) {
        char buf[128];
        snprintf(buf, sizeof(buf),
                 "mosquitto_subscribe() failed: %s",
                 mosquitto_strerror(rc));
        log_error(buf);
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        return -1;
    }

    return 0;
}

static void mqtt_disconnect(void)
{
    if (g_mosq) {
        mosquitto_loop_stop(g_mosq, false);
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                      */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *mosq, void *userdata,
                       int result)
{
    (void)userdata;

    if (result == MOSQ_ERR_SUCCESS) {
        log_message("MQTT connected");
    } else {
        char buf[128];
        snprintf(buf, sizeof(buf),
                 "MQTT connect error: %s",
                 mosquitto_strerror(result));
        log_error(buf);
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata,
                          int rc)
{
    (void)userdata;

    if (rc == MOSQ_ERR_SUCCESS) {
        log_message("MQTT disconnected (clean)");
    } else {
        char buf[128];
        snprintf(buf, sizeof(buf),
                 "MQTT unexpected disconnect: %s",
                 mosquitto_strerror(rc));
        log_error(buf);
    }
}

static void on_error(struct mosquitto *mosq, void *userdata,
                      int error)
{
    (void)mosq;
    (void)userdata;

    char buf[128];
    snprintf(buf, sizeof(buf),
             "MQTT error: %s",
             mosquitto_strerror(error));
    log_error(buf);
}

static void on_message(struct mosquitto *mosq, void *userdata,
                        const struct mosquitto_message *message)
{
    (void)mosq;
