#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>

#define SERVO_PINS {7, 8, 9, 10, 11}
#define SERVO_PULSES {1000, 1500, 2000, 500, 2500}
#define NUM_SERVOS 5
#define HOLD_TIME_US 3000000  /* 3 seconds */

int main(void)
{
    int i;
    int ret;

    /* Initialize pigpio library */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure each servo pin as output and set PWM frequency to 50 Hz */
    for (i = 0; i < NUM_SERVOS; i++) {
        ret = gpioSetMode(SERVO_PINS[i], PI_OUTPUT);
        if (ret != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d (code %d).\n",
                    SERVO_PINS[i], ret);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        ret = gpioSetPWMfrequency(SERVO_PINS[i], 50);
        if (ret < 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency failed for pin %d (code %d).\n",
                    SERVO_PINS[i], ret);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        ret = gpioSetPWMrange(SERVO_PINS[i], 20000);  /* 20 ms period = 20000 steps */
        if (ret < 0) {
            fprintf(stderr, "Error: gpioSetPWMrange failed for pin %d (code %d).\n",
                    SERVO_PINS[i], ret);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Apply pulse widths to each servo */
    for (i = 0; i < NUM_SERVOS; i++) {
        ret = gpioServo(SERVO_PINS[i], SERVO_PULSES[i]);
        if (ret != 0) {
            fprintf(stderr, "Error: gpioServo failed for pin %d (code %d).\n",
                    SERVO_PINS[i], ret);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Allow servos to reach their positions */
    gpioDelay(HOLD_TIME_US);

    /* Stop PWM on all servo pins */
    for (i = 0; i < NUM_SERVOS; i++) {
        gpioServo(SERVO_PINS[i], 0);
    }

    /* Clean up pigpio resources */
    gpioTerminate();

    return EXIT_SUCCESS;
}

