#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>
#include <stdbool.h>
#include <stdatomic.h>

/* Motor A */
#define MOTOR_A_PWM_PIN 17
#define MOTOR_A_DIR_PIN 18

/* Motor B */
#define MOTOR_B_PWM_PIN 22
#define MOTOR_B_DIR_PIN 23

/* Encoder A */
#define ENCODER_A_PHASE_A_PIN 4
#define ENCODER_A_PHASE_B_PIN 5

/* Encoder B */
#define ENCODER_B_PHASE_A_PIN 6
#define ENCODER_B_PHASE_B_PIN 12

#define TARGET_RPM 50.0
#define KP 0.5
#define KI 0.05
#define PWM_FREQUENCY 10000
#define PWM_RANGE 255
#define STALL_TIMEOUT_SEC 2
#define CONTROL_PERIOD_US 100000
#define ENCODER_TICKS_PER_REV 64
#define ENCODER_TICKS_PER_REV_PER_REV (ENCODER_TICKS_PER_REV * 60.0 / TARGET_RPM)

static volatile sig_atomic_t running = 1;
static atomic_int encoder_a_count = 0;
static atomic_int encoder_b_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    atomic_fetch_add(&encoder_a_count, 1);
}

static void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    atomic_fetch_add(&encoder_b_count, 1);
}

static double calculate_rpm(int32_t *last_count, int32_t *current_count) {
    int32_t diff = (int32_t)atomic_exchange(&*current_count, 0);
    static uint32_t last_tick = 0;
    uint32_t now = gpioTick();
    uint32_t elapsed_us = now - last_tick;
    last_tick = now;

    if (elapsed_us == 0) return 0.0;

    double ticks_per_sec = (double)diff * 1000000.0 / (double)elapsed_us;
    double rpm = ticks_per_sec / ENCODER_TICKS_PER_REV_PER_REV;
    *last_count = diff;
    return rpm;
}

static void set_motor_speed(int pwm_pin, int dir_pin, double rpm) {
    double error = TARGET_RPM - rpm;
    static double integral = 0.0;
    double dt = CONTROL_PERIOD_US / 1000000.0;

    integral += error * dt;

    if (integral > 255.0) integral = 255.0;
    if (integral < 0.0) integral = 0.0;

    double output = KP * error + KI * integral;

    if (output > 255.0) output = 255.0;
    if (output < 0.0) output = 0.0;

    int duty = (int)output;
    if (duty > 0) {
        gpioWrite(dir_pin, 1);
        gpioPWM(pwm_pin, duty);
    } else {
        gpioWrite(dir_pin, 0);
        gpioPWM(pwm_pin, 0);
    }
}

static void stop_motors(void) {
    gpioPWM(MOTOR_A_PWM_PIN, 0);
    gpioPWM(MOTOR_B_PWM_PIN, 0);
    gpioWrite(MOTOR_A_DIR_PIN, 0);
    gpioWrite(MOTOR_B_DIR_PIN, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_A_PWM_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_DIR_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_PWM_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_DIR_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set motor GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ENCODER_A_PHASE_A_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_A_PHASE_B_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_PHASE_A_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_PHASE_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set encoder GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(ENCODER_A_PHASE_A_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(ENCODER_A_PHASE_B_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(ENCODER_B_PHASE_A_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(ENCODER_B_PHASE_B_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set encoder pull-ups\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_A_PWM_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR_A_PWM_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(MOTOR_B_PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(ENCODER_A_PHASE_A_PIN, RISING_EDGE, 0, encoder_a_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_A_PHASE_B_PIN, RISING_EDGE, 0, encoder_a_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_B_PHASE_A_PIN, RISING_EDGE, 0, encoder_b_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_B_PHASE_B_PIN, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register encoder ISRs\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Closed-loop speed control started. Target: %.1f RPM\n", TARGET_RPM);

    int32_t last_a = 0, last_b = 0;
    uint32_t stall_start_a = 0, stall_start_b = 0;
    bool stalled_a = false, stalled_b = false;

    while (running) {
        double rpm_a = calculate_rpm(&last_a, &encoder_a_count);
        double rpm_b = calculate_rpm(&last_b, &encoder_b_count);

        set_motor_speed(MOTOR_A_PWM_PIN, MOTOR_A_DIR_PIN, rpm_a);
        set_motor_speed(MOTOR_B_PWM_PIN, MOTOR_B_DIR_PIN, rpm_b);

        uint32_t now = gpioTick();
        if (!stalled_a && last_a == 0 && (now - stall_start_a) > STALL_TIMEOUT_SEC * 1000000) {
            stalled_a = true;
            printf("Warning: Motor A stalled (no encoder ticks for %d s)\n", STALL_TIMEOUT_SEC);
        }
        if (!stalled_b && last_b == 0 && (now - stall_start_b) > STALL_TIMEOUT_SEC * 1000000) {
            stalled_b = true;
            printf("Warning: Motor B stalled (no encoder ticks for %d s)\n", STALL_TIMEOUT_SEC);
        }
        if (stalled_a && last_a != 0) { stalled_a = false; stall_start_a = now; }
        if (stalled_b && last_b != 0) { stalled_b = false; stall_start_b = now; }

        uint32_t pwm_a = gpioGetPWMdutycycle(MOTOR_A_PWM_PIN);
        uint32_t pwm_b = gpioGetPWMdutycycle(MOTOR_B_PWM_PIN);

        printf("Motor A: %.2f RPM, PWM %u\n", rpm_a, pwm_a);
        printf("Motor B: %.2f RPM, PWM %u\n", rpm_b, pwm_b);

        gpioDelay(CONTROL_PERIOD_US);
    }

    printf("\nShutting down...\n");
    stop_motors();
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

