#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define BH1750_ADDR 0x23
#define LUX_DUSK 50.0
#define LUX_DAWN 200.0
#define I2C_BUS 1
#define LOG_FILE "chicken_coop_log.txt"
#define POLL_INTERVAL_SEC 5
#define BH1750_MEAS_DELAY_MS 180

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", ts, msg);
    fflush(log_file);
}

static int read_lux(float *lux_out) {
    if (i2cWriteByte(i2c_handle, 0x21) < 0) {
        log_message("Error: BH1750 One-Time High-Resolution Mode 2 command failed.");
        return -1;
    }
    gpioDelay(BH1750_MEAS_DELAY_MS * 1000);

    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        log_message("Error: BH1750 failed to return lux data.");
        return -1;
    }

    unsigned int raw = ((unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) < 0) {
        log_message("Error: Failed to write to relay GPIO.");
        return;
    }
    char msg[64];
    snprintf(msg, sizeof(msg), "Relay set to %s", state ? "ON" : "OFF");
    log_message(msg);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    if (log_file) {
        log_message("System shutdown.");
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set relay GPIO mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at addr 0x%02X.\n", I2C_BUS, BH1750_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("System started.");

    int relay_state = 0;
    while (running) {
        float lux;
        if (read_lux(&lux) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Lux = %.2f", lux);
            log_message(msg);

            if (lux < LUX_DUSK && relay_state == 0) {
                control_relay(1);
                relay_state = 1;
            } else if (lux > LUX_DAWN && relay_state == 1) {
                control_relay(0);
                relay_state = 0;
            }
        } else {
            log_message("Error: Sensor read failed. Relay turned off for safety.");
            control_relay(0);
        }
        sleep(POLL_INTERVAL_SEC);
    }

    cleanup();
    return EXIT_SUCCESS;
}

