#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000   /* 50 ms debounce */
#define LOOP_DELAY_US 10000       /* 10 ms main-loop sleep */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void log_relay_state(int state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("[%s] Relay %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

int main(void)
{
    int relay_state = 0;
    int touch_state;
    int ret;

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    ret = gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %d\n", TOUCH_SENSOR_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(RELAY_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %d\n", RELAY_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure relay starts in OFF state */
    ret = gpioWrite(RELAY_PIN, 0);
    if (ret != 0) {
        fprintf(stderr, "Failed to initialise relay state: %d\n", ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_relay_state(relay_state);

    /* Main loop */
    while (running) {
        touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "Failed to read touch sensor: %d\n", touch_state);
            break;
        }

        if (touch_state == 1) {
            /* Debounce: wait and re-read */
            gpioDelay(DEBOUNCE_DELAY_US);
            touch_state = gpioRead(TOUCH_SENSOR_PIN);
            if (touch_state < 0) {
                fprintf(stderr, "Failed to read touch sensor during debounce: %d\n", touch_state);
                break;
            }

            if (touch_state == 1) {
                /* Toggle relay */
                relay_state = !relay_state;
                ret = gpioWrite(RELAY_PIN, relay_state);
                if (ret != 0) {
                    fprintf(stderr, "Failed to write relay state: %d\n", ret);
                    break;
                }
                log_relay_state(relay_state);

                /* Wait for touch release (edge detection) */
                while (running) {
                    touch_state = gpioRead(TOUCH_SENSOR_PIN);
                    if (touch_state < 0) {
                        fprintf(stderr, "Failed to read touch sensor during release wait: %d\n", touch_state);
                        break;
                    }
                    if (touch_state == 0) {
                        break;
                    }
                    gpioDelay(LOOP_DELAY_US);
                }
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Graceful shutdown */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

