#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define CONFIG_FILE "config.ini"
#define LOG_FILE "dispensing_log.json"
#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18
#define SERVO_MIN_PULSE 1000
#define SERVO_MAX_PULSE 2000
#define SERVO_OPEN_PULSE 1500
#define SERVO_CLOSE_PULSE 1000
#define HX711_TIMEOUT_ATTEMPTS 1000
#define HX711_TIMEOUT_DELAY_US 1
#define SERVO_OPEN_DELAY_US 1000000
#define HX711_STABILIZE_DELAY_US 1000000

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int servo_fd = -1;
static double calibration_factor = 1.0;
static char server_ip[32] = "127.0.0.1";
static int server_port = 12345;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file '%s': %s. Using defaults.\n", filename, strerror(errno));
        return -1;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=\n");
        char *value = strtok(NULL, "\n");
        if (!key || !value) continue;
        while (*key == ' ' || *key == '\t') key++;
        while (*value == ' ' || *value == '\t') value++;
        if (strcmp(key, "calibration_factor") == 0) {
            calibration_factor = atof(value);
        } else if (strcmp(key, "server_ip") == 0) {
            strncpy(server_ip, value, sizeof(server_ip) - 1);
            server_ip[sizeof(server_ip) - 1] = '\0';
        } else if (strcmp(key, "server_port") == 0) {
            server_port = atoi(value);
        }
    }
    fclose(fp);
    return 0;
}

static int hx711_read(int data_pin, int sck_pin) {
    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(sck_pin, PI_OUTPUT);
    gpioWrite(sck_pin, 0);
    gpioDelay(1);

    int data = 0;
    int timeout = 0;
    while (gpioRead(data_pin) == 1) {
        gpioDelay(HX711_TIMEOUT_DELAY_US);
        timeout++;
        if (timeout >= HX711_TIMEOUT_ATTEMPTS) {
            fprintf(stderr, "HX711 timeout: DATA line stuck HIGH (sensor absent or not ready).\n");
            return -1;
        }
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(sck_pin, 1);
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(data_pin)) data |= 1;
        gpioWrite(sck_pin, 0);
        gpioDelay(1);
    }

    gpioWrite(sck_pin, 1);
    gpioDelay(1);
    gpioWrite(sck_pin, 0);
    gpioDelay(1);

    if (data & 0x800000) data |= 0xFF000000;
    return data;
}

static double hx711_get_weight(int data_pin, int sck_pin) {
    int raw = hx711_read(data_pin, sck_pin);
    if (raw < 0) return -1.0;
    return (double)raw / calibration_factor;
}

static int set_servo_pulse(int pin, int pulse_us) {
    if (pulse_us < SERVO_MIN_PULSE || pulse_us > SERVO_MAX_PULSE) {
        fprintf(stderr, "Error: Servo pulse %d out of range [%d, %d].\n", pulse_us, SERVO_MIN_PULSE, SERVO_MAX_PULSE);
        return -1;
    }
    if (gpioServo(pin, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d.\n", pin);
        return -1;
    }
    return 0;
}

static int log_dispensing_event(double target_weight, double actual_weight, const char *error_msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "{\"timestamp\":\"%s\",\"target_weight\":%.2f,\"actual_weight\":%.2f,\"error_message\":\"%s\"}\n", timestamp, target_weight, actual_weight, error_msg ? error_msg : "none");
    fclose(fp);
    return 0;
}

static int dispense_ingredient(double target_weight) {
    if (set_servo_pulse(SERVO_PIN, SERVO_OPEN_PULSE) < 0) return -1;
    gpioDelay(SERVO_OPEN_DELAY_US);
    if (set_servo_pulse(SERVO_PIN, SERVO_CLOSE_PULSE) < 0) return -1;
    gpioDelay(HX711_STABILIZE_DELAY_US);
    double actual_weight = hx711_get_weight(HX711_DATA_PIN, HX711_SCK_PIN);
    if (actual_weight < 0) {
        fprintf(stderr, "Error: HX711 read failed during dispense.\n");
        log_dispensing_event(target_weight, -1.0, "HX711 read failed");
        return -1;
    }
    printf("Dispensed: target=%.2f g, actual=%.2f g\n", target_weight, actual_weight);
    log_dispensing_event(target_weight, actual_weight, NULL);
    return 0;
}

static int map_weight_to_pulse(double weight) {
    if (weight < 0) weight = 0;
    if (weight > 100) weight = 100;
    double pulse = SERVO_MIN_PULSE + (weight / 100.0) * (SERVO_MAX_PULSE - SERVO_MIN_PULSE);
    return (int)pulse;
}

static void handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        fprintf(stderr, "Error: recv failed: %s\n", strerror(errno));
        close(client_socket);
        return;
    }
    if (bytes_received == 0) {
        printf("Client disconnected.\n");
        close(client_socket);
        return;
    }
    buffer[bytes_received] = '\0';
    printf("Received: %s\n", buffer);
    double target_weight = atof(buffer);
    if (target_weight < 0) {
        fprintf(stderr, "Error: Invalid target weight: %s\n", buffer);
        const char *err = "Invalid target weight";
        send(client_socket, err, strlen(err), 0);
        close(client_socket);
        return;
    }
    if (dispense_ingredient(target_weight) < 0) {
        const char *err = "Dispensing failed";
        send(client_socket, err, strlen(err), 0);
    } else {
        char resp[64];
        snprintf(resp, sizeof(resp), "%.2f", target_weight);
        send(client_socket, resp, strlen(resp), 0);
    }
    close(client_socket);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (read_config(CONFIG_FILE) < 0) {
        calibration_factor = 1.0;
        strncpy(server_ip, "127.0.0.1", sizeof(server_ip) - 1);
        server_ip[sizeof(server_ip) - 1] = '\0';
        server_port = 12345;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        fprintf(stderr, "Error: Could not create socket: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        fprintf(stderr, "Warning: setsockopt failed: %s\n", strerror(errno));
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = inet_addr(server_ip);
    server_addr.sin_port = htons(server_port);

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error: Bind failed: %s\n", strerror(errno));
        close(server_fd);
        gpioTerminate();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        fprintf(stderr, "Error: Listen failed: %s\n", strerror(errno));
        close(server_fd);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on %s:%d\n", server_ip, server_port);

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_socket = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_socket < 0) {
            if (errno == EINTR && !running) break;
            fprintf(stderr, "Error: Accept failed: %s\n", strerror(errno));
            continue;
        }
        printf("Connection accepted from %s:%d\n", inet_ntoa(client_addr.sin_addr), ntohs(client_addr.sin_port));
        handle_client(client_socket);
    }

    printf("\nShutting down...\n");
    if (servo_fd >= 0) {
        gpioServo(SERVO_PIN, 0);
    }
    if (server_fd >= 0) close(server_fd);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

