#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <termios.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define DEFAULT_ANGLE 90
#define STEP_SIZE 10
#define PWM_FREQUENCY 50
#define PWM_RANGE 2000000  /* 20 ms period in microseconds */

static volatile sig_atomic_t running = 1;
static struct termios orig_termios;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static int set_terminal_raw(void) {
    struct termios raw;
    if (tcgetattr(STDIN_FILENO, &orig_termios) != 0) {
        perror("tcgetattr");
        return -1;
    }
    raw = orig_termios;
    raw.c_lflag &= ~(ICANON | ECHO);
    raw.c_cc[VMIN] = 0;
    raw.c_cc[VTIME] = 0;
    if (tcsetattr(STDIN_FILENO, TCSANOW, &raw) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static void restore_terminal(void) {
    tcsetattr(STDIN_FILENO, TCSANOW, &orig_termios);
}

static int angle_to_pulse_width(int angle) {
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    return MIN_PULSE_WIDTH + (angle * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH)) / MAX_ANGLE;
}

static int pulse_width_to_angle(int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH) pulse_width = MIN_PULSE_WIDTH;
    if (pulse_width > MAX_PULSE_WIDTH) pulse_width = MAX_PULSE_WIDTH;
    return (pulse_width - MIN_PULSE_WIDTH) * MAX_ANGLE / (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH);
}

int main(void) {
    int angle = DEFAULT_ANGLE;
    int pulse_width;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(SERVO_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_terminal_raw() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Servo control started. GPIO%d, 50 Hz PWM. Press '+' to increase, '-' to decrease, 'q' to quit.\n", SERVO_PIN);
    printf("Current angle: %d degrees\n", angle);
    fflush(stdout);

    while (running) {
        int c = getchar();
        if (c == '+') {
            angle += STEP_SIZE;
            if (angle > MAX_ANGLE) angle = MAX_ANGLE;
            pulse_width = angle_to_pulse_width(angle);
            if (gpioServo(SERVO_PIN, pulse_width) != 0) {
                fprintf(stderr, "gpioServo failed for pulse %d\n", pulse_width);
            }
            printf("Angle: %d degrees (pulse %d us)\n", angle, pulse_width);
            fflush(stdout);
        } else if (c == '-') {
            angle -= STEP_SIZE;
            if (angle < MIN_ANGLE) angle = MIN_ANGLE;
            pulse_width = angle_to_pulse_width(angle);
            if (gpioServo(SERVO_PIN, pulse_width) != 0) {
                fprintf(stderr, "gpioServo failed for pulse %d\n", pulse_width);
            }
            printf("Angle: %d degrees (pulse %d us)\n", angle, pulse_width);
            fflush(stdout);
        } else if (c == 'q') {
            break;
        } else if (c != EOF) {
            printf("Invalid input. Use '+', '-', or 'q'.\n");
            fflush(stdout);
        }
        usleep(50000); /* 50 ms debounce */
    }

    /* Stop PWM pulses and release GPIO */
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    restore_terminal();
    printf("\nServo stopped. Exiting.\n");
    return EXIT_SUCCESS;
}

