#define LOG_FILE "motor_rpm.log"
#define SAMPLE_INTERVAL_SEC 5
#define DEBOUNCE_NS 2000000L  /* 2 ms */

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_error(const char *message)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s (errno: %s)\n", ts, message, strerror(errno));
}

static void log_rpm(double rpm)
{
    time_t now = time(NULL);
    struct tm tm_buf;
