#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN        17
#define POLL_DELAY_US    50000   /* 50 ms */
#define FAILSAFE_TIMEOUT 10      /* seconds */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(pin=%u, level=%u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(pin=%u, mode=%u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

int main(void)
{
    int relay_state = 0;
    uint32_t touch_start_tick = 0;
    int rc = EXIT_SUCCESS;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (safe_set_mode(TOUCH_SENSOR_PIN, PI_INPUT) != 0 ||
        safe_set_mode(RELAY_PIN, PI_OUTPUT) != 0) {
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    /* Ensure relay starts OFF */
    if (safe_write(RELAY_PIN, 0) != 0) {
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    printf("Touch-controlled relay started. Touch GPIO4 to toggle GPIO17.\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state == PI_BAD_GPIO) {
            fprintf(stderr, "Error: gpioRead(TOUCH_SENSOR_PIN) returned PI_BAD_GPIO\n");
            rc = EXIT_FAILURE;
            break;
        }

        if (touch_state == 1) {
            /* Rising edge: toggle relay */
            relay_state = !relay_state;
            if (safe_write(RELAY_PIN, relay_state) != 0) {
                rc = EXIT_FAILURE;
                break;
            }
            printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");

            /* Failsafe: if touch is held for > 10 s, force OFF */
            if (touch_start_tick == 0) {
                touch_start_tick = gpioTick();
            } else {
                uint32_t elapsed = gpioTick() - touch_start_tick;
                if (elapsed > (uint32_t)(FAILSAFE_TIMEOUT * 1000000)) {
                    fprintf(stderr, "Failsafe: touch held > %d s, forcing relay OFF\n",
                            FAILSAFE_TIMEOUT);
                    relay_state = 0;
                    if (safe_write(RELAY_PIN, 0) != 0) {
                        rc = EXIT_FAILURE;
                        break;
                    }
                    touch_start_tick = 0; /* reset so we don't keep forcing */
                }
            }
        } else {
            /* Sensor released: reset failsafe timer */
            touch_start_tick = 0;
        }

        gpioDelay(POLL_DELAY_US);
    }

cleanup:
    /* Clean shutdown: relay OFF, release pigpio resources */
    if (safe_write(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn off relay during cleanup\n");
    }
    gpioTerminate();
    printf("Program terminated.\n");
    return rc;
}

