#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_ENABLE_PIN 23
#define VALVE_PWM_PIN    18
#define FLOW_SENSOR_PIN  24

#define PULSES_PER_LITER 450.0
#define SAMPLE_PERIOD_US 100000  /* 100 ms */
#define PWM_RANGE        255
#define PWM_FREQ         1000     /* Hz */

#define LOG_FILE "flow_log.csv"

static volatile sig_atomic_t g_running = 1;
static volatile int g_pulse_count = 0;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void pulse_counter(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    g_pulse_count++;
}

static double calculate_flow_rate(int pulses, double sample_us) {
    double liters = (double)pulses / PULSES_PER_LITER;
    double minutes = (double)sample_us / (1000000.0 * 60.0);
    return liters / minutes;
}

static int set_valve_position(double flow_rate, double target_flow_rate,
                              double kp, int *current_pwm) {
    double error = target_flow_rate - flow_rate;
    double pwm_adj = kp * error;
    int new_pwm = *current_pwm + (int)pwm_adj;
    if (new_pwm < 0) new_pwm = 0;
    if (new_pwm > PWM_RANGE) new_pwm = PWM_RANGE;
    *current_pwm = new_pwm;
    if (gpioPWM(VALVE_PWM_PIN, new_pwm) < 0) {
        fprintf(stderr, "Error: gpioPWM failed for pin %d\n", VALVE_PWM_PIN);
        return -1;
    }
    return 0;
}

static void log_data(double flow_rate, int valve_position) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    long timestamp_ms = (long)(ts.tv_sec * 1000L + ts.tv_nsec / 1000000L);
    if (fprintf(g_log_fp, "%ld,%.2f,%d\n", timestamp_ms, flow_rate, valve_position) < 0) {
        perror("fprintf");
    }
    fflush(g_log_fp);
}

static void cleanup(void) {
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioPWM(VALVE_PWM_PIN, 0);
    gpioWrite(VALVE_ENABLE_PIN, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    double target_flow_rate = 0.0;
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                target_flow_rate = atof(optarg);
                if (target_flow_rate <= 0.0) {
                    fprintf(stderr, "Error: target flow rate must be positive\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s -t <target_flow_rate_L_min>\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for enable pin %d\n", VALVE_ENABLE_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for PWM pin %d\n", VALVE_PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for flow sensor pin %d\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for flow sensor pin %d\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for pin %d\n", VALVE_PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for pin %d\n", VALVE_PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(VALVE_ENABLE_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite failed to enable valve on pin %d\n", VALVE_ENABLE_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(VALVE_PWM_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioPWM failed to initialize PWM on pin %d\n", VALVE_PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, pulse_counter, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed for flow sensor pin %d\n", FLOW_SENSOR_PIN);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        cleanup();
        return EXIT_FAILURE;
    }

    int current_pwm = 0;
    printf("Flow control started. Target: %.2f L/min\n", target_flow_rate);

    while (g_running) {
        int pulses = g_pulse_count;
        g_pulse_count = 0;

        double flow_rate = calculate_flow_rate(pulses, SAMPLE_PERIOD_US);

        if (set_valve_position(flow_rate, target_flow_rate, 1.0, &current_pwm) < 0) {
            break;
        }

        log_data(flow_rate, current_pwm);

        printf("Flow: %.2f L/min  PWM: %d\n", flow_rate, current_pwm);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

