#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK_1_GPIO 17
#define LOCK_2_GPIO 27
#define BUTTON_GPIO 22
#define SPI_CHANNEL 0
#define SPI_SPEED 100000
#define RFID_BYTES 10
#define VALID_TAG {0x01,0x02,0x03,0x04,0x05,0x06,0x07,0x08,0x09,0x0A}
#define DEBOUNCE_US 50000
#define DISENGAGE_US 5000000
#define POLL_US 100000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s %s\n", ts, msg);
    fflush(log_file);
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(LOCK_1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK_2_GPIO, PI_OUTPUT);
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);
    if (gpioWrite(LOCK_1_GPIO, 1) < 0 || gpioWrite(LOCK_2_GPIO, 1) < 0) {
        fprintf(stderr, "Failed to set lock initial state\n");
        return -1;
    }
    return 0;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

static int read_rfid(unsigned char *buf, int len) {
    char tx[RFID_BYTES] = {0};
    char rx[RFID_BYTES] = {0};
    int ret = spiXfer(spi_handle, tx, rx, len);
    if (ret != len) {
        fprintf(stderr, "SPI transfer failed: %d\n", ret);
        return -1;
    }
    for (int i = 0; i < len; i++) {
        if (rx[i] != 0x00) {
            buf[i] = rx[i];
        }
    }
    return 0;
}

static int check_tag(const unsigned char *tag) {
    for (int i = 0; i < RFID_BYTES; i++) {
        if (tag[i] != VALID_TAG[i]) return 0;
    }
    return 1;
}

static int button_pressed(void) {
    if (gpioRead(BUTTON_GPIO) == 0) {
        gpioDelay(DEBOUNCE_US);
        if (gpioRead(BUTTON_GPIO) == 0) return 1;
    }
    return 0;
}

static int control_lock(int gpio, int state) {
    if (gpioWrite(gpio, state) < 0) {
        fprintf(stderr, "gpioWrite failed on GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LOCK_1_GPIO, 1);
    gpioWrite(LOCK_2_GPIO, 1);
    gpioTerminate();
    if (log_file) {
        log_event("System shutdown");
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    log_file = fopen("/var/log/door_access.log", "a");
    if (!log_file) {
        perror("fopen log");
        return 1;
    }

    if (init_gpio() < 0) {
        log_event("GPIO init failed");
        cleanup();
        return 1;
    }

    if (init_spi() < 0) {
        log_event("SPI init failed");
        cleanup();
        return 1;
    }

    log_event("System started");

    while (running) {
        unsigned char tag[RFID_BYTES];
        int tag_ok = 0;

        if (read_rfid(tag, RFID_BYTES) < 0) {
            log_event("RFID read failure");
            gpioDelay(POLL_US);
            continue;
        }

        if (check_tag(tag)) {
            tag_ok = 1;
            log_event("Valid tag detected");
        } else {
            log_event("Invalid tag detected");
        }

        if (button_pressed()) {
            if (tag_ok) {
                log_event("Two-factor authentication successful");
                if (control_lock(LOCK_1_GPIO, 0) < 0 || control_lock(LOCK_2_GPIO, 0) < 0) {
                    log_event("Lock disengage failed");
                } else {
                    gpioDelay(DISENGAGE_US);
                    if (control_lock(LOCK_1_GPIO, 1) < 0 || control_lock(LOCK_2_GPIO, 1) < 0) {
                        log_event("Lock re-engage failed");
                    }
                }
            } else {
                log_event("Button press without valid tag");
            }
        }

        gpioDelay(POLL_US);
    }

    cleanup();
    return 0;
}

