#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

#define ENC1_A 5
#define ENC1_B 6
#define ENC2_A 26
#define ENC2_B 27

#define PULSES_PER_REV 600.0
#define PWM_FREQ_HZ 100
#define PWM_PERIOD_US (1000000 / PWM_FREQ_HZ)
#define SAMPLE_TIME_MS 100

#define KP 1.0
#define KI 0.1
#define KD 0.01

#define TARGET_RPM_M1 60.0
#define TARGET_RPM_M2 60.0

static volatile int running = 1;
static FILE *log_file = NULL;

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *motor_lines[4];
static struct gpiod_line *encoder_lines[4];
static int motor_line_requested[4] = {0};
static int encoder_line_requested[4] = {0};

static long long encoder_counts[2] = {0, 0};
static pthread_mutex_t encoder_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (chip) {
        for (int i = 0; i < 4; i++) {
            if (motor_line_requested[i]) {
                gpiod_line_set_value(motor_lines[i], 0);
                gpiod_line_release(motor_lines[i]);
                motor_line_requested[i] = 0;
            }
        }
        for (int i = 0; i < 4; i++) {
            if (encoder_line_requested[i]) {
                gpiod_line_release(encoder_lines[i]);
                encoder_line_requested[i] = 0;
            }
        }
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static void set_motor_speed(int motor, double speed) {
    if (speed < 0.0) speed = 0.0;
    if (speed > 1.0) speed = 1.0;
    int duty_us = (int)(speed * PWM_PERIOD_US);
    if (duty_us < 1) duty_us = 1;
    if (duty_us > PWM_PERIOD_US - 1) duty_us = PWM_PERIOD_US - 1;

    if (motor == 1) {
        gpiod_line_set_value(motor_lines[0], duty_us > 0 ? 1 : 0);
        gpiod_line_set_value(motor_lines[1], duty_us > 0 ? 0 : 1);
        gpiod_line_set_value(motor_lines[2], duty_us > 0 ? 0 : 1);
    } else if (motor == 2) {
        gpiod_line_set_value(motor_lines[3], duty_us > 0 ? 1 : 0);
        gpiod_line_set_value(motor_lines[4], duty_us > 0 ? 0 : 1);
        gpiod_line_set_value(motor_lines[5], duty_us > 0 ? 0 : 1);
    }
}

static double calculate_pid(double setpoint, double actual, double *integral, double *prev_error, double dt) {
    double error = setpoint - actual;
    *integral += error * dt;
    double derivative = (error - *prev_error) / dt;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *prev_error = error;
    return output;
}

static void *encoder_thread(void *arg) {
    int enc_num = *(int *)arg;
    int a_pin = (enc_num == 1) ? ENC1_A : ENC2_A;
    int b_pin = (enc_num == 1) ? ENC1_B : ENC2_B;
    struct gpiod_line *a_line = (enc_num == 1) ? encoder_lines[0] : encoder_lines[2];
    struct gpiod_line *b_line = (enc_num == 1) ? encoder_lines[1] : encoder_lines[3];

    struct gpiod_line_event event;
    while (running) {
        int ret = gpiod_line_event_wait(a_line, NULL);
        if (ret < 0) {
            if (errno == EINTR) continue;
            break;
        }
        if (ret == 0) continue;

        if (gpiod_line_event_read(a_line, &event) < 0) continue;

        int b_val = gpiod_line_get_value(b_line);
        if (b_val < 0) continue;

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            if (b_val == 1) {
                pthread_mutex_lock(&encoder_mutex);
                encoder_counts[enc_num - 1]++;
                pthread_mutex_unlock(&encoder_mutex);
            } else {
                pthread_mutex_lock(&encoder_mutex);
                encoder_counts[enc_num - 1]--;
                pthread_mutex_unlock(&encoder_mutex);
            }
        } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            if (b_val == 0) {
                pthread_mutex_lock(&encoder_mutex);
                encoder_counts[enc_num - 1]++;
                pthread_mutex_unlock(&encoder_mutex);
            } else {
                pthread_mutex_lock(&encoder_mutex);
                encoder_counts[enc_num - 1]--;
                pthread_mutex_unlock(&encoder_mutex);
            }
        }
    }
    return NULL;
}

static double measure_rpm(int enc_num) {
    struct timespec ts_start, ts_end;
    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    long long count_start, count_end;
    pthread_mutex_lock(&encoder_mutex);
    count_start = encoder_counts[enc_num - 1];
    pthread_mutex_unlock(&encoder_mutex);

    struct timespec sleep_ts = {0, SAMPLE_TIME_MS * 1000000L};
    while (running) {
        clock_nanosleep(CLOCK_MONOTONIC, 0, &sleep_ts, NULL);
        pthread_mutex_lock(&encoder_mutex);
        count_end = encoder_counts[enc_num - 1];
        pthread_mutex_unlock(&encoder_mutex);
        long long delta = count_end - count_start;
        double elapsed_s = (double)(ts_end.tv_sec - ts_start.tv_sec) +
                           (double)(ts_end.tv_nsec - ts_start.tv_nsec) / 1e9;
        if (elapsed_s >= 0.01) break;
    }

    struct timespec ts_end;
    clock_gettime(CLOCK_MONOTONIC, &ts_end);
    double elapsed_s = (double)(ts_end.tv_sec - ts_start.tv_sec) +
                       (double)(ts_end.tv_nsec - ts_start.tv_nsec) / 1e9;

    pthread_mutex_lock(&encoder_mutex);
    count_end = encoder_counts[enc_num - 1];
    pthread_mutex_unlock(&encoder_mutex);
    long long delta = count_end - count_start;

    if (delta == 0) return 0.0;
    double rpm = (double)delta / PULSES_PER_REV / elapsed_s * 60.0;
    return rpm;
}

static void log_data(double rpm1, double rpm2, double pid_p, double pid_i, double pid_d, double pid_out) {
    if (!log_file) return;
