#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int mpr121_write(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d\n", reg, value, rc);
    }
    return rc;
}

int mpr121_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C block read failed: reg=0x%02X, rc=%d\n", reg, rc);
    }
    return rc;
}

int mpr121_init(int handle) {
    if (mpr121_write(handle, MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000);

    if (mpr121_write(handle, MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write(handle, MPR121_FDLR, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NHDF, 0x05) < 0) return -1;
    if (mpr121_write(handle, MPR121_NCLF, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_FDLF, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_NHDT, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_NCLT, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_FDLT, 0x00) < 0) return -1;

    for (int i = 0; i < 12; i++) {
        if (mpr121_write(handle, MPR121_E0TTH + 2 * i, 0x0C) < 0) return -1;
        if (mpr121_write(handle, MPR121_E0RTH + 2 * i, 0x0A) < 0) return -1;
    }

    if (mpr121_write(handle, MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write(handle, MPR121_CONFIG2, 0x20) < 0) return -1;

    if (mpr121_write(handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) return -1;
    if (mpr121_write(handle, MPR121_ECR, 0x8C) < 0) return -1;

    return 0;
}

int read_touch_status(int handle, uint16_t *status) {
    uint8_t buf[2];
    if (mpr121_read_block(handle, MPR121_TOUCHSTATUS_L, buf, 2) < 0) return -1;
    *status = (buf[1] << 8) | buf[0];
    return 0;
}

void log_relay_state(int state) {
    FILE *fp = fopen("relay_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s Relay state: %s\n", s, state ? "ON" : "OFF");
    fclose(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    int relay_state = 0;
    int prev_touched = 0;

    while (running) {
        uint16_t touch_status;
        if (read_touch_status(i2c_handle, &touch_status) < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        int touched = (touch_status & 0x0FFF) ? 1 : 0;

        if (touched && !prev_touched) {
            gpioWrite(RELAY_GPIO, 1);
            relay_state = 1;
            log_relay_state(relay_state);
        } else if (!touched && prev_touched) {
            gpioWrite(RELAY_GPIO, 0);
            relay_state = 0;
            log_relay_state(relay_state);
        }

        prev_touched = touched;
        gpioDelay(50000);
    }

    gpioWrite(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

