#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define VALVE1_GPIO 17
#define VALVE2_GPIO 18
#define VALVE1_DURATION_MS 500
#define VALVE2_DURATION_MS 1000
#define VALVE1_PAUSE_SEC 5
#define VALVE2_PAUSE_SEC 10
#define LOG_FILE "valve_log.txt"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *valve1_line = NULL;
static struct gpiod_line *valve2_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (valve1_line) {
        gpiod_line_set_value(valve1_line, 0);
        gpiod_line_release(valve1_line);
        valve1_line = NULL;
    }
    if (valve2_line) {
        gpiod_line_set_value(valve2_line, 0);
        gpiod_line_release(valve2_line);
        valve2_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip4\")");
        cleanup();
        return EXIT_FAILURE;
    }

    valve1_line = gpiod_chip_get_line(chip, VALVE1_GPIO);
    if (!valve1_line) {
        perror("gpiod_chip_get_line(VALVE1_GPIO)");
        cleanup();
        return EXIT_FAILURE;
    }

    valve2_line = gpiod_chip_get_line(chip, VALVE2_GPIO);
    if (!valve2_line) {
        perror("gpiod_chip_get_line(VALVE2_GPIO)");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(valve1_line, "valve1", 0) < 0) {
        perror("gpiod_line_request_output(valve1)");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(valve2_line, "valve2", 0) < 0) {
        perror("gpiod_line_request_output(valve2)");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Greenhouse irrigation system started.");

    while (program_running) {
        if (gpiod_line_set_value(valve1_line, 1) < 0) {
            perror("gpiod_line_set_value(valve1, ON)");
            log_event("ERROR: Failed to activate Valve 1.");
        } else {
            log_event("Valve 1 activated.");
        }
        usleep(VALVE1_DURATION_MS * 1000);

        if (!program_running) break;

        if (gpiod_line_set_value(valve1_line, 0) < 0) {
            perror("gpiod_line_set_value(valve1, OFF)");
            log_event("ERROR: Failed to deactivate Valve 1.");
        } else {
            log_event("Valve 1 deactivated.");
        }
        sleep(VALVE1_PAUSE_SEC);

        if (!program_running) break;

        if (gpiod_line_set_value(valve2_line, 1) < 0) {
            perror("gpiod_line_set_value(valve2, ON)");
            log_event("ERROR: Failed to activate Valve 2.");
        } else {
            log_event("Valve 2 activated.");
        }
        usleep(VALVE2_DURATION_MS * 1000);

        if (!program_running) break;

        if (gpiod_line_set_value(valve2_line, 0) < 0) {
            perror("gpiod_line_set_value(valve2, OFF)");
            log_event("ERROR: Failed to deactivate Valve 2.");
        } else {
            log_event("Valve 2 deactivated.");
        }
        sleep(VALVE2_PAUSE_SEC);
    }

    log_event("Greenhouse irrigation system stopped.");
    cleanup();
    return EXIT_SUCCESS;
}

