#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d\n", reg, value, rc);
    }
    return rc;
}

static int mpr121_init(void) {
    if (mpr121_write(MPR121_ECR, 0x00) < 0) return -1;
    gpioDelay(1000);

    for (int i = 0; i < 12; i++) {
        if (mpr121_write(MPR121_E0TTH + 2 * i, 0x10) < 0) return -1;
        if (mpr121_write(MPR121_E0RTH + 2 * i, 0x0A) < 0) return -1;
    }

    if (mpr121_write(MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write(MPR121_FDLR, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHDF, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCLF, 0x0E) < 0) return -1;
    if (mpr121_write(MPR121_FDLF, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_NHDT, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCLT, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FDLT, 0x00) < 0) return -1;

    if (mpr121_write(MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write(MPR121_CONFIG2, 0x20) < 0) return -1;

    if (mpr121_write(MPR121_ECR, 0x80) < 0) return -1;
    gpioDelay(100000);
    return 0;
}

static int read_touch_status(uint16_t *status) {
    int rc = i2cReadWordData(i2c_handle, MPR121_TOUCHSTATUS_L);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: rc=%d\n", rc);
        return -1;
    }
    *status = (uint16_t)(rc & 0xFFFF);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t touch_status;
    int relay_state = 0;

    while (running) {
        if (read_touch_status(&touch_status) == 0) {
            if (touch_status > 0) {
                relay_state = !relay_state;
                gpioWrite(RELAY_GPIO, relay_state);
                printf("Touch detected (0x%04X), relay %s\n", touch_status, relay_state ? "ON" : "OFF");
            }
        } else {
            fprintf(stderr, "Failed to read touch status\n");
        }
        gpioDelay(100000);
    }

    gpioWrite(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

