        return 1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set RELAY_PIN mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(RELAY_PIN, 0) < 0) {
