        gpioTerminate();
        return 1;
    }

    log_file = fopen("door_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open log file\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler\n");
    }

    printf("Motion detection system started. Press Ctrl+C to exit.\n");
    log_event("System started");

    int last_pir_state = 0;
    uint32_t last_event_tick = 0;

    while (running) {
        int pir_state = gpioRead(PIR_PIN);
