            }
        }
        last_pir_state = pir_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    log_event("System stopped");

    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    return 0;
}

