#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MIN_DUTY 0
#define MAX_DUTY 255
#define MIN_DURATION_MS 50
#define MAX_DURATION_MS 200
#define MIN_STEPS 5
#define MAX_STEPS 15

static volatile sig_atomic_t shutdown_requested = 0;

static void signal_handler(int sig) {
    (void)sig;
    shutdown_requested = 1;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void stop_motors(void) {
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
}

static void cleanup(void) {
    stop_motors();
    gpioTerminate();
}

static void generate_pattern(int *motor1_duty, int *motor2_duty, int *duration_ms, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        motor1_duty[i] = MIN_DUTY + (rand() % (MAX_DUTY - MIN_DUTY + 1));
        motor2_duty[i] = MIN_DUTY + (rand() % (MAX_DUTY - MIN_DUTY + 1));
        duration_ms[i] = MIN_DURATION_MS + (rand() % (MAX_DURATION_MS - MIN_DURATION_MS + 1));
    }
}

static void play_pattern(const int *motor1_duty, const int *motor2_duty,
                         const int *duration_ms, int num_steps) {
    for (int i = 0; i < num_steps && !shutdown_requested; i++) {
        gpioPWM(MOTOR1_PIN, motor1_duty[i]);
        gpioPWM(MOTOR2_PIN, motor2_duty[i]);
        gpioDelay(duration_ms[i] * 1000);
    }
}

int main(void) {
    srand((unsigned int)time(NULL));

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Warning: could not register SIGINT handler");
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int num_steps = MIN_STEPS + (rand() % (MAX_STEPS - MIN_STEPS + 1));
    int *motor1_duty = malloc(num_steps * sizeof(int));
    int *motor2_duty = malloc(num_steps * sizeof(int));
    int *duration_ms = malloc(num_steps * sizeof(int));

    if (motor1_duty == NULL || motor2_duty == NULL || duration_ms == NULL) {
        fprintf(stderr, "Error: memory allocation failed.\n");
        free(motor1_duty);
        free(motor2_duty);
        free(duration_ms);
        cleanup();
        return EXIT_FAILURE;
    }

    generate_pattern(motor1_duty, motor2_duty, duration_ms, num_steps);

    while (!shutdown_requested) {
        printf("Playing pattern with %d steps...\n", num_steps);
        play_pattern(motor1_duty, motor2_duty, duration_ms, num_steps);
        num_steps = MIN_STEPS + (rand() % (MAX_STEPS - MIN_STEPS + 1));
    }

    free(motor1_duty);
    free(motor2_duty);
    free(duration_ms);
    cleanup();

    printf("Shutdown complete.\n");
    return EXIT_SUCCESS;
}

