#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define WEIGHT_LOG_FILE "weight_log.txt"
#define CALIBRATION_SAMPLES 100
#define CALIBRATION_THRESHOLD 10.0
#define READ_TIMEOUT_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin) {
    int data = 0;
    int timeout = 0;

    gpioSetMode(clock_pin, PI_OUTPUT);
    gpioSetMode(data_pin, PI_INPUT);

    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    while (gpioRead(data_pin) == 1) {
        gpioDelay(10);
        timeout += 10;
        if (timeout >= READ_TIMEOUT_US) {
            return -1;
        }
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(data_pin)) {
            data |= 1;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

static int load_calibration(float *scale_factor, float *offset) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (!fp) {
        return -1;
    }
    if (fscanf(fp, "%f %f", scale_factor, offset) != 2) {
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int save_calibration(float scale_factor, float offset) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (!fp) {
        return -1;
    }
    fprintf(fp, "%f %f\n", scale_factor, offset);
    fclose(fp);
    return 0;
}

static int calibrate_hx711(int data_pin, int clock_pin, float *scale_factor, float *offset) {
    int raw_sum = 0;
    int valid_readings = 0;

    printf("Starting calibration. Place no load on the sensor and press Enter.\n");
    getchar();

    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        int raw = read_hx711(data_pin, clock_pin);
        if (raw == -1) {
            fprintf(stderr, "Calibration read timeout at sample %d\n", i);
            return -1;
        }
        raw_sum += raw;
        valid_readings++;
        gpioDelay(10000);
    }

    if (valid_readings == 0) {
        fprintf(stderr, "Calibration failed: no valid readings\n");
        return -1;
    }

    *offset = (float)raw_sum / valid_readings;
    *scale_factor = 1.0;

    printf("Calibration complete. Offset: %.2f\n", *offset);
    return 0;
}

static float read_weight(int data_pin, int clock_pin, float scale_factor, float offset) {
    int raw = read_hx711(data_pin, clock_pin);
    if (raw == -1) {
        return -1.0;
    }
    return ((float)raw - offset) / scale_factor;
}

static void log_weight(float weight) {
    FILE *fp = fopen(WEIGHT_LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Weight: %.2f kg\n", timestamp, weight);
    fclose(fp);
}

int main(void) {
    float scale_factor = 1.0;
    float offset = 0.0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (load_calibration(&scale_factor, &offset) != 0) {
        fprintf(stderr, "Calibration file not found or invalid. Starting calibration.\n");
        if (calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &scale_factor, &offset) != 0) {
            fprintf(stderr, "Calibration failed. Exiting.\n");
            gpioTerminate();
            return 1;
        }
        if (save_calibration(scale_factor, offset) != 0) {
            fprintf(stderr, "Failed to save calibration.\n");
        }
    }

    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0);

    printf("System started. Press Ctrl+C to exit.\n");

    while (running) {
        float weight = read_weight(HX711_DATA_PIN, HX711_CLOCK_PIN, scale_factor, offset);

        if (weight == -1.0) {
            fprintf(stderr, "Sensor read timeout. Skipping iteration.\n");
            gpioDelay(500000);
            continue;
        }

        log_weight(weight);

        if (weight > (CALIBRATION_THRESHOLD / scale_factor) + offset) {
            gpioWrite(SOLENOID_PIN, 1);
            printf("Weight %.2f kg exceeds threshold. Lock engaged.\n", weight);
        } else {
            gpioWrite(SOLENOID_PIN, 0);
            printf("Weight %.2f kg below threshold. Lock released.\n", weight);
        }

        gpioDelay(500000);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("System stopped.\n");
    return 0;
}

