#include <unistd.h>

#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_US 50000
#define MOTOR_RUN_TIME_US 5000000
#define MOTOR_PWM_FREQ 1000
#define MOTOR_PWM_DUTY 150
#define CHECK_INTERVAL_US 60000000
#define MOTOR_STOP_DELAY_US 60000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin mode");
        return -1;
    }

    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set motor pin modes");
        return -1;
    }

    if (gpioSetPWMfrequency(MOTOR_PWM_PIN, MOTOR_PWM_FREQ) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency");
        return -1;
    }

    if (gpioPWM(MOTOR_PWM_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to initialise PWM duty cycle");
        return -1;
    }

    if (gpioWrite(MOTOR_IN1_PIN, 0) != 0 ||
        gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to initialise motor pins");
        return -1;
    }

    return 0;
}

static int read_rain_sensor(void) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int val = gpioRead(RAIN_SENSOR_PIN);
        if (val < 0) {
            syslog(LOG_ERR, "Failed to read rain sensor");
            return -1;
        }
        if (val == 0) {
            low_count++;
        }
        if (i < DEBOUNCE_READINGS - 1) {
            gpioDelay(DEBOUNCE_DELAY_US);
        }
    }
    return (low_count >= 3) ? 0 : 1;
}

static int close_window(void) {
    if (gpioWrite(MOTOR_IN1_PIN, 1) != 0 ||
