        syslog(LOG_ERR, "Failed to set motor direction");
        return -1;
    }

    if (gpioPWM(MOTOR_PWM_PIN, MOTOR_PWM_DUTY) != 0) {
        syslog(LOG_ERR, "Failed to start PWM");
        return -1;
    }

    gpioDelay(MOTOR_RUN_TIME_US);

    if (gpioPWM(MOTOR_PWM_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to stop PWM");
        return -1;
    }

    if (gpioWrite(MOTOR_IN1_PIN, 0) != 0 ||
        gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to stop motor");
        return -1;
    }

    return 0;
}

static void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s: %s", timestamp, event);
}

int main(void) {
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handlers");
        closelog();
        return 1;
    }

    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    log_event("Program started");

    while (running) {
        int rain = read_rain_sensor();
        if (rain < 0) {
            log_event("Error reading rain sensor");
            gpioDelay(CHECK_INTERVAL_US);
            continue;
        }

        if (rain == 0) {
            log_event("Rain detected, closing window");
            if (close_window() != 0) {
                log_event("Error closing window");
            } else {
                log_event("Window closed");
            }
            gpioDelay(MOTOR_STOP_DELAY_US);
        } else {
            gpioDelay(CHECK_INTERVAL_US);
        }
    }

    gpioPWM(MOTOR_PWM_PIN, 0);
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioTerminate();
    log_event("Program terminated");
    closelog();
    return 0;
}

