#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define HX711_DT 23
#define HX711_SCK 24
#define SOLENOID_PIN 17
#define WEIGHT_THRESHOLD 100
#define SOLENOID_DURATION 5
#define HX711_TIMEOUT_US 1000000
#define HX711_SETTLE_US 1
#define HX711_READ_RETRIES 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int dt, int sck) {
    int timeout = HX711_TIMEOUT_US;
    int data = 0;

    gpioSetMode(sck, PI_OUTPUT);
    gpioSetMode(dt, PI_INPUT);
    gpioWrite(sck, 0);

    while (gpioRead(dt) == 1) {
        gpioDelay(1);
        timeout--;
        if (timeout <= 0) {
            fprintf(stderr, "HX711 timeout: DT stuck high\n");
            return -1;
        }
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(sck, 1);
        gpioDelay(HX711_SETTLE_US);
        data = (data << 1) | gpioRead(dt);
        gpioWrite(sck, 0);
        gpioDelay(HX711_SETTLE_US);
    }

    gpioWrite(sck, 1);
    gpioDelay(HX711_SETTLE_US);
    gpioWrite(sck, 0);
    gpioDelay(HX711_SETTLE_US);

    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

static int log_event(const char *message) {
    FILE *fp = fopen("stock_events.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening stock_events.txt: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (!tm) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error writing to stock_events.txt\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing stock_events.txt: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int activate_solenoid(int pin, int duration) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error activating solenoid on GPIO%d\n", pin);
        return -1;
    }

    gpioDelay(duration * 1000000);

    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error deactivating solenoid on GPIO%d\n", pin);
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting solenoid pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_PIN, 0) != 0) {
        fprintf(stderr, "Error initializing solenoid pin state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Kitchen ingredient stock monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_weight = -1;
        int retries = HX711_READ_RETRIES;

        while (retries > 0 && running) {
            raw_weight = read_hx711(HX711_DT, HX711_SCK);
            if (raw_weight >= 0) break;
            retries--;
            gpioDelay(100000);
        }

        if (raw_weight < 0) {
            fprintf(stderr, "Failed to read HX711 after %d retries\n", HX711_READ_RETRIES);
            gpioDelay(1000000);
            continue;
        }

        int weight = raw_weight;
        if (weight < 0) weight = -weight;

        printf("Weight: %d g\n", weight);

        if (weight < WEIGHT_THRESHOLD) {
            printf("Weight below threshold! Activating solenoid.\n");
            if (activate_solenoid(SOLENOID_PIN, SOLENOID_DURATION) != 0) {
                fprintf(stderr, "Solenoid activation failed\n");
            } else {
                if (log_event("Solenoid activated") != 0) {
                    fprintf(stderr, "Failed to log event\n");
                }
            }
        }

        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

