static volatile sig_atomic_t running = 1;
static FILE *calibration_file = NULL;
static FILE *security_log_file = NULL;
static double calibration_factor = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin, long *raw_value) {
    int timeout = 0;
    while (gpioRead(data_pin) == 1) {
        gpioDelay(10);
        timeout += 10;
        if (timeout > HX711_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout: data line stuck high\n");
            return -1;
        }
    }

    long value = 0;
    for (int i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        value = (value << 1) | gpioRead(data_pin);
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    *raw_value = value;
    return 0;
}

static double calculate_weight(long raw_value, double calibration_factor) {
    return (double)raw_value / calibration_factor;
}

static int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (security_log_file == NULL) {
        security_log_file = fopen(SECURITY_LOG_FILE, "a");
        if (security_log_file == NULL) {
            perror("Error opening security log file");
            return -1;
        }
    }

    if (fprintf(security_log_file, "%s: %s\n", timestamp, message) < 0) {
        perror("Error writing to security log file");
        return -1;
    }
    fflush(security_log_file);
    return 0;
}

static int save_calibration(double calibration_factor) {
    if (calibration_file == NULL) {
        calibration_file = fopen(CALIBRATION_FILE, "w");
        if (calibration_file == NULL) {
            perror("Error opening calibration file");
            return -1;
        }
    }

    if (fprintf(calibration_file, "%.6f\n", calibration_factor) < 0) {
        perror("Error writing to calibration file");
        return -1;
    }
    fflush(calibration_file);
    return 0;
}

static int load_calibration(void) {
    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file == NULL) {
        fprintf(stderr, "Calibration file not found. Starting calibration.\n");
        return -1;
    }

    if (fscanf(calibration_file, "%lf", &calibration_factor) != 1) {
        fprintf(stderr, "Failed to read calibration factor from file.\n");
        fclose(calibration_file);
        calibration_file = NULL;
        return -1;
    }

    fclose(calibration_file);
    calibration_file = NULL;
    printf("Calibration factor loaded: %.6f\n", calibration_factor);
    return 0;
}

static int calibrate_load_cell(double known_weight_kg) {
    printf("Place a known weight of %.2f kg on the load cell.\n", known_weight_kg);
    printf("Press Enter to start reading...\n");
    getchar();

    long raw_value;
    if (read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &raw_value) != 0) {
        fprintf(stderr, "Failed to read raw value during calibration.\n");
        return -1;
    }

    calibration_factor = (double)raw_value / known_weight_kg;
    printf("Calibration factor: %.6f\n", calibration_factor);

    if (save_calibration(calibration_factor) != 0) {
        fprintf(stderr, "Failed to save calibration factor.\n");
        return -1;
    }

    return 0;
}

static void control_solenoid(int state) {
    gpioWrite(SOLENOID_PIN, state);
    printf("Solenoid %s\n", state ? "locked" : "unlocked");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioWrite(SOLENOID_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (load_calibration() != 0) {
        if (calibrate_load_cell(1.0) != 0) {
            fprintf(stderr, "Calibration failed. Exiting.\n");
            gpioWrite(SOLENOID_PIN, 0);
            gpioTerminate();
            return 1;
        }
    }

    printf("Starting weight monitoring...\n");

    while (running) {
        long raw_value;
        if (read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &raw_value) != 0) {
            fprintf(stderr, "HX711 read error. Retrying...\n");
            gpioDelay(1000000);
            continue;
        }

        double weight = calculate_weight(raw_value, calibration_factor);
        printf("Weight: %.2f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            char message[128];
            snprintf(message, sizeof(message), "Weight threshold exceeded: %.2f kg", weight);
            log_event(message);
            control_solenoid(1);
