#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define CONFIG_FILE "watering.conf"
#define GPIO_CHIP_NAME "gpiochip0"
#define VALVE_LINE_OFFSET 18
#define MAX_DURATION 3600
#define MIN_DURATION 1
#define CONFIG_LINE_LEN 256

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_duration(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return -1;
    }

    char line[CONFIG_LINE_LEN];
    if (!fgets(line, sizeof(line), fp)) {
        if (ferror(fp)) {
            fprintf(stderr, "Error reading %s: %s\n", filename, strerror(errno));
        } else {
            fprintf(stderr, "Error reading %s: file is empty\n", filename);
        }
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *eq = strchr(line, '=');
    if (!eq) {
        fprintf(stderr, "Error reading %s: missing '='\n", filename);
        return -1;
    }

    char *val = eq + 1;
    while (*val == ' ' || *val == '\t') val++;
    if (*val == '\0') {
        fprintf(stderr, "Error reading %s: empty value\n", filename);
        return -1;
    }

    errno = 0;
    char *endptr = NULL;
    long val_long = strtol(val, &endptr, 10);
    if (errno != 0 || endptr == val || *endptr != '\0') {
        fprintf(stderr, "Error reading %s: invalid integer value\n", filename);
        return -1;
    }

    if (val_long < MIN_DURATION || val_long > MAX_DURATION) {
        fprintf(stderr, "Error reading %s: duration %ld out of range [%d, %d]\n",
                filename, val_long, MIN_DURATION, MAX_DURATION);
        return -1;
    }

    *duration = (int)val_long;
    return 0;
}

static void sleep_interruptible(unsigned int seconds) {
    struct timespec req = { .tv_sec = seconds, .tv_nsec = 0 };
    while (nanosleep(&req, &req) == -1 && errno == EINTR) {
        if (!program_running) {
            return;
        }
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, VALVE_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", VALVE_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "watering-valve", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                VALVE_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Valve control initialized on GPIO%d (BCM). Waiting for watering command...\n",
           VALVE_LINE_OFFSET);

    int duration = 0;
    if (read_duration(CONFIG_FILE, &duration) != 0) {
        fprintf(stderr, "Failed to read watering duration from %s\n", CONFIG_FILE);
        goto cleanup;
    }

    printf("Watering duration: %d seconds\n", duration);

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to activate valve: %s\n", strerror(errno));
        goto cleanup;
    }
    printf("Valve activated (ON)\n");

    if (!program_running) {
        fprintf(stderr, "Interrupted before watering started; deactivating valve.\n");
        if (gpiod_line_set_value(line, 0) < 0) {
            fprintf(stderr, "Failed to deactivate valve: %s\n", strerror(errno));
        }
        goto cleanup;
    }

    sleep_interruptible(duration);

    if (!program_running) {
        fprintf(stderr, "Interrupted during watering; deactivating valve.\n");
    } else {
        printf("Watering duration complete.\n");
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to deactivate valve: %s\n", strerror(errno));
        goto cleanup;
    }
    printf("Valve deactivated (OFF)\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

