#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

#define LEFT_MOTOR_PIN 22
#define RIGHT_MOTOR_PIN 24
#define LEFT_ENABLE_PIN 23
#define RIGHT_ENABLE_PIN 25

#define BASE_SPEED 150
#define PWM_FREQUENCY 1000
#define LOG_FILE "trace_log.txt"
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(LEFT_MOTOR_PIN, 0);
    gpioPWM(RIGHT_MOTOR_PIN, 0);
    gpioWrite(LEFT_ENABLE_PIN, 0);
    gpioWrite(RIGHT_ENABLE_PIN, 0);
    gpioTerminate();
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set LEFT_SENSOR_PIN mode\n");
        return -1;
    }
    if (gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set MIDDLE_SENSOR_PIN mode\n");
        return -1;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set RIGHT_SENSOR_PIN mode\n");
        return -1;
    }

    if (gpioSetMode(LEFT_MOTOR_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LEFT_MOTOR_PIN mode\n");
        return -1;
    }
    if (gpioSetMode(RIGHT_MOTOR_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set RIGHT_MOTOR_PIN mode\n");
        return -1;
    }
    if (gpioSetMode(LEFT_ENABLE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LEFT_ENABLE_PIN mode\n");
        return -1;
    }
    if (gpioSetMode(RIGHT_ENABLE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set RIGHT_ENABLE_PIN mode\n");
        return -1;
    }

    if (gpioSetPWMfrequency(LEFT_MOTOR_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for LEFT_MOTOR_PIN\n");
        return -1;
    }
    if (gpioSetPWMfrequency(RIGHT_MOTOR_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for RIGHT_MOTOR_PIN\n");
        return -1;
    }

    if (gpioWrite(LEFT_ENABLE_PIN, 1) != 0) {
        fprintf(stderr, "Failed to enable LEFT motor\n");
        return -1;
    }
    if (gpioWrite(RIGHT_ENABLE_PIN, 1) != 0) {
        fprintf(stderr, "Failed to enable RIGHT motor\n");
        return -1;
    }

    return 0;
}

static int read_sensors(void) {
    int left = gpioRead(LEFT_SENSOR_PIN);
    int middle = gpioRead(MIDDLE_SENSOR_PIN);
    int right = gpioRead(RIGHT_SENSOR_PIN);

    if (left < 0 || middle < 0 || right < 0) {
        fprintf(stderr, "Error reading sensor pins\n");
        return -1;
    }
    return (left << 16) | (middle << 8) | right;
}

static void set_motor_speed(int left_speed, int right_speed) {
    if (gpioPWM(LEFT_MOTOR_PIN, left_speed) != 0) {
        fprintf(stderr, "Error setting LEFT_MOTOR_PWM\n");
    }
    if (gpioPWM(RIGHT_MOTOR_PIN, right_speed) != 0) {
        fprintf(stderr, "Error setting RIGHT_MOTOR_PWM\n");
    }
}

static void log_data(int left_state, int middle_state, int right_state,
                     int left_speed, int right_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file) {
        fprintf(log_file, "%s, %d, %d, %d, %d, %d\n",
                timestamp, left_state, middle_state, right_state,
                left_speed, right_speed);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: log file is not open\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    while (running) {
        int sensors = read_sensors();
        if (sensors < 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        int left_state = (sensors >> 16) & 1;
        int middle_state = (sensors >> 8) & 1;
        int right_state = sensors & 1;

        int left_speed = BASE_SPEED;
        int right_speed = BASE_SPEED;

        if (middle_state == 0) {
            /* Line detected under middle sensor */
        } else if (left_state == 0) {
            /* Line on left side */
            left_speed = BASE_SPEED / 2;
        } else if (right_state == 0) {
            /* Line on right side */
            right_speed = BASE_SPEED / 2;
        } else {
            /* No line detected */
            left_speed = 0;
            right_speed = 0;
        }

        set_motor_speed(left_speed, right_speed);
        log_data(left_state, middle_state, right_state, left_speed, right_speed);

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return 0;
}

