#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

#define LOCK_POSITION 1000  /* microseconds ~ 0 degrees */
#define UNLOCK_POSITION 2000 /* microseconds ~ 180 degrees */

#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_position(int gpio, int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE || pulse_width > SERVO_MAX_PULSE) {
        fprintf(stderr, "Error: pulse width %d out of range [%d, %d]\n",
                pulse_width, SERVO_MIN_PULSE, SERVO_MAX_PULSE);
        return -1;
    }
    if (gpioServo(gpio, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed on GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

static int lock_door(void) {
    printf("Locking door...\n");
    return set_servo_position(SERVO_PIN, LOCK_POSITION);
}

static int unlock_door(void) {
    printf("Unlocking door...\n");
    return set_servo_position(SERVO_PIN, UNLOCK_POSITION);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: could not register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure button pins as inputs with pull-up resistors (external or internal) */
    if (gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for LOCK_BUTTON_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for UNLOCK_BUTTON_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for LOCK_BUTTON_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for UNLOCK_BUTTON_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure servo starts at a safe position */
    if (set_servo_position(SERVO_PIN, LOCK_POSITION) < 0) {
        fprintf(stderr, "Error: failed to initialise servo position\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock control ready. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(LOCK_BUTTON_PIN) == 0) {
            printf("Lock button pressed\n");
            if (lock_door() == 0) {
                gpioDelay(100000); /* 100 ms debounce */
            }
        }

        if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
            printf("Unlock button pressed\n");
            if (unlock_door() == 0) {
                gpioDelay(100000); /* 100 ms debounce */
            }
        }

        gpioDelay(10000); /* 10 ms poll interval */
    }

    /* Clean shutdown: centre servo and release pigpio */
    gpioServo(SERVO_PIN, 0); /* stop PWM pulses */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

