#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>
#include <zmq.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27
#define ZMQ_PUB_ENDPOINT "tcp://*:5555"
#define ZMQ_SUB_ENDPOINT "tcp://localhost:5555"
#define SOUND_ALERTS_TOPIC "SOUND_ALERTS"
#define POLL_INTERVAL_MS 10
#define ALARM_DURATION_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_ms(unsigned int ms) {
    struct timespec ts = {
        .tv_sec = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s (errno: %s)\n", ts, msg, strerror(errno));
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sound_sensor|alarm_node>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];
    if (strcmp(mode, "sound_sensor") != 0 && strcmp(mode, "alarm_node") != 0) {
        fprintf(stderr, "Invalid mode: %s. Use 'sound_sensor' or 'alarm_node'.\n", mode);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        log_error("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        log_error("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sound_line = NULL;
    struct gpiod_line *led_line = NULL;
    int zmq_rc = EXIT_FAILURE;

    if (strcmp(mode, "sound_sensor") == 0) {
        chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
        if (!chip) {
            log_error("gpiod_chip_open_by_name");
            goto cleanup;
        }

        sound_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
        if (!sound_line) {
            log_error("gpiod_chip_get_line(sound)");
            goto cleanup;
        }

        if (gpiod_line_request_input(sound_line, "sound_sensor") < 0) {
            log_error("gpiod_line_request_input(sound)");
            goto cleanup;
        }

        zmq_rc = EXIT_SUCCESS;
    } else {
        led_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
        if (!led_line) {
            log_error("gpiod_chip_get_line(led)");
            goto cleanup;
        }

        if (gpiod_line_request_output(led_line, "alarm_led", 0) < 0) {
            log_error("gpiod_line_request_output(led)");
            goto cleanup;
        }

        zmq_rc = EXIT_SUCCESS;
    }

    void *context = zmq_ctx_new();
    if (!context) {
        log_error("zmq_ctx_new");
        goto cleanup;
    }

    void *socket = NULL;
    if (strcmp(mode, "sound_sensor") == 0) {
        socket = zmq_socket(context, ZMQ_PUB);
        if (!socket) {
            log_error("zmq_socket(PUB)");
            goto cleanup;
        }

        if (zmq_bind(socket, ZMQ_PUB_ENDPOINT) < 0) {
            log_error("zmq_bind(PUB)");
            goto cleanup;
        }
    } else {
        socket = zmq_socket(context, ZMQ_SUB);
        if (!socket) {
            log_error("zmq_socket(SUB)");
            goto cleanup;
        }

        if (zmq_setsockopt(socket, ZMQ_SUBSCRIBE, SOUND_ALERTS_TOPIC, strlen(SOUND_ALERTS_TOPIC)) < 0) {
            log_error("zmq_setsockopt(SUB)");
            goto cleanup;
        }

        if (zmq_connect(socket, ZMQ_SUB_ENDPOINT) < 0) {
            log_error("zmq_connect(SUB)");
            goto cleanup;
        }
    }

    printf("Running in %s mode...\n", mode);

    while (running) {
        if (strcmp(mode, "sound_sensor") == 0) {
            int val = gpiod_line_get_value(sound_line);
            if (val < 0) {
                log_error("gpiod_line_get_value(sound)");
                sleep_ms(POLL_INTERVAL_MS);
                continue;
            }
            if (val == 0) {
                char buf[64];
                time_t now = time(NULL);
                struct tm *t = localtime(&now);
                strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", t);
                char *msg = malloc(strlen(buf) + strlen(SOUND_ALERTS_TOPIC) + 16);
                if (msg) {
                    snprintf(msg, strlen(buf) + strlen(SOUND_ALERTS_TOPIC) + 16, "%s - %s", buf, SOUND_ALERTS_TOPIC);
                    if (zmq_send(socket, msg, strlen(msg), 0) < 0) {
                        log_error("zmq_send(PUB)");
                    }
                    free(msg);
                }
            }
        } else {
            char buffer[256];
            int recv_rc = zmq_recv(socket, buffer, sizeof(buffer) - 1, 0);
            if (recv_rc < 0) {
                if (errno == EINTR) continue;
                log_error("zmq_recv(SUB)");
                sleep_ms(POLL_INTERVAL_MS);
                continue;
            }
            buffer[recv_rc] = '\0';
            printf("Received: %s\n", buffer);

            if (gpiod_line_set_value(led_line, 1) < 0) {
                log_error("gpiod_line_set_value(led, 1)");
            }
            sleep_ms(ALARM_DURATION_MS);
            if (gpiod_line_set_value(led_line, 0) < 0) {
                log_error("gpiod_line_set_value(led, 0)");
            }
        }
        sleep_ms(POLL_INTERVAL_MS);
    }

cleanup:
    if (socket) zmq_close(socket);
    if (context) zmq_ctx_destroy(context);
    if (sound_line) gpiod_line_release(sound_line);
    if (led_line) gpiod_line_release(led_line);
    if (chip) gpiod_chip_close(chip);
    return zmq_rc;
}

