#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define IR_GPIO 17
#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MAX_PULSES 100
#define MAX_PULSES_PER_FRAME 68

/* NEC timing constants (microseconds) */
#define NEC_HDR_MARK 9000
#define NEC_HDR_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define NEC_RPT_SPACE 2250
#define NEC_TOL 25

typedef struct {
    uint32_t address;
    uint32_t command;
    int valid;
} ir_data_t;

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t pulse_count = 0;
static volatile uint32_t pulse_lengths[MAX_PULSES];
static MQTTClient mqtt_client;
static MQTTClient_connectOptions mqtt_connect_options = MQTTClient_connectOptions_initializer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int decode_nec(const uint32_t *pulses, int count, ir_data_t *out) {
    out->address = 0;
    out->command = 0;
    out->valid = 0;

    if (count < 68) return 0;

    /* Validate header */
    if (pulses[0] < NEC_HDR_MARK - NEC_TOL || pulses[0] > NEC_HDR_MARK + NEC_TOL) return 0;
    if (pulses[1] < NEC_HDR_SPACE - NEC_TOL || pulses[1] > NEC_HDR_SPACE + NEC_TOL) return 0;

    /* Decode 32-bit address (top 8 bits) */
    for (int i = 0; i < 8; i++) {
        int idx = 2 + i * 2;
        if (pulses[idx] < NEC_BIT_MARK - NEC_TOL || pulses[idx] > NEC_BIT_MARK + NEC_TOL) return 0;
        if (pulses[idx + 1] > NEC_ZERO_SPACE - NEC_TOL && pulses[idx + 1] < NEC_ONE_SPACE + NEC_TOL) {
            out->address = (out->address << 1) | 1;
        } else if (pulses[idx + 1] > NEC_ZERO_SPACE - NEC_TOL && pulses[idx + 1] < NEC_ONE_SPACE + NEC_TOL) {
            out->address = (out->address << 1) | 0;
        } else {
            return 0;
        }
    }

    /* Decode 32-bit command (top 8 bits) */
    for (int i = 0; i < 8; i++) {
        int idx = 18 + i * 2;
        if (pulses[idx] < NEC_BIT_MARK - NEC_TOL || pulses[idx] > NEC_BIT_MARK + NEC_TOL) return 0;
        if (pulses[idx + 1] > NEC_ZERO_SPACE - NEC_TOL && pulses[idx + 1] < NEC_ONE_SPACE + NEC_TOL) {
            out->command = (out->command << 1) | 1;
        } else if (pulses[idx + 1] > NEC_ZERO_SPACE - NEC_TOL && pulses[idx + 1] < NEC_ONE_SPACE + NEC_TOL) {
            out->command = (out->command << 1) | 0;
        } else {
            return 0;
        }
    }

    /* Validate checksum (lower 8 bits of address + command should equal 0) */
    uint8_t addr_lo = (uint8_t)(out->address & 0xFF);
    uint8_t cmd_lo = (uint8_t)(out->command & 0xFF);
    uint8_t checksum = (uint8_t)(~((addr_lo + cmd_lo) & 0xFF));
    if (checksum != 0) return 0;

    out->valid = 1;
    return 1;
}

static void ir_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    static uint32_t last_tick = 0;
    uint32_t pulse_len;

    if (level == PI_TIMEOUT) return;

    if (last_tick == 0) {
        last_tick = tick;
        return;
    }

    if (level == 0) {
        pulse_len = tick - last_tick;
        if (pulse_count < MAX_PULSES) {
            pulse_lengths[pulse_count++] = pulse_len;
        }
        last_tick = tick;
    }
}

static void mqtt_connect_callback(void *userdata, char *message, int flag) {
    (void)userdata;
    if (flag == 1) {
        MQTTClient_message *message_info = MQTTClient_message_initializer;
        message_info.payload = (void *)"Connected to MQTT broker";
        message_info.payloadlen = (int)strlen((const char *)message_info.payload);
        message_info.qos = 0;
        message_info.retained = 0;
        MQTTClient_publishMessage(mqtt_client, "status", &message_info);
    } else if (flag == 2) {
        syslog(LOG_ERR, "MQTT connection lost");
    }
}

static void mqtt_message_callback(void *userdata, char *topicName, int topicLen, MQTTClient_message *message) {
    (void)userdata;
    (void)topicLen;
    (void)message;
    syslog(LOG_INFO, "Received MQTT message on topic: %.*s", topicLen, topicName);
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(IR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as input", IR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(IR_GPIO, PI_PUD_UP) != 0) {
        syslog(LOG_ERR, "Failed to set pull-up on GPIO %d", IR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(IR_GPIO, ir_callback) != 0) {
        syslog(LOG_ERR, "Failed to set alert function on GPIO %d", IR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mqtt_client = NULL;
    mqtt_connect_options.keepAliveInterval = 20;
    mqtt_connect_options.cleansession = 1;
    mqtt_connect_options.connectTimeout = 10;

    int rc = MQTTClient_create(&mqtt_client, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, NULL, MQTTCLIENT_PERSISTENCE_NONE);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTTClient_create failed: %s", MQTTClient_strerror(rc));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    rc = MQTTClient_connect(mqtt_client, &mqtt_connect_options, mqtt_connect_callback);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTTClient_connect failed: %s", MQTTClient_strerror(rc));
        MQTTClient_destroy(&mqtt_client);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    rc = MQTTClient_setCallbacks(mqtt_client, NULL, mqtt_connect_callback, mqtt_message_callback, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTTClient_setCallbacks failed: %s", MQTTClient_strerror(rc));
        MQTTClient_destroy(&mqtt_client);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "IR decoder started on GPIO %d", IR_GPIO);

    while (running) {
        if (pulse_count >= MAX_PULSES_PER_FRAME) {
            ir_data_t data;
            if (decode_nec(pulse_lengths, pulse_count, &data)) {
                char json_string[256];
                snprintf(json_string, sizeof(json_string),
                         "{\"address\": 0x%08X, \"command\": 0x%08X, \"valid\": %d}",
                         data.address, data.command, data.valid);
                MQTTClient_message message = MQTTClient_message_initializer;
                message.payload = json_string;
                message.payloadlen = (int)strlen(json_string);
                message.qos = 1;
                message.retained = 0;
                MQTTClient_publishMessage(mqtt_client, MQTT_TOPIC, &message);
                syslog(LOG_INFO, "Decoded: %s", json_string);
            }
            pulse_count = 0;
        }
        gpioDelay(10000);
    }

    syslog(LOG_INFO, "Shutting down...");
    MQTTClient_disconnect(mqtt_client, 1000);
    MQTTClient_destroy(&mqtt_client);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

