#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <math.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS        "/dev/i2c-1"
#define NUM_SENSORS     4
#define MULTICAST_ADDR  "239.255.255.250"
#define MULTICAST_PORT  5005
#define BH1750_CMD_OT_HRES 0x20
#define CONV_TIME_MS    180
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static float read_bh1750(int fd, int addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02x): %s\n", addr, strerror(errno));
        return NAN;
    }

    unsigned char cmd = BH1750_CMD_OT_HRES;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "write(0x%02x): %s\n", addr, strerror(errno));
        return NAN;
    }

    usleep(CONV_TIME_MS * 1000);

    unsigned char buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "read(0x%02x): got %zd bytes (%s)\n", addr, n, strerror(errno));
        return NAN;
    }

    unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
    return (float)raw / 1.2f;
}

static int send_multicast(int sockfd, const char *data) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(sockfd, data, strlen(data), 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto");
        return -1;
    }
    return 0;
}

int main(void) {
    int i2c_fd = -1;
    int sockfd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        goto cleanup;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open(" I2C_BUS ")");
        goto cleanup;
    }

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        goto cleanup;
    }

    printf("Starting BH1750 light sensor broadcast (4 sensors, %s:%d)...\n",
           MULTICAST_ADDR, MULTICAST_PORT);

    while (g_running) {
        char data[256];
        int idx = 0;
        int addrs[NUM_SENSORS] = {0x23, 0x24, 0x25, 0x26};

        for (int i = 0; i < NUM_SENSORS; i++) {
            float lux = read_bh1750(i2c_fd, addrs[i]);
            if (isnan(lux)) {
                fprintf(stderr, "Sensor %d (0x%02x) read failed; reporting NaN\n",
                        i + 1, addrs[i]);
            }
            idx += snprintf(data + idx, sizeof(data) - idx,
                            "%d,%.2f;", i + 1, lux);
        }

        if (idx > 0) {
            data[idx - 1] = '\0';
            if (send_multicast(sockfd, data) < 0) {
                fprintf(stderr, "Multicast send failed\n");
            } else {
                printf("Sent: %s\n", data);
            }
        }

        sleep(SAMPLE_PERIOD_S);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (i2c_fd >= 0) close(i2c_fd);
    if (sockfd >= 0) close(sockfd);
    return rc;
}

