static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read 2 bytes from the AWM7300V.
 * Returns 0 on success, -1 on persistent failure.
 */
static int awm7300_read_flow(int fd, uint16_t *raw_out)
{
    uint8_t buf[2];
    ssize_t n;

    /*
     * A zero-length write acts as a start condition on the bus,
     * followed by a repeated-start read of 2 bytes.
     */
    n = write(fd, buf, 0);
    if (n < 0) {
        fprintf(stderr, "I2C write (start) failed: %s\n", strerror(errno));
        return -1;
    }

    n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        if (n < 0)
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        else
            fprintf(stderr, "I2C read short: %zd bytes\n", n);
        return -1;
    }

    /* 14-bit data in the first two bytes; mask to 14 bits */
    *raw_out = ((uint16_t)buf[0] << 8) | buf[1];
    *raw_out &= 0x3FFF;
    return 0;
}

static float raw_to_slpm(uint16_t raw)
{
    return ((float)raw - 3277.0f) * 0.1f;
}

static void log_data(FILE *fp, float flow_slpm)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, %.2f SLPM\n", ts, flow_slpm) < 0)
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    else
        fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    uint16_t raw;
    float flow;
    int attempt;

    /* --- Signal handling --- */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AWM7300_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                AWM7300_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("AWM7300V airflow logger started. Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int success = 0;

        for (attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (awm7300_read_flow(g_i2c_fd, &raw) == 0) {
                success = 1;
                break;
            }
            if (errno == ENXIO || errno == EIO) {
                fprintf(stderr, "I2C bus error (attempt %d/%d): %s\n",
                        attempt + 1, MAX_RETRIES, strerror(errno));
            }
            if (attempt < MAX_RETRIES - 1)
                usleep(RETRY_DELAY_MS * 1000);
        }

        if (success) {
            flow = raw_to_slpm(raw);
            log_data(g_log_fp, flow);
            printf("Flow: %.2f SLPM\n", flow);
        } else {
            fprintf(stderr, "Failed to read flow after %d attempts.\n", MAX_RETRIES);
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            usleep(100 * 1000);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

