#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define AS7341_ADDR 0x39
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "spectral_log.csv"

#define REG_ENABLE 0x80
#define REG_PON 0x01
#define REG_CFG6 0xAF
#define REG_ID 0x24
#define REG_F1 0x60
#define REG_F2 0x61
#define REG_F3 0x62
#define REG_F4 0x63
#define REG_F5 0x64
#define REG_F6 0x65
#define REG_F7 0x66
#define REG_F8 0x67
#define REG_CLEAR 0x68
#define REG_NIR 0x69

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_as7341(int fd) {
    uint8_t id = 0;
    if (i2c_read_reg8(fd, REG_ID, &id) < 0) return -1;
    if (id != 0x19) {
        fprintf(stderr, "AS7341 ID mismatch: got 0x%02X, expected 0x19\n", id);
        return -1;
    }
    if (i2c_write_reg8(fd, REG_ENABLE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_CFG6, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_ENABLE, REG_PON) < 0) return -1;
    usleep(100000);
    return 0;
}

static int read_channel(int fd, uint8_t reg, uint16_t *value) {
    uint8_t lo = 0, hi = 0;
    if (i2c_read_reg8(fd, reg, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, reg + 1, &hi) < 0) return -1;
    *value = (uint16_t)((hi << 8) | lo);
    return 0;
}

static float calculate_lux(uint16_t f1, uint16_t f2, uint16_t f3, uint16_t f4,
                           uint16_t f5, uint16_t f6, uint16_t f7, uint16_t f8,
                           uint16_t clear, uint16_t nir) {
    float f1_f = (float)f1 / 65535.0f;
    float f2_f = (float)f2 / 65535.0f;
    float f3_f = (float)f3 / 65535.0f;
    float f4_f = (float)f4 / 65535.0f;
    float f5_f = (float)f5 / 65535.0f;
    float f6_f = (float)f6 / 65535.0f;
    float f7_f = (float)f7 / 65535.0f;
    float f8_f = (float)f8 / 65535.0f;
    float clear_f = (float)clear / 65535.0f;
    float nir_f = (float)nir / 65535.0f;
    float lux = (f1_f + f2_f + f3_f + f4_f + f5_f + f6_f + f7_f + f8_f + clear_f) * 100.0f;
    return lux;
}

static void log_data(FILE *fp, float lux, uint16_t f1, uint16_t f2, uint16_t f3,
                     uint16_t f4, uint16_t f5, uint16_t f6, uint16_t f7,
                     uint16_t f8, uint16_t clear, uint16_t nir) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%u,%u,%u,%u,%u,%u,%u,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            lux, f1, f2, f3, f4, f5, f6, f7, f8, clear, nir);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open " I2C_BUS);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    if (init_as7341(i2c_fd) < 0) {
        fprintf(stderr, "AS7341 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen " LOG_FILE);
        close(i2c_fd);
        return 1;
    }

    while (running) {
        uint16_t f1, f2, f3, f4, f5, f6, f7, f8, clear, nir;
        int err = 0;

        if (read_channel(i2c_fd, REG_F1, &f1) < 0) err = 1;
        if (read_channel(i2c_fd, REG_F2, &f2) < 0) err = 1;
        if (read_channel(i2c_fd, REG_F3, &f3) < 0) err = 1;
        if (read_channel(i2c_fd, REG_F4, &f4) < 0) err = 1;
        if (read_channel(i2c_fd, REG_F5, &f5) < 0) err = 1;
        if (read_channel(i2c_fd, REG_F6, &f6) < 0) err = 1;
        if (read_channel(i2c_fd, REG_F7, &f7) < 0) err = 1;
        if (read_channel(i2c_fd, REG_F8, &f8) < 0) err = 1;
        if (read_channel(i2c_fd, REG_CLEAR, &clear) < 0) err = 1;
        if (read_channel(i2c_fd, REG_NIR, &nir) < 0) err = 1;

        if (err) {
            fprintf(stderr, "Error reading sensor data, skipping log\n");
        } else {
            float lux = calculate_lux(f1, f2, f3, f4, f5, f6, f7, f8, clear, nir);
            log_data(log_fp, lux, f1, f2, f3, f4, f5, f6, f7, f8, clear, nir);
        }

        sleep(5);
    }

    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

