#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <getopt.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define DEFAULT_I2C_ADDRESS 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define I2C_BUS "/dev/i2c-1"
#define NUM_AXES 3
#define NUM_BYTES (NUM_AXES * 2)
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SCALE_FACTOR 0.000244f

static int i2c_fd = -1;
static FILE *data_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void log_error(const char *message) {
    FILE *fp = fopen("seismic_error.log", "a");
    if (!fp) {
        perror("Error opening error log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] Error: %s (errno: %d - %s)\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message, errno, strerror(errno));
    fclose(fp);
}

static int i2c_write_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        log_error("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != (ssize_t)len) {
        log_error("I2C read failed");
        return -1;
    }
    return 0;
}

static int read_sensor_data(int fd, float *x, float *y, float *z) {
    uint8_t buf[NUM_BYTES];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2c_write_byte(fd, 0x28) != 0) {
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (i2c_read_bytes(fd, buf, NUM_BYTES) != 0) {
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
        int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
        int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

        *x = (float)raw_x * SCALE_FACTOR;
        *y = (float)raw_y * SCALE_FACTOR;
        *z = (float)raw_z * SCALE_FACTOR;

        return 0;
    }

    log_error("Failed to read sensor data after multiple retries");
    return -1;
}

static void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.6f,%.6f,%.6f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp);
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    int interval = DEFAULT_INTERVAL;
    char *filename = DEFAULT_FILENAME;

    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                break;
            case 'i':
                interval = atoi(optarg);
                break;
            case 'f':
                filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i interval] [-f filename]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    data_file = fopen(filename, "a");
    if (!data_file) {
        perror("Failed to open data file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fseek(data_file, 0, SEEK_END);
    if (ftell(data_file) == 0) {
        fprintf(data_file, "timestamp,x_g,y_g,z_g\n");
        fflush(data_file);
    }

    float x, y, z;
    while (!terminate) {
        if (read_sensor_data(i2c_fd, &x, &y, &z) == 0) {
            log_data(data_file, x, y, z);
        } else {
            log_error("Failed to read sensor data");
        }
        sleep(interval);
    }

    if (data_file) {
        fflush(data_file);
        fclose(data_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return EXIT_SUCCESS;
}

