#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int sockfd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, unsigned char cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_cmd(fd, 0x01) < 0) return -1;
    usleep(10000);
    if (i2c_write_cmd(fd, 0x10) < 0) return -1;
    usleep(180000);
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out) {
    unsigned char buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(float lux) {
    struct sockaddr_in addr;
    char buffer[32];
    int ttl = 1;

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    snprintf(buffer, sizeof(buffer), "%.2f", lux);

    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("setsockopt");
        return -1;
    }

    if (sendto(sockfd, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) == 0) {
            if (send_multicast(lux) < 0) {
                fprintf(stderr, "Failed to send multicast.\n");
            }
        } else {
            fprintf(stderr, "Failed to read lux value.\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (i2c_fd >= 0) close(i2c_fd);
    if (sockfd >= 0) close(sockfd);
    return 0;
}

