#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define CSV_FILE "radar_data.csv"
#define MAX_OBJECTS 100
#define READ_TIMEOUT_MS 1000
#define MAX_FRAME_SIZE 8192

/* AWR1642 TLV magic word (little-endian) */
static const uint8_t MAGIC_WORD[4] = {0x02, 0x04, 0x03, 0x06};

/* TLV types */
#define TLV_TYPE_DETECTED_POINTS 1
#define TLV_TYPE_RANGE_PROFILE  2

/* TLV header */
typedef struct {
    uint16_t type;
    uint32_t length;
} tlv_header_t;

/* Detected point (16-bit range, 16-bit velocity, 8-bit peak, 8-bit x, 8-bit y) */
typedef struct {
    uint16_t range;
    uint16_t velocity;
    uint8_t  peak;
    uint8_t  x;
    uint8_t  y;
} detected_point_t;

static int uart_handle = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (uart_handle >= 0) {
        serClose(uart_handle);
        uart_handle = -1;
    }
    if (csv_file != NULL) {
        fflush(csv_file);
        fclose(csv_file);
        csv_file = NULL;
    }
    gpioTerminate();
}

/* Read exactly n bytes from UART with timeout */
static int read_exact(int handle, uint8_t *buf, int n, int timeout_ms) {
    int total = 0;
    int elapsed = 0;
    while (total < n && !terminate) {
        int r = serRead(handle, (char *)(buf + total), n - total);
        if (r > 0) {
            total += r;
        } else if (r < 0) {
            fprintf(stderr, "UART read error\n");
            return -1;
        } else {
            gpioDelay(1000); /* 1 ms */
            elapsed += 1000;
            if (elapsed >= timeout_ms * 1000) {
                fprintf(stderr, "UART read timeout\n");
                return -1;
            }
        }
    }
    return (total == n) ? 0 : -1;
}

/* Synchronize on magic word */
static int sync_magic(int handle, uint8_t *buf, int *pos) {
    int i;
    for (i = 0; i < 4 && !terminate; i++) {
        if (read_exact(handle, buf + *pos, 1, READ_TIMEOUT_MS) != 0) return -1;
        (*pos)++;
    }
    if (terminate) return -1;
    if (memcmp(buf + *pos - 4, MAGIC_WORD, 4) != 0) {
        fprintf(stderr, "Magic word mismatch\n");
        return -1;
    }
    return 0;
}

/* Read a TLV header */
static int read_tlv_header(int handle, tlv_header_t *hdr, int timeout_ms) {
    uint8_t buf[8];
    if (read_exact(handle, buf, 8, timeout_ms) != 0) return -1;
    hdr->type = (uint16_t)(buf[0] | (buf[1] << 8));
    hdr->length = (uint32_t)(buf[2] | (buf[3] << 8) | (buf[4] << 16) | (buf[5] << 24));
    return 0;
}

/* Read a TLV payload */
static int read_tlv_payload(int handle, uint8_t *buf, uint32_t len, int timeout_ms) {
    int total = 0;
    int elapsed = 0;
    while (total < (int)len && !terminate) {
        int r = serRead(handle, (char *)(buf + total), len - total);
        if (r > 0) {
            total += r;
        } else if (r < 0) {
            fprintf(stderr, "UART read error\n");
            return -1;
        } else {
            gpioDelay(1000);
            elapsed += 1000;
            if (elapsed >= timeout_ms * 1000) {
                fprintf(stderr, "TLV payload read timeout\n");
                return -1;
            }
        }
    }
    return (total == (int)len) ? 0 : -1;
}

/* Parse detected points TLV */
static int parse_detected_points(const uint8_t *data, uint32_t len,
                                 int num_objects, detected_point_t *objs) {
    if (len < 4) return -1;
    uint32_t num_obj = (uint32_t)(data[0] | (data[1] << 8) | (data[2] << 16) | (data[3] << 24));
    if (num_obj > (uint32_t)num_objects) num_obj = (uint32_t)num_objects;
    if (len < 4 + (num_obj * sizeof(detected_point_t))) return -1;
    for (uint32_t i = 0; i < num_obj; i++) {
        memcpy(&objs[i], data + 4 + (i * sizeof(detected_point_t)), sizeof(detected_point_t));
    }
    return (int)num_obj;
}

int main(void) {
    uint8_t frame_buf[MAX_FRAME_SIZE];
    int frame_pos = 0;
    uint8_t sync_buf[4];
    int sync_pos = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_handle < 0) {
        fprintf(stderr, "Failed to open UART %s\n", UART_DEVICE);
        gpioTerminate();
        return 1;
    }

    csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file %s\n", CSV_FILE);
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    fflush(csv_file);

    fprintf(stderr, "Radar data acquisition started on %s\n", UART_DEVICE);

    while (!terminate) {
        if (sync_pos == 0) {
            if (sync_magic(uart_handle, sync_buf, &sync_pos) != 0) {
                if (!terminate) sync_pos = 0;
                continue;
            }
            sync_pos = 0;
        }

        tlv_header_t hdr;
        if (read_tlv_header(uart_handle, &hdr, READ_TIMEOUT_MS) != 0) {
            if (!terminate) sync_pos = 0;
            continue;
        }

        if (hdr.type == TLV_TYPE_DETECTED_POINTS) {
            if (hdr.length > MAX_FRAME_SIZE - frame_pos) {
                fprintf(stderr, "TLV length too large\n");
                if (!terminate) sync_pos = 0;
                continue;
            }
            if (read_tlv_payload(uart_handle, frame_buf + frame_pos, hdr.length, READ_TIMEOUT_MS) != 0) {
                if (!terminate) sync_pos = 0;
                continue;
            }
            frame_pos += hdr.length;

            detected_point_t objects[MAX_OBJECTS];
            int num_objs = parse_detected_points(frame_buf, hdr.length, MAX_OBJECTS, objects);
            if (num_objs > 0) {
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                char ts[32];
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
                for (int i = 0; i < num_objs; i++) {
                    float range_m = (float)objects[i].range / 1000.0f;
                    float vel_mps = (float)objects[i].velocity / 1000.0f;
                    fprintf(csv_file, "%s,%d,%.3f,%.3f\n", ts, i, range_m, vel_mps);
                }
                fflush(csv_file);
            }
            frame_pos = 0;
        } else {
            /* Unknown TLV type: skip payload */
            uint32_t skipped = 0;
            while (skipped < hdr.length && !terminate) {
                int r = serRead(uart_handle, NULL, 1);
                if (r > 0) skipped++;
                else if (r < 0) {
                    fprintf(stderr, "UART read error during skip\n");
                    break;
                } else {
                    gpioDelay(1000);
                }
            }
        }
    }

    fprintf(stderr, "Radar data acquisition stopped\n");
    cleanup();
    return 0;
}

