#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE   B115200
#define LINE_BUF_SIZE 256
#define READ_TIMEOUT_SEC 2

static volatile sig_atomic_t g_running = 1;
static int g_uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag = 0;
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_oflag = 0;
    tty.c_oflag &= ~OPOST;

    tty.c_lflag = 0;
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);

    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_uart_line(int fd, char *line, size_t line_size) {
    static char read_buf[LINE_BUF_SIZE];
    static size_t read_buf_len = 0;

    fd_set rfds;
    struct timeval tv;

    FD_ZERO(&rfds);
    FD_SET(fd, &rfds);

    tv.tv_sec  = READ_TIMEOUT_SEC;
    tv.tv_usec = 0;

    int sel = select(fd + 1, &rfds, NULL, NULL, &tv);
    if (sel < 0) {
        if (errno == EINTR) return 0;
        fprintf(stderr, "select error: %s\n", strerror(errno));
        return -1;
    }
    if (sel == 0) {
        return 0;
    }

    ssize_t n = read(fd, read_buf + read_buf_len, sizeof(read_buf) - read_buf_len);
    if (n < 0) {
        if (errno == EINTR) return 0;
        fprintf(stderr, "read error: %s\n", strerror(errno));
        return -1;
    }
    if (n == 0) {
        fprintf(stderr, "UART closed by peer\n");
        return -1;
    }

    read_buf_len += (size_t)n;

    char *nl = NULL;
    for (char *p = read_buf; p < read_buf + read_buf_len; p++) {
        if (*p == '\n') {
            nl = p;
            break;
        }
    }

    if (nl != NULL) {
        size_t copy_len = nl - read_buf;
        if (copy_len >= line_size) copy_len = line_size - 1;
        memcpy(line, read_buf, copy_len);
        line[copy_len] = '\0';

        size_t consumed = copy_len + 1;
        memmove(read_buf, read_buf + consumed, read_buf_len - consumed);
        read_buf_len -= consumed;
        return 1;
    }

    if (read_buf_len >= line_size) {
        memmove(read_buf, read_buf + line_size - 1, read_buf_len - (line_size - 1));
        read_buf_len = line_size - 1;
        read_buf[read_buf_len] = '\0';
    }
    return 0;
}

static int parse_range(const char *line, long *timestamp, float *range) {
    char *endptr = NULL;
    errno = 0;
    long ts = strtol(line, &endptr, 10);
    if (errno != 0 || endptr == line || *endptr != ',') {
        fprintf(stderr, "Invalid timestamp format: %s\n", line);
        return -1;
    }

    errno = 0;
    float r = strtof(endptr + 1, &endptr);
    if (errno != 0 || *endptr != '\0') {
        fprintf(stderr, "Invalid range format: %s\n", line);
        return -1;
    }

    *timestamp = ts;
    *range = r;
    return 0;
}

static void log_range(long timestamp, float range) {
    time_t rawtime = timestamp;
    struct tm *timeinfo = localtime(&rawtime);
    char ts_str[32];
    strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("Timestamp: %s, Range: %.2f meters\n", ts_str, range);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (g_uart_fd < 0) {
        return 1;
    }

    char line[LINE_BUF_SIZE];
    long timestamp;
    float range;

    while (g_running) {
        int rc = read_uart_line(g_uart_fd, line, sizeof(line));
        if (rc < 0) {
            break;
        }
        if (rc == 1) {
            if (parse_range(line, &timestamp, &range) == 0) {
                log_range(timestamp, range);
            }
        }
    }

    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }
    printf("\nUART closed. Exiting.\n");
    return 0;
}

