#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define SERIAL_PORT "/dev/ttyAMA0"
#define BAUD_RATE 115200
#define POLL_DELAY_US 100000  /* 100 ms -> 10 Hz */

static volatile sig_atomic_t running = 1;
static int serial_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (serial_fd >= 0) {
        close(serial_fd);
        serial_fd = -1;
    }
    gpioTerminate();
}

static int read_sensor(int pin) {
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %d: %d\n", pin, v);
        return -1;
    }
    return v;
}

static void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Left: %d, Middle: %d, Right: %d\n",
           timestamp, left, middle, right);
    fflush(stdout);
}

static void send_emergency_stop(void) {
    const char *msg = "EMERGENCY STOP!\n";
    size_t len = strlen(msg);
    ssize_t written = write(serial_fd, msg, len);
    if (written < 0) {
        perror("write to serial port failed");
    } else if ((size_t)written != len) {
        fprintf(stderr, "partial write to serial port: %zd of %zu bytes\n",
                written, len);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);

    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    serial_fd = serOpen(SERIAL_PORT, BAUD_RATE, 0);
    if (serial_fd < 0) {
        fprintf(stderr, "Failed to open serial port %s: %d\n",
                SERIAL_PORT, serial_fd);
        gpioTerminate();
        return 1;
    }

    while (running) {
        int left = read_sensor(LEFT_SENSOR_PIN);
        int middle = read_sensor(MIDDLE_SENSOR_PIN);
        int right = read_sensor(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Sensor read error, continuing...\n");
        } else {
            log_sensor_data(left, middle, right);
            if (left == 0 && middle == 0 && right == 0) {
                send_emergency_stop();
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return 0;
}

